CREATE TABLE IF NOT EXISTS "public"."documents_soignants" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "type_document" "public"."type_document" NOT NULL,
    "libelle" "text",
    "s3_bucket" "text" DEFAULT 'jolene-documents'::"text" NOT NULL,
    "s3_cle" "text" NOT NULL,
    "s3_version_id" "text",
    "nom_fichier" "text" NOT NULL,
    "type_mime" "text",
    "taille_octets" bigint,
    "valide_depuis" "date",
    "valide_jusqua" "date",
    "statut_verification" "public"."statut_verification" DEFAULT 'EN_ATTENTE'::"public"."statut_verification",
    "verifie_par" "uuid",
    "verifie_le" timestamp with time zone,
    "motif_rejet" "text",
    "est_critique" boolean DEFAULT false,
    "rappel_j30_envoye" boolean DEFAULT false,
    "rappel_j7_envoye" boolean DEFAULT false,
    "rappel_expire_envoye" boolean DEFAULT false,
    "televerse_le" timestamp with time zone DEFAULT "now"(),
    "modifie_le" timestamp with time zone DEFAULT "now"(),
    "supprime_le" timestamp with time zone,
    "resultat_ia" "jsonb",
    "nom_extrait_ia" "text",
    "prenom_extrait_ia" "text",
    "coherence_nom" boolean,
    "score_confiance_ia" numeric,
    "verification_attempt_id" "uuid",
    "revoque_le" timestamp with time zone,
    "revoque_raison" "text",
    "remplace_par_document_id" "uuid",
    CONSTRAINT "documents_soignants_revoque_raison_check" CHECK (((("revoque_le" IS NULL) AND ("revoque_raison" IS NULL) AND ("remplace_par_document_id" IS NULL)) OR (("revoque_le" IS NOT NULL) AND ("revoque_raison" = ANY (ARRAY['REMPLACEMENT'::"text", 'RETRAIT'::"text"])))))
);

ALTER TABLE ONLY "public"."documents_soignants" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."documents_soignants" OWNER TO "postgres";


COMMENT ON COLUMN "public"."documents_soignants"."verification_attempt_id" IS 'Jeton interne éphémère de la tentative de vérification automatique active.';



COMMENT ON COLUMN "public"."documents_soignants"."revoque_le" IS 'Date de désactivation de cette version de preuve. La ligne et son verdict restent conservés pour audit.';



COMMENT ON COLUMN "public"."documents_soignants"."remplace_par_document_id" IS 'Nouvelle version qui a atomiquement remplacé cette preuve.';



CREATE TABLE IF NOT EXISTS "public"."heures_externes_soignants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "etablissement_nom" "text" NOT NULL,
    "etablissement_type" "text",
    "date_debut" "date" NOT NULL,
    "date_fin" "date" NOT NULL,
    "heures_declarees" integer NOT NULL,
    "attestation_url" "text",
    "attestation_nom_fichier" "text",
    "statut_validation" "text" DEFAULT 'EN_ATTENTE'::"text",
    "commentaire_validation" "text",
    "valide_par" "uuid",
    "valide_le" timestamp with time zone,
    "cree_le" timestamp with time zone DEFAULT "now"(),
    "mis_a_jour_le" timestamp with time zone DEFAULT "now"(),
    "heures_extraites_ia" integer,
    "resultat_ia" "jsonb",
    "coherence_ia" boolean,
    "verifie_ia_le" timestamp with time zone,
    "version_source" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "empreinte_preuve_sha256" "text",
    "source_validation_serveur" "text",
    "empreinte_snapshot_source" "text",
    CONSTRAINT "heures_externes_soignants_check" CHECK (("date_fin" >= "date_debut")),
    CONSTRAINT "heures_externes_soignants_heures_declarees_check" CHECK ((("heures_declarees" > 0) AND ("heures_declarees" <= 10000))),
    CONSTRAINT "heures_externes_soignants_statut_validation_check" CHECK (("statut_validation" = ANY (ARRAY['EN_ATTENTE'::"text", 'VALIDE'::"text", 'REJETE'::"text"])))
);

ALTER TABLE ONLY "public"."heures_externes_soignants" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."heures_externes_soignants" OWNER TO "postgres";


COMMENT ON COLUMN "public"."heures_externes_soignants"."heures_extraites_ia" IS 'Nombre d''heures lu par l''IA sur l''attestation (NULL si non extrait).';



COMMENT ON COLUMN "public"."heures_externes_soignants"."resultat_ia" IS 'Verdict JSON complet renvoyé par Anthropic Vision (traçabilité / diagnostic).';



COMMENT ON COLUMN "public"."heures_externes_soignants"."coherence_ia" IS 'TRUE si heures_extraites_ia cohérent avec heures_declarees (tolérance), FALSE sinon, NULL si non évalué.';



COMMENT ON COLUMN "public"."heures_externes_soignants"."verifie_ia_le" IS 'Horodatage de la vérification IA automatique.';



COMMENT ON COLUMN "public"."heures_externes_soignants"."version_source" IS 'Jeton serveur de la source immuable utilisé par les CAS de vérification et de décision.';



COMMENT ON COLUMN "public"."heures_externes_soignants"."empreinte_preuve_sha256" IS 'SHA-256 des octets téléchargés depuis le bucket privé, calculé par l Edge Function.';



COMMENT ON COLUMN "public"."heures_externes_soignants"."source_validation_serveur" IS 'Provenance serveur du verdict. ADMIN_AAL2 et ADMIN_LEGACY_AUDITE alimentent les comptes reels ; TEST_FIXTURE_SERVICE_ROLE est limite aux profils Playwright ephemeres par le compteur et sa RPC service_role.';



COMMENT ON COLUMN "public"."heures_externes_soignants"."empreinte_snapshot_source" IS 'SHA-256 du snapshot complet et immuable sur lequel le verdict serveur a été rendu.';



CREATE OR REPLACE FUNCTION "public"."_sha256_hex"("p_input" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT encode(extensions.digest(p_input, 'sha256'), 'hex');
$$;


ALTER FUNCTION "public"."_sha256_hex"("p_input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_alerte_mission_liberee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF OLD.statut = 'ASSIGNEE' AND NEW.statut = 'OUVERTE'
       AND NEW.debut_le < NOW() + INTERVAL '24 hours' THEN
        NEW.est_urgente := TRUE;
        NEW.niveau_urgence := 3;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_alerte_mission_liberee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_alerte_pause_obligatoire"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_total_pauses NUMERIC;
BEGIN
    IF NEW.pointage_depart_le IS NOT NULL AND NEW.duree_brute_min IS NOT NULL THEN
        SELECT COALESCE(SUM(
            CASE WHEN fin_le IS NOT NULL THEN EXTRACT(EPOCH FROM (fin_le - debut_le)) / 60 ELSE 0 END
        ), 0) INTO v_total_pauses FROM pauses_presence WHERE presence_id = NEW.id;

        IF NEW.duree_brute_min > 360 AND v_total_pauses < 20 THEN
            NEW.alertes_fraude := COALESCE(NEW.alertes_fraude, '[]'::JSONB) || jsonb_build_array(jsonb_build_object(
                'type_alerte', 'PAUSE_MANQUANTE',
                'duree_shift_min', NEW.duree_brute_min,
                'duree_pause_min', v_total_pauses,
                'message', 'Shift > 6h sans 20 min de pause. Art. L3121-16.'
            ));
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_alerte_pause_obligatoire"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_annuler_contrat_si_mission_annulee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.statut IN ('ANNULEE_PAR_ETABLISSEMENT', 'ANNULEE_PAR_SOIGNANT') THEN
        UPDATE contrats_mission SET statut = 'ANNULE', modifie_le = NOW()
        WHERE mission_id = NEW.id AND statut NOT IN ('SIGNE_COMPLET', 'ANNULE');
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_annuler_contrat_si_mission_annulee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_anti_double_assignation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.soignant_assigne_id IS NOT NULL AND NEW.statut = 'ASSIGNEE' THEN
        IF OLD.soignant_assigne_id IS NOT NULL AND OLD.statut = 'ASSIGNEE' THEN
            -- Déjà assigné, refuser le double
            IF OLD.soignant_assigne_id != NEW.soignant_assigne_id THEN
                RAISE EXCEPTION 'Cette mission est déjà assignée à un autre soignant.';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_anti_double_assignation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_antifraude_presence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_teleport JSONB;
    v_etab RECORD;
    v_dist NUMERIC;
BEGIN
    IF NEW.pointage_arrivee_le IS NOT NULL AND NEW.arrivee_lat IS NOT NULL THEN
        -- Détection téléportation
        v_teleport := fn_detecter_teleportation(
            NEW.soignant_id, NEW.arrivee_lat, NEW.arrivee_lng, NEW.pointage_arrivee_le
        );
        IF (v_teleport->>'suspect')::BOOLEAN THEN
            NEW.alerte_teleportation := TRUE;
            NEW.alertes_fraude := NEW.alertes_fraude || jsonb_build_array(v_teleport);

            INSERT INTO file_revue_manuelle (type_entite, id_entite, service_en_echec, motif_echec, donnees_originales, priorite)
            VALUES ('ALERTE_FRAUDE', NEW.id, 'GEOLOCALISATION', 'Téléportation détectée', v_teleport, 5);

            PERFORM fn_ecrire_audit(
                NEW.soignant_id, 'SYSTEME', 'PRESENCE_ALERTE_FRAUDE',
                'presence', NEW.id, NULL, v_teleport
            );
        END IF;

        -- Vérification périmètre GPS — tolérance RÉGLÉE par l'établissement
        SELECT e.adresse_lat, e.adresse_lng, COALESCE(e.tolerance_pointage_m, 500) AS tolerance
        INTO v_etab
        FROM missions m JOIN etablissements e ON e.id = m.etablissement_id
        WHERE m.id = NEW.mission_id;

        IF v_etab.adresse_lat IS NOT NULL THEN
            v_dist := 6371000 * acos(LEAST(1.0,
                cos(radians(v_etab.adresse_lat)) * cos(radians(NEW.arrivee_lat))
                * cos(radians(NEW.arrivee_lng) - radians(v_etab.adresse_lng))
                + sin(radians(v_etab.adresse_lat)) * sin(radians(NEW.arrivee_lat))
            ));
            NEW.distance_etablissement_m := ROUND(v_dist, 2);
            NEW.perimetre_gps_valide := (v_dist <= v_etab.tolerance);

            IF NOT NEW.perimetre_gps_valide THEN
                NEW.alertes_fraude := NEW.alertes_fraude || jsonb_build_array(jsonb_build_object(
                    'type_alerte', 'HORS_PERIMETRE',
                    'distance_m', ROUND(v_dist, 2),
                    'distance_max_m', v_etab.tolerance
                ));
            END IF;
        END IF;

        -- Lot 13 (recours) : une anomalie n'est JAMAIS un rejet silencieux — le
        -- soignant est prévenu et peut expliquer/contester depuis ses présences.
        IF NEW.alerte_teleportation OR (NEW.perimetre_gps_valide IS FALSE) THEN
            BEGIN
                PERFORM fn_creer_notification(
                    p_destinataire_id   := NEW.soignant_id,
                    p_type_destinataire := 'SOIGNANT',
                    p_type              := 'SYSTEM',
                    p_titre             := 'Anomalie GPS sur votre pointage',
                    p_corps             := 'Un écart GPS a été détecté sur votre pointage. Votre présence reste enregistrée — vous pouvez apporter une explication depuis vos présences.',
                    p_lien              := '/soignant/presences',
                    p_type_ressource    := 'presence',
                    p_id_ressource      := NEW.id
                );
            EXCEPTION WHEN OTHERS THEN
                NULL; -- la notif ne doit jamais bloquer le pointage.
            END;
        END IF;
    END IF;

    -- Retard de pointage (> 15 min)
    IF NEW.pointage_arrivee_le IS NOT NULL THEN
        DECLARE v_debut_mission TIMESTAMPTZ;
        BEGIN
            SELECT m.debut_le INTO v_debut_mission FROM missions m WHERE m.id = NEW.mission_id;
            IF NEW.pointage_arrivee_le > v_debut_mission + INTERVAL '15 minutes' THEN
                UPDATE soignants SET
                    total_retards_pointage = total_retards_pointage + 1, modifie_le = NOW()
                WHERE id = NEW.soignant_id;
            END IF;
        END;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_antifraude_presence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_appliquer_plafond_rist"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plafond numeric;
  v_est_secteur_public boolean;
  v_regime_effectif text;
BEGIN
  -- Avant assignation, le taux publié est le taux réellement utilisé pour
  -- l'estimation. Le plafond ne peut être figé qu'avec un contrat salarié.
  IF NEW.soignant_assigne_id IS NULL THEN
    NEW.taux_rist_plafonne := NEW.taux_horaire_base;
    NEW.rist_plafond_applique := false;
    RETURN NEW;
  END IF;

  SELECT e.est_secteur_public
    INTO v_est_secteur_public
    FROM public.etablissements e
   WHERE e.id = NEW.etablissement_id;

  -- Après assignation, le choix réellement figé prime toujours sur le filtre
  -- de recherche. Une mission publiée « TOUS » puis attribuée en LIBERAL ne
  -- doit notamment jamais recevoir un plafond salarié.
  v_regime_effectif := COALESCE(
    NEW.type_contrat_applique::text,
    NULLIF(upper(btrim(NEW.choix_contrat_soignant)), ''),
    CASE WHEN NEW.type_contrat_recherche = 'SALARIE' THEN 'SALARIE' ELSE NULL END
  );

  IF NOT COALESCE(v_est_secteur_public, false)
     OR v_regime_effectif IS DISTINCT FROM 'SALARIE' THEN
    NEW.taux_rist_plafonne := NEW.taux_horaire_base;
    NEW.rist_plafond_applique := false;
    RETURN NEW;
  END IF;

  SELECT rp.plafond_calcule
    INTO v_plafond
    FROM public.rist_plafonds rp
   WHERE rp.profession = NEW.profession_requise
     AND rp.type_contrat IN ('CDD', 'SALARIE', 'VACATION')
     AND rp.en_vigueur_depuis <= CURRENT_DATE
     AND (rp.en_vigueur_jusqua IS NULL OR rp.en_vigueur_jusqua >= CURRENT_DATE)
   ORDER BY rp.en_vigueur_depuis DESC
   LIMIT 1;

  IF v_plafond IS NOT NULL AND NEW.taux_horaire_base > v_plafond THEN
    NEW.taux_rist_plafonne := v_plafond;
    NEW.rist_plafond_applique := true;
  ELSE
    NEW.taux_rist_plafonne := NEW.taux_horaire_base;
    NEW.rist_plafond_applique := false;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_appliquer_plafond_rist"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dec_appliquer_plafond_rist"() IS 'Détermine le taux Rist depuis la profession requise par la mission, uniquement après assignation salariée dans le secteur public.';



