CREATE OR REPLACE FUNCTION "public"."dec_calculer_commission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_taux NUMERIC;
BEGIN
    IF NEW.statut = 'TERMINEE' AND NEW.net_a_payer IS NOT NULL THEN
        v_taux := COALESCE(
            NEW.taux_commission_fige,
            (SELECT e.taux_commission_negocie FROM etablissements e WHERE e.id = NEW.etablissement_id),
            public.fn_param_num('commission_defaut_pct', 15)
        );

        NEW.taux_commission := v_taux;
        NEW.montant_commission_ht := ROUND(NEW.net_a_payer * (v_taux / 100.0), 2);
        NEW.montant_commission_tva := ROUND(NEW.montant_commission_ht * 0.20, 2);
        NEW.montant_commission_ttc := NEW.montant_commission_ht + NEW.montant_commission_tva;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_calculer_commission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_calculer_duree_presence"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_debut_mission timestamptz;
  v_fin_mission timestamptz;
  v_total_pauses numeric := 0;
  v_effectif_minutes numeric;
  v_effectif_premier timestamptz;
  v_effectif_dernier timestamptz;
  v_effectif_count integer := 0;
BEGIN
  IF NEW.pointage_depart_le IS NOT NULL AND NEW.pointage_arrivee_le IS NOT NULL THEN
    SELECT
      count(*),
      COALESCE(sum(EXTRACT(EPOCH FROM (mc.fin - mc.debut)) / 60.0)
        FILTER (WHERE mc.fin IS NOT NULL AND NOT mc.est_pause), 0),
      min(mc.debut) FILTER (WHERE NOT mc.est_pause),
      max(mc.fin) FILTER (WHERE mc.fin IS NOT NULL AND NOT mc.est_pause)
    INTO v_effectif_count, v_effectif_minutes, v_effectif_premier, v_effectif_dernier
    FROM public.mission_creneaux mc
    WHERE mc.mission_id = NEW.mission_id
      AND mc.type_creneau = 'EFFECTIF';

    IF v_effectif_count > 0 THEN
      NEW.duree_brute_min := round(
        EXTRACT(EPOCH FROM (COALESCE(v_effectif_dernier, NEW.pointage_depart_le)
          - COALESCE(v_effectif_premier, NEW.pointage_arrivee_le))) / 60.0,
        2
      );
      NEW.duree_nette_min := round(GREATEST(v_effectif_minutes, 0), 2);
      NEW.duree_pause_min := round(
        GREATEST(NEW.duree_brute_min - NEW.duree_nette_min, 0),
        2
      );
      NEW.heures_reelles := round(NEW.duree_nette_min / 60.0, 2);
    ELSE
      NEW.duree_brute_min := round(
        EXTRACT(EPOCH FROM (NEW.pointage_depart_le - NEW.pointage_arrivee_le)) / 60.0,
        2
      );
      SELECT COALESCE(sum(
        CASE WHEN pp.fin_le IS NOT NULL
          THEN EXTRACT(EPOCH FROM (pp.fin_le - pp.debut_le)) / 60.0
          ELSE 0 END
      ), 0)
      INTO v_total_pauses
      FROM public.pauses_presence pp
      WHERE pp.presence_id = NEW.id;
      NEW.duree_pause_min := round(v_total_pauses, 2);
      NEW.duree_nette_min := GREATEST(0, NEW.duree_brute_min - NEW.duree_pause_min);
      NEW.heures_reelles := round(NEW.duree_nette_min / 60.0, 2);
    END IF;

    SELECT m.debut_le, m.fin_le
    INTO v_debut_mission, v_fin_mission
    FROM public.missions m
    WHERE m.id = NEW.mission_id;

    NEW.retard_min := CASE
      WHEN v_debut_mission IS NOT NULL AND NEW.pointage_arrivee_le > v_debut_mission
        THEN round(EXTRACT(EPOCH FROM (NEW.pointage_arrivee_le - v_debut_mission)) / 60.0, 2)
      ELSE 0
    END;
    NEW.depart_anticipe_min := CASE
      WHEN v_fin_mission IS NOT NULL AND NEW.pointage_depart_le < v_fin_mission
        THEN round(EXTRACT(EPOCH FROM (v_fin_mission - NEW.pointage_depart_le)) / 60.0, 2)
      ELSE 0
    END;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_calculer_duree_presence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_calculer_finance_mission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_taux_effectif numeric;
  v_calcul jsonb;
  v_c record;
  v_sum_prev numeric := 0;
  v_sum_eff numeric := 0;
  v_use_effectif boolean;
  v_est_liberal boolean;
  v_h_nuit numeric := 0;
  v_h_dim numeric := 0;
  v_h_fer numeric := 0;
  v_m_nuit numeric := 0;
  v_m_dim numeric := 0;
  v_m_fer numeric := 0;
  v_brut numeric := 0;
  v_ifm numeric := 0;
  v_icp numeric := 0;
  v_taux_ifm numeric := 0;
  v_taux_icp numeric := 0;
BEGIN
  v_est_liberal := COALESCE(
    NEW.type_contrat_applique::text,
    CASE WHEN NEW.type_contrat_recherche = 'LIBERAL' THEN 'LIBERAL' ELSE 'SALARIE' END
  ) = 'LIBERAL';
  v_taux_effectif := COALESCE(NEW.taux_rist_plafonne, NEW.taux_horaire_base);

  SELECT COALESCE(sum(CASE WHEN NOT est_pause THEN extract(epoch FROM (fin - debut)) / 3600.0 ELSE 0 END), 0)
    INTO v_sum_prev
    FROM public.mission_creneaux
   WHERE mission_id = NEW.id AND type_creneau = 'PREVISIONNEL' AND fin IS NOT NULL;
  SELECT COALESCE(sum(CASE WHEN NOT est_pause THEN extract(epoch FROM (fin - debut)) / 3600.0 ELSE 0 END), 0)
    INTO v_sum_eff
    FROM public.mission_creneaux
   WHERE mission_id = NEW.id AND type_creneau = 'EFFECTIF' AND fin IS NOT NULL;
  v_use_effectif := v_sum_eff > v_sum_prev;

  IF v_sum_prev > 0 OR v_sum_eff > 0 THEN
    FOR v_c IN
      SELECT debut, fin
        FROM public.mission_creneaux
       WHERE mission_id = NEW.id
         AND NOT est_pause
         AND fin IS NOT NULL
         AND type_creneau = CASE WHEN v_use_effectif THEN 'EFFECTIF' ELSE 'PREVISIONNEL' END
       ORDER BY debut
    LOOP
      -- NULL évite toute déduction depuis le profil ; le régime est appliqué
      -- ci-dessous depuis NEW.type_contrat_applique.
      v_calcul := public.fn_calculer_remuneration_mission(
        v_c.debut, v_c.fin, v_taux_effectif, NEW.etablissement_id, NULL
      );
      v_h_nuit := v_h_nuit + (v_calcul->>'heures_nuit')::numeric;
      v_h_dim := v_h_dim + (v_calcul->>'heures_dimanche')::numeric;
      v_h_fer := v_h_fer + (v_calcul->>'heures_ferie')::numeric;
      v_m_nuit := v_m_nuit + (v_calcul->>'montant_majoration_nuit')::numeric;
      v_m_dim := v_m_dim + (v_calcul->>'montant_majoration_dimanche')::numeric;
      v_m_fer := v_m_fer + (v_calcul->>'montant_majoration_ferie')::numeric;
      v_brut := v_brut + (v_calcul->>'total_brut')::numeric;
    END LOOP;
  ELSE
    v_calcul := public.fn_calculer_remuneration_mission(
      NEW.debut_le, NEW.fin_le, v_taux_effectif, NEW.etablissement_id, NULL
    );
    v_h_nuit := (v_calcul->>'heures_nuit')::numeric;
    v_h_dim := (v_calcul->>'heures_dimanche')::numeric;
    v_h_fer := (v_calcul->>'heures_ferie')::numeric;
    v_m_nuit := (v_calcul->>'montant_majoration_nuit')::numeric;
    v_m_dim := (v_calcul->>'montant_majoration_dimanche')::numeric;
    v_m_fer := (v_calcul->>'montant_majoration_ferie')::numeric;
    v_brut := (v_calcul->>'total_brut')::numeric;
  END IF;

  IF NOT v_est_liberal THEN
    v_taux_ifm := 0.10;
    v_taux_icp := 0.10;
    v_ifm := round(v_brut * v_taux_ifm, 2);
    v_icp := round((v_brut + v_ifm) * v_taux_icp, 2);
  END IF;

  NEW.heures_nuit := round(v_h_nuit, 2);
  NEW.heures_dimanche := round(v_h_dim, 2);
  NEW.heures_ferie := round(v_h_fer, 2);
  NEW.montant_majoration_nuit := round(v_m_nuit, 2);
  NEW.montant_majoration_dimanche := round(v_m_dim, 2);
  NEW.montant_majoration_ferie := round(v_m_fer, 2);
  NEW.total_brut := round(v_brut, 2);
  NEW.taux_ifm := v_taux_ifm;
  NEW.montant_ifm := v_ifm;
  NEW.taux_icp := v_taux_icp;
  NEW.montant_icp := v_icp;
  NEW.net_a_payer := round(v_brut + v_ifm + v_icp, 2);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_calculer_finance_mission"() OWNER TO "postgres";


