CREATE OR REPLACE FUNCTION "public"."dec_creer_conversation_assignation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.statut <> 'ASSIGNEE'
     OR NEW.soignant_assigne_id IS NULL
     OR (
       OLD.statut = 'ASSIGNEE'
       AND OLD.soignant_assigne_id = NEW.soignant_assigne_id
     ) THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM public.fn_creer_conversation_si_absente(
      NEW.id,
      NEW.soignant_assigne_id,
      NEW.etablissement_id
    );
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.journaux_audit (
        acteur_id,
        type_acteur,
        action,
        type_ressource,
        id_ressource,
        details
      ) VALUES (
        '00000000-0000-0000-0000-000000000000'::uuid,
        'SYSTEME',
        'SYSTEM',
        'missions',
        NEW.id,
        pg_catalog.jsonb_build_object(
          'evenement', 'MESSAGERIE_TRIGGER_ASSIGNATION_ECHEC',
          'sql_state', SQLSTATE,
          'sql_errm', SQLERRM,
          'mission_id', NEW.id,
          'soignant_id', NEW.soignant_assigne_id,
          'etablissement_id', NEW.etablissement_id
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_creer_conversation_assignation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_creer_partage_rib_contrat"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_doc_rib_id UUID;
BEGIN
    -- Seulement quand le contrat passe en SIGNE_COMPLET
    IF NEW.statut != 'SIGNE_COMPLET' THEN RETURN NEW; END IF;
    IF OLD.statut = 'SIGNE_COMPLET' THEN RETURN NEW; END IF;
    
    SELECT * INTO v_mission FROM missions WHERE id = NEW.mission_id;
    IF v_mission IS NULL OR v_mission.type_paiement_soignant != 'BULLETIN_PAIE' THEN
        RETURN NEW;
    END IF;
    
    -- Trouver le RIB vérifié du soignant
    SELECT id INTO v_doc_rib_id FROM documents_soignants
    WHERE soignant_id = NEW.soignant_id AND type_document = 'RIB'
    AND statut_verification = 'VERIFIE' AND supprime_le IS NULL
    LIMIT 1;
    
    -- Créer le partage
    INSERT INTO partages_rib (soignant_id, etablissement_id, mission_id, contrat_id, actif, document_rib_id, partage_le)
    VALUES (NEW.soignant_id, NEW.etablissement_id, NEW.mission_id, NEW.id, TRUE, v_doc_rib_id, NOW())
    ON CONFLICT DO NOTHING;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_creer_partage_rib_contrat"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_definir_type_paiement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_choix text;
BEGIN
  IF NEW.soignant_assigne_id IS NOT NULL THEN
    v_choix := COALESCE(
      NEW.type_contrat_applique::text,
      NULLIF(upper(NEW.choix_contrat_soignant), ''),
      CASE WHEN NEW.type_contrat_recherche::text = 'LIBERAL' THEN 'LIBERAL' ELSE 'SALARIE' END
    );
    IF v_choix = 'LIBERAL' THEN
      NEW.type_paiement_soignant := 'NOTE_HONORAIRES';
      NEW.mode_paiement_soignant := 'STRIPE_CONNECT';
    ELSE
      NEW.type_paiement_soignant := 'BULLETIN_PAIE';
      NEW.mode_paiement_soignant := 'DIRECT';
    END IF;
    IF NEW.type_paiement_soignant = 'NOTE_HONORAIRES'
       AND NEW.statut = 'TERMINEE' AND NEW.numero_note_honoraires IS NULL THEN
      NEW.numero_note_honoraires := public.fn_generer_numero_note_honoraires();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_definir_type_paiement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_depart_apres_arrivee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NEW.pointage_depart_le IS NOT NULL AND NEW.pointage_arrivee_le IS NULL THEN
        RAISE EXCEPTION 'Impossible de pointer le départ sans avoir pointé l''arrivée.';
    END IF;
    IF NEW.pointage_depart_le IS NOT NULL AND NEW.pointage_depart_le < NEW.pointage_arrivee_le THEN
        RAISE EXCEPTION 'Le départ ne peut pas être avant l''arrivée.';
    END IF;
    RETURN NEW;
END;
$$;


