BEGIN
    SELECT type, est_secteur_public INTO v_etab
    FROM etablissements WHERE id = NEW.etablissement_id;

    IF v_etab.est_secteur_public = TRUE OR v_etab.type IN ('HOPITAL_PUBLIC', 'ESPIC') THEN
        NEW.est_secteur_public := TRUE;
