CREATE OR REPLACE FUNCTION "public"."dec_maj_compteurs_soignant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_old_soignant_id uuid;
  v_new_soignant_id uuid;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    v_old_soignant_id := OLD.soignant_assigne_id;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_new_soignant_id := NEW.soignant_assigne_id;
  END IF;

  IF v_old_soignant_id IS NOT NULL THEN
    PERFORM private.fn_resynchroniser_compteurs_soignant(v_old_soignant_id);
  END IF;
  IF v_new_soignant_id IS NOT NULL
     AND v_new_soignant_id IS DISTINCT FROM v_old_soignant_id THEN
    PERFORM private.fn_resynchroniser_compteurs_soignant(v_new_soignant_id);
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_maj_compteurs_soignant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_maj_note_moyenne"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_note_moy NUMERIC;
    v_nb_evals INT;
    v_missions_term INT;
    v_absences INT;
    v_anciennete_mois INT;
    v_score INT;
BEGIN
    SELECT ROUND(AVG(note)::NUMERIC, 2), COUNT(*)
    INTO v_note_moy, v_nb_evals
    FROM evaluations WHERE evalue_id = NEW.evalue_id AND visible = TRUE;

    SELECT 
        COUNT(*) FILTER (WHERE statut = 'TERMINEE'),
        COUNT(*) FILTER (WHERE statut = 'ABSENCE')
    INTO v_missions_term, v_absences
    FROM missions WHERE soignant_assigne_id = NEW.evalue_id;

    SELECT GREATEST(1, EXTRACT(MONTH FROM AGE(NOW(), cree_le))::INT)
    INTO v_anciennete_mois
    FROM soignants WHERE id = NEW.evalue_id;

    v_score := LEAST(100, GREATEST(0,
        ROUND(COALESCE(v_note_moy, 3) * 8)
        + CASE WHEN v_missions_term = 0 THEN 20
               ELSE ROUND(GREATEST(0, 1 - (v_absences::NUMERIC / GREATEST(v_missions_term, 1))) * 40)
          END
        + LEAST(20, v_anciennete_mois * 20 / 12)
    ));

    -- Poser le flag pour que le trigger de protection autorise le changement
    PERFORM set_config('jolene.system_update', 'true', true);

    UPDATE soignants SET
        note_moyenne = v_note_moy,
        nb_evaluations = v_nb_evals,
        score_fiabilite = v_score,
        modifie_le = NOW()
    WHERE id = NEW.evalue_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_maj_note_moyenne"() OWNER TO "postgres";


