CREATE OR REPLACE FUNCTION "public"."dec_verifier_docs_avant_debut"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_rcp_ok BOOLEAN;
BEGIN
    IF NEW.statut = 'EN_COURS' AND OLD.statut = 'ASSIGNEE' AND NEW.soignant_assigne_id IS NOT NULL THEN
        IF NOT fn_documents_ok_pour_mission(NEW.soignant_assigne_id, NEW.type_contrat_applique::text) THEN
            RAISE EXCEPTION 'Documents obligatoires non validés pour le régime de cette mission. Le soignant doit compléter son dossier avant le début.';
        END IF;
        IF NEW.type_contrat_applique = 'LIBERAL' THEN
            SELECT EXISTS(SELECT 1 FROM documents_soignants
                WHERE soignant_id = NEW.soignant_assigne_id AND type_document = 'RCP_ASSURANCE'
                AND statut_verification = 'VERIFIE' AND supprime_le IS NULL
                AND (valide_jusqua IS NULL OR valide_jusqua > CURRENT_DATE)) INTO v_rcp_ok;
            IF NOT v_rcp_ok THEN
                RAISE EXCEPTION 'Assurance RCP manquante ou expirée. Le soignant ne peut pas commencer la mission en libéral.';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_docs_avant_debut"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_verifier_docs_jusqua_fin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_type_manquant public.type_document;
  v_regime_liberal boolean;
  v_verifier boolean := false;
BEGIN
  IF NEW.statut = 'ASSIGNEE' AND NEW.soignant_assigne_id IS NOT NULL THEN
    IF TG_OP = 'INSERT' THEN
      v_verifier := true;
    ELSE
      v_verifier := OLD.statut IS DISTINCT FROM NEW.statut
        OR OLD.soignant_assigne_id IS DISTINCT FROM NEW.soignant_assigne_id
        OR OLD.type_contrat_applique IS DISTINCT FROM NEW.type_contrat_applique;
    END IF;
  END IF;

  IF v_verifier THEN
    IF NEW.type_contrat_applique IS NULL THEN
      RAISE EXCEPTION 'Le contrat appliqué doit être déterminé avant l''affectation.'
        USING ERRCODE = 'check_violation';
    END IF;

    v_regime_liberal := upper(COALESCE(NEW.type_contrat_applique::text, 'SALARIE')) = 'LIBERAL';

    IF NOT public.fn_documents_ok_pour_mission(
      NEW.soignant_assigne_id,
      NEW.type_contrat_applique::text
    ) THEN
      RAISE EXCEPTION 'Les documents obligatoires ne sont pas tous vérifiés pour le contrat attribué.'
        USING ERRCODE = 'check_violation';
    END IF;

    SELECT drp.type_document
      INTO v_type_manquant
    FROM public.documents_requis_par_profession drp
    JOIN public.soignants s
      ON s.id = NEW.soignant_assigne_id
     AND s.profession = drp.profession
     AND s.supprime_le IS NULL
    WHERE drp.est_critique IS TRUE
      AND drp.type_document NOT IN ('RPPS_ADELI', 'DIPLOME')
      AND (
        drp.type_exercice_requis = 'TOUS'
        OR (drp.type_exercice_requis = 'LIBERAL_ONLY' AND v_regime_liberal)
        OR (drp.type_exercice_requis = 'SALARIE_ONLY' AND NOT v_regime_liberal)
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.documents_soignants ds
        WHERE ds.soignant_id = NEW.soignant_assigne_id
          AND public.fn_type_document_preuve_compatible(
            drp.type_document,
            ds.type_document
          )
          AND ds.statut_verification = 'VERIFIE'
          AND ds.supprime_le IS NULL
          AND (
            drp.a_expiration IS FALSE
            OR (
              ds.valide_jusqua IS NOT NULL
              AND ds.valide_jusqua >= NEW.fin_le::date
            )
          )
      )
    LIMIT 1;

    IF v_type_manquant IS NOT NULL THEN
      RAISE EXCEPTION 'Aucun document vérifié de type « % » ne couvre la mission jusqu’au %. Veuillez le renouveler.',
        v_type_manquant,
        to_char(NEW.fin_le, 'DD/MM/YYYY')
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_docs_jusqua_fin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_verifier_eligibilite_liberal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_heures_cumulees numeric;
  v_seuil_heures numeric;
  v_etablissement record;
  v_mode jsonb;
  v_verifier boolean := false;
BEGIN
  IF NEW.soignant_assigne_id IS NOT NULL
     AND NEW.statut = 'ASSIGNEE'
     AND NEW.type_contrat_applique::text = 'LIBERAL' THEN
    IF TG_OP = 'INSERT' THEN
      v_verifier := true;
    ELSE
      v_verifier := OLD.statut IS DISTINCT FROM NEW.statut
        OR OLD.soignant_assigne_id IS DISTINCT FROM NEW.soignant_assigne_id
        OR OLD.type_contrat_applique IS DISTINCT FROM NEW.type_contrat_applique;
    END IF;
  END IF;

  IF NOT v_verifier THEN
    RETURN NEW;
  END IF;

  IF upper(COALESCE(NEW.type_contrat_recherche::text, 'SALARIE'))
       NOT IN ('LIBERAL', 'TOUS') THEN
    RAISE EXCEPTION 'La mission n''est pas ouverte a un contrat liberal.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT e.type::text AS type_etablissement,
         COALESCE(e.est_secteur_public, false) AS est_public
  INTO v_etablissement
  FROM public.etablissements e
  WHERE e.id = NEW.etablissement_id
    AND e.supprime_le IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Etablissement introuvable pour la mission.'
      USING ERRCODE = 'check_violation';
  END IF;

  v_mode := public.fn_mode_exercice(
    NEW.profession_requise::text,
    v_etablissement.type_etablissement,
    CASE WHEN v_etablissement.est_public THEN 'PUBLIC' ELSE NULL END
  );
  IF COALESCE(v_mode->>'niveau', 'NON_PROPOSE') <> 'AUTORISE' THEN
    RAISE EXCEPTION '%', COALESCE(
      v_mode->>'source_libelle',
      'Cette profession est proposee en salarie pour cet etablissement.'
    ) USING ERRCODE = 'check_violation';
  END IF;

  IF NOT public.fn_soignant_liberal_actif_verifie(
    NEW.soignant_assigne_id
  ) THEN
    RAISE EXCEPTION 'Le profil liberal doit etre actif, avec SIRET et identite verifies.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT public.fn_documents_ok_pour_mission(
    NEW.soignant_assigne_id, 'LIBERAL'
  ) THEN
    RAISE EXCEPTION 'Les documents requis pour la mission liberale ne sont pas tous verifies.'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.soignants s
    WHERE s.id = NEW.soignant_assigne_id
      AND s.supprime_le IS NULL
  ) THEN
    RAISE EXCEPTION 'Profil soignant introuvable.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT h.heures_totales
  INTO v_heures_cumulees
  FROM private.fn_heures_exercice_verifiees(
    NEW.soignant_assigne_id
  ) h;

  SELECT private.fn_seuil_heures_liberal(
    NEW.soignant_assigne_id,
    NEW.profession_requise::text
  )
  INTO v_seuil_heures;
  IF v_seuil_heures IS NULL THEN
    RAISE EXCEPTION 'Le parcours kine (2 240 heures ou zone sous-dotee) doit etre choisi avant une mission liberale.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF COALESCE(v_heures_cumulees, 0) < v_seuil_heures THEN
    RAISE EXCEPTION 'Vous devez cumuler % heures d''exercice pour accepter cette mission liberale. Vous avez actuellement % heures.',
      v_seuil_heures,
      round(COALESCE(v_heures_cumulees, 0), 2)
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_eligibilite_liberal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_verifier_evaluation_counterparty"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_expected_evalue UUID;
    v_etab_id UUID;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = NEW.mission_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Mission introuvable';
    END IF;

    v_etab_id := mon_etablissement_id();

    IF v_mission.soignant_assigne_id = NEW.evaluateur_id THEN
        -- Soignant évalue → doit évaluer l'établissement
        v_expected_evalue := v_mission.etablissement_id;
    ELSIF v_mission.etablissement_id = v_etab_id THEN
        -- Établissement évalue → doit évaluer le soignant
        v_expected_evalue := v_mission.soignant_assigne_id;
    ELSIF est_admin() THEN
        -- Admin peut évaluer
        NEW.visible := FALSE;
        RETURN NEW;
    ELSE
        RAISE EXCEPTION 'Vous n''avez pas participé à cette mission.';
    END IF;

    IF NEW.evalue_id != v_expected_evalue THEN
        RAISE EXCEPTION 'L''évaluation doit concerner l''autre partie de la mission.';
    END IF;

    -- Forcer visible = FALSE (modération admin)
    NEW.visible := FALSE;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_evaluation_counterparty"() OWNER TO "postgres";


