CREATE OR REPLACE FUNCTION "public"."dec_verifier_moyenne_44h_12_semaines"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_regime text;
  v_nb_creneaux_valides integer;
  v_fin_fenetre date;
  v_debut_fenetre date;
  v_heures_jolene numeric;
  v_heures_externes numeric;
  v_heures_mission numeric;
  v_heures_total numeric;
  v_moyenne numeric;
  v_moyenne_max numeric := 0;
  v_fenetre_max_debut date;
  v_fenetre_max_fin date;
BEGIN
  IF NEW.soignant_assigne_id IS NULL
     OR NEW.statut NOT IN ('ASSIGNEE', 'EN_COURS') THEN
    RETURN NEW;
  END IF;

  -- Le régime se résout sur la mission, jamais sur les diplômes ou le statut
  -- global du profil. Une IADE sur une mission IDE salariée est donc contrôlée;
  -- une mission effectivement libérale ne l'est pas.
  v_regime := COALESCE(
    NEW.type_contrat_applique::text,
    NULLIF(upper(NEW.choix_contrat_soignant), ''),
    CASE
      WHEN NEW.type_contrat_recherche::text = 'LIBERAL' THEN 'LIBERAL'
      ELSE 'SALARIE'
    END
  );
  IF v_regime = 'LIBERAL' THEN
    RETURN NEW;
  END IF;

  -- Même verrou que l'attribution atomique et le plafond de 48 h : deux
  -- missions ne peuvent pas valider en parallèle le même planning.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('jolene:attribution:' || NEW.soignant_assigne_id::text, 0)
  );

  IF COALESCE(NEW.nb_creneaux, 0) > 1 THEN
    SELECT count(*)::integer
    INTO v_nb_creneaux_valides
    FROM public.mission_creneaux mc
    WHERE mc.mission_id = NEW.id
      AND mc.fin IS NOT NULL
      AND NOT mc.est_pause
      AND mc.type_creneau = CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.mission_creneaux p
          WHERE p.mission_id = NEW.id
            AND p.type_creneau = 'PREVISIONNEL'
            AND p.fin IS NOT NULL
            AND NOT p.est_pause
        ) THEN 'PREVISIONNEL'
        ELSE 'EFFECTIF'
      END;

    IF v_nb_creneaux_valides < NEW.nb_creneaux THEN
      RAISE EXCEPTION
        '[PLANNING_HEBDOMADAIRE_INDISPONIBLE] Mission % : % créneau(x) valide(s) sur % attendu(s)',
        NEW.id, v_nb_creneaux_valides, NEW.nb_creneaux;
    END IF;
  END IF;

  -- Une heure ajoutée en semaine S affecte les douze fenêtres glissantes se
  -- terminant de S à S+11. On vérifie l'union de ces fenêtres pour chacune des
  -- semaines réellement touchées par la mission.
  FOR v_fin_fenetre IN
    SELECT DISTINCT (sm.semaine_debut + (offsets.n * 7))::date
    FROM public.fn_semaines_mission(NEW.id) sm
    CROSS JOIN generate_series(0, 11) AS offsets(n)
    ORDER BY 1
  LOOP
    v_debut_fenetre := v_fin_fenetre - 77;

    SELECT COALESCE(sum(
      public.fn_heures_soignant_semaine(
        NEW.soignant_assigne_id,
        (v_debut_fenetre + (semaines.n * 7))::date,
        NEW.id
      )
    ), 0)
    INTO v_heures_jolene
    FROM generate_series(0, 11) AS semaines(n);

    SELECT COALESCE(sum(COALESCE(a.heures_salarie, 0)), 0)
    INTO v_heures_externes
    FROM public.attestations_heures_externes a
    WHERE a.soignant_id = NEW.soignant_assigne_id
      AND a.semaine_du BETWEEN v_debut_fenetre AND v_fin_fenetre;

    SELECT COALESCE(sum(sm.heures), 0)
    INTO v_heures_mission
    FROM public.fn_semaines_mission(NEW.id) sm
    WHERE sm.semaine_debut BETWEEN v_debut_fenetre AND v_fin_fenetre;

    v_heures_total := v_heures_jolene + v_heures_externes + v_heures_mission;
    v_moyenne := v_heures_total / 12.0;

    IF v_moyenne > v_moyenne_max THEN
      v_moyenne_max := v_moyenne;
      v_fenetre_max_debut := v_debut_fenetre;
      v_fenetre_max_fin := v_fin_fenetre + 6;
    END IF;

    IF v_moyenne > 44.0 THEN
      INSERT INTO public.conformite_travail (
        soignant_id, mission_id, type_controle, resultat, details_violation
      ) VALUES (
        NEW.soignant_assigne_id,
        NEW.id,
        'MOYENNE_44H_12_SEMAINES',
        'VIOLATION_BLOQUEE',
        jsonb_build_object(
          'fenetre_debut', v_debut_fenetre,
          'fenetre_fin', v_fin_fenetre + 6,
          'heures_jolene_existantes', round(v_heures_jolene, 2),
          'heures_mission', round(v_heures_mission, 2),
          'heures_externes', round(v_heures_externes, 2),
          'total_heures', round(v_heures_total, 2),
          'moyenne_hebdo', round(v_moyenne, 2),
          'nb_semaines', 12,
          'plafond_moyenne', 44,
          'article', 'L3121-22'
        )
      );

      RAISE EXCEPTION
        '[CODE DU TRAVAIL] Moyenne dépassée du % au % : %h/semaine sur 12 semaines (max 44h, Art. L3121-22). Assignation bloquée.',
        to_char(v_debut_fenetre, 'DD/MM/YYYY'),
        to_char(v_fin_fenetre + 6, 'DD/MM/YYYY'),
        round(v_moyenne, 1);
    END IF;
  END LOOP;

  IF v_moyenne_max > 40.0 THEN
    INSERT INTO public.conformite_travail (
      soignant_id, mission_id, type_controle, resultat, details_violation
    ) VALUES (
      NEW.soignant_assigne_id,
      NEW.id,
      'MOYENNE_44H_12_SEMAINES',
      'CONFORME',
      jsonb_build_object(
        'moyenne_hebdo_max', round(v_moyenne_max, 2),
        'fenetre_debut', v_fenetre_max_debut,
        'fenetre_fin', v_fenetre_max_fin,
        'nb_semaines', 12,
        'plafond_moyenne', 44,
        'article', 'L3121-22'
      )
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_moyenne_44h_12_semaines"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dec_verifier_moyenne_44h_12_semaines"() IS 'Contrôle salarié de toute fenêtre glissante de 12 semaines affectée par la mission, ventilée par semaine réelle (Art. L3121-22).';



CREATE OR REPLACE FUNCTION "public"."dec_verifier_numerotation_facture"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_dernier_numero TEXT;
    v_dernier_seq INTEGER;
    v_nouveau_seq INTEGER;
BEGIN
    -- Extraire le séquentiel du dernier numéro
    SELECT numero_facture INTO v_dernier_numero
    FROM factures
    WHERE numero_facture LIKE 'SD-' || TO_CHAR(NOW(), 'YYYYMM') || '-%'
    ORDER BY cree_le DESC LIMIT 1;

    IF v_dernier_numero IS NOT NULL THEN
        v_dernier_seq := SPLIT_PART(v_dernier_numero, '-', 3)::INTEGER;
        v_nouveau_seq := SPLIT_PART(NEW.numero_facture, '-', 3)::INTEGER;
        IF v_nouveau_seq != v_dernier_seq + 1 THEN
            RAISE WARNING 'Saut de numérotation facture détecté : % → %', v_dernier_numero, NEW.numero_facture;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_numerotation_facture"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_verifier_plafond_48h"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_semaine record;
  v_heures_jolene numeric;
  v_heures_externes numeric;
  v_heures_total numeric;
  v_regime text;
  v_nb_creneaux_valides integer;
  v_details_semaines jsonb := '[]'::jsonb;
BEGIN
  IF NEW.soignant_assigne_id IS NULL OR NEW.statut NOT IN ('ASSIGNEE', 'EN_COURS') THEN
    RETURN NEW;
  END IF;

  v_regime := COALESCE(
    NEW.type_contrat_applique::text,
    NULLIF(upper(NEW.choix_contrat_soignant), ''),
    CASE WHEN NEW.type_contrat_recherche::text = 'LIBERAL' THEN 'LIBERAL' ELSE 'SALARIE' END
  );
  IF v_regime = 'LIBERAL' THEN RETURN NEW; END IF;

  IF COALESCE(NEW.nb_creneaux, 0) > 1 THEN
    SELECT count(*)::integer INTO v_nb_creneaux_valides
      FROM public.mission_creneaux mc
     WHERE mc.mission_id = NEW.id
       AND mc.fin IS NOT NULL
       AND mc.type_creneau = CASE
         WHEN EXISTS (
           SELECT 1 FROM public.mission_creneaux p
            WHERE p.mission_id = NEW.id AND p.type_creneau = 'PREVISIONNEL'
              AND p.fin IS NOT NULL AND NOT p.est_pause
         ) THEN 'PREVISIONNEL'
         ELSE 'EFFECTIF'
       END;
    IF v_nb_creneaux_valides < NEW.nb_creneaux THEN
      RAISE EXCEPTION '[PLANNING_HEBDOMADAIRE_INDISPONIBLE] Mission % : % créneau(x) valide(s) sur % attendu(s)',
        NEW.id, v_nb_creneaux_valides, NEW.nb_creneaux;
    END IF;
  END IF;

  FOR v_semaine IN
    SELECT * FROM public.fn_semaines_mission(NEW.id)
  LOOP
    v_heures_jolene := public.fn_heures_soignant_semaine(
      NEW.soignant_assigne_id, v_semaine.semaine_debut, NEW.id
    );
    SELECT COALESCE(heures_salarie, 0)
      INTO v_heures_externes
      FROM public.attestations_heures_externes
     WHERE soignant_id = NEW.soignant_assigne_id
       AND semaine_du = v_semaine.semaine_debut;
    IF NOT FOUND THEN v_heures_externes := 0; END IF;

    v_heures_total := v_heures_jolene + v_heures_externes + v_semaine.heures;
    v_details_semaines := v_details_semaines || jsonb_build_array(jsonb_build_object(
      'semaine_du', v_semaine.semaine_debut,
      'heures_jolene_existantes', round(v_heures_jolene, 2),
      'heures_mission', round(v_semaine.heures, 2),
      'heures_externes', round(v_heures_externes, 2),
      'total', round(v_heures_total, 2),
      'plafond', 48
    ));

    IF v_heures_total > 48 THEN
      INSERT INTO public.conformite_travail(
        soignant_id, mission_id, type_controle, resultat, details_violation
      ) VALUES (
        NEW.soignant_assigne_id, NEW.id, 'PLAFOND_48H_HEBDO', 'VIOLATION_BLOQUEE',
        jsonb_build_object(
          'semaine_du', v_semaine.semaine_debut,
          'heures_jolene', round(v_heures_jolene + v_semaine.heures, 2),
          'heures_externes', round(v_heures_externes, 2),
          'total', round(v_heures_total, 2),
          'plafond', 48,
          'article', 'L3121-20'
        )
      );
      RAISE EXCEPTION '[CODE DU TRAVAIL] Semaine du % : %h Jolene + %h ailleurs = %h total (max 48h, Art. L3121-20)',
        to_char(v_semaine.semaine_debut, 'DD/MM/YYYY'),
        round(v_heures_jolene + v_semaine.heures, 1),
        round(v_heures_externes, 1),
        round(v_heures_total, 1);
    END IF;
  END LOOP;

  INSERT INTO public.conformite_travail(
    soignant_id, mission_id, type_controle, resultat, details_violation
  ) VALUES (
    NEW.soignant_assigne_id, NEW.id, 'PLAFOND_48H_HEBDO', 'CONFORME',
    jsonb_build_object('semaines', v_details_semaines)
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."dec_verifier_plafond_48h"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dec_verifier_profession_etablissement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type public.type_etablissement;
BEGIN
  SELECT type INTO v_type FROM public.etablissements WHERE id = NEW.etablissement_id;
  IF v_type = 'PHARMACIE_OFFICINE' THEN
    RAISE EXCEPTION 'Jolene ne propose pas le remplacement du titulaire d''une officine. Les missions pharmacien proposées par la plateforme sont des missions salariées d''établissement, notamment en PUI.';
  END IF;
  RETURN NEW;
END;
$$;


