CREATE OR REPLACE FUNCTION "public"."est_admin_etablissement"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  SELECT public.fn_role_etablissement_courant(NULL) IN ('PROPRIETAIRE', 'ADMIN_GROUPE', 'RH');
$$;


ALTER FUNCTION "public"."est_admin_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."est_admin_valide"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  SELECT COALESCE(EXISTS (
    SELECT 1
    FROM auth.users u
    WHERE u.id = auth.uid()
      AND u.raw_app_meta_data ->> 'role' = 'ADMIN_PLATEFORME'
      AND u.deleted_at IS NULL
      AND (u.banned_until IS NULL OR u.banned_until <= now())
      AND u.email_confirmed_at IS NOT NULL
      AND (
        COALESCE(auth.jwt() ->> 'aal', '') = 'aal2'
        OR lower(COALESCE(u.email, '')) IN (
          'admin@jolene.app',
          'gabrielle.pcd@outlook.com'
        )
      )
      AND EXISTS (
        SELECT 1
        FROM public.equipe_admin ea
        WHERE ea.user_id = u.id
          AND ea.actif IS TRUE
          AND ARRAY[
            'Dashboard',
            'Utilisateurs',
            'Missions',
            'Litiges & contrats',
            'Finances',
            'Messagerie',
            'Conformité & Technique',
            'Fondateur'
          ]::text[] <@ COALESCE(ea.acces_groupes, ARRAY[]::text[])
      )
  ), false);
$$;


ALTER FUNCTION "public"."est_admin_valide"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."est_admin_valide"() IS 'Garde admin de lancement : rôle canonique, compte sain, registre 8/8 et AAL2, sauf les deux comptes fondateurs explicitement autorisés sans MFA.';



