CREATE OR REPLACE FUNCTION "public"."fn_admin_creer_compte_employe"("p_email" "text", "p_password" "text", "p_prenom" "text", "p_nom" "text", "p_poste" "text" DEFAULT 'Opérations'::"text", "p_salaire_brut" numeric DEFAULT 0, "p_acces_groupes" "text"[] DEFAULT ARRAY['Dashboard'::"text", 'Utilisateurs'::"text", 'Missions'::"text", 'Litiges & contrats'::"text", 'Finances'::"text", 'Messagerie'::"text", 'Conformité & Technique'::"text", 'Fondateur'::"text"]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_groupes_lancement constant text[] := ARRAY[
    'Dashboard',
    'Utilisateurs',
    'Missions',
    'Litiges & contrats',
    'Finances',
    'Messagerie',
    'Conformité & Technique',
    'Fondateur'
  ]::text[];
BEGIN
  IF NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse au lancement' USING ERRCODE = '42501';
  END IF;

  -- p_acces_groupes reste dans la signature pour compatibilite PostgREST,
  -- mais une creation partielle est volontairement impossible au lancement.
  RETURN private.fn_admin_creer_compte_employe_interne_lancement(
    p_email,
    p_password,
    p_prenom,
    p_nom,
    p_poste,
    p_salaire_brut,
    v_groupes_lancement
  );
END;
$$;


