CREATE OR REPLACE FUNCTION "public"."fn_admin_creer_litige_force"("p_mission_id" "uuid", "p_type_litige" "public"."type_litige", "p_motif" "text", "p_raison_bypass" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_mission RECORD;
  v_litige_id UUID;
  v_est_informatif BOOLEAN;
  v_facture_id UUID;
BEGIN
  IF v_user_id IS NULL OR NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Admin requis pour cette opération.');
  END IF;
  IF length(trim(p_motif)) < 10 THEN
    RETURN jsonb_build_object('error', 'Le motif doit contenir au moins 10 caractères.');
  END IF;
  IF length(trim(COALESCE(p_raison_bypass, ''))) < 10 THEN
    RETURN jsonb_build_object('error', 'La raison du bypass doit contenir au moins 10 caractères (traçabilité).');
  END IF;

  SELECT id, etablissement_id, soignant_assigne_id
    INTO v_mission
    FROM public.missions WHERE id = p_mission_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;

  IF p_type_litige IN ('DESACCORD_MONTANT_FACTURE', 'NON_PAIEMENT', 'FRAIS_COMPLEMENTAIRES') THEN
    SELECT id INTO v_facture_id
      FROM public.factures_honoraires
     WHERE mission_id = p_mission_id AND statut <> 'BROUILLON'
     ORDER BY date_emission DESC NULLS LAST
     LIMIT 1;
  END IF;

  v_est_informatif := NOT public.fn_fenetre_contestation_ouverte(
    p_type_litige, p_mission_id, v_facture_id
  );

  INSERT INTO public.litiges (
    mission_id, soignant_id, etablissement_id, initie_par,
    motif, statut, type_litige, est_informatif, facture_id
  )
  VALUES (
    p_mission_id, v_mission.soignant_assigne_id, v_mission.etablissement_id, 'ADMIN',
    trim(p_motif), 'OUVERT', p_type_litige, v_est_informatif, v_facture_id
  )
  RETURNING id INTO v_litige_id;

  PERFORM public.fn_ecrire_audit(
    v_user_id, 'ADMIN', 'LITIGE_FORCE_CREATION',
    'litige', v_litige_id, NULL,
    jsonb_build_object(
      'mission_id', p_mission_id,
      'type_litige', p_type_litige,
      'est_informatif', v_est_informatif,
      'raison_bypass', trim(p_raison_bypass),
      'facture_id', v_facture_id
    ),
    NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'litige_id', v_litige_id,
    'est_informatif', v_est_informatif,
    'facture_id', v_facture_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_creer_litige_force"("p_mission_id" "uuid", "p_type_litige" "public"."type_litige", "p_motif" "text", "p_raison_bypass" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_admin_creer_litige_force"("p_mission_id" "uuid", "p_type_litige" "public"."type_litige", "p_motif" "text", "p_raison_bypass" "text") IS 'Admin-only : crée un litige en bypassant la fenêtre de contestation. FIX T18 : résout facture_id pour types financiers + stocke dans litiges.facture_id. Flag est_informatif=TRUE si hors fenêtre. Audit RGPD obligatoire avec raison.';



CREATE OR REPLACE FUNCTION "public"."fn_admin_crm_assigner_contact"("p_contact_id" "uuid", "p_responsable_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
BEGIN
  IF NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse' USING ERRCODE = '42501';
  END IF;
  IF p_responsable_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.equipe_admin WHERE user_id = p_responsable_id AND actif IS TRUE
  ) THEN
    RAISE EXCEPTION 'Responsable CRM invalide';
  END IF;

  UPDATE public.sales_contacts
     SET responsable_id = p_responsable_id, maj_le = now()
   WHERE id = p_contact_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Contact CRM introuvable'; END IF;
  UPDATE public.sales_taches
     SET assignee_a = p_responsable_id, maj_le = now()
   WHERE contact_id = p_contact_id AND statut IN ('A_FAIRE', 'EN_COURS');
  INSERT INTO public.sales_activites (contact_id, action_type, resultat, acteur_id)
  VALUES (p_contact_id, 'ATTRIBUTION', COALESCE(p_responsable_id::text, 'NON_ASSIGNE'), auth.uid());

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_crm_assigner_contact"("p_contact_id" "uuid", "p_responsable_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_crm_effectuer_action"("p_tache_id" "uuid", "p_resultat" "text", "p_notes" "text" DEFAULT NULL::"text", "p_prochaine_action_le" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_tache public.sales_taches%ROWTYPE;
  v_contact public.sales_contacts%ROWTYPE;
  v_etape smallint;
  v_echeance timestamptz;
BEGIN
  IF NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse' USING ERRCODE = '42501';
  END IF;
  IF p_resultat NOT IN (
    'EMAIL_ENVOYE', 'APPEL_REPONDU', 'SANS_REPONSE', 'INTERESSE',
    'INSCRIT', 'A_RAPPELER', 'PAS_INTERESSE', 'STOP'
  ) THEN
    RAISE EXCEPTION 'Resultat CRM invalide';
  END IF;

  SELECT * INTO v_tache
  FROM public.sales_taches
  WHERE id = p_tache_id
  FOR UPDATE;
  IF NOT FOUND OR v_tache.statut NOT IN ('A_FAIRE', 'EN_COURS') THEN
    RAISE EXCEPTION 'Tache CRM absente ou deja traitee';
  END IF;

  SELECT * INTO v_contact
  FROM public.sales_contacts
  WHERE id = v_tache.contact_id
  FOR UPDATE;

  IF p_resultat = 'EMAIL_ENVOYE' THEN
    PERFORM public.fn_crm_enregistrer_email_envoye(v_contact.id, false, p_notes);
  ELSE
    UPDATE public.sales_taches
       SET statut = 'TERMINEE', terminee_le = now(), terminee_par = auth.uid(),
           notes = COALESCE(p_notes, notes), maj_le = now()
     WHERE id = p_tache_id;

    v_etape := CASE
      WHEN p_resultat IN ('APPEL_REPONDU', 'SANS_REPONSE', 'INTERESSE') THEN LEAST(v_contact.sequence_etape + 1, 20)
      ELSE v_contact.sequence_etape
    END;
    v_echeance := CASE
      WHEN p_resultat = 'A_RAPPELER' THEN COALESCE(p_prochaine_action_le, now() + interval '1 day')
      WHEN p_resultat = 'INTERESSE' THEN COALESCE(p_prochaine_action_le, now() + interval '1 day')
      WHEN p_resultat = 'SANS_REPONSE' THEN COALESCE(p_prochaine_action_le, now() + interval '2 days')
      WHEN p_resultat = 'APPEL_REPONDU' THEN COALESCE(p_prochaine_action_le, now() + interval '3 days')
      ELSE NULL
    END;

    UPDATE public.sales_contacts
       SET statut = CASE
             WHEN p_resultat = 'INSCRIT' THEN 'INSCRIT'
             WHEN p_resultat = 'INTERESSE' AND statut = 'PROSPECT' THEN 'CONTACTE'
             WHEN p_resultat IN ('PAS_INTERESSE', 'STOP') THEN 'PERDU'
             WHEN p_resultat = 'SANS_REPONSE' THEN 'RELANCE'
             WHEN p_resultat = 'APPEL_REPONDU' AND statut = 'PROSPECT' THEN 'CONTACTE'
             ELSE statut
           END,
           reponse = CASE
             WHEN p_resultat IN ('INTERESSE', 'INSCRIT') THEN 'POSITIVE'
             WHEN p_resultat IN ('PAS_INTERESSE', 'STOP') THEN 'NEGATIVE'
             WHEN p_resultat = 'APPEL_REPONDU' THEN 'EN_ATTENTE'
             ELSE reponse
           END,
           a_rappeler = p_resultat IN ('A_RAPPELER', 'SANS_REPONSE', 'APPEL_REPONDU', 'INTERESSE'),
           ne_plus_contacter = p_resultat IN ('PAS_INTERESSE', 'STOP'),
           sequence_active = p_resultat NOT IN ('INSCRIT', 'PAS_INTERESSE', 'STOP'),
           sequence_etape = v_etape,
           prochaine_action_le = v_echeance,
           dernier_contact_le = CASE
             WHEN p_resultat IN ('APPEL_REPONDU', 'SANS_REPONSE', 'INTERESSE') THEN now()
             ELSE dernier_contact_le
           END,
           derniere_action_type = p_resultat,
           maj_le = now()
     WHERE id = v_contact.id;

    INSERT INTO public.sales_activites (
      contact_id, tache_id, action_type, canal, resultat, details, acteur_id, automatisee
    ) VALUES (
      v_contact.id, v_tache.id, 'TACHE_TRAITEE', v_tache.canal,
      p_resultat, p_notes, auth.uid(), false
    );

    IF v_echeance IS NOT NULL THEN
      PERFORM public.fn_crm_generer_taches();
    END IF;
  END IF;

  RETURN jsonb_build_object('success', true, 'contact_id', v_contact.id, 'resultat', p_resultat);
END;
$$;


ALTER FUNCTION "public"."fn_admin_crm_effectuer_action"("p_tache_id" "uuid", "p_resultat" "text", "p_notes" "text", "p_prochaine_action_le" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_crm_reporter_tache"("p_tache_id" "uuid", "p_echeance_le" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_contact_id uuid;
BEGIN
  IF NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse' USING ERRCODE = '42501';
  END IF;
  IF p_echeance_le <= now() - interval '5 minutes' OR p_echeance_le > now() + interval '1 year' THEN
    RAISE EXCEPTION 'Nouvelle echeance invalide';
  END IF;

  UPDATE public.sales_taches
     SET echeance_le = p_echeance_le, priorite = 'NORMALE', maj_le = now()
   WHERE id = p_tache_id AND statut IN ('A_FAIRE', 'EN_COURS')
   RETURNING contact_id INTO v_contact_id;
  IF v_contact_id IS NULL THEN RAISE EXCEPTION 'Tache CRM introuvable'; END IF;

  UPDATE public.sales_contacts
     SET prochaine_action_le = p_echeance_le, a_rappeler = true, maj_le = now()
   WHERE id = v_contact_id;
  INSERT INTO public.sales_activites (contact_id, tache_id, action_type, resultat, acteur_id)
  VALUES (v_contact_id, p_tache_id, 'TACHE_REPORTEE', p_echeance_le::text, auth.uid());

  RETURN jsonb_build_object('success', true, 'echeance_le', p_echeance_le);
END;
$$;


ALTER FUNCTION "public"."fn_admin_crm_reporter_tache"("p_tache_id" "uuid", "p_echeance_le" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_crm_tableau"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse' USING ERRCODE = '42501';
  END IF;

  SELECT jsonb_build_object(
    'stats', jsonb_build_object(
      'a_traiter', (SELECT count(*) FROM public.sales_taches WHERE statut IN ('A_FAIRE', 'EN_COURS') AND echeance_le <= now()),
      'en_retard', (SELECT count(*) FROM public.sales_taches WHERE statut IN ('A_FAIRE', 'EN_COURS') AND echeance_le < date_trunc('day', now())),
      'sept_jours', (SELECT count(*) FROM public.sales_taches WHERE statut IN ('A_FAIRE', 'EN_COURS') AND echeance_le <= now() + interval '7 days'),
      'sans_responsable', (SELECT count(*) FROM public.sales_contacts WHERE archive IS FALSE AND sequence_active IS TRUE AND responsable_id IS NULL),
      'contacts_actifs', (SELECT count(*) FROM public.sales_contacts WHERE archive IS FALSE AND statut NOT IN ('INSCRIT', 'PERDU')),
      'taux_conversion', (SELECT CASE WHEN count(*) = 0 THEN 0 ELSE round(100.0 * count(*) FILTER (WHERE statut = 'INSCRIT') / count(*), 1) END FROM public.sales_contacts WHERE archive IS FALSE),
      'emails_7j', (SELECT count(*) FROM public.sales_activites WHERE action_type = 'EMAIL_ENVOYE' AND cree_le >= now() - interval '7 days'),
      'actions_7j', (SELECT count(*) FROM public.sales_activites WHERE cree_le >= now() - interval '7 days')
    ),
    'taches', COALESCE((
      SELECT jsonb_agg(to_jsonb(t) ORDER BY t.echeance_le, t.priorite DESC)
      FROM (
        SELECT st.id, st.contact_id, st.type, st.canal, st.statut, st.priorite,
               st.titre, st.echeance_le, st.assignee_a, st.sequence_etape,
               st.origine, st.notes,
               sc.type AS contact_type, sc.nom, sc.profession, sc.telephone,
               sc.email, sc.ville, sc.departement, sc.statut AS contact_statut,
               sc.reponse, sc.ne_plus_contacter
        FROM public.sales_taches st
        JOIN public.sales_contacts sc ON sc.id = st.contact_id
        WHERE st.statut IN ('A_FAIRE', 'EN_COURS')
        ORDER BY st.echeance_le,
                 CASE st.priorite WHEN 'URGENTE' THEN 0 WHEN 'HAUTE' THEN 1 WHEN 'NORMALE' THEN 2 ELSE 3 END
        LIMIT LEAST(GREATEST(p_limit, 1), 300)
      ) t
    ), '[]'::jsonb),
    'activites', COALESCE((
      SELECT jsonb_agg(to_jsonb(a) ORDER BY a.cree_le DESC)
      FROM (
        SELECT sa.id, sa.contact_id, sa.action_type, sa.canal, sa.resultat,
               sa.details, sa.acteur_id, sa.automatisee, sa.cree_le, sc.nom
        FROM public.sales_activites sa
        JOIN public.sales_contacts sc ON sc.id = sa.contact_id
        ORDER BY sa.cree_le DESC
        LIMIT 30
      ) a
    ), '[]'::jsonb),
    'responsables', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'user_id', ea.user_id, 'nom', ea.nom, 'prenom', ea.prenom, 'email', ea.email
      ) ORDER BY ea.prenom, ea.nom)
      FROM public.equipe_admin ea
      WHERE ea.actif IS TRUE AND ea.user_id IS NOT NULL
    ), '[]'::jsonb),
    'genere_le', now()
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_admin_crm_tableau"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_decider_preuve_etablissement"("p_etablissement_id" "uuid", "p_preuve" "text", "p_decision" "text", "p_motif" "text", "p_version_attendue" bigint, "p_source_s3_key_attendue" "text", "p_date_naissance_confirmee" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab public.etablissements%ROWTYPE;
  v_source_s3_key text;
  v_resultat jsonb;
  v_resultat_final jsonb;
  v_snapshot jsonb;
  v_rapprochement jsonb;
  v_rattachement jsonb;
  v_version_finale bigint;
  v_motif text := NULLIF(btrim(p_motif), '');
BEGIN
  IF v_uid IS NULL
     OR NOT public.est_admin_valide() THEN
    RAISE EXCEPTION 'Administrateur autorisé requis'
      USING ERRCODE = '42501';
  END IF;
  IF p_preuve NOT IN ('IDENTITE', 'FONCTION')
     OR p_decision NOT IN ('APPROUVER', 'REJETER') THEN
    RAISE EXCEPTION 'Décision de preuve invalide' USING ERRCODE = '22023';
  END IF;
  IF p_decision = 'REJETER' AND COALESCE(length(v_motif), 0) < 5 THEN
    RAISE EXCEPTION 'Un motif de rejet d au moins 5 caractères est requis'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Établissement introuvable' USING ERRCODE = 'P0002';
  END IF;
  IF v_etab.statut_verification = 'REJETE' THEN
    RAISE EXCEPTION 'Le dossier global est rejeté; rechargez la file'
      USING ERRCODE = '40001';
  END IF;
  IF v_etab.verification_source_version IS DISTINCT FROM p_version_attendue THEN
    RAISE EXCEPTION 'Le dossier a changé : rechargez avant de décider'
      USING ERRCODE = '40001';
  END IF;

  IF p_preuve = 'IDENTITE' THEN
    v_source_s3_key := v_etab.representant_piece_s3_key;
    v_resultat := COALESCE(v_etab.representant_identite_resultat_ia, '{}'::jsonb);
  ELSE
    v_source_s3_key := v_etab.justificatif_fonction_s3_key;
    v_resultat := COALESCE(v_etab.justificatif_fonction_resultat_ia, '{}'::jsonb);
  END IF;
  IF NULLIF(v_source_s3_key, '') IS NULL
     OR v_source_s3_key IS DISTINCT FROM p_source_s3_key_attendue THEN
    RAISE EXCEPTION 'La source documentaire a changé : rechargez avant de décider'
      USING ERRCODE = '40001';
  END IF;

  v_rapprochement := private.fn_rapprocher_naissance_representant(
    v_resultat,
    v_etab.dirigeants,
    v_etab.representant_nom,
    v_etab.representant_prenom,
    CASE WHEN p_preuve = 'IDENTITE' THEN p_date_naissance_confirmee ELSE NULL END
  );

  IF p_preuve = 'IDENTITE' AND p_decision = 'APPROUVER'
     AND v_rapprochement ->> 'statut' IN ('DIVERGE', 'PIECE_NON_LUE') THEN
    RAISE EXCEPTION 'La date de naissance de la pièce doit correspondre au registre avant approbation'
      USING ERRCODE = '22023';
  END IF;
  IF p_preuve = 'FONCTION' AND p_decision = 'APPROUVER'
     AND v_etab.representant_identite_verifiee IS NOT TRUE THEN
    RAISE EXCEPTION 'L identité du représentant doit être approuvée en premier'
      USING ERRCODE = '22023';
  END IF;

  v_snapshot := jsonb_strip_nulls(jsonb_build_object(
    'source_version', v_etab.verification_source_version,
    'source_s3_key', v_source_s3_key,
    'preuve', p_preuve,
    'resultat_ia', v_resultat,
    'representant_nom', v_etab.representant_nom,
    'representant_prenom', v_etab.representant_prenom,
    'siret', v_etab.siret,
    'siret_verifie', v_etab.siret_verifie,
    'siret_raison_sociale', v_etab.siret_raison_sociale,
    'finess', v_etab.finess,
    'finess_verifie', v_etab.finess_verifie,
    'finess_raison_sociale', v_etab.finess_raison_sociale,
    'rapprochement_naissance', v_rapprochement
  ));

  v_resultat_final := v_resultat || jsonb_build_object(
    'verdict_final', CASE WHEN p_decision = 'APPROUVER' THEN 'VERIFIE' ELSE 'REJETE' END,
    'motif', CASE
      WHEN p_decision = 'APPROUVER' THEN COALESCE(v_motif, 'Approuvé après revue humaine contextualisée.')
      ELSE v_motif
    END,
    'revue_admin', jsonb_strip_nulls(jsonb_build_object(
      'decision', p_decision,
      'admin_id', v_uid,
      'decide_le', now(),
      'motif', v_motif,
      'date_naissance_confirmee', CASE
        WHEN p_preuve = 'IDENTITE' THEN p_date_naissance_confirmee
        ELSE NULL
      END,
      'rapprochement_naissance', v_rapprochement,
      'source_version', p_version_attendue,
      'source_s3_key', v_source_s3_key
    ))
  );

  IF p_preuve = 'IDENTITE' THEN
    UPDATE public.etablissements
    SET representant_identite_verifiee = p_decision = 'APPROUVER',
        representant_identite_verifiee_le = CASE
          WHEN p_decision = 'APPROUVER' THEN now() ELSE NULL
        END,
        representant_identite_resultat_ia = v_resultat_final,
        modifie_le = now()
    WHERE id = p_etablissement_id;
  ELSE
    UPDATE public.etablissements
    SET justificatif_fonction_verifie = p_decision = 'APPROUVER',
        justificatif_fonction_verifie_le = CASE
          WHEN p_decision = 'APPROUVER' THEN now() ELSE NULL
        END,
        justificatif_fonction_resultat_ia = v_resultat_final,
        modifie_le = now()
    WHERE id = p_etablissement_id;
  END IF;

  v_rattachement := public.fn_evaluer_rattachement_etablissement(p_etablissement_id);

  SELECT verification_source_version INTO v_version_finale
  FROM public.etablissements
  WHERE id = p_etablissement_id;

  INSERT INTO public.etablissement_preuve_audit (
    etablissement_id, preuve, evenement, acteur_id, source_version,
    source_s3_key, source_snapshot, motif
  ) VALUES (
    p_etablissement_id,
    p_preuve,
    CASE WHEN p_decision = 'APPROUVER' THEN 'APPROUVE' ELSE 'REJETE' END,
    v_uid, p_version_attendue, v_source_s3_key, v_snapshot,
    CASE
      WHEN p_decision = 'APPROUVER' THEN COALESCE(v_motif, 'Revue humaine contextualisée')
      ELSE v_motif
    END
  );

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'etablissement',
    p_etablissement_id, v_source_s3_key,
    jsonb_build_object(
      'sous_action', 'DECISION_PREUVE_ETABLISSEMENT',
      'preuve', p_preuve,
      'decision', p_decision,
      'motif', v_motif,
      'source_version', p_version_attendue,
      'source_snapshot', v_snapshot,
      'rattachement_apres_decision', v_rattachement
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'preuve', p_preuve,
    'decision', p_decision,
    'rattachement', v_rattachement,
    'verification_source_version', v_version_finale
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_decider_preuve_etablissement"("p_etablissement_id" "uuid", "p_preuve" "text", "p_decision" "text", "p_motif" "text", "p_version_attendue" bigint, "p_source_s3_key_attendue" "text", "p_date_naissance_confirmee" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_decider_revue_manuelle"("p_revue_id" "uuid", "p_decision" "text", "p_motif" "text", "p_jeton_cas" "text", "p_confirmation" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_decision text := upper(btrim(COALESCE(p_decision, '')));
  v_motif text := left(btrim(COALESCE(p_motif, '')), 1000);
  v_confirmation jsonb := COALESCE(p_confirmation, '{}'::jsonb);
  v_revue public.file_revue_manuelle%ROWTYPE;
  v_decision_existante private.revue_manuelle_decisions%ROWTYPE;
  v_jeton text;
  v_etab public.etablissements%ROWTYPE;
  v_soignant public.soignants%ROWTYPE;
  v_doc_identite public.documents_soignants%ROWTYPE;
  v_donnees jsonb;
  v_officiel jsonb;
  v_version_origine bigint;
  v_version_attendue bigint;
  v_rib_key text;
  v_rib_sha256 text;
  v_rib_object_id uuid;
  v_rib_object_updated_at timestamptz;
  v_identite_object_id uuid;
  v_identite_object_updated_at timestamptz;
  v_identite_empreinte text;
  v_iban_normalise text;
  v_iban_last4 text;
  v_finess_candidat text;
  v_siret_candidat text;
  v_snapshot jsonb := '{}'::jsonb;
  v_rows integer;
BEGIN
  IF v_uid IS NULL
     OR NOT public.est_admin_valide() THEN
    RAISE EXCEPTION 'Administrateur autorise requis'
      USING ERRCODE = '42501';
  END IF;
  IF p_revue_id IS NULL
     OR v_decision NOT IN ('APPROUVER', 'REJETER')
     OR char_length(v_motif) < 10
     OR COALESCE(p_jeton_cas, '') !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_confirmation) <> 'object' THEN
    RAISE EXCEPTION 'Decision, motif et snapshot de revue invalides'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_revue
  FROM public.file_revue_manuelle
  WHERE id = p_revue_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Revue introuvable' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_decision_existante
  FROM private.revue_manuelle_decisions
  WHERE revue_id = p_revue_id;
  IF FOUND THEN
    IF v_decision_existante.decision = v_decision
       AND v_decision_existante.jeton_cas = p_jeton_cas THEN
      RETURN jsonb_build_object(
        'success', true,
        'idempotent', true,
        'decision', v_decision,
        'service', v_decision_existante.service
      );
    END IF;
    RAISE EXCEPTION 'Cette revue possede deja un verdict different'
      USING ERRCODE = '40001';
  END IF;

  IF v_revue.statut NOT IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE') THEN
    RAISE EXCEPTION 'Cette revue n est plus active; rechargez la file'
      USING ERRCODE = '40001';
  END IF;
  IF v_revue.expire_le IS NULL OR v_revue.expire_le < now() THEN
    RAISE EXCEPTION 'Le snapshot de revue a expire; relancez la verification source'
      USING ERRCODE = '40001';
  END IF;
  IF v_revue.service_en_echec NOT IN (
    'VERIFY_RIB_ETABLISSEMENT',
    'VERIFY_FINESS_RECOUPEMENT',
    'VERIFY_SIRET_IDENTITE_NON_CONCLUANTE'
  ) THEN
    RAISE EXCEPTION 'Cette preuve doit etre decidee dans son workflow specialise'
      USING ERRCODE = '22023';
  END IF;

  v_jeton := private.fn_jeton_cas_revue_manuelle(
    v_revue.id, v_revue.type_entite, v_revue.id_entite,
    v_revue.service_en_echec, v_revue.motif_echec,
    v_revue.donnees_originales, v_revue.statut, v_revue.priorite,
    v_revue.assigne_a, v_revue.revu_le, v_revue.resolu_le,
    v_revue.expire_le
  );
  IF v_jeton IS DISTINCT FROM p_jeton_cas THEN
    RAISE EXCEPTION 'La revue a change; rechargez avant de decider'
      USING ERRCODE = '40001';
  END IF;

  v_donnees := COALESCE(v_revue.donnees_originales, '{}'::jsonb);

  IF v_revue.service_en_echec = 'VERIFY_RIB_ETABLISSEMENT' THEN
    IF v_revue.type_entite <> 'ETABLISSEMENT' THEN
      RAISE EXCEPTION 'Type de ressource RIB incoherent' USING ERRCODE = '22023';
    END IF;
    v_version_origine := NULLIF(
      v_donnees ->> 'verification_source_version', ''
    )::bigint;
    v_version_attendue := NULLIF(
      v_donnees ->> 'verification_source_version_apres_verdict', ''
    )::bigint;
    v_rib_key := NULLIF(v_donnees ->> 'rib_s3_key', '');
    v_rib_sha256 := lower(NULLIF(v_donnees ->> 'rib_source_sha256_v1', ''));
    IF v_version_origine IS NULL
       OR v_version_attendue IS DISTINCT FROM v_version_origine + 1
       OR v_rib_key IS NULL
       OR v_rib_key NOT LIKE v_revue.id_entite::text || '/rib-etablissement-%'
       OR COALESCE(v_rib_sha256, '') !~ '^[0-9a-f]{64}$' THEN
      RAISE EXCEPTION 'Snapshot RIB incomplet; relancez la verification automatique'
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_etab
    FROM public.etablissements
    WHERE id = v_revue.id_entite AND supprime_le IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Etablissement introuvable' USING ERRCODE = 'P0002';
    END IF;
    IF v_etab.verification_source_version IS DISTINCT FROM v_version_attendue
       OR v_etab.rib_s3_key IS DISTINCT FROM v_rib_key
       OR v_etab.rib_ia_coherent IS NOT NULL THEN
      RAISE EXCEPTION 'Le RIB ou son verdict a change; rechargez la file'
        USING ERRCODE = '40001';
    END IF;

    -- L'objet exact doit encore exister pendant toute la transaction de
    -- decision. On verrouille d'abord l'etablissement (ordre commun aux flux
    -- de remplacement), puis l'objet Storage afin d'eviter un interblocage.
    SELECT o.id, o.updated_at
    INTO v_rib_object_id, v_rib_object_updated_at
    FROM storage.objects o
    WHERE o.bucket_id = 'jolene-documents'
      AND o.name = v_rib_key
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Le fichier RIB source n existe plus; relancez la verification automatique'
        USING ERRCODE = '22023';
    END IF;

    v_iban_normalise := upper(regexp_replace(
      COALESCE(v_confirmation ->> 'iban', ''),
      '[^A-Za-z0-9]',
      '',
      'g'
    ));
    v_iban_last4 := right(v_iban_normalise, 4);
    IF v_decision = 'APPROUVER'
       AND NOT public.fn_iban_est_valide(v_iban_normalise) THEN
      RAISE EXCEPTION 'L IBAN complet lu sur le RIB est requis avec un checksum ISO 13616 valide'
        USING ERRCODE = '22023';
    END IF;
    IF v_decision = 'APPROUVER'
       AND NULLIF(upper(v_donnees ->> 'iban_last4'), '') IS NOT NULL
       AND upper(v_donnees ->> 'iban_last4') IS DISTINCT FROM v_iban_last4 THEN
      RAISE EXCEPTION 'Le suffixe IBAN saisi contredit le snapshot de verification'
        USING ERRCODE = '22023';
    END IF;
    IF v_decision = 'APPROUVER'
       AND NULLIF(v_donnees ->> 'iban_fingerprint_sha256_v1', '') IS NOT NULL
       AND encode(
         extensions.digest(
           convert_to(
             v_revue.id_entite::text || '|'
               || v_version_origine::text || '|'
               || v_rib_key || '|' || v_iban_normalise,
             'UTF8'
           ),
           'sha256'
         ),
         'hex'
       ) IS DISTINCT FROM v_donnees ->> 'iban_fingerprint_sha256_v1' THEN
      RAISE EXCEPTION 'L IBAN saisi ne correspond pas a celui extrait dans le snapshot'
        USING ERRCODE = '22023';
    END IF;

    v_snapshot := jsonb_build_object(
      'verification_source_version', v_etab.verification_source_version,
      'verification_source_version_origine', v_version_origine,
      'rib_s3_key', v_rib_key,
      'rib_source_sha256_v1', v_rib_sha256,
      'storage_object_id', v_rib_object_id,
      'storage_object_updated_at', v_rib_object_updated_at,
      'iban_last4', CASE WHEN v_decision = 'APPROUVER' THEN v_iban_last4 ELSE NULL END,
      'ancien_verdict', v_etab.rib_ia_resultat ->> 'verdict_final'
    );
    UPDATE public.etablissements
    SET rib_ia_resultat = (
          COALESCE(rib_ia_resultat, '{}'::jsonb)
            - 'iban' - 'iban_extrait' - 'raw_text'
        ) || jsonb_build_object(
          'verdict_final', CASE WHEN v_decision = 'APPROUVER' THEN 'VERIFIE' ELSE 'REJETE' END,
          'motif_serveur', v_motif,
          'revue_manuelle_requise', false,
          'source_validation', 'ADMIN_REVUE_MANUELLE',
          'revue_admin_le', now()
        ),
        rib_ia_coherent = v_decision = 'APPROUVER',
        rib_ia_verifie_le = now(),
        iban_last4 = CASE WHEN v_decision = 'APPROUVER' THEN v_iban_last4 ELSE NULL END,
        rib_verifie_s3_key = CASE WHEN v_decision = 'APPROUVER' THEN v_rib_key ELSE NULL END,
        rib_verifie_source_version = CASE
          WHEN v_decision = 'APPROUVER' THEN v_version_attendue + 1
          ELSE NULL
        END,
        modifie_le = now()
    WHERE id = v_revue.id_entite
      AND verification_source_version = v_version_attendue
      AND rib_s3_key = v_rib_key
      AND rib_ia_coherent IS NULL;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Decision RIB concurrente detectee' USING ERRCODE = '40001';
    END IF;

  ELSIF v_revue.service_en_echec = 'VERIFY_FINESS_RECOUPEMENT' THEN
    IF v_revue.type_entite <> 'ETABLISSEMENT' THEN
      RAISE EXCEPTION 'Type de ressource FINESS incoherent' USING ERRCODE = '22023';
    END IF;
    v_version_attendue := NULLIF(v_donnees ->> 'verification_source_version', '')::bigint;
    v_finess_candidat := NULLIF(v_donnees ->> 'finess_candidat', '');
    v_officiel := COALESCE(v_donnees -> 'donnees_officielles_candidat', '{}'::jsonb);
    IF v_version_attendue IS NULL
       OR COALESCE(v_finess_candidat, '') !~ '^[0-9]{9}$'
       OR jsonb_typeof(v_officiel) <> 'object'
       OR COALESCE((v_officiel ->> 'actif')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Snapshot FINESS officiel incomplet ou inactif'
        USING ERRCODE = '22023';
    END IF;
    IF v_decision = 'APPROUVER'
       AND NULLIF(btrim(v_officiel ->> 'raison_sociale'), '') IS NULL THEN
      RAISE EXCEPTION 'La raison sociale FINESS officielle est requise pour approuver'
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_etab
    FROM public.etablissements
    WHERE id = v_revue.id_entite AND supprime_le IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Etablissement introuvable' USING ERRCODE = 'P0002';
    END IF;
    IF v_etab.verification_source_version IS DISTINCT FROM v_version_attendue
       OR v_etab.finess IS DISTINCT FROM NULLIF(v_donnees ->> 'finess_canonique_avant', '')
       OR v_etab.siret IS DISTINCT FROM NULLIF(v_donnees ->> 'siret_profil', '')
       OR v_etab.siret_verifie IS DISTINCT FROM (v_donnees ->> 'siret_profil_verifie')::boolean THEN
      RAISE EXCEPTION 'Le dossier FINESS a change; rechargez la file'
        USING ERRCODE = '40001';
    END IF;

    v_snapshot := jsonb_build_object(
      'verification_source_version', v_etab.verification_source_version,
      'finess_canonique_avant', v_etab.finess,
      'finess_candidat', v_finess_candidat,
      'donnees_officielles_candidat', v_officiel,
      'recoupement', v_donnees -> 'recoupement'
    );
    v_rows := 0;
    IF v_decision = 'APPROUVER' THEN
      IF v_etab.finess IS DISTINCT FROM v_finess_candidat THEN
        UPDATE public.etablissements
        SET finess = v_finess_candidat,
            modifie_le = now()
        WHERE id = v_revue.id_entite;
      END IF;
      UPDATE public.etablissements
      SET finess_verifie = true,
          finess_verifie_le = now(),
          finess_raison_sociale = NULLIF(v_officiel ->> 'raison_sociale', ''),
          finess_categorie = NULLIF(v_officiel ->> 'categorie_label', ''),
          finess_secteur = NULLIF(v_officiel ->> 'secteur_label', ''),
          finess_est_public = CASE
            WHEN v_officiel ? 'est_public' THEN (v_officiel ->> 'est_public')::boolean
            ELSE NULL
          END,
          modifie_le = now()
      WHERE id = v_revue.id_entite;
      PERFORM public.fn_evaluer_rattachement_etablissement(v_revue.id_entite);
    ELSIF v_etab.finess IS NOT DISTINCT FROM v_finess_candidat THEN
      -- Un rejet du FINESS actuellement canonique révoque réellement cette
      -- preuve. Le numéro déclaré reste visible pour correction, mais aucun
      -- statut vérifié ni droit de publication ne survit au verdict humain.
      UPDATE public.etablissements
      SET finess_verifie = false,
          finess_verifie_le = NULL,
          finess_raison_sociale = NULL,
          finess_categorie = NULL,
          finess_secteur = NULL,
          finess_est_public = NULL,
          statut_verification = 'EN_COURS',
          peut_publier_missions = false,
          verifie_le = NULL,
          verifie_par = NULL,
          motif_rejet = left('FINESS rejete en revue manuelle : ' || v_motif, 1000),
          modifie_le = now()
      WHERE id = v_revue.id_entite
        AND verification_source_version = v_version_attendue;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'Decision FINESS concurrente detectee' USING ERRCODE = '40001';
      END IF;
    END IF;

  ELSE
    IF v_revue.type_entite <> 'SOIGNANT' THEN
      RAISE EXCEPTION 'Type de ressource SIRET incoherent' USING ERRCODE = '22023';
    END IF;
    v_siret_candidat := NULLIF(v_donnees ->> 'siret_candidat', '');
    IF COALESCE(v_siret_candidat, '') !~ '^[0-9]{14}$'
       OR v_siret_candidat ~ '^0+$'
       OR NULLIF(v_donnees ->> 'profil_modifie_le', '') IS NULL
       OR COALESCE((v_donnees ->> 'siret_officiel_actif')::boolean, false) IS NOT TRUE
       OR COALESCE((v_donnees ->> 'activite_officielle_sante')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Snapshot SIRET officiel incomplet ou inactif'
        USING ERRCODE = '22023';
    END IF;
    IF v_decision = 'APPROUVER'
       AND NULLIF(btrim(v_donnees ->> 'raison_sociale_officielle'), '') IS NULL THEN
      RAISE EXCEPTION 'La raison sociale SIRET officielle est requise pour approuver'
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_soignant
    FROM public.soignants
    WHERE id = v_revue.id_entite AND supprime_le IS NULL
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Soignant introuvable' USING ERRCODE = 'P0002';
    END IF;
    IF v_soignant.modifie_le IS DISTINCT FROM (v_donnees ->> 'profil_modifie_le')::timestamptz
       OR v_soignant.prenom IS DISTINCT FROM v_donnees ->> 'prenom_declare'
       OR v_soignant.nom IS DISTINCT FROM v_donnees ->> 'nom_declare'
       OR v_soignant.date_naissance IS DISTINCT FROM (v_donnees ->> 'date_naissance_declaree')::date
       OR v_soignant.siret_liberal IS DISTINCT FROM NULLIF(v_donnees ->> 'siret_canonique_avant', '')
       OR v_soignant.statut_liberal IS DISTINCT FROM NULLIF(v_donnees ->> 'statut_liberal', '')
       OR v_soignant.type_contrat::text IS DISTINCT FROM NULLIF(v_donnees ->> 'type_contrat', '') THEN
      RAISE EXCEPTION 'Le profil liberal a change; rechargez la file'
        USING ERRCODE = '40001';
    END IF;

    IF v_decision = 'APPROUVER' THEN
      IF v_soignant.identite_verifiee IS NOT TRUE
         OR v_soignant.coherence_identite IS DISTINCT FROM 'COHERENT' THEN
        RAISE EXCEPTION 'Une identite courante coherente est requise avant approbation SIRET'
          USING ERRCODE = '22023';
      END IF;

      SELECT * INTO v_doc_identite
      FROM public.documents_soignants d
      WHERE d.soignant_id = v_soignant.id
        AND d.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
        AND d.statut_verification = 'VERIFIE'
        AND d.supprime_le IS NULL
        AND d.revoque_le IS NULL
        AND d.verifie_le IS NOT NULL
        AND d.valide_jusqua IS NOT NULL
        AND d.valide_jusqua > current_date
        AND d.coherence_nom IS TRUE
        AND d.resultat_ia ->> 'verdict_serveur' = 'VERIFIE'
        AND d.resultat_ia ->> 'date_naissance_extraite' = v_soignant.date_naissance::text
        AND d.s3_bucket = 'jolene-documents'
        AND d.s3_cle LIKE v_soignant.id::text || '/%'
        AND public.fn_noms_personne_correspondent(
          v_soignant.nom,
          v_soignant.prenom,
          d.nom_extrait_ia,
          d.prenom_extrait_ia
        )
      ORDER BY d.verifie_le DESC, d.modifie_le DESC, d.id
      LIMIT 1
      FOR SHARE;

      IF NOT FOUND
         OR v_soignant.coherence_details ->> 'document_id'
              IS DISTINCT FROM v_doc_identite.id::text THEN
        RAISE EXCEPTION 'Une piece d identite precise, concordante et non expiree est requise avant approbation SIRET'
          USING ERRCODE = '22023';
      END IF;

      -- Le document logique ne suffit pas : la ligne de metadonnees de l'objet
      -- exact doit toujours exister. Ce verrou partage ferme la course avec un
      -- remplacement/suppression Storage pendant le verdict humain.
      SELECT o.id, o.updated_at
      INTO v_identite_object_id, v_identite_object_updated_at
      FROM storage.objects o
      WHERE o.bucket_id = v_doc_identite.s3_bucket
        AND o.name = v_doc_identite.s3_cle
      FOR SHARE;
      IF NOT FOUND OR v_identite_object_updated_at IS NULL THEN
        RAISE EXCEPTION 'Le fichier d identite source n existe plus; televersez puis verifiez une nouvelle piece'
          USING ERRCODE = '22023';
      END IF;

      v_identite_empreinte := private.fn_empreinte_preuve_identite_siret(
        v_doc_identite
      );
    END IF;

    v_snapshot := jsonb_build_object(
      'profil_modifie_le', v_soignant.modifie_le,
      'siret_canonique_avant', v_soignant.siret_liberal,
      'siret_candidat', v_siret_candidat,
      'siret_last4', right(v_siret_candidat, 4),
      'raison_sociale_officielle', v_donnees ->> 'raison_sociale_officielle',
      'preuve_identite_document_id', v_doc_identite.id,
      'preuve_identite_s3_bucket', v_doc_identite.s3_bucket,
      'preuve_identite_s3_cle', v_doc_identite.s3_cle,
      'preuve_identite_s3_version_id', v_doc_identite.s3_version_id,
      'preuve_identite_modifie_le', v_doc_identite.modifie_le,
      'preuve_identite_verifie_le', v_doc_identite.verifie_le,
      'preuve_identite_valide_jusqua', v_doc_identite.valide_jusqua,
      'preuve_identite_storage_object_id', v_identite_object_id,
      'preuve_identite_storage_updated_at', v_identite_object_updated_at,
      'preuve_identite_source_sha256_v1', v_identite_empreinte
    );
    v_rows := 0;
    IF v_decision = 'APPROUVER' THEN
      IF (v_soignant.statut_liberal = 'ACTIF' OR v_soignant.type_contrat::text = 'LIBERAL')
         AND v_soignant.siret_liberal IS NOT NULL
         AND v_soignant.siret_liberal IS DISTINCT FROM v_siret_candidat THEN
        RAISE EXCEPTION 'Le SIRET d un exercice liberal actif ne peut pas etre remplace ici'
          USING ERRCODE = '22023';
      END IF;
      UPDATE public.soignants
      SET siret_liberal = v_siret_candidat,
          statut_liberal = CASE WHEN statut_liberal = 'ACTIF' THEN 'ACTIF' ELSE 'EN_COURS' END,
          siret_liberal_verifie = true,
          siret_liberal_verifie_le = now(),
          siret_liberal_raison_sociale = NULLIF(v_donnees ->> 'raison_sociale_officielle', ''),
          siret_liberal_coherence_identite = true,
          siret_liberal_source_verification = 'REVUE_MANUELLE_IDENTITE',
          siret_liberal_preuve_siret = v_siret_candidat,
          siret_liberal_preuve_identite_document_id = v_doc_identite.id,
          siret_liberal_preuve_identite_document_modifie_le = v_doc_identite.modifie_le,
          siret_liberal_preuve_identite_s3_bucket = v_doc_identite.s3_bucket,
          siret_liberal_preuve_identite_s3_cle = v_doc_identite.s3_cle,
          siret_liberal_preuve_identite_s3_version_id = v_doc_identite.s3_version_id,
          siret_liberal_preuve_identite_storage_object_id = v_identite_object_id,
          siret_liberal_preuve_identite_storage_updated_at = v_identite_object_updated_at,
          siret_liberal_preuve_identite_valide_jusqua = v_doc_identite.valide_jusqua,
          siret_liberal_preuve_identite_empreinte_sha256 = v_identite_empreinte,
          modifie_le = now()
      WHERE id = v_revue.id_entite
        AND modifie_le = v_soignant.modifie_le;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
    ELSIF v_soignant.siret_liberal IS NOT DISTINCT FROM v_siret_candidat THEN
      UPDATE public.soignants
      SET siret_liberal_verifie = false,
          siret_liberal_verifie_le = NULL,
          siret_liberal_raison_sociale = NULL,
          siret_liberal_coherence_identite = false,
          siret_liberal_source_verification = NULL,
          siret_liberal_preuve_siret = NULL,
          siret_liberal_preuve_identite_document_id = NULL,
          siret_liberal_preuve_identite_document_modifie_le = NULL,
          siret_liberal_preuve_identite_s3_bucket = NULL,
          siret_liberal_preuve_identite_s3_cle = NULL,
          siret_liberal_preuve_identite_s3_version_id = NULL,
          siret_liberal_preuve_identite_storage_object_id = NULL,
          siret_liberal_preuve_identite_storage_updated_at = NULL,
          siret_liberal_preuve_identite_valide_jusqua = NULL,
          siret_liberal_preuve_identite_empreinte_sha256 = NULL,
          tous_documents_valides = false,
          modifie_le = now()
      WHERE id = v_revue.id_entite
        AND modifie_le = v_soignant.modifie_le;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
    END IF;
    IF v_rows <> 1 AND (
      v_decision = 'APPROUVER'
      OR v_soignant.siret_liberal IS NOT DISTINCT FROM v_siret_candidat
    ) THEN
      RAISE EXCEPTION 'Decision SIRET concurrente detectee' USING ERRCODE = '40001';
    END IF;
    PERFORM public.fn_calculer_tous_documents_valides(v_revue.id_entite);
  END IF;

  INSERT INTO private.revue_manuelle_decisions (
    revue_id, decision, motif, acteur_id, service, type_entite,
    id_entite, jeton_cas, source_snapshot
  ) VALUES (
    v_revue.id, v_decision, v_motif, v_uid, v_revue.service_en_echec,
    v_revue.type_entite, v_revue.id_entite, v_jeton, v_snapshot
  );

  UPDATE public.file_revue_manuelle
  SET statut = 'RESOLU_MANUELLEMENT',
      assigne_a = v_uid,
      notes_resolution = left(
        CASE WHEN v_decision = 'APPROUVER' THEN 'Approuve : ' ELSE 'Rejete : ' END
          || v_motif,
        1000
      ),
      revu_le = COALESCE(revu_le, now()),
      resolu_le = now()
  WHERE id = v_revue.id
    AND statut = v_revue.statut;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Transition de revue concurrente detectee' USING ERRCODE = '40001';
  END IF;

  -- ADMIN_ACTION appartient a l'allowlist journaux_audit. L'ecriture directe
  -- est volontairement bloquante : un verdict sans audit est annule.
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'file_revue_manuelle',
    v_revue.id,
    CASE
      WHEN v_revue.service_en_echec = 'VERIFY_RIB_ETABLISSEMENT' THEN v_rib_key
      ELSE NULL
    END,
    jsonb_build_object(
      'sous_action', 'DECISION_REVUE_MANUELLE',
      'decision', v_decision,
      'service', v_revue.service_en_echec,
      'type_entite', v_revue.type_entite,
      'id_entite', v_revue.id_entite,
      'motif', v_motif,
      'source_snapshot', v_snapshot
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'idempotent', false,
    'decision', v_decision,
    'service', v_revue.service_en_echec
  );
END;
$_$;


ALTER FUNCTION "public"."fn_admin_decider_revue_manuelle"("p_revue_id" "uuid", "p_decision" "text", "p_motif" "text", "p_jeton_cas" "text", "p_confirmation" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_degeler_escrow_etablissement"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'ADMIN_REQUIS');
  END IF;

  UPDATE escrow_etablissement_etat
  SET gele = false, gele_le = NULL, gele_raison = NULL, modifie_le = now()
  WHERE etablissement_id = p_etablissement_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ETAB_INCONNU_OU_NON_GELE');
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    auth.uid(), 'ADMIN',
    'ESCROW_ETAB_DEGELE', 'etablissement', p_etablissement_id,
    NULL, '{}'::jsonb, NULL, 'fn_admin_degeler_escrow_etablissement'
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


