CREATE OR REPLACE FUNCTION "public"."fn_admin_lister_reclamations"("p_statut" "text" DEFAULT 'PENDING'::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_uid IS NULL OR NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'evenement_type', r.evenement_type,
    'evenement_id', COALESCE(r.evenement_soignant_id, r.evenement_etab_id),
    'event_type_evenement',
      COALESCE((SELECT type_evenement FROM public.evenements_score_soignant WHERE id = r.evenement_soignant_id),
                (SELECT type_evenement FROM public.evenements_score_etab WHERE id = r.evenement_etab_id)),
    'event_points',
      COALESCE((SELECT points FROM public.evenements_score_soignant WHERE id = r.evenement_soignant_id),
                (SELECT points FROM public.evenements_score_etab WHERE id = r.evenement_etab_id)),
    'event_motif',
      COALESCE((SELECT motif FROM public.evenements_score_soignant WHERE id = r.evenement_soignant_id),
                (SELECT motif FROM public.evenements_score_etab WHERE id = r.evenement_etab_id)),
    'event_cree_le',
      COALESCE((SELECT cree_le FROM public.evenements_score_soignant WHERE id = r.evenement_soignant_id),
                (SELECT cree_le FROM public.evenements_score_etab WHERE id = r.evenement_etab_id)),
    'contesteur_id', r.contesteur_id,
    'motif_categorie', r.motif_categorie,
    'texte_libre', r.texte_libre,
    'justificatif_storage_path', r.justificatif_storage_path,
    'statut', r.statut,
    'decision_admin', r.decision_admin,
    'motif_admin', r.motif_admin,
    'cree_le', r.cree_le,
    'jours_attente', EXTRACT(EPOCH FROM (NOW() - r.cree_le)) / 86400
  ) ORDER BY r.cree_le ASC), '[]'::jsonb) INTO v_result
  FROM public.reclamations_score r
  WHERE (p_statut IS NULL OR p_statut = 'TOUS' OR r.statut = p_statut)
  LIMIT p_limit;

  RETURN jsonb_build_object('success', true, 'reclamations', v_result);
END;
$$;


ALTER FUNCTION "public"."fn_admin_lister_reclamations"("p_statut" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_lister_revues_manuelles"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions'
    AS $$
DECLARE
  v_resultat jsonb;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.est_admin_valide() THEN
    RAISE EXCEPTION 'Administrateur autorise requis'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(file) ORDER BY file.priorite DESC,
                                                file.cree_le ASC), '[]'::jsonb)
    INTO v_resultat
  FROM (
    SELECT
      f.id,
      f.type_entite,
      f.id_entite,
      f.service_en_echec,
      f.motif_echec,
      f.statut,
      f.priorite,
      f.cree_le,
      f.expire_le,
      CASE
        WHEN f.type_entite = 'ETABLISSEMENT' THEN COALESCE(e.est_compte_test, false)
        WHEN f.type_entite = 'SOIGNANT' THEN COALESCE(s.est_compte_test, false)
        WHEN f.type_entite = 'TELEVERSEMENT_DOCUMENT' THEN COALESCE(sd.est_compte_test, false)
        ELSE false
      END AS est_compte_test,
      f.service_en_echec IN (
        'VERIFY_RIB_ETABLISSEMENT',
        'VERIFY_FINESS_RECOUPEMENT',
        'VERIFY_SIRET_IDENTITE_NON_CONCLUANTE'
      ) AS decision_directe,
      CASE
        WHEN f.type_entite = 'ETABLISSEMENT' THEN COALESCE(e.nom, 'Etablissement')
        WHEN f.type_entite = 'SOIGNANT' THEN btrim(COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, ''))
        WHEN f.type_entite = 'TELEVERSEMENT_DOCUMENT' THEN
          btrim(COALESCE(sd.prenom, '') || ' ' || COALESCE(sd.nom, ''))
        ELSE f.type_entite || ' ' || f.id_entite::text
      END AS ressource_libelle,
      CASE
        WHEN f.service_en_echec ILIKE '%HEURES%'
          THEN '/admin/heures-externes'
        WHEN f.type_entite = 'ETABLISSEMENT'
          THEN '/admin/verification-etablissements'
        WHEN f.type_entite = 'SOIGNANT'
          THEN '/admin/utilisateurs/' || f.id_entite::text
        WHEN f.type_entite = 'TELEVERSEMENT_DOCUMENT'
          THEN '/admin/moderation?onglet=documents'
        ELSE '/admin/moderation'
      END AS route_ressource,
      CASE
        WHEN f.service_en_echec IN (
          'VERIFY_RIB_ETABLISSEMENT',
          'VERIFY_PIECE_IDENTITE_ETAB',
          'VERIFY_JUSTIFICATIF_FONCTION'
        ) THEN 'jolene-documents'
        WHEN f.type_entite = 'TELEVERSEMENT_DOCUMENT' THEN d.s3_bucket
        ELSE NULL
      END AS preuve_bucket,
      CASE
        WHEN f.service_en_echec = 'VERIFY_RIB_ETABLISSEMENT' THEN e.rib_s3_key
        WHEN f.service_en_echec = 'VERIFY_PIECE_IDENTITE_ETAB'
          THEN e.representant_piece_s3_key
        WHEN f.service_en_echec = 'VERIFY_JUSTIFICATIF_FONCTION'
          THEN e.justificatif_fonction_s3_key
        WHEN f.type_entite = 'TELEVERSEMENT_DOCUMENT' THEN d.s3_cle
        ELSE NULL
      END AS preuve_path,
      CASE
        WHEN f.service_en_echec = 'VERIFY_RIB_ETABLISSEMENT' THEN 'RIB'
        WHEN f.service_en_echec = 'VERIFY_PIECE_IDENTITE_ETAB' THEN 'Identite du representant'
        WHEN f.service_en_echec = 'VERIFY_JUSTIFICATIF_FONCTION' THEN 'Justificatif de fonction'
        WHEN f.type_entite = 'TELEVERSEMENT_DOCUMENT' THEN d.type_document::text
        ELSE NULL
      END AS preuve_type,
      jsonb_strip_nulls(jsonb_build_object(
        'etablissement_nom', e.nom,
        'etablissement_siret', e.siret,
        'etablissement_finess', e.finess,
        'etablissement_version', e.verification_source_version,
        'rib_iban_last4', e.iban_last4,
        'soignant_prenom', s.prenom,
        'soignant_nom', s.nom,
        'soignant_profession', s.profession::text,
        'document_type', d.type_document::text,
        'donnees_revue', CASE
          WHEN f.service_en_echec = 'VERIFY_RIB_ETABLISSEMENT' THEN
            jsonb_strip_nulls(jsonb_build_object(
              'cause', f.donnees_originales ->> 'cause',
              'verification_source_version',
                f.donnees_originales ->> 'verification_source_version',
              'rib_source_sha256_v1',
                f.donnees_originales ->> 'rib_source_sha256_v1',
              'iban_last4', f.donnees_originales ->> 'iban_last4'
            ))
          WHEN f.service_en_echec = 'VERIFY_FINESS_RECOUPEMENT' THEN
            jsonb_strip_nulls(jsonb_build_object(
              'code', f.donnees_originales ->> 'code',
              'finess_candidat', f.donnees_originales ->> 'finess_candidat',
              'siret_profil', f.donnees_originales ->> 'siret_profil',
              'donnees_officielles_candidat',
                f.donnees_originales -> 'donnees_officielles_candidat',
              'recoupement', f.donnees_originales -> 'recoupement'
            ))
          WHEN f.service_en_echec = 'VERIFY_SIRET_IDENTITE_NON_CONCLUANTE' THEN
            jsonb_strip_nulls(jsonb_build_object(
              'siret_candidat', f.donnees_originales ->> 'siret_candidat',
              'raison_sociale_officielle',
                f.donnees_originales ->> 'raison_sociale_officielle',
              'code_naf_officiel', f.donnees_originales ->> 'code_naf_officiel',
              'source_officielle', f.donnees_originales ->> 'source_officielle'
            ))
          ELSE jsonb_strip_nulls(jsonb_build_object(
            'code', f.donnees_originales ->> 'code',
            'cause', f.donnees_originales ->> 'cause'
          ))
        END
      )) AS contexte,
      private.fn_jeton_cas_revue_manuelle(
        f.id, f.type_entite, f.id_entite, f.service_en_echec,
        f.motif_echec, f.donnees_originales, f.statut, f.priorite,
        f.assigne_a, f.revu_le, f.resolu_le, f.expire_le
      ) AS jeton_cas
    FROM public.file_revue_manuelle f
    LEFT JOIN public.etablissements e
      ON f.type_entite = 'ETABLISSEMENT' AND e.id = f.id_entite
    LEFT JOIN public.soignants s
      ON f.type_entite = 'SOIGNANT' AND s.id = f.id_entite
    LEFT JOIN public.documents_soignants d
      ON f.type_entite = 'TELEVERSEMENT_DOCUMENT' AND d.id = f.id_entite
    LEFT JOIN public.soignants sd ON sd.id = d.soignant_id
    WHERE f.statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE')
    ORDER BY f.priorite DESC, f.cree_le ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 100), 500))
  ) AS file;

  RETURN jsonb_build_object('success', true, 'revues', v_resultat);
END;
$$;


ALTER FUNCTION "public"."fn_admin_lister_revues_manuelles"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_lister_signalements"("p_statut" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "signaleur_id" "uuid", "signaleur_type" "text", "signaleur_nom" "text", "cible_id" "uuid", "cible_type" "text", "cible_nom" "text", "categorie" "text", "motif" "text", "mission_id" "uuid", "statut" "text", "resolution" "text", "traite_le" timestamp with time zone, "cree_le" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    s.id, s.signaleur_id, s.signaleur_type,
    CASE WHEN s.signaleur_type = 'SOIGNANT'
      THEN (SELECT trim(coalesce(so.prenom,'') || ' ' || coalesce(so.nom,'')) FROM soignants so WHERE so.id = s.signaleur_id)
      ELSE (SELECT et.nom FROM etablissements et WHERE et.id = s.signaleur_id)
    END AS signaleur_nom,
    s.cible_id, s.cible_type,
    CASE WHEN s.cible_type = 'SOIGNANT'
      THEN (SELECT trim(coalesce(so.prenom,'') || ' ' || coalesce(so.nom,'')) FROM soignants so WHERE so.id = s.cible_id)
      ELSE (SELECT et.nom FROM etablissements et WHERE et.id = s.cible_id)
    END AS cible_nom,
    s.categorie, s.motif, s.mission_id, s.statut, s.resolution, s.traite_le, s.cree_le
  FROM public.signalements s
  WHERE public.est_admin()
    AND (p_statut IS NULL OR s.statut = p_statut)
  ORDER BY CASE s.statut WHEN 'OUVERT' THEN 0 WHEN 'EN_COURS' THEN 1 ELSE 2 END, s.cree_le DESC;
$$;


ALTER FUNCTION "public"."fn_admin_lister_signalements"("p_statut" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_lister_taux_commission"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'groupes', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'nom', nom, 'siren', siren,
        'taux_commission_negocie', taux_commission_negocie,
        'contrat_debut', contrat_debut, 'contrat_fin', contrat_fin,
        'nb_etablissements', (SELECT count(*) FROM etablissements e WHERE e.groupe_sante_id = g.id)
      ) ORDER BY nom), '[]'::jsonb)
      FROM groupes_sante g WHERE supprime_le IS NULL
    ),
    'etablissements', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', e.id, 'nom', e.nom, 'siret', e.siret,
        'taux_commission_negocie', e.taux_commission_negocie,
        'groupe_id', e.groupe_sante_id, 'groupe_nom', g.nom,
        'taux_groupe', g.taux_commission_negocie,
        'taux_resolu', COALESCE(e.taux_commission_negocie, g.taux_commission_negocie, 15),
        'taux_resolu_source', CASE
          WHEN e.taux_commission_negocie IS NOT NULL THEN 'etablissement'
          WHEN g.taux_commission_negocie IS NOT NULL THEN 'groupe'
          ELSE 'defaut_15' END
      ) ORDER BY e.nom), '[]'::jsonb)
      FROM etablissements e
      LEFT JOIN groupes_sante g ON g.id = e.groupe_sante_id
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_lister_taux_commission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_lister_templates_contrats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_templates jsonb;
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', t.id,
    'nom', t.nom,
    'type_contrat', t.type_contrat,
    'version', t.version,
    'est_actif', t.est_actif,
    'variables', t.variables,
    'contenu_taille', length(t.contenu_html),
    'cree_le', t.cree_le,
    'modifie_le', t.modifie_le
  ) ORDER BY t.type_contrat, t.version DESC, t.nom), '[]'::jsonb)
  INTO v_templates
  FROM public.templates_contrat t;

  RETURN jsonb_build_object('success', true, 'templates', v_templates);
END;
$$;


ALTER FUNCTION "public"."fn_admin_lister_templates_contrats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_maj_parametre"("p_cle" "text", "p_valeur" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v public.parametres_systeme;
BEGIN
  IF NOT public.est_admin() THEN RAISE EXCEPTION 'Accès admin requis'; END IF;
  SELECT * INTO v FROM public.parametres_systeme WHERE cle = p_cle;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Paramètre inconnu'); END IF;
  IF v.val_min IS NOT NULL AND p_valeur < v.val_min THEN
    RETURN jsonb_build_object('success', false, 'error', 'Valeur sous le minimum (' || v.val_min || ')'); END IF;
  IF v.val_max IS NOT NULL AND p_valeur > v.val_max THEN
    RETURN jsonb_build_object('success', false, 'error', 'Valeur au-dessus du maximum (' || v.val_max || ')'); END IF;
  UPDATE public.parametres_systeme SET valeur = p_valeur, maj_le = now() WHERE cle = p_cle;
  RETURN jsonb_build_object('success', true);
END; $$;


ALTER FUNCTION "public"."fn_admin_maj_parametre"("p_cle" "text", "p_valeur" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_mandats_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NOT est_admin() THEN RETURN '{"error":"Accès refusé"}'::JSONB; END IF;
    RETURN jsonb_build_object(
        'total_soignants', (SELECT COUNT(*) FROM soignants WHERE supprime_le IS NULL),
        'mandat_signe', (SELECT COUNT(*) FROM soignants WHERE supprime_le IS NULL AND mandat_facturation_signe = TRUE),
        'mandat_non_signe', (SELECT COUNT(*) FROM soignants WHERE supprime_le IS NULL AND COALESCE(mandat_facturation_signe, FALSE) = FALSE),
        'total_factures_honoraires', (SELECT COUNT(*) FROM factures_honoraires),
        'montant_factures_honoraires_total', (SELECT COALESCE(SUM(montant_ttc), 0) FROM factures_honoraires),
        'montant_factures_honoraires_impayees', (SELECT COALESCE(SUM(montant_ttc), 0) FROM factures_honoraires WHERE statut IN ('EMISE','EN_RETARD'))
    );
END;
$$;


ALTER FUNCTION "public"."fn_admin_mandats_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_marquer_absence_sans_prevenir"("p_mission_id" "uuid", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_uid UUID := auth.uid(); v_mission RECORD;
BEGIN
  IF NOT est_admin() THEN RETURN jsonb_build_object('success', false, 'error', 'Accès admin uniquement'); END IF;

  SELECT id, statut, soignant_assigne_id INTO v_mission FROM missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable'); END IF;
  IF v_mission.statut <> 'ABSENCE' THEN RETURN jsonb_build_object('success', false, 'error', 'Mission doit être en statut ABSENCE'); END IF;

  UPDATE missions SET absence_sans_prevenir = true, modifie_le = NOW() WHERE id = p_mission_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid, p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'ADMIN_ACTION', p_type_ressource := 'mission', p_id_ressource := p_mission_id,
    p_details := jsonb_build_object('action', 'absence_sans_prevenir_marquee', 'motif', p_motif, 'soignant_id', v_mission.soignant_assigne_id)
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_marquer_absence_sans_prevenir"("p_mission_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_marquer_facture_en_retard"("p_facture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_ancien_statut text;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  SELECT statut INTO v_ancien_statut FROM public.factures WHERE id = p_facture_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Facture introuvable');
  END IF;

  UPDATE public.factures SET statut = 'EN_RETARD' WHERE id = p_facture_id;

  PERFORM fn_ecrire_audit_safe(
    v_actor, 'ADMIN_PLATEFORME',
    'FACTURE_MARQUEE_EN_RETARD', 'facture', p_facture_id,
    NULL,
    jsonb_build_object('ancien_statut', v_ancien_statut, 'nouveau_statut', 'EN_RETARD'),
    NULL, NULL
  );

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_marquer_facture_en_retard"("p_facture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_masquer_notation"("p_notation_id" "uuid", "p_raison" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_notation RECORD;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seul l''administrateur peut masquer une notation');
  END IF;

  IF p_raison IS NULL OR LENGTH(TRIM(p_raison)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Raison requise (min 10 caractères)');
  END IF;

  SELECT * INTO v_notation FROM notations_missions WHERE id = p_notation_id;
  IF v_notation IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Notation introuvable');
  END IF;

  UPDATE notations_missions SET
    masque = true, masque_par = v_uid, masque_le = NOW(), mis_a_jour_le = NOW()
  WHERE id = p_notation_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'NOTATION_MASQUEE',
    p_type_ressource := 'notation',
    p_id_ressource := p_notation_id,
    p_details := jsonb_build_object('raison', p_raison, 'mission_id', v_notation.mission_id)
  );

  -- Recalculer le score de la cible (notation masquée sort du calcul)
  IF v_notation.sens = 'ETAB_VERS_SOIGNANT' THEN
    PERFORM public.fn_calculer_score_fiabilite_v2(v_notation.note_id, 'notation_masquee');
  ELSIF v_notation.sens = 'SOIGNANT_VERS_ETAB' THEN
    PERFORM public.fn_calculer_score_etablissement(v_notation.note_id);
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_masquer_notation"("p_notation_id" "uuid", "p_raison" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_mes_acces"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse au lancement' USING ERRCODE = '42501';
  END IF;

  -- Tant que les controles serveur ne sont pas delegues groupe par groupe,
  -- tout compte autorise est necessairement un administrateur complet.
  RETURN jsonb_build_object(
    'acces_total', true,
    'groupes', '[]'::jsonb,
    'actif', true,
    'mode_lancement', true
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_mes_acces"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_metriques_argent"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
  debut_mois timestamptz := date_trunc('month', now());
  fin_mois   timestamptz := date_trunc('month', now()) + INTERVAL '1 month';
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès réservé aux administrateurs');
  END IF;

  WITH m AS (
    SELECT mi.montant_commission_ht, mi.montant_commission_tva, mi.total_brut, mi.fin_le,
           NOT (COALESCE(e.est_compte_test,false) OR COALESCE(s.est_compte_test,false)) AS est_reel
    FROM missions mi
    LEFT JOIN etablissements e ON e.id = mi.etablissement_id
    LEFT JOIN soignants s ON s.id = mi.soignant_assigne_id
    WHERE mi.statut = 'TERMINEE'
  ),
  f AS (
    SELECT fa.montant_ht, fa.montant_ttc, fa.statut,
           NOT COALESCE(e.est_compte_test,false) AS est_reel
    FROM factures fa
    LEFT JOIN etablissements e ON e.id = fa.etablissement_id
  ),
  esc AS (
    SELECT pe.commission_cents, pe.debite_le,
           NOT (COALESCE(e.est_compte_test,false) OR COALESCE(s.est_compte_test,false)) AS est_reel
    FROM paiements_escrow pe
    LEFT JOIN etablissements e ON e.id = pe.etablissement_id
    LEFT JOIN soignants s ON s.id = pe.soignant_id
  )
  SELECT jsonb_build_object(
    'commission', jsonb_build_object(
      'unite', 'HT',
      'total_reel', (SELECT COALESCE(SUM(montant_commission_ht),0) FROM m WHERE est_reel),
      'total_test', (SELECT COALESCE(SUM(montant_commission_ht),0) FROM m WHERE NOT est_reel),
      'mois_reel',  (SELECT COALESCE(SUM(montant_commission_ht),0) FROM m WHERE est_reel AND fin_le>=debut_mois AND fin_le<fin_mois),
      'mois_test',  (SELECT COALESCE(SUM(montant_commission_ht),0) FROM m WHERE NOT est_reel AND fin_le>=debut_mois AND fin_le<fin_mois),
      'tva_reel',   (SELECT COALESCE(SUM(montant_commission_tva),0) FROM m WHERE est_reel)
    ),
    'encaisse', jsonb_build_object(
      'ht_reel',  ROUND((SELECT COALESCE(SUM(montant_ht),0) FROM f WHERE statut='PAYEE' AND est_reel)
                + (SELECT COALESCE(SUM(commission_cents),0)/100.0 FROM esc WHERE debite_le IS NOT NULL AND est_reel), 2),
      'ttc_reel', ROUND((SELECT COALESCE(SUM(montant_ttc),0) FROM f WHERE statut='PAYEE' AND est_reel)
                + (SELECT COALESCE(SUM(commission_cents),0)/100.0 FROM esc WHERE debite_le IS NOT NULL AND est_reel), 2),
      'ht_test',  ROUND((SELECT COALESCE(SUM(montant_ht),0) FROM f WHERE statut='PAYEE' AND NOT est_reel)
                + (SELECT COALESCE(SUM(commission_cents),0)/100.0 FROM esc WHERE debite_le IS NOT NULL AND NOT est_reel), 2)
    ),
    'facturable', jsonb_build_object(
      'unite', 'HT',
      'ht_reel', (SELECT COALESCE(SUM(montant_commission_ht),0) FROM m WHERE est_reel),
      'ht_test', (SELECT COALESCE(SUM(montant_commission_ht),0) FROM m WHERE NOT est_reel)
    ),
    'gmv', jsonb_build_object(
      'unite', 'brut',
      'total_reel', (SELECT COALESCE(SUM(total_brut),0) FROM m WHERE est_reel),
      'total_test', (SELECT COALESCE(SUM(total_brut),0) FROM m WHERE NOT est_reel),
      'mois_reel', (SELECT COALESCE(SUM(total_brut),0) FROM m WHERE est_reel AND fin_le>=debut_mois AND fin_le<fin_mois),
      'mois_test', (SELECT COALESCE(SUM(total_brut),0) FROM m WHERE NOT est_reel AND fin_le>=debut_mois AND fin_le<fin_mois)
    ),
    'nb_missions_terminees_reel', (SELECT COUNT(*) FROM m WHERE est_reel),
    'nb_missions_terminees_test', (SELECT COUNT(*) FROM m WHERE NOT est_reel),
    'etab_a_valider', (
      SELECT COUNT(*)
      FROM etablissements e
      WHERE e.supprime_le IS NULL
        AND (
          COALESCE(e.statut_verification, 'EN_ATTENTE') IN ('EN_ATTENTE', 'EN_COURS')
          OR (
            e.statut_verification = 'VERIFIE'
            AND (
              e.siret_verifie IS NOT TRUE
              OR e.finess_verifie IS NOT TRUE
              OR e.representant_identite_verifiee IS NOT TRUE
              OR e.rattachement_verifie IS NOT TRUE
              OR e.contrat_service_signe IS NOT TRUE
            )
          )
        )
    ),
    'a_des_donnees_test', (
      SELECT EXISTS(SELECT 1 FROM etablissements WHERE COALESCE(est_compte_test,false))
        OR EXISTS(SELECT 1 FROM soignants WHERE COALESCE(est_compte_test,false))
    )
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."fn_admin_metriques_argent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_moderer_document"("p_document_id" "uuid", "p_action" "text", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.est_admin() THEN
    RAISE EXCEPTION 'Administrateur autorisé requis'
      USING ERRCODE = '42501';
  END IF;
  RAISE EXCEPTION 'Contexte documentaire obligatoire : rechargez la modération et utilisez la revue détaillée'
    USING ERRCODE = '22023';
END;
$$;


ALTER FUNCTION "public"."fn_admin_moderer_document"("p_document_id" "uuid", "p_action" "text", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_moderer_document"("p_document_id" "uuid", "p_action" "text", "p_motif" "text", "p_validation_manuelle" "jsonb", "p_raison_override" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_action text := upper(NULLIF(btrim(p_action), ''));
  v_validation jsonb := COALESCE(p_validation_manuelle, '{}'::jsonb);
  v_doc public.documents_soignants%ROWTYPE;
  v_soignant public.soignants%ROWTYPE;
  v_heures public.heures_externes%ROWTYPE;
  v_expected_doc_modifie timestamptz;
  v_expected_soignant_modifie timestamptz;
  v_nom_extrait text;
  v_prenom_extrait text;
  v_date_naissance date;
  v_date_emission date;
  v_date_expiration date;
  v_date_emission_raw text;
  v_date_expiration_raw text;
  v_profession_certifiee text;
  v_type_identifiant text;
  v_numero_professionnel text;
  v_numero_attendu text;
  v_iban text;
  v_iban_normalise text;
  v_iban_last4 text;
  v_liaison_bancaire jsonb;
  v_exige_expiration boolean := false;
  v_diplome_compatible boolean := false;
  v_diplome_etranger boolean := false;
  v_formation text;
  v_annee_validee integer;
  v_specialite_licence text;
  v_override_requis boolean := false;
  v_ai_indisponible boolean := false;
  v_source text;
  v_raison_override text := NULLIF(btrim(p_raison_override), '');
  v_snapshot jsonb;
  v_resultat_final jsonb;
  v_previous_moderation text := COALESCE(
    current_setting('jolene.document_moderation_rpc', true),
    ''
  );
  v_row_count integer := 0;
  v_allowed_key text;
BEGIN
  -- est_admin() impose déjà rôle app_metadata, compte actif, registre
  -- equipe_admin complet et AAL2. Le contrôle AAL explicite protège aussi
  -- contre une future régression de cette fonction partagée.
  IF v_uid IS NULL
     OR NOT public.est_admin() THEN
    RAISE EXCEPTION 'Administrateur autorisé requis'
      USING ERRCODE = '42501';
  END IF;
  IF p_document_id IS NULL OR v_action NOT IN ('VALIDER', 'REJETER') THEN
    RAISE EXCEPTION 'Action de modération invalide'
      USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_validation) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'Contexte de modération invalide'
      USING ERRCODE = '22023';
  END IF;

  -- Liste blanche : empêche de journaliser ou conserver par mégarde un champ
  -- arbitraire/sensible fourni par le navigateur.
  SELECT key INTO v_allowed_key
  FROM jsonb_object_keys(v_validation) AS keys(key)
  WHERE key <> ALL (ARRAY[
    'expected_document_modifie_le', 'expected_soignant_modifie_le',
    'expected_statut', 'expected_type_document', 'expected_soignant_id',
    'expected_s3_bucket', 'expected_s3_cle', 'expected_s3_version_id',
    'document_lisible', 'document_complet', 'type_document_confirme',
    'antifraude_verifiee', 'override_confirme', 'nom_extrait',
    'prenom_extrait', 'date_naissance', 'date_emission', 'date_expiration',
    'profession_certifiee', 'diplome_etranger',
    'type_identifiant_professionnel', 'numero_professionnel', 'iban',
    'scolarite_formation', 'scolarite_annee_validee',
    'licence_remplacement_specialite', 'employeur_extrait',
    'periode_debut_extraite', 'periode_fin_extraite', 'heures_extraites'
  ]::text[])
  LIMIT 1;
  IF v_allowed_key IS NOT NULL THEN
    RAISE EXCEPTION 'Champ de modération non autorisé : %', v_allowed_key
      USING ERRCODE = '22023';
  END IF;

  IF NULLIF(v_validation ->> 'expected_document_modifie_le', '') IS NULL
     OR NULLIF(v_validation ->> 'expected_soignant_modifie_le', '') IS NULL
     OR NULLIF(v_validation ->> 'expected_statut', '') IS NULL
     OR NULLIF(v_validation ->> 'expected_type_document', '') IS NULL
     OR NULLIF(v_validation ->> 'expected_soignant_id', '') IS NULL
     OR NULLIF(v_validation ->> 'expected_s3_bucket', '') IS NULL
     OR NULLIF(v_validation ->> 'expected_s3_cle', '') IS NULL THEN
    RAISE EXCEPTION 'Snapshot CAS incomplet : rechargez la file de modération'
      USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_expected_doc_modifie := (v_validation ->> 'expected_document_modifie_le')::timestamptz;
    v_expected_soignant_modifie := (v_validation ->> 'expected_soignant_modifie_le')::timestamptz;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'Snapshot CAS invalide : rechargez la file de modération'
      USING ERRCODE = '22023';
  END;

  SELECT * INTO v_doc
  FROM public.documents_soignants
  WHERE id = p_document_id
  FOR UPDATE;
  IF NOT FOUND OR v_doc.supprime_le IS NOT NULL THEN
    RAISE EXCEPTION 'Document introuvable ou supprimé' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_soignant
  FROM public.soignants
  WHERE id = v_doc.soignant_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profil soignant introuvable' USING ERRCODE = 'P0002';
  END IF;

  IF v_doc.modifie_le IS DISTINCT FROM v_expected_doc_modifie
     OR v_soignant.modifie_le IS DISTINCT FROM v_expected_soignant_modifie
     OR v_doc.statut_verification::text IS DISTINCT FROM v_validation ->> 'expected_statut'
     OR v_doc.type_document::text IS DISTINCT FROM v_validation ->> 'expected_type_document'
     OR v_doc.soignant_id::text IS DISTINCT FROM v_validation ->> 'expected_soignant_id'
     OR v_doc.s3_bucket IS DISTINCT FROM v_validation ->> 'expected_s3_bucket'
     OR v_doc.s3_cle IS DISTINCT FROM v_validation ->> 'expected_s3_cle'
     OR v_doc.s3_version_id IS DISTINCT FROM NULLIF(v_validation ->> 'expected_s3_version_id', '') THEN
    RAISE EXCEPTION 'Le document, sa source ou le profil a changé : rechargez avant de décider'
      USING ERRCODE = '40001';
  END IF;
  IF v_doc.statut_verification NOT IN (
       'EN_ATTENTE', 'REVUE_MANUELLE_REQUISE', 'API_INDISPONIBLE'
     )
     OR v_doc.verification_attempt_id IS NOT NULL THEN
    RAISE EXCEPTION 'Ce document n’est plus disponible pour une décision manuelle'
      USING ERRCODE = '40001';
  END IF;

  v_snapshot := jsonb_build_object(
    'document', jsonb_build_object(
      'id', v_doc.id,
      'modifie_le', v_doc.modifie_le,
      'statut', v_doc.statut_verification,
      'type_document', v_doc.type_document,
      's3_bucket', v_doc.s3_bucket,
      's3_cle', v_doc.s3_cle,
      's3_version_id', v_doc.s3_version_id,
      'type_mime', v_doc.type_mime,
      'taille_octets', v_doc.taille_octets,
      'motif_precedent', v_doc.motif_rejet,
      'resultat_ia_present', v_doc.resultat_ia IS NOT NULL
    ),
    'profil', jsonb_build_object(
      'id', v_soignant.id,
      'modifie_le', v_soignant.modifie_le,
      'nom', v_soignant.nom,
      'prenom', v_soignant.prenom,
      'date_naissance', v_soignant.date_naissance,
      'profession', v_soignant.profession,
      'rpps_verifie', COALESCE(v_soignant.rpps_verifie, false),
      'adeli_verifie', COALESCE(v_soignant.adeli_verifie, false)
    )
  );

  IF v_action = 'REJETER' THEN
    IF char_length(btrim(COALESCE(p_motif, ''))) < 10
       OR char_length(btrim(COALESCE(p_motif, ''))) > 1000 THEN
      RAISE EXCEPTION 'Le motif de rejet doit contenir entre 10 et 1000 caractères'
        USING ERRCODE = '22023';
    END IF;

    PERFORM set_config('jolene.document_moderation_rpc', 'true', true);
    BEGIN
      UPDATE public.documents_soignants
      SET statut_verification = 'REJETE',
          verifie_par = v_uid,
          verifie_le = now(),
          motif_rejet = btrim(p_motif),
          valide_depuis = NULL,
          valide_jusqua = NULL,
          verification_attempt_id = NULL,
          resultat_ia = COALESCE(resultat_ia, '{}'::jsonb) || jsonb_build_object(
            'verdict_serveur', 'REJETE',
            'motif_serveur', btrim(p_motif),
            'source_validation', 'ADMIN_REJET'
          ),
          modifie_le = now()
      WHERE id = v_doc.id
        AND modifie_le = v_expected_doc_modifie
        AND statut_verification = v_doc.statut_verification
        AND verification_attempt_id IS NULL;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      IF v_row_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'Décision concurrente détectée' USING ERRCODE = '40001';
      END IF;

      INSERT INTO public.journaux_audit (
        acteur_id, type_acteur, action, type_ressource, id_ressource,
        cle_s3_ressource, details
      ) VALUES (
        v_uid, 'ADMIN', 'MODERATION_DOCUMENT', 'document', v_doc.id,
        v_doc.s3_cle,
        jsonb_build_object(
          'decision', 'REJETER',
          'source', 'ADMIN_REJET',
          'motif', btrim(p_motif),
          'snapshot', v_snapshot
        )
      );

      UPDATE public.file_revue_manuelle
      SET statut = 'RESOLU_MANUELLEMENT',
          assigne_a = v_uid,
          notes_resolution = left('Document rejeté : ' || btrim(p_motif), 1000),
          revu_le = COALESCE(revu_le, now()),
          resolu_le = now()
      WHERE id_entite = v_doc.id
        AND type_entite = 'TELEVERSEMENT_DOCUMENT'
        AND statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE');

      PERFORM public.fn_calculer_tous_documents_valides(v_doc.soignant_id);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config(
        'jolene.document_moderation_rpc',
        v_previous_moderation,
        true
      );
      RAISE;
    END;
    PERFORM set_config(
      'jolene.document_moderation_rpc',
      v_previous_moderation,
      true
    );
    RETURN jsonb_build_object('success', true, 'action', 'REJETER');
  END IF;

  -- Toute validation exige une revue visuelle explicite et une identité lue.
  IF v_validation -> 'document_lisible' IS DISTINCT FROM 'true'::jsonb
     OR v_validation -> 'document_complet' IS DISTINCT FROM 'true'::jsonb
     OR v_validation -> 'type_document_confirme' IS DISTINCT FROM 'true'::jsonb
     OR v_validation -> 'antifraude_verifiee' IS DISTINCT FROM 'true'::jsonb THEN
    RAISE EXCEPTION 'Lisibilité, complétude, type et contrôle antifraude doivent être confirmés'
      USING ERRCODE = '23514';
  END IF;

  v_nom_extrait := NULLIF(left(btrim(v_validation ->> 'nom_extrait'), 200), '');
  v_prenom_extrait := NULLIF(left(btrim(v_validation ->> 'prenom_extrait'), 200), '');
  IF NOT public.fn_noms_personne_correspondent(
    v_soignant.nom,
    v_soignant.prenom,
    v_nom_extrait,
    v_prenom_extrait
  ) THEN
    RAISE EXCEPTION 'Le nom et le prénom lus ne correspondent pas au profil'
      USING ERRCODE = '23514';
  END IF;

  v_date_emission_raw := NULLIF(btrim(v_validation ->> 'date_emission'), '');
  v_date_expiration_raw := NULLIF(btrim(v_validation ->> 'date_expiration'), '');
  v_date_emission := private.fn_date_iso_moderation(v_date_emission_raw);
  v_date_expiration := private.fn_date_iso_moderation(v_date_expiration_raw);
  IF v_date_emission_raw IS NOT NULL AND v_date_emission IS NULL THEN
    RAISE EXCEPTION 'Date d’émission invalide' USING ERRCODE = '22023';
  END IF;
  IF v_date_expiration_raw IS NOT NULL AND v_date_expiration IS NULL THEN
    RAISE EXCEPTION 'Date d’expiration invalide' USING ERRCODE = '22023';
  END IF;
  IF v_date_emission > current_date THEN
    RAISE EXCEPTION 'La date d’émission ne peut pas être future' USING ERRCODE = '23514';
  END IF;
  IF v_date_expiration IS NOT NULL AND v_date_expiration <= current_date THEN
    RAISE EXCEPTION 'Un document expiré ne peut pas être validé' USING ERRCODE = '23514';
  END IF;
  IF v_date_emission IS NOT NULL
     AND v_date_expiration IS NOT NULL
     AND v_date_expiration < v_date_emission THEN
    RAISE EXCEPTION 'La date d’expiration précède la date d’émission'
      USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(bool_or(drp.a_expiration), false)
  INTO v_exige_expiration
  FROM public.documents_requis_par_profession drp
  WHERE drp.profession = v_soignant.profession
    AND public.fn_type_document_preuve_compatible(
      drp.type_document,
      v_doc.type_document
    );
  v_exige_expiration := COALESCE(v_exige_expiration, false)
    OR v_doc.type_document IN (
      'CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR',
      'RCP_ASSURANCE', 'LICENCE_REMPLACEMENT'
    );
  IF v_exige_expiration AND v_date_expiration IS NULL THEN
    RAISE EXCEPTION 'La date d’expiration est obligatoire pour ce document'
      USING ERRCODE = '23514';
  END IF;

  IF v_doc.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR') THEN
    v_date_naissance := private.fn_date_iso_moderation(
      v_validation ->> 'date_naissance'
    );
    IF v_date_naissance IS NULL
       OR v_date_naissance < DATE '1900-01-01'
       OR v_date_naissance >= current_date THEN
      RAISE EXCEPTION 'Date de naissance absente ou non plausible'
        USING ERRCODE = '23514';
    END IF;
    IF v_soignant.date_naissance IS NOT NULL
       AND v_soignant.date_naissance IS DISTINCT FROM v_date_naissance THEN
      RAISE EXCEPTION 'La date de naissance du document contredit le profil'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_doc.type_document IN ('DIPLOME', 'AUTORISATION_EXERCICE') THEN
    v_profession_certifiee := upper(NULLIF(btrim(
      v_validation ->> 'profession_certifiee'
    ), ''));
    IF NOT EXISTS (
      SELECT 1
      FROM unnest(enum_range(NULL::public.type_profession)) AS p(profession)
      WHERE p.profession::text = v_profession_certifiee
    ) THEN
      RAISE EXCEPTION 'Profession certifiée absente ou inconnue'
        USING ERRCODE = '23514';
    END IF;
    v_diplome_compatible := CASE v_soignant.profession::text
      WHEN 'IDE' THEN v_profession_certifiee IN ('IDE', 'IADE', 'IBODE')
      WHEN 'IADE' THEN v_profession_certifiee = 'IADE'
      WHEN 'IBODE' THEN v_profession_certifiee = 'IBODE'
      ELSE v_profession_certifiee = v_soignant.profession::text
    END;
    IF NOT v_diplome_compatible THEN
      RAISE EXCEPTION 'La qualification certifiée ne correspond pas à la profession du profil'
        USING ERRCODE = '23514';
    END IF;

    v_diplome_etranger := COALESCE(
      (v_validation ->> 'diplome_etranger')::boolean,
      false
    );
    IF v_doc.type_document = 'DIPLOME'
       AND v_diplome_etranger
       AND NOT EXISTS (
         SELECT 1
         FROM public.documents_soignants autorisation
         WHERE autorisation.soignant_id = v_doc.soignant_id
           AND autorisation.type_document = 'AUTORISATION_EXERCICE'
           AND autorisation.statut_verification = 'VERIFIE'
           AND autorisation.supprime_le IS NULL
           AND (
             autorisation.valide_jusqua IS NULL
             OR autorisation.valide_jusqua > current_date
           )
           AND CASE v_soignant.profession::text
             WHEN 'IDE' THEN upper(COALESCE(
               autorisation.resultat_ia ->> 'profession_certifiee', ''
             )) IN ('IDE', 'IADE', 'IBODE')
             WHEN 'IADE' THEN upper(COALESCE(
               autorisation.resultat_ia ->> 'profession_certifiee', ''
             )) = 'IADE'
             WHEN 'IBODE' THEN upper(COALESCE(
               autorisation.resultat_ia ->> 'profession_certifiee', ''
             )) = 'IBODE'
             ELSE upper(COALESCE(
               autorisation.resultat_ia ->> 'profession_certifiee', ''
             )) = v_soignant.profession::text
           END
       ) THEN
      RAISE EXCEPTION 'Un diplôme étranger exige une autorisation d’exercice vérifiée et concordante'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_doc.type_document = 'RPPS_ADELI' THEN
    v_type_identifiant := upper(NULLIF(btrim(
      v_validation ->> 'type_identifiant_professionnel'
    ), ''));
    v_numero_professionnel := regexp_replace(
      COALESCE(v_validation ->> 'numero_professionnel', ''),
      '[^0-9]',
      '',
      'g'
    );
    IF v_type_identifiant = 'RPPS' THEN
      v_numero_attendu := regexp_replace(COALESCE(v_soignant.numero_rpps, ''), '[^0-9]', '', 'g');
      IF COALESCE(v_soignant.rpps_verifie, false) IS NOT TRUE
         OR v_numero_professionnel !~ '^\d{11}$'
         OR v_numero_professionnel IS DISTINCT FROM v_numero_attendu THEN
        RAISE EXCEPTION 'RPPS non vérifié ou différent du profil'
          USING ERRCODE = '23514';
      END IF;
    ELSIF v_type_identifiant = 'ADELI' THEN
      v_numero_attendu := regexp_replace(COALESCE(v_soignant.numero_adeli, ''), '[^0-9]', '', 'g');
      IF COALESCE(v_soignant.adeli_verifie, false) IS NOT TRUE
         OR v_numero_professionnel !~ '^\d{9}$'
         OR v_numero_professionnel IS DISTINCT FROM v_numero_attendu THEN
        RAISE EXCEPTION 'ADELI non vérifié ou différent du profil'
          USING ERRCODE = '23514';
      END IF;
    ELSE
      RAISE EXCEPTION 'Type d’identifiant professionnel invalide'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_doc.type_document = 'RIB' THEN
    v_iban := v_validation ->> 'iban';
    IF NOT private.fn_iban_valide_moderation(v_iban) THEN
      RAISE EXCEPTION 'IBAN invalide (format ou checksum ISO 13616)'
        USING ERRCODE = '23514';
    END IF;
    v_iban_normalise := upper(regexp_replace(v_iban, '[^A-Za-z0-9]', '', 'g'));
    v_iban_last4 := right(v_iban_normalise, 4);
    IF NULLIF(btrim(v_soignant.iban_virement), '') IS NOT NULL
       AND upper(regexp_replace(v_soignant.iban_virement, '[^A-Za-z0-9]', '', 'g'))
         IS DISTINCT FROM v_iban_normalise THEN
      RAISE EXCEPTION 'L’IBAN du RIB diffère de l’IBAN de versement enregistré'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_doc.type_document = 'ATTESTATION_SCOLARITE' THEN
    v_formation := upper(NULLIF(btrim(
      v_validation ->> 'scolarite_formation'
    ), ''));
    BEGIN
      v_annee_validee := (v_validation ->> 'scolarite_annee_validee')::integer;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      v_annee_validee := NULL;
    END;
    IF v_date_emission IS NULL
       OR v_date_emission < current_date - 400
       OR v_date_emission > current_date THEN
      RAISE EXCEPTION 'L’attestation de scolarité doit dater de moins de 400 jours'
        USING ERRCODE = '23514';
    END IF;
    IF v_formation IS NULL OR v_annee_validee IS NULL
       OR NOT EXISTS (
         SELECT 1
         FROM public.fn_professions_autorisees_scolarite(
           v_formation,
           v_annee_validee
         ) AS autorisee(profession)
         WHERE autorisee.profession = v_soignant.profession
       ) THEN
      RAISE EXCEPTION 'La formation ou l’année validée ne permet pas la profession du profil'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_doc.type_document = 'LICENCE_REMPLACEMENT' THEN
    v_specialite_licence := NULLIF(left(btrim(
      v_validation ->> 'licence_remplacement_specialite'
    ), 200), '');
    IF v_soignant.profession IS DISTINCT FROM 'MEDECIN'
       OR v_date_emission IS NULL
       OR v_date_expiration IS NULL
       OR v_date_expiration > (v_date_emission + interval '13 months')::date
       OR v_specialite_licence IS NULL THEN
      RAISE EXCEPTION 'Licence de remplacement non concordante, incomplète ou hors validité'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF v_doc.type_document::text IN (
    'BULLETIN_PAIE', 'ATTESTATION_EMPLOYEUR', 'CERTIFICAT_TRAVAIL'
  ) THEN
    SELECT * INTO v_heures
    FROM public.heures_externes
    WHERE document_id = v_doc.id
      AND soignant_id = v_doc.soignant_id
    FOR SHARE;
    IF NOT FOUND
       OR public.fn_normaliser_nom(v_heures.employeur_nom)
         IS DISTINCT FROM public.fn_normaliser_nom(
           v_validation ->> 'employeur_extrait'
         )
       OR v_heures.date_debut IS DISTINCT FROM private.fn_date_iso_moderation(
         v_validation ->> 'periode_debut_extraite'
       )
       OR v_heures.date_fin IS DISTINCT FROM private.fn_date_iso_moderation(
         v_validation ->> 'periode_fin_extraite'
       )
       OR v_heures.heures_declarees IS DISTINCT FROM
         NULLIF(v_validation ->> 'heures_extraites', '')::numeric
       OR v_heures.type_preuve IS DISTINCT FROM v_doc.type_document::text THEN
      RAISE EXCEPTION 'Employeur, période ou heures non concordants avec la déclaration'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  v_ai_indisponible := v_doc.statut_verification = 'API_INDISPONIBLE'
    OR v_doc.resultat_ia IS NULL
    OR v_doc.resultat_ia ? 'erreur_anthropic'
    OR v_doc.resultat_ia ? 'erreur_parse';
  v_override_requis := NOT v_ai_indisponible AND (
    upper(COALESCE(v_doc.resultat_ia ->> 'verdict', '')) = 'REJETE'
    OR upper(COALESCE(v_doc.resultat_ia ->> 'verdict_serveur', '')) = 'REJETE'
    OR v_doc.resultat_ia -> 'type_correspond' = 'false'::jsonb
    OR v_doc.resultat_ia -> 'document_lisible' = 'false'::jsonb
    OR v_doc.resultat_ia -> 'document_complet' = 'false'::jsonb
    OR v_doc.resultat_ia -> 'nom_correspond' = 'false'::jsonb
    OR v_doc.coherence_nom IS FALSE
    OR (
      jsonb_typeof(v_doc.resultat_ia -> 'indices_falsification') = 'array'
      AND jsonb_array_length(v_doc.resultat_ia -> 'indices_falsification') > 0
    )
  );
  IF v_raison_override IS NOT NULL THEN
    v_override_requis := true;
  END IF;
  IF v_override_requis AND (
    v_validation -> 'override_confirme' IS DISTINCT FROM 'true'::jsonb
    OR char_length(v_raison_override) < 30
    OR char_length(v_raison_override) > 1000
  ) THEN
    RAISE EXCEPTION 'Une dérogation exceptionnelle confirmée et motivée (30 à 1000 caractères) est obligatoire'
      USING ERRCODE = '23514';
  END IF;
  v_source := CASE
    WHEN v_override_requis THEN 'ADMIN_OVERRIDE_EXCEPTIONNEL'
    WHEN v_ai_indisponible THEN 'ADMIN_SAISIE_MANUELLE'
    ELSE 'ADMIN_REVUE_IA'
  END;

  -- Les champs manuels nécessaires aux règles dérivées sont persistés dans
  -- resultat_ia, mais jamais l'IBAN complet. Le suffixe historique de colonne
  -- reste inchangé pour compatibilité avec les recalculs existants.
  v_resultat_final := (
    COALESCE(v_doc.resultat_ia, '{}'::jsonb)
      - 'iban'
      - 'iban_extrait'
      - 'raw_text'
  ) || jsonb_strip_nulls(jsonb_build_object(
    'verdict_serveur', 'VERIFIE',
    'motif_serveur', NULL,
    'source_validation', v_source,
    'revue_manuelle_le', now(),
    'type_correspond', true,
    'document_lisible', true,
    'document_complet', true,
    'antifraude_manuelle_verifiee', true,
    'nom_correspond', true,
    'nom_extrait', v_nom_extrait,
    'prenom_extrait', v_prenom_extrait,
    'date_naissance_extraite', v_date_naissance,
    'date_emission', v_date_emission,
    'date_expiration', v_date_expiration,
    'profession_certifiee', v_profession_certifiee,
    'diplome_etranger', CASE
      WHEN v_doc.type_document = 'DIPLOME' THEN v_diplome_etranger
      ELSE NULL
    END,
    'type_identifiant_professionnel', v_type_identifiant,
    'numero_professionnel_extrait', v_numero_professionnel,
    'iban_last4', v_iban_last4,
    'iban_valide', CASE WHEN v_doc.type_document = 'RIB' THEN true ELSE NULL END,
    'iban_preuve_hash_v1', CASE
      WHEN v_doc.type_document = 'RIB' THEN encode(
        extensions.digest(
          convert_to(v_iban_normalise || ':' || v_doc.id::text, 'UTF8'),
          'sha256'
        ),
        'hex'
      )
      ELSE NULL
    END,
    'scolarite_formation', v_formation,
    'scolarite_annee_validee', v_annee_validee,
    'licence_remplacement_specialite', v_specialite_licence,
    'employeur_extrait', CASE WHEN v_heures.id IS NULL THEN NULL ELSE v_heures.employeur_nom END,
    'periode_debut_extraite', CASE WHEN v_heures.id IS NULL THEN NULL ELSE v_heures.date_debut END,
    'periode_fin_extraite', CASE WHEN v_heures.id IS NULL THEN NULL ELSE v_heures.date_fin END,
    'heures_extraites', CASE WHEN v_heures.id IS NULL THEN NULL ELSE v_heures.heures_declarees END
  ));

  PERFORM set_config('jolene.document_moderation_rpc', 'true', true);
  BEGIN
    IF v_doc.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
       AND v_soignant.date_naissance IS NULL THEN
      UPDATE public.soignants
      SET date_naissance = v_date_naissance,
          modifie_le = now()
      WHERE id = v_soignant.id
        AND modifie_le = v_expected_soignant_modifie
        AND date_naissance IS NULL;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      IF v_row_count IS DISTINCT FROM 1 THEN
        RAISE EXCEPTION 'Le profil a changé pendant la décision'
          USING ERRCODE = '40001';
      END IF;
    END IF;

    UPDATE public.documents_soignants
    SET statut_verification = 'VERIFIE',
        verifie_par = v_uid,
        verifie_le = now(),
        motif_rejet = NULL,
        valide_depuis = v_date_emission,
        valide_jusqua = v_date_expiration,
        resultat_ia = v_resultat_final,
        nom_extrait_ia = v_nom_extrait,
        prenom_extrait_ia = v_prenom_extrait,
        coherence_nom = true,
        verification_attempt_id = NULL,
        modifie_le = now()
    WHERE id = v_doc.id
      AND modifie_le = v_expected_doc_modifie
      AND statut_verification = v_doc.statut_verification
      AND verification_attempt_id IS NULL;
    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    IF v_row_count IS DISTINCT FROM 1 THEN
      RAISE EXCEPTION 'Décision concurrente détectée' USING ERRCODE = '40001';
    END IF;

    IF v_doc.type_document = 'RIB' THEN
      -- L'IBAN complet n'est jamais persisté dans resultat_ia ni dans l'audit.
      -- Il est transmis en mémoire à la liaison service-role, qui le rattache à
      -- cette version exacte du RIB et à la pièce d'identité courante.
      -- Cette fonction est créée par la migration de durcissement suivante.
      -- La résolution dynamique évite une dépendance d'ordre au moment du
      -- CREATE FUNCTION, tout en conservant l'appel dans la même transaction.
      EXECUTE
        'SELECT public.fn_lier_iban_verifie_document($1, $2, $3)'
      INTO v_liaison_bancaire
      USING v_doc.id, v_doc.s3_cle, v_iban_normalise;
      IF COALESCE((v_liaison_bancaire ->> 'success')::boolean, false) IS NOT TRUE
         AND COALESCE(v_liaison_bancaire ->> 'error_code', '') NOT IN (
           'IDENTITE_VERIFIEE_REQUISE',
           'IDENTITE_COURANTE_REQUISE'
         ) THEN
        RAISE EXCEPTION 'Le RIB validé ne peut pas être lié au compte de versement'
          USING ERRCODE = '23514';
      END IF;
    END IF;

    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource,
      cle_s3_ressource, details
    ) VALUES (
      v_uid, 'ADMIN', 'MODERATION_DOCUMENT', 'document', v_doc.id,
      v_doc.s3_cle,
      jsonb_build_object(
        'decision', 'VALIDER',
        'source', v_source,
        'snapshot', v_snapshot,
        'champs_confirmes', jsonb_strip_nulls(jsonb_build_object(
          'nom_extrait', v_nom_extrait,
          'prenom_extrait', v_prenom_extrait,
          'date_naissance', v_date_naissance,
          'date_emission', v_date_emission,
          'date_expiration', v_date_expiration,
          'profession_certifiee', v_profession_certifiee,
          'type_identifiant_professionnel', v_type_identifiant,
          'numero_professionnel', v_numero_professionnel,
          'iban_last4', v_iban_last4,
          'scolarite_formation', v_formation,
          'scolarite_annee_validee', v_annee_validee,
          'licence_specialite', v_specialite_licence
        )),
        'override_raison', v_raison_override
      )
    );

    UPDATE public.file_revue_manuelle
    SET statut = 'RESOLU_MANUELLEMENT',
        assigne_a = v_uid,
        notes_resolution = left(
          CASE
            WHEN v_override_requis THEN 'Validation exceptionnelle : ' || v_raison_override
            ELSE 'Validation documentaire après revue contextualisée (' || v_source || ')'
          END,
          1000
        ),
        revu_le = COALESCE(revu_le, now()),
        resolu_le = now()
    WHERE id_entite = v_doc.id
      AND type_entite = 'TELEVERSEMENT_DOCUMENT'
      AND statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE');

    PERFORM public.fn_calculer_tous_documents_valides(v_doc.soignant_id);
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'jolene.document_moderation_rpc',
      v_previous_moderation,
      true
    );
    RAISE;
  END;
  PERFORM set_config(
    'jolene.document_moderation_rpc',
    v_previous_moderation,
    true
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', 'VALIDER',
    'source', v_source
  );
END;
$_$;


ALTER FUNCTION "public"."fn_admin_moderer_document"("p_document_id" "uuid", "p_action" "text", "p_motif" "text", "p_validation_manuelle" "jsonb", "p_raison_override" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_admin_moderer_document"("p_document_id" "uuid", "p_action" "text", "p_motif" "text", "p_validation_manuelle" "jsonb", "p_raison_override" "text") IS 'Décision documentaire admin AAL2 : snapshot/CAS, contrôle métier par type, audit atomique et dérogation exceptionnelle motivée.';



CREATE OR REPLACE FUNCTION "public"."fn_admin_moderer_evaluation"("p_evaluation_id" "uuid", "p_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_action_norm TEXT;
BEGIN
    IF NOT est_admin() THEN
        RETURN jsonb_build_object('error', 'Accès refusé — admin uniquement');
    END IF;

    -- Normaliser l'action pour accepter MAJ/min et plusieurs synonymes
    v_action_norm := UPPER(COALESCE(p_action, ''));

    IF v_action_norm IN ('PUBLIER', 'AFFICHER', 'DEMASQUER') THEN
        UPDATE evaluations SET visible = TRUE WHERE id = p_evaluation_id;
    ELSIF v_action_norm IN ('MASQUER', 'CACHER') THEN
        UPDATE evaluations SET visible = FALSE WHERE id = p_evaluation_id;
    ELSIF v_action_norm IN ('SUPPRIMER', 'SUPPRESSION') THEN
        DELETE FROM evaluations WHERE id = p_evaluation_id;
    ELSE
        RETURN jsonb_build_object('error', 'Action invalide : PUBLIER, MASQUER ou SUPPRIMER');
    END IF;

    -- Audit (fix: id_ressource au lieu de ressource_id)
    INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES (auth.uid(), 'ADMIN', 'MODERATION_EVALUATION', 'evaluation', p_evaluation_id,
        jsonb_build_object('action', v_action_norm));

    RETURN jsonb_build_object('success', TRUE, 'action', v_action_norm);
END;
$$;


ALTER FUNCTION "public"."fn_admin_moderer_evaluation"("p_evaluation_id" "uuid", "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_modifier_gel_scope_litige"("p_litige_id" "uuid", "p_nouveau_scope" "text", "p_raison" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_old_scope text;
  v_litige RECORD;
BEGIN
  IF NOT est_admin() THEN RETURN jsonb_build_object('success',false,'error','Admin requis'); END IF;
  IF p_nouveau_scope NOT IN ('MISSION_ENTIERE','FACTURE_UNIQUE','AUCUN','PERIODE_LITIGIEUSE') THEN
    RETURN jsonb_build_object('success',false,'error','Scope invalide');
  END IF;
  IF COALESCE(trim(p_raison),'') = '' THEN RETURN jsonb_build_object('success',false,'error','Raison obligatoire'); END IF;
  SELECT * INTO v_litige FROM litiges WHERE id = p_litige_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Litige introuvable'); END IF;
  v_old_scope := v_litige.gel_facture_scope;
  IF p_nouveau_scope = 'FACTURE_UNIQUE' AND v_litige.facture_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','FACTURE_UNIQUE requiert facture_id');
  END IF;
  IF p_nouveau_scope = 'PERIODE_LITIGIEUSE' AND (v_litige.periode_debut IS NULL OR v_litige.periode_fin IS NULL) THEN
    RETURN jsonb_build_object('success',false,'error','PERIODE_LITIGIEUSE requiert periode_debut et periode_fin');
  END IF;
  UPDATE litiges SET gel_facture_scope = p_nouveau_scope WHERE id = p_litige_id;
  UPDATE factures_honoraires SET statut_litige='NORMAL', litige_id=NULL
   WHERE litige_id=p_litige_id AND statut_litige='EN_ATTENTE_LITIGE';
  IF v_litige.statut IN ('OUVERT','EN_DISCUSSION','EN_MEDIATION','CONTESTEE')
     AND NOT COALESCE(v_litige.est_informatif,false) AND p_nouveau_scope <> 'AUCUN' THEN
    IF v_litige.categorie_litige = 'FINANCIER' AND v_litige.facture_id IS NOT NULL THEN
      UPDATE factures_honoraires SET statut_litige='EN_ATTENTE_LITIGE', litige_id=p_litige_id
       WHERE id=v_litige.facture_id AND statut_litige='NORMAL' AND statut<>'PAYEE';
    ELSIF v_litige.categorie_litige::text IN ('PRESENCE','CONDITIONS','COMPORTEMENT') THEN
      IF p_nouveau_scope = 'FACTURE_UNIQUE' AND v_litige.facture_id IS NOT NULL THEN
        UPDATE factures_honoraires SET statut_litige='EN_ATTENTE_LITIGE', litige_id=p_litige_id
         WHERE id=v_litige.facture_id AND statut_litige='NORMAL' AND statut<>'PAYEE';
      ELSIF p_nouveau_scope = 'PERIODE_LITIGIEUSE' AND v_litige.periode_debut IS NOT NULL AND v_litige.periode_fin IS NOT NULL THEN
        UPDATE factures_honoraires SET statut_litige='EN_ATTENTE_LITIGE', litige_id=p_litige_id
         WHERE mission_id=v_litige.mission_id AND statut_litige='NORMAL' AND statut<>'PAYEE'
           AND periode_debut <= v_litige.periode_fin AND periode_fin >= v_litige.periode_debut;
      ELSE
        UPDATE factures_honoraires SET statut_litige='EN_ATTENTE_LITIGE', litige_id=p_litige_id
         WHERE mission_id=v_litige.mission_id AND statut_litige='NORMAL' AND statut<>'PAYEE';
      END IF;
    END IF;
  END IF;
  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid, p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'LITIGE_GEL_SCOPE_MODIFIE', p_type_ressource := 'litige',
    p_id_ressource := p_litige_id,
    p_details := jsonb_build_object('old_scope',v_old_scope,'new_scope',p_nouveau_scope,'raison',p_raison,'reapplique_immediatement',true)
  );
  RETURN jsonb_build_object('success',true,'litige_id',p_litige_id,'old_scope',v_old_scope,'new_scope',p_nouveau_scope);
END;
$$;


ALTER FUNCTION "public"."fn_admin_modifier_gel_scope_litige"("p_litige_id" "uuid", "p_nouveau_scope" "text", "p_raison" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_modifier_palier_bfa"("p_palier_id" "uuid", "p_nom" "text" DEFAULT NULL::"text", "p_missions_min" integer DEFAULT NULL::integer, "p_missions_max" integer DEFAULT NULL::integer, "p_taux_bfa" numeric DEFAULT NULL::numeric, "p_est_actif" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_avant record;
  v_min integer;
  v_max integer;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Non autorisé');
  END IF;

  SELECT * INTO v_avant FROM paliers_bfa WHERE id = p_palier_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Palier introuvable');
  END IF;

  v_min := COALESCE(p_missions_min, v_avant.missions_min);
  v_max := COALESCE(p_missions_max, v_avant.missions_max);

  IF p_taux_bfa IS NOT NULL AND (p_taux_bfa < 0 OR p_taux_bfa > 50) THEN
    RETURN jsonb_build_object('error', 'Le taux BFA doit être entre 0 et 50 %');
  END IF;
  IF v_min < 0 OR (v_max IS NOT NULL AND v_max < v_min) THEN
    RETURN jsonb_build_object('error', 'Bornes invalides (max < min)');
  END IF;
  -- Non-chevauchement avec les autres paliers actifs
  IF COALESCE(p_est_actif, v_avant.est_actif) AND EXISTS (
    SELECT 1 FROM paliers_bfa autre
    WHERE autre.id <> p_palier_id AND autre.est_actif
      AND v_min <= COALESCE(autre.missions_max, 2147483647)
      AND COALESCE(v_max, 2147483647) >= autre.missions_min
  ) THEN
    RETURN jsonb_build_object('error', 'Les bornes chevauchent un autre palier actif');
  END IF;

  UPDATE paliers_bfa SET
    nom = COALESCE(p_nom, nom),
    missions_min = v_min,
    missions_max = CASE WHEN p_missions_max IS NOT NULL THEN p_missions_max ELSE missions_max END,
    taux_bfa = COALESCE(p_taux_bfa, taux_bfa),
    est_actif = COALESCE(p_est_actif, est_actif)
  WHERE id = p_palier_id;

  INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
  VALUES (auth.uid(), 'ADMIN', 'TAUX_COMMISSION_MODIFIE', 'palier_bfa', p_palier_id,
    jsonb_build_object(
      'avant', jsonb_build_object('nom', v_avant.nom, 'min', v_avant.missions_min, 'max', v_avant.missions_max, 'taux', v_avant.taux_bfa, 'actif', v_avant.est_actif),
      'apres', jsonb_build_object('nom', COALESCE(p_nom, v_avant.nom), 'min', v_min, 'max', COALESCE(p_missions_max, v_avant.missions_max), 'taux', COALESCE(p_taux_bfa, v_avant.taux_bfa), 'actif', COALESCE(p_est_actif, v_avant.est_actif))
    ));

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_modifier_palier_bfa"("p_palier_id" "uuid", "p_nom" "text", "p_missions_min" integer, "p_missions_max" integer, "p_taux_bfa" numeric, "p_est_actif" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_modifier_remise_groupe"("p_groupe_id" "uuid", "p_remise" numeric, "p_raison" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ancienne numeric;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Non autorisé');
  END IF;
  IF p_remise IS NULL OR p_remise < 0 OR p_remise > 100 THEN
    RETURN jsonb_build_object('error', 'La remise doit être entre 0 et 100 %');
  END IF;

  SELECT remise_groupe_pourcent INTO v_ancienne FROM groupes_sante WHERE id = p_groupe_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Groupe introuvable');
  END IF;

  UPDATE groupes_sante SET remise_groupe_pourcent = p_remise WHERE id = p_groupe_id;

  INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
  VALUES (auth.uid(), 'ADMIN', 'TAUX_COMMISSION_MODIFIE', 'groupe', p_groupe_id,
    jsonb_build_object('champ', 'remise_groupe_pourcent', 'ancienne', v_ancienne, 'nouvelle', p_remise, 'raison', p_raison));

  RETURN jsonb_build_object('success', true, 'remise', p_remise);
END;
$$;


ALTER FUNCTION "public"."fn_admin_modifier_remise_groupe"("p_groupe_id" "uuid", "p_remise" numeric, "p_raison" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_modifier_taux_commission"("p_etablissement_id" "uuid" DEFAULT NULL::"uuid", "p_groupe_id" "uuid" DEFAULT NULL::"uuid", "p_nouveau_taux" numeric DEFAULT NULL::numeric, "p_raison" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_old_taux numeric;
  v_target text;
  v_target_id uuid;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  IF (p_etablissement_id IS NULL AND p_groupe_id IS NULL)
     OR (p_etablissement_id IS NOT NULL AND p_groupe_id IS NOT NULL) THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Exactement un de p_etablissement_id ou p_groupe_id doit être fourni');
  END IF;

  IF p_nouveau_taux IS NOT NULL AND (p_nouveau_taux < 0 OR p_nouveau_taux > 100) THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Taux de commission hors bornes (attendu entre 0 et 100)');
  END IF;

  IF COALESCE(trim(p_raison), '') = '' THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Raison obligatoire (audit)');
  END IF;

  IF p_etablissement_id IS NOT NULL THEN
    SELECT taux_commission_negocie INTO v_old_taux
    FROM etablissements WHERE id = p_etablissement_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Établissement introuvable');
    END IF;
    UPDATE etablissements SET taux_commission_negocie = p_nouveau_taux WHERE id = p_etablissement_id;
    v_target := 'etablissement';
    v_target_id := p_etablissement_id;
  ELSE
    SELECT taux_commission_negocie INTO v_old_taux
    FROM groupes_sante WHERE id = p_groupe_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Groupe introuvable');
    END IF;
    UPDATE groupes_sante SET taux_commission_negocie = p_nouveau_taux WHERE id = p_groupe_id;
    v_target := 'groupe';
    v_target_id := p_groupe_id;
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'TAUX_COMMISSION_MODIFIE',
    p_type_ressource := v_target,
    p_id_ressource := v_target_id,
    p_details := jsonb_build_object(
      'old_taux', v_old_taux,
      'new_taux', p_nouveau_taux,
      'raison', p_raison,
      'note', 'Impacte uniquement les futures missions assignées (gel existant préservé)'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'cible', v_target,
    'cible_id', v_target_id,
    'ancien_taux', v_old_taux,
    'nouveau_taux', p_nouveau_taux
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_modifier_taux_commission"("p_etablissement_id" "uuid", "p_groupe_id" "uuid", "p_nouveau_taux" numeric, "p_raison" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_modifier_template_contrat"("p_template_id" "uuid", "p_contenu_html" "text", "p_nom" "text" DEFAULT NULL::"text", "p_variables" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ancien_version int;
  v_nouvelle_version int;
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  IF p_contenu_html IS NULL OR length(p_contenu_html) < 50 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CONTENU_TROP_COURT',
                                'error', 'Le contenu HTML doit faire au moins 50 caractères');
  END IF;

  SELECT version INTO v_ancien_version FROM public.templates_contrat WHERE id = p_template_id;
  IF v_ancien_version IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TEMPLATE_INTROUVABLE');
  END IF;

  v_nouvelle_version := v_ancien_version + 1;

  UPDATE public.templates_contrat
  SET contenu_html = p_contenu_html,
      nom = COALESCE(p_nom, nom),
      variables = COALESCE(p_variables, variables),
      version = v_nouvelle_version,
      modifie_le = now()
  WHERE id = p_template_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'template_contrat', p_template_id,
    jsonb_build_object(
      'evenement', 'TEMPLATE_CONTRAT_MODIFIE',
      'ancienne_version', v_ancien_version,
      'nouvelle_version', v_nouvelle_version,
      'taille_contenu', length(p_contenu_html)
    )
  );

  RETURN jsonb_build_object('success', true, 'version', v_nouvelle_version);
END;
$$;


ALTER FUNCTION "public"."fn_admin_modifier_template_contrat"("p_template_id" "uuid", "p_contenu_html" "text", "p_nom" "text", "p_variables" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_planning_global"("p_debut" "date", "p_fin" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'debut', p_debut,
    'fin', p_fin,
    'missions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', m.id,
        'intitule', m.intitule,
        'statut', m.statut,
        'profession_requise', m.profession_requise,
        'service', m.service,
        'debut_le', m.debut_le,
        'fin_le', m.fin_le,
        'est_urgente', m.est_urgente,
        'etablissement_nom', e.nom,
        'etablissement_ville', e.adresse_ville,
        'soignant_nom', CASE WHEN s.id IS NOT NULL THEN s.prenom || ' ' || s.nom ELSE NULL END
      ) ORDER BY m.debut_le), '[]'::jsonb)
      FROM missions m
      LEFT JOIN etablissements e ON e.id = m.etablissement_id
      LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
      WHERE m.debut_le >= p_debut::timestamptz
        AND m.debut_le < (p_fin::timestamptz + interval '1 day')
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_planning_global"("p_debut" "date", "p_fin" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_recategoriser_litige_legacy"("p_litige_id" "uuid", "p_nouveau_type" "public"."type_litige") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id       UUID := auth.uid();
  v_litige        public.litiges%ROWTYPE;
  v_ancien_type   public.type_litige;
  v_nouvelle_cat  public.categorie_litige;
BEGIN
  IF v_user_id IS NULL OR NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Admin requis.');
  END IF;

  SELECT * INTO v_litige FROM public.litiges WHERE id = p_litige_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Litige introuvable.');
  END IF;

  IF v_litige.type_legacy IS DISTINCT FROM TRUE THEN
    RETURN jsonb_build_object(
      'error', 'Ce litige n''est pas marqué legacy — recatégorisation interdite.'
    );
  END IF;

  IF v_litige.type_litige IS DISTINCT FROM 'AUTRE'::public.type_litige THEN
    RETURN jsonb_build_object(
      'error', 'Seuls les litiges legacy de type AUTRE peuvent être recatégorisés.'
    );
  END IF;

  IF p_nouveau_type IS NULL THEN
    RETURN jsonb_build_object('error', 'Nouveau type requis.');
  END IF;

  v_ancien_type := v_litige.type_litige;

  UPDATE public.litiges
     SET type_litige = p_nouveau_type,
         type_legacy = FALSE
   WHERE id = p_litige_id
  RETURNING categorie_litige INTO v_nouvelle_cat;

  PERFORM public.fn_ecrire_audit(
    v_user_id, 'ADMIN', 'LITIGE_RECATEGORISATION_LEGACY',
    'litige', p_litige_id, NULL,
    jsonb_build_object(
      'ancien_type', v_ancien_type,
      'nouveau_type', p_nouveau_type,
      'nouvelle_categorie', v_nouvelle_cat,
      'motif_original', v_litige.motif
    ),
    NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'litige_id', p_litige_id,
    'ancien_type', v_ancien_type,
    'nouveau_type', p_nouveau_type,
    'nouvelle_categorie', v_nouvelle_cat,
    'type_legacy', FALSE
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_recategoriser_litige_legacy"("p_litige_id" "uuid", "p_nouveau_type" "public"."type_litige") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_admin_recategoriser_litige_legacy"("p_litige_id" "uuid", "p_nouveau_type" "public"."type_litige") IS 'CP-LITIGES-7b-3 — recatégorise un litige legacy (type_legacy=TRUE, type_litige=AUTRE). Le trigger fn_trg_litige_mapping_categorie recalcule categorie_litige. Lève le flag legacy, audit RGPD LITIGE_RECATEGORISATION_LEGACY. Admin-only.';



CREATE OR REPLACE FUNCTION "public"."fn_admin_recherche_globale"("p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_q text := LOWER(TRIM(COALESCE(p_query, '')));
  v_vide jsonb := jsonb_build_object(
    'utilisateurs', '[]'::jsonb,
    'missions', '[]'::jsonb,
    'factures', '[]'::jsonb
  );
  v_utilisateurs jsonb;
  v_missions jsonb;
  v_factures jsonb;
BEGIN
  IF NOT est_admin() THEN RETURN v_vide; END IF;
  IF length(v_q) < 2 THEN RETURN v_vide; END IF;

  -- Utilisateurs : soignants (nom, prénom, email, téléphone) + établissements (nom)
  SELECT COALESCE(jsonb_agg(x.r), '[]'::jsonb) INTO v_utilisateurs FROM (
    SELECT jsonb_build_object(
      'id', u.id,
      'type', CASE
        WHEN s.id IS NOT NULL THEN 'soignant'
        WHEN e.id IS NOT NULL THEN 'etablissement'
        ELSE 'inconnu'
      END,
      'nom', COALESCE(s.nom, e.nom, ''),
      'prenom', COALESCE(s.prenom, ''),
      'email', u.email,
      'profession', s.profession,
      'ville', COALESCE(s.adresse_ville, e.adresse_ville)
    ) AS r
    FROM auth.users u
    LEFT JOIN soignants s ON s.id = u.id
    LEFT JOIN etablissements e ON e.id = u.id
    WHERE LOWER(u.email) LIKE v_q || '%'
       OR LOWER(COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '')) LIKE '%' || v_q || '%'
       OR LOWER(COALESCE(s.nom, '') || ' ' || COALESCE(s.prenom, '')) LIKE '%' || v_q || '%'
       OR LOWER(COALESCE(e.nom, '')) LIKE '%' || v_q || '%'
       OR COALESCE(s.telephone, '') LIKE v_q || '%'
    LIMIT 5
  ) x;

  -- Missions : intitulé, service, n° de note d'honoraires, début d'UUID, nom d'établissement
  SELECT COALESCE(jsonb_agg(x.r), '[]'::jsonb) INTO v_missions FROM (
    SELECT jsonb_build_object(
      'id', m.id,
      'intitule', m.intitule,
      'statut', m.statut,
      'etablissement', e.nom,
      'debut_le', m.debut_le,
      'profession', m.profession_requise
    ) AS r
    FROM missions m
    JOIN etablissements e ON e.id = m.etablissement_id
    WHERE LOWER(COALESCE(m.intitule, '')) LIKE '%' || v_q || '%'
       OR LOWER(COALESCE(m.service, '')) LIKE '%' || v_q || '%'
       OR LOWER(COALESCE(m.numero_note_honoraires, '')) LIKE v_q || '%'
       OR m.id::text LIKE v_q || '%'
       OR LOWER(e.nom) LIKE '%' || v_q || '%'
    ORDER BY m.debut_le DESC
    LIMIT 5
  ) x;

  -- Factures : numéro, début d'UUID, nom d'établissement
  SELECT COALESCE(jsonb_agg(x.r), '[]'::jsonb) INTO v_factures FROM (
    SELECT jsonb_build_object(
      'id', f.id,
      'numero', f.numero_facture,
      'statut', f.statut,
      'etablissement', e.nom,
      'montant_ttc', f.montant_ttc,
      'date_emission', f.date_emission,
      'type_document', f.type_document
    ) AS r
    FROM factures f
    JOIN etablissements e ON e.id = f.etablissement_id
    WHERE LOWER(COALESCE(f.numero_facture, '')) LIKE '%' || v_q || '%'
       OR f.id::text LIKE v_q || '%'
       OR LOWER(e.nom) LIKE '%' || v_q || '%'
    ORDER BY f.date_emission DESC NULLS LAST
    LIMIT 5
  ) x;

  RETURN jsonb_build_object(
    'utilisateurs', v_utilisateurs,
    'missions', v_missions,
    'factures', v_factures
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_recherche_globale"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_rejeter_dossier_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab public.etablissements%ROWTYPE;
  v_motif text := left(btrim(COALESCE(p_motif, '')), 1000);
  v_version_finale bigint;
  v_snapshot jsonb;
BEGIN
  IF v_uid IS NULL
     OR NOT public.est_admin_valide() THEN
    RAISE EXCEPTION 'Administrateur autorise requis'
      USING ERRCODE = '42501';
  END IF;
  IF p_etablissement_id IS NULL OR p_version_attendue IS NULL
     OR length(v_motif) < 10 THEN
    RAISE EXCEPTION 'Un motif de rejet explicite de 10 caracteres minimum est requis'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Etablissement introuvable' USING ERRCODE = 'P0002';
  END IF;
  IF v_etab.verification_source_version IS DISTINCT FROM p_version_attendue THEN
    RAISE EXCEPTION 'Le dossier a change : rechargez avant de rejeter'
      USING ERRCODE = '40001';
  END IF;

  v_snapshot := jsonb_build_object(
    'source_version', v_etab.verification_source_version,
    'siret', v_etab.siret,
    'siret_verifie', v_etab.siret_verifie,
    'finess', v_etab.finess,
    'finess_verifie', v_etab.finess_verifie,
    'representant_piece_s3_key', v_etab.representant_piece_s3_key,
    'representant_identite_verifiee', v_etab.representant_identite_verifiee,
    'justificatif_fonction_s3_key', v_etab.justificatif_fonction_s3_key,
    'justificatif_fonction_verifie', v_etab.justificatif_fonction_verifie,
    'rattachement_methode', v_etab.rattachement_methode,
    'rattachement_verifie', v_etab.rattachement_verifie,
    'contrat_service_signe', v_etab.contrat_service_signe
  );

  UPDATE public.etablissements
  SET statut_verification = 'REJETE',
      peut_publier_missions = false,
      motif_rejet = v_motif,
      verifie_le = NULL,
      verifie_par = NULL,
      modifie_le = now()
  WHERE id = p_etablissement_id;

  SELECT verification_source_version INTO v_version_finale
  FROM public.etablissements WHERE id = p_etablissement_id;

  INSERT INTO public.etablissement_preuve_audit (
    etablissement_id, preuve, evenement, acteur_id, source_version,
    source_snapshot, motif
  ) VALUES (
    p_etablissement_id, 'DOSSIER', 'REJETE', v_uid,
    v_etab.verification_source_version, v_snapshot, v_motif
  );
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'etablissement',
    p_etablissement_id,
    jsonb_build_object(
      'sous_action', 'REJET_DOSSIER_ETABLISSEMENT',
      'motif', v_motif,
      'source_snapshot', v_snapshot
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'nom', v_etab.nom,
    'verification_source_version', v_version_finale
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_rejeter_dossier_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_rejeter_etablissement"("p_etablissement_id" "uuid", "p_motif" "text" DEFAULT 'Non conforme aux critères de la plateforme'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_nom TEXT; v_motif_safe TEXT;
BEGIN
    IF NOT est_admin() THEN RETURN jsonb_build_object('error', 'Accès refusé — admin uniquement'); END IF;
    v_motif_safe := LEFT(REGEXP_REPLACE(COALESCE(NULLIF(TRIM(p_motif), ''), 'Non conforme'), '<[^>]*>', '', 'g'), 500);
    UPDATE etablissements SET statut_verification = 'REJETE', peut_publier_missions = FALSE, motif_rejet = v_motif_safe
    WHERE id = p_etablissement_id;
    SELECT COALESCE(nom, 'Inconnu') INTO v_nom FROM etablissements WHERE id = p_etablissement_id;
    INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES (auth.uid(), 'ADMIN', 'ADMIN_ACTION', 'etablissement', p_etablissement_id,
        jsonb_build_object('sous_action', 'REJET_ETABLISSEMENT', 'nom', v_nom, 'motif', v_motif_safe));
    RETURN jsonb_build_object('success', TRUE, 'message', 'Établissement rejeté : ' || v_nom);
END;
$$;


ALTER FUNCTION "public"."fn_admin_rejeter_etablissement"("p_etablissement_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_reset_test_account"("p_role" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email text;
  v_user_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  v_email := CASE p_role
    WHEN 'SOIGNANT' THEN 'playwright-soignant@jolene.app'
    WHEN 'ADMIN_ETABLISSEMENT' THEN 'playwright-etab@jolene.app'
    ELSE NULL
  END;

  IF v_email IS NULL THEN
    RETURN jsonb_build_object('error', 'Rôle invalide');
  END IF;

  SELECT id INTO v_user_id FROM auth.users WHERE email = v_email;
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Compte test introuvable, exécuter le seed d''abord');
  END IF;

  IF p_role = 'SOIGNANT' THEN
    DELETE FROM public.candidatures WHERE soignant_id = v_user_id;
    DELETE FROM public.notations_missions
    WHERE notateur_id = v_user_id OR note_id = v_user_id;
    DELETE FROM public.evaluations
    WHERE evaluateur_id = v_user_id OR evalue_id = v_user_id;
    DELETE FROM public.exclusions
    WHERE exclu_par = v_user_id OR exclu_id = v_user_id;
    DELETE FROM public.notifications WHERE destinataire_id = v_user_id;
    DELETE FROM public.parrainages WHERE filleul_id = v_user_id;
    UPDATE public.soignants SET
      score_fiabilite = 50,
      total_missions_terminees = 0,
      total_missions_annulees = 0,
      heures_cumulees = 0,
      premiere_mission_le = NULL
    WHERE id = v_user_id;
  ELSIF p_role = 'ADMIN_ETABLISSEMENT' THEN
    DELETE FROM public.candidatures WHERE mission_id IN (
      SELECT id FROM public.missions WHERE etablissement_id = v_user_id
    );
    DELETE FROM public.missions
    WHERE etablissement_id = v_user_id AND statut = 'OUVERTE';
    DELETE FROM public.notifications WHERE destinataire_id = v_user_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'role', p_role);
END;
$$;


ALTER FUNCTION "public"."fn_admin_reset_test_account"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_resoudre_alerte"("p_alerte_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  UPDATE public.alertes_systeme
     SET resolu_le = COALESCE(resolu_le, now()),
         resolu_motif = COALESCE(
           resolu_motif,
           'Résolution manuelle par un administrateur'
         ),
         details = COALESCE(details, '{}'::jsonb)
           || jsonb_build_object(
             'resolution_admin', jsonb_build_object(
               'resolu_par', auth.uid(),
               'resolu_le', now()
             )
           )
   WHERE id = p_alerte_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Alerte introuvable');
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_resoudre_alerte"("p_alerte_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_resoudre_litige"("p_litige_id" "uuid", "p_resolution" "text", "p_ajuster_heures" numeric DEFAULT NULL::numeric, "p_ajuster_taux" numeric DEFAULT NULL::numeric, "p_en_faveur_de" "text" DEFAULT 'NEUTRE'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_litige RECORD;
    v_presence RECORD;
    v_mission RECORD;
    v_nouveau_statut TEXT;
BEGIN
    IF NOT est_admin() THEN
        RETURN jsonb_build_object('error', 'Réservé aux administrateurs');
    END IF;

    SELECT * INTO v_litige FROM litiges WHERE id = p_litige_id;
    IF v_litige IS NULL THEN RETURN jsonb_build_object('error', 'Litige introuvable'); END IF;
    
    IF v_litige.statut IN ('RESOLU_ADMIN','FERME') THEN
        RETURN jsonb_build_object('error', 'Ce litige est déjà résolu');
    END IF;

    -- Déterminer le statut de résolution
    v_nouveau_statut := CASE p_en_faveur_de
        WHEN 'SOIGNANT' THEN 'RESOLU_SOIGNANT'
        WHEN 'ETABLISSEMENT' THEN 'RESOLU_ETABLISSEMENT'
        ELSE 'RESOLU_ADMIN'
    END;

    -- Ajuster les heures de présence si demandé
    IF p_ajuster_heures IS NOT NULL AND v_litige.presence_id IS NOT NULL THEN
        SELECT * INTO v_presence FROM presences WHERE id = v_litige.presence_id;
        IF v_presence.id IS NOT NULL THEN
            UPDATE presences SET 
                heures_reelles = p_ajuster_heures,
                duree_nette_min = p_ajuster_heures * 60,
                modifie_le = NOW()
            WHERE id = v_litige.presence_id;
        END IF;
    END IF;

    -- Ajuster le taux horaire de la mission si demandé
    IF p_ajuster_taux IS NOT NULL THEN
        SELECT * INTO v_mission FROM missions WHERE id = v_litige.mission_id;
        IF v_mission.id IS NOT NULL THEN
            UPDATE missions SET 
                taux_horaire_base = p_ajuster_taux,
                modifie_le = NOW()
            WHERE id = v_litige.mission_id;
            -- Le trigger dec_calculer_finance_mission recalculera automatiquement
        END IF;
    END IF;

    -- Résoudre le litige
    UPDATE litiges SET 
        statut = v_nouveau_statut,
        resolution = p_resolution,
        resolu_par = auth.uid(),
        resolu_le = NOW()
    WHERE id = p_litige_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'statut', v_nouveau_statut,
        'heures_ajustees', p_ajuster_heures IS NOT NULL,
        'taux_ajuste', p_ajuster_taux IS NOT NULL
    );
END;
$$;


ALTER FUNCTION "public"."fn_admin_resoudre_litige"("p_litige_id" "uuid", "p_resolution" "text", "p_ajuster_heures" numeric, "p_ajuster_taux" numeric, "p_en_faveur_de" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_resoudre_litige"("p_litige_id" "uuid", "p_resolution" "text", "p_en_faveur_de" "text" DEFAULT NULL::"text", "p_ajuster_heures" numeric DEFAULT NULL::numeric, "p_ajuster_taux" numeric DEFAULT NULL::numeric, "p_action_financiere" "text" DEFAULT 'AUTO'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_litige public.litiges%ROWTYPE;
  v_mission public.missions%ROWTYPE;
  v_presence public.presences%ROWTYPE;
  v_facture public.factures_honoraires%ROWTYPE;
  v_transfer public.stripe_transfers%ROWTYPE;
  v_facture_trouvee boolean := false;
  v_presence_trouvee boolean := false;
  v_transfer_trouve boolean := false;
  v_action text := upper(btrim(COALESCE(p_action_financiere, 'AUTO')));
  v_faveur text := upper(btrim(COALESCE(p_en_faveur_de, 'NEUTRE')));
  v_nouveau_statut text;
  v_heures_ref numeric;
  v_taux_ref numeric;
  v_heures_payload numeric;
  v_montant_payload numeric;
  v_heures_final numeric;
  v_taux_final numeric;
  v_nouveau_montant_ht numeric;
  v_nouveau_montant_tva numeric;
  v_nouveau_montant_ttc numeric;
  v_diff numeric;
  v_diff_tva numeric;
  v_diff_ttc numeric;
  v_payload jsonb;
  v_modifications jsonb;
  v_type_payload text;
  v_arrivee_payload timestamptz;
  v_depart_payload timestamptz;
  v_accord_remplace boolean := false;
  v_ajustement_demande boolean := false;
  v_helper_result jsonb;
  v_audit_result jsonb;
  v_regen_id bigint;
  v_regen_ids bigint[] := ARRAY[]::bigint[];
  v_nouvelle_facture_id uuid;
  v_nouveau_numero text;
  v_avoir_id uuid;
  v_avoir_numero text;
  v_mode_remboursement public.mode_remboursement_avoir;
  v_delai_stripe_j integer;
  v_delai_urssaf_j integer;
  v_regul_sociale boolean := false;
  v_rows integer;
  v_email_data jsonb;
BEGIN
  IF v_uid IS NULL OR public.est_admin() IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Admin AAL2 requis pour cette opération.');
  END IF;
  IF length(btrim(COALESCE(p_resolution, ''))) < 10
     OR length(btrim(COALESCE(p_resolution, ''))) > 5000 THEN
    RETURN jsonb_build_object(
      'error', 'La résolution doit contenir entre 10 et 5 000 caractères.'
    );
  END IF;
  IF v_faveur NOT IN ('SOIGNANT', 'ETABLISSEMENT', 'NEUTRE') THEN
    RETURN jsonb_build_object(
      'error', 'p_en_faveur_de doit être SOIGNANT, ETABLISSEMENT ou NEUTRE.'
    );
  END IF;
  IF v_action NOT IN (
    'AUTO', 'AUCUNE', 'RECALCUL', 'ANNULER_REEMETTRE', 'AVOIR'
  ) THEN
    RETURN jsonb_build_object('error', 'p_action_financiere invalide.');
  END IF;
  IF p_ajuster_heures IS NOT NULL
     AND (
       p_ajuster_heures::text IN ('NaN', 'Infinity', '-Infinity')
       OR p_ajuster_heures <= 0
       OR p_ajuster_heures > 168
     ) THEN
    RETURN jsonb_build_object(
      'error', 'Les heures ajustées doivent être finies, strictement positives et au plus égales à 168.'
    );
  END IF;
  IF p_ajuster_taux IS NOT NULL
     AND (
       p_ajuster_taux::text IN ('NaN', 'Infinity', '-Infinity')
       OR p_ajuster_taux < 0.01
       OR p_ajuster_taux > 1000
     ) THEN
    RETURN jsonb_build_object(
      'error', 'Le taux ajusté doit être fini, strictement positif et au plus égal à 1 000 €.'
    );
  END IF;

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Litige introuvable.');
  END IF;
  IF v_litige.statut NOT IN (
    'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS',
    'REVUE_ADMIN'
  ) THEN
    RETURN jsonb_build_object('error', 'Ce litige est déjà résolu ou non modifiable.');
  END IF;

  v_payload := v_litige.payload_modifications;
  IF v_payload IS NOT NULL THEN
    IF v_litige.modifications_executees IS TRUE THEN
      RETURN jsonb_build_object(
        'error', 'Les modifications de cet accord ont déjà été exécutées.'
      );
    END IF;
    IF v_litige.statut <> 'REVUE_ADMIN'
       OR v_litige.accord_soignant IS NOT TRUE
       OR v_litige.accord_etablissement IS NOT TRUE
       OR v_litige.accord_soignant_le IS NULL
       OR v_litige.accord_etablissement_le IS NULL THEN
      RETURN jsonb_build_object(
        'error', 'Un payload financier exige REVUE_ADMIN et le double accord horodaté.'
      );
    END IF;
    IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_payload->'type') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_payload->'modifications') IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_payload->'justification') IS DISTINCT FROM 'string'
       OR btrim(v_payload->>'justification') = ''
       OR length(v_payload->>'justification') > 2000
       OR v_payload - ARRAY[
         'type', 'modifications', 'justification'
       ]::text[] <> '{}'::jsonb THEN
      RETURN jsonb_build_object('error', 'Schéma de l’accord stocké invalide.');
    END IF;

    v_type_payload := v_payload->>'type';
    v_modifications := v_payload->'modifications';
    IF v_type_payload NOT IN (
      'MODIFICATION_HORAIRES', 'MODIFICATION_MONTANT', 'MIXTE'
    ) THEN
      RETURN jsonb_build_object(
        'error',
        'Ce type d’accord doit être exécuté par son validateur dédié.'
      );
    END IF;

    IF v_type_payload IN ('MODIFICATION_HORAIRES', 'MIXTE') THEN
      IF jsonb_typeof(v_modifications->'pointage_arrivee_le') IS DISTINCT FROM 'string'
         OR jsonb_typeof(v_modifications->'pointage_depart_le') IS DISTINCT FROM 'string'
         OR v_modifications
           - (CASE WHEN v_type_payload = 'MIXTE'
               THEN ARRAY[
                 'pointage_arrivee_le', 'pointage_depart_le',
                 'montant_total_corrige'
               ]::text[]
               ELSE ARRAY[
                 'pointage_arrivee_le', 'pointage_depart_le'
               ]::text[]
             END) <> '{}'::jsonb THEN
        RETURN jsonb_build_object('error', 'Horaires convenus invalides.');
      END IF;
      BEGIN
        v_arrivee_payload :=
          (v_modifications->>'pointage_arrivee_le')::timestamptz;
        v_depart_payload :=
          (v_modifications->>'pointage_depart_le')::timestamptz;
      EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
        RETURN jsonb_build_object('error', 'Format des horaires convenus invalide.');
      END;
      IF v_depart_payload <= v_arrivee_payload
         OR v_depart_payload - v_arrivee_payload > interval '7 days' THEN
        RETURN jsonb_build_object('error', 'Plage horaire convenue invalide.');
      END IF;
    END IF;

    IF v_type_payload IN ('MODIFICATION_MONTANT', 'MIXTE') THEN
      IF jsonb_typeof(v_modifications->'montant_total_corrige')
           IS DISTINCT FROM 'number'
         OR (
           v_type_payload = 'MODIFICATION_MONTANT'
           AND v_modifications - ARRAY['montant_total_corrige']::text[]
             <> '{}'::jsonb
         ) THEN
        RETURN jsonb_build_object('error', 'Montant convenu invalide.');
      END IF;
      v_montant_payload :=
        (v_modifications->>'montant_total_corrige')::numeric;
      IF v_montant_payload <= 0 OR v_montant_payload > 10000000 THEN
        RETURN jsonb_build_object('error', 'Montant convenu hors limites.');
      END IF;
    END IF;
  END IF;

  SELECT m.*
    INTO v_mission
    FROM public.missions m
   WHERE m.id = v_litige.mission_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission du litige introuvable.');
  END IF;

  IF v_litige.presence_id IS NOT NULL THEN
    SELECT p.*
      INTO v_presence
      FROM public.presences p
     WHERE p.id = v_litige.presence_id
       AND p.mission_id = v_litige.mission_id
     FOR UPDATE;
    v_presence_trouvee := FOUND;
  ELSE
    SELECT p.*
      INTO v_presence
      FROM public.presences p
     WHERE p.mission_id = v_litige.mission_id
     ORDER BY p.valide_le DESC NULLS LAST, p.cree_le DESC
     LIMIT 1
     FOR UPDATE;
    v_presence_trouvee := FOUND;
  END IF;

  IF (p_ajuster_heures IS NOT NULL
      OR v_type_payload IN ('MODIFICATION_HORAIRES', 'MIXTE'))
     AND v_presence_trouvee IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'error', 'Aucune présence verrouillable pour appliquer les heures.'
    );
  END IF;

  IF v_presence_trouvee
     AND v_type_payload IN ('MODIFICATION_HORAIRES', 'MIXTE') THEN
    v_heures_payload := round(
      GREATEST(
        0,
        EXTRACT(epoch FROM (v_depart_payload - v_arrivee_payload)) / 3600
        - COALESCE(v_presence.duree_pause_min, 0) / 60
      )::numeric,
      2
    );
    IF v_heures_payload <= 0 OR v_heures_payload > 168 THEN
      RETURN jsonb_build_object('error', 'Durée nette convenue hors limites.');
    END IF;
  END IF;

  IF v_litige.facture_id IS NOT NULL THEN
    SELECT f.*
      INTO v_facture
      FROM public.factures_honoraires f
     WHERE f.id = v_litige.facture_id
     FOR UPDATE;
    v_facture_trouvee := FOUND;
  ELSE
    SELECT f.*
      INTO v_facture
      FROM public.factures_honoraires f
     WHERE f.mission_id = v_litige.mission_id
       AND f.type_document = 'FACTURE'
       AND f.statut_litige = 'EN_ATTENTE_LITIGE'
     ORDER BY f.date_emission ASC, f.id
     LIMIT 1
     FOR UPDATE;
    v_facture_trouvee := FOUND;
  END IF;

  IF v_facture_trouvee
     AND (
       v_facture.mission_id IS DISTINCT FROM v_litige.mission_id
       OR v_facture.soignant_id IS DISTINCT FROM v_litige.soignant_id
       OR v_facture.etablissement_id IS DISTINCT FROM v_litige.etablissement_id
       OR v_facture.type_document <> 'FACTURE'
     ) THEN
    RETURN jsonb_build_object(
      'error', 'La facture liée ne correspond pas aux parties et à la mission du litige.'
    );
  END IF;

  -- Le verrou SQL couvre aussi la tentative Connect locale. Une Checkout
  -- Session ne peut pas être expirée de façon atomique en PostgreSQL : tant
  -- que son état n'est pas explicitement ECHOUE/ANNULEE/REMBOURSE, on refuse
  -- de remplacer le document qui a servi à calculer son montant.
  SELECT st.*
    INTO v_transfer
    FROM public.stripe_transfers st
   WHERE st.mission_id = v_litige.mission_id
   ORDER BY st.cree_le DESC, st.id
   LIMIT 1
   FOR UPDATE;
  v_transfer_trouve := FOUND;

  v_ajustement_demande := v_payload IS NOT NULL
    OR p_ajuster_heures IS NOT NULL
    OR p_ajuster_taux IS NOT NULL;
  IF v_ajustement_demande AND v_facture_trouvee IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'error', 'Aucune facture verrouillable pour appliquer cet ajustement.'
    );
  END IF;

  IF v_presence_trouvee THEN
    v_heures_ref := COALESCE(
      v_presence.heures_ajustees_litige,
      v_presence.heures_reelles
    );
  END IF;
  v_taux_ref := v_mission.taux_horaire_base;
  IF v_facture_trouvee AND (v_taux_ref IS NULL OR v_taux_ref = 0) THEN
    v_taux_ref := CASE
      WHEN v_heures_ref > 0 THEN v_facture.montant_ht / v_heures_ref
      ELSE NULL
    END;
  END IF;
  IF v_facture_trouvee AND v_heures_ref IS NULL AND v_taux_ref > 0 THEN
    v_heures_ref := v_facture.montant_ht / v_taux_ref;
  END IF;

  v_heures_final := COALESCE(
    p_ajuster_heures, v_heures_payload, v_heures_ref
  );
  v_taux_final := COALESCE(p_ajuster_taux, v_taux_ref);

  IF v_payload IS NOT NULL THEN
    v_accord_remplace := p_ajuster_taux IS NOT NULL
      OR (
        p_ajuster_heures IS NOT NULL
        AND (
          v_heures_payload IS NULL
          OR abs(p_ajuster_heures - v_heures_payload) > 0.005
        )
      );
  END IF;

  IF v_montant_payload IS NOT NULL AND v_accord_remplace IS NOT TRUE THEN
    v_nouveau_montant_ht := round(v_montant_payload, 2);
  ELSIF v_ajustement_demande THEN
    IF v_heures_final IS NULL OR v_heures_final <= 0
       OR v_heures_final > 168
       OR v_taux_final IS NULL OR v_taux_final < 0.01
       OR v_taux_final > 1000 THEN
      RETURN jsonb_build_object(
        'error', 'Heures ou taux de référence absents ou hors limites.'
      );
    END IF;
    v_nouveau_montant_ht := round(v_heures_final * v_taux_final, 2);
  ELSIF v_facture_trouvee THEN
    v_nouveau_montant_ht := v_facture.montant_ht;
  END IF;

  -- montant_total_corrige désigne bien le total TTC affiché aux parties.
  -- On dérive le HT et la TVA au lieu d'ajouter une seconde fois la TVA.
  IF v_montant_payload IS NOT NULL AND v_accord_remplace IS NOT TRUE THEN
    v_nouveau_montant_ttc := round(v_montant_payload, 2);
    v_nouveau_montant_ht := round(
      v_nouveau_montant_ttc
        / (1 + COALESCE(v_facture.taux_tva, 0) / 100),
      2
    );
    v_nouveau_montant_tva :=
      v_nouveau_montant_ttc - v_nouveau_montant_ht;
  ELSIF v_nouveau_montant_ht IS NOT NULL THEN
    v_nouveau_montant_tva := round(
      v_nouveau_montant_ht * COALESCE(v_facture.taux_tva, 0) / 100,
      2
    );
    v_nouveau_montant_ttc :=
      v_nouveau_montant_ht + v_nouveau_montant_tva;
  END IF;

  IF v_nouveau_montant_ht IS NOT NULL
     AND (
       v_nouveau_montant_ht <= 0 OR v_nouveau_montant_ht > 10000000
       OR v_nouveau_montant_ttc <= 0
       OR v_nouveau_montant_ttc > 10000000
     ) THEN
    RETURN jsonb_build_object('error', 'Montant final hors limites.');
  END IF;

  IF v_action = 'AUTO' THEN
    IF v_ajustement_demande IS NOT TRUE THEN
      v_action := 'AUCUNE';
    ELSIF v_facture.statut = 'BROUILLON' THEN
      v_action := 'RECALCUL';
    ELSIF v_facture.statut IN ('EMISE', 'EN_RETARD') THEN
      v_action := 'ANNULER_REEMETTRE';
    ELSIF v_facture.statut = 'PAYEE' THEN
      v_action := 'AVOIR';
    ELSE
      RETURN jsonb_build_object(
        'error', 'Le statut de la facture ne permet aucune action financière sûre.'
      );
    END IF;
  END IF;

  IF v_action = 'AUCUNE' AND v_ajustement_demande THEN
    RETURN jsonb_build_object(
      'error', 'AUCUNE est interdite lorsqu’un ajustement ou un accord financier existe.'
    );
  END IF;
  IF v_action <> 'AUCUNE' AND v_facture_trouvee IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Action financière sans facture interdite.');
  END IF;
  IF v_action IN ('RECALCUL', 'ANNULER_REEMETTRE')
     AND v_transfer_trouve
     AND v_transfer.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
     AND (
       v_transfer.stripe_checkout_session_id IS NOT NULL
       OR v_transfer.statut IN (
         'EN_ATTENTE', 'CHARGE_REUSSI', 'TRANSFERE', 'PAYE'
       )
     ) THEN
    RETURN jsonb_build_object(
      'error',
      'Une tentative ou un paiement Stripe Connect est encore actif. Expirez ou réconciliez-le avant de modifier la facture.'
    );
  END IF;
  IF v_action = 'RECALCUL' AND v_facture.statut <> 'BROUILLON' THEN
    RETURN jsonb_build_object('error', 'RECALCUL exige une facture BROUILLON.');
  END IF;
  IF v_action = 'ANNULER_REEMETTRE'
     AND v_facture.statut NOT IN ('EMISE', 'EN_RETARD') THEN
    RETURN jsonb_build_object(
      'error', 'ANNULER_REEMETTRE exige une facture EMISE ou EN_RETARD.'
    );
  END IF;
  IF v_action = 'AVOIR' AND v_facture.statut <> 'PAYEE' THEN
    RETURN jsonb_build_object('error', 'AVOIR exige une facture PAYEE.');
  END IF;
  IF v_action <> 'AUCUNE'
     AND v_nouveau_montant_ttc IS NOT DISTINCT FROM v_facture.montant_ttc THEN
    RETURN jsonb_build_object(
      'error', 'L’ajustement ne change pas le montant de la facture.'
    );
  END IF;

  IF v_action = 'ANNULER_REEMETTRE' AND EXISTS (
    SELECT 1
      FROM public.factures_honoraires enfant
     WHERE enfant.facture_precedente_id = v_facture.id
       AND enfant.type_document = 'FACTURE'
       AND enfant.statut NOT IN (
         'ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION'
       )
  ) THEN
    RETURN jsonb_build_object('error', 'Une facture de remplacement existe déjà.');
  END IF;
  IF v_action = 'AVOIR' AND EXISTS (
    SELECT 1
      FROM public.factures_honoraires enfant
     WHERE enfant.facture_precedente_id = v_facture.id
       AND enfant.type_document = 'AVOIR'
       AND enfant.statut NOT IN (
         'ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION'
       )
  ) THEN
    RETURN jsonb_build_object('error', 'Un avoir actif existe déjà pour cette facture.');
  END IF;

  IF v_action = 'RECALCUL' THEN
    UPDATE public.factures_honoraires
       SET montant_ht = v_nouveau_montant_ht,
           montant_tva = v_nouveau_montant_tva,
           montant_ttc = v_nouveau_montant_ttc,
           statut_litige = 'LITIGE_RESOLU_AJUSTE',
           pdf_a_regenerer = true
     WHERE id = v_facture.id
       AND statut = 'BROUILLON';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Recalcul concurrent refusé';
    END IF;
    v_regen_id := public.fn_trigger_regen_pdf_immediate(v_facture.id);
    IF v_regen_id IS NOT NULL THEN
      IF v_regen_id <= 0 THEN
        RAISE EXCEPTION 'Identifiant de régénération PDF invalide';
      END IF;
      v_regen_ids := array_append(v_regen_ids, v_regen_id);
    END IF;

  ELSIF v_action = 'ANNULER_REEMETTRE' THEN
    UPDATE public.factures_honoraires
       SET statut = 'REMPLACEE',
           statut_litige = 'LITIGE_RESOLU_AJUSTE'
     WHERE id = v_facture.id
       AND statut IN ('EMISE', 'EN_RETARD');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Remplacement concurrent refusé';
    END IF;

    v_nouveau_numero := public.next_invoice_number(v_facture.soignant_id);
    IF btrim(COALESCE(v_nouveau_numero, '')) = '' THEN
      RAISE EXCEPTION 'Numéro de facture de remplacement invalide';
    END IF;
    INSERT INTO public.factures_honoraires (
      soignant_id, etablissement_id, mission_id,
      numero_facture, montant_ht, montant_tva, montant_ttc,
      taux_tva, exoneration_tva, date_emission, date_echeance,
      statut, mandat_version, type_document, facture_precedente_id,
      statut_litige, litige_id, pdf_a_regenerer,
      periode_debut, periode_fin, numero_semaine_iso, annee_iso,
      est_facture_finale_mission
    ) VALUES (
      v_facture.soignant_id, v_facture.etablissement_id,
      v_facture.mission_id, v_nouveau_numero, v_nouveau_montant_ht,
      v_nouveau_montant_tva, v_nouveau_montant_ttc,
      v_facture.taux_tva, v_facture.exoneration_tva,
      CURRENT_DATE, CURRENT_DATE + 30, 'BROUILLON',
      v_facture.mandat_version, 'FACTURE', v_facture.id,
      'LITIGE_RESOLU_AJUSTE', p_litige_id, true,
      v_facture.periode_debut, v_facture.periode_fin,
      v_facture.numero_semaine_iso, v_facture.annee_iso,
      v_facture.est_facture_finale_mission
    )
    RETURNING id INTO v_nouvelle_facture_id;
    IF v_nouvelle_facture_id IS NULL THEN
      RAISE EXCEPTION 'Facture de remplacement non créée';
    END IF;
    v_regen_id :=
      public.fn_trigger_regen_pdf_immediate(v_nouvelle_facture_id);
    IF v_regen_id IS NOT NULL THEN
      IF v_regen_id <= 0 THEN
        RAISE EXCEPTION 'Identifiant de régénération PDF invalide';
      END IF;
      v_regen_ids := array_append(v_regen_ids, v_regen_id);
    END IF;

  ELSIF v_action = 'AVOIR' THEN
    v_diff := round(v_facture.montant_ht - v_nouveau_montant_ht, 2);
    v_diff_tva := round(v_facture.montant_tva - v_nouveau_montant_tva, 2);
    v_diff_ttc := round(v_facture.montant_ttc - v_nouveau_montant_ttc, 2);
    IF v_diff <= 0 OR v_diff_tva < 0 OR v_diff_ttc <= 0
       OR v_diff_ttc > v_facture.montant_ttc THEN
      RETURN jsonb_build_object(
        'error', 'Un avoir exige un montant corrigé strictement inférieur au montant payé.'
      );
    END IF;

    SELECT COALESCE(pl.valeur::integer, 30)
      INTO v_delai_stripe_j
      FROM public.parametres_litiges pl
     WHERE pl.cle = 'delai_stripe_refund_auto_j';
    v_delai_stripe_j := COALESCE(v_delai_stripe_j, 30);
    IF v_transfer_trouve THEN
      -- Un remboursement Connect doit aussi reprendre le transfer et la
      -- commission. La queue legacy ne sait pas garantir cette atomicité.
      v_mode_remboursement := 'VIREMENT_MANUEL';
    ELSIF v_facture.stripe_payment_intent_id IS NOT NULL
       AND v_facture.date_paiement IS NOT NULL
       AND v_facture.date_paiement
         > CURRENT_DATE - make_interval(days => v_delai_stripe_j) THEN
      v_mode_remboursement := 'AUTO_STRIPE';
    ELSE
      v_mode_remboursement := 'VIREMENT_MANUEL';
    END IF;

    v_avoir_numero := public.next_avoir_number(v_facture.soignant_id);
    IF btrim(COALESCE(v_avoir_numero, '')) = '' THEN
      RAISE EXCEPTION 'Numéro d’avoir invalide';
    END IF;
    INSERT INTO public.factures_honoraires (
      soignant_id, etablissement_id, mission_id,
      numero_facture, montant_ht, montant_tva, montant_ttc,
      taux_tva, exoneration_tva, date_emission, date_echeance,
      statut, mandat_version, type_document, facture_precedente_id,
      statut_litige, litige_id, mode_remboursement, pdf_a_regenerer,
      periode_debut, periode_fin, numero_semaine_iso, annee_iso,
      est_facture_finale_mission
    ) VALUES (
      v_facture.soignant_id, v_facture.etablissement_id,
      v_facture.mission_id, v_avoir_numero, v_diff,
      v_diff_tva, v_diff_ttc,
      v_facture.taux_tva, v_facture.exoneration_tva,
      CURRENT_DATE, CURRENT_DATE, 'EMISE', v_facture.mandat_version,
      'AVOIR', v_facture.id, 'LITIGE_RESOLU_AJUSTE', p_litige_id,
      v_mode_remboursement, true, v_facture.periode_debut,
      v_facture.periode_fin, v_facture.numero_semaine_iso,
      v_facture.annee_iso, v_facture.est_facture_finale_mission
    )
    RETURNING id INTO v_avoir_id;
    IF v_avoir_id IS NULL THEN
      RAISE EXCEPTION 'Avoir non créé';
    END IF;

    UPDATE public.factures_honoraires
       SET statut_litige = 'LITIGE_RESOLU_AJUSTE'
     WHERE id = v_facture.id
       AND statut = 'PAYEE';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Avoir concurrent refusé';
    END IF;

    IF v_mode_remboursement = 'AUTO_STRIPE' THEN
      INSERT INTO public.stripe_refunds_queue (
        avoir_id, facture_origine_id, stripe_payment_intent_id, montant_cts
      ) VALUES (
        v_avoir_id, v_facture.id, v_facture.stripe_payment_intent_id,
        round(v_diff_ttc * 100)::integer
      );
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'Remboursement Stripe non mis en file';
      END IF;
    END IF;

    v_regen_id := public.fn_trigger_regen_pdf_immediate(v_avoir_id);
    IF v_regen_id IS NOT NULL THEN
      IF v_regen_id <= 0 THEN
        RAISE EXCEPTION 'Identifiant de régénération PDF invalide';
      END IF;
      v_regen_ids := array_append(v_regen_ids, v_regen_id);
    END IF;
  END IF;

  -- Les changements de données source arrivent après l'effet comptable. Toute
  -- erreur lève une exception et annule aussi facture/avoir dans la transaction.
  IF v_type_payload IN ('MODIFICATION_HORAIRES', 'MIXTE')
     AND (
       p_ajuster_heures IS NULL
       OR abs(p_ajuster_heures - v_heures_payload) <= 0.005
     ) THEN
    v_helper_result := public.fn_modifier_horaires_presence(
      v_presence.id,
      v_arrivee_payload,
      v_depart_payload,
      v_payload->>'justification'
    );
    IF COALESCE(v_helper_result @> '{"success": true}'::jsonb, false)
         IS NOT TRUE THEN
      RAISE EXCEPTION 'Échec atomique de la correction des horaires: %',
        COALESCE(v_helper_result->>'error', 'résultat interne invalide');
    END IF;
    UPDATE public.presences
       SET heures_ajustees_litige = NULL,
           ajustement_litige_id = p_litige_id,
           motif_litige = left(
             'Accord litige : ' || (v_payload->>'justification'),
             2000
           ),
           modifie_le = now()
     WHERE id = v_presence.id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Traçabilité de la correction des horaires non appliquée';
    END IF;
  ELSIF p_ajuster_heures IS NOT NULL THEN
    UPDATE public.presences
       SET heures_ajustees_litige = p_ajuster_heures,
           ajustement_litige_id = p_litige_id,
           motif_litige = left(
             'Décision admin litige : ' || btrim(p_resolution),
             2000
           ),
           modifie_le = now()
     WHERE id = v_presence.id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Ajustement de présence non appliqué';
    END IF;
  END IF;

  IF p_ajuster_taux IS NOT NULL THEN
    UPDATE public.missions
       SET taux_horaire_base = p_ajuster_taux,
           modifie_le = now()
     WHERE id = v_mission.id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Ajustement de taux non appliqué';
    END IF;
  END IF;

  IF v_action IN ('RECALCUL', 'ANNULER_REEMETTRE', 'AVOIR') THEN
    UPDATE public.missions
       SET commission_a_recalculer = true
     WHERE id = v_mission.id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Marquage de recalcul de commission non appliqué';
    END IF;
  END IF;

  IF (p_ajuster_heures IS NOT NULL OR v_heures_payload IS NOT NULL)
     AND v_facture_trouvee
     AND v_action IN ('ANNULER_REEMETTRE', 'AVOIR') THEN
    SELECT COALESCE(pl.valeur::integer, 3) * 30
      INTO v_delai_urssaf_j
      FROM public.parametres_litiges pl
     WHERE pl.cle = 'delai_notif_urssaf_mois';
    v_delai_urssaf_j := COALESCE(v_delai_urssaf_j, 90);
    IF CURRENT_DATE - v_facture.date_emission > v_delai_urssaf_j THEN
      UPDATE public.missions
         SET regularisation_sociale_requise = true
       WHERE id = v_mission.id;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'Régularisation sociale non marquée';
      END IF;
      v_regul_sociale := true;
    END IF;
  END IF;

  v_nouveau_statut := CASE v_faveur
    WHEN 'SOIGNANT' THEN 'RESOLU_SOIGNANT'
    WHEN 'ETABLISSEMENT' THEN 'RESOLU_ETABLISSEMENT'
    ELSE 'RESOLU_ADMIN'
  END;

  UPDATE public.litiges
     SET statut = v_nouveau_statut,
         resolution = btrim(p_resolution),
         resolu_par = v_uid,
         resolu_le = now(),
         modifications_executees = CASE
           WHEN v_payload IS NOT NULL THEN true
           ELSE modifications_executees
         END,
         modifications_executees_a = CASE
           WHEN v_payload IS NOT NULL THEN now()
           ELSE modifications_executees_a
         END,
         modifications_executees_par = CASE
           WHEN v_payload IS NOT NULL THEN v_uid
           ELSE modifications_executees_par
         END
   WHERE id = p_litige_id
     AND statut IN (
       'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS',
       'REVUE_ADMIN'
     );
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Résolution concurrente refusée';
  END IF;

  IF v_accord_remplace THEN
    v_audit_result := public.fn_ecrire_audit_safe(
      p_acteur_id := v_uid,
      p_type_acteur := 'ADMIN_PLATEFORME',
      p_action := 'LITIGE_RESOLUTION',
      p_type_ressource := 'litige',
      p_id_ressource := p_litige_id,
      p_details := jsonb_build_object(
        'evenement', 'LITIGE_ACCORD_REMPLACE_PAR_DECISION_ADMIN',
        'accord_payload_remplace', v_payload,
        'accord_soignant_le', v_litige.accord_soignant_le,
        'accord_etablissement_le', v_litige.accord_etablissement_le,
        'resolution_admin', btrim(p_resolution),
        'heures_admin', p_ajuster_heures,
        'taux_admin', p_ajuster_taux,
        'montant_final_ht', v_nouveau_montant_ht,
        'montant_final_ttc', v_nouveau_montant_ttc,
        'action_financiere', v_action
      )
    );
    IF COALESCE(v_audit_result @> '{"success": true}'::jsonb, false)
         IS NOT TRUE THEN
      RAISE EXCEPTION 'Audit du remplacement d’accord non écrit: %',
        COALESCE(v_audit_result->>'error', 'résultat interne invalide');
    END IF;
  END IF;

  v_audit_result := public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'LITIGE_RESOLUTION',
    p_type_ressource := 'litige',
    p_id_ressource := p_litige_id,
    p_details := jsonb_build_object(
      'evenement', 'LITIGE_RESOLUTION_FINANCIERE',
      'action_financiere', v_action,
      'en_faveur_de', v_faveur,
      'accord_payload_applique', CASE
        WHEN v_payload IS NOT NULL AND NOT v_accord_remplace THEN v_payload
        ELSE NULL
      END,
      'accord_remplace', v_accord_remplace,
      'heures_final', v_heures_final,
      'taux_final', v_taux_final,
      'montant_avant_ht', CASE
        WHEN v_facture_trouvee THEN v_facture.montant_ht ELSE NULL
      END,
      'montant_avant_ttc', CASE
        WHEN v_facture_trouvee THEN v_facture.montant_ttc ELSE NULL
      END,
      'montant_apres_ht', v_nouveau_montant_ht,
      'montant_apres_ttc', v_nouveau_montant_ttc,
      'facture_id', CASE WHEN v_facture_trouvee THEN v_facture.id ELSE NULL END,
      'nouvelle_facture_id', v_nouvelle_facture_id,
      'avoir_id', v_avoir_id,
      'mode_remboursement', v_mode_remboursement,
      'regularisation_sociale_requise', v_regul_sociale,
      'regen_pdf_request_ids', to_jsonb(v_regen_ids)
    )
  );
  IF COALESCE(v_audit_result @> '{"success": true}'::jsonb, false)
       IS NOT TRUE THEN
    RAISE EXCEPTION 'Audit de résolution non écrit: %',
      COALESCE(v_audit_result->>'error', 'résultat interne invalide');
  END IF;

  IF v_action IN ('RECALCUL', 'ANNULER_REEMETTRE', 'AVOIR') THEN
    v_email_data := jsonb_build_object(
      'action_financiere', v_action,
      'en_faveur_de', v_faveur,
      'resolution', btrim(p_resolution),
      'numero_facture', v_facture.numero_facture,
      'numero_nouvelle', v_nouveau_numero,
      'numero_avoir', v_avoir_numero,
      'montant_avant', v_facture.montant_ht,
      'montant_apres', v_nouveau_montant_ht,
      'montant_avant_ttc', v_facture.montant_ttc,
      'montant_apres_ttc', v_nouveau_montant_ttc
    );
    PERFORM public.fn_litige_push_notification(
      v_litige.soignant_id,
      'SOIGNANT',
      'LITIGE_RESOLU_AJUSTE',
      'Litige résolu — ajustement appliqué',
      'La résolution du litige a été appliquée à la facturation.',
      p_litige_id,
      v_email_data
    );
    PERFORM public.fn_litige_push_notification(
      v_litige.etablissement_id,
      'ETABLISSEMENT',
      'LITIGE_RESOLU_AJUSTE',
      'Litige résolu — ajustement appliqué',
      'La résolution du litige a été appliquée à la facturation.',
      p_litige_id,
      v_email_data
    );
    IF v_action = 'AVOIR' AND v_avoir_id IS NOT NULL THEN
      PERFORM public.fn_litige_push_notification(
        v_litige.soignant_id,
        'SOIGNANT',
        'AVOIR_EMIS',
        'Avoir ' || COALESCE(v_avoir_numero, '') || ' émis',
        'Un avoir a été émis suite à la résolution du litige.',
        p_litige_id,
        jsonb_build_object(
          'avoir_id', v_avoir_id,
          'numero_avoir', v_avoir_numero,
          'numero_facture_origine', v_facture.numero_facture,
          'montant_avoir_ht', v_diff,
          'montant_avoir_ttc', v_diff_ttc,
          'mode_remboursement', v_mode_remboursement,
          'mode_remboursement_texte', CASE v_mode_remboursement::text
            WHEN 'AUTO_STRIPE' THEN
              'Remboursement Stripe automatique (2 à 5 jours ouvrés)'
            WHEN 'VIREMENT_MANUEL' THEN
              'Remboursement manuel après vérification de la reprise des fonds'
            ELSE 'Mode de remboursement à confirmer'
          END
        )
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'action_financiere', v_action,
    'statut', v_nouveau_statut,
    'facture_id', CASE WHEN v_facture_trouvee THEN v_facture.id ELSE NULL END,
    'nouvelle_facture_id', v_nouvelle_facture_id,
    'avoir_id', v_avoir_id,
    'avoir_numero', v_avoir_numero,
    'mode_remboursement', v_mode_remboursement,
    'regularisation_sociale_requise', v_regul_sociale,
    'regen_pdf_request_ids', to_jsonb(v_regen_ids),
    'heures_final', v_heures_final,
    'taux_final', v_taux_final,
    'montant_final_ht', v_nouveau_montant_ht,
    'montant_final_ttc', v_nouveau_montant_ttc,
    'accord_remplace', v_accord_remplace
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_resoudre_litige"("p_litige_id" "uuid", "p_resolution" "text", "p_en_faveur_de" "text", "p_ajuster_heures" numeric, "p_ajuster_taux" numeric, "p_action_financiere" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_admin_resoudre_litige"("p_litige_id" "uuid", "p_resolution" "text", "p_en_faveur_de" "text", "p_ajuster_heures" numeric, "p_ajuster_taux" numeric, "p_action_financiere" "text") IS 'Résolution admin AAL2 atomique. Verrouille litige/mission/présence/facture, applique la matrice de statuts comptables, protège contre les doubles documents et trace tout remplacement d’un accord accepté.';



CREATE OR REPLACE FUNCTION "public"."fn_admin_resume_alertes_pointage"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_kpi jsonb;
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  SELECT jsonb_build_object(
    -- Périodes : 24h / 7j / 30j pour chaque type d'alerte
    'teleportations_24h', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE type_alerte = 'TELEPORTATION_DETECTED' AND cree_le > NOW() - INTERVAL '24 hours'),
    'teleportations_7j', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE type_alerte = 'TELEPORTATION_DETECTED' AND cree_le > NOW() - INTERVAL '7 days'),
    'teleportations_30j', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE type_alerte = 'TELEPORTATION_DETECTED' AND cree_le > NOW() - INTERVAL '30 days'),

    'mock_gps_24h', (SELECT COUNT(*) FROM public.presences
        WHERE (arrivee_mock_detected = true OR depart_mock_detected = true)
          AND modifie_le > NOW() - INTERVAL '24 hours'),
    'mock_gps_7j', (SELECT COUNT(*) FROM public.presences
        WHERE (arrivee_mock_detected = true OR depart_mock_detected = true)
          AND modifie_le > NOW() - INTERVAL '7 days'),
    'mock_gps_30j', (SELECT COUNT(*) FROM public.presences
        WHERE (arrivee_mock_detected = true OR depart_mock_detected = true)
          AND modifie_le > NOW() - INTERVAL '30 days'),

    'coherence_24h', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE type_alerte = 'POINTAGE_INCOHERENT' AND cree_le > NOW() - INTERVAL '24 hours'),
    'coherence_7j', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE type_alerte = 'POINTAGE_INCOHERENT' AND cree_le > NOW() - INTERVAL '7 days'),
    'coherence_30j', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE type_alerte = 'POINTAGE_INCOHERENT' AND cree_le > NOW() - INTERVAL '30 days'),

    'qr_gps_eloigne_24h', (SELECT COUNT(*) FROM public.journaux_audit
        WHERE action = 'POINTAGE' AND details->>'evenement' = 'QR_SCAN_GPS_ELOIGNE'
          AND cree_le > NOW() - INTERVAL '24 hours'),
    'qr_gps_eloigne_7j', (SELECT COUNT(*) FROM public.journaux_audit
        WHERE action = 'POINTAGE' AND details->>'evenement' = 'QR_SCAN_GPS_ELOIGNE'
          AND cree_le > NOW() - INTERVAL '7 days'),
    'qr_gps_eloigne_30j', (SELECT COUNT(*) FROM public.journaux_audit
        WHERE action = 'POINTAGE' AND details->>'evenement' = 'QR_SCAN_GPS_ELOIGNE'
          AND cree_le > NOW() - INTERVAL '30 days'),

    'total_ouvertes', (SELECT COUNT(*) FROM public.alertes_systeme
        WHERE resolu_le IS NULL
          AND type_alerte IN ('TELEPORTATION_DETECTED', 'POINTAGE_INCOHERENT'))
  ) INTO v_kpi;

  RETURN jsonb_build_object('success', true, 'kpis', v_kpi);
END;
$$;


ALTER FUNCTION "public"."fn_admin_resume_alertes_pointage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_stripe_connect_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ DECLARE v_total_comptes integer := 0; v_complets integer := 0; v_en_cours integer := 0; v_total_verse_soignants numeric := 0; v_en_attente_soignants numeric := 0; v_total_commission_jolene numeric := 0; v_en_attente_commission numeric := 0; v_volume_total numeric := 0; v_volume_en_attente numeric := 0; BEGIN IF NOT est_admin() THEN RETURN '{"error":"Accès réservé aux administrateurs"}'::JSONB; END IF; SELECT COUNT(*) INTO v_total_comptes FROM stripe_connect_onboarding; SELECT COUNT(*) INTO v_complets FROM stripe_connect_onboarding WHERE statut = 'COMPLETE'; SELECT COUNT(*) INTO v_en_cours FROM stripe_connect_onboarding WHERE statut IN ('PENDING', 'EN_COURS'); SELECT COALESCE(SUM(montant_soignant), 0) INTO v_total_verse_soignants FROM stripe_transfers WHERE statut = 'COMPLETED'; SELECT COALESCE(SUM(montant_soignant), 0) INTO v_en_attente_soignants FROM stripe_transfers WHERE statut = 'PENDING'; SELECT COALESCE(SUM(montant_commission), 0) INTO v_total_commission_jolene FROM stripe_transfers WHERE statut = 'COMPLETED'; SELECT COALESCE(SUM(montant_commission), 0) INTO v_en_attente_commission FROM stripe_transfers WHERE statut = 'PENDING'; SELECT COALESCE(SUM(montant_total), 0) INTO v_volume_total FROM stripe_transfers WHERE statut = 'COMPLETED'; SELECT COALESCE(SUM(montant_total), 0) INTO v_volume_en_attente FROM stripe_transfers WHERE statut = 'PENDING'; RETURN jsonb_build_object('total_comptes', v_total_comptes, 'complets', v_complets, 'en_cours', v_en_cours, 'total_verse_soignants', v_total_verse_soignants, 'en_attente_soignants', v_en_attente_soignants, 'total_commission_jolene', v_total_commission_jolene, 'en_attente_commission', v_en_attente_commission, 'volume_total', v_volume_total, 'volume_en_attente', v_volume_en_attente); END; $$;


ALTER FUNCTION "public"."fn_admin_stripe_connect_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_supprimer_compte_test"("p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_email text := lower(trim(p_email));
  v_id uuid;
  v_rpps text;
  v_nb_soignant int := 0;
  v_nb_auth int := 0;
BEGIN
  -- Autorisé : admin authentifié OU contexte service_role / éditeur SQL (auth.uid() NULL).
  IF NOT fn_est_contexte_cron_ou_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Réservé à l''administrateur.');
  END IF;

  SELECT id, numero_rpps INTO v_id, v_rpps FROM soignants WHERE lower(email) = v_email;

  -- Supprime la ligne soignant (libère le RPPS via l'unicité) puis le compte auth (libère l'email).
  DELETE FROM soignants WHERE lower(email) = v_email;
  GET DIAGNOSTICS v_nb_soignant = ROW_COUNT;

  DELETE FROM auth.users WHERE lower(email) = v_email;
  GET DIAGNOSTICS v_nb_auth = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'email', v_email,
    'soignant_id', v_id,
    'rpps_libere', v_rpps,
    'lignes_soignant_supprimees', v_nb_soignant,
    'comptes_auth_supprimes', v_nb_auth
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_supprimer_compte_test"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_suspendre_utilisateur"("p_table" "text", "p_id" "uuid", "p_suspendre" boolean DEFAULT true, "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_nom text;
  v_motif text := NULLIF(btrim(COALESCE(p_motif, '')), '');
  v_maintenant timestamptz := transaction_timestamp();
  v_membres integer := 0;
  v_auth_trouve boolean := false;
  v_auth_state_existe boolean := false;
  v_banned_until_courant timestamptz;
  v_banned_until_pose timestamptz;
  v_pose_precedente timestamptz;
  v_peut_publier_avant boolean := false;
  v_supprime_le timestamptz;
  v_est_suppression_rgpd boolean := false;
  v_provenance_suspension boolean := false;
BEGIN
  IF NOT public.est_admin_valide() THEN
    RETURN jsonb_build_object('error', 'Accès refusé — admin AAL2 uniquement');
  END IF;
  IF p_table NOT IN ('soignants', 'etablissements') THEN
    RETURN jsonb_build_object('error', 'Table invalide');
  END IF;
  IF p_id IS NULL OR p_suspendre IS NULL THEN
    RETURN jsonb_build_object('error', 'Paramètres de suspension invalides');
  END IF;
  IF p_suspendre AND (v_motif IS NULL OR char_length(v_motif) < 3) THEN
    RETURN jsonb_build_object('error', 'Motif obligatoire (3 caractères minimum)');
  END IF;
  IF v_motif IS NOT NULL AND char_length(v_motif) > 1000 THEN
    RETURN jsonb_build_object('error', 'Motif trop long (1000 caractères maximum)');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_table || ':' || p_id::text, 0));

  IF p_table = 'soignants' THEN
    SELECT
      COALESCE(s.prenom || ' ' || s.nom, 'Inconnu'),
      s.supprime_le,
      (
        lower(COALESCE(s.email, '')) LIKE '%@supprime.jolene.app'
        OR EXISTS (
          SELECT 1 FROM public.journaux_audit j
          WHERE j.id_ressource = s.id
            AND j.action = 'RGPD_SUPPRESSION_COMPTE'
        )
      )
    INTO v_nom, v_supprime_le, v_est_suppression_rgpd
    FROM public.soignants s
    WHERE s.id = p_id
    FOR UPDATE;
  ELSE
    SELECT
      COALESCE(e.nom, 'Inconnu'),
      e.peut_publier_missions,
      e.supprime_le,
      (
        lower(COALESCE(e.email_contact, '')) LIKE '%@supprime.jolene.app'
        OR COALESCE(e.bloque_auto_raisons, '[]'::jsonb) ? 'COMPTE_SUPPRIME_RGPD'
        OR EXISTS (
          SELECT 1 FROM public.journaux_audit j
          WHERE j.id_ressource = e.id
            AND j.action = 'RGPD_SUPPRESSION_COMPTE_ETABLISSEMENT'
        )
      )
    INTO v_nom, v_peut_publier_avant, v_supprime_le, v_est_suppression_rgpd
    FROM public.etablissements e
    WHERE e.id = p_id
    FOR UPDATE;
  END IF;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Compte introuvable');
  END IF;

  SELECT u.banned_until
  INTO v_banned_until_courant
  FROM auth.users u
  WHERE u.id = p_id AND u.deleted_at IS NULL
  FOR UPDATE;
  v_auth_trouve := FOUND;

  SELECT EXISTS (
    SELECT 1 FROM public.suspensions_profils_admin sp
    WHERE sp.type_ressource = p_table AND sp.id_ressource = p_id
  ) INTO v_provenance_suspension;

  IF v_est_suppression_rgpd THEN
    RETURN jsonb_build_object(
      'error',
      'Compte supprimé au titre du RGPD : suspension et réactivation interdites'
    );
  END IF;

  IF p_suspendre THEN
    IF v_supprime_le IS NOT NULL AND NOT v_provenance_suspension THEN
      RETURN jsonb_build_object(
        'error',
        'Compte déjà supprimé sans provenance de suspension réversible'
      );
    END IF;

    INSERT INTO public.suspensions_profils_admin (
      type_ressource, id_ressource, supprime_le_avant,
      suspendu_le, suspendu_par, motif
    ) VALUES (
      p_table, p_id, v_supprime_le, v_maintenant, auth.uid(), v_motif
    )
    ON CONFLICT (type_ressource, id_ressource) DO UPDATE
      SET suspendu_par = EXCLUDED.suspendu_par,
          motif = EXCLUDED.motif;

    IF v_auth_trouve THEN
      SELECT sa.banned_until_pose
      INTO v_pose_precedente
      FROM public.suspensions_auth_admin sa
      WHERE sa.type_ressource = p_table
        AND sa.id_ressource = p_id
        AND sa.user_id = p_id
      FOR UPDATE;
      v_auth_state_existe := FOUND;

      IF NOT v_auth_state_existe THEN
        v_banned_until_pose := GREATEST(
          COALESCE(v_banned_until_courant, v_maintenant),
          v_maintenant + interval '100 years'
        );

        INSERT INTO public.suspensions_auth_admin (
          type_ressource, id_ressource, user_id,
          banned_until_avant, banned_until_pose,
          suspendu_le, suspendu_par, motif
        ) VALUES (
          p_table, p_id, p_id,
          v_banned_until_courant, v_banned_until_pose,
          v_maintenant, auth.uid(), v_motif
        );

        UPDATE auth.users
        SET banned_until = v_banned_until_pose,
            updated_at = v_maintenant
        WHERE id = p_id
          AND banned_until IS NOT DISTINCT FROM v_banned_until_courant;
      ELSIF v_banned_until_courant IS NOT DISTINCT FROM v_pose_precedente THEN
        -- Suspension répétée : conserver l'état antérieur, mais faire suivre
        -- la valeur CAS réellement posée. Un ban externe divergent est intact.
        v_banned_until_pose := GREATEST(
          COALESCE(v_banned_until_courant, v_maintenant),
          v_maintenant + interval '100 years'
        );

        UPDATE auth.users
        SET banned_until = v_banned_until_pose,
            updated_at = v_maintenant
        WHERE id = p_id
          AND banned_until IS NOT DISTINCT FROM v_pose_precedente;

        UPDATE public.suspensions_auth_admin
        SET banned_until_pose = v_banned_until_pose,
            suspendu_par = auth.uid(),
            motif = v_motif
        WHERE type_ressource = p_table
          AND id_ressource = p_id
          AND user_id = p_id;
      END IF;
    END IF;

    IF p_table = 'soignants' THEN
      UPDATE public.soignants
      SET supprime_le = COALESCE(supprime_le, v_maintenant),
          modifie_le = v_maintenant
      WHERE id = p_id;
    ELSE
      INSERT INTO public.suspensions_etablissement_admin (
        etablissement_id, peut_publier_avant, suspendu_le, suspendu_par, motif
      ) VALUES (
        p_id, v_peut_publier_avant, v_maintenant, auth.uid(), v_motif
      )
      ON CONFLICT (etablissement_id) DO NOTHING;

      INSERT INTO public.suspensions_membres_etablissement_admin (
        etablissement_id, membre_id, user_id, actif_avant, desactive_le,
        suspendu_par, motif
      )
      SELECT p_id, m.id, m.user_id, m.actif, v_maintenant, auth.uid(), v_motif
      FROM public.membres_etablissement m
      WHERE m.etablissement_id = p_id
        AND m.actif IS TRUE
      ON CONFLICT (etablissement_id, membre_id) DO UPDATE
        SET desactive_le = EXCLUDED.desactive_le,
            suspendu_par = EXCLUDED.suspendu_par,
            motif = EXCLUDED.motif;

      UPDATE public.membres_etablissement m
      SET actif = false,
          maj_le = v_maintenant
      WHERE m.etablissement_id = p_id
        AND m.actif IS TRUE;
      GET DIAGNOSTICS v_membres = ROW_COUNT;

      UPDATE public.etablissements
      SET supprime_le = COALESCE(supprime_le, v_maintenant),
          peut_publier_missions = false,
          modifie_le = v_maintenant
      WHERE id = p_id;
    END IF;
  ELSE
    IF NOT v_provenance_suspension THEN
      RETURN jsonb_build_object(
        'error',
        'Aucune suspension administrateur réversible pour ce compte'
      );
    END IF;

    IF p_table = 'soignants' THEN
      UPDATE public.soignants s
      SET supprime_le = sp.supprime_le_avant,
          modifie_le = v_maintenant
      FROM public.suspensions_profils_admin sp
      WHERE s.id = p_id
        AND sp.type_ressource = 'soignants'
        AND sp.id_ressource = s.id;
    ELSE
      DELETE FROM public.suspensions_etablissement_admin se
      WHERE se.etablissement_id = p_id
      RETURNING se.peut_publier_avant INTO v_peut_publier_avant;

      UPDATE public.etablissements e
      SET supprime_le = sp.supprime_le_avant,
          peut_publier_missions = (
            COALESCE(v_peut_publier_avant, false)
            AND e.statut_verification = 'VERIFIE'
            AND e.siret_verifie IS TRUE
            AND e.finess_verifie IS TRUE
            AND e.representant_identite_verifiee IS TRUE
            AND e.rattachement_verifie IS TRUE
            AND e.contrat_service_signe IS TRUE
            AND e.bloque_auto_le IS NULL
            AND NOT EXISTS (
              SELECT 1 FROM public.factures f
              WHERE f.etablissement_id = e.id
                AND f.statut IN ('EMISE', 'EN_RETARD')
                AND f.date_echeance < current_date
            )
          ),
          modifie_le = v_maintenant
      FROM public.suspensions_profils_admin sp
      WHERE e.id = p_id
        AND sp.type_ressource = 'etablissements'
        AND sp.id_ressource = e.id;

      UPDATE public.membres_etablissement m
      SET actif = sm.actif_avant,
          maj_le = v_maintenant
      FROM public.suspensions_membres_etablissement_admin sm
      WHERE sm.etablissement_id = p_id
        AND sm.membre_id = m.id
        AND m.etablissement_id = sm.etablissement_id
        AND m.user_id = sm.user_id
        AND m.actif IS FALSE
        AND m.maj_le = sm.desactive_le;
      GET DIAGNOSTICS v_membres = ROW_COUNT;

      DELETE FROM public.suspensions_membres_etablissement_admin sm
      WHERE sm.etablissement_id = p_id;
    END IF;

    UPDATE auth.users u
    SET banned_until = sa.banned_until_avant,
        updated_at = v_maintenant
    FROM public.suspensions_auth_admin sa
    WHERE sa.type_ressource = p_table
      AND sa.id_ressource = p_id
      AND sa.user_id = u.id
      AND u.banned_until IS NOT DISTINCT FROM sa.banned_until_pose;

    DELETE FROM public.suspensions_auth_admin sa
    WHERE sa.type_ressource = p_table
      AND sa.id_ressource = p_id;

    DELETE FROM public.suspensions_profils_admin sp
    WHERE sp.type_ressource = p_table
      AND sp.id_ressource = p_id;
  END IF;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    auth.uid(), 'ADMIN',
    CASE WHEN p_suspendre THEN 'SUSPENSION_COMPTE' ELSE 'REACTIVATION_COMPTE' END,
    p_table, p_id,
    jsonb_build_object(
      'nom', v_nom,
      'table', p_table,
      'action', CASE WHEN p_suspendre THEN 'suspendre' ELSE 'réactiver' END,
      'motif', v_motif,
      'auth_synchronise', v_auth_trouve,
      'membres_affectes', v_membres
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', CASE WHEN p_suspendre THEN 'Compte suspendu : ' ELSE 'Compte réactivé : ' END || v_nom,
    'auth_synchronise', v_auth_trouve,
    'membres_affectes', v_membres
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_suspendre_utilisateur"("p_table" "text", "p_id" "uuid", "p_suspendre" boolean, "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_toggle_template_contrat"("p_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ancien_statut boolean;
  v_nouveau_statut boolean;
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  SELECT est_actif INTO v_ancien_statut FROM public.templates_contrat WHERE id = p_template_id;
  IF v_ancien_statut IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TEMPLATE_INTROUVABLE');
  END IF;

  v_nouveau_statut := NOT v_ancien_statut;

  UPDATE public.templates_contrat
  SET est_actif = v_nouveau_statut, modifie_le = now()
  WHERE id = p_template_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'template_contrat', p_template_id,
    jsonb_build_object(
      'evenement', CASE WHEN v_nouveau_statut THEN 'TEMPLATE_CONTRAT_ACTIVE' ELSE 'TEMPLATE_CONTRAT_DESACTIVE' END,
      'ancien_statut', v_ancien_statut,
      'nouveau_statut', v_nouveau_statut
    )
  );

  RETURN jsonb_build_object('success', true, 'est_actif', v_nouveau_statut);
END;
$$;


ALTER FUNCTION "public"."fn_admin_toggle_template_contrat"("p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_traiter_alerte_pointage"("p_alerte_id" "uuid", "p_decision" "text", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_alerte public.alertes_systeme%ROWTYPE;
  v_motif text := trim(COALESCE(p_motif, ''));
  v_revue_id uuid;
  v_soignant_id uuid;
  v_notifications integer := 0;
  v_effet text := 'ALERTE_FERMEE';
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;
  IF p_decision NOT IN (
    'LEGITIME', 'FRAUDE_AVERTISSEMENT',
    'FRAUDE_SUSPENSION_PROPOSEE', 'IGNORER'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DECISION_INVALIDE');
  END IF;
  IF length(v_motif) < 10 OR length(v_motif) > 1000 THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'MOTIF_INVALIDE',
      'error', 'Le motif doit contenir entre 10 et 1000 caracteres.'
    );
  END IF;

  SELECT * INTO v_alerte
  FROM public.alertes_systeme
  WHERE id = p_alerte_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ALERTE_INTROUVABLE');
  END IF;
  IF v_alerte.type_alerte NOT IN ('TELEPORTATION_DETECTED', 'POINTAGE_INCOHERENT') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TYPE_ALERTE_INVALIDE');
  END IF;
  IF v_alerte.resolu_le IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ALERTE_DEJA_TRAITEE');
  END IF;

  IF COALESCE(v_alerte.details ->> 'soignant_id', '') ~ '^[0-9a-fA-F-]{36}$' THEN
    v_soignant_id := (v_alerte.details ->> 'soignant_id')::uuid;
  END IF;

  IF p_decision = 'FRAUDE_SUSPENSION_PROPOSEE' THEN
    SELECT f.id INTO v_revue_id
    FROM public.file_revue_manuelle f
    WHERE f.type_entite = 'ALERTE_FRAUDE'
      AND f.id_entite = p_alerte_id
      AND f.service_en_echec = 'ADMIN_SUSPENSION_REVIEW'
      AND f.statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE')
    ORDER BY f.cree_le DESC
    LIMIT 1;

    IF v_revue_id IS NULL THEN
      INSERT INTO public.file_revue_manuelle(
        type_entite, id_entite, service_en_echec, motif_echec,
        donnees_originales, statut, priorite, expire_le
      ) VALUES (
        'ALERTE_FRAUDE', p_alerte_id, 'ADMIN_SUSPENSION_REVIEW', v_motif,
        jsonb_build_object(
          'alerte_id', p_alerte_id,
          'type_alerte', v_alerte.type_alerte,
          'soignant_id', v_soignant_id,
          'propose_par', v_uid,
          'propose_le', now(),
          'details_alerte', v_alerte.details
        ),
        'EN_ATTENTE', 5, now() + interval '7 days'
      ) RETURNING id INTO v_revue_id;
    END IF;

    INSERT INTO public.notifications(
      destinataire_id, type_destinataire, type, titre, corps,
      lien, type_ressource, id_ressource
    )
    SELECT
      a.id, 'ADMIN', 'SYSTEM', 'Suspension a revoir',
      'Une proposition de suspension anti-fraude requiert une seconde validation.',
      '/admin/alertes-pointage', 'file_revue_manuelle', v_revue_id
    FROM public.fn_list_admin_user_ids() AS a(id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.notifications n
      WHERE n.destinataire_id = a.id
        AND n.type = 'SYSTEM'
        AND n.type_ressource = 'file_revue_manuelle'
        AND n.id_ressource = v_revue_id
    );
    GET DIAGNOSTICS v_notifications = ROW_COUNT;
    v_effet := 'SUSPENSION_REVIEW_CREATED';
  ELSIF p_decision = 'FRAUDE_AVERTISSEMENT' THEN
    v_effet := 'AVERTISSEMENT_A_PREPARER_ENREGISTRE';
  END IF;

  UPDATE public.alertes_systeme
  SET resolu_le = now(),
      details = COALESCE(details, '{}'::jsonb) || jsonb_build_object(
        'decision_admin', p_decision,
        'motif_admin', v_motif,
        'traite_par', v_uid,
        'traite_le', now(),
        'revue_suspension_id', v_revue_id
      )
  WHERE id = p_alerte_id;

  INSERT INTO public.journaux_audit(
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'alerte_systeme', p_alerte_id,
    jsonb_build_object(
      'evenement', 'ALERTE_POINTAGE_TRAITEE',
      'decision', p_decision,
      'motif', v_motif,
      'type_alerte', v_alerte.type_alerte,
      'effet', v_effet,
      'revue_suspension_id', v_revue_id,
      'notifications_admin', v_notifications
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'decision', p_decision,
    'effect', v_effet,
    'review_task_id', v_revue_id,
    'admin_notifications_created', v_notifications,
    'automatic_suspension', false
  );
END;
$_$;


ALTER FUNCTION "public"."fn_admin_traiter_alerte_pointage"("p_alerte_id" "uuid", "p_decision" "text", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_traiter_message_contact"("p_message_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR public.est_admin() IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Accès refusé');
  END IF;

  UPDATE public.messages_contact
  SET statut = 'TRAITE',
      traite_le = COALESCE(traite_le, pg_catalog.now()),
      traite_par = COALESCE(traite_par, v_uid)
  WHERE id = p_message_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Message introuvable');
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'ADMIN_ACTION',
    p_type_ressource := 'message_contact',
    p_id_ressource := p_message_id,
    p_details := pg_catalog.jsonb_build_object(
      'sous_action', 'MESSAGE_CONTACT_TRAITE'
    )
  );
  RETURN pg_catalog.jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_traiter_message_contact"("p_message_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_traiter_reclamation"("p_reclamation_id" "uuid", "p_decision" "text", "p_points_corriges" integer, "p_motif_admin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_rec RECORD;
  v_event_id uuid;
  v_event_type text;
  v_proprio_id uuid;
  v_score jsonb;
BEGIN
  IF v_uid IS NULL OR NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_ADMIN');
  END IF;

  IF p_decision NOT IN ('MAINTENIR', 'REDUIRE', 'ANNULER') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DECISION_INVALIDE',
                                'error', 'Décision doit être MAINTENIR, REDUIRE ou ANNULER');
  END IF;

  IF p_motif_admin IS NULL OR length(trim(p_motif_admin)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MOTIF_ADMIN_REQUIS',
                                'error', 'Motif admin obligatoire (min 10 caractères)');
  END IF;

  IF p_decision = 'REDUIRE' AND (p_points_corriges IS NULL OR p_points_corriges >= 0) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'POINTS_CORRIGES_INVALIDE',
                                'error', 'REDUIRE requiert points_corriges < 0 (ex: -5 au lieu de -10)');
  END IF;

  SELECT * INTO v_rec FROM public.reclamations_score WHERE id = p_reclamation_id;
  IF v_rec IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'RECLAMATION_INTROUVABLE');
  END IF;

  IF v_rec.statut != 'PENDING' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_TRAITEE',
                                'error', 'Réclamation déjà traitée (statut : ' || v_rec.statut || ')');
  END IF;

  v_event_type := v_rec.evenement_type;
  v_event_id := COALESCE(v_rec.evenement_soignant_id, v_rec.evenement_etab_id);

  -- Mettre à jour la réclamation
  UPDATE public.reclamations_score SET
    statut = 'TREATED',
    decision_admin = p_decision,
    motif_admin = trim(p_motif_admin),
    traitee_par_admin_id = v_uid,
    traitee_le = NOW(),
    modifiee_le = NOW()
  WHERE id = p_reclamation_id;

  -- Propager la décision sur l'événement
  IF v_event_type = 'SOIGNANT' THEN
    UPDATE public.evenements_score_soignant SET
      decision_admin = p_decision,
      points_corriges = CASE WHEN p_decision = 'REDUIRE' THEN p_points_corriges ELSE NULL END,
      motif_admin = trim(p_motif_admin),
      traite_par_admin_id = v_uid,
      traite_le = NOW()
    WHERE id = v_event_id
    RETURNING soignant_id INTO v_proprio_id;

    -- Recalcul score auto
    v_score := public.fn_calculer_score_soignant(v_proprio_id);
  ELSE
    UPDATE public.evenements_score_etab SET
      decision_admin = p_decision,
      points_corriges = CASE WHEN p_decision = 'REDUIRE' THEN p_points_corriges ELSE NULL END,
      motif_admin = trim(p_motif_admin),
      traite_par_admin_id = v_uid,
      traite_le = NOW()
    WHERE id = v_event_id
    RETURNING etablissement_id INTO v_proprio_id;

    v_score := public.fn_calculer_score_etab(v_proprio_id);
  END IF;

  -- Notification user (email + push) avec décision et motif
  INSERT INTO public.externalisation_actions (type_action, payload, source, source_id)
  VALUES
    ('EMAIL_NOTIF', jsonb_build_object(
      'destinataire_id', v_rec.contesteur_id,
      'type', 'RECLAMATION_SCORE_DECISION',
      'data', jsonb_build_object(
        'reclamation_id', p_reclamation_id,
        'decision', p_decision,
        'motif_admin', p_motif_admin,
        'points_corriges', p_points_corriges,
        'nouveau_score', (v_score->>'score_total')::int
      )
    ), 'AUTRE', p_reclamation_id),
    ('PUSH_NOTIF', jsonb_build_object(
      'destinataire_id', v_rec.contesteur_id,
      'type_evenement', 'RECLAMATION_SCORE_DECISION',
      'titre', CASE p_decision
        WHEN 'ANNULER' THEN 'Réclamation acceptée ✅'
        WHEN 'REDUIRE' THEN 'Réclamation partiellement acceptée'
        ELSE 'Réclamation examinée'
      END,
      'corps', 'Votre score a été mis à jour. Consultez votre profil pour le détail.'
    ), 'AUTRE', p_reclamation_id);

  -- Audit
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_PLATEFORME', 'ADMIN_ACTION', 'reclamation_score', p_reclamation_id,
    jsonb_build_object(
      'evenement', 'RECLAMATION_SCORE_TRAITEE',
      'decision', p_decision,
      'points_corriges', p_points_corriges,
      'motif_admin', p_motif_admin,
      'event_id', v_event_id, 'event_type', v_event_type,
      'nouveau_score', v_score
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'reclamation_id', p_reclamation_id,
    'decision', p_decision,
    'event_id', v_event_id,
    'nouveau_score', v_score
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_traiter_reclamation"("p_reclamation_id" "uuid", "p_decision" "text", "p_points_corriges" integer, "p_motif_admin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_traiter_signalement"("p_id" "uuid", "p_statut" "text", "p_resolution" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.est_admin() THEN RETURN jsonb_build_object('success', false, 'error', 'Admin requis'); END IF;
  IF p_statut NOT IN ('OUVERT','EN_COURS','TRAITE','REJETE') THEN RETURN jsonb_build_object('success', false, 'error', 'Statut invalide'); END IF;
  UPDATE public.signalements SET statut = p_statut, resolution = p_resolution, traite_par = auth.uid(),
    traite_le = CASE WHEN p_statut IN ('TRAITE','REJETE') THEN now() ELSE traite_le END WHERE id = p_id;
  RETURN jsonb_build_object('success', true);
END; $$;


ALTER FUNCTION "public"."fn_admin_traiter_signalement"("p_id" "uuid", "p_statut" "text", "p_resolution" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_trancher_litige"("p_litige_id" "uuid", "p_decision" "text", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_litige record;
  v_decision_clean text;
  v_statut_final text;
  v_motif_clean text;
BEGIN
  IF public.est_admin() IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Seul l''administrateur peut trancher'
    );
  END IF;

  v_decision_clean := upper(trim(COALESCE(p_decision, '')));
  IF v_decision_clean NOT IN (
    'FAVEUR_SOIGNANT', 'FAVEUR_ETAB', 'PARTAGE'
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Décision invalide (FAVEUR_SOIGNANT/FAVEUR_ETAB/PARTAGE)'
    );
  END IF;
  v_motif_clean := trim(COALESCE(p_motif, ''));
  IF length(v_motif_clean) < 50 OR length(v_motif_clean) > 2000 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Le motif doit contenir entre 50 et 2000 caractères'
    );
  END IF;

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Litige introuvable'
    );
  END IF;
  IF v_litige.statut = 'REVUE_ADMIN'
     OR v_litige.payload_modifications IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',
      'Accord structuré à traiter via fn_admin_valider_accord_litige'
    );
  END IF;
  IF v_litige.statut NOT IN (
    'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS'
  ) THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'Litige déjà résolu ou non arbitrable'
    );
  END IF;

  v_statut_final := 'RESOLU_' || v_decision_clean;
  UPDATE public.litiges
     SET statut = v_statut_final,
         resolution = v_motif_clean,
         resolu_par = v_uid,
         resolu_le = now()
   WHERE id = p_litige_id;

  INSERT INTO public.notifications (
    destinataire_id, type_destinataire, type, titre, corps, lien
  ) VALUES
    (
      v_litige.soignant_id,
      'SOIGNANT',
      'LITIGE_RESOLU',
      CASE v_decision_clean
        WHEN 'FAVEUR_SOIGNANT' THEN 'Litige tranché en votre faveur ✅'
        WHEN 'FAVEUR_ETAB' THEN 'Litige tranché en faveur de l''établissement'
        ELSE 'Litige tranché : décision partagée'
      END,
      v_motif_clean,
      '/soignant/litiges'
    ),
    (
      v_litige.etablissement_id,
      'ETABLISSEMENT',
      'LITIGE_RESOLU',
      CASE v_decision_clean
        WHEN 'FAVEUR_SOIGNANT' THEN 'Litige tranché en faveur du soignant'
        WHEN 'FAVEUR_ETAB' THEN 'Litige tranché en votre faveur ✅'
        ELSE 'Litige tranché : décision partagée'
      END,
      v_motif_clean,
      '/etablissement/litiges'
    );

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'LITIGE_ADMIN_TRANCHE',
    p_type_ressource := 'litige',
    p_id_ressource := p_litige_id,
    p_details := jsonb_build_object(
      'decision', v_decision_clean,
      'statut_final', v_statut_final,
      'motif', v_motif_clean
    )
  );

  RETURN jsonb_build_object(
    'success', true, 'statut_final', v_statut_final
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_trancher_litige"("p_litige_id" "uuid", "p_decision" "text", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_triage_scores"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé — admin uniquement');
  END IF;

  SELECT jsonb_build_object('success', true, 'lignes', COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.score ASC), '[]'::jsonb))
  INTO v
  FROM (
    SELECT s.id AS user_id,
           'SOIGNANT' AS type,
           NULLIF(btrim(COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '')), '') AS nom,
           COALESCE(s.email, '') AS email,
           COALESCE(s.score_fiabilite, 0)::numeric AS score
    FROM public.soignants s
    WHERE s.supprime_le IS NULL
    UNION ALL
    SELECT e.id,
           'ETAB',
           NULLIF(btrim(COALESCE(e.nom, '')), '') AS nom,
           COALESCE(e.email_contact, '') AS email,
           COALESCE(e.score_qualite, 0)::numeric AS score
    FROM public.etablissements e
    WHERE e.supprime_le IS NULL
  ) x;

  RETURN v;
END;
$$;


ALTER FUNCTION "public"."fn_admin_triage_scores"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_valider_accord_litige"("p_litige_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_litige record;
  v_exec jsonb;
  v_audit_result jsonb;
  v_type text;
  v_rows integer;
BEGIN
  IF public.est_admin() IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Litige introuvable');
  END IF;

  v_type := v_litige.payload_modifications->>'type';
  IF v_litige.statut <> 'REVUE_ADMIN'
     OR v_litige.accord_soignant IS NOT TRUE
     OR v_litige.accord_etablissement IS NOT TRUE
     OR v_litige.accord_soignant_le IS NULL
     OR v_litige.accord_etablissement_le IS NULL
     OR v_litige.payload_modifications IS NULL
     OR COALESCE(v_type, 'ACCORD_SANS_MODIFICATION')
       = 'ACCORD_SANS_MODIFICATION'
     OR v_litige.modifications_executees IS TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Aucun accord financier complet à valider sur ce litige'
    );
  END IF;

  -- Ces ajustements doivent passer par fn_admin_resoudre_litige : cette RPC
  -- demande à l'admin les paramètres comptables exacts selon l'état réel de
  -- la facture. On retourne un résultat structuré sans sortir le dossier de
  -- REVUE_ADMIN et sans tenter d'avoir approximatif.
  IF v_type IN (
    'MODIFICATION_HORAIRES',
    'MODIFICATION_MONTANT',
    'MIXTE'
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
      'error', 'Cet ajustement doit être appliqué via la résolution financière administrateur.',
      'manual_resolution_required', true,
      'type', v_type
    );
  END IF;

  PERFORM set_config('jolene.litige_exec_ok', 'true', true);
  v_exec := public.fn_executer_modifications_litige(p_litige_id);

  IF COALESCE((v_exec->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Échec de l''exécution de l''accord financier: %',
      COALESCE(v_exec->>'error', 'erreur inconnue');
  END IF;

  UPDATE public.litiges
     SET statut = 'RESOLU_ADMIN',
         resolu_le = COALESCE(resolu_le, now()),
         resolu_par = v_uid
   WHERE id = p_litige_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Validation concurrente de l''accord refusée';
  END IF;

  v_audit_result := public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_PLATEFORME',
    p_action := 'LITIGE_RESOLUTION',
    p_type_ressource := 'litige',
    p_id_ressource := p_litige_id,
    p_details := jsonb_build_object(
      'evenement', 'LITIGE_ACCORD_VALIDE_ADMIN',
      'execution', v_exec
    )
  );
  IF COALESCE(v_audit_result @> '{"success": true}'::jsonb, false)
       IS NOT TRUE THEN
    RAISE EXCEPTION 'Audit de validation d''accord non écrit: %',
      COALESCE(v_audit_result->>'error', 'résultat interne invalide');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'statut', 'RESOLU_ADMIN',
    'execution', v_exec
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_valider_accord_litige"("p_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_valider_contrat_etablissement"("p_etablissement_id" "uuid", "p_valider" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NOT public.est_admin() THEN RETURN jsonb_build_object('error', 'Accès refusé — admin uniquement'); END IF;
  IF p_valider AND NOT EXISTS (
    SELECT 1 FROM public.etablissements
    WHERE id = p_etablissement_id AND contrat_url IS NOT NULL AND contrat_ia_coherent IS TRUE
  ) THEN
    RETURN jsonb_build_object('error', 'Le contrat et sa cohérence IA doivent être contrôlés avant validation.');
  END IF;
  UPDATE public.etablissements SET contrat_valide = p_valider, modifie_le = now()
  WHERE id = p_etablissement_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Établissement introuvable'); END IF;
  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := auth.uid(), p_type_acteur := 'ADMIN_PLATEFORME', p_action := 'ADMIN_ACTION',
    p_type_ressource := 'etablissement', p_id_ressource := p_etablissement_id,
    p_details := jsonb_build_object('sous_action', 'VALIDATION_CONTRAT_ETABLISSEMENT', 'valide', p_valider)
  );
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_admin_valider_contrat_etablissement"("p_etablissement_id" "uuid", "p_valider" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_valider_etablissement"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_etab record;
BEGIN
  IF NOT public.est_admin() THEN RETURN jsonb_build_object('error', 'Accès refusé — admin uniquement'); END IF;
  SELECT id, nom, siret, finess, siret_verifie, finess_verifie,
         representant_identite_verifiee, rattachement_verifie, contrat_service_signe
    INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Établissement introuvable'); END IF;
  IF v_etab.siret IS NULL OR v_etab.siret_verifie IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Le SIRET officiel doit être vérifié.');
  END IF;
  IF v_etab.finess IS NULL OR v_etab.finess_verifie IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Le FINESS officiel doit être vérifié.');
  END IF;
  IF v_etab.representant_identite_verifiee IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'L identité du représentant doit être vérifiée.');
  END IF;
  IF v_etab.rattachement_verifie IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'L habilitation du représentant doit être vérifiée.');
  END IF;
  IF v_etab.contrat_service_signe IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Le contrat de service Jolene doit être signé.');
  END IF;
  UPDATE public.etablissements
  SET statut_verification = 'VERIFIE', peut_publier_missions = true,
      verifie_le = now(), verifie_par = auth.uid(), modifie_le = now()
  WHERE id = p_etablissement_id;
  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := auth.uid(), p_type_acteur := 'ADMIN_PLATEFORME', p_action := 'ADMIN_ACTION',
    p_type_ressource := 'etablissement', p_id_ressource := p_etablissement_id,
    p_details := jsonb_build_object('sous_action', 'VALIDATION_ETABLISSEMENT', 'nom', v_etab.nom)
  );
  RETURN jsonb_build_object('success', true, 'nom', v_etab.nom);
END;
$$;


ALTER FUNCTION "public"."fn_admin_valider_etablissement"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_admin_valider_heures_externes"("p_id" "uuid", "p_decision" "text", "p_commentaire" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'storage'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ligne public.heures_externes_soignants%ROWTYPE;
  v_empreinte_snapshot text;
  v_row_count integer;
  v_guc_precedent text := COALESCE(
    current_setting('jolene.heures_externes_server_update', true), ''
  );
BEGIN
  IF v_uid IS NULL
     OR NOT public.fn_compte_auth_actif()
     OR NOT public.est_admin_valide() THEN
    RAISE EXCEPTION 'Administrateur valide requis'
      USING ERRCODE = '42501';
  END IF;

  IF p_decision NOT IN ('VALIDE', 'REJETE') THEN
    RAISE EXCEPTION 'Décision invalide (VALIDE ou REJETE)'
      USING ERRCODE = '22023';
  END IF;
  IF p_decision = 'REJETE'
     AND char_length(btrim(COALESCE(p_commentaire, ''))) < 5 THEN
    RAISE EXCEPTION 'Motif requis pour un rejet (min 5 caractères)'
      USING ERRCODE = '22023';
  END IF;
  IF char_length(COALESCE(p_commentaire, '')) > 1000 THEN
    RAISE EXCEPTION 'Commentaire trop long' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ligne
  FROM public.heures_externes_soignants
  WHERE id = p_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'INTROUVABLE',
      'error', 'Déclaration introuvable.'
    );
  END IF;
  IF v_ligne.statut_validation IS DISTINCT FROM 'EN_ATTENTE' THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'DECISION_CONCURRENTE',
      'error', 'Cette déclaration a déjà été traitée.'
    );
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('heures-soignant:' || v_ligne.soignant_id::text, 0)
  );
  v_empreinte_snapshot :=
    private.fn_empreinte_snapshot_heures_externes(v_ligne);

  IF p_decision = 'VALIDE' THEN
    IF v_ligne.empreinte_preuve_sha256 IS NULL
       OR v_ligne.empreinte_snapshot_source IS DISTINCT FROM v_empreinte_snapshot
       OR NOT EXISTS (
         SELECT 1
         FROM storage.objects o
         WHERE o.name = v_ligne.attestation_url
           AND o.bucket_id IN (
             'jolene-documents', 'attestations-heures-externes'
           )
       ) THEN
      RETURN jsonb_build_object(
        'success', false, 'error_code', 'PREUVE_NON_FINALISEE',
        'error', 'La preuve doit être vérifiée sur ce snapshot avant validation.'
      );
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.heures_externes_soignants autre
      WHERE autre.id <> v_ligne.id
        AND autre.empreinte_preuve_sha256 = v_ligne.empreinte_preuve_sha256
        AND autre.statut_validation IN ('EN_ATTENTE', 'VALIDE')
    ) THEN
      RETURN jsonb_build_object(
        'success', false, 'error_code', 'PREUVE_DUPLIQUEE',
        'error', 'Cette preuve binaire est déjà utilisée par une autre déclaration.'
      );
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.heures_externes_soignants autre
      WHERE autre.id <> v_ligne.id
        AND autre.soignant_id = v_ligne.soignant_id
        AND autre.statut_validation = 'VALIDE'
        AND daterange(autre.date_debut, autre.date_fin, '[]')
            && daterange(v_ligne.date_debut, v_ligne.date_fin, '[]')
    ) THEN
      RETURN jsonb_build_object(
        'success', false, 'error_code', 'PERIODE_DEJA_VALIDEE',
        'error', 'Une autre preuve validée couvre déjà cette période.'
      );
    END IF;
  END IF;

  PERFORM set_config('jolene.heures_externes_server_update', 'true', true);
  UPDATE public.heures_externes_soignants h
  SET statut_validation = p_decision,
      commentaire_validation = NULLIF(
        left(btrim(COALESCE(p_commentaire, '')), 1000), ''
      ),
      valide_par = v_uid,
      valide_le = now(),
      source_validation_serveur = 'ADMIN_AAL2',
      empreinte_snapshot_source = v_empreinte_snapshot,
      mis_a_jour_le = now()
  WHERE h.id = v_ligne.id
    AND h.version_source = v_ligne.version_source
    AND h.statut_validation = 'EN_ATTENTE'
    AND private.fn_empreinte_snapshot_heures_externes(h) = v_empreinte_snapshot;
  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  PERFORM set_config(
    'jolene.heures_externes_server_update', v_guc_precedent, true
  );
  IF v_row_count <> 1 THEN
    RAISE EXCEPTION 'Décision concurrente détectée'
      USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details
  ) VALUES (
    v_uid, 'ADMIN', 'HEURES_EXTERNES_VALIDATION_MANUELLE',
    'heures_externes_soignants', v_ligne.id, v_ligne.attestation_url,
    jsonb_build_object(
      'decision', p_decision,
      'soignant_id', v_ligne.soignant_id,
      'heures_declarees', v_ligne.heures_declarees,
      'heures_extraites_ia', v_ligne.heures_extraites_ia,
      'empreinte_snapshot_source', v_empreinte_snapshot,
      'source', 'ADMIN_AAL2'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'statut', p_decision,
    'source', 'ADMIN_AAL2'
  );
END;
$$;


ALTER FUNCTION "public"."fn_admin_valider_heures_externes"("p_id" "uuid", "p_decision" "text", "p_commentaire" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ajouter_jours_ouvres"("p_date" timestamp with time zone, "p_nb_jours" integer) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_local  TIMESTAMP;
  v_count  INTEGER := 0;
  v_step   INTEGER := CASE WHEN p_nb_jours >= 0 THEN 1 ELSE -1 END;
  v_target INTEGER := abs(p_nb_jours);
  v_dow    INTEGER;
  v_is_feried BOOLEAN;
BEGIN
  v_local := p_date AT TIME ZONE 'Europe/Paris';

  IF v_target = 0 THEN
    RETURN v_local AT TIME ZONE 'Europe/Paris';
  END IF;

  WHILE v_count < v_target LOOP
    v_local := v_local + (v_step || ' day')::INTERVAL;
    v_dow := EXTRACT(DOW FROM v_local)::INTEGER;
    IF v_dow IN (0, 6) THEN
      CONTINUE;
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.jours_feries_fr
      WHERE date_ferie = v_local::DATE
    ) INTO v_is_feried;
    IF v_is_feried THEN
      CONTINUE;
    END IF;
    v_count := v_count + 1;
  END LOOP;

  RETURN v_local AT TIME ZONE 'Europe/Paris';
END;
$$;


ALTER FUNCTION "public"."fn_ajouter_jours_ouvres"("p_date" timestamp with time zone, "p_nb_jours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ajouter_jours_ouvres"("p_date" timestamp with time zone, "p_nb_jours" integer) IS 'CP-LITIGES-7a FIX 10 — ajoute N jours ouvrés (FR) en basculant l''arith. en wall time Europe/Paris (DOW + DATE évalués en Paris, arithmétique en jour civil). Entrée/sortie TIMESTAMPTZ, TZ UTC en base. Gère DST.';



CREATE OR REPLACE FUNCTION "public"."fn_ajouter_message_litige"("p_litige_id" "uuid", "p_contenu" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_litige public.litiges%ROWTYPE;
  v_type_auteur text;
  v_est_admin boolean := false;
  v_contenu text;
  v_message_id uuid;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Accès refusé');
  END IF;

  v_est_admin := public.est_admin();
  SELECT l.* INTO v_litige
  FROM public.litiges l
  WHERE l.id = p_litige_id
    AND (
      l.soignant_id = v_uid
      OR public.fn_a_permission_etablissement(
        'contrats', l.etablissement_id
      ) IS TRUE
      OR v_est_admin
    )
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'error', 'Litige introuvable ou accès refusé'
    );
  END IF;
  IF v_litige.statut IS NULL OR v_litige.statut NOT IN (
    'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS',
    'REVUE_ADMIN'
  ) THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Ce litige est clôturé.');
  END IF;

  v_contenu := pg_catalog.btrim(COALESCE(p_contenu, ''));
  IF pg_catalog.length(v_contenu) < 10
     OR pg_catalog.length(v_contenu) > 5000 THEN
    RETURN pg_catalog.jsonb_build_object(
      'error', 'Le message doit contenir entre 10 et 5000 caractères.'
    );
  END IF;

  IF v_uid = v_litige.soignant_id THEN
    v_type_auteur := 'SOIGNANT';
  ELSIF v_est_admin THEN
    v_type_auteur := 'ADMIN';
  ELSIF public.fn_a_permission_etablissement(
          'contrats', v_litige.etablissement_id
        ) IS TRUE THEN
    v_type_auteur := 'ETABLISSEMENT';
  ELSE
    RETURN pg_catalog.jsonb_build_object('error', 'Accès refusé');
  END IF;

  INSERT INTO public.messages_litige (
    litige_id, auteur_id, type_auteur, contenu
  ) VALUES (
    p_litige_id, v_uid, v_type_auteur, v_contenu
  )
  RETURNING id INTO v_message_id;

  WITH candidats AS (
    SELECT
      v_litige.soignant_id AS user_id,
      'SOIGNANT'::text AS type_destinataire,
      CASE WHEN v_type_auteur = 'ADMIN'
        THEN 'Nouveau message de l''équipe Jolene'
        ELSE 'Nouveau message sur le litige'
      END AS titre,
      CASE WHEN v_type_auteur = 'ADMIN'
        THEN 'Un message administrateur a été ajouté à votre litige.'
        ELSE 'Un message a été ajouté au litige concernant la mission.'
      END AS corps,
      '/soignant/litiges?litige=' || v_litige.id::text AS lien,
      0 AS priorite
    WHERE v_type_auteur IN ('ETABLISSEMENT', 'ADMIN')
      AND v_litige.soignant_id IS DISTINCT FROM v_uid
      AND private.fn_soignant_messagerie_actif(
        v_litige.soignant_id
      )

    UNION ALL

    SELECT
      d.user_id,
      'ETABLISSEMENT',
      CASE WHEN v_type_auteur = 'ADMIN'
        THEN 'Nouveau message de l''équipe Jolene'
        ELSE 'Nouveau message sur le litige'
      END,
      CASE WHEN v_type_auteur = 'ADMIN'
        THEN 'Un message administrateur a été ajouté à votre litige.'
        ELSE 'Un message a été ajouté au litige concernant la mission.'
      END,
      '/etablissement/litiges?litige=' || v_litige.id::text,
      1
    FROM private.fn_destinataires_litige_etablissement(
      v_litige.etablissement_id
    ) AS d(user_id)
    WHERE v_type_auteur IN ('SOIGNANT', 'ADMIN')
      AND d.user_id IS DISTINCT FROM v_uid
      AND d.user_id IS DISTINCT FROM v_litige.soignant_id
  ), destinataires AS (
    SELECT DISTINCT ON (user_id)
      user_id,
      type_destinataire,
      titre,
      corps,
      lien
    FROM candidats
    ORDER BY user_id, priorite
  )
  INSERT INTO public.notifications (
    destinataire_id,
    type_destinataire,
    type,
    titre,
    corps,
    lien,
    type_ressource,
    id_ressource
  )
  SELECT
    user_id,
    type_destinataire,
    'SYSTEM',
    titre,
    corps,
    lien,
    'message_litige',
    v_message_id
  FROM destinataires
  ON CONFLICT (destinataire_id, id_ressource)
    WHERE type_ressource = 'message_litige'
  DO NOTHING;

  RETURN pg_catalog.jsonb_build_object(
    'success', true,
    'message_id', v_message_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_ajouter_message_litige"("p_litige_id" "uuid", "p_contenu" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_alerte_cddu_repetitif"("p_soignant_id" "uuid", "p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_jours INTEGER;
BEGIN
    IF NOT est_admin() AND v_etab_id IS DISTINCT FROM p_etablissement_id THEN
        RAISE EXCEPTION 'Accès refusé : alerte réservée à l''établissement' USING ERRCODE = '42501';
    END IF;

    SELECT COUNT(DISTINCT debut_le::DATE) INTO v_jours
    FROM missions
    WHERE soignant_assigne_id = p_soignant_id
      AND etablissement_id = p_etablissement_id
      AND statut = 'TERMINEE'
      AND debut_le > NOW() - INTERVAL '365 days';

    RETURN jsonb_build_object(
        'jours_12_mois', v_jours,
        'alerte', v_jours > 150,
        'message', CASE
            WHEN v_jours > 150 THEN 'Risque de requalification en CDI — ' || v_jours || ' jours travaillés sur 12 mois'
            ELSE NULL
        END
    );
END;
$$;


ALTER FUNCTION "public"."fn_alerte_cddu_repetitif"("p_soignant_id" "uuid", "p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_alerte_reclamations_pending_old"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_liste jsonb;
  v_admin_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  SELECT count(*),
         jsonb_agg(jsonb_build_object(
           'id', id,
           'evenement_type', evenement_type,
           'contesteur_id', contesteur_id,
           'motif_categorie', motif_categorie,
           'texte_libre', left(texte_libre, 100),
           'cree_le', cree_le,
           'jours_attente', extract(epoch FROM (now() - cree_le)) / 86400
         ) ORDER BY cree_le ASC)
    INTO v_count, v_liste
    FROM public.reclamations_score
   WHERE statut = 'PENDING'
     AND cree_le < now() - interval '14 days';

  IF v_count = 0 THEN
    RETURN jsonb_build_object('success', true, 'count', 0);
  END IF;

  SELECT COALESCE(array_agg(admin_user_id), ARRAY[]::uuid[])
    INTO v_admin_ids
    FROM public.fn_list_admin_user_ids() AS admins(admin_user_id);

  IF cardinality(v_admin_ids) > 0 THEN
    INSERT INTO public.externalisation_actions (
      type_action, payload, source, source_id
    )
    SELECT
      'EMAIL_NOTIF',
      jsonb_build_object(
        'destinataire_id', uid,
        'type', 'ALERTE_RECLAMATIONS_PENDING',
        'data', jsonb_build_object(
          'count', v_count,
          'liste', v_liste,
          'lien_admin', 'https://jolene.app/admin/reclamations-score'
        )
      ),
      'CRON_ALERTES',
      NULL
    FROM unnest(v_admin_ids) AS uid;

    INSERT INTO public.externalisation_actions (
      type_action, payload, source, source_id
    )
    SELECT
      'PUSH_NOTIF',
      jsonb_build_object(
        'destinataire_id', uid,
        'type_evenement', 'ALERTE_ADMIN',
        'titre', '⚠️ ' || v_count || ' réclamation'
          || CASE WHEN v_count > 1 THEN 's' ELSE '' END
          || ' en attente > 14j',
        'corps', 'Examen requis.',
        'lien', '/admin/reclamations-score'
      ),
      'CRON_ALERTES',
      NULL
    FROM unnest(v_admin_ids) AS uid;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'count', v_count,
    'admins_notifies', cardinality(v_admin_ids)
  );
END;
$$;


ALTER FUNCTION "public"."fn_alerte_reclamations_pending_old"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_alerter_mediation_prioritaire"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_delai_j INT;
  v_nb_alertes INT := 0;
  v_litige RECORD;
  v_admin_id UUID;
BEGIN
  SELECT valeur::INT INTO v_delai_j
    FROM public.parametres_litiges WHERE cle = 'delai_mediation_alerte_prioritaire_j';

  FOR v_litige IN
    SELECT id, mission_id, type_litige, escalade_auto_le
      FROM public.litiges
     WHERE statut = 'EN_MEDIATION'
       AND escalade_auto_le IS NOT NULL
       AND escalade_auto_le < NOW() - make_interval(days => v_delai_j)
       AND NOT (derniers_rappels_envoyes ? 'MEDIATION_7J')
  LOOP
    FOR v_admin_id IN SELECT * FROM public.fn_list_admin_user_ids()
    LOOP
      PERFORM public.fn_litige_push_notification(
        v_admin_id,
        'ADMIN',
        'LITIGE_MEDIATION_PRIORITAIRE',
        'Litige en médiation depuis > ' || v_delai_j || ' jours',
        'Le litige ' || v_litige.type_litige || ' sur mission '
          || v_litige.mission_id::text
          || ' est en médiation sans action admin depuis plus de '
          || v_delai_j || ' jours.',
        v_litige.id,
        jsonb_build_object(
          'type_litige', v_litige.type_litige,
          'mission_id', v_litige.mission_id,
          'jours_depuis_escalade', v_delai_j,
          'prioritaire', TRUE
        )
      );
    END LOOP;

    UPDATE public.litiges
       SET derniers_rappels_envoyes = derniers_rappels_envoyes
         || jsonb_build_object('MEDIATION_7J', NOW())
     WHERE id = v_litige.id;

    v_nb_alertes := v_nb_alertes + 1;
  END LOOP;

  RETURN jsonb_build_object('alertes_mediation', v_nb_alertes);
END;
$$;


ALTER FUNCTION "public"."fn_alerter_mediation_prioritaire"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_alerter_mediation_prioritaire"() IS 'Cron : alerte admin si litige EN_MEDIATION sans action > 7 jours. Idempotence via derniers_rappels_envoyes.MEDIATION_7J.';



CREATE OR REPLACE FUNCTION "public"."fn_alerter_paiements_retard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_facture RECORD;
    v_montant_estime NUMERIC;
    v_count_emails INT := 0;
    v_count_missions_j7 INT := 0;
    v_count_missions_j21 INT := 0;
    v_count_factures_j7 INT := 0;
    v_count_factures_j21 INT := 0;
BEGIN
    FOR v_mission IN
        SELECT m.id, m.intitule, m.fin_le, m.net_a_payer, m.total_brut,
               m.relance_paiement_1_le, m.relance_paiement_2_le,
               m.soignant_assigne_id, m.etablissement_id,
               e.nom AS etab_nom, e.email_contact AS etab_email,
               COALESCE(s.prenom, '') AS soignant_prenom,
               COALESCE(s.nom, '') AS soignant_nom
        FROM public.missions m
        JOIN public.etablissements e ON e.id = m.etablissement_id
        LEFT JOIN public.soignants s ON s.id = m.soignant_assigne_id
        WHERE m.statut = 'TERMINEE'
        AND m.type_contrat_applique = 'SALARIE'
        AND m.fin_le IS NOT NULL
        AND m.soignant_assigne_id IS NOT NULL
        AND (m.relance_paiement_1_le IS NULL OR m.relance_paiement_2_le IS NULL)
        AND NOT EXISTS (
            SELECT 1 FROM public.paiements_soignant ps
            WHERE ps.mission_id = m.id AND ps.statut IN ('DECLARE', 'CONFIRME')
        )
    LOOP
        v_montant_estime := COALESCE(v_mission.net_a_payer, v_mission.total_brut, 0);

        IF v_mission.fin_le + INTERVAL '7 days' <= NOW()
           AND v_mission.relance_paiement_1_le IS NULL THEN

            IF v_mission.etab_email IS NOT NULL THEN
                INSERT INTO public.email_queue (type, destinataire_id, destinataire_email, data)
                VALUES ('RAPPEL_PAIEMENT_J7', v_mission.etablissement_id, v_mission.etab_email,
                    jsonb_build_object(
                        'type_obligation', 'PAIEMENT_SOIGNANT',
                        'mission_id', v_mission.id,
                        'mission_intitule', v_mission.intitule,
                        'soignant_prenom', v_mission.soignant_prenom,
                        'soignant_nom', v_mission.soignant_nom,
                        'montant_estime', ROUND(v_montant_estime, 2),
                        'date_fin_mission', TO_CHAR(v_mission.fin_le AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'),
                        'etablissement_nom', v_mission.etab_nom
                    ));
                v_count_emails := v_count_emails + 1;
            END IF;

            INSERT INTO public.notifications (destinataire_id, type, titre, corps, lien, type_destinataire, type_ressource, id_ressource)
            VALUES (v_mission.etablissement_id, 'SYSTEM',
                'Rappel paiement soignant',
                'Rappel : paiement de ' || v_montant_estime || ' EUR a declarer pour "' || COALESCE(v_mission.intitule, 'Mission') || '" (' || v_mission.soignant_prenom || ' ' || v_mission.soignant_nom || ').',
                '/etablissement/obligations-financieres', 'ETABLISSEMENT', 'mission', v_mission.id);

            UPDATE public.missions SET relance_paiement_1_le = NOW() WHERE id = v_mission.id;
            v_count_missions_j7 := v_count_missions_j7 + 1;
        END IF;

        IF v_mission.fin_le + INTERVAL '21 days' <= NOW()
           AND v_mission.relance_paiement_2_le IS NULL THEN

            IF v_mission.etab_email IS NOT NULL THEN
                INSERT INTO public.email_queue (type, destinataire_id, destinataire_email, data)
                VALUES ('PAIEMENT_RETARD_J21', v_mission.etablissement_id, v_mission.etab_email,
                    jsonb_build_object(
                        'type_obligation', 'PAIEMENT_SOIGNANT',
                        'mission_id', v_mission.id,
                        'mission_intitule', v_mission.intitule,
                        'soignant_prenom', v_mission.soignant_prenom,
                        'soignant_nom', v_mission.soignant_nom,
                        'montant_estime', ROUND(v_montant_estime, 2),
                        'date_fin_mission', TO_CHAR(v_mission.fin_le AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'),
                        'etablissement_nom', v_mission.etab_nom,
                        'jours_retard', 21,
                        'jours_avant_blocage', 24
                    ));
                v_count_emails := v_count_emails + 1;
            END IF;

            INSERT INTO public.notifications (destinataire_id, type, titre, corps, lien, type_destinataire, type_ressource, id_ressource)
            VALUES (v_mission.etablissement_id, 'SYSTEM',
                'Paiement en retard (21 jours)',
                'Paiement de ' || v_montant_estime || ' EUR toujours non declare pour "' || COALESCE(v_mission.intitule, 'Mission') || '" (' || v_mission.soignant_prenom || ' ' || v_mission.soignant_nom || '). Sans regularisation sous 24 jours la publication de nouvelles missions sera suspendue.',
                '/etablissement/obligations-financieres', 'ETABLISSEMENT', 'mission', v_mission.id);

            UPDATE public.missions SET relance_paiement_2_le = NOW() WHERE id = v_mission.id;
            v_count_missions_j21 := v_count_missions_j21 + 1;
        END IF;
    END LOOP;

    FOR v_facture IN
        SELECT f.id, f.numero_facture, f.montant_ttc, f.date_emission,
               f.relance_1_le, f.relance_2_le, f.etablissement_id,
               e.nom AS etab_nom, e.email_contact AS etab_email
        FROM public.factures f
        JOIN public.etablissements e ON e.id = f.etablissement_id
        WHERE f.statut IN ('EMISE', 'EN_RETARD')
        AND f.date_emission IS NOT NULL
        AND (f.relance_1_le IS NULL OR f.relance_2_le IS NULL)
    LOOP
        IF v_facture.date_emission + INTERVAL '7 days' <= NOW()
           AND v_facture.relance_1_le IS NULL THEN

            IF v_facture.etab_email IS NOT NULL THEN
                INSERT INTO public.email_queue (type, destinataire_id, destinataire_email, data)
                VALUES ('RAPPEL_PAIEMENT_J7', v_facture.etablissement_id, v_facture.etab_email,
                    jsonb_build_object(
                        'type_obligation', 'FACTURE_COMMISSION',
                        'numero_facture', v_facture.numero_facture,
                        'montant_ttc', ROUND(v_facture.montant_ttc, 2),
                        'date_emission', TO_CHAR(v_facture.date_emission AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'),
                        'etablissement_nom', v_facture.etab_nom
                    ));
                v_count_emails := v_count_emails + 1;
            END IF;

            INSERT INTO public.notifications (destinataire_id, type, titre, corps, lien, type_destinataire, type_ressource, id_ressource)
            VALUES (v_facture.etablissement_id, 'SYSTEM',
                'Rappel facture commission',
                'Rappel : facture ' || COALESCE(v_facture.numero_facture, '-') || ' de ' || v_facture.montant_ttc || ' EUR en attente de reglement.',
                '/etablissement/facturation', 'ETABLISSEMENT', 'facture', v_facture.id);

            UPDATE public.factures SET relance_1_le = NOW() WHERE id = v_facture.id;
            v_count_factures_j7 := v_count_factures_j7 + 1;
        END IF;

        IF v_facture.date_emission + INTERVAL '21 days' <= NOW()
           AND v_facture.relance_2_le IS NULL THEN

            IF v_facture.etab_email IS NOT NULL THEN
                INSERT INTO public.email_queue (type, destinataire_id, destinataire_email, data)
                VALUES ('PAIEMENT_RETARD_J21', v_facture.etablissement_id, v_facture.etab_email,
                    jsonb_build_object(
                        'type_obligation', 'FACTURE_COMMISSION',
                        'numero_facture', v_facture.numero_facture,
                        'montant_ttc', ROUND(v_facture.montant_ttc, 2),
                        'date_emission', TO_CHAR(v_facture.date_emission AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'),
                        'etablissement_nom', v_facture.etab_nom,
                        'jours_retard', 21,
                        'jours_avant_blocage', 24
                    ));
                v_count_emails := v_count_emails + 1;
            END IF;

            INSERT INTO public.notifications (destinataire_id, type, titre, corps, lien, type_destinataire, type_ressource, id_ressource)
            VALUES (v_facture.etablissement_id, 'SYSTEM',
                'Facture en retard (21 jours)',
                'Facture ' || COALESCE(v_facture.numero_facture, '-') || ' de ' || v_facture.montant_ttc || ' EUR toujours impayee. Sans regularisation sous 24 jours la publication de nouvelles missions sera suspendue.',
                '/etablissement/facturation', 'ETABLISSEMENT', 'facture', v_facture.id);

            UPDATE public.factures SET relance_2_le = NOW() WHERE id = v_facture.id;
            v_count_factures_j21 := v_count_factures_j21 + 1;
        END IF;
    END LOOP;

    FOR v_mission IN
        SELECT p.id AS paiement_id, p.soignant_id, p.mission_id, p.montant_net,
               m.intitule, e.nom AS etab_nom
        FROM public.paiements_soignant p
        JOIN public.missions m ON m.id = p.mission_id
        JOIN public.etablissements e ON e.id = p.etablissement_id
        WHERE p.statut = 'DECLARE'
        AND p.confirme_par_soignant = FALSE
        AND p.cree_le < NOW() - INTERVAL '15 days'
        AND p.relance_1_le IS NULL
    LOOP
        UPDATE public.paiements_soignant SET relance_1_le = NOW() WHERE id = v_mission.paiement_id;

        INSERT INTO public.notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (v_mission.soignant_id, 'SYSTEM',
            'Rappel : confirmez la reception du paiement',
            'L etablissement "' || COALESCE(v_mission.etab_nom, 'Etablissement') || '" a declare vous avoir paye ' || v_mission.montant_net || ' EUR pour "' || COALESCE(v_mission.intitule, 'Mission') || '". Merci de confirmer ou contester.',
            '/soignant/mes-gains', 'SOIGNANT');
    END LOOP;

    RETURN jsonb_build_object(
        'success', TRUE,
        'emails_queued', v_count_emails,
        'missions_j7', v_count_missions_j7,
        'missions_j21', v_count_missions_j21,
        'factures_j7', v_count_factures_j7,
        'factures_j21', v_count_factures_j21
    );
END;
$$;


ALTER FUNCTION "public"."fn_alerter_paiements_retard"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_alerter_paiements_retard"() IS 'CP-C-2 C refonte seuils J+7/J+21 + factures commission + email_queue. Cron jobid 11. Blocage J+45 delegue a CP-C-3.';



CREATE OR REPLACE FUNCTION "public"."fn_alertes_dashboard_etab"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etab_id UUID;
  v_missions_orphelines JSONB;
  v_contrats_a_uploader JSONB;
BEGIN
  IF NOT est_admin() THEN
    v_etab_id := mon_etablissement_id();
    IF v_etab_id IS NULL THEN
      RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;
  END IF;

  -- Missions OUVERTE > 48h sans aucune candidature, début à venir
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mission_id', m.id,
    'intitule', m.intitule,
    'profession_requise', m.profession_requise::text,
    'debut_le', m.debut_le,
    'cree_le', m.cree_le,
    'taux_horaire_base', m.taux_horaire_base,
    'est_urgente', COALESCE(m.est_urgente, false),
    'jours_sans_candidature', EXTRACT(EPOCH FROM (NOW() - m.cree_le)) / 86400.0
  ) ORDER BY m.debut_le ASC), '[]'::jsonb)
  INTO v_missions_orphelines
  FROM missions m
  WHERE (v_etab_id IS NULL OR m.etablissement_id = v_etab_id)
    AND m.statut = 'OUVERTE'
    AND m.cree_le < NOW() - INTERVAL '48 hours'
    AND m.debut_le > NOW()
    AND NOT EXISTS (SELECT 1 FROM candidatures c WHERE c.mission_id = m.id);

  -- Missions SALARIE J-1 sans contrat travail uploadé (étab-scope)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mission_id', m.id,
    'intitule', m.intitule,
    'debut_le', m.debut_le,
    'soignant_prenom', s.prenom,
    'soignant_nom_initiale', LEFT(s.nom, 1) || '.',
    'heures_avant_debut', ROUND((EXTRACT(EPOCH FROM (m.debut_le - NOW())) / 3600.0)::numeric, 1)
  ) ORDER BY m.debut_le ASC), '[]'::jsonb)
  INTO v_contrats_a_uploader
  FROM missions m
  JOIN soignants s ON s.id = m.soignant_assigne_id
  WHERE (v_etab_id IS NULL OR m.etablissement_id = v_etab_id)
    AND m.statut IN ('ASSIGNEE','EN_COURS')
    AND m.type_contrat_applique = 'SALARIE'
    AND m.debut_le >= NOW()
    AND m.debut_le < NOW() + INTERVAL '48 hours'
    AND m.soignant_assigne_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM contrats_travail_missions ct WHERE ct.mission_id = m.id);

  RETURN jsonb_build_object(
    'missions_sans_candidature_48h', v_missions_orphelines,
    'contrats_travail_a_uploader', v_contrats_a_uploader,
    'count_total',
      jsonb_array_length(v_missions_orphelines) + jsonb_array_length(v_contrats_a_uploader)
  );
END;
$$;


ALTER FUNCTION "public"."fn_alertes_dashboard_etab"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_analytics_etablissement"("p_etablissement_id" "uuid", "p_mois" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id UUID := mon_etablissement_id();
  v_debut DATE;
  v_result JSONB;
  v_taux_remplissage NUMERIC;
  v_cout_heure_moyen NUMERIC;
  v_turnover NUMERIC;
  v_missions_par_mois JSONB;
  v_top_professions JSONB;
  v_soignants_recurrents JSONB;
BEGIN
  IF NOT est_admin() AND v_etab_id IS DISTINCT FROM p_etablissement_id THEN
    RETURN jsonb_build_object('error', 'Accès refusé : analytics réservées au propriétaire de l''établissement');
  END IF;

  v_debut := (CURRENT_DATE - (p_mois || ' months')::INTERVAL)::DATE;

  SELECT ROUND(COALESCE(
    COUNT(*) FILTER(WHERE soignant_assigne_id IS NOT NULL) * 100.0 / NULLIF(COUNT(*), 0)
  , 0), 1) INTO v_taux_remplissage
  FROM missions WHERE etablissement_id = p_etablissement_id AND cree_le >= v_debut;

  SELECT ROUND(COALESCE(AVG(CASE WHEN duree_heures > 0 THEN total_brut / duree_heures END), 0), 2) INTO v_cout_heure_moyen
  FROM missions WHERE etablissement_id = p_etablissement_id AND statut = 'TERMINEE' AND debut_le >= v_debut;

  SELECT ROUND(COALESCE(
    COUNT(DISTINCT soignant_assigne_id) FILTER(WHERE statut = 'TERMINEE') * 1.0 / NULLIF(COUNT(*) FILTER(WHERE statut = 'TERMINEE'), 0)
  , 0), 2) INTO v_turnover
  FROM missions WHERE etablissement_id = p_etablissement_id AND debut_le >= v_debut;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mois', mois, 'total', total, 'terminees', terminees, 'gmv', gmv
  ) ORDER BY mois), '[]'::jsonb) INTO v_missions_par_mois
  FROM (
    SELECT TO_CHAR(cree_le, 'YYYY-MM') AS mois,
      COUNT(*) AS total,
      COUNT(*) FILTER(WHERE statut = 'TERMINEE') AS terminees,
      ROUND(COALESCE(SUM(total_brut) FILTER(WHERE statut = 'TERMINEE'), 0), 2) AS gmv
    FROM missions WHERE etablissement_id = p_etablissement_id AND cree_le >= v_debut
    GROUP BY TO_CHAR(cree_le, 'YYYY-MM')
  ) sub;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('profession', profession, 'nb', nb)), '[]'::jsonb) INTO v_top_professions
  FROM (
    SELECT profession_requise AS profession, COUNT(*) AS nb FROM missions
    WHERE etablissement_id = p_etablissement_id AND cree_le >= v_debut
    GROUP BY profession_requise ORDER BY nb DESC LIMIT 10
  ) sub;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('soignant_id', soignant_id, 'nb_missions', nb_missions)), '[]'::jsonb) INTO v_soignants_recurrents
  FROM (
    SELECT soignant_assigne_id AS soignant_id, COUNT(*) AS nb_missions FROM missions
    WHERE etablissement_id = p_etablissement_id AND statut = 'TERMINEE' AND debut_le >= v_debut
      AND soignant_assigne_id IS NOT NULL
    GROUP BY soignant_assigne_id HAVING COUNT(*) > 1 ORDER BY nb_missions DESC LIMIT 10
  ) sub;

  v_result := jsonb_build_object(
    'taux_remplissage', v_taux_remplissage, 'cout_heure_moyen', v_cout_heure_moyen,
    'turnover', v_turnover, 'missions_par_mois', v_missions_par_mois,
    'top_professions', v_top_professions, 'soignants_recurrents', v_soignants_recurrents
  );
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_analytics_etablissement"("p_etablissement_id" "uuid", "p_mois" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_candidature_soignant"("p_candidature_id" "uuid", "p_motif_categorie" "text", "p_texte_libre" "text", "p_justificatif_storage_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_candidature RECORD;
  v_mission RECORD;
  v_contrat RECORD;
  v_penalite jsonb;
  v_event_id uuid;
  v_points int;
  v_motif_event text;
  v_signalement boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE', 'error', 'Non authentifié');
  END IF;

  IF p_motif_categorie IS NULL OR p_motif_categorie NOT IN (
    'URGENCE_PERSONNELLE', 'URGENCE_MEDICALE', 'DEUIL',
    'PROBLEME_TRANSPORT', 'CHANGEMENT_AVIS', 'AUTRE'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MOTIF_INVALIDE',
                                'error', 'Motif requis (URGENCE_PERSONNELLE, URGENCE_MEDICALE, DEUIL, PROBLEME_TRANSPORT, CHANGEMENT_AVIS, AUTRE)');
  END IF;

  IF p_texte_libre IS NULL OR length(trim(p_texte_libre)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TEXTE_REQUIS',
                                'error', 'Texte libre obligatoire (min 10 caractères)');
  END IF;

  SELECT * INTO v_candidature FROM public.candidatures WHERE id = p_candidature_id;
  IF v_candidature IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CANDIDATURE_INTROUVABLE', 'error', 'Candidature introuvable');
  END IF;

  IF v_candidature.soignant_id != v_uid THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE',
                                'error', 'Vous n''êtes pas le soignant de cette candidature');
  END IF;

  IF v_candidature.statut NOT IN ('ACCEPTEE', 'EN_ATTENTE') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'STATUT_INVALIDE',
                                'error', 'Candidature pas dans un état annulable (statut : ' || v_candidature.statut || ')');
  END IF;

  SELECT * INTO v_mission FROM public.missions WHERE id = v_candidature.mission_id;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MISSION_INTROUVABLE', 'error', 'Mission introuvable');
  END IF;

  PERFORM set_config('jolene.annulation_soignant_ctx', 'true', true);

  IF v_candidature.statut = 'EN_ATTENTE' THEN
    UPDATE public.candidatures SET
      statut = 'ANNULEE',
      traite_le = NOW(),
      motif_refus = p_texte_libre
    WHERE id = p_candidature_id;

    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource, details
    ) VALUES (
      v_uid, 'SOIGNANT', 'SYSTEM', 'candidature', p_candidature_id,
      jsonb_build_object('evenement', 'CANDIDATURE_ANNULEE_PAR_SOIGNANT',
                          'motif_categorie', p_motif_categorie,
                          'texte_libre', p_texte_libre,
                          'libre', true,
                          'statut_initial', v_candidature.statut)
    );

    RETURN jsonb_build_object('success', true, 'libre', true, 'points', 0,
                                'message', 'Candidature retirée sans impact');
  END IF;

  v_penalite := public.fn_calculer_penalite_annulation_soignant(
    v_candidature.acceptee_a, v_mission.debut_le, v_mission.est_asap
  );

  v_points := (v_penalite->>'points')::int;
  v_motif_event := v_penalite->>'motif';
  v_signalement := COALESCE((v_penalite->>'signalement_admin')::boolean, false);

  UPDATE public.candidatures SET
    statut = 'ANNULEE',
    traite_le = NOW(),
    motif_refus = p_motif_categorie || ' : ' || p_texte_libre
  WHERE id = p_candidature_id;

  UPDATE public.missions SET
    statut = 'OUVERTE',
    soignant_assigne_id = NULL,
    modifie_le = NOW()
  WHERE id = v_candidature.mission_id AND statut IN ('ASSIGNEE', 'EN_COURS');

  SELECT * INTO v_contrat FROM public.contrats_mission
  WHERE mission_id = v_candidature.mission_id LIMIT 1;
  IF FOUND THEN
    UPDATE public.contrats_mission SET
      statut = 'RUPTURE_SOIGNANT',
      modifie_le = NOW()
    WHERE id = v_contrat.id;

    IF v_contrat.type_contrat IN ('CDD', 'CDD', 'SALARIE')
       AND v_contrat.statut = 'SIGNE_COMPLET' THEN
      INSERT INTO public.externalisation_actions (type_action, payload, source, source_id)
      VALUES ('DPAE_ANNULATION',
              jsonb_build_object('contrat_id', v_contrat.id, 'mission_id', v_candidature.mission_id,
                                  'motif', 'ANNULATION_SOIGNANT', 'echeance_legale_h', 48),
              'ANNULATION_MISSION', p_candidature_id);
    END IF;
  END IF;

  IF v_points < 0 THEN
    INSERT INTO public.evenements_score_soignant (
      soignant_id, type_evenement, points, motif, contestable,
      mission_id, candidature_id, justificatif_storage_path,
      details
    ) VALUES (
      v_uid, v_motif_event, v_points,
      p_motif_categorie || ' : ' || left(p_texte_libre, 200),
      true,
      v_candidature.mission_id, p_candidature_id, p_justificatif_storage_path,
      jsonb_build_object(
        'motif_categorie', p_motif_categorie,
        'texte_libre', p_texte_libre,
        'delta_mission_h', EXTRACT(EPOCH FROM (v_mission.debut_le - NOW())) / 3600,
        'delta_retract_min', EXTRACT(EPOCH FROM (NOW() - v_candidature.acceptee_a)) / 60,
        'est_asap', v_mission.est_asap,
        'signalement_admin', v_signalement
      )
    ) RETURNING id INTO v_event_id;

    IF v_signalement THEN
      INSERT INTO public.journaux_audit (
        acteur_id, type_acteur, action, type_ressource, id_ressource, details
      ) VALUES (
        v_uid, 'SOIGNANT', 'SYSTEM', 'soignant', v_uid,
        jsonb_build_object('evenement', 'ALERTE_ADMIN_NO_SHOW',
                            'mission_id', v_candidature.mission_id,
                            'event_score_id', v_event_id,
                            'motif_categorie', p_motif_categorie,
                            'action_requise', 'REVISION_MANUELLE_ADMIN')
      );
    END IF;
  END IF;

  INSERT INTO public.externalisation_actions (type_action, payload, source, source_id)
  VALUES
    ('EMAIL_NOTIF', jsonb_build_object(
      'destinataire_id', v_mission.etablissement_id,
      'type', 'CANDIDATURE_ANNULEE_SOIGNANT',
      'data', jsonb_build_object(
        'mission_id', v_mission.id,
        'motif_categorie', p_motif_categorie,
        'libre', v_points = 0
      )
    ), 'ANNULATION_MISSION', p_candidature_id),
    ('PUSH_NOTIF', jsonb_build_object(
      'destinataire_id', v_mission.etablissement_id,
      'type_evenement', 'CANDIDATURE_ANNULEE_SOIGNANT',
      'titre', 'Le soignant a annulé',
      'corps', 'La mission est de nouveau disponible. Notifications envoyées aux soignants matching.'
    ), 'ANNULATION_MISSION', p_candidature_id);

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'SOIGNANT', 'SYSTEM', 'candidature', p_candidature_id,
    jsonb_build_object(
      'evenement', 'CANDIDATURE_ANNULEE_PAR_SOIGNANT',
      'motif_categorie', p_motif_categorie,
      'texte_libre', p_texte_libre,
      'points', v_points,
      'motif_score', v_motif_event,
      'event_score_id', v_event_id,
      'mission_id', v_mission.id,
      'signalement_admin', v_signalement
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'libre', v_points = 0,
    'points', v_points,
    'motif_score', v_motif_event,
    'event_score_id', v_event_id,
    'contestable', v_points < 0,
    'signalement_admin', v_signalement
  );
END;
$$;


ALTER FUNCTION "public"."fn_annuler_candidature_soignant"("p_candidature_id" "uuid", "p_motif_categorie" "text", "p_texte_libre" "text", "p_justificatif_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_invitation_membre"("p_invitation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_invitation RECORD;
  v_perms jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  SELECT * INTO v_invitation FROM public.invitations_etablissement WHERE id = p_invitation_id;
  IF v_invitation IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'INVITATION_INTROUVABLE');
  END IF;

  SELECT public.fn_mes_permissions_etab(v_invitation.etablissement_id) INTO v_perms;
  IF NOT COALESCE((v_perms->'permissions'->>'gerer_equipe')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  UPDATE public.invitations_etablissement
  SET statut = 'ANNULEE'
  WHERE id = p_invitation_id AND statut = 'EN_ATTENTE';

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_annuler_invitation_membre"("p_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_mission"("p_mission_id" "uuid", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_is_admin BOOLEAN := est_admin();
    v_etab_id UUID := mon_etablissement_id();
    v_nouveau_statut public.statut_mission;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN '{"error":"Mission introuvable"}'::JSONB; END IF;

    IF auth.uid() IS NULL THEN
        RETURN '{"error":"Accès refusé"}'::jsonb;
    END IF;

    IF v_is_admin IS NOT TRUE
       AND v_mission.etablissement_id IS DISTINCT FROM v_etab_id
       AND v_mission.soignant_assigne_id IS DISTINCT FROM auth.uid() THEN
        RETURN '{"error":"Accès refusé"}'::jsonb;
    END IF;

    IF v_mission.statut NOT IN ('OUVERTE', 'ASSIGNEE', 'EN_COURS') THEN
        RETURN jsonb_build_object('error', 'Impossible d''annuler au statut ' || v_mission.statut);
    END IF;

    -- Déterminer le bon statut selon qui annule
    IF auth.uid() = v_mission.soignant_assigne_id THEN
        v_nouveau_statut := 'ANNULEE_PAR_SOIGNANT';
        UPDATE soignants SET
            score_fiabilite = GREATEST(0, score_fiabilite - 10),
            total_missions_annulees = total_missions_annulees + 1,
            modifie_le = NOW()
        WHERE id = v_mission.soignant_assigne_id;
    ELSE
        v_nouveau_statut := 'ANNULEE_PAR_ETABLISSEMENT';
    END IF;

    UPDATE missions SET
        statut = v_nouveau_statut,
        motif_annulation = COALESCE(p_motif, 'Annulée'),
        annulee_le = NOW(),
        annulee_par = auth.uid(),
        modifie_le = NOW()
    WHERE id = p_mission_id;

    UPDATE contrats_mission SET statut = 'ANNULE', modifie_le = NOW()
    WHERE mission_id = p_mission_id AND statut != 'SIGNE';

    IF v_mission.soignant_assigne_id IS NOT NULL AND auth.uid() != v_mission.soignant_assigne_id THEN
        INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (v_mission.soignant_assigne_id, 'MISSION_ANNULEE', 'Mission annulée',
            'La mission "' || v_mission.intitule || '" a été annulée.', '/soignant/missions', 'SOIGNANT');
    END IF;

    IF auth.uid() != v_mission.etablissement_id THEN
        INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (v_mission.etablissement_id, 'MISSION_ANNULEE', 'Mission annulée',
            'La mission "' || v_mission.intitule || '" a été annulée.', '/etablissement/missions', 'ETABLISSEMENT');
    END IF;

    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_annuler_mission"("p_mission_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_mission_complete"("p_mission_id" "uuid", "p_motif" "text", "p_source_litige_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_presence_id uuid;
  v_escrow public.paiements_escrow%ROWTYPE;
  v_refund jsonb;
BEGIN
  SELECT m.*
    INTO v_mission
    FROM public.missions m
   WHERE m.id = p_mission_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.stripe_transfers st
     WHERE st.mission_id = p_mission_id
       AND st.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
      'error', 'Un paiement Stripe Connect actif exige un reversal manuel vérifié.'
    );
  END IF;

  SELECT pe.*
    INTO v_escrow
    FROM public.paiements_escrow pe
   WHERE pe.mission_id = p_mission_id
     AND pe.statut NOT IN ('ECHOUE', 'DISPUTE')
   ORDER BY pe.cree_le DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND AND v_escrow.statut <> 'REMBOURSE' THEN
    v_refund := public.fn_escrow_rembourser(
      v_escrow.id,
      v_escrow.honoraires_cents,
      true,
      p_motif
    );
    IF COALESCE(v_refund @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
      RETURN v_refund;
    END IF;
  ELSIF v_mission.stripe_payment_intent_id IS NOT NULL THEN
    INSERT INTO public.externalisation_actions (
      type_action, payload, source, source_id
    ) VALUES (
      'STRIPE_REFUND_TOTAL',
      jsonb_build_object('mission_id', p_mission_id, 'motif', p_motif),
      'LITIGE_EXEC',
      p_source_litige_id
    );
  END IF;

  UPDATE public.missions
     SET statut = 'LITIGE',
         modifie_le = now()
   WHERE id = p_mission_id;

  SELECT p.id
    INTO v_presence_id
    FROM public.presences p
   WHERE p.mission_id = p_mission_id
   ORDER BY p.cree_le
   LIMIT 1
   FOR UPDATE;
  IF v_presence_id IS NOT NULL THEN
    UPDATE public.presences
       SET heures_ajustees_litige = 0,
           ajustement_litige_id = p_source_litige_id,
           motif_litige = p_motif,
           modifie_le = now()
     WHERE id = v_presence_id;
  END IF;

  INSERT INTO public.externalisation_actions (
    type_action, payload, source, source_id
  ) VALUES
    (
      'CHORUS_RECYCLER_FACTURE',
      jsonb_build_object('mission_id', p_mission_id, 'motif', 'ANNULATION'),
      'LITIGE_EXEC', p_source_litige_id
    ),
    (
      'DPAE_ANNULATION',
      jsonb_build_object('mission_id', p_mission_id, 'motif', p_motif),
      'LITIGE_EXEC', p_source_litige_id
    ),
    (
      'AVOIR_PDF_GENERATION',
      jsonb_build_object(
        'mission_id', p_mission_id,
        'type', 'TOTAL',
        'motif_avoir', 'ANNULATION_MISSION_SOIGNANT'
      ),
      'LITIGE_EXEC', p_source_litige_id
    );

  RETURN jsonb_build_object(
    'success', true,
    'mission_id', p_mission_id,
    'presence_id', v_presence_id,
    'refund', v_refund
  );
END;
$$;


ALTER FUNCTION "public"."fn_annuler_mission_complete"("p_mission_id" "uuid", "p_motif" "text", "p_source_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_mission_etab"("p_mission_id" "uuid", "p_motif_categorie" "text", "p_texte_libre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mission public.missions%ROWTYPE;
  v_contrat public.contrats_mission%ROWTYPE;
  v_presence_id uuid;
  v_indemnite jsonb;
  v_delta_mission interval;
  v_points integer := 0;
  v_type_evt text;
  v_event_id uuid;
  v_montant_indem numeric := 0;
  v_salarie boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'NON_AUTHENTIFIE',
      'error', 'Non authentifié'
    );
  END IF;
  IF p_motif_categorie IS NULL OR p_motif_categorie NOT IN (
    'BESOIN_DISPARU', 'BUDGET_REVU', 'REMPLACEMENT_INTERNE',
    'CHANGEMENT_PLANNING', 'CAS_FORCE_MAJEURE', 'AUTRE'
  ) THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'MOTIF_INVALIDE',
      'error', 'Motif requis'
    );
  END IF;
  IF p_texte_libre IS NULL OR length(btrim(p_texte_libre)) < 10 THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'TEXTE_REQUIS',
      'error', 'Texte libre obligatoire (min 10 caractères)'
    );
  END IF;

  SELECT m.*
    INTO v_mission
    FROM public.missions m
   WHERE m.id = p_mission_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'MISSION_INTROUVABLE',
      'error', 'Mission introuvable'
    );
  END IF;
  IF public.est_admin() IS NOT TRUE
     AND (
       v_mission.etablissement_id IS DISTINCT FROM public.mon_etablissement_id()
       OR public.fn_a_permission_etablissement(
         'missions', v_mission.etablissement_id
       ) IS NOT TRUE
     ) THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'NON_AUTORISE',
      'error', 'Non autorisé à annuler cette mission'
    );
  END IF;
  IF v_mission.statut IN (
    'LITIGE', 'ANNULEE_PAR_ETABLISSEMENT', 'TERMINEE'
  ) THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'STATUT_INVALIDE',
      'error', 'Mission déjà annulée ou terminée'
    );
  END IF;

  v_delta_mission := v_mission.debut_le - now();
  IF v_mission.statut = 'OUVERTE' THEN
    UPDATE public.missions
       SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = now()
     WHERE id = p_mission_id
       AND statut = 'OUVERTE';
    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource, details
    ) VALUES (
      v_uid, 'ADMIN_ETABLISSEMENT', 'ANNULATION_MISSION', 'mission',
      p_mission_id,
      jsonb_build_object(
        'evenement', 'MISSION_ANNULEE_ETAB',
        'motif_categorie', p_motif_categorie,
        'texte_libre', p_texte_libre,
        'libre', true,
        'statut_initial', 'OUVERTE'
      )
    );
    RETURN jsonb_build_object(
      'success', true, 'libre', true, 'points', 0,
      'indemnite_montant', 0,
      'message', 'Mission ouverte annulée sans impact'
    );
  END IF;

  SELECT c.*
    INTO v_contrat
    FROM public.contrats_mission c
   WHERE c.mission_id = p_mission_id
   ORDER BY c.cree_le DESC
   LIMIT 1
   FOR UPDATE;
  SELECT p.id
    INTO v_presence_id
    FROM public.presences p
   WHERE p.mission_id = p_mission_id
   ORDER BY p.cree_le
   LIMIT 1
   FOR UPDATE;
  v_salarie := v_contrat.id IS NOT NULL
    AND v_contrat.type_contrat IN ('CDD', 'CDDU', 'VACATION');

  IF v_presence_id IS NOT NULL THEN
    UPDATE public.missions
       SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = now()
     WHERE id = p_mission_id;
    UPDATE public.presences
       SET motif_litige = btrim(
             COALESCE(motif_litige, '') || ' ANNULEE_ETAB_APRES_POINTAGE'
           ),
           modifie_le = now()
     WHERE id = v_presence_id;
    v_points := -20;
    v_type_evt := 'ANNULATION_APRES_POINTAGE';
    v_indemnite := public.fn_calculer_indemnite_annulation_etab(
      COALESCE(
        v_contrat.type_contrat,
        v_mission.type_contrat_applique::text,
        'SALARIE'
      ),
      COALESCE(v_mission.duree_heures, 0)
        * COALESCE(v_mission.taux_horaire_base, 0),
      v_mission.duree_heures,
      v_mission.taux_horaire_base,
      interval '0'
    );
    v_montant_indem := COALESCE((v_indemnite->>'montant')::numeric, 0);
  ELSIF v_contrat.id IS NOT NULL AND v_contrat.statut = 'SIGNE_COMPLET' THEN
    UPDATE public.missions
       SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = now()
     WHERE id = p_mission_id;
    UPDATE public.contrats_mission
       SET statut = 'RUPTURE_ETAB', modifie_le = now()
     WHERE id = v_contrat.id
       AND statut = 'SIGNE_COMPLET';
    v_indemnite := public.fn_calculer_indemnite_annulation_etab(
      v_contrat.type_contrat,
      COALESCE(v_mission.duree_heures, 0)
        * COALESCE(v_mission.taux_horaire_base, 0),
      v_mission.duree_heures,
      v_mission.taux_horaire_base,
      v_delta_mission
    );
    v_montant_indem := COALESCE((v_indemnite->>'montant')::numeric, 0);
    v_points := -10;
    v_type_evt := CASE
      WHEN v_salarie THEN 'ANNULATION_CDD_SIGNE'
      ELSE 'ANNULATION_LIBERAL_SIGNE'
    END;
    IF v_salarie THEN
      INSERT INTO public.externalisation_actions (
        type_action, payload, source, source_id
      ) VALUES (
        'DPAE_ANNULATION',
        jsonb_build_object(
          'contrat_id', v_contrat.id,
          'mission_id', p_mission_id,
          'motif', 'ANNULATION_ETAB',
          'echeance_legale_h', 48
        ),
        'ANNULATION_MISSION', p_mission_id
      );
    END IF;
  ELSE
    UPDATE public.missions
       SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = now()
     WHERE id = p_mission_id;
    v_points := -3;
    v_type_evt := 'ANNULATION_AVANT_CONTRAT';
    v_indemnite := jsonb_build_object(
      'montant', 0,
      'motif', 'AUCUNE_INDEMNITE_AVANT_CONTRAT'
    );
  END IF;

  INSERT INTO public.evenements_score_etab (
    etablissement_id, type_evenement, points, motif, contestable,
    mission_id, details
  ) VALUES (
    v_mission.etablissement_id, v_type_evt, v_points,
    p_motif_categorie || ' : ' || left(p_texte_libre, 200),
    true, p_mission_id,
    jsonb_build_object(
      'motif_categorie', p_motif_categorie,
      'texte_libre', p_texte_libre,
      'delta_mission_h', extract(epoch FROM v_delta_mission) / 3600,
      'indemnite', v_indemnite,
      'indemnite_statut', CASE
        WHEN v_montant_indem > 0 THEN 'DUE_TRAITEMENT_ETABLISSEMENT'
        ELSE 'NON_DUE'
      END,
      'pointage_existant', v_presence_id IS NOT NULL,
      'contrat_signe', v_contrat.id IS NOT NULL
        AND v_contrat.statut = 'SIGNE_COMPLET'
    )
  ) RETURNING id INTO v_event_id;

  -- Suivi honnête : dette à traiter par l'établissement, sans mouvement
  -- Stripe/SWAN automatique et sans type REFUND détourné.
  IF v_montant_indem > 0 THEN
    INSERT INTO public.notifications (
      destinataire_id, type_destinataire, type, titre, corps, lien,
      type_ressource, id_ressource
    ) VALUES (
      v_mission.etablissement_id,
      'ETABLISSEMENT',
      'SYSTEM',
      'Indemnité d''annulation à traiter',
      'Une indemnité de ' || v_montant_indem
        || '€ est due au soignant. ' || CASE
          WHEN v_salarie THEN 'Intégrez-la à la paie et conservez la preuve.'
          ELSE 'Réglez-la selon le contrat et conservez la preuve.'
        END,
      '/etablissement/facturation',
      'mission',
      p_mission_id
    );
  END IF;

  INSERT INTO public.externalisation_actions (
    type_action, payload, source, source_id
  ) VALUES (
    'AVOIR_PDF_GENERATION',
    jsonb_build_object(
      'mission_id', p_mission_id,
      'type', 'ANNULATION_ETAB',
      'motif_avoir', 'ANNULATION_MISSION_ETAB',
      'montant_indemnite', v_montant_indem
    ),
    'ANNULATION_MISSION', p_mission_id
  );

  IF v_mission.soignant_assigne_id IS NOT NULL THEN
    INSERT INTO public.externalisation_actions (
      type_action, payload, source, source_id
    ) VALUES
      (
        'EMAIL_NOTIF',
        jsonb_build_object(
          'destinataire_id', v_mission.soignant_assigne_id,
          'type', 'MISSION_ANNULEE_ETAB',
          'data', jsonb_build_object(
            'mission_id', p_mission_id,
            'motif_categorie', p_motif_categorie,
            'indemnite_montant', v_montant_indem,
            'indemnite_motif', v_indemnite->>'motif',
            'indemnite_statut', CASE
              WHEN v_montant_indem > 0 THEN 'DUE_EN_COURS_DE_TRAITEMENT'
              ELSE 'NON_DUE'
            END
          )
        ),
        'ANNULATION_MISSION', p_mission_id
      ),
      (
        'PUSH_NOTIF',
        jsonb_build_object(
          'destinataire_id', v_mission.soignant_assigne_id,
          'type_evenement', 'MISSION_ANNULEE_ETAB',
          'titre', 'Mission annulée par l''établissement',
          'corps', CASE
            WHEN v_montant_indem > 0 THEN
              'Une indemnité de ' || v_montant_indem
                || '€ est due et doit être traitée par l''établissement.'
            ELSE 'Aucun contrat signé, pas d''indemnité.'
          END
        ),
        'ANNULATION_MISSION', p_mission_id
      );
  END IF;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'ANNULATION_MISSION', 'mission',
    p_mission_id,
    jsonb_build_object(
      'evenement', 'MISSION_ANNULEE_ETAB',
      'motif_categorie', p_motif_categorie,
      'texte_libre', p_texte_libre,
      'points', v_points,
      'type_evenement', v_type_evt,
      'indemnite', v_indemnite,
      'indemnite_statut', CASE
        WHEN v_montant_indem > 0 THEN 'DUE_TRAITEMENT_ETABLISSEMENT'
        ELSE 'NON_DUE'
      END,
      'mode_traitement', CASE
        WHEN v_salarie THEN 'PAIE_ETABLISSEMENT'
        ELSE 'REGLEMENT_CONTRACTUEL_ETABLISSEMENT'
      END,
      'pointage_existant', v_presence_id IS NOT NULL,
      'contrat_signe', v_contrat.id IS NOT NULL
        AND v_contrat.statut = 'SIGNE_COMPLET',
      'event_score_id', v_event_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'libre', v_points = 0,
    'points', v_points,
    'type_evenement', v_type_evt,
    'event_score_id', v_event_id,
    'indemnite', v_indemnite,
    'indemnite_statut', CASE
      WHEN v_montant_indem > 0 THEN 'DUE_TRAITEMENT_ETABLISSEMENT'
      ELSE 'NON_DUE'
    END,
    'message', CASE
      WHEN v_montant_indem > 0 THEN
        'Indemnité de ' || v_montant_indem
          || '€ due au soignant, à traiter par l''établissement'
      WHEN v_points = -3 THEN
        'Annulation enregistrée, pas d''indemnité (contrat non signé)'
      ELSE 'Annulation enregistrée'
    END
  );
END;
$$;


ALTER FUNCTION "public"."fn_annuler_mission_etab"("p_mission_id" "uuid", "p_motif_categorie" "text", "p_texte_libre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_mission_etablissement"("p_mission_id" "uuid", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN '{"error":"Mission introuvable"}'::JSONB; END IF;
    IF public.est_admin() IS NOT TRUE
       AND (
         v_mission.etablissement_id IS DISTINCT FROM public.mon_etablissement_id()
         OR public.fn_a_permission_etablissement(
           'missions', v_mission.etablissement_id
         ) IS NOT TRUE
       ) THEN
        RETURN '{"error":"Cette mission ne vous appartient pas"}'::JSONB;
    END IF;
    IF v_mission.statut NOT IN ('OUVERTE', 'ASSIGNEE') THEN
        RETURN '{"error":"Impossible d''annuler une mission en cours ou terminée. Ouvrez un litige si nécessaire."}'::JSONB;
    END IF;

    UPDATE missions SET
        statut = 'ANNULEE_PAR_ETABLISSEMENT',
        annulee_par = COALESCE(mon_etablissement_id(), auth.uid()),
        annulee_le = NOW(),
        motif_annulation = COALESCE(p_motif, 'Annulée par l''établissement'),
        modifie_le = NOW()
    WHERE id = p_mission_id;

    -- ★ Notifier le soignant assigné
    IF v_mission.soignant_assigne_id IS NOT NULL THEN
        INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (v_mission.soignant_assigne_id, 'SYSTEM',
            '❌ Mission annulée par l''établissement',
            'La mission "' || v_mission.intitule || '" a été annulée.' ||
            CASE WHEN p_motif IS NOT NULL THEN ' Motif : ' || p_motif ELSE '' END,
            '/soignant/missions', 'SOIGNANT');
    END IF;

    -- ★ Audit
    PERFORM fn_ecrire_audit_safe(
        COALESCE(mon_etablissement_id(), auth.uid()), 'ETABLISSEMENT', 
        'MISSION_ANNULEE_PAR_ETABLISSEMENT', 'mission', p_mission_id, NULL,
        jsonb_build_object('motif', p_motif, 'soignant_assigne', v_mission.soignant_assigne_id)
    );

    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_annuler_mission_etablissement"("p_mission_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_mission_soignant"("p_mission_id" "uuid", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_heures_avant NUMERIC;
    v_est_tardive BOOLEAN;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN '{"error":"Mission introuvable"}'::JSONB; END IF;

    IF v_mission.soignant_assigne_id != auth.uid() THEN
        RETURN '{"error":"Cette mission ne vous est pas assignée"}'::JSONB;
    END IF;
    IF v_mission.statut NOT IN ('ASSIGNEE') THEN
        RETURN '{"error":"Annulation impossible dans cet état. Si la mission est en cours, ouvrez un litige."}'::JSONB;
    END IF;

    v_heures_avant := EXTRACT(EPOCH FROM (v_mission.debut_le - NOW())) / 3600;
    v_est_tardive := v_heures_avant < 24;

    UPDATE missions SET
        statut = 'OUVERTE',
        soignant_assigne_id = NULL,
        annulee_par = auth.uid(),
        annulee_le = NOW(),
        motif_annulation = COALESCE(p_motif, 'Annulée par le soignant'),
        modifie_le = NOW()
    WHERE id = p_mission_id;

    IF v_est_tardive THEN
        UPDATE soignants SET
            total_missions_annulees = COALESCE(total_missions_annulees, 0) + 1,
            score_fiabilite = GREATEST(0, COALESCE(score_fiabilite, 50) - 8),
            modifie_le = NOW()
        WHERE id = auth.uid();
    ELSE
        UPDATE soignants SET
            total_missions_annulees = COALESCE(total_missions_annulees, 0) + 1,
            modifie_le = NOW()
        WHERE id = auth.uid();
    END IF;

    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (v_mission.etablissement_id, 'SYSTEM',
        CASE WHEN v_est_tardive THEN '⚠️ Annulation tardive' ELSE '❌ Mission annulée' END,
        'Le soignant a annulé la mission "' || v_mission.intitule || '"' ||
        CASE WHEN v_est_tardive THEN ' à moins de 24h du début.' ELSE '.' END ||
        CASE WHEN p_motif IS NOT NULL THEN ' Motif : ' || p_motif ELSE '' END ||
        ' La mission est remise en ligne.',
        '/etablissement/missions', 'ETABLISSEMENT');

    PERFORM fn_ecrire_audit_safe(
        auth.uid(), 'SOIGNANT', 'MISSION_ANNULEE_PAR_SOIGNANT', 'mission', p_mission_id, NULL,
        jsonb_build_object('tardive', v_est_tardive, 'heures_avant', ROUND(v_heures_avant, 1), 'motif', p_motif)
    );

    IF COALESCE(v_mission.est_urgente, false) = true THEN
        PERFORM public.fn_calculer_score_fiabilite_v2(auth.uid(), 'annulation_mission_urgente');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'annulation_tardive', v_est_tardive,
        'penalite_score', CASE WHEN v_est_tardive THEN -8 ELSE 0 END
    );
END;
$$;


ALTER FUNCTION "public"."fn_annuler_mission_soignant"("p_mission_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_serie"("p_serie_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF NOT est_admin_etablissement() AND NOT est_admin() THEN
        RETURN '{"error":"Accès refusé"}'::JSONB;
    END IF;

    UPDATE missions SET
        statut = 'ANNULEE_PAR_ETABLISSEMENT',
        modifie_le = NOW()
    WHERE serie_id = p_serie_id
      AND statut IN ('OUVERTE', 'ASSIGNEE')
      AND (etablissement_id = mon_etablissement_id() OR est_admin());

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN jsonb_build_object('success', true, 'missions_annulees', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_annuler_serie"("p_serie_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_annuler_serie_etablissement"("p_mission_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid;
  v_count int := 0;
  v_mid uuid;
BEGIN
  -- Get caller's establishment
  SELECT mon_etablissement_id() INTO v_etab_id;
  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Établissement non trouvé');
  END IF;

  -- Cancel all missions in a single transaction
  FOREACH v_mid IN ARRAY p_mission_ids LOOP
    UPDATE missions 
    SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = now()
    WHERE id = v_mid 
      AND etablissement_id = v_etab_id 
      AND statut = 'OUVERTE';
    IF FOUND THEN v_count := v_count + 1; END IF;
  END LOOP;

  -- Audit
  PERFORM fn_ecrire_audit_safe(
    auth.uid(), 'ADMIN_ETABLISSEMENT', 'MISSION_ANNULATION_SERIE',
    'mission', v_etab_id, NULL,
    jsonb_build_object('nb_annulees', v_count, 'mission_ids', to_jsonb(p_mission_ids)),
    NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'nb_annulees', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_annuler_serie_etablissement"("p_mission_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_anonymiser_gps_anciennes"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE presences
  SET arrivee_lat = NULL, arrivee_lng = NULL,
      depart_lat = NULL, depart_lng = NULL,
      arrivee_precision_gps_m = NULL, depart_precision_gps_m = NULL,
      arrivee_ip = NULL, depart_ip = NULL
  WHERE (pointage_arrivee_le < now() - interval '90 days')
    AND (arrivee_lat IS NOT NULL OR depart_lat IS NOT NULL);
END;
$$;


ALTER FUNCTION "public"."fn_anonymiser_gps_anciennes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_anti_seed_facture_honoraire"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mission_net numeric;
  v_strategie public.strategie_facturation;
  v_montant_attendu numeric;
  v_calcul_periode jsonb;
  v_ecart numeric;
  v_ctx text;
  v_admin_reason text;
BEGIN
  v_ctx := NULLIF(current_setting('jolene.generate_invoice_context', true), '');
  IF v_ctx = 'true' THEN
    RETURN NEW;
  END IF;

  v_admin_reason := NULLIF(current_setting('jolene.admin_seed_override_reason', true), '');
  IF v_admin_reason IS NOT NULL THEN
    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource, details
    ) VALUES (
      auth.uid(), 'ADMIN_PLATEFORME', 'OVERRIDE_ANTI_SEED',
      'factures_honoraires', NEW.id,
      jsonb_build_object(
        'reason', v_admin_reason,
        'mission_id', NEW.mission_id,
        'montant_ht', NEW.montant_ht,
        'numero_facture', NEW.numero_facture
      )
    );
    RETURN NEW;
  END IF;

  IF public.est_admin() THEN
    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource, details
    ) VALUES (
      auth.uid(), 'ADMIN_PLATEFORME', 'OVERRIDE_ANTI_SEED',
      'factures_honoraires', NEW.id,
      jsonb_build_object(
        'reason', 'admin_context (résolution litige / ajustement financier)',
        'mission_id', NEW.mission_id,
        'montant_ht', NEW.montant_ht,
        'numero_facture', NEW.numero_facture
      )
    );
    RETURN NEW;
  END IF;

  SELECT m.net_a_payer, m.strategie_facturation
  INTO v_mission_net, v_strategie
  FROM public.missions m
  WHERE m.id = NEW.mission_id;

  IF v_mission_net IS NULL THEN
    RAISE EXCEPTION 'anti-seed facture: mission % sans snapshot financier (net_a_payer=NULL). Utilisez generate-invoice ou définissez jolene.admin_seed_override_reason.',
      NEW.mission_id USING ERRCODE = 'check_violation';
  END IF;

  IF v_strategie = 'HEBDO_ET_FINALE'
     AND NEW.periode_debut IS NOT NULL
     AND NEW.periode_fin IS NOT NULL THEN
    v_calcul_periode := public.fn_calculer_montant_periode(
      NEW.mission_id,
      NEW.periode_debut,
      NEW.periode_fin
    );
    v_montant_attendu := NULLIF(v_calcul_periode->>'montant_ht_periode', '')::numeric;
  ELSE
    v_montant_attendu := v_mission_net;
  END IF;

  IF v_montant_attendu IS NULL THEN
    RAISE EXCEPTION 'anti-seed facture: montant attendu indéterminable pour mission % et période %–%.',
      NEW.mission_id, NEW.periode_debut, NEW.periode_fin
      USING ERRCODE = 'check_violation';
  END IF;

  v_ecart := abs(COALESCE(NEW.montant_ht, 0) - v_montant_attendu);
  IF v_ecart > 0.50 THEN
    RAISE EXCEPTION 'anti-seed facture: montant_ht % incohérent avec le montant attendu % pour la période %–% (écart=%€ > 0.50€).',
      NEW.montant_ht,
      v_montant_attendu,
      NEW.periode_debut,
      NEW.periode_fin,
      v_ecart
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_anti_seed_facture_honoraire"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_anti_seed_mission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_ctx text;
  v_admin_reason text;
  v_calcul jsonb;
  v_taux_effectif numeric;
  v_expected_duree numeric;
  v_expected_brut numeric;
  v_expected_ifm numeric;
  v_expected_icp numeric;
  v_expected_net numeric;
  v_est_liberal boolean;
  v_snapshot_absent boolean;
BEGIN
  v_ctx := NULLIF(
    pg_catalog.current_setting('jolene.creer_mission_context', true),
    ''
  );
  IF v_ctx = 'true' THEN RETURN NEW; END IF;

  v_admin_reason := NULLIF(
    pg_catalog.current_setting('jolene.admin_seed_override_reason', true),
    ''
  );
  IF v_admin_reason IS NOT NULL THEN
    INSERT INTO public.journaux_audit (
      acteur_id,
      type_acteur,
      action,
      type_ressource,
      id_ressource,
      details
    ) VALUES (
      auth.uid(),
      'ADMIN_PLATEFORME',
      'OVERRIDE_ANTI_SEED',
      'missions',
      NEW.id,
      pg_catalog.jsonb_build_object(
        'reason', v_admin_reason,
        'intitule', NEW.intitule,
        'etablissement_id', NEW.etablissement_id,
        'total_brut', NEW.total_brut,
        'net_a_payer', NEW.net_a_payer
      )
    );
    RETURN NEW;
  END IF;

  -- Les colonnes ont historiquement DEFAULT 0. Un INSERT applicatif/API qui ne
  -- fournit aucun snapshot arrive donc ici avec 0/0, et non NULL/NULL. Ces deux
  -- couples représentent l'absence de snapshot : le moteur canonique placé
  -- après ce garde les remplit. Toute autre combinaison reste contrôlée.
  v_snapshot_absent :=
    (NEW.total_brut IS NULL AND NEW.net_a_payer IS NULL)
    OR (NEW.total_brut = 0 AND NEW.net_a_payer = 0);

  IF (NEW.total_brut IS NULL) <> (NEW.net_a_payer IS NULL) THEN
    RAISE EXCEPTION
      'anti-seed mission: total_brut et net_a_payer doivent être tous deux NULL ou tous deux renseignés.'
      USING ERRCODE = '23514';
  END IF;
  -- Conserve le parcours applicatif historique : quand aucun snapshot n'est
  -- fourni, le moteur financier placé après ce garde calcule toutes les
  -- colonnes. Le garde ne doit pas imposer duree_heures aux INSERT normaux.
  IF v_snapshot_absent THEN RETURN NEW; END IF;

  IF NEW.duree_heures IS NULL OR NEW.taux_horaire_base IS NULL THEN
    RAISE EXCEPTION
      'anti-seed mission: durée et taux horaire sont obligatoires pour un INSERT direct. Utilisez fn_creer_mission ou jolene.admin_seed_override_reason.'
      USING ERRCODE = '23514';
  END IF;

  -- Le trigger plafond Rist s'exécute avant celui-ci et a déjà posé le taux
  -- réellement applicable à la profession requise par la mission.
  v_taux_effectif := COALESCE(
    NEW.taux_rist_plafonne,
    NEW.taux_horaire_base
  );
  v_calcul := public.fn_calculer_remuneration_mission(
    NEW.debut_le,
    NEW.fin_le,
    v_taux_effectif,
    NEW.etablissement_id,
    NULL
  );
  v_expected_duree := pg_catalog.round(
    (v_calcul ->> 'heures_totales')::numeric,
    2
  );
  v_expected_brut := pg_catalog.round(
    (v_calcul ->> 'total_brut')::numeric,
    2
  );

  -- La mission, jamais le profil du soignant, décide du régime financier.
  v_est_liberal := COALESCE(
    NEW.type_contrat_applique::text,
    CASE
      WHEN NEW.type_contrat_recherche = 'LIBERAL' THEN 'LIBERAL'
      ELSE 'SALARIE'
    END
  ) = 'LIBERAL';
  IF v_est_liberal THEN
    v_expected_ifm := 0;
    v_expected_icp := 0;
  ELSE
    v_expected_ifm := pg_catalog.round(v_expected_brut * 0.10, 2);
    v_expected_icp := pg_catalog.round(
      (v_expected_brut + v_expected_ifm) * 0.10,
      2
    );
  END IF;
  v_expected_net := pg_catalog.round(
    v_expected_brut + v_expected_ifm + v_expected_icp,
    2
  );

  IF NEW.duree_heures IS DISTINCT FROM v_expected_duree THEN
    RAISE EXCEPTION
      'anti-seed mission: duree_heures % incohérente avec le créneau canonique %.',
      NEW.duree_heures,
      v_expected_duree
      USING ERRCODE = '23514';
  END IF;

  IF NEW.total_brut IS DISTINCT FROM v_expected_brut THEN
    RAISE EXCEPTION
      'anti-seed mission: total_brut % incohérent avec le moteur canonique % (majorations incluses).',
      NEW.total_brut,
      v_expected_brut
      USING ERRCODE = '23514';
  END IF;
  IF NEW.net_a_payer IS DISTINCT FROM v_expected_net THEN
    RAISE EXCEPTION
      'anti-seed mission: net_a_payer % incohérent avec brut + IFM + ICP = %. La commission Jolene est facturée séparément et ne doit jamais être déduite.',
      NEW.net_a_payer,
      v_expected_net
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_anti_seed_mission"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_anti_seed_mission"() IS 'Contrôle avant calcul les snapshots financiers seedés : majorations incluses, IFM/ICP selon le contrat de la mission, commission jamais déduite.';



CREATE OR REPLACE FUNCTION "public"."fn_apercu_marche_profession"("p_profession" "text" DEFAULT NULL::"text", "p_lat" double precision DEFAULT NULL::double precision, "p_lng" double precision DEFAULT NULL::double precision, "p_rayon_km" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_geo boolean := p_lat IS NOT NULL AND p_lng IS NOT NULL AND COALESCE(p_rayon_km, 0) > 0;
  v_nb_missions integer;
  v_taux_max numeric;
  v_taux_moyen numeric;
  v_nb_etabs integer;
BEGIN
  SELECT count(*)::integer, max(m.taux_horaire_base), round(avg(m.taux_horaire_base), 2)
  INTO v_nb_missions, v_taux_max, v_taux_moyen
  FROM missions m
  JOIN etablissements e ON e.id = m.etablissement_id
  WHERE m.statut = 'OUVERTE'
    AND m.debut_le > now()
    AND e.supprime_le IS NULL
    AND (p_profession IS NULL OR btrim(p_profession) = '' OR m.profession_requise::text = btrim(p_profession))
    AND (
      NOT v_geo
      OR (e.adresse_lat IS NOT NULL AND e.adresse_lng IS NOT NULL
          AND public.fn_haversine_distance_m(e.adresse_lat, e.adresse_lng, p_lat::numeric, p_lng::numeric) <= p_rayon_km * 1000)
    );

  -- Preuve sociale de repli quand le marché est vide : établissements inscrits.
  SELECT count(*)::integer
  INTO v_nb_etabs
  FROM etablissements e
  WHERE e.supprime_le IS NULL
    AND (
      NOT v_geo
      OR (e.adresse_lat IS NOT NULL AND e.adresse_lng IS NOT NULL
          AND public.fn_haversine_distance_m(e.adresse_lat, e.adresse_lng, p_lat::numeric, p_lng::numeric) <= p_rayon_km * 1000)
    );

  RETURN jsonb_build_object(
    'nb_missions', COALESCE(v_nb_missions, 0),
    'taux_max', v_taux_max,
    'taux_moyen', v_taux_moyen,
    'nb_etablissements', COALESCE(v_nb_etabs, 0),
    'zone', CASE WHEN v_geo THEN 'rayon' ELSE 'national' END
  );
END;
$$;


ALTER FUNCTION "public"."fn_apercu_marche_profession"("p_profession" "text", "p_lat" double precision, "p_lng" double precision, "p_rayon_km" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_compensation_partielle"("p_mission_id" "uuid", "p_pourcentage" numeric, "p_motif" "text", "p_source_litige_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_presence_id uuid;
  v_taux numeric;
  v_escrow public.paiements_escrow%ROWTYPE;
  v_refund jsonb;
  v_honoraires_refund integer;
BEGIN
  IF p_pourcentage IS NULL OR p_pourcentage <= 0 OR p_pourcentage > 100 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Pourcentage doit être entre 0 et 100'
    );
  END IF;

  SELECT m.*
    INTO v_mission
    FROM public.missions m
   WHERE m.id = p_mission_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.stripe_transfers st
     WHERE st.mission_id = p_mission_id
       AND st.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
      'error', 'Un paiement Stripe Connect actif exige un reversal manuel vérifié.'
    );
  END IF;

  SELECT pe.*
    INTO v_escrow
    FROM public.paiements_escrow pe
   WHERE pe.mission_id = p_mission_id
     AND pe.statut NOT IN ('ECHOUE', 'DISPUTE', 'REMBOURSE')
   ORDER BY pe.cree_le DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    v_honoraires_refund := round(
      v_escrow.honoraires_cents::numeric * p_pourcentage / 100
    )::integer;
    v_refund := public.fn_escrow_rembourser(
      v_escrow.id,
      v_honoraires_refund,
      p_pourcentage = 100,
      p_motif
    );
    IF COALESCE(v_refund @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
      RETURN v_refund;
    END IF;
  ELSIF v_mission.stripe_payment_intent_id IS NOT NULL THEN
    INSERT INTO public.externalisation_actions (
      type_action, payload, source, source_id
    ) VALUES (
      'STRIPE_REFUND_PARTIEL',
      jsonb_build_object(
        'mission_id', p_mission_id,
        'pourcentage', p_pourcentage
      ),
      'LITIGE_EXEC',
      p_source_litige_id
    );
  END IF;

  v_taux := (100 - p_pourcentage) / 100.0;
  SELECT p.id
    INTO v_presence_id
    FROM public.presences p
   WHERE p.mission_id = p_mission_id
   ORDER BY p.cree_le
   LIMIT 1
   FOR UPDATE;
  IF v_presence_id IS NOT NULL THEN
    UPDATE public.presences
       SET heures_ajustees_litige = round(
             duree_brute_min::numeric / 60 * v_taux,
             2
           ),
           ajustement_litige_id = p_source_litige_id,
           motif_litige = p_motif,
           modifie_le = now()
     WHERE id = v_presence_id;
  END IF;

  INSERT INTO public.externalisation_actions (
    type_action, payload, source, source_id
  ) VALUES (
    'AVOIR_PDF_GENERATION',
    jsonb_build_object(
      'mission_id', p_mission_id,
      'type', 'PARTIEL',
      'pourcentage', p_pourcentage,
      'motif_avoir', 'COMPENSATION_PARTIELLE'
    ),
    'LITIGE_EXEC',
    p_source_litige_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'mission_id', p_mission_id,
    'pourcentage_compensation', p_pourcentage,
    'presence_id', v_presence_id,
    'refund', v_refund
  );
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_compensation_partielle"("p_mission_id" "uuid", "p_pourcentage" numeric, "p_motif" "text", "p_source_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_credits_disponibles_etab"("p_facture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_facture RECORD;
  v_etab_id UUID;
  v_credits_dispo NUMERIC;
  v_a_deduire NUMERIC;
  v_credit RECORD;
  v_reste_a_deduire NUMERIC;
BEGIN
  IF NOT (est_admin() OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Accès refusé');
  END IF;

  SELECT id, etablissement_id, montant_ht, montant_ttc, statut, type_document
  INTO v_facture FROM factures WHERE id = p_facture_id;
  IF v_facture IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Facture introuvable');
  END IF;
  IF v_facture.statut <> 'BROUILLON' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Facture non modifiable (statut: ' || v_facture.statut || ')');
  END IF;
  IF v_facture.type_document <> 'FACTURE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Crédits applicables uniquement sur FACTURE');
  END IF;

  v_etab_id := v_facture.etablissement_id;

  SELECT COALESCE(SUM(montant_eur), 0) INTO v_credits_dispo
  FROM credits_etablissement WHERE etablissement_id = v_etab_id AND applique_le IS NULL;

  IF v_credits_dispo <= 0 THEN
    RETURN jsonb_build_object('success', true, 'credit_applique_eur', 0, 'message', 'Aucun crédit disponible');
  END IF;

  v_a_deduire := LEAST(v_credits_dispo, v_facture.montant_ht);
  v_reste_a_deduire := v_a_deduire;

  FOR v_credit IN
    SELECT id, montant_eur FROM credits_etablissement
    WHERE etablissement_id = v_etab_id AND applique_le IS NULL
    ORDER BY cree_le ASC
  LOOP
    EXIT WHEN v_reste_a_deduire <= 0;
    UPDATE credits_etablissement SET applique_le = NOW(), facture_id = p_facture_id WHERE id = v_credit.id;
    v_reste_a_deduire := v_reste_a_deduire - v_credit.montant_eur;
  END LOOP;

  UPDATE factures
  SET montant_ht = GREATEST(0, montant_ht - v_a_deduire),
      montant_ttc = GREATEST(0, montant_ttc - v_a_deduire)
  WHERE id = p_facture_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_etab_id,
    p_type_acteur := 'SYSTEME',
    p_action := 'CREDIT_PARRAINAGE_APPLIQUE',
    p_type_ressource := 'facture',
    p_id_ressource := p_facture_id,
    p_details := jsonb_build_object('credit_eur', v_a_deduire, 'etablissement_id', v_etab_id)
  );

  RETURN jsonb_build_object('success', true, 'credit_applique_eur', v_a_deduire);
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_credits_disponibles_etab"("p_facture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_parrainage"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parrain RECORD;
  v_filleul_id UUID := auth.uid();
  v_nb_filleuls_valides INT;
  v_parrainage_id UUID;
  v_ip TEXT;
  v_user_agent TEXT;
  v_prime integer := (public.fn_param_num('prime_parrainage_eur', 50))::integer;
BEGIN
  IF v_filleul_id IS NULL THEN RETURN '{"error":"Non authentifié"}'::JSONB; END IF;
  SELECT * INTO v_parrain FROM soignants WHERE code_parrainage = UPPER(TRIM(p_code)) AND supprime_le IS NULL;
  IF v_parrain IS NULL THEN RETURN '{"error":"Code de parrainage invalide"}'::JSONB; END IF;
  IF v_parrain.id = v_filleul_id THEN RETURN '{"error":"Vous ne pouvez pas vous parrainer vous-même"}'::JSONB; END IF;
  SELECT COUNT(*) INTO v_nb_filleuls_valides FROM parrainages WHERE parrain_id = v_parrain.id AND statut IN ('VALIDE','FILLEUL_ACTIF','VALIDE_EN_ATTENTE_SEUIL','PRIME_VERSEE');
  IF v_nb_filleuls_valides >= 20 THEN RETURN '{"error":"Le parrain a atteint la limite de 20 filleuls validés"}'::JSONB; END IF;
  IF EXISTS (SELECT 1 FROM parrainages WHERE filleul_id = v_filleul_id) THEN RETURN '{"error":"Vous avez déjà appliqué un code de parrainage"}'::JSONB; END IF;
  INSERT INTO parrainages (parrain_id, filleul_id, code_parrainage, statut) VALUES (v_parrain.id, v_filleul_id, UPPER(TRIM(p_code)), 'EN_ATTENTE') RETURNING id INTO v_parrainage_id;
  UPDATE soignants SET parraine_par = v_parrain.id WHERE id = v_filleul_id AND parraine_par IS NULL;
  BEGIN
    v_ip := COALESCE(current_setting('request.headers', true)::json->>'x-forwarded-for', current_setting('request.headers', true)::json->>'x-real-ip', 'unknown');
    v_user_agent := COALESCE(current_setting('request.headers', true)::json->>'user-agent', 'unknown');
  EXCEPTION WHEN OTHERS THEN v_ip := 'unknown'; v_user_agent := 'unknown';
  END;
  IF v_ip <> 'unknown' THEN
    DECLARE v_parrain_last_ip TEXT;
    BEGIN
      SELECT (details->>'ip')::text INTO v_parrain_last_ip FROM journaux_audit WHERE acteur_id = v_parrain.id AND action = 'CONNEXION' ORDER BY cree_le DESC LIMIT 1;
      IF v_parrain_last_ip IS NOT NULL AND v_parrain_last_ip = v_ip THEN
        INSERT INTO parrainage_fraude_signals (parrainage_id, type, detail) VALUES (v_parrainage_id, 'MEME_IP', jsonb_build_object('ip', v_ip, 'parrain_id', v_parrain.id, 'filleul_id', v_filleul_id));
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;
  INSERT INTO parrainage_fraude_signals (parrainage_id, type, detail) VALUES (v_parrainage_id, 'MEME_DEVICE', jsonb_build_object('ip_filleul', v_ip, 'user_agent_filleul', v_user_agent, 'filleul_id', v_filleul_id, 'parrain_id', v_parrain.id));
  RETURN jsonb_build_object('success', true, 'message', 'Code accepté ! Votre prime de ' || v_prime || '€ sera versée après votre 1ère mission terminée et 100€ de commission encaissée par Jolene.');
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_parrainage"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_parrainage_etab"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_filleul_id UUID;
  v_parrain_etab RECORD;
  v_filleul_siret TEXT;
  v_existing UUID;
  v_nb_valides INT;
BEGIN
  v_filleul_id := mon_etablissement_id();
  IF v_filleul_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vous devez être connecté en tant qu''établissement');
  END IF;

  IF p_code IS NULL OR LENGTH(TRIM(p_code)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Code invalide');
  END IF;

  SELECT id, nom, siret INTO v_parrain_etab FROM etablissements
  WHERE code_parrainage = UPPER(TRIM(p_code));

  IF v_parrain_etab IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Code parrainage introuvable');
  END IF;

  IF v_parrain_etab.id = v_filleul_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vous ne pouvez pas vous parrainer vous-même');
  END IF;

  SELECT siret INTO v_filleul_siret FROM etablissements WHERE id = v_filleul_id;
  IF EXISTS (
    SELECT 1 FROM parrainages_etablissements pe
    JOIN etablissements ef ON ef.id = pe.filleul_etab_id
    WHERE ef.siret = v_filleul_siret AND pe.statut = 'VALIDATED'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cet établissement (SIRET) a déjà bénéficié d''un parrainage validé');
  END IF;

  SELECT id INTO v_existing FROM parrainages_etablissements WHERE filleul_etab_id = v_filleul_id;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vous avez déjà appliqué un code parrainage');
  END IF;

  SELECT COUNT(*) INTO v_nb_valides FROM parrainages_etablissements
  WHERE parrain_etab_id = v_parrain_etab.id AND statut = 'VALIDATED';
  IF v_nb_valides >= 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cet établissement parrain a atteint la limite de 10 parrainages validés');
  END IF;

  INSERT INTO parrainages_etablissements (parrain_etab_id, filleul_etab_id, code_parrainage, statut)
  VALUES (v_parrain_etab.id, v_filleul_id, UPPER(TRIM(p_code)), 'PENDING');

  UPDATE etablissements SET parraine_par_id = v_parrain_etab.id
  WHERE id = v_filleul_id AND parraine_par_id IS NULL;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_filleul_id,
    p_type_acteur := 'ADMIN_ETABLISSEMENT',
    p_action := 'PARRAINAGE_ETAB_APPLIQUE',
    p_type_ressource := 'etablissement',
    p_id_ressource := v_parrain_etab.id,
    p_details := jsonb_build_object('code_parrainage', UPPER(TRIM(p_code)), 'parrain_nom', v_parrain_etab.nom)
  );

  RETURN jsonb_build_object(
    'success', true,
    'parrain_nom', v_parrain_etab.nom,
    'message', 'Code parrainage appliqué. Vous et votre parrain recevrez des crédits commission au fil des missions : 50€ chacun dès 500€ de missions réalisées, puis 150€ chacun à 2 000€.'
  );
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_parrainage_etab"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_remise_groupe"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_groupe RECORD;
    v_nb_updated INTEGER := 0;
    v_total INTEGER := 0;
BEGIN
    IF NOT est_admin() THEN RETURN jsonb_build_object('error', 'Non autorisé'); END IF;

    FOR v_groupe IN 
        SELECT g.id, g.nom, g.remise_groupe_pourcent
        FROM groupes_sante g
        WHERE g.supprime_le IS NULL
          AND g.remise_groupe_pourcent IS NOT NULL
          AND g.remise_groupe_pourcent > 0
    LOOP
        -- Appliquer: le taux effectif = taux palier - remise groupe
        -- (sans descendre en dessous de 5%)
        UPDATE etablissements SET
            taux_commission_negocie = GREATEST(5.00, 
                COALESCE(
                    (SELECT pc.taux_commission FROM paliers_commission pc WHERE pc.id = palier_commission_id),
                    15.00
                ) - v_groupe.remise_groupe_pourcent
            ),
            modifie_le = NOW()
        WHERE groupe_sante_id = v_groupe.id
          AND supprime_le IS NULL;
          
        GET DIAGNOSTICS v_nb_updated = ROW_COUNT;
        v_total := v_total + v_nb_updated;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'etablissements_mis_a_jour', v_total);
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_remise_groupe"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_verification_contrat_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_contrat_url" "text", "p_nom_etablissement" "text", "p_siret" "text", "p_siret_raison_sociale" "text", "p_finess_raison_sociale" "text", "p_representant_nom" "text", "p_representant_prenom" "text", "p_coherent" boolean, "p_resultat" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_etab record;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT verification_source_version, contrat_url, nom, siret,
         siret_raison_sociale, finess_raison_sociale,
         representant_nom, representant_prenom
    INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND
     OR v_etab.verification_source_version IS DISTINCT FROM p_version_attendue
     OR v_etab.contrat_url IS DISTINCT FROM p_contrat_url
     OR v_etab.nom IS DISTINCT FROM p_nom_etablissement
     OR v_etab.siret IS DISTINCT FROM p_siret
     OR v_etab.siret_raison_sociale IS DISTINCT FROM p_siret_raison_sociale
     OR v_etab.finess_raison_sociale IS DISTINCT FROM p_finess_raison_sociale
     OR v_etab.representant_nom IS DISTINCT FROM p_representant_nom
     OR v_etab.representant_prenom IS DISTINCT FROM p_representant_prenom THEN
    RETURN false;
  END IF;

  UPDATE public.etablissements
  SET contrat_ia_resultat = COALESCE(p_resultat, '{}'::jsonb),
      contrat_ia_coherent = p_coherent,
      contrat_ia_verifie_le = now(),
      modifie_le = now()
  WHERE id = p_etablissement_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_verification_contrat_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_contrat_url" "text", "p_nom_etablissement" "text", "p_siret" "text", "p_siret_raison_sociale" "text", "p_finess_raison_sociale" "text", "p_representant_nom" "text", "p_representant_prenom" "text", "p_coherent" boolean, "p_resultat" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_verification_finess_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_finess_source_attendu" "text", "p_finess_nouveau" "text", "p_trouve" boolean, "p_verifie" boolean, "p_raison_sociale" "text", "p_categorie" "text", "p_secteur" "text", "p_est_public" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_etab record;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT verification_source_version, finess
    INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND
     OR v_etab.verification_source_version IS DISTINCT FROM p_version_attendue
     OR v_etab.finess IS DISTINCT FROM p_finess_source_attendu THEN
    RETURN false;
  END IF;

  -- Le changement de numéro doit d'abord passer seul afin que le trigger
  -- d'invalidation révoque l'ancien verdict. Le verrou de ligne conserve
  -- néanmoins les deux écritures dans une seule transaction atomique.
  IF v_etab.finess IS DISTINCT FROM p_finess_nouveau THEN
    UPDATE public.etablissements
    SET finess = p_finess_nouveau,
        modifie_le = now()
    WHERE id = p_etablissement_id;
  END IF;

  UPDATE public.etablissements
  SET finess_verifie = COALESCE(p_verifie, false),
      finess_verifie_le = CASE WHEN p_verifie IS TRUE THEN now() ELSE NULL END,
      finess_raison_sociale = CASE WHEN p_trouve IS TRUE THEN p_raison_sociale ELSE NULL END,
      finess_categorie = CASE WHEN p_trouve IS TRUE THEN p_categorie ELSE NULL END,
      finess_secteur = CASE WHEN p_trouve IS TRUE THEN p_secteur ELSE NULL END,
      finess_est_public = CASE WHEN p_trouve IS TRUE THEN p_est_public ELSE NULL END,
      modifie_le = now()
  WHERE id = p_etablissement_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_verification_finess_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_finess_source_attendu" "text", "p_finess_nouveau" "text", "p_trouve" boolean, "p_verifie" boolean, "p_raison_sociale" "text", "p_categorie" "text", "p_secteur" "text", "p_est_public" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_verification_fonction_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_justificatif_s3_key" "text", "p_justificatif_type" "text", "p_justificatif_type_mime" "text", "p_representant_nom" "text", "p_representant_prenom" "text", "p_nom_etablissement" "text", "p_siret" "text", "p_siret_raison_sociale" "text", "p_finess_raison_sociale" "text", "p_verifie" boolean, "p_resultat" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_etab record;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT verification_source_version, justificatif_fonction_s3_key,
         justificatif_fonction_type, justificatif_fonction_type_mime,
         representant_nom, representant_prenom, nom, siret,
         siret_raison_sociale, finess_raison_sociale
    INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND
     OR v_etab.verification_source_version IS DISTINCT FROM p_version_attendue
     OR v_etab.justificatif_fonction_s3_key IS DISTINCT FROM p_justificatif_s3_key
     OR v_etab.justificatif_fonction_type IS DISTINCT FROM p_justificatif_type
     OR v_etab.justificatif_fonction_type_mime IS DISTINCT FROM p_justificatif_type_mime
     OR v_etab.representant_nom IS DISTINCT FROM p_representant_nom
     OR v_etab.representant_prenom IS DISTINCT FROM p_representant_prenom
     OR v_etab.nom IS DISTINCT FROM p_nom_etablissement
     OR v_etab.siret IS DISTINCT FROM p_siret
     OR v_etab.siret_raison_sociale IS DISTINCT FROM p_siret_raison_sociale
     OR v_etab.finess_raison_sociale IS DISTINCT FROM p_finess_raison_sociale THEN
    RETURN false;
  END IF;

  UPDATE public.etablissements
  SET justificatif_fonction_verifie = COALESCE(p_verifie, false),
      justificatif_fonction_verifie_le = CASE WHEN p_verifie IS TRUE THEN now() ELSE NULL END,
      justificatif_fonction_resultat_ia = COALESCE(p_resultat, '{}'::jsonb),
      modifie_le = now()
  WHERE id = p_etablissement_id;
  RETURN true;
END;
$$;


