CREATE OR REPLACE FUNCTION "public"."fn_appliquer_verification_rib_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_rib_s3_key" "text", "p_nom_etablissement" "text", "p_siret_raison_sociale" "text", "p_finess_raison_sociale" "text", "p_coherent" boolean, "p_resultat" "jsonb", "p_iban_last4" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_etab public.etablissements%ROWTYPE;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND
     OR v_etab.verification_source_version IS DISTINCT FROM p_version_attendue
     OR v_etab.rib_s3_key IS DISTINCT FROM p_rib_s3_key
     OR v_etab.nom IS DISTINCT FROM p_nom_etablissement
     OR v_etab.siret_raison_sociale IS DISTINCT FROM p_siret_raison_sociale
     OR v_etab.finess_raison_sociale IS DISTINCT FROM p_finess_raison_sociale THEN
    RETURN false;
  END IF;

  UPDATE public.etablissements
  SET rib_ia_resultat = COALESCE(p_resultat, '{}'::jsonb),
      rib_ia_coherent = p_coherent,
      rib_ia_verifie_le = now(),
      iban_last4 = CASE
        WHEN p_coherent IS TRUE AND upper(COALESCE(p_iban_last4, '')) ~ '^[A-Z0-9]{4}$'
          THEN upper(p_iban_last4)
        ELSE NULL
      END,
      rib_verifie_s3_key = CASE WHEN p_coherent IS TRUE THEN p_rib_s3_key ELSE NULL END,
      -- trg_00_versionner_verifications_etablissement incrémente la version
      -- globale pendant cet UPDATE. On journalise la version effectivement
      -- écrite ; les mises à jour sans changement de RIB ne révoquent pas la
      -- provenance bancaire.
      rib_verifie_source_version = CASE WHEN p_coherent IS TRUE THEN p_version_attendue + 1 ELSE NULL END,
      modifie_le = now()
  WHERE id = p_etablissement_id;
  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."fn_appliquer_verification_rib_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_rib_s3_key" "text", "p_nom_etablissement" "text", "p_siret_raison_sociale" "text", "p_finess_raison_sociale" "text", "p_coherent" boolean, "p_resultat" "jsonb", "p_iban_last4" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_verification_siret_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_siret" "text", "p_verifie" boolean, "p_est_actif" boolean, "p_code_naf" "text", "p_raison_sociale" "text", "p_categorie_juridique" "text", "p_dirigeants" "jsonb", "p_est_secteur_public" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_etab record;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT verification_source_version, siret
    INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND
     OR v_etab.verification_source_version IS DISTINCT FROM p_version_attendue
     OR v_etab.siret IS DISTINCT FROM p_siret THEN
    RETURN false;
  END IF;

  UPDATE public.etablissements
  SET siret_verifie = COALESCE(p_verifie, false),
      siret_verifie_le = CASE WHEN p_verifie IS TRUE THEN now() ELSE NULL END,
      siret_est_actif = p_est_actif,
      siret_code_naf = p_code_naf,
      siret_raison_sociale = p_raison_sociale,
      siret_categorie_juridique = p_categorie_juridique,
      dirigeants = p_dirigeants,
      est_secteur_public = COALESCE(p_est_secteur_public, false),
      modifie_le = now()
  WHERE id = p_etablissement_id;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_appliquer_verification_siret_etablissement"("p_etablissement_id" "uuid", "p_version_attendue" bigint, "p_siret" "text", "p_verifie" boolean, "p_est_actif" boolean, "p_code_naf" "text", "p_raison_sociale" "text", "p_categorie_juridique" "text", "p_dirigeants" "jsonb", "p_est_secteur_public" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_appliquer_verification_siret_soignant"("p_soignant_id" "uuid", "p_expected_prenom" "text", "p_expected_nom" "text", "p_expected_date_naissance" "date", "p_expected_siret_liberal" "text", "p_expected_statut_liberal" "text", "p_expected_type_contrat" "text", "p_siret" "text", "p_raison_sociale" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_soignant record;
BEGIN
  IF COALESCE(
       auth.jwt() ->> 'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  IF p_soignant_id IS NULL
     OR NULLIF(btrim(p_expected_prenom), '') IS NULL
     OR NULLIF(btrim(p_expected_nom), '') IS NULL
     OR p_expected_date_naissance IS NULL
     OR COALESCE(p_siret, '') !~ '^[0-9]{14}$'
     OR p_siret ~ '^0+$' THEN
    RAISE EXCEPTION 'Snapshot SIRET ou identite incomplet'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    s.prenom,
    s.nom,
    s.date_naissance,
    s.siret_liberal,
    s.statut_liberal,
    s.type_contrat::text AS type_contrat
  INTO v_soignant
  FROM public.soignants s
  WHERE s.id = p_soignant_id
    AND s.supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND
     OR v_soignant.prenom IS DISTINCT FROM p_expected_prenom
     OR v_soignant.nom IS DISTINCT FROM p_expected_nom
     OR v_soignant.date_naissance IS DISTINCT FROM p_expected_date_naissance
     OR v_soignant.siret_liberal IS DISTINCT FROM p_expected_siret_liberal
     OR v_soignant.statut_liberal IS DISTINCT FROM p_expected_statut_liberal
     OR v_soignant.type_contrat IS DISTINCT FROM p_expected_type_contrat THEN
    RETURN false;
  END IF;

  IF (v_soignant.statut_liberal = 'ACTIF' OR v_soignant.type_contrat = 'LIBERAL')
     AND v_soignant.siret_liberal IS NOT NULL
     AND v_soignant.siret_liberal IS DISTINCT FROM p_siret THEN
    RETURN false;
  END IF;

  UPDATE public.soignants
  SET siret_liberal = p_siret,
      statut_liberal = CASE
        WHEN v_soignant.statut_liberal = 'ACTIF' THEN 'ACTIF'
        ELSE 'EN_COURS'
      END,
      siret_liberal_verifie = true,
      siret_liberal_verifie_le = now(),
      siret_liberal_raison_sociale = NULLIF(btrim(p_raison_sociale), ''),
      siret_liberal_coherence_identite = true,
      siret_liberal_source_verification = 'REGISTRE_OFFICIEL',
      siret_liberal_preuve_siret = NULL,
      siret_liberal_preuve_identite_document_id = NULL,
      siret_liberal_preuve_identite_document_modifie_le = NULL,
      siret_liberal_preuve_identite_s3_bucket = NULL,
      siret_liberal_preuve_identite_s3_cle = NULL,
      siret_liberal_preuve_identite_s3_version_id = NULL,
      siret_liberal_preuve_identite_storage_object_id = NULL,
      siret_liberal_preuve_identite_storage_updated_at = NULL,
      siret_liberal_preuve_identite_valide_jusqua = NULL,
      siret_liberal_preuve_identite_empreinte_sha256 = NULL,
      modifie_le = now()
  WHERE id = p_soignant_id;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."fn_appliquer_verification_siret_soignant"("p_soignant_id" "uuid", "p_expected_prenom" "text", "p_expected_nom" "text", "p_expected_date_naissance" "date", "p_expected_siret_liberal" "text", "p_expected_statut_liberal" "text", "p_expected_type_contrat" "text", "p_siret" "text", "p_raison_sociale" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_archiver_conversations_anciennes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_archivees int;
BEGIN
  WITH upd AS (
    UPDATE conversations c
    SET archived_at = NOW()
    FROM missions m
    WHERE c.mission_id = m.id
      AND c.archived_at IS NULL
      AND m.statut IN ('TERMINEE', 'ANNULEE_PAR_ETABLISSEMENT', 'ANNULEE_PAR_SOIGNANT', 'EXPIREE')
      AND COALESCE(m.fin_le, m.cree_le) < NOW() - INTERVAL '30 days'
    RETURNING c.id
  )
  SELECT count(*) INTO v_archivees FROM upd;

  IF v_archivees > 0 THEN
    INSERT INTO public.journaux_audit(acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES ('00000000-0000-0000-0000-000000000000', 'SYSTEME', 'SYSTEM', 'conversations', NULL,
            jsonb_build_object(
              'evenement', 'MESSAGERIE_ARCHIVAGE_AUTO',
              'nombre_archivees', v_archivees,
              'date_iso', NOW()::text
            ));
  END IF;

  RETURN jsonb_build_object(
    'archivees', v_archivees,
    'execute_le', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."fn_archiver_conversations_anciennes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_archiver_conversations_anciennes"() IS 'Sprint 10-A v3 PR 4 : archive conversations dont mission terminee + 30j. Appelee par cron pg_cron quotidien 3h.';



CREATE OR REPLACE FUNCTION "public"."fn_arrondir_quart_heure"("p_ts" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT date_trunc('hour', p_ts) +
    INTERVAL '15 minutes' * ROUND(EXTRACT(MINUTE FROM p_ts) / 15.0);
$$;


