CREATE OR REPLACE FUNCTION "public"."fn_audit_connexion"("p_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_ip inet;
    v_user_agent text;
    v_headers jsonb;
BEGIN
    IF p_action NOT IN ('CONNEXION', 'DECONNEXION') THEN
        RETURN '{"error":"Action non autorisée"}'::JSONB;
    END IF;

    -- Capture automatique de l'IP et du User-Agent depuis les headers HTTP
    -- (PostgREST expose request.headers à PostgreSQL)
    BEGIN
        v_headers := current_setting('request.headers', true)::jsonb;
        -- X-Forwarded-For peut contenir une chaine "ip1, ip2, ip3" -> on prend la 1ere (client réel)
        v_ip := NULLIF(trim(split_part(coalesce(v_headers->>'x-forwarded-for', ''), ',', 1)), '')::inet;
        v_user_agent := NULLIF(v_headers->>'user-agent', '');
    EXCEPTION WHEN OTHERS THEN
        v_ip := NULL;
        v_user_agent := NULL;
    END;

    INSERT INTO journaux_audit (
        acteur_id, type_acteur, action, type_ressource, id_ressource,
        ip_acteur, navigateur_acteur, details
    )
    VALUES (
        COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::UUID),
        COALESCE(mon_role(), 'SOIGNANT'),
        p_action,
        'session',
        COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000'::UUID),
        v_ip,
        v_user_agent,
        jsonb_build_object(
            'horodatage', now(),
            'method', 'email_password'
        )
    );

    RETURN '{"success":true}'::JSONB;
EXCEPTION WHEN OTHERS THEN
    -- Silencieux — l'audit de connexion ne doit jamais bloquer l'utilisateur
    RETURN '{"success":false}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_audit_connexion"("p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_audit_rls_strict"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_total int;
  v_problemes jsonb;
  v_nb_sans_rls int;
  v_nb_sans_policy int;
BEGIN
  IF v_uid IS NULL OR NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  SELECT count(*) INTO v_total
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'r'
    AND c.relname NOT IN ('signature_rate_limit_ip', 'spatial_ref_sys');

  WITH sans_rls AS (
    SELECT c.relname AS t, 'RLS_DESACTIVEE' AS type
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity = false
      AND c.relname NOT IN ('signature_rate_limit_ip', 'spatial_ref_sys')
  ),
  sans_policy AS (
    SELECT c.relname AS t, 'RLS_ACTIVE_SANS_POLICY' AS type
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    LEFT JOIN pg_policy p ON p.polrelid = c.oid
    WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity = true
    GROUP BY c.relname HAVING COUNT(p.polname) = 0
  ),
  tous AS (SELECT * FROM sans_rls UNION ALL SELECT * FROM sans_policy)
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object('type', type, 'table', t) ORDER BY type, t), '[]'::jsonb),
    (SELECT count(*) FROM sans_rls),
    (SELECT count(*) FROM sans_policy)
  INTO v_problemes, v_nb_sans_rls, v_nb_sans_policy
  FROM tous;

  RETURN jsonb_build_object(
    'success', true,
    'verdict', CASE WHEN (v_nb_sans_rls + v_nb_sans_policy) = 0 THEN 'OK' ELSE 'KO' END,
    'total_tables', v_total,
    'tables_sans_rls', v_nb_sans_rls,
    'tables_sans_policy', v_nb_sans_policy,
    'problemes', v_problemes,
    'executed_at', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."fn_audit_rls_strict"() OWNER TO "postgres";


