CREATE OR REPLACE FUNCTION "public"."fn_charger_demo_investisseur"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etablissements integer;
  v_soignants integer;
  v_missions integer;
BEGIN
  IF NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Acces refuse');
  END IF;

  SELECT COUNT(*)::integer
    INTO v_etablissements
    FROM public.etablissements
   WHERE est_compte_test IS TRUE;

  SELECT COUNT(*)::integer
    INTO v_soignants
    FROM public.soignants
   WHERE est_compte_test IS TRUE;

  SELECT COUNT(*)::integer
    INTO v_missions
    FROM public.missions m
    LEFT JOIN public.etablissements e ON e.id = m.etablissement_id
    LEFT JOIN public.soignants s ON s.id = m.soignant_assigne_id
   WHERE COALESCE(e.est_compte_test, false)
      OR COALESCE(s.est_compte_test, false);

  RETURN jsonb_build_object(
    'success', true,
    'mode', 'PRESERVATION',
    'message', 'Donnees de demonstration existantes conservees',
    'etablissements', v_etablissements,
    'soignants', v_soignants,
    'missions', v_missions
  );
END;
$$;


ALTER FUNCTION "public"."fn_charger_demo_investisseur"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_crons_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_results jsonb := '[]'::jsonb; v_cron RECORD; v_dernier_run TIMESTAMPTZ;
  v_dernier_statut TEXT; v_dernier_msg TEXT; v_intervalle_attendu INTERVAL;
  v_retard BOOLEAN; v_alertes_emises INT := 0;
BEGIN
  IF NOT fn_est_contexte_cron_ou_admin() THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;
  FOR v_cron IN SELECT jobid, jobname, schedule FROM cron.job WHERE active = true LOOP
    SELECT end_time, status, return_message INTO v_dernier_run, v_dernier_statut, v_dernier_msg
    FROM cron.job_run_details WHERE jobid = v_cron.jobid ORDER BY end_time DESC LIMIT 1;
    v_intervalle_attendu := CASE
      WHEN v_cron.schedule LIKE '*/5%' THEN INTERVAL '15 minutes'
      WHEN v_cron.schedule LIKE '*/10%' THEN INTERVAL '30 minutes'
      WHEN v_cron.schedule LIKE '*/15%' THEN INTERVAL '45 minutes'
      WHEN v_cron.schedule LIKE '0 * * * *' THEN INTERVAL '90 minutes'
      WHEN v_cron.schedule LIKE '15 * * * *' THEN INTERVAL '90 minutes'
      WHEN v_cron.schedule LIKE '0 % * * *' THEN INTERVAL '26 hours'
      WHEN v_cron.schedule LIKE '0 % % * *' THEN INTERVAL '32 days'
      WHEN v_cron.schedule LIKE '0 % * * 0' THEN INTERVAL '8 days'
      ELSE INTERVAL '40 days' END;
    -- Un cron JAMAIS exécuté (v_dernier_run IS NULL) n'est « en retard » que s'il est
    -- assez fréquent pour avoir déjà dû tourner (intervalle <= 2 jours). Sinon (mensuel,
    -- annuel, hebdo) c'est normal qu'il n'ait pas encore tourné après sa création — on
    -- évite ainsi le bruit de faux positifs qui noyait les vraies alertes (auto-facturation
    -- mensuelle, recalcul paliers, calcul BFA annuel). Un échec réel reste capté par la
    -- branche 'failed' dès la première exécution.
    v_retard := (v_dernier_run IS NOT NULL AND v_dernier_run < NOW() - v_intervalle_attendu)
             OR (v_dernier_run IS NULL AND v_intervalle_attendu <= INTERVAL '2 days');
    IF v_dernier_statut = 'failed' THEN
      PERFORM fn_emettre_alerte_monitoring('CRON_FAILED', 'CRITICAL', v_cron.jobname,
        format('Cron "%s" a échoué : %s', v_cron.jobname, COALESCE(SUBSTRING(v_dernier_msg, 1, 200), '?')),
        jsonb_build_object('jobid', v_cron.jobid, 'schedule', v_cron.schedule, 'dernier_run', v_dernier_run));
      v_alertes_emises := v_alertes_emises + 1;
    ELSIF v_retard AND v_cron.jobname NOT IN ('calculer-bfa-annuel') THEN
      PERFORM fn_emettre_alerte_monitoring('CRON_RETARD', 'WARNING', v_cron.jobname,
        format('Cron "%s" en retard (dernier run : %s)', v_cron.jobname, COALESCE(v_dernier_run::text, 'jamais')),
        jsonb_build_object('jobid', v_cron.jobid, 'schedule', v_cron.schedule, 'dernier_run', v_dernier_run));
      v_alertes_emises := v_alertes_emises + 1;
    END IF;
    v_results := v_results || jsonb_build_object('jobid', v_cron.jobid, 'jobname', v_cron.jobname,
      'schedule', v_cron.schedule, 'dernier_run', v_dernier_run, 'dernier_statut', v_dernier_statut,
      'retard', v_retard, 'echec', v_dernier_statut = 'failed');
  END LOOP;
  RETURN jsonb_build_object('success', true, 'crons', v_results, 'alertes_emises', v_alertes_emises);
END;
$$;


ALTER FUNCTION "public"."fn_check_crons_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_rate_limit_ip_signature"("p_ip" "inet") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_count int; v_max constant int := 5;
BEGIN
  IF p_ip IS NULL THEN RETURN jsonb_build_object('allowed', true, 'reason', 'no_ip'); END IF;
  DELETE FROM public.signature_rate_limit_ip WHERE derniere_action < NOW() - INTERVAL '2 hours';
  SELECT COALESCE(SUM(nb_envois), 0) INTO v_count
  FROM public.signature_rate_limit_ip
  WHERE ip_signature = p_ip AND fenetre_debut > NOW() - INTERVAL '1 hour';
  IF v_count >= v_max THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'rate_limit_exceeded',
      'envois_courant', v_count, 'max', v_max);
  END IF;
  INSERT INTO public.signature_rate_limit_ip (ip_signature, fenetre_debut, nb_envois, derniere_action)
  VALUES (p_ip, date_trunc('hour', NOW()), 1, NOW())
  ON CONFLICT (ip_signature, fenetre_debut) DO UPDATE SET
    nb_envois = signature_rate_limit_ip.nb_envois + 1,
    derniere_action = NOW();
  RETURN jsonb_build_object('allowed', true, 'envois_courant', v_count + 1, 'max', v_max);
END; $$;


ALTER FUNCTION "public"."fn_check_rate_limit_ip_signature"("p_ip" "inet") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_check_stripe_webhook_health"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_total_24h INT; v_avec_erreur INT; v_non_traites_24h INT; v_taux_erreur NUMERIC;
BEGIN
  IF NOT fn_est_contexte_cron_ou_admin() THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;
  SELECT COUNT(*) INTO v_total_24h FROM stripe_webhook_events WHERE recu_le > NOW() - INTERVAL '24 hours';
  SELECT COUNT(*) INTO v_avec_erreur FROM stripe_webhook_events WHERE recu_le > NOW() - INTERVAL '24 hours' AND erreur IS NOT NULL;
  SELECT COUNT(*) INTO v_non_traites_24h FROM stripe_webhook_events WHERE recu_le > NOW() - INTERVAL '24 hours' AND traite_le IS NULL;
  v_taux_erreur := CASE WHEN v_total_24h > 0 THEN ROUND(v_avec_erreur * 100.0 / v_total_24h, 1) ELSE 0 END;
  IF v_total_24h > 0 AND v_taux_erreur > 5 THEN
    PERFORM fn_emettre_alerte_monitoring('WEBHOOK_ERROR_RATE', 'WARNING', 'stripe-webhook',
      format('Taux erreur webhook Stripe %s%% sur 24h (%s/%s)', v_taux_erreur, v_avec_erreur, v_total_24h),
      jsonb_build_object('total', v_total_24h, 'avec_erreur', v_avec_erreur, 'non_traites', v_non_traites_24h));
  END IF;
  RETURN jsonb_build_object('success', true, 'total_24h', v_total_24h, 'avec_erreur', v_avec_erreur, 'non_traites', v_non_traites_24h, 'taux_erreur_pct', v_taux_erreur);
END;
$$;


ALTER FUNCTION "public"."fn_check_stripe_webhook_health"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."parcours_liberal_soignants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "demarre_le" timestamp with time zone DEFAULT "now"(),
    "termine_le" timestamp with time zone,
    "parcours_kine" "text",
    "etapes" "jsonb" DEFAULT '{}'::"jsonb",
    "cree_le" timestamp with time zone DEFAULT "now"(),
    "mis_a_jour_le" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "parcours_liberal_soignants_parcours_kine_check" CHECK ((("parcours_kine" IS NULL) OR ("parcours_kine" = ANY (ARRAY['HEURES_2240'::"text", 'ZONE_SOUS_DOTEE'::"text"]))))
);


ALTER TABLE "public"."parcours_liberal_soignants" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_choisir_parcours_kine"("p_parcours" "text") RETURNS "public"."parcours_liberal_soignants"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_parcours public.parcours_liberal_soignants;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Non authentifié';
  END IF;
  IF p_parcours IS NOT NULL AND p_parcours NOT IN ('HEURES_2240', 'ZONE_SOUS_DOTEE') THEN
    RAISE EXCEPTION 'Parcours kiné invalide';
  END IF;

  PERFORM public.fn_get_or_create_parcours_liberal();

  UPDATE public.parcours_liberal_soignants
  SET parcours_kine = p_parcours
  WHERE soignant_id = auth.uid()
  RETURNING * INTO v_parcours;

  RETURN v_parcours;
END;
$$;


ALTER FUNCTION "public"."fn_choisir_parcours_kine"("p_parcours" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_classifier_canal"("p_utm_source" "text", "p_utm_medium" "text", "p_referrer" "text", "p_ref_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  s text := lower(coalesce(p_utm_source, ''));
  m text := lower(coalesce(p_utm_medium, ''));
  r text := lower(coalesce(p_referrer, ''));
BEGIN
  IF coalesce(p_ref_code, '') <> '' THEN RETURN 'PARRAINAGE'; END IF;
  IF m IN ('cpc','ppc','paid','paidsearch','paid-search','paid_search','ads','display','cpm','retargeting') THEN RETURN 'PAID'; END IF;
  IF m IN ('social','paid-social','paid_social','social-paid')
     OR s ~ '(facebook|instagram|linkedin|tiktok|twitter|youtube|snapchat|pinterest)'
     OR r ~ '(facebook|instagram|linkedin|tiktok|twitter|t\.co|youtube|snapchat|pinterest)' THEN RETURN 'SOCIAL'; END IF;
  IF m IN ('email','newsletter','mail') OR s = 'email' THEN RETURN 'EMAIL'; END IF;
  IF s <> '' OR m <> '' THEN RETURN 'CAMPAGNE'; END IF;
  IF r ~ '(google|bing|yahoo|duckduckgo|qwant|ecosia)' THEN RETURN 'SEO'; END IF;
  IF r <> '' THEN RETURN 'REFERRAL'; END IF;
  RETURN 'DIRECT';
END;
$$;


ALTER FUNCTION "public"."fn_classifier_canal"("p_utm_source" "text", "p_utm_medium" "text", "p_referrer" "text", "p_ref_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cleanup_missions_test"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_ids uuid[];
  r record;
BEGIN
  SELECT array_agg(m.id) INTO v_ids
  FROM missions m
  JOIN etablissements e ON e.id = m.etablissement_id
  WHERE e.est_compte_test
    AND m.statut = 'OUVERTE'
    AND m.cree_le < now() - interval '2 hours';

  IF v_ids IS NULL THEN RETURN 0; END IF;

  FOR r IN
    SELECT c.conrelid::regclass::text AS t, a.attname AS col
    FROM pg_constraint c
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
    WHERE c.confrelid = 'public.missions'::regclass AND c.contype = 'f'
  LOOP
    EXECUTE format('DELETE FROM %s WHERE %I = ANY($1)', r.t, r.col) USING v_ids;
  END LOOP;

  DELETE FROM missions WHERE id = ANY(v_ids);
  RETURN array_length(v_ids, 1);
END;
$_$;


ALTER FUNCTION "public"."fn_cleanup_missions_test"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cloturer_litige"("p_litige_id" "uuid", "p_resolution" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_litige record;
  v_qui text;
  v_uid uuid := auth.uid();
  v_etablissement_id uuid;
  v_est_admin boolean := false;
BEGIN
  -- Autoriser avant toute lecture du statut : un UUID tiers ne doit révéler
  -- ni l'existence du litige, ni le fait qu'il soit déjà clôturé.
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  v_etablissement_id := public.mon_etablissement_id();
  v_est_admin := public.est_admin();

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
     AND (
       l.soignant_id = v_uid
       OR (
         l.etablissement_id = v_etablissement_id
         AND public.fn_a_permission_etablissement(
           'contrats', l.etablissement_id
         ) IS TRUE
       )
       OR v_est_admin
     )
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Litige introuvable ou accès refusé');
  END IF;
  IF v_litige.statut NOT IN (
    'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS'
  ) THEN
    RETURN jsonb_build_object('error', 'Litige déjà résolu ou non modifiable.');
  END IF;
  IF v_litige.payload_modifications IS NOT NULL THEN
    RETURN jsonb_build_object(
      'error',
      'Un accord avec proposition doit être accepté via son payload exact'
    );
  END IF;

  IF v_uid = v_litige.soignant_id THEN
    v_qui := 'soignant';
    UPDATE public.litiges
       SET accord_soignant = true,
           accord_soignant_le = now()
     WHERE id = p_litige_id;
  ELSIF v_etablissement_id = v_litige.etablissement_id
        AND public.fn_a_permission_etablissement(
          'contrats', v_litige.etablissement_id
        ) IS TRUE THEN
    v_qui := 'etablissement';
    UPDATE public.litiges
       SET accord_etablissement = true,
           accord_etablissement_le = now()
     WHERE id = p_litige_id;
  ELSIF v_est_admin THEN
    UPDATE public.litiges
       SET statut = 'RESOLU_ADMIN',
           resolu_par = v_uid,
           resolution = COALESCE(
             p_resolution,
             'Clôturé par l''équipe Jolene'
           ),
           resolu_le = now()
     WHERE id = p_litige_id;
    RETURN jsonb_build_object('success', true, 'statut', 'RESOLU_ADMIN');
  ELSE
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
     AND (
       l.soignant_id = v_uid
       OR (
         l.etablissement_id = v_etablissement_id
         AND public.fn_a_permission_etablissement(
           'contrats', l.etablissement_id
         ) IS TRUE
       )
       OR v_est_admin
     );

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Litige introuvable ou accès refusé');
  END IF;

  IF v_litige.accord_soignant = true
     AND v_litige.accord_etablissement = true THEN
    UPDATE public.litiges
       SET statut = 'RESOLU_ACCORD_PARTIES',
           resolu_par = v_uid,
           resolution = COALESCE(p_resolution, 'Clôturé par accord mutuel'),
           resolu_le = now()
     WHERE id = p_litige_id;
    RETURN jsonb_build_object(
      'success', true,
      'statut', 'RESOLU_ACCORD_PARTIES',
      'resolution', 'accord_mutuel'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'accord_' || v_qui, true,
    'en_attente', CASE
      WHEN v_qui = 'soignant' THEN 'établissement'
      ELSE 'soignant'
    END
  );
END;
$$;


ALTER FUNCTION "public"."fn_cloturer_litige"("p_litige_id" "uuid", "p_resolution" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cloturer_litige_avec_payload"("p_litige_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etablissement_id uuid;
  v_litige record;
  v_role text;
  v_other_role text;
  v_exec_result jsonb;
  v_admin_ids uuid[];
  v_type text;
  v_modifications jsonb;
  v_arrivee timestamptz;
  v_depart timestamptz;
  v_montant numeric;
  v_compensation numeric;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Non authentifié'
    );
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Payload de proposition invalide'
    );
  END IF;

  -- Le JSONB lui-même est la version de la proposition : toute différence de
  -- valeur invalide l'accord opposé. Les champs de présentation ne sont jamais
  -- stockés et chaque type ne peut porter que les données qu'il exécute.
  v_type := p_payload->>'type';
  v_modifications := p_payload->'modifications';
  IF jsonb_typeof(p_payload->'type') IS DISTINCT FROM 'string'
     OR v_type NOT IN (
       'MODIFICATION_HORAIRES',
       'MODIFICATION_MONTANT',
       'ANNULATION_TOTALE',
       'COMPENSATION_PARTIELLE',
       'MIXTE',
       'ACCORD_SANS_MODIFICATION'
     )
     OR jsonb_typeof(v_modifications) IS DISTINCT FROM 'object'
     OR jsonb_typeof(p_payload->'justification') IS DISTINCT FROM 'string'
     OR btrim(p_payload->>'justification') = ''
     OR length(p_payload->>'justification') > 2000
     OR p_payload - ARRAY['type', 'modifications', 'justification']::text[]
       <> '{}'::jsonb THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Schéma de proposition invalide'
    );
  END IF;

  IF v_type = 'ACCORD_SANS_MODIFICATION' THEN
    IF v_modifications <> '{}'::jsonb THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Un accord sans modification doit avoir un objet modifications vide'
      );
    END IF;
  ELSIF v_type IN ('MODIFICATION_HORAIRES', 'MIXTE') THEN
    IF jsonb_typeof(v_modifications->'pointage_arrivee_le') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_modifications->'pointage_depart_le') IS DISTINCT FROM 'string'
       OR v_modifications
         - (CASE WHEN v_type = 'MIXTE'
             THEN ARRAY[
               'pointage_arrivee_le', 'pointage_depart_le',
               'montant_total_corrige'
             ]::text[]
             ELSE ARRAY['pointage_arrivee_le', 'pointage_depart_le']::text[]
           END)
         <> '{}'::jsonb THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Champs horaires invalides'
      );
    END IF;
    BEGIN
      v_arrivee := (v_modifications->>'pointage_arrivee_le')::timestamptz;
      v_depart := (v_modifications->>'pointage_depart_le')::timestamptz;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Format des horaires invalide'
      );
    END;
    IF v_depart <= v_arrivee OR v_depart - v_arrivee > interval '7 days' THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Plage horaire invalide'
      );
    END IF;
  END IF;

  IF v_type IN ('MODIFICATION_MONTANT', 'MIXTE') THEN
    IF jsonb_typeof(v_modifications->'montant_total_corrige') IS DISTINCT FROM 'number' THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Montant corrigé invalide'
      );
    END IF;
    v_montant := (v_modifications->>'montant_total_corrige')::numeric;
    IF v_montant <= 0 OR v_montant > 10000000 THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Montant corrigé hors limites'
      );
    END IF;
    IF v_type = 'MODIFICATION_MONTANT'
       AND v_modifications - ARRAY['montant_total_corrige']::text[]
         <> '{}'::jsonb THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Champs de montant invalides'
      );
    END IF;
  ELSIF v_type = 'COMPENSATION_PARTIELLE' THEN
    IF jsonb_typeof(v_modifications->'pourcentage_compensation') IS DISTINCT FROM 'number'
       OR v_modifications - ARRAY['pourcentage_compensation']::text[]
         <> '{}'::jsonb THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Compensation invalide'
      );
    END IF;
    v_compensation := (v_modifications->>'pourcentage_compensation')::numeric;
    IF v_compensation <= 0 OR v_compensation > 100 THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Compensation hors limites'
      );
    END IF;
  ELSIF v_type = 'ANNULATION_TOTALE' THEN
    IF jsonb_typeof(v_modifications->'motif_annulation') IS DISTINCT FROM 'string'
       OR btrim(v_modifications->>'motif_annulation') = ''
       OR v_modifications - ARRAY['motif_annulation']::text[] <> '{}'::jsonb THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Motif d''annulation invalide'
      );
    END IF;
  END IF;

  v_etablissement_id := public.mon_etablissement_id();

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
     AND (
       l.soignant_id = v_uid
       OR (
         l.etablissement_id = v_etablissement_id
         AND public.fn_a_permission_etablissement(
           'contrats', l.etablissement_id
         ) IS TRUE
       )
     )
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Litige introuvable ou accès refusé'
    );
  END IF;
  IF v_litige.statut NOT IN (
    'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS'
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Litige déjà résolu ou non modifiable'
    );
  END IF;

  IF v_litige.soignant_id = v_uid THEN
    v_role := 'soignant';
    v_other_role := 'etablissement';
  ELSE
    v_role := 'etablissement';
    v_other_role := 'soignant';
  END IF;

  IF p_payload IS DISTINCT FROM v_litige.payload_modifications THEN
    UPDATE public.litiges
       SET payload_modifications = p_payload,
           accord_soignant = (v_role = 'soignant'),
           accord_soignant_le = CASE
             WHEN v_role = 'soignant' THEN now() ELSE NULL
           END,
           accord_etablissement = (v_role = 'etablissement'),
           accord_etablissement_le = CASE
             WHEN v_role = 'etablissement' THEN now() ELSE NULL
           END
     WHERE id = p_litige_id;
  ELSIF v_role = 'soignant' THEN
    UPDATE public.litiges
       SET accord_soignant = true,
           accord_soignant_le = COALESCE(accord_soignant_le, now())
     WHERE id = p_litige_id;
  ELSE
    UPDATE public.litiges
       SET accord_etablissement = true,
           accord_etablissement_le = COALESCE(
             accord_etablissement_le, now()
           )
     WHERE id = p_litige_id;
  END IF;

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id;

  IF v_litige.statut = 'REVUE_ADMIN' THEN
    SELECT COALESCE(array_agg(admin_user_id), ARRAY[]::uuid[])
      INTO v_admin_ids
      FROM public.fn_list_admin_user_ids() AS admins(admin_user_id);

    IF cardinality(v_admin_ids) > 0 THEN
      INSERT INTO public.externalisation_actions (
        type_action, payload, source, source_id
      )
      SELECT
        'PUSH_NOTIF',
        jsonb_build_object(
          'destinataire_id', uid,
          'type_evenement', 'ALERTE_ADMIN',
          'titre', '⚖️ Accord financier à valider',
          'corps', 'Les parties ont accepté le même ajustement financier. Validation admin requise.',
          'lien', '/admin/litiges'
        ),
        'LITIGE_EXEC',
        p_litige_id
      FROM unnest(v_admin_ids) AS destinataires(uid);
    END IF;

    RETURN jsonb_build_object(
      'success', true,
      'statut', 'EN_ATTENTE_VALIDATION_ADMIN',
      'type', v_litige.payload_modifications->>'type',
      'payload_propose', v_litige.payload_modifications
    );
  END IF;

  IF v_litige.statut = 'RESOLU_ACCORD_PARTIES' THEN
    PERFORM set_config('jolene.litige_exec_ok', 'true', true);
    v_exec_result := public.fn_executer_modifications_litige(p_litige_id);
    RETURN jsonb_build_object(
      'success', true,
      'statut', 'RESOLU_ACCORD_PARTIES',
      'execution', v_exec_result
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'statut', 'EN_ATTENTE_ACCORD_AUTRE_PARTIE',
    'role_en_attente', v_other_role,
    'payload_propose', v_litige.payload_modifications
  );
END;
$$;


ALTER FUNCTION "public"."fn_cloturer_litige_avec_payload"("p_litige_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_codes_pointage_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
BEGIN
  SELECT id, code_arrivee, code_depart, etablissement_id
  INTO v_mission
  FROM missions WHERE id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;

  IF NOT est_admin() AND v_mission.etablissement_id != mon_etablissement_id() THEN
    RETURN jsonb_build_object('error', 'Accès interdit');
  END IF;

  IF v_mission.code_arrivee IS NULL THEN
    UPDATE missions SET
      code_arrivee = lpad(floor(random() * 1000000)::text, 6, '0'),
      code_depart = lpad(floor(random() * 1000000)::text, 6, '0')
    WHERE id = p_mission_id
    RETURNING code_arrivee, code_depart INTO v_mission.code_arrivee, v_mission.code_depart;
  END IF;

  RETURN jsonb_build_object(
    'code_arrivee', v_mission.code_arrivee,
    'code_depart', v_mission.code_depart
  );
END;
$$;


ALTER FUNCTION "public"."fn_codes_pointage_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_commission_info_etablissement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab RECORD;
    v_paliers JSONB;
    v_missions_mois INT;
    v_etab_id uuid;
BEGIN
    IF auth.uid() IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
      RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    v_etab_id := public.mon_etablissement_id();
    IF v_etab_id IS NULL
       OR public.fn_a_permission_etablissement(
         'lecture_paiement', v_etab_id
       ) IS NOT TRUE THEN
      RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    SELECT e.*, p.nom AS palier_nom FROM etablissements e
    LEFT JOIN paliers_commission p ON p.id = e.palier_commission_id
    INTO v_etab WHERE e.id = v_etab_id;

    IF v_etab IS NULL THEN RETURN jsonb_build_object('error', 'Établissement introuvable'); END IF;

    -- Missions du mois en cours
    SELECT COUNT(*) INTO v_missions_mois FROM missions
    WHERE etablissement_id = v_etab.id AND statut = 'TERMINEE'
    AND fin_le >= DATE_TRUNC('month', NOW()) AND fin_le < DATE_TRUNC('month', NOW()) + INTERVAL '1 month';

    -- Tous les paliers pour affichage
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'nom', nom, 'taux', taux_commission, 'missions_min', missions_min, 'missions_max', missions_max,
        'actuel', (v_etab.palier_commission_id = id)
    ) ORDER BY ordre), '[]'::JSONB) INTO v_paliers FROM paliers_commission WHERE est_actif = TRUE;

    RETURN jsonb_build_object(
        'taux_actuel', COALESCE(v_etab.taux_commission_negocie, 15),
        'palier_actuel', COALESCE(v_etab.palier_nom, 'Découverte'),
        'missions_mois_en_cours', v_missions_mois,
        'missions_mois_precedent', COALESCE(v_etab.missions_mois_precedent, 0),
        'palier_recalcule_le', v_etab.palier_recalcule_le,
        'paliers', v_paliers,
        'explication', 'Votre commission est recalculée le 1er de chaque mois en fonction du nombre de missions terminées le mois précédent. Plus vous utilisez Jolene, plus votre taux baisse.'
    );
END;
$$;


ALTER FUNCTION "public"."fn_commission_info_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_compte_auth_actif"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
  SELECT COALESCE(EXISTS (
    SELECT 1
    FROM auth.users u
    WHERE u.id = auth.uid()
      AND u.deleted_at IS NULL
      AND (u.banned_until IS NULL OR u.banned_until <= now())
      AND NOT EXISTS (
        SELECT 1 FROM public.soignants s
        WHERE s.id = u.id AND s.supprime_le IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.etablissements e
        WHERE e.id = u.id AND e.supprime_le IS NOT NULL
      )
  ), false);
$$;


ALTER FUNCTION "public"."fn_compte_auth_actif"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_compter_missions_sans_notation"("p_role" "text" DEFAULT 'auto'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_etab_id UUID;
  v_role TEXT;
  v_count INT := 0;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('count', 0); END IF;

  v_etab_id := mon_etablissement_id();
  v_role := CASE
    WHEN p_role = 'auto' THEN
      CASE WHEN v_etab_id IS NOT NULL THEN 'ETAB' ELSE 'SOIGNANT' END
    ELSE p_role
  END;

  IF v_role = 'ETAB' AND v_etab_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_count FROM missions m
    WHERE m.etablissement_id = v_etab_id AND m.statut = 'TERMINEE'
      AND m.soignant_assigne_id IS NOT NULL
      AND m.fin_le >= NOW() - INTERVAL '30 days'
      AND NOT EXISTS (SELECT 1 FROM notations_missions n WHERE n.mission_id = m.id AND n.sens = 'ETAB_VERS_SOIGNANT');
  ELSE
    SELECT COUNT(*) INTO v_count FROM missions m
    WHERE m.soignant_assigne_id = v_uid AND m.statut = 'TERMINEE'
      AND m.fin_le >= NOW() - INTERVAL '30 days'
      AND NOT EXISTS (SELECT 1 FROM notations_missions n WHERE n.mission_id = m.id AND n.sens = 'SOIGNANT_VERS_ETAB');
  END IF;

  RETURN jsonb_build_object('count', v_count, 'role', v_role);
END;
$$;


ALTER FUNCTION "public"."fn_compter_missions_sans_notation"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_compter_nouveaux_pour_filtre"("p_filtre_id" "uuid", "p_since" timestamp with time zone) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_filtre RECORD;
  v_count integer := 0;
  v_profession text;
  v_taux_min numeric;
  v_urgentes_only boolean;
BEGIN
  SELECT * INTO v_filtre FROM filtres_sauvegardes WHERE id = p_filtre_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  IF v_filtre.audience = 'SOIGNANT_RECHERCHE_MISSIONS' THEN
    v_profession := v_filtre.filtres->>'profession';
    v_taux_min := COALESCE((v_filtre.filtres->>'tauxMin')::numeric, 0);
    v_urgentes_only := COALESCE((v_filtre.filtres->>'urgentesOnly')::boolean, false);
    SELECT count(*) INTO v_count FROM missions m
    WHERE m.statut = 'OUVERTE'
      AND m.cree_le > p_since
      AND (v_profession IS NULL OR v_profession = '' OR m.profession_requise::text = v_profession)
      AND COALESCE(m.taux_horaire_base, 0) >= v_taux_min
      AND (NOT v_urgentes_only OR COALESCE(m.est_urgente, false) = true);
  ELSIF v_filtre.audience = 'ETAB_RECHERCHE_SOIGNANTS' THEN
    v_profession := v_filtre.filtres->>'profession';
    SELECT count(*) INTO v_count FROM soignants s
    WHERE s.cree_le > p_since
      AND COALESCE(s.tous_documents_valides, false) = true
      AND (v_profession IS NULL OR v_profession = '' OR s.profession::text = v_profession);
  END IF;

  RETURN COALESCE(v_count, 0);
END;
$$;


ALTER FUNCTION "public"."fn_compter_nouveaux_pour_filtre"("p_filtre_id" "uuid", "p_since" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_compteur_heures_soignant"("p_soignant_id" "uuid") RETURNS TABLE("heures_jolene" numeric, "heures_externes_validees" numeric, "heures_externes_en_attente" numeric, "heures_totales" numeric, "eligible_free_transition" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_compteur record;
BEGIN
  IF auth.uid() IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RAISE EXCEPTION 'Compte authentifie actif requis'
      USING ERRCODE = '42501';
  END IF;
  IF auth.uid() <> p_soignant_id AND NOT public.est_admin_valide() THEN
    RAISE EXCEPTION 'Acces non autorise' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_compteur
  FROM private.fn_heures_exercice_verifiees(p_soignant_id);

  RETURN QUERY SELECT
    v_compteur.heures_jolene,
    v_compteur.heures_externes_validees,
    v_compteur.heures_externes_en_attente,
    v_compteur.heures_totales,
    v_compteur.heures_jolene >= 3200;
END;
$$;


ALTER FUNCTION "public"."fn_compteur_heures_soignant"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_compteur_soignants_disponibles"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    SELECT COUNT(DISTINCT s.id) INTO v_count
    FROM soignants s
    WHERE s.supprime_le IS NULL
      AND s.derniere_activite_le > NOW() - INTERVAL '7 days'
      AND fn_documents_ok_pour_mission(s.id, 'TOUS')
      AND s.profession IN (
          SELECT DISTINCT profession_requise FROM missions
          WHERE etablissement_id = p_etablissement_id AND statut = 'OUVERTE'
      )
      AND NOT fn_est_exclu(s.id, p_etablissement_id);
    RETURN jsonb_build_object('disponibles', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_compteur_soignants_disponibles"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_confirmer_accord_partie"("p_litige_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etablissement_id uuid;
  v_litige record;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  v_etablissement_id := public.mon_etablissement_id();
  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
     AND (
       l.soignant_id = v_uid
       OR (
         l.etablissement_id = v_etablissement_id
         AND public.fn_a_permission_etablissement(
           'contrats', l.etablissement_id
         ) IS TRUE
       )
     )
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Litige introuvable ou accès refusé'
    );
  END IF;
  IF v_litige.payload_modifications IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'La proposition doit être acceptée via son payload exact'
    );
  END IF;

  RETURN public.fn_cloturer_litige(p_litige_id, NULL);
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_accord_partie"("p_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_confirmer_email_etab"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid;
  v_expire timestamptz;
  v_rattachement jsonb;
BEGIN
  IF p_token IS NULL OR length(p_token) < 32 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Token invalide');
  END IF;

  SELECT id, email_contact_token_expire_le
    INTO v_etab_id, v_expire
  FROM etablissements
  WHERE email_contact_token = p_token;

  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Token inconnu ou déjà utilisé');
  END IF;

  IF v_expire < now() THEN
    UPDATE etablissements SET email_contact_token = NULL, email_contact_token_expire_le = NULL
    WHERE id = v_etab_id;
    RETURN jsonb_build_object('success', false, 'error', 'Token expiré. Veuillez renvoyer un e-mail de confirmation.');
  END IF;

  UPDATE etablissements SET
    email_contact_verifie = true,
    email_contact_verifie_le = now(),
    email_contact_token = NULL,
    email_contact_token_expire_le = NULL
  WHERE id = v_etab_id;

  BEGIN
    SELECT fn_evaluer_rattachement_etablissement(v_etab_id) INTO v_rattachement;
  EXCEPTION WHEN OTHERS THEN
    v_rattachement := NULL;
  END;

  RETURN jsonb_build_object('success', true, 'etablissement_id', v_etab_id, 'rattachement', v_rattachement);
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_email_etab"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_confirmer_honoraires_retrocession"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_m RECORD; v_mandat boolean; v_facture boolean := false;
BEGIN
  SELECT * INTO v_m FROM missions WHERE id = p_mission_id AND soignant_assigne_id = auth.uid();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF v_m.montant_honoraires_bruts IS NULL THEN
    RETURN jsonb_build_object('error', 'Aucun relevé à confirmer.');
  END IF;
  IF v_m.honoraires_confirmes_le IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'Relevé déjà confirmé.');
  END IF;

  UPDATE missions SET honoraires_confirmes_le = NOW(), modifie_le = NOW() WHERE id = p_mission_id;

  SELECT COALESCE(mandat_facturation_signe, FALSE) INTO v_mandat FROM soignants WHERE id = auth.uid();
  IF v_mandat AND NOT EXISTS (SELECT 1 FROM factures_honoraires WHERE mission_id = p_mission_id) THEN
    PERFORM fn_generer_facture_honoraires_mission(p_mission_id);
    v_facture := true;
  END IF;

  INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (v_m.etablissement_id, 'SYSTEM', 'Relevé confirmé par le remplaçant ✓',
    'Le remplaçant a confirmé le relevé de "' || fn_html_escape(v_m.intitule) || '" — rétrocession de ' ||
    v_m.net_a_payer || ' € à régler par virement (à déclarer sur la mission).',
    '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT');

  RETURN jsonb_build_object('success', TRUE, 'facture_generee', v_facture);
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_honoraires_retrocession"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_confirmer_paiement_soignant"("p_paiement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_paiement public.paiements_soignant%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;

  SELECT * INTO v_paiement
  FROM public.paiements_soignant
  WHERE id = p_paiement_id
  FOR UPDATE;
  IF v_paiement.id IS NULL THEN
    RETURN jsonb_build_object('error', 'Paiement introuvable');
  END IF;
  IF v_paiement.soignant_id <> v_uid THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;
  IF v_paiement.confirme_par_soignant THEN
    RETURN jsonb_build_object('error', 'Paiement déjà confirmé');
  END IF;
  IF v_paiement.statut NOT IN ('DECLARE', 'EN_ATTENTE') THEN
    RETURN jsonb_build_object(
      'error',
      'Ce paiement ne peut plus être confirmé (statut: ' || v_paiement.statut || ')'
    );
  END IF;

  UPDATE public.paiements_soignant
  SET statut = 'CONFIRME',
      confirme_par_soignant = true,
      confirme_par_soignant_le = now(),
      modifie_le = now()
  WHERE id = p_paiement_id;

  IF v_paiement.facture_honoraire_id IS NOT NULL THEN
    UPDATE public.factures_honoraires
    SET statut = 'PAYEE',
        date_paiement = COALESCE(v_paiement.date_paiement, CURRENT_DATE),
        modifie_le = now()
    WHERE id = v_paiement.facture_honoraire_id
      AND statut IN ('EMISE', 'EN_RETARD');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'confirme_le', now(),
    'facture_honoraires_id', v_paiement.facture_honoraire_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_paiement_soignant"("p_paiement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_confirmer_presence_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_m RECORD;
BEGIN
  SELECT * INTO v_m FROM missions WHERE id = p_mission_id AND soignant_assigne_id = auth.uid();
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF v_m.statut NOT IN ('ASSIGNEE', 'EN_COURS') THEN
    RETURN jsonb_build_object('error', 'Cette mission n''est plus active.');
  END IF;
  UPDATE missions SET presence_confirmee_le = NOW(), modifie_le = NOW() WHERE id = p_mission_id;
  -- L'établissement est rassuré en temps réel
  INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (v_m.etablissement_id, 'SYSTEM', 'Présence confirmée ✓',
    'Le soignant a confirmé sa présence pour "' || fn_html_escape(v_m.intitule) || '" du ' ||
    TO_CHAR(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24:MI') || '.',
    '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT');
  RETURN jsonb_build_object('success', TRUE);
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_presence_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_confirmer_remboursement_avoir"("p_avoir_id" "uuid", "p_reference_virement" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_avoir RECORD;
  v_montant NUMERIC;
BEGIN
  IF v_user_id IS NULL OR NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Admin requis.');
  END IF;
  IF length(trim(COALESCE(p_reference_virement, ''))) < 4 THEN
    RETURN jsonb_build_object('error', 'Référence virement requise (min 4 caractères).');
  END IF;

  SELECT * INTO v_avoir FROM public.factures_honoraires WHERE id = p_avoir_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Avoir introuvable.');
  END IF;
  IF v_avoir.type_document <> 'AVOIR' THEN
    RETURN jsonb_build_object('error', 'Ce document n''est pas un avoir.');
  END IF;
  IF v_avoir.mode_remboursement <> 'VIREMENT_MANUEL' THEN
    RETURN jsonb_build_object('error', 'Mode de remboursement incompatible (attendu : VIREMENT_MANUEL).');
  END IF;
  IF v_avoir.date_remboursement IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'Remboursement déjà confirmé.');
  END IF;

  UPDATE public.factures_honoraires
     SET statut = 'REMBOURSE',
         date_remboursement = NOW(),
         reference_remboursement = trim(p_reference_virement)
   WHERE id = p_avoir_id;

  PERFORM public.fn_ecrire_audit(
    v_user_id, 'ADMIN', 'AVOIR_REMBOURSEMENT_CONFIRME',
    'facture_honoraire', p_avoir_id, NULL,
    jsonb_build_object(
      'numero_avoir', v_avoir.numero_facture,
      'montant_ht', v_avoir.montant_ht,
      'reference_virement', trim(p_reference_virement),
      'mode_remboursement', 'VIREMENT_MANUEL'
    ),
    NULL, NULL
  );

  -- Notifier le soignant (in-app + push + email), comme le chemin SWAN auto
  v_montant := COALESCE(v_avoir.montant_ttc, v_avoir.montant_ht, 0);
  IF v_avoir.soignant_id IS NOT NULL THEN
    PERFORM public.fn_litige_push_notification(
      v_avoir.soignant_id,
      'SOIGNANT',
      'REMBOURSEMENT_CONFIRME',
      'Remboursement effectué',
      'Le remboursement de ' || to_char(v_montant, 'FM999G999D00') || ' € (avoir ' ||
        COALESCE(v_avoir.numero_facture, '') || ') a été effectué par virement. Référence : ' ||
        trim(p_reference_virement) || '.',
      v_avoir.litige_id,
      jsonb_build_object(
        'montant', v_montant,
        'numero_avoir', v_avoir.numero_facture,
        'reference_virement', trim(p_reference_virement)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', TRUE,
    'avoir_id', p_avoir_id,
    'statut', 'REMBOURSE',
    'date_remboursement', NOW()
  );
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_remboursement_avoir"("p_avoir_id" "uuid", "p_reference_virement" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_confirmer_remboursement_avoir"("p_avoir_id" "uuid", "p_reference_virement" "text") IS 'Admin-only. Confirme le remboursement manuel d''un avoir (mode VIREMENT_MANUEL) après virement bancaire effectué.';



CREATE OR REPLACE FUNCTION "public"."fn_confirmer_virement_admin"("p_facture_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_facture RECORD;
BEGIN
  IF NOT est_admin() THEN
    RETURN json_build_object('error', 'Réservé aux administrateurs');
  END IF;

  SELECT id, statut INTO v_facture FROM factures WHERE id = p_facture_id;

  IF NOT FOUND THEN
    RETURN json_build_object('error', 'Facture introuvable');
  END IF;

  IF v_facture.statut != 'VIREMENT_DECLARE' THEN
    RETURN json_build_object('error', 'Cette facture n''est pas en attente de vérification de virement');
  END IF;

  UPDATE factures
     SET statut = 'PAYEE',
         date_paiement = now(),
         virement_confirme_le = now(),
         virement_confirme_par = auth.uid(),
         modifie_le = now()
   WHERE id = p_facture_id;

  RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_confirmer_virement_admin"("p_facture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_conflit_planning_soignant"("p_soignant_id" "uuid", "p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission RECORD;
  v_conflit RECORD;
  v_adjacent RECORD;
BEGIN
  SELECT debut_le, fin_le INTO v_mission FROM missions WHERE id = p_mission_id;
  IF v_mission.debut_le IS NULL THEN
    RETURN jsonb_build_object('conflit', false);
  END IF;

  SELECT m.intitule, m.debut_le, m.fin_le INTO v_conflit
  FROM missions m
  WHERE m.soignant_assigne_id = p_soignant_id
    AND m.statut IN ('ASSIGNEE', 'EN_COURS')
    AND m.debut_le < v_mission.fin_le
    AND m.fin_le > v_mission.debut_le
  LIMIT 1;

  IF v_conflit.intitule IS NOT NULL THEN
    RETURN jsonb_build_object(
      'conflit', true,
      'mission_conflit', v_conflit.intitule,
      'message', 'Tu es déjà confirmé(e) sur « ' || v_conflit.intitule || ' » du '
        || to_char(v_conflit.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM HH24hMI') || ' au '
        || to_char(v_conflit.fin_le AT TIME ZONE 'Europe/Paris', 'DD/MM HH24hMI')
        || ' — ce créneau chevauche cette mission.'
    );
  END IF;

  SELECT m.intitule INTO v_adjacent
  FROM missions m
  WHERE m.soignant_assigne_id = p_soignant_id
    AND m.statut IN ('ASSIGNEE', 'EN_COURS')
    AND (
      (m.fin_le <= v_mission.debut_le AND v_mission.debut_le - m.fin_le < interval '60 minutes')
      OR (v_mission.fin_le <= m.debut_le AND m.debut_le - v_mission.fin_le < interval '60 minutes')
    )
  LIMIT 1;

  IF v_adjacent.intitule IS NOT NULL THEN
    RETURN jsonb_build_object(
      'conflit', false,
      'warning', 'Attention : moins d''1 h de battement avec « ' || v_adjacent.intitule || ' ».'
    );
  END IF;

  RETURN jsonb_build_object('conflit', false);
END;
$$;


ALTER FUNCTION "public"."fn_conflit_planning_soignant"("p_soignant_id" "uuid", "p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_consentir_gps"("p_accepte" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE soignants SET
        consentement_gps = p_accepte,
        consentement_gps_le = NOW(),
        modifie_le = NOW()
    WHERE id = auth.uid();

    INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES (auth.uid(), 'SOIGNANT', 'DONNEES_PERSO_MODIFICATION', 'soignant', auth.uid(),
        jsonb_build_object('consentement_gps', p_accepte));

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_consentir_gps"("p_accepte" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_consulter_mon_iban"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_s public.soignants%ROWTYPE;
  v_verifie boolean := false;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;
  SELECT * INTO v_s FROM public.soignants
  WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('iban_renseigne', false, 'iban_verifie', false);
  END IF;
  v_verifie := v_s.iban_titulaire_coherent IS TRUE
    AND v_s.iban_verifie_le IS NOT NULL
    AND v_s.iban_empreinte_sha256 ~ '^[0-9a-f]{64}$'
    AND EXISTS (
      SELECT 1 FROM public.documents_soignants ds
      WHERE ds.id = v_s.iban_source_document_id
        AND ds.s3_cle = v_s.iban_source_s3_cle
        AND ds.soignant_id = v_s.id
        AND ds.type_document = 'RIB'
        AND ds.statut_verification = 'VERIFIE'
        AND ds.supprime_le IS NULL AND ds.revoque_le IS NULL
    )
    AND EXISTS (
      SELECT 1 FROM public.documents_soignants ds
      WHERE ds.id = v_s.iban_identite_document_id
        AND ds.soignant_id = v_s.id
        AND ds.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
        AND ds.statut_verification = 'VERIFIE'
        AND ds.supprime_le IS NULL AND ds.revoque_le IS NULL
    );
  RETURN jsonb_build_object(
    'iban_renseigne', NULLIF(v_s.iban_virement, '') IS NOT NULL,
    'iban_verifie', v_verifie,
    'verification_requise', NULLIF(v_s.iban_virement, '') IS NOT NULL AND NOT v_verifie,
    'iban_last4', v_s.iban_last4,
    'iban_titulaire', v_s.iban_titulaire
  );
END;
$_$;


ALTER FUNCTION "public"."fn_consulter_mon_iban"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_consulter_rib_soignant"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_partage public.partages_rib%ROWTYPE;
  v_doc public.documents_soignants%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  SELECT * INTO v_partage
  FROM public.partages_rib
  WHERE mission_id = p_mission_id
    AND (etablissement_id = public.mon_etablissement_id() OR public.est_admin())
    AND actif IS TRUE
    AND (expire_le IS NULL OR expire_le > now())
  ORDER BY partage_le DESC NULLS LAST, id DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND OR v_partage.document_rib_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PARTAGE_RIB_INACTIF',
      'error', 'Le partage de RIB vérifié n''est pas actif pour cette mission.'
    );
  END IF;

  SELECT * INTO v_doc
  FROM public.documents_soignants
  WHERE id = v_partage.document_rib_id
    AND soignant_id = v_partage.soignant_id
    AND type_document = 'RIB'
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL AND revoque_le IS NULL
    AND resultat_ia->>'verdict_serveur' = 'VERIFIE';
  IF NOT FOUND THEN
    UPDATE public.partages_rib SET actif = false, expire_le = now()
    WHERE id = v_partage.id;
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'RIB_REVOQUE',
      'error', 'Le RIB partagé n''est plus une preuve courante vérifiée.'
    );
  END IF;

  UPDATE public.partages_rib
  SET consulte_le = now(), consulte_par = auth.uid()
  WHERE id = v_partage.id;
  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := auth.uid(),
    p_type_acteur := 'ADMIN_ETABLISSEMENT',
    p_action := 'RIB_CONSULTE',
    p_type_ressource := 'document',
    p_id_ressource := v_doc.id,
    p_details := jsonb_build_object(
      'mission_id', p_mission_id,
      'soignant_id', v_partage.soignant_id
    )
  );
  RETURN jsonb_build_object(
    'success', true,
    'document_id', v_doc.id,
    'nom_fichier', v_doc.nom_fichier,
    's3_cle', v_doc.s3_cle,
    's3_bucket', v_doc.s3_bucket
  );
END;
$$;


ALTER FUNCTION "public"."fn_consulter_rib_soignant"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contacter_support"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_support uuid;
BEGIN
  IF v_me IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;

  SELECT u.id INTO v_support
  FROM auth.users u
  JOIN public.equipe_admin ea ON ea.user_id = u.id
  WHERE u.id <> v_me
    AND u.deleted_at IS NULL
    AND u.email_confirmed_at IS NOT NULL
    AND (u.banned_until IS NULL OR u.banned_until <= pg_catalog.now())
    AND u.raw_app_meta_data ->> 'role' = 'ADMIN_PLATEFORME'
    AND ea.actif IS TRUE
    AND ARRAY[
      'Dashboard',
      'Utilisateurs',
      'Missions',
      'Litiges & contrats',
      'Finances',
      'Messagerie',
      'Conformité & Technique',
      'Fondateur'
    ]::text[] <@ COALESCE(ea.acces_groupes, ARRAY[]::text[])
  ORDER BY (u.email = 'admin@jolene.app') DESC, u.created_at, u.id
  LIMIT 1;
  IF v_support IS NULL THEN
    RAISE EXCEPTION 'Support indisponible pour le moment.'
      USING ERRCODE = '55000';
  END IF;

  -- Délégation au chemin canonique : même verrou que les autres conversations
  -- sans mission et recherche des deux orientations historiques.
  RETURN public.fn_obtenir_conversation(v_support, NULL);
END;
$$;


ALTER FUNCTION "public"."fn_contacter_support"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contester_paiement_soignant"("p_paiement_id" "uuid", "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_paiement RECORD;
    v_litige_id UUID;
BEGIN
    SELECT * INTO v_paiement FROM paiements_soignant WHERE id = p_paiement_id;
    IF v_paiement IS NULL THEN RETURN '{"error":"Paiement introuvable"}'::JSONB; END IF;
    IF v_paiement.soignant_id != auth.uid() THEN RETURN '{"error":"Accès refusé"}'::JSONB; END IF;

    -- Marquer le paiement contesté
    UPDATE paiements_soignant SET
        conteste = TRUE,
        motif_contestation = p_motif,
        statut = 'CONTESTE',
        modifie_le = NOW()
    WHERE id = p_paiement_id;

    -- Créer automatiquement un litige
    INSERT INTO litiges (
        mission_id, soignant_id, etablissement_id, initie_par, motif,
        statut, paiement_soignant_id
    ) VALUES (
        v_paiement.mission_id,
        v_paiement.soignant_id,
        v_paiement.etablissement_id,
        'SOIGNANT',
        'Paiement contesté — ' || p_motif,
        'OUVERT',
        p_paiement_id
    ) RETURNING id INTO v_litige_id;

    -- Notifier l'établissement
    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (
        v_paiement.etablissement_id,
        'CONTESTATION_PAIEMENT',
        'Paiement contesté ⚠️',
        'Le soignant conteste un paiement. Motif : ' || p_motif,
        '/etablissement/facturation',
        'ETABLISSEMENT'
    );

    -- Notifier l'admin
    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    SELECT id, 'SYSTEM', 'Paiement contesté ⚠️',
        'Un soignant conteste un paiement. Motif : ' || p_motif,
        '/admin/facturation', 'ADMIN'
    FROM auth.users WHERE raw_app_meta_data->>'role' = 'ADMIN_PLATEFORME'
    LIMIT 1;

    RETURN jsonb_build_object('success', true, 'litige_id', v_litige_id);
END;
$$;


ALTER FUNCTION "public"."fn_contester_paiement_soignant"("p_paiement_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contester_presence"("p_presence_id" "uuid", "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid;
  v_presence RECORD;
  v_ip inet;
  v_user_agent text;
  v_headers jsonb;
BEGIN
  v_etab_id := mon_etablissement_id();
  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  IF p_motif IS NULL OR length(trim(p_motif)) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Le motif est obligatoire (3 caractères min.)');
  END IF;

  SELECT p.* INTO v_presence
  FROM presences p
  JOIN missions m ON m.id = p.mission_id
  WHERE p.id = p_presence_id
    AND m.etablissement_id = v_etab_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Présence introuvable');
  END IF;

  UPDATE presences
  SET motif_litige = trim(p_motif),
      modifie_le = now()
  WHERE id = p_presence_id;

  -- Audit RGPD (contestation d'un pointage = donnée CDD critique)
  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_ip := NULLIF(trim(split_part(coalesce(v_headers->>'x-forwarded-for', ''), ',', 1)), '')::inet;
    v_user_agent := NULLIF(v_headers->>'user-agent', '');
  EXCEPTION WHEN OTHERS THEN
    v_ip := NULL; v_user_agent := NULL;
  END;

  PERFORM fn_ecrire_audit(
    auth.uid(), 'ADMIN_ETABLISSEMENT', 'PRESENCE_CONTESTATION',
    'presence', p_presence_id, NULL,
    jsonb_build_object(
      'mission_id', v_presence.mission_id,
      'soignant_id', v_presence.soignant_id,
      'motif', LEFT(trim(p_motif), 500)
    ),
    v_ip, v_user_agent
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_contester_presence"("p_presence_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_contrat_storage_path"("p_contrat_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_cm RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT storage_path, hash_document, contenu_html_rendu_le,
         soignant_id, etablissement_id
  INTO v_cm
  FROM public.contrats_mission WHERE id = p_contrat_id;

  IF v_cm IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contrat introuvable');
  END IF;

  IF NOT (est_admin()
          OR v_cm.soignant_id = v_uid
          OR v_cm.etablissement_id = mon_etablissement_id()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'storage_path', v_cm.storage_path,
    'hash_document', v_cm.hash_document,
    'rendu_le', v_cm.contenu_html_rendu_le
  );
END;
$$;


ALTER FUNCTION "public"."fn_contrat_storage_path"("p_contrat_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_conversation_accessible"("p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_conv public.conversations%ROWTYPE;
  v_autre uuid;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN false;
  END IF;
  IF public.est_admin() THEN
    RETURN EXISTS (
      SELECT 1 FROM public.conversations c WHERE c.id = p_conversation_id
    );
  END IF;

  SELECT c.* INTO v_conv
  FROM public.conversations c
  WHERE c.id = p_conversation_id;
  IF NOT FOUND THEN RETURN false; END IF;

  IF v_conv.etablissement_id IS NOT NULL
     AND v_conv.soignant_id IS NOT NULL THEN
    RETURN private.fn_relation_conversation_partagee(
      v_uid,
      p_conversation_id
    );
  END IF;

  IF v_uid = v_conv.participant_1_id THEN
    v_autre := v_conv.participant_2_id;
  ELSIF v_uid = v_conv.participant_2_id THEN
    v_autre := v_conv.participant_1_id;
  ELSE
    RETURN private.fn_membre_equipe_conversation(
      v_uid,
      p_conversation_id
    );
  END IF;

  RETURN private.fn_relation_messagerie_autorisee(
    v_uid,
    v_autre,
    v_conv.mission_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_conversation_accessible"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_coordonnees_bancaires_soignant_verifiees"("p_soignant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_s public.soignants%ROWTYPE;
  v_rib public.documents_soignants%ROWTYPE;
  v_identite public.documents_soignants%ROWTYPE;
  v_hash text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_s FROM public.soignants
  WHERE id = p_soignant_id AND supprime_le IS NULL;
  IF NOT FOUND
     OR NULLIF(v_s.iban_virement, '') IS NULL
     OR v_s.iban_titulaire_coherent IS NOT TRUE
     OR v_s.identite_verifiee IS NOT TRUE
     OR v_s.coherence_identite IS DISTINCT FROM 'COHERENT'
     OR NOT public.fn_iban_est_valide(v_s.iban_virement) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'RIB_VERIFIE_REQUIS');
  END IF;

  SELECT * INTO v_rib FROM public.documents_soignants
  WHERE id = v_s.iban_source_document_id
    AND soignant_id = v_s.id
    AND type_document = 'RIB'
    AND s3_cle = v_s.iban_source_s3_cle
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL AND revoque_le IS NULL;
  SELECT * INTO v_identite FROM public.documents_soignants
  WHERE id = v_s.iban_identite_document_id
    AND soignant_id = v_s.id
    AND type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL AND revoque_le IS NULL;
  IF v_rib.id IS NULL OR v_identite.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'PREUVE_REVOQUEE');
  END IF;

  v_hash := encode(extensions.digest(
    convert_to(v_s.iban_virement || ':' || v_rib.id::text, 'UTF8'), 'sha256'
  ), 'hex');
  IF v_hash IS DISTINCT FROM v_s.iban_empreinte_sha256
     OR v_hash IS DISTINCT FROM v_rib.resultat_ia->>'iban_preuve_hash_v1'
     OR right(v_s.iban_virement, 4) IS DISTINCT FROM v_rib.resultat_ia->>'iban_last4'
     OR v_rib.resultat_ia->>'verdict_serveur' IS DISTINCT FROM 'VERIFIE'
     OR v_rib.coherence_nom IS NOT TRUE
     OR v_identite.coherence_nom IS NOT TRUE
     OR NOT public.fn_noms_personne_correspondent(
       v_s.nom, v_s.prenom, v_rib.nom_extrait_ia, v_rib.prenom_extrait_ia
     )
     OR NOT public.fn_noms_personne_correspondent(
       v_s.nom, v_s.prenom, v_identite.nom_extrait_ia, v_identite.prenom_extrait_ia
     ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'RIB_NON_CONCORDANT');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'iban', v_s.iban_virement,
    'titulaire', v_s.iban_titulaire,
    'iban_last4', right(v_s.iban_virement, 4),
    'source_document_id', v_rib.id,
    'verifie_le', v_s.iban_verifie_le
  );
END;
$$;


ALTER FUNCTION "public"."fn_coordonnees_bancaires_soignant_verifiees"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_api_key"("p_nom" "text", "p_permissions" "text"[], "p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean := public.est_admin();
  v_etab_id uuid;
  v_cle_api text;
  v_cle_secret text;
  v_id uuid;
  v_allowed text[] := ARRAY['missions:read','missions:write','presences:read','factures:read'];
BEGIN
  IF v_actor IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('error', 'Non authentifie');
  END IF;

  IF v_is_admin THEN
    -- Une cle globale etablissement_id=NULL etait inutilisable mais surtout
    -- dangereuse en cas d'oubli d'un filtre multi-tenant.
    v_etab_id := p_etablissement_id;
    IF v_etab_id IS NULL THEN
      RETURN jsonb_build_object('error', 'Un etablissement est obligatoire pour chaque cle API');
    END IF;
  ELSE
    v_etab_id := public.mon_etablissement_id();
    IF v_etab_id IS NULL
       OR NOT public.fn_a_permission_etablissement('api', v_etab_id)
       OR (p_etablissement_id IS NOT NULL AND p_etablissement_id <> v_etab_id) THEN
      RETURN jsonb_build_object('error', 'Acces refuse');
    END IF;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id = v_etab_id AND e.supprime_le IS NULL) THEN
    RETURN jsonb_build_object('error', 'Etablissement introuvable');
  END IF;
  IF p_nom IS NULL OR length(trim(p_nom)) < 2 OR length(trim(p_nom)) > 100 THEN
    RETURN jsonb_build_object('error', 'Nom invalide (2 a 100 caracteres)');
  END IF;
  IF p_permissions IS NULL OR cardinality(p_permissions) = 0
     OR NOT (p_permissions <@ v_allowed) THEN
    RETURN jsonb_build_object('error', 'Permissions invalides');
  END IF;

  v_cle_api := 'sd_live_' || encode(extensions.gen_random_bytes(24), 'hex');
  v_cle_secret := encode(extensions.gen_random_bytes(32), 'hex');

  INSERT INTO public.api_keys (
    nom, cle_api, cle_secret, cle_secret_hash, permissions,
    etablissement_id, groupe_sante_id, actif
  ) VALUES (
    trim(p_nom), v_cle_api, NULL, public._sha256_hex(v_cle_secret),
    ARRAY(SELECT DISTINCT unnest(p_permissions)), v_etab_id, NULL, true
  ) RETURNING id INTO v_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_actor,
    p_type_acteur := CASE WHEN v_is_admin THEN 'ADMIN_PLATEFORME' ELSE 'ADMIN_ETABLISSEMENT' END,
    p_action := 'API_KEY_CREEE',
    p_type_ressource := 'api_key',
    p_id_ressource := v_id,
    p_details := jsonb_build_object('nom', trim(p_nom), 'permissions', p_permissions, 'etablissement_id', v_etab_id)
  );

  -- Le secret en clair n'est ni stocke ni relisible. C'est son unique affichage.
  RETURN jsonb_build_object('id', v_id, 'cle_api', v_cle_api, 'cle_secret', v_cle_secret);
END;
$$;


ALTER FUNCTION "public"."fn_creer_api_key"("p_nom" "text", "p_permissions" "text"[], "p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_bulletin_paie"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_mission record;
  v_cot record;
  v_bulletin_id uuid;
  v_numero text;
  v_existing uuid;
  v_regime text;
BEGIN
  SELECT m.id, m.soignant_assigne_id, m.etablissement_id, m.statut,
         m.debut_le, m.fin_le, m.duree_heures, m.taux_horaire_base,
         m.type_contrat_applique, m.type_paiement_soignant
    INTO v_mission
    FROM public.missions m
   WHERE m.id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable'); END IF;
  IF v_mission.soignant_assigne_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun soignant assigné');
  END IF;
  IF v_mission.statut <> 'TERMINEE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission non terminée');
  END IF;

  v_regime := COALESCE(
    v_mission.type_contrat_applique::text,
    CASE WHEN v_mission.type_paiement_soignant = 'NOTE_HONORAIRES' THEN 'LIBERAL' ELSE 'SALARIE' END
  );
  IF v_regime <> 'SALARIE' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Bulletin de paie non applicable : cette mission est libérale.'
    );
  END IF;

  SELECT id INTO v_existing
    FROM public.bulletins_paie WHERE mission_id = p_mission_id;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'bulletin_id', v_existing, 'already_existed', true);
  END IF;

  SELECT * INTO v_cot
    FROM public.cotisations_sociales WHERE mission_id = p_mission_id;
  IF NOT FOUND OR v_cot.type_contrat <> 'CDD' THEN
    PERFORM public.fn_calculer_cotisations(p_mission_id);
    SELECT * INTO v_cot
      FROM public.cotisations_sociales WHERE mission_id = p_mission_id;
  END IF;
  IF v_cot IS NULL OR v_cot.type_contrat <> 'CDD' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Calcul des cotisations salariées échoué');
  END IF;

  v_numero := public.fn_next_bulletin_paie_number(v_mission.soignant_assigne_id);
  INSERT INTO public.bulletins_paie(
    numero_bulletin, soignant_id, mission_id, etablissement_id,
    periode_debut, periode_fin, salaire_brut,
    total_cotisations_salariales, total_cotisations_patronales,
    net_avant_impot, ifm, icp, statut, date_emission
  ) VALUES (
    v_numero, v_mission.soignant_assigne_id, p_mission_id, v_mission.etablissement_id,
    v_mission.debut_le::date, v_mission.fin_le::date, v_cot.salaire_brut,
    v_cot.total_cotisations_salariales, v_cot.total_cotisations_patronales,
    v_cot.net_avant_impot, COALESCE(v_cot.ifm, 0), COALESCE(v_cot.icp, 0),
    'EMIS', current_date
  ) RETURNING id INTO v_bulletin_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_mission.soignant_assigne_id,
    p_type_acteur := 'SOIGNANT',
    p_action := 'BULLETIN_PAIE_EMIS',
    p_type_ressource := 'bulletin_paie',
    p_id_ressource := v_bulletin_id,
    p_details := jsonb_build_object(
      'numero_bulletin', v_numero,
      'mission_id', p_mission_id,
      'profession_requise', (
        SELECT profession_requise::text FROM public.missions WHERE id = p_mission_id
      ),
      'salaire_brut', v_cot.salaire_brut,
      'net_avant_impot', v_cot.net_avant_impot
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'bulletin_id', v_bulletin_id,
    'numero_bulletin', v_numero,
    'salaire_brut', v_cot.salaire_brut,
    'net_avant_impot', v_cot.net_avant_impot
  );
END;
$$;


ALTER FUNCTION "public"."fn_creer_bulletin_paie"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_conversation_si_absente"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_user_etab_id uuid;
  v_conv_id uuid;
  v_participant_1 uuid;
  v_participant_2 uuid;
  v_raison text;
  v_intitule text;
BEGIN
  IF p_mission_id IS NULL
     OR p_soignant_id IS NULL
     OR p_etablissement_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT mi.intitule
  INTO v_intitule
  FROM public.missions mi
  WHERE mi.id = p_mission_id
    AND mi.etablissement_id = p_etablissement_id
    AND mi.soignant_assigne_id = p_soignant_id;
  IF NOT FOUND THEN
    v_raison := 'relation_mission_invalide';
  ELSIF private.fn_soignant_messagerie_actif(p_soignant_id) IS NOT TRUE THEN
    v_raison := 'soignant_inactif';
  ELSE
    v_user_etab_id :=
      private.fn_interlocuteur_operationnel_id(p_etablissement_id);
    IF v_user_etab_id IS NULL THEN
      v_raison := 'interlocuteur_etablissement_introuvable';
    END IF;
  END IF;

  IF v_raison IS NOT NULL THEN
    BEGIN
      INSERT INTO public.journaux_audit (
        acteur_id,
        type_acteur,
        action,
        type_ressource,
        id_ressource,
        details
      ) VALUES (
        '00000000-0000-0000-0000-000000000000'::uuid,
        'SYSTEME',
        'SYSTEM',
        'conversations',
        NULL,
        pg_catalog.jsonb_build_object(
          'evenement', 'MESSAGERIE_CREATION_CONVERSATION_ECHEC',
          'raison', v_raison,
          'mission_id', p_mission_id,
          'soignant_id', p_soignant_id,
          'etablissement_id', p_etablissement_id
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
    RETURN NULL;
  END IF;

  v_participant_1 := LEAST(p_soignant_id, v_user_etab_id);
  v_participant_2 := GREATEST(p_soignant_id, v_user_etab_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_etablissement_id::text || ':' || p_soignant_id::text || ':' ||
      p_mission_id::text,
      0
    )
  );

  SELECT c.id
  INTO v_conv_id
  FROM public.conversations c
  WHERE c.mission_id = p_mission_id
    AND (
      (
        c.etablissement_id = p_etablissement_id
        AND c.soignant_id = p_soignant_id
      )
      OR (
        c.etablissement_id IS NULL
        AND c.soignant_id IS NULL
        AND c.participant_1_id = v_participant_1
        AND c.participant_2_id = v_participant_2
      )
    )
  ORDER BY
    CASE
      WHEN c.etablissement_id = p_etablissement_id
       AND c.soignant_id = p_soignant_id THEN 0
      ELSE 1
    END,
    c.cree_le,
    c.id
  LIMIT 1;

  IF v_conv_id IS NOT NULL THEN
    UPDATE public.conversations
    SET etablissement_id = p_etablissement_id,
        soignant_id = p_soignant_id
    WHERE id = v_conv_id
      AND etablissement_id IS NULL
      AND soignant_id IS NULL;
  END IF;

  IF v_conv_id IS NULL THEN
    INSERT INTO public.conversations (
      mission_id,
      participant_1_id,
      participant_2_id,
      etablissement_id,
      soignant_id,
      cree_le,
      dernier_message_le
    ) VALUES (
      p_mission_id,
      v_participant_1,
      v_participant_2,
      p_etablissement_id,
      p_soignant_id,
      pg_catalog.now(),
      pg_catalog.now()
    )
    RETURNING id INTO v_conv_id;

    INSERT INTO public.messages_chat (
      conversation_id,
      auteur_id,
      contenu,
      est_admin
    ) VALUES (
      v_conv_id,
      '00000000-0000-0000-0000-000000000000'::uuid,
      '📋 Mission "' || COALESCE(v_intitule, 'Mission') ||
        '" assignée. Vous pouvez échanger ici pour coordonner les détails.',
      true
    );

    BEGIN
      INSERT INTO public.journaux_audit (
        acteur_id,
        type_acteur,
        action,
        type_ressource,
        id_ressource,
        details
      ) VALUES (
        p_soignant_id,
        'SYSTEME',
        'SYSTEM',
        'conversations',
        v_conv_id,
        pg_catalog.jsonb_build_object(
          'evenement', 'MESSAGERIE_CONVERSATION_OUVERTE',
          'origine', 'ATTRIBUTION_MISSION',
          'mission_id', p_mission_id,
          'soignant_id', p_soignant_id,
          'etablissement_id', p_etablissement_id,
          'user_etab_id', v_user_etab_id
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN v_conv_id;
END;
$$;


ALTER FUNCTION "public"."fn_creer_conversation_si_absente"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_creer_conversation_si_absente"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid") IS 'Sprint 10-A v3 PR 1 : crée conversation soignant<->user_etab pour une mission si absente. Idempotent. SECURITY DEFINER. Echec silencieux + audit pour ne jamais bloquer l acceptation.';



CREATE OR REPLACE FUNCTION "public"."fn_creer_filtre_sauvegarde"("p_nom" "text", "p_audience" "public"."filtre_audience", "p_filtres" "jsonb", "p_alerte_active" boolean DEFAULT false, "p_frequence_alerte" "public"."filtre_frequence_alerte" DEFAULT 'QUOTIDIENNE'::"public"."filtre_frequence_alerte") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Non authentifié'); END IF;
  IF length(p_nom) = 0 OR length(p_nom) > 100 THEN
    RETURN jsonb_build_object('error','Nom invalide (1-100 caractères)');
  END IF;

  -- Limite : 20 filtres max par utilisateur
  SELECT count(*) INTO v_count FROM filtres_sauvegardes WHERE utilisateur_id = v_uid;
  IF v_count >= 20 THEN
    RETURN jsonb_build_object('error', 'Limite de 20 recherches sauvegardées atteinte. Supprimez-en une avant d''en créer une nouvelle.');
  END IF;

  INSERT INTO filtres_sauvegardes (utilisateur_id, nom, audience, filtres, alerte_active, frequence_alerte)
  VALUES (v_uid, p_nom, p_audience, COALESCE(p_filtres, '{}'::jsonb), p_alerte_active, p_frequence_alerte)
  RETURNING id INTO v_id;

  PERFORM fn_ecrire_audit_safe(
    p_acteur_id := v_uid, p_type_acteur := 'SOIGNANT',
    p_action := 'FILTRE_CREE', p_type_ressource := 'filtre_sauvegarde',
    p_id_ressource := v_id,
    p_details := jsonb_build_object('nom', p_nom, 'audience', p_audience::text, 'alerte_active', p_alerte_active, 'frequence', p_frequence_alerte::text)
  );

  IF p_alerte_active THEN
    PERFORM fn_ecrire_audit_safe(
      p_acteur_id := v_uid, p_type_acteur := 'SOIGNANT',
      p_action := 'ALERTE_ACTIVEE', p_type_ressource := 'filtre_sauvegarde',
      p_id_ressource := v_id,
      p_details := jsonb_build_object('frequence', p_frequence_alerte::text)
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'id', v_id);
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'Un filtre avec ce nom existe déjà');
END;
$$;


ALTER FUNCTION "public"."fn_creer_filtre_sauvegarde"("p_nom" "text", "p_audience" "public"."filtre_audience", "p_filtres" "jsonb", "p_alerte_active" boolean, "p_frequence_alerte" "public"."filtre_frequence_alerte") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_mission"("p_intitule" "text", "p_description" "text" DEFAULT NULL::"text", "p_profession_requise" "public"."type_profession" DEFAULT NULL::"public"."type_profession", "p_service" "text" DEFAULT NULL::"text", "p_debut_le" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_fin_le" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_taux_horaire_base" numeric DEFAULT NULL::numeric, "p_est_urgente" boolean DEFAULT false, "p_niveau_urgence" integer DEFAULT 0, "p_mode_attribution" "text" DEFAULT 'PREMIER_ARRIVE'::"text", "p_specialite_medicale_requise" "text" DEFAULT NULL::"text", "p_accepte_non_specialises" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID;
    v_blocage JSONB;
    v_mission_id UUID;
    v_mode TEXT;
BEGIN
    v_etab_id := mon_etablissement_id();
    IF v_etab_id IS NULL AND NOT est_admin() THEN
        RETURN '{"error":"Acces refuse"}'::JSONB;
    END IF;

    v_blocage := fn_blocage_publication_etab(v_etab_id);
    IF v_blocage IS NOT NULL THEN
        RETURN v_blocage;
    END IF;

    IF p_intitule IS NULL OR p_profession_requise IS NULL OR p_debut_le IS NULL OR p_fin_le IS NULL OR p_taux_horaire_base IS NULL THEN
        RETURN '{"error":"Champs obligatoires manquants."}'::JSONB;
    END IF;
    IF p_fin_le <= p_debut_le THEN
        RETURN '{"error":"La fin doit etre apres le debut."}'::JSONB;
    END IF;
    IF p_debut_le < NOW() AND NOT est_admin() THEN
        RETURN '{"error":"La mission ne peut pas commencer dans le passe."}'::JSONB;
    END IF;

    v_mode := COALESCE(p_mode_attribution, 'PREMIER_ARRIVE');
    IF v_mode NOT IN ('PREMIER_ARRIVE', 'CANDIDATURE') THEN
        v_mode := 'PREMIER_ARRIVE';
    END IF;

    PERFORM set_config('jolene.creer_mission_context', 'true', true);

    INSERT INTO missions (
        etablissement_id, intitule, description,
        profession_requise, service, debut_le, fin_le,
        taux_horaire_base, est_urgente, niveau_urgence, mode_attribution,
        specialite_medicale_requise, accepte_non_specialises
    ) VALUES (
        v_etab_id, p_intitule, p_description,
        p_profession_requise, p_service, p_debut_le, p_fin_le,
        p_taux_horaire_base, p_est_urgente,
        CASE WHEN p_est_urgente THEN p_niveau_urgence ELSE 0 END,
        v_mode,
        p_specialite_medicale_requise, p_accepte_non_specialises
    ) RETURNING id INTO v_mission_id;

    RETURN jsonb_build_object('success', true, 'mission_id', v_mission_id);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_creer_mission"("p_intitule" "text", "p_description" "text", "p_profession_requise" "public"."type_profession", "p_service" "text", "p_debut_le" timestamp with time zone, "p_fin_le" timestamp with time zone, "p_taux_horaire_base" numeric, "p_est_urgente" boolean, "p_niveau_urgence" integer, "p_mode_attribution" "text", "p_specialite_medicale_requise" "text", "p_accepte_non_specialises" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_mission_multi_jours"("p_intitule" "text", "p_description" "text" DEFAULT NULL::"text", "p_profession_requise" "public"."type_profession" DEFAULT NULL::"public"."type_profession", "p_service" "text" DEFAULT NULL::"text", "p_taux_horaire_base" numeric DEFAULT NULL::numeric, "p_est_urgente" boolean DEFAULT false, "p_niveau_urgence" integer DEFAULT 0, "p_mode_attribution" "text" DEFAULT 'PREMIER_ARRIVE'::"text", "p_specialite_medicale_requise" "text" DEFAULT NULL::"text", "p_accepte_non_specialises" boolean DEFAULT true, "p_creneaux" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid;
  v_blocage jsonb;
  v_mission_id uuid;
  v_mode text;
  v_nb int;
  v_min timestamptz;
  v_max timestamptz;
  v_c jsonb;
  v_ordre int := 0;
  v_cd timestamptz;
  v_cf timestamptz;
BEGIN
  v_etab_id := mon_etablissement_id();
  IF v_etab_id IS NULL AND NOT est_admin() THEN
    RETURN '{"error":"Acces refuse"}'::jsonb;
  END IF;

  v_blocage := fn_blocage_publication_etab(v_etab_id);
  IF v_blocage IS NOT NULL THEN RETURN v_blocage; END IF;

  IF p_intitule IS NULL OR p_profession_requise IS NULL OR p_taux_horaire_base IS NULL THEN
    RETURN '{"error":"Champs obligatoires manquants."}'::jsonb;
  END IF;

  v_nb := COALESCE(jsonb_array_length(p_creneaux), 0);
  IF v_nb = 0 THEN RETURN '{"error":"Aucun jour fourni."}'::jsonb; END IF;
  IF v_nb > 366 THEN RETURN '{"error":"Maximum 366 jours par mission."}'::jsonb; END IF;

  -- Validation de chaque jour (fin > début) + enveloppe globale
  FOR v_c IN SELECT * FROM jsonb_array_elements(p_creneaux) LOOP
    v_cd := (v_c->>'debut')::timestamptz;
    v_cf := (v_c->>'fin')::timestamptz;
    IF v_cd IS NULL OR v_cf IS NULL OR v_cf <= v_cd THEN
      RETURN '{"error":"Chaque jour doit avoir une fin après le début."}'::jsonb;
    END IF;
  END LOOP;

  SELECT MIN((c->>'debut')::timestamptz), MAX((c->>'fin')::timestamptz)
  INTO v_min, v_max
  FROM jsonb_array_elements(p_creneaux) c;

  IF v_min < NOW() AND NOT est_admin() THEN
    RETURN '{"error":"La mission ne peut pas commencer dans le passe."}'::jsonb;
  END IF;

  v_mode := COALESCE(p_mode_attribution, 'PREMIER_ARRIVE');
  IF v_mode NOT IN ('PREMIER_ARRIVE','CANDIDATURE') THEN v_mode := 'PREMIER_ARRIVE'; END IF;

  PERFORM set_config('jolene.creer_mission_context','true', true);

  -- (a) UNE mission, span = enveloppe (1er jour → dernier jour)
  INSERT INTO missions (
    etablissement_id, intitule, description, profession_requise, service,
    debut_le, fin_le, taux_horaire_base, est_urgente, niveau_urgence, mode_attribution,
    specialite_medicale_requise, accepte_non_specialises
  ) VALUES (
    v_etab_id, p_intitule, p_description, p_profession_requise, p_service,
    v_min, v_max, p_taux_horaire_base, p_est_urgente,
    CASE WHEN p_est_urgente THEN p_niveau_urgence ELSE 0 END, v_mode,
    p_specialite_medicale_requise, p_accepte_non_specialises
  ) RETURNING id INTO v_mission_id;

  -- (b) N créneaux PREVISIONNEL (sync suspendue → un seul re-sync ensuite, perf)
  PERFORM set_config('jolene.sync_in_progress','true', true);
  v_ordre := 0;
  FOR v_c IN SELECT * FROM jsonb_array_elements(p_creneaux) LOOP
    v_ordre := v_ordre + 1;
    INSERT INTO mission_creneaux (mission_id, debut, fin, est_pause, ordre, type_creneau)
    VALUES (v_mission_id, (v_c->>'debut')::timestamptz, (v_c->>'fin')::timestamptz, false, v_ordre, 'PREVISIONNEL');
  END LOOP;
  PERFORM set_config('jolene.sync_in_progress','false', true);

  -- (c) Re-sync unique : enveloppe + nb_creneaux ; le trigger financier recalcule
  --     duree_heures depuis les créneaux (somme des jours).
  UPDATE missions SET debut_le = v_min, fin_le = v_max, nb_creneaux = v_nb
  WHERE id = v_mission_id;

  RETURN jsonb_build_object('success', true, 'mission_id', v_mission_id, 'nb_creneaux', v_nb);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_creer_mission_multi_jours"("p_intitule" "text", "p_description" "text", "p_profession_requise" "public"."type_profession", "p_service" "text", "p_taux_horaire_base" numeric, "p_est_urgente" boolean, "p_niveau_urgence" integer, "p_mode_attribution" "text", "p_specialite_medicale_requise" "text", "p_accepte_non_specialises" boolean, "p_creneaux" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_notation_mission"("p_mission_id" "uuid", "p_sens" "text", "p_critere_1" integer, "p_critere_2" integer, "p_critere_3" integer, "p_critere_4" integer, "p_commentaire" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_etab_id UUID := mon_etablissement_id();
  v_mission RECORD;
  v_sens public.sens_notation;
  v_notateur_id UUID;
  v_note_id UUID;
  v_id UUID;
  v_tardive BOOLEAN := false;
  v_litige_actif_count INT;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  BEGIN v_sens := UPPER(TRIM(p_sens))::public.sens_notation;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Sens invalide');
  END;

  IF p_critere_1 NOT BETWEEN 1 AND 5 OR p_critere_2 NOT BETWEEN 1 AND 5
     OR p_critere_3 NOT BETWEEN 1 AND 5 OR p_critere_4 NOT BETWEEN 1 AND 5 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Critères doivent être entre 1 et 5');
  END IF;

  IF p_commentaire IS NOT NULL AND LENGTH(p_commentaire) > 2000 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Commentaire max 2000 caractères');
  END IF;

  SELECT id, etablissement_id, soignant_assigne_id, statut, fin_le INTO v_mission
  FROM missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable');
  END IF;

  -- 7b-C : TERMINEE, ou EN_COURS avec départ pointé (check-out fait, le cron
  -- de transition n'est simplement pas encore passé).
  IF v_mission.statut <> 'TERMINEE'
     AND NOT (v_mission.statut = 'EN_COURS' AND EXISTS (
       SELECT 1 FROM presences pr
       WHERE pr.mission_id = p_mission_id AND pr.pointage_depart_le IS NOT NULL
     ))
     AND NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seules les missions TERMINEE peuvent être notées');
  END IF;

  -- Itération 1 fix B.8 : bloquer notation pendant litige actif (médiation/arbitrage)
  IF NOT est_admin() THEN
    SELECT COUNT(*) INTO v_litige_actif_count FROM litiges
    WHERE mission_id = p_mission_id
      AND statut IN ('MEDIATION_EN_COURS', 'REVUE_ADMIN');
    IF v_litige_actif_count > 0 THEN
      RETURN jsonb_build_object('success', false,
        'error', 'Notation impossible pendant un litige en médiation ou en revue admin. Vous pourrez noter après résolution.');
    END IF;
  END IF;

  IF v_sens = 'ETAB_VERS_SOIGNANT' THEN
    IF NOT est_admin() AND v_mission.etablissement_id <> v_etab_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'Vous n''êtes pas l''établissement de cette mission');
    END IF;
    IF v_mission.soignant_assigne_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Mission sans soignant assigné');
    END IF;
    v_notateur_id := COALESCE(v_etab_id, v_mission.etablissement_id);
    v_note_id := v_mission.soignant_assigne_id;
  ELSE
    IF NOT est_admin() AND v_mission.soignant_assigne_id <> v_uid THEN
      RETURN jsonb_build_object('success', false, 'error', 'Vous n''êtes pas le soignant de cette mission');
    END IF;
    v_notateur_id := v_uid;
    v_note_id := v_mission.etablissement_id;
  END IF;

  IF v_mission.fin_le < NOW() - INTERVAL '30 days' THEN
    v_tardive := true;
  END IF;

  INSERT INTO notations_missions (
    mission_id, notateur_id, note_id, sens,
    critere_1, critere_2, critere_3, critere_4, commentaire
  ) VALUES (
    p_mission_id, v_notateur_id, v_note_id, v_sens,
    p_critere_1, p_critere_2, p_critere_3, p_critere_4, NULLIF(TRIM(p_commentaire), '')
  )
  ON CONFLICT (mission_id, sens) DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission déjà notée pour ce sens');
  END IF;

  -- D8 (Lot 15) : double-aveugle — l'INSERT part NON publié (publie_le NULL).
  -- Dès que les deux sens existent, publication SIMULTANÉE des deux notes
  -- (l'UPDATE déclenche le recalcul des scores via le trigger). Sinon le cron
  -- fn_publier_notations_echues publie à J+7.
  IF EXISTS (
    SELECT 1 FROM notations_missions
    WHERE mission_id = p_mission_id AND sens <> v_sens
  ) THEN
    UPDATE notations_missions SET publie_le = NOW()
    WHERE mission_id = p_mission_id AND publie_le IS NULL;
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_notateur_id,
    p_type_acteur := CASE WHEN v_sens = 'ETAB_VERS_SOIGNANT' THEN 'ADMIN_ETABLISSEMENT' ELSE 'SOIGNANT' END,
    p_action := 'NOTATION_DONNEE',
    p_type_ressource := 'mission',
    p_id_ressource := p_mission_id,
    p_details := jsonb_build_object('notation_id', v_id, 'sens', v_sens::text, 'note_id', v_note_id, 'tardive', v_tardive)
  );

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_note_id,
    p_type_acteur := CASE WHEN v_sens = 'ETAB_VERS_SOIGNANT' THEN 'SOIGNANT' ELSE 'ADMIN_ETABLISSEMENT' END,
    p_action := 'NOTATION_RECUE',
    p_type_ressource := 'mission',
    p_id_ressource := p_mission_id,
    p_details := jsonb_build_object('notation_id', v_id, 'sens', v_sens::text)
  );

  RETURN jsonb_build_object('success', true, 'id', v_id, 'tardive', v_tardive);
END;
$$;


ALTER FUNCTION "public"."fn_creer_notation_mission"("p_mission_id" "uuid", "p_sens" "text", "p_critere_1" integer, "p_critere_2" integer, "p_critere_3" integer, "p_critere_4" integer, "p_commentaire" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_notification"("p_destinataire_id" "uuid", "p_type_destinataire" "text", "p_type" "text", "p_titre" "text", "p_corps" "text", "p_lien" "text" DEFAULT NULL::"text", "p_type_ressource" "text" DEFAULT NULL::"text", "p_id_ressource" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_id uuid;
BEGIN
    -- Sécurité : appelant authentifié OU contexte cron/service/admin (auth.uid() IS NULL).
    -- anon n'a PAS le GRANT EXECUTE → ce garde ne bloque que des appelants de confiance.
    -- Avant ce fix, le strict « auth.uid() IS NULL → refus » cassait tous les crons
    -- (relance-candidatures-en-attente notamment) qui s'exécutent sans session.
    IF auth.uid() IS NULL AND NOT fn_est_contexte_cron_ou_admin() THEN
      RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
    END IF;

    INSERT INTO public.notifications (
        destinataire_id, type_destinataire, type,
        titre, corps, lien, type_ressource, id_ressource
    ) VALUES (
        p_destinataire_id, p_type_destinataire, p_type,
        p_titre, p_corps, p_lien, p_type_ressource, p_id_ressource
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."fn_creer_notification"("p_destinataire_id" "uuid", "p_type_destinataire" "text", "p_type" "text", "p_titre" "text", "p_corps" "text", "p_lien" "text", "p_type_ressource" "text", "p_id_ressource" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_reclamation_score"("p_evenement_id" "uuid", "p_evenement_type" "text", "p_motif_categorie" "text", "p_texte_libre" "text", "p_justificatif_storage_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_event RECORD;
  v_proprio_id uuid;
  v_reclamation_id uuid;
  v_existante RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  IF p_evenement_type NOT IN ('SOIGNANT', 'ETAB') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TYPE_INVALIDE',
                                'error', 'evenement_type doit être SOIGNANT ou ETAB');
  END IF;

  IF p_motif_categorie NOT IN ('URGENCE_MEDICALE','DEUIL','FORCE_MAJEURE',
                                'ERREUR_JOLENE','CONTEXTE_PARTICULIER','AUTRE') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MOTIF_INVALIDE',
                                'error', 'Motif catégorie invalide');
  END IF;

  IF p_texte_libre IS NULL OR length(trim(p_texte_libre)) < 20 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TEXTE_REQUIS',
                                'error', 'Texte libre obligatoire (min 20 caractères)');
  END IF;

  -- Charger l'événement + check propriété + contestable
  IF p_evenement_type = 'SOIGNANT' THEN
    SELECT id, soignant_id, contestable, decision_admin, reclamation_id
    INTO v_event FROM public.evenements_score_soignant WHERE id = p_evenement_id;
    v_proprio_id := v_event.soignant_id;
  ELSE
    SELECT id, etablissement_id AS proprio_id, contestable, decision_admin, reclamation_id
    INTO v_event FROM public.evenements_score_etab WHERE id = p_evenement_id;
    v_proprio_id := v_event.proprio_id;
  END IF;

  IF v_event.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'EVENT_INTROUVABLE',
                                'error', 'Événement de score introuvable');
  END IF;

  -- Auth : seul le propriétaire peut réclamer
  IF p_evenement_type = 'SOIGNANT' AND v_proprio_id != v_uid THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE',
                                'error', 'Vous n''êtes pas concerné par cet événement');
  END IF;
  IF p_evenement_type = 'ETAB' AND v_proprio_id != mon_etablissement_id() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE',
                                'error', 'Vous n''êtes pas concerné par cet événement');
  END IF;

  IF NOT v_event.contestable THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_CONTESTABLE',
                                'error', 'Cet événement n''est pas contestable');
  END IF;

  IF v_event.decision_admin IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_TRAITE',
                                'error', 'Cet événement a déjà été traité par un admin');
  END IF;

  IF v_event.reclamation_id IS NOT NULL THEN
    SELECT id, statut INTO v_existante FROM public.reclamations_score WHERE id = v_event.reclamation_id;
    IF v_existante.statut = 'PENDING' THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'RECLAMATION_EN_COURS',
                                  'error', 'Une réclamation est déjà ouverte pour cet événement',
                                  'reclamation_id', v_existante.id);
    END IF;
  END IF;

  -- Créer la réclamation
  INSERT INTO public.reclamations_score (
    evenement_type, evenement_soignant_id, evenement_etab_id,
    contesteur_id, motif_categorie, texte_libre, justificatif_storage_path
  ) VALUES (
    p_evenement_type,
    CASE WHEN p_evenement_type = 'SOIGNANT' THEN p_evenement_id ELSE NULL END,
    CASE WHEN p_evenement_type = 'ETAB' THEN p_evenement_id ELSE NULL END,
    v_uid, p_motif_categorie, trim(p_texte_libre), p_justificatif_storage_path
  ) RETURNING id INTO v_reclamation_id;

  -- Lier l'event à la réclamation
  IF p_evenement_type = 'SOIGNANT' THEN
    UPDATE public.evenements_score_soignant SET reclamation_id = v_reclamation_id WHERE id = p_evenement_id;
  ELSE
    UPDATE public.evenements_score_etab SET reclamation_id = v_reclamation_id WHERE id = p_evenement_id;
  END IF;

  -- Notification admin via externalisation
  INSERT INTO public.externalisation_actions (type_action, payload, source, source_id)
  VALUES ('EMAIL_NOTIF', jsonb_build_object(
    'destinataire_role', 'ADMIN',
    'type', 'RECLAMATION_SCORE_NOUVELLE',
    'data', jsonb_build_object(
      'reclamation_id', v_reclamation_id,
      'evenement_type', p_evenement_type,
      'motif_categorie', p_motif_categorie,
      'contesteur_id', v_uid
    )
  ), 'AUTRE', v_reclamation_id);

  -- Audit
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'SOIGNANT', 'SYSTEM', 'reclamation_score', v_reclamation_id,
    jsonb_build_object('evenement', 'RECLAMATION_SCORE_CREEE',
                        'event_score_id', p_evenement_id,
                        'event_type', p_evenement_type,
                        'motif_categorie', p_motif_categorie,
                        'justificatif', p_justificatif_storage_path IS NOT NULL)
  );

  RETURN jsonb_build_object('success', true, 'reclamation_id', v_reclamation_id, 'statut', 'PENDING');
END;
$$;


ALTER FUNCTION "public"."fn_creer_reclamation_score"("p_evenement_id" "uuid", "p_evenement_type" "text", "p_motif_categorie" "text", "p_texte_libre" "text", "p_justificatif_storage_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_creer_serie"("p_intitule" "text", "p_description" "text" DEFAULT NULL::"text", "p_profession_requise" "public"."type_profession" DEFAULT NULL::"public"."type_profession", "p_service" "text" DEFAULT NULL::"text", "p_taux_horaire_base" numeric DEFAULT NULL::numeric, "p_est_urgente" boolean DEFAULT false, "p_niveau_urgence" integer DEFAULT 0, "p_missions" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etablissement_id uuid;
  v_blocage jsonb;
  v_count integer;
  v_mission jsonb;
  v_created_ids uuid[] := ARRAY[]::uuid[];
  v_mission_id uuid;
BEGIN
  v_etablissement_id := mon_etablissement_id();
  IF v_etablissement_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Établissement non trouvé.');
  END IF;

  v_blocage := fn_blocage_publication_etab(v_etablissement_id);
  IF v_blocage IS NOT NULL THEN
    RETURN (v_blocage - 'error') || jsonb_build_object('success', false, 'error', v_blocage->>'error');
  END IF;

  IF p_intitule IS NULL OR p_profession_requise IS NULL OR p_taux_horaire_base IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Champs obligatoires manquants.');
  END IF;

  v_count := jsonb_array_length(p_missions);
  IF v_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun créneau fourni.');
  END IF;
  IF v_count > 30 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Maximum 30 créneaux par série.');
  END IF;

  FOR v_mission IN SELECT * FROM jsonb_array_elements(p_missions)
  LOOP
    INSERT INTO missions (
      etablissement_id, intitule, description, profession_requise, service,
      debut_le, fin_le, taux_horaire_base, est_urgente, niveau_urgence
    ) VALUES (
      v_etablissement_id,
      p_intitule,
      p_description,
      p_profession_requise,
      p_service,
      (v_mission->>'debut')::timestamptz,
      (v_mission->>'fin')::timestamptz,
      p_taux_horaire_base,
      p_est_urgente,
      CASE WHEN p_est_urgente THEN p_niveau_urgence ELSE 0 END
    )
    RETURNING id INTO v_mission_id;
    v_created_ids := v_created_ids || v_mission_id;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'count', v_count, 'mission_ids', to_jsonb(v_created_ids));
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_creer_serie"("p_intitule" "text", "p_description" "text", "p_profession_requise" "public"."type_profession", "p_service" "text", "p_taux_horaire_base" numeric, "p_est_urgente" boolean, "p_niveau_urgence" integer, "p_missions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crm_enregistrer_email_envoye"("p_contact_id" "uuid", "p_automatisee" boolean DEFAULT false, "p_details" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_contact public.sales_contacts%ROWTYPE;
  v_etape smallint;
  v_echeance timestamptz;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_contact
  FROM public.sales_contacts
  WHERE id = p_contact_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Contact CRM introuvable';
  END IF;
  IF v_contact.ne_plus_contacter OR v_contact.statut = 'PERDU' THEN
    RAISE EXCEPTION 'Ce contact ne doit plus etre contacte';
  END IF;

  v_etape := LEAST(v_contact.sequence_etape + 1, 20);
  v_echeance := now() + CASE
    WHEN v_etape <= 1 THEN interval '3 days'
    WHEN v_etape = 2 THEN interval '7 days'
    ELSE interval '14 days'
  END;

  UPDATE public.sales_contacts
     SET statut = CASE WHEN statut = 'PROSPECT' THEN 'CONTACTE' ELSE 'RELANCE' END,
         reponse = COALESCE(reponse, 'EN_ATTENTE'),
         dernier_contact_le = now(),
         derniere_action_type = 'EMAIL_ENVOYE',
         sequence_etape = v_etape,
         sequence_active = true,
         a_rappeler = true,
         prochaine_action_le = v_echeance,
         maj_le = now()
   WHERE id = p_contact_id;

  UPDATE public.sales_taches
     SET statut = 'TERMINEE', terminee_le = now(), terminee_par = auth.uid(), maj_le = now()
   WHERE contact_id = p_contact_id
     AND statut IN ('A_FAIRE', 'EN_COURS')
     AND canal = 'EMAIL';

  INSERT INTO public.sales_activites (
    contact_id, action_type, canal, resultat, details, acteur_id, automatisee
  ) VALUES (
    p_contact_id, 'EMAIL_ENVOYE', 'EMAIL', 'EN_ATTENTE', p_details,
    auth.uid(), COALESCE(p_automatisee, false)
  );

  PERFORM public.fn_crm_generer_taches();
  RETURN jsonb_build_object('success', true, 'prochaine_action_le', v_echeance, 'sequence_etape', v_etape);
END;
$$;


ALTER FUNCTION "public"."fn_crm_enregistrer_email_envoye"("p_contact_id" "uuid", "p_automatisee" boolean, "p_details" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crm_generer_taches"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_creees integer := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.est_admin() THEN
    RAISE EXCEPTION 'Acces admin refuse' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.sales_taches (
    contact_id, type, canal, priorite, titre, echeance_le, assignee_a,
    sequence_etape, origine, idempotence_key
  )
  SELECT
    c.id,
    CASE
      WHEN c.statut = 'PROSPECT' AND c.sequence_etape = 0 THEN 'PREMIER_CONTACT'
      WHEN c.a_rappeler THEN 'RAPPEL'
      WHEN c.sequence_etape >= 3 THEN 'RELANCE_FINALE'
      ELSE 'RELANCE'
    END,
    CASE WHEN c.telephone IS NOT NULL AND btrim(c.telephone) <> '' THEN 'TELEPHONE' ELSE 'EMAIL' END,
    CASE
      WHEN c.prochaine_action_le < now() - interval '2 days' THEN 'URGENTE'
      WHEN c.prochaine_action_le < now() THEN 'HAUTE'
      ELSE 'NORMALE'
    END,
    CASE
      WHEN c.statut = 'PROSPECT' AND c.sequence_etape = 0 THEN 'Premier contact — ' || c.nom
      WHEN c.a_rappeler THEN 'Rappeler — ' || c.nom
      WHEN c.sequence_etape >= 3 THEN 'Derniere relance — ' || c.nom
      ELSE 'Relance ' || c.sequence_etape::text || ' — ' || c.nom
    END,
    COALESCE(c.prochaine_action_le, now()),
    c.responsable_id,
    c.sequence_etape,
    'AUTOMATISATION',
    c.id::text || ':SEQUENCE:' || c.sequence_etape::text
  FROM public.sales_contacts c
  WHERE c.archive IS FALSE
    AND c.sequence_active IS TRUE
    AND c.ne_plus_contacter IS FALSE
    AND c.statut NOT IN ('INSCRIT', 'PERDU')
    AND COALESCE(c.prochaine_action_le, now()) <= now() + interval '7 days'
  ON CONFLICT (idempotence_key) DO NOTHING;

  GET DIAGNOSTICS v_creees = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'taches_creees', v_creees, 'genere_le', now());
END;
$$;


ALTER FUNCTION "public"."fn_crm_generer_taches"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_crm_initialiser_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
BEGIN
  IF NEW.statut IN ('INSCRIT', 'PERDU') OR NEW.archive IS TRUE THEN
    NEW.sequence_active := false;
    NEW.prochaine_action_le := NULL;
  ELSE
    NEW.sequence_active := COALESCE(NEW.sequence_active, true);
    NEW.prochaine_action_le := COALESCE(NEW.prochaine_action_le, now());
  END IF;

  IF NEW.responsable_id IS NULL THEN
    SELECT ea.user_id
      INTO NEW.responsable_id
      FROM public.equipe_admin ea
     WHERE ea.actif IS TRUE
       AND ea.user_id IS NOT NULL
     ORDER BY
       CASE WHEN lower(ea.email) IN ('gabrielle.pcd@outlook.com', 'admin@jolene.app') THEN 0 ELSE 1 END,
       ea.cree_le
     LIMIT 1;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_crm_initialiser_contact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cumul_annuel_paie"("p_soignant_id" "uuid", "p_annee" integer DEFAULT NULL::integer, "p_jusqu_au" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH params AS (
    SELECT
      COALESCE(p_annee, EXTRACT(YEAR FROM COALESCE(p_jusqu_au, CURRENT_DATE))::int) AS annee,
      COALESCE(p_jusqu_au, CURRENT_DATE) AS jusqu_au
  )
  SELECT jsonb_build_object(
    'annee', (SELECT annee FROM params),
    'jusqu_au', (SELECT jusqu_au FROM params),
    'nombre_bulletins', COALESCE(COUNT(bp.id), 0),
    'cumul_brut', COALESCE(SUM(bp.salaire_brut), 0),
    'cumul_cotisations_salariales', COALESCE(SUM(bp.total_cotisations_salariales), 0),
    'cumul_cotisations_patronales', COALESCE(SUM(bp.total_cotisations_patronales), 0),
    'cumul_net_avant_impot', COALESCE(SUM(bp.net_avant_impot), 0),
    'cumul_ifm', COALESCE(SUM(bp.ifm), 0),
    'cumul_icp', COALESCE(SUM(bp.icp), 0)
  )
  FROM bulletins_paie bp, params
  WHERE bp.soignant_id = p_soignant_id
    AND EXTRACT(YEAR FROM bp.periode_debut) = params.annee
    AND bp.periode_debut <= params.jusqu_au
    AND bp.statut <> 'ANNULE'
    AND (
      bp.soignant_id = auth.uid()
      OR public.est_admin()
    );
$$;


ALTER FUNCTION "public"."fn_cumul_annuel_paie"("p_soignant_id" "uuid", "p_annee" integer, "p_jusqu_au" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_cumul_factures_mission"("p_mission_id" "uuid", "p_jusqu_au" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_cumul_ht numeric;
  v_cumul_ttc numeric;
  v_nb_factures integer;
BEGIN
  SELECT
    COALESCE(SUM(montant_ht), 0),
    COALESCE(SUM(montant_ttc), 0),
    COUNT(*)
  INTO v_cumul_ht, v_cumul_ttc, v_nb_factures
  FROM factures_honoraires
  WHERE mission_id = p_mission_id
    AND statut NOT IN ('ANNULEE','REMPLACEE','ERREUR_GENERATION','EN_GENERATION')
    AND type_document = 'FACTURE'
    AND (p_jusqu_au IS NULL OR periode_fin <= p_jusqu_au);

  RETURN jsonb_build_object(
    'mission_id', p_mission_id,
    'jusqu_au', p_jusqu_au,
    'cumul_ht', v_cumul_ht,
    'cumul_ttc', v_cumul_ttc,
    'nb_factures', v_nb_factures
  );
END;
$$;


