COMMENT ON FUNCTION "public"."fn_cumul_factures_mission"("p_mission_id" "uuid", "p_jusqu_au" "date") IS 'Partie 2 — cumul HT/TTC + nombre de factures FACTURE non-ANNULEE/REMPLACEE/ERREUR/EN_GENERATION pour une mission jusqu''à p_jusqu_au (default toutes). Utilisé par generate-invoice pour mention cumul dans le PDF hebdo et finale partielle.';



CREATE OR REPLACE FUNCTION "public"."fn_dans_fenetre_retractation"("p_candidature_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_acceptee_a timestamptz;
BEGIN
  SELECT acceptee_a INTO v_acceptee_a FROM public.candidatures WHERE id = p_candidature_id;
  IF v_acceptee_a IS NULL THEN RETURN false; END IF;
  RETURN NOW() - v_acceptee_a < INTERVAL '30 minutes';
END;
$$;


