CREATE OR REPLACE FUNCTION "public"."fn_declarer_empechement_imperieux"("p_mission_id" "uuid", "p_indispo_debut" "date", "p_indispo_fin" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m public.missions%ROWTYPE;
  v_escrow public.paiements_escrow%ROWTYPE;
  v_nb integer := 0;
  v_max integer := greatest(
    0, fn_param_num('annulations_justifiees_max_12m', 2)::integer
  );
  v_n12 integer;
  v_depasse boolean;
  v_admin uuid;
  v_soignant_id uuid := auth.uid();
  v_audit_result jsonb;
  v_refund_result jsonb;
  v_blocage_publication jsonb;
  v_notifications_avant integer := 0;
  v_rows integer := 0;
  v_context text;
  v_est_future boolean;
  v_originale_cloturee boolean := false;
  v_remplacement_en_revue boolean := false;
  v_finance_resolution text := 'AUCUNE';
  v_previous_empechement_context text := COALESCE(
    current_setting('jolene.empechement_mission_context', true), ''
  );
  v_previous_empechement_validated text := COALESCE(
    current_setting('jolene.empechement_mission_validated', true), ''
  );
  v_mission_diffusee_id uuid := p_mission_id;
  v_remplacement_id uuid;
  v_previous_system_update text := COALESCE(
    current_setting('jolene.system_update', true), ''
  );
BEGIN
  -- Un verrou par soignant sérialise le quota même si deux missions distinctes
  -- sont déclarées en parallèle. Le verrou de ligne empêche en plus une double
  -- déclaration de la même mission.
  IF v_soignant_id IS NOT NULL THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'jolene.empechement.' || v_soignant_id::text,
        0
      )
    );
  END IF;

  SELECT * INTO v_m
  FROM public.missions
  WHERE id = p_mission_id AND soignant_assigne_id = v_soignant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;
  IF v_m.est_arret_maladie THEN
    RETURN jsonb_build_object('error', 'Un empêchement est déjà déclaré sur cette mission.');
  END IF;
  IF v_m.statut NOT IN ('ASSIGNEE', 'EN_COURS') THEN
    RETURN jsonb_build_object('error', 'Cette mission n''est plus active.');
  END IF;
  IF p_indispo_debut IS NULL OR p_indispo_fin IS NULL OR p_indispo_fin < p_indispo_debut THEN
    RETURN jsonb_build_object('error', 'Dates d''indisponibilité invalides.');
  END IF;
  IF p_indispo_fin - p_indispo_debut > 90 THEN
    RETURN jsonb_build_object('error', 'Période d''indisponibilité trop longue (90 jours max).');
  END IF;
  IF p_indispo_fin < (v_m.debut_le AT TIME ZONE 'Europe/Paris')::date
     OR p_indispo_debut > (v_m.fin_le AT TIME ZONE 'Europe/Paris')::date THEN
    RETURN jsonb_build_object(
      'error_code', 'INDISPONIBILITE_HORS_MISSION',
      'error', 'La période d''indisponibilité doit chevaucher la mission.'
    );
  END IF;

  v_est_future := v_m.statut = 'ASSIGNEE' AND v_m.debut_le > now();

  -- Une mission future doit pouvoir être annulée sans jamais payer l'ancien
  -- soignant. Les situations déjà externalisées ou ambiguës sont arrêtées
  -- avant le moindre flag/audit : aucune demi-transaction n'est possible.
  IF v_est_future THEN
    IF EXISTS (
      SELECT 1 FROM public.stripe_transfers st
      WHERE st.mission_id = p_mission_id
        AND st.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
    ) OR EXISTS (
      SELECT 1 FROM public.paiements_soignant ps
      WHERE ps.mission_id = p_mission_id
    ) OR EXISTS (
      SELECT 1 FROM public.factures_honoraires fh
      WHERE fh.mission_id = p_mission_id
        AND fh.statut NOT IN ('ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION')
    ) THEN
      RETURN jsonb_build_object(
        'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
        'error', 'Une opération financière existe déjà pour cette mission. Le support doit la rapprocher avant l''annulation.'
      );
    END IF;

    SELECT pe.* INTO v_escrow
    FROM public.paiements_escrow pe
    WHERE pe.mission_id = p_mission_id
    ORDER BY pe.cree_le DESC
    LIMIT 1
    FOR UPDATE;

    IF FOUND THEN
      IF v_escrow.statut IN ('RELEASE_PLANIFIE', 'PAYE', 'DISPUTE')
         OR (
           v_escrow.statut = 'INITIE'
           AND (
             v_escrow.stripe_payment_intent_id IS NOT NULL
             OR v_escrow.stripe_charge_id IS NOT NULL
             OR v_escrow.stripe_payout_id IS NOT NULL
             OR COALESCE(v_escrow.tentatives_debit, 0) > 0
           )
         ) THEN
        RETURN jsonb_build_object(
          'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
          'error', 'Le paiement rapide est déjà en cours d''externalisation. Le support doit le rapprocher avant l''annulation.',
          'escrow_statut', v_escrow.statut
        );
      END IF;
    END IF;
  END IF;

  SELECT count(*) INTO v_n12
  FROM public.journaux_audit
  WHERE acteur_id = v_soignant_id
    AND action = 'ANNULATION_EMPECHEMENT_IMPERIEUX'
    AND cree_le > NOW() - INTERVAL '12 months';
  v_depasse := (v_n12 + 1) > v_max;

  -- Phase FLAG : le garde alphabétiquement premier vérifie que ces trois
  -- colonnes sont les seules mutées. La phase est nécessaire aussi pour un
  -- profil soignant qui possède parallèlement un rôle établissement faible.
  v_context := 'FLAG:' || p_mission_id::text || ':' || v_soignant_id::text;
  BEGIN
    PERFORM set_config(
      'jolene.empechement_mission_context', v_context, true
    );
    PERFORM set_config('jolene.empechement_mission_validated', '', true);
    UPDATE missions
    SET est_arret_maladie = TRUE,
        arret_maladie_declare_le = NOW(),
        modifie_le = NOW()
    WHERE id = p_mission_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1
       OR NOT EXISTS (
         SELECT 1
         FROM public.missions m_flag
         WHERE m_flag.id = p_mission_id
           AND m_flag.est_arret_maladie IS TRUE
           AND m_flag.arret_maladie_declare_le IS NOT NULL
       ) THEN
      RAISE EXCEPTION 'Phase interne FLAG incomplète.'
        USING ERRCODE = 'P0001';
    END IF;
    PERFORM set_config(
      'jolene.empechement_mission_validated',
      v_previous_empechement_validated,
      true
    );
    PERFORM set_config(
      'jolene.empechement_mission_context',
      v_previous_empechement_context,
      true
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'jolene.empechement_mission_validated',
      v_previous_empechement_validated,
      true
    );
    PERFORM set_config(
      'jolene.empechement_mission_context',
      v_previous_empechement_context,
      true
    );
    RAISE;
  END;

  v_audit_result := fn_ecrire_audit_safe(
    v_soignant_id, 'SOIGNANT', 'ANNULATION_EMPECHEMENT_IMPERIEUX',
    'mission', p_mission_id, NULL,
    jsonb_build_object(
      'sur_honneur', true,
      'indispo_debut', p_indispo_debut,
      'indispo_fin', p_indispo_fin,
      'n_12_mois', v_n12 + 1,
      'max_12_mois', v_max,
      'depassement', v_depasse
    )
  );
  IF COALESCE((v_audit_result->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'La déclaration ne peut pas être journalisée.'
      USING ERRCODE = 'P0001';
  END IF;

  -- Le compteur est intégralement dérivé de ses sources canoniques.
  PERFORM private.fn_resynchroniser_compteurs_soignant(v_soignant_id);

  IF v_depasse THEN
    BEGIN
      PERFORM set_config('jolene.system_update', 'true', true);
      UPDATE soignants
      SET score_fiabilite = GREATEST(
            0, COALESCE(score_fiabilite, 50) - 8
          ),
          modifie_le = NOW()
      WHERE id = v_soignant_id;
      PERFORM set_config(
        'jolene.system_update', v_previous_system_update, true
      );
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config(
        'jolene.system_update', v_previous_system_update, true
      );
      RAISE;
    END;

    FOR v_admin IN
      SELECT user_id FROM equipe_admin WHERE actif AND user_id IS NOT NULL
    LOOP
      INSERT INTO notifications (
        destinataire_id, type, titre, corps, lien, type_destinataire
      ) VALUES (
        v_admin,
        'SYSTEM',
        'Empêchements répétés — revue soignant ⚠️',
        'Un soignant vient de déclarer son ' || (v_n12 + 1) ||
          'e empêchement impérieux sur 12 mois (max toléré : ' || v_max ||
          '). Pénalité de score appliquée. Détails dans le journal d''audit ' ||
          '(action ANNULATION_EMPECHEMENT_IMPERIEUX).',
        '/admin/audit',
        'ADMIN'
      );
    END LOOP;
  END IF;

  -- Neutraliser l'ancien rail financier puis clôturer toute mission future,
  -- garantie ou non. L'originale conserve l'assigné pour la preuve et les
  -- compteurs ; le remplacement aura toujours un nouvel id.
  IF v_est_future THEN
    IF v_escrow.id IS NOT NULL THEN
      IF v_escrow.statut = 'INITIE' THEN
        UPDATE public.paiements_escrow
           SET statut = 'REMBOURSE',
               erreur = 'Annulé avant tout débit : empêchement impérieux',
               modifie_le = now()
         WHERE id = v_escrow.id
           AND statut = 'INITIE'
           AND stripe_payment_intent_id IS NULL
           AND stripe_charge_id IS NULL
           AND stripe_payout_id IS NULL
           AND tentatives_debit = 0;
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows <> 1 THEN
          RAISE EXCEPTION 'Neutralisation escrow concurrente refusée.'
            USING ERRCODE = 'P0001';
        END IF;
        UPDATE public.escrow_exposition_releases
           SET statut = 'REGLE'
         WHERE paiement_escrow_id = v_escrow.id AND statut = 'ACTIF';
        UPDATE public.escrow_release_queue
           SET statut = 'ECHEC',
               erreur = 'Mission annulée avant débit',
               traite_le = now()
         WHERE paiement_escrow_id = v_escrow.id
           AND statut IN ('EN_ATTENTE', 'EN_COURS');
        INSERT INTO public.journaux_audit (
          acteur_id, type_acteur, action, type_ressource, id_ressource,
          details, navigateur_acteur
        ) VALUES (
          '00000000-0000-0000-0000-000000000000'::uuid,
          'SYSTEME', 'ADMIN_ACTION', 'paiement_escrow', v_escrow.id,
          jsonb_build_object(
            'evenement', 'ESCROW_ANNULE_AVANT_DEBIT',
            'mission_id', p_mission_id,
            'motif', 'EMPECHEMENT_IMPERIEUX'
          ),
          'fn_declarer_empechement_imperieux'
        );
        v_finance_resolution := 'ESCROW_ANNULE_AVANT_DEBIT';
      ELSIF v_escrow.statut IN ('DEBITE', 'DISPONIBLE') THEN
        v_refund_result := public.fn_escrow_rembourser(
          v_escrow.id,
          v_escrow.honoraires_cents,
          true,
          'Empêchement impérieux avant mission'
        );
        IF COALESCE((v_refund_result->>'success')::boolean, false) IS NOT TRUE THEN
          RAISE EXCEPTION 'Remboursement escrow impossible: %', v_refund_result
            USING ERRCODE = 'P0001';
        END IF;
        v_finance_resolution := 'ESCROW_REMBOURSEMENT_ENFILE';
      ELSIF v_escrow.statut = 'REMBOURSE_EN_COURS' THEN
        v_finance_resolution := 'ESCROW_REMBOURSEMENT_DEJA_EN_COURS';
      ELSIF v_escrow.statut IN ('REMBOURSE', 'ECHOUE') THEN
        v_finance_resolution := 'ESCROW_TERMINAL';
      ELSE
        RAISE EXCEPTION 'Etat escrow non annulable: %', v_escrow.statut
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    v_context := 'CLOSE:' || p_mission_id::text || ':' || v_soignant_id::text;
    BEGIN
      PERFORM set_config('jolene.empechement_mission_context', v_context, true);
      PERFORM set_config('jolene.empechement_mission_validated', '', true);
      UPDATE public.missions
         SET statut = 'ANNULEE_PAR_SOIGNANT', modifie_le = now()
       WHERE id = p_mission_id;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 OR NOT EXISTS (
        SELECT 1 FROM public.missions m_close
        WHERE m_close.id = p_mission_id
          AND m_close.statut = 'ANNULEE_PAR_SOIGNANT'
          AND m_close.soignant_assigne_id = v_soignant_id
          AND m_close.est_arret_maladie IS TRUE
      ) THEN
        RAISE EXCEPTION 'Phase interne CLOSE incomplète.'
          USING ERRCODE = 'P0001';
      END IF;
      PERFORM set_config(
        'jolene.empechement_mission_validated',
        v_previous_empechement_validated, true
      );
      PERFORM set_config(
        'jolene.empechement_mission_context',
        v_previous_empechement_context, true
      );
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config(
        'jolene.empechement_mission_validated',
        v_previous_empechement_validated, true
      );
      PERFORM set_config(
        'jolene.empechement_mission_context',
        v_previous_empechement_context, true
      );
      RAISE;
    END;
    v_originale_cloturee := true;

    -- Le contrat signé reste une preuve immuable. Si une DPAE a été faite,
    -- on enfile explicitement son annulation au lieu de falsifier le contrat.
    INSERT INTO public.externalisation_actions (
      type_action, payload, source, source_id
    )
    SELECT 'DPAE_ANNULATION',
           jsonb_build_object(
             'contrat_id', cm.id,
             'mission_id', p_mission_id,
             'motif', 'EMPECHEMENT_IMPERIEUX',
             'echeance_legale_h', 48
           ),
           'ANNULATION_MISSION', p_mission_id
    FROM public.contrats_mission cm
    WHERE cm.mission_id = p_mission_id
      AND cm.statut = 'SIGNE_COMPLET'
      AND cm.type_contrat IN ('CDD', 'CDDU', 'VACATION')
      AND (
        COALESCE(cm.dpae_effectuee, false) IS TRUE
        OR NULLIF(btrim(COALESCE(cm.dpae_numero, '')), '') IS NOT NULL
      );
  END IF;

  INSERT INTO public.notifications (
    destinataire_id, type, titre, corps, lien, type_destinataire
  ) VALUES (
    v_m.etablissement_id,
    'SYSTEM',
    'Empêchement impérieux déclaré ⚠️',
    'Le soignant assigné à "' || fn_html_escape(v_m.intitule) ||
      '" atteste sur l''honneur d''un empêchement impérieux et sera indisponible du ' ||
      TO_CHAR(p_indispo_debut, 'DD/MM') || ' au ' || TO_CHAR(p_indispo_fin, 'DD/MM') || '.' ||
      CASE
        WHEN v_m.garantie_remplacement AND v_m.fin_le > now() + interval '1 hour'
          THEN ' Garantie remplacement : Jolene traite la demande. Vous serez informé dès sa diffusion.'
        WHEN v_est_future
          THEN ' La mission originale est clôturée. Publiez un remplacement depuis vos missions.'
        ELSE ' La mission est suspendue jusqu''à validation des heures réellement effectuées.'
      END,
    '/etablissement/missions/' || v_m.id,
    'ETABLISSEMENT'
  );

  INSERT INTO notifications (
    destinataire_id, type, titre, corps, lien, type_destinataire
  ) VALUES (
    v_soignant_id,
    'SYSTEM',
    'Empêchement enregistré',
    'Votre attestation sur l''honneur est enregistrée — aucun justificatif à fournir.' ||
      CASE
        WHEN v_depasse
          THEN ' Attention : au-delà de ' || v_max ||
            ' empêchements sur 12 mois, la pénalité de score s''applique (c''est le cas ici).'
        ELSE ' Aucune pénalité de score.'
      END ||
      ' Une fausse déclaration engage votre responsabilité (CGU).',
    '/soignant/missions/' || v_m.id,
    'SOIGNANT'
  );

  IF v_m.garantie_remplacement AND v_m.fin_le > now() + interval '1 hour' THEN
    v_blocage_publication := public.fn_blocage_publication_etab(
      v_m.etablissement_id
    );
    IF v_blocage_publication IS NOT NULL THEN
      v_remplacement_en_revue := true;
      FOR v_admin IN
        SELECT user_id FROM public.equipe_admin
        WHERE actif AND user_id IS NOT NULL
      LOOP
        INSERT INTO public.notifications (
          destinataire_id, type_destinataire, type, titre, corps, lien,
          type_ressource, id_ressource
        ) VALUES (
          v_admin, 'ADMIN', 'SYSTEM',
          'Garantie remplacement à traiter manuellement ⚠️',
          'L''empêchement est enregistré mais la publication automatique est bloquée : '
            || COALESCE(
              v_blocage_publication->>'message',
              v_blocage_publication->>'error', 'gate établissement'
            ) || '.',
          '/admin/missions', 'mission', p_mission_id
        );
      END LOOP;
    ELSE
      v_context := 'REPLACEMENT:' || p_mission_id::text || ':'
        || v_soignant_id::text;
      BEGIN
        PERFORM set_config(
          'jolene.empechement_mission_context', v_context, true
        );
        PERFORM set_config('jolene.empechement_mission_validated', '', true);
        INSERT INTO public.missions (
          etablissement_id, intitule, description, service,
          profession_requise, specialite_medicale_requise,
          accepte_non_specialises, debut_le, fin_le, duree_heures,
          taux_horaire_base, type_contrat_recherche,
          mode_remuneration, retrocession_pct, mission_source, statut,
          mode_attribution, est_urgente, niveau_urgence,
          garantie_remplacement, remplacement_de_mission_id
        ) VALUES (
          v_m.etablissement_id,
          'REMPLACEMENT URGENT — ' || v_m.intitule,
          COALESCE(v_m.description, '')
            || E'\n\n[Mission de remplacement générée automatiquement — garantie Jolene]',
          v_m.service,
          v_m.profession_requise,
          v_m.specialite_medicale_requise,
          v_m.accepte_non_specialises,
          GREATEST(v_m.debut_le, now() + interval '15 minutes'),
          v_m.fin_le,
          round(extract(epoch FROM (
            v_m.fin_le - GREATEST(
              v_m.debut_le, now() + interval '15 minutes'
            )
          )) / 3600.0, 2),
          v_m.taux_horaire_base,
          v_m.type_contrat_recherche,
          v_m.mode_remuneration,
          v_m.retrocession_pct,
          'REMPLACEMENT',
          'OUVERTE',
          'PREMIER_ARRIVE',
          true,
          3,
          true,
          v_m.id
        ) RETURNING id INTO v_remplacement_id;
        IF NOT EXISTS (
          SELECT 1
          FROM public.missions m_replacement
          WHERE m_replacement.id = v_remplacement_id
            AND m_replacement.remplacement_de_mission_id = p_mission_id
            AND m_replacement.statut = 'OUVERTE'
            AND m_replacement.soignant_assigne_id IS NULL
            AND m_replacement.est_urgente IS TRUE
            AND m_replacement.niveau_urgence = 3
            AND m_replacement.mode_attribution = 'PREMIER_ARRIVE'
            AND m_replacement.debut_le > now()
        ) THEN
          RAISE EXCEPTION 'Phase interne REPLACEMENT incomplète.'
            USING ERRCODE = 'P0001';
        END IF;
        PERFORM set_config(
          'jolene.empechement_mission_validated',
          v_previous_empechement_validated,
          true
        );
        PERFORM set_config(
          'jolene.empechement_mission_context',
          v_previous_empechement_context,
          true
        );
      EXCEPTION WHEN OTHERS THEN
        PERFORM set_config(
          'jolene.empechement_mission_validated',
          v_previous_empechement_validated,
          true
        );
        PERFORM set_config(
          'jolene.empechement_mission_context',
          v_previous_empechement_context,
          true
        );
        RAISE;
      END;
      v_mission_diffusee_id := v_remplacement_id;

      INSERT INTO notifications (
        destinataire_id, type, titre, corps, lien, type_destinataire,
        type_ressource, id_ressource
      ) VALUES (
        v_m.etablissement_id,
        'SYSTEM',
        'Mission de remplacement urgente créée 🚨',
        'La mission de remplacement pour « '
          || fn_html_escape(v_m.intitule)
          || ' » est publiée pour le temps restant et le pool vient d''être alerté.',
        '/etablissement/missions/' || v_remplacement_id,
        'ETABLISSEMENT',
        'mission',
        v_remplacement_id
      );

      -- Le trigger urgent est l'unique fan-out externe.
      SELECT greatest(0, count(*)::integer - v_notifications_avant)
      INTO v_nb
      FROM public.notifications n
      WHERE n.type IN ('MISSION_URGENTE', 'POOL_URGENCE')
        AND n.type_ressource = 'mission'
        AND n.id_ressource = v_mission_diffusee_id;
    END IF;
  END IF;

  -- Les AFTER triggers historiques peuvent avoir touché les compteurs pendant
  -- CLOSE ; le résultat final est toujours recalé sur les sources canoniques.
  PERFORM private.fn_resynchroniser_compteurs_soignant(v_soignant_id);

  RETURN jsonb_build_object(
    'success', true,
    'pool_alerte', v_nb,
    'mission_diffusee_id', v_mission_diffusee_id,
    'mission_remplacement_id', v_remplacement_id,
    'mission_originale_cloturee', v_originale_cloturee,
    'remplacement_en_revue', v_remplacement_en_revue,
    'finance_resolution', v_finance_resolution,
    'depassement', v_depasse,
    'n_12_mois', v_n12 + 1,
    'max_12_mois', v_max
  );
END;
$$;


ALTER FUNCTION "public"."fn_declarer_empechement_imperieux"("p_mission_id" "uuid", "p_indispo_debut" "date", "p_indispo_fin" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_declarer_fin_retroactive"("p_mission_id" "uuid", "p_heure_fin" timestamp with time zone, "p_raison" "text" DEFAULT 'Oubli de scan'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission RECORD;
  v_creneau_id uuid;
  v_creneau_debut timestamptz;
  v_arrondi timestamptz;
  v_scan_numero smallint;
  v_new_code text;
  v_new_hmac text;
  v_caller_is_soignant boolean;
  v_caller_is_etab_admin boolean;
BEGIN
  SELECT id, soignant_assigne_id, etablissement_id, nb_scans, statut
  INTO v_mission
  FROM missions
  WHERE id = p_mission_id AND statut IN ('ASSIGNEE', 'EN_COURS')
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Mission % introuvable ou dans un statut incompatible.', p_mission_id
      USING ERRCODE = 'no_data_found';
  END IF;

  v_caller_is_soignant := (auth.uid() = v_mission.soignant_assigne_id);
  v_caller_is_etab_admin := est_admin_etablissement()
    AND mon_etablissement_id() = v_mission.etablissement_id;

  IF NOT (v_caller_is_soignant OR v_caller_is_etab_admin OR est_admin()) THEN
    RAISE EXCEPTION 'Vous n''êtes pas autorisé(e) à déclarer une fin rétroactive sur cette mission.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT id, debut INTO v_creneau_id, v_creneau_debut
  FROM mission_creneaux
  WHERE mission_id = v_mission.id AND type_creneau = 'EFFECTIF' AND fin IS NULL
  ORDER BY debut DESC LIMIT 1;

  IF v_creneau_id IS NULL THEN
    RAISE EXCEPTION 'Aucun créneau effectif ouvert à fermer pour cette mission.'
      USING ERRCODE = 'no_data_found';
  END IF;

  IF p_heure_fin <= v_creneau_debut THEN
    RAISE EXCEPTION 'L''heure de fin (%) doit être postérieure au début du créneau (%).',
      p_heure_fin, v_creneau_debut USING ERRCODE = 'check_violation';
  END IF;

  v_arrondi := fn_arrondir_quart_heure(p_heure_fin);
  IF v_arrondi <= v_creneau_debut THEN
    v_arrondi := v_creneau_debut + INTERVAL '15 minutes';
  END IF;

  UPDATE mission_creneaux SET fin = v_arrondi WHERE id = v_creneau_id;

  v_scan_numero := COALESCE(v_mission.nb_scans, 0) + 1;
  INSERT INTO scans_pointage (
    mission_id, soignant_id, code_saisi, numero_scan, type_scan,
    scanne_le, horodatage_arrondi, creneau_effectif_id,
    est_en_avance, validation_etab_requise
  ) VALUES (
    v_mission.id, v_mission.soignant_assigne_id, 'RETROACTIF', v_scan_numero, 'FERMETURE',
    now(), v_arrondi, v_creneau_id,
    false, true
  );

  v_new_code := lpad(floor(random() * 1000000)::text, 6, '0');
  WHILE EXISTS (
    SELECT 1 FROM missions
    WHERE code_pointage_actif = v_new_code AND id != v_mission.id
      AND statut IN ('ASSIGNEE', 'EN_COURS')
  ) LOOP
    v_new_code := lpad(floor(random() * 1000000)::text, 6, '0');
  END LOOP;

  v_new_hmac := CASE
    WHEN current_setting('app.settings.hmac_secret', true) IS NOT NULL THEN
      encode(extensions.hmac(v_mission.id::text || ':' || v_new_code,
        current_setting('app.settings.hmac_secret', true), 'sha256'), 'hex')
    ELSE NULL
  END;

  UPDATE missions SET
    code_pointage_actif = v_new_code,
    code_pointage_hmac = v_new_hmac,
    prochain_type_scan = 'OUVERTURE',
    nb_scans = v_scan_numero
  WHERE id = v_mission.id;

  INSERT INTO journaux_audit
    (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
  VALUES (
    auth.uid(),
    CASE WHEN v_caller_is_soignant THEN 'SOIGNANT'
         WHEN v_caller_is_etab_admin THEN 'ADMIN_ETABLISSEMENT'
         ELSE 'ADMIN_PLATEFORME' END,
    'POINTAGE', 'mission', v_mission.id,
    jsonb_build_object(
      'sous_action', 'FIN_RETROACTIVE',
      'raison', p_raison,
      'creneau_effectif_id', v_creneau_id,
      'debut_creneau', v_creneau_debut,
      'heure_fin_declaree', p_heure_fin,
      'horodatage_arrondi', v_arrondi,
      'validation_etab_requise', true
    )
  );

  RETURN jsonb_build_object(
    'creneau_effectif_id', v_creneau_id,
    'debut_creneau', v_creneau_debut,
    'fin_declaree', v_arrondi,
    'validation_etab_requise', true,
    'nouveau_code', v_new_code,
    'nouveau_hmac', v_new_hmac,
    'prochain_type_scan', 'OUVERTURE',
    'numero_scan', v_scan_numero
  );
END;
$$;


ALTER FUNCTION "public"."fn_declarer_fin_retroactive"("p_mission_id" "uuid", "p_heure_fin" timestamp with time zone, "p_raison" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_declarer_heures_externes_avec_document"("p_employeur_nom" "text", "p_employeur_type" "text", "p_date_debut" "date", "p_date_fin" "date", "p_heures_declarees" numeric, "p_type_preuve" "text", "p_s3_cle" "text", "p_nom_fichier" "text", "p_type_mime" "text", "p_taille_octets" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_document jsonb;
  v_document_id uuid;
  v_heures_id uuid;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF p_type_preuve NOT IN ('BULLETIN_PAIE', 'ATTESTATION_EMPLOYEUR', 'CERTIFICAT_TRAVAIL')
     OR NULLIF(btrim(COALESCE(p_employeur_nom, '')), '') IS NULL
     OR length(p_employeur_nom) > 255
     OR p_date_debut IS NULL OR p_date_fin IS NULL OR p_date_fin < p_date_debut
     OR p_heures_declarees IS NULL OR p_heures_declarees < 1 OR p_heures_declarees > 10000 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DECLARATION_INVALIDE');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('heures:' || COALESCE(p_s3_cle, ''), 0));
  v_document := public.fn_remplacer_document_soignant(
    p_type_preuve, 'Justificatif d''heures externes', p_s3_cle,
    p_nom_fichier, p_type_mime, p_taille_octets
  );
  IF COALESCE((v_document->>'success')::boolean, false) IS NOT TRUE THEN
    RETURN v_document;
  END IF;
  v_document_id := (v_document->>'document_id')::uuid;

  SELECT id INTO v_heures_id
  FROM public.heures_externes
  WHERE soignant_id = v_uid AND document_id = v_document_id
  LIMIT 1;
  IF v_heures_id IS NULL THEN
    INSERT INTO public.heures_externes (
      soignant_id, employeur_nom, employeur_type, date_debut, date_fin,
      heures_declarees, document_id, type_preuve, statut
    ) VALUES (
      v_uid, left(btrim(p_employeur_nom), 255),
      NULLIF(left(btrim(COALESCE(p_employeur_type, '')), 100), ''),
      p_date_debut, p_date_fin, p_heures_declarees,
      v_document_id, p_type_preuve, 'EN_ATTENTE'
    ) RETURNING id INTO v_heures_id;

    PERFORM public.fn_ecrire_audit_safe(
      p_acteur_id := v_uid,
      p_type_acteur := 'SOIGNANT',
      p_action := 'HEURES_EXTERNES_DECLAREES',
      p_type_ressource := 'heures_externes',
      p_id_ressource := v_heures_id,
      p_details := jsonb_build_object(
        'document_id', v_document_id,
        'heures', p_heures_declarees,
        'date_debut', p_date_debut,
        'date_fin', p_date_fin
      )
    );
  END IF;
  RETURN jsonb_build_object(
    'success', true,
    'document_id', v_document_id,
    'heures_id', v_heures_id,
    'idempotent', COALESCE((v_document->>'idempotent')::boolean, false)
  );
END;
$$;


ALTER FUNCTION "public"."fn_declarer_heures_externes_avec_document"("p_employeur_nom" "text", "p_employeur_type" "text", "p_date_debut" "date", "p_date_fin" "date", "p_heures_declarees" numeric, "p_type_preuve" "text", "p_s3_cle" "text", "p_nom_fichier" "text", "p_type_mime" "text", "p_taille_octets" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_declarer_heures_externes_soignant"("p_etablissement_nom" "text", "p_etablissement_type" "text", "p_date_debut" "date", "p_date_fin" "date", "p_heures_declarees" integer, "p_attestation_url" "text", "p_attestation_nom_fichier" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'storage'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_version_source uuid;
  v_guc_precedent text := COALESCE(
    current_setting('jolene.heures_externes_server_update', true), ''
  );
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RAISE EXCEPTION 'Compte authentifié actif requis' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(btrim(COALESCE(p_etablissement_nom, '')), '') IS NULL
     OR char_length(btrim(p_etablissement_nom)) > 255
     OR char_length(COALESCE(p_etablissement_type, '')) > 100
     OR p_date_debut IS NULL
     OR p_date_fin IS NULL
     OR p_date_fin < p_date_debut
     OR p_heures_declarees IS NULL
     OR p_heures_declarees < 1
     OR p_heures_declarees > 10000 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'DECLARATION_INVALIDE',
      'error', 'Les données de la déclaration sont invalides.'
    );
  END IF;

  IF NULLIF(btrim(COALESCE(p_attestation_url, '')), '') IS NULL
     OR NULLIF(btrim(COALESCE(p_attestation_nom_fichier, '')), '') IS NULL
     OR char_length(p_attestation_nom_fichier) > 255
     OR p_attestation_url !~ (
       '^' || v_uid::text
       || '/heures-externes/[0-9]{10,17}_[A-Za-z0-9_-]{1,80}[.](pdf|jpg|png|webp)$'
     ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PREUVE_REQUISE',
      'error', 'Une preuve privée appartenant au soignant est obligatoire.'
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects o
    WHERE o.bucket_id = 'jolene-documents'
      AND o.name = p_attestation_url
      AND o.owner_id = v_uid::text
      AND CASE
        WHEN COALESCE(o.metadata ->> 'size', '') ~ '^[0-9]+$'
          THEN (o.metadata ->> 'size')::numeric > 0
        ELSE false
      END
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PREUVE_STORAGE_INVALIDE',
      'error', 'La preuve privée est absente, vide ou ne vous appartient pas.'
    );
  END IF;

  -- Les verrous sérialisent à la fois la réutilisation du chemin et les
  -- déclarations concurrentes du même soignant.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('heures-path:' || p_attestation_url, 0)
  );
  PERFORM pg_advisory_xact_lock(
    hashtextextended('heures-soignant:' || v_uid::text, 0)
  );

  IF EXISTS (
    SELECT 1
    FROM public.heures_externes_soignants h
    WHERE h.attestation_url = p_attestation_url
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PREUVE_DEJA_UTILISEE',
      'error', 'Cette preuve est déjà rattachée à une déclaration.'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.heures_externes_soignants h
    WHERE h.soignant_id = v_uid
      AND h.statut_validation IN ('EN_ATTENTE', 'VALIDE')
      AND daterange(h.date_debut, h.date_fin, '[]')
          && daterange(p_date_debut, p_date_fin, '[]')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PERIODE_CHEVAUCHANTE',
      'error', 'Une déclaration active couvre déjà tout ou partie de cette période.'
    );
  END IF;

  PERFORM set_config('jolene.heures_externes_server_update', 'true', true);
  INSERT INTO public.heures_externes_soignants (
    soignant_id,
    etablissement_nom,
    etablissement_type,
    date_debut,
    date_fin,
    heures_declarees,
    attestation_url,
    attestation_nom_fichier,
    statut_validation,
    commentaire_validation,
    valide_par,
    valide_le,
    heures_extraites_ia,
    resultat_ia,
    coherence_ia,
    verifie_ia_le,
    empreinte_preuve_sha256,
    source_validation_serveur,
    empreinte_snapshot_source
  ) VALUES (
    v_uid,
    left(btrim(p_etablissement_nom), 255),
    NULLIF(left(btrim(COALESCE(p_etablissement_type, '')), 100), ''),
    p_date_debut,
    p_date_fin,
    p_heures_declarees,
    p_attestation_url,
    left(btrim(p_attestation_nom_fichier), 255),
    'EN_ATTENTE',
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL
  )
  RETURNING id, version_source INTO v_id, v_version_source;
  PERFORM set_config(
    'jolene.heures_externes_server_update', v_guc_precedent, true
  );

  -- Action déjà autorisée par la contrainte journaux_audit. Écriture directe :
  -- une erreur d'audit annule aussi la déclaration, elle n'est jamais avalée.
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details
  ) VALUES (
    v_uid, 'SOIGNANT', 'HEURES_EXTERNES_DECLAREES',
    'heures_externes_soignants', v_id, p_attestation_url,
    jsonb_build_object(
      'date_debut', p_date_debut,
      'date_fin', p_date_fin,
      'heures_declarees', p_heures_declarees,
      'version_source', v_version_source
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'id', v_id,
    'version_source', v_version_source,
    'statut', 'EN_ATTENTE'
  );
END;
$_$;


ALTER FUNCTION "public"."fn_declarer_heures_externes_soignant"("p_etablissement_nom" "text", "p_etablissement_type" "text", "p_date_debut" "date", "p_date_fin" "date", "p_heures_declarees" integer, "p_attestation_url" "text", "p_attestation_nom_fichier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_declarer_honoraires_retrocession"("p_mission_id" "uuid", "p_montant_honoraires" numeric, "p_justificatif_cle" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m RECORD;
  v_retrocede numeric;
  v_taux_com numeric;
  v_com_ht numeric;
BEGIN
  SELECT * INTO v_m FROM missions WHERE id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF v_m.etablissement_id != mon_etablissement_id() AND NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Non autorisé');
  END IF;
  IF v_m.mode_remuneration != 'RETROCESSION' THEN
    RETURN jsonb_build_object('error', 'Cette mission n''est pas en rétrocession.');
  END IF;
  IF v_m.statut != 'TERMINEE' THEN
    RETURN jsonb_build_object('error', 'Déclaration possible une fois la mission terminée.');
  END IF;
  IF v_m.montant_honoraires_bruts IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'Honoraires déjà déclarés. Contactez le support pour rectifier.');
  END IF;
  IF p_montant_honoraires IS NULL OR p_montant_honoraires <= 0 OR p_montant_honoraires > 100000 THEN
    RETURN jsonb_build_object('error', 'Montant d''honoraires invalide.');
  END IF;
  IF p_justificatif_cle IS NULL OR length(trim(p_justificatif_cle)) < 5 THEN
    RETURN jsonb_build_object('error', 'Justificatif obligatoire : téléversez le relevé d''actes ou bordereau de la période.');
  END IF;

  v_retrocede := ROUND(p_montant_honoraires * COALESCE(v_m.retrocession_pct, 50) / 100.0, 2);
  v_taux_com := COALESCE(v_m.taux_commission_fige, v_m.taux_commission, 15);
  v_com_ht := ROUND(v_retrocede * v_taux_com / 100.0, 2);

  UPDATE missions SET
    montant_honoraires_bruts = p_montant_honoraires,
    justificatif_honoraires_cle = trim(p_justificatif_cle),
    total_brut = v_retrocede,
    net_a_payer = v_retrocede,
    montant_commission_ht = v_com_ht,
    montant_commission_tva = ROUND(v_com_ht * 0.20, 2),
    montant_commission_ttc = ROUND(v_com_ht * 1.20, 2),
    modifie_le = NOW()
  WHERE id = p_mission_id;

  INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (v_m.soignant_assigne_id, 'SYSTEM', 'Relevé d''honoraires à confirmer 💶',
    'Le cabinet déclare ' || p_montant_honoraires || ' € d''honoraires (justificatif joint) pour "' || fn_html_escape(v_m.intitule) ||
    '" — votre rétrocession (' || COALESCE(v_m.retrocession_pct, 50) || '%) : ' || v_retrocede ||
    ' €. CONFIRMEZ le relevé sur la mission (ou contestez sous 48h via un litige). Sans action de votre part, le montant sera validé automatiquement sous 48h.',
    '/soignant/missions/' || v_m.id, 'SOIGNANT');

  RETURN jsonb_build_object('success', TRUE, 'montant_retrocede', v_retrocede,
    'commission_ttc', ROUND(v_com_ht * 1.20, 2), 'en_attente_confirmation', TRUE);
END;
$$;


ALTER FUNCTION "public"."fn_declarer_honoraires_retrocession"("p_mission_id" "uuid", "p_montant_honoraires" numeric, "p_justificatif_cle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_declarer_paiement_facture_soignant"("p_facture_honoraire_id" "uuid", "p_montant" numeric, "p_methode" "text" DEFAULT NULL::"text", "p_reference" "text" DEFAULT NULL::"text", "p_date_paiement" "date" DEFAULT CURRENT_DATE, "p_attestation_sur_l_honneur" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fh public.factures_honoraires%ROWTYPE;
  v_mission public.missions%ROWTYPE;
  v_soignant public.soignants%ROWTYPE;
  v_etab public.etablissements%ROWTYPE;
  v_etab_id uuid := public.mon_etablissement_id();
  v_methode text;
  v_ref text;
  v_echeance date;
  v_paiement_id uuid;
BEGIN
  IF NOT p_attestation_sur_l_honneur THEN
    RETURN jsonb_build_object(
      'error', 'ATTESTATION_REQUISE',
      'message', 'L''attestation sur l''honneur est obligatoire pour déclarer un paiement soignant.'
    );
  END IF;

  SELECT * INTO v_fh
  FROM public.factures_honoraires
  WHERE id = p_facture_honoraire_id
  FOR UPDATE;
  IF v_fh.id IS NULL OR v_fh.type_document <> 'FACTURE' THEN
    RETURN jsonb_build_object('error', 'Facture d''honoraires introuvable');
  END IF;

  SELECT * INTO v_mission
  FROM public.missions
  WHERE id = v_fh.mission_id
  FOR UPDATE;
  IF v_mission.id IS NULL
     OR v_fh.etablissement_id <> v_mission.etablissement_id
     OR v_fh.soignant_id <> v_mission.soignant_assigne_id THEN
    RETURN jsonb_build_object('error', 'Facture et mission incohérentes');
  END IF;

  IF v_etab_id IS NULL
     OR v_etab_id <> v_mission.etablissement_id
     OR public.fn_a_permission_etablissement('paiement', v_etab_id) IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  IF v_mission.type_contrat_applique <> 'LIBERAL' THEN
    RETURN jsonb_build_object(
      'error', 'CONTRAT_INCOMPATIBLE',
      'message', 'Le paiement par facture est réservé aux missions libérales.'
    );
  END IF;
  IF v_fh.statut NOT IN ('EMISE', 'EN_RETARD') THEN
    RETURN jsonb_build_object('error', 'Cette facture n''est plus payable');
  END IF;
  IF v_mission.statut NOT IN ('EN_COURS', 'TERMINEE')
     OR (
       v_mission.statut = 'EN_COURS'
       AND (
         v_mission.strategie_facturation <> 'HEBDO_ET_FINALE'
         OR v_fh.est_facture_finale_mission
         OR v_fh.periode_fin >= CURRENT_DATE
       )
     ) THEN
    RETURN jsonb_build_object(
      'error', 'PERIODE_NON_PAYABLE',
      'message', 'Seule une période hebdomadaire close ou une mission terminée peut être payée.'
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.paiements_soignant p
    WHERE p.facture_honoraire_id = v_fh.id
      AND p.statut IN ('DECLARE', 'CONFIRME', 'RESOLU')
  ) OR EXISTS (
    SELECT 1 FROM public.stripe_transfers st
    WHERE st.facture_honoraire_id = v_fh.id
      AND st.statut IN ('CHARGE_REUSSI', 'TRANSFERE', 'PAYE')
  ) THEN
    RETURN jsonb_build_object('error', 'Paiement déjà déclaré pour cette période');
  END IF;

  IF p_montant IS NULL OR p_montant <= 0 THEN
    RETURN jsonb_build_object('error', 'Le montant doit être supérieur à 0.');
  END IF;
  IF abs(round(p_montant, 2) - round(v_fh.montant_ttc, 2)) > 0.01 THEN
    RETURN jsonb_build_object(
      'error', 'MONTANT_FACTURE_INCOHERENT',
      'message', 'Le montant déclaré doit correspondre au montant exact de la facture (' || v_fh.montant_ttc || ' €).'
    );
  END IF;
  IF p_date_paiement > CURRENT_DATE THEN
    RETURN jsonb_build_object('error', 'La date de paiement ne peut pas être dans le futur.');
  END IF;

  IF p_methode IS NOT NULL
     AND p_methode NOT IN ('VIREMENT', 'CHEQUE', 'NOTE_HONORAIRES') THEN
    RETURN jsonb_build_object(
      'error', 'METHODE_INVALIDE',
      'message', 'Pour une note d''honoraires, utilisez VIREMENT, CHEQUE ou NOTE_HONORAIRES.'
    );
  END IF;
  v_methode := COALESCE(p_methode, 'NOTE_HONORAIRES');
  v_ref := btrim(COALESCE(p_reference, ''));
  IF length(v_ref) < 5 OR v_ref !~ '[0-9]' THEN
    RETURN jsonb_build_object(
      'error', 'REFERENCE_INVALIDE',
      'message', 'La référence doit contenir au moins 5 caractères et un chiffre.'
    );
  END IF;

  SELECT * INTO v_soignant FROM public.soignants WHERE id = v_fh.soignant_id;
  SELECT * INTO v_etab FROM public.etablissements WHERE id = v_etab_id;
  v_echeance := p_date_paiement + COALESCE(v_etab.delai_paiement_jours, 30);

  INSERT INTO public.paiements_soignant (
    mission_id, facture_honoraire_id, soignant_id, etablissement_id,
    montant_net, methode, reference_virement, date_paiement, echeance_le,
    statut, confirme_par_etablissement, confirme_par_etablissement_le
  ) VALUES (
    v_mission.id, v_fh.id, v_fh.soignant_id, v_etab_id,
    round(p_montant, 2), v_methode, v_ref, p_date_paiement, v_echeance,
    'DECLARE', true, now()
  )
  RETURNING id INTO v_paiement_id;

  INSERT INTO public.notifications (
    destinataire_id, type, titre, corps, lien, type_destinataire
  ) VALUES (
    v_fh.soignant_id,
    'SYSTEM',
    'Paiement hebdomadaire déclaré',
    'Paiement de ' || round(p_montant, 2) || ' € déclaré pour la période du '
      || to_char(v_fh.periode_debut, 'DD/MM/YYYY') || ' au '
      || to_char(v_fh.periode_fin, 'DD/MM/YYYY') || ' de « '
      || public.fn_html_escape(v_mission.intitule) || ' » (réf. ' || v_ref || ').',
    '/soignant/mes-gains',
    'SOIGNANT'
  );

  PERFORM public.fn_ecrire_audit_safe(
    auth.uid(), 'ETABLISSEMENT', 'PAIEMENT_SOIGNANT_DECLARE_ETAB',
    'factures_honoraires', v_fh.id, NULL,
    jsonb_build_object(
      'mission_id', v_mission.id,
      'facture_honoraire_id', v_fh.id,
      'periode_debut', v_fh.periode_debut,
      'periode_fin', v_fh.periode_fin,
      'montant_net', round(p_montant, 2),
      'methode', v_methode,
      'reference_virement', v_ref,
      'date_paiement', p_date_paiement,
      'attestation_sur_l_honneur', true
    ),
    NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'paiement_id', v_paiement_id,
    'facture_honoraires_id', v_fh.id,
    'soignant_id', v_fh.soignant_id,
    'mission_intitule', v_mission.intitule,
    'echeance', v_echeance
  );
END;
$$;


ALTER FUNCTION "public"."fn_declarer_paiement_facture_soignant"("p_facture_honoraire_id" "uuid", "p_montant" numeric, "p_methode" "text", "p_reference" "text", "p_date_paiement" "date", "p_attestation_sur_l_honneur" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_declarer_paiement_soignant"("p_mission_id" "uuid", "p_montant" numeric, "p_methode" "text" DEFAULT NULL::"text", "p_reference" "text" DEFAULT NULL::"text", "p_date_paiement" "date" DEFAULT CURRENT_DATE, "p_attestation_sur_l_honneur" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission RECORD;
  v_soignant RECORD;
  v_etab RECORD;
  v_etab_id UUID := mon_etablissement_id();
  v_methode TEXT;
  v_echeance DATE;
  v_ref TEXT;
  v_stripe_actif BOOLEAN;
  v_paiement_id UUID;
  v_ecart_pct NUMERIC;
BEGIN
  IF NOT p_attestation_sur_l_honneur THEN
    RETURN jsonb_build_object('error', 'ATTESTATION_REQUISE',
      'message', 'L''attestation sur l''honneur est obligatoire pour déclarer un paiement soignant.');
  END IF;

  SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;

  IF v_mission.etablissement_id != v_etab_id AND NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  IF v_mission.statut != 'TERMINEE' THEN
    RETURN jsonb_build_object('error', 'La mission doit être terminée');
  END IF;

  IF EXISTS (SELECT 1 FROM paiements_soignant WHERE mission_id = p_mission_id AND statut IN ('DECLARE', 'CONFIRME')) THEN
    RETURN jsonb_build_object('error', 'Paiement déjà déclaré pour cette mission');
  END IF;

  IF v_mission.type_contrat_applique IS NULL THEN
    RETURN jsonb_build_object('error', 'CONTRAT_NON_FIGE',
      'message', 'Le type de contrat de cette mission n''est pas encore figé (assignation incomplète ou MIXTE sans choix). Impossible de déclarer un paiement tant que type_contrat_applique = NULL.');
  END IF;

  SELECT * INTO v_soignant FROM soignants WHERE id = v_mission.soignant_assigne_id;
  SELECT * INTO v_etab FROM etablissements WHERE id = v_etab_id;

  SELECT EXISTS(
    SELECT 1 FROM stripe_connect_onboarding
    WHERE soignant_id = v_soignant.id AND charges_enabled = TRUE AND payouts_enabled = TRUE
  ) INTO v_stripe_actif;

  IF p_methode IS NOT NULL THEN
    IF p_methode NOT IN ('VIREMENT', 'CHEQUE', 'BULLETIN_PAIE', 'NOTE_HONORAIRES') THEN
      RETURN jsonb_build_object('error', 'METHODE_INVALIDE',
        'message', 'Méthode de paiement non autorisée. Valeurs acceptées : VIREMENT, CHEQUE, BULLETIN_PAIE, NOTE_HONORAIRES.');
    END IF;
    v_methode := p_methode;
  ELSIF v_mission.type_paiement_soignant = 'NOTE_HONORAIRES' THEN
    IF v_stripe_actif THEN
      RETURN jsonb_build_object('error', 'use_stripe_connect',
        'message', 'Ce soignant a un compte Stripe Connect actif. Utilisez le paiement Stripe.',
        'use_stripe_connect', TRUE);
    END IF;
    v_methode := 'NOTE_HONORAIRES';
  ELSE
    v_methode := 'VIREMENT';
  END IF;

  IF v_mission.type_contrat_applique = 'SALARIE' AND v_methode = 'NOTE_HONORAIRES' THEN
    RETURN jsonb_build_object('error', 'CONTRAT_SALARIE_METHODE_INCOMPATIBLE',
      'message', 'Les missions en contrat salarié (CDD) ne peuvent pas être payées par note d''honoraires. Utilisez VIREMENT ou BULLETIN_PAIE.');
  END IF;

  IF v_mission.type_contrat_applique = 'LIBERAL' AND v_methode = 'BULLETIN_PAIE' THEN
    RETURN jsonb_build_object('error', 'CONTRAT_LIBERAL_METHODE_INCOMPATIBLE',
      'message', 'Les missions en contrat libéral ne génèrent pas de bulletin de paie. Utilisez VIREMENT ou NOTE_HONORAIRES.');
  END IF;

  IF v_methode IN ('VIREMENT', 'CHEQUE', 'NOTE_HONORAIRES') THEN
    v_ref := TRIM(COALESCE(p_reference, ''));
    IF LENGTH(v_ref) < 5 THEN
      RETURN jsonb_build_object('error', 'La référence doit contenir au moins 5 caractères.');
    END IF;
    IF v_ref !~ '[0-9]' THEN
      RETURN jsonb_build_object('error', 'La référence doit contenir au moins un chiffre.');
    END IF;
  ELSE
    v_ref := TRIM(COALESCE(p_reference, ''));
  END IF;

  IF p_montant <= 0 THEN
    RETURN jsonb_build_object('error', 'Le montant doit être supérieur à 0.');
  END IF;

  IF p_date_paiement > CURRENT_DATE THEN
    RETURN jsonb_build_object('error', 'La date de paiement ne peut pas être dans le futur.');
  END IF;

  v_echeance := p_date_paiement + COALESCE(v_etab.delai_paiement_jours, 30);

  INSERT INTO paiements_soignant (
    mission_id, soignant_id, etablissement_id, montant_net, methode, reference_virement,
    date_paiement, confirme_par_etablissement, confirme_par_etablissement_le, statut, echeance_le
  ) VALUES (
    p_mission_id, v_mission.soignant_assigne_id, v_etab_id,
    p_montant, v_methode, v_ref, p_date_paiement, TRUE, NOW(), 'DECLARE', v_echeance
  ) RETURNING id INTO v_paiement_id;

  IF v_mission.net_a_payer IS NOT NULL AND v_mission.net_a_payer > 0 THEN
    v_ecart_pct := ABS(p_montant - v_mission.net_a_payer) / v_mission.net_a_payer * 100;
    IF v_ecart_pct > 10 THEN
      PERFORM fn_ecrire_audit_safe(
        auth.uid(),
        'ETABLISSEMENT',
        'PAIEMENT',
        'paiements_soignant',
        v_paiement_id,
        NULL,
        jsonb_build_object(
          'sous_action', 'PAIEMENT_MONTANT_ECART',
          'mission_id', p_mission_id,
          'mission_intitule', v_mission.intitule,
          'montant_declare', p_montant,
          'montant_attendu_net_a_payer', v_mission.net_a_payer,
          'ecart_pct', ROUND(v_ecart_pct, 2),
          'methode', v_methode,
          'type_contrat_applique', v_mission.type_contrat_applique
        ),
        NULL,
        NULL
      );
    END IF;
  END IF;

  INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (
    v_mission.soignant_assigne_id, 'SYSTEM', 'Paiement déclaré',
    'Paiement de ' || p_montant || ' € déclaré pour "' || COALESCE(v_mission.intitule, 'Mission') || '" (réf. ' || v_ref || ').',
    '/soignant/mes-gains', 'SOIGNANT'
  );

  PERFORM public.fn_ecrire_audit_safe(
    auth.uid(),
    'ETABLISSEMENT',
    'PAIEMENT_SOIGNANT_DECLARE_ETAB',
    'paiements_soignant',
    v_paiement_id,
    NULL,
    jsonb_build_object(
      'mission_id', p_mission_id,
      'mission_intitule', v_mission.intitule,
      'soignant_id', v_mission.soignant_assigne_id,
      'etablissement_id', v_etab_id,
      'montant_net', p_montant,
      'methode', v_methode,
      'reference_virement', v_ref,
      'date_paiement', p_date_paiement,
      'echeance_le', v_echeance,
      'type_contrat_applique', v_mission.type_contrat_applique,
      'attestation_sur_l_honneur', TRUE,
      'attestation_timestamp', NOW()
    ),
    NULL,
    NULL
  );

  RETURN jsonb_build_object(
    'success', TRUE,
    'paiement_id', v_paiement_id,
    'methode', v_methode,
    'echeance', v_echeance,
    'soignant_id', v_mission.soignant_assigne_id,
    'mission_intitule', v_mission.intitule
  );
END;
$$;


ALTER FUNCTION "public"."fn_declarer_paiement_soignant"("p_mission_id" "uuid", "p_montant" numeric, "p_methode" "text", "p_reference" "text", "p_date_paiement" "date", "p_attestation_sur_l_honneur" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_declarer_paiement_soignant"("p_mission_id" "uuid", "p_montant" numeric, "p_methode" "text", "p_reference" "text", "p_date_paiement" "date", "p_attestation_sur_l_honneur" boolean) IS 'Déclaration paiement soignant par l''étab (flow SALARIE + NOTE_HONORAIRES hors Connect). CP-C-1 : attestation sur l''honneur obligatoire + audit RGPD + enum méthode strict.';



CREATE OR REPLACE FUNCTION "public"."fn_declarer_virement"("p_facture_id" "uuid", "p_reference" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_facture RECORD;
BEGIN
    SELECT id, statut, etablissement_id INTO v_facture FROM factures WHERE id = p_facture_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Facture introuvable'); END IF;
    IF v_facture.etablissement_id != mon_etablissement_id() AND NOT est_admin() THEN
        RETURN jsonb_build_object('error', 'Non autorisé');
    END IF;
    IF v_facture.statut NOT IN ('EMISE', 'EN_RETARD') THEN
        RETURN jsonb_build_object('error', 'Statut incorrect : ' || v_facture.statut);
    END IF;
    IF p_reference IS NULL OR LENGTH(TRIM(p_reference)) < 3 THEN
        RETURN jsonb_build_object('error', 'Référence de virement requise.');
    END IF;
    UPDATE factures SET virement_reference = TRIM(p_reference), mode_paiement = 'VIREMENT',
        statut = 'VIREMENT_DECLARE', modifie_le = NOW() WHERE id = p_facture_id;
    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_declarer_virement"("p_facture_id" "uuid", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_definir_disponibilite"("p_jour" "date", "p_creneau" "text", "p_disponible" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM soignants s WHERE s.id = v_uid AND s.supprime_le IS NULL) THEN
    RETURN jsonb_build_object('error', 'Profil soignant introuvable');
  END IF;
  IF p_creneau NOT IN ('JOURNEE', 'MATIN', 'APRES_MIDI', 'NUIT') THEN
    RETURN jsonb_build_object('error', 'Créneau invalide');
  END IF;
  IF p_jour < CURRENT_DATE OR p_jour > CURRENT_DATE + 90 THEN
    RETURN jsonb_build_object('error', 'La disponibilité doit être entre aujourd''hui et J+90');
  END IF;

  IF p_disponible THEN
    INSERT INTO disponibilites_soignant (soignant_id, jour, creneau)
    VALUES (v_uid, p_jour, p_creneau)
    ON CONFLICT (soignant_id, jour, creneau) DO NOTHING;
  ELSE
    DELETE FROM disponibilites_soignant
    WHERE soignant_id = v_uid AND jour = p_jour AND creneau = p_creneau;
  END IF;

  RETURN jsonb_build_object('success', TRUE);
END;
$$;


ALTER FUNCTION "public"."fn_definir_disponibilite"("p_jour" "date", "p_creneau" "text", "p_disponible" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_definir_retrocession_mission"("p_mission_id" "uuid", "p_pct" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_m RECORD;
BEGIN
  SELECT * INTO v_m FROM missions WHERE id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF v_m.etablissement_id != mon_etablissement_id() AND NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Non autorisé');
  END IF;
  IF v_m.statut != 'OUVERTE' THEN
    RETURN jsonb_build_object('error', 'Modifiable uniquement sur une mission ouverte.');
  END IF;
  IF p_pct IS NULL OR p_pct <= 0 OR p_pct > 100 THEN
    RETURN jsonb_build_object('error', 'Pourcentage de rétrocession invalide (1-100).');
  END IF;
  UPDATE missions SET mode_remuneration = 'RETROCESSION', retrocession_pct = p_pct,
    type_contrat_recherche = 'LIBERAL', modifie_le = NOW()
   WHERE id = p_mission_id;
  RETURN jsonb_build_object('success', TRUE, 'retrocession_pct', p_pct);
END;
$$;


ALTER FUNCTION "public"."fn_definir_retrocession_mission"("p_mission_id" "uuid", "p_pct" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_demander_a_retravailler"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_s RECORD;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  SELECT prenom, nom, profession INTO v_s FROM soignants WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profil soignant introuvable'); END IF;

  -- Légitimité : au moins une mission TERMINEE ensemble (on redemande à
  -- travailler quelque part où on a déjà travaillé).
  IF NOT EXISTS (
    SELECT 1 FROM missions m
    WHERE m.etablissement_id = p_etablissement_id
      AND m.soignant_assigne_id = v_uid AND m.statut = 'TERMINEE'
  ) THEN
    RETURN jsonb_build_object('error', 'Disponible après une première mission terminée avec cet établissement.');
  END IF;

  IF fn_est_exclu(v_uid, p_etablissement_id) THEN
    RETURN jsonb_build_object('error', 'Demande impossible auprès de cet établissement.');
  END IF;

  -- Dédup 7 jours : une seule sollicitation par étab par semaine.
  IF EXISTS (
    SELECT 1 FROM notifications n
    WHERE n.destinataire_id = p_etablissement_id AND n.type = 'SYSTEM'
      AND n.lien = '/etablissement/soignants/' || v_uid
      AND n.titre LIKE '%veut retravailler%'
      AND n.cree_le > NOW() - INTERVAL '7 days'
  ) THEN
    RETURN jsonb_build_object('error', 'Demande déjà envoyée cette semaine — l''établissement a été prévenu.');
  END IF;

  INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (p_etablissement_id, 'SYSTEM',
    v_s.prenom || ' ' || v_s.nom || ' veut retravailler avec vous ⭐',
    'Vous avez déjà travaillé ensemble. Reproposez-lui une mission en 2 clics depuis son profil.',
    '/etablissement/soignants/' || v_uid, 'ETABLISSEMENT');

  RETURN jsonb_build_object('success', TRUE);
END;
$$;


ALTER FUNCTION "public"."fn_demander_a_retravailler"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_demander_confirmation_email_etab"("p_etablissement_id" "uuid", "p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_token text;
  v_expire timestamptz;
  v_etab RECORD;
BEGIN
  IF NOT est_admin() THEN
    IF mon_etablissement_id() IS NULL OR mon_etablissement_id() <> p_etablissement_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
    END IF;
  END IF;

  IF p_email IS NULL OR p_email !~ '^[^@]+@[^@]+\.[^@]+$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Adresse e-mail invalide');
  END IF;

  SELECT id, nom INTO v_etab FROM etablissements WHERE id = p_etablissement_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Établissement introuvable');
  END IF;

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  v_expire := now() + interval '24 hours';

  UPDATE etablissements SET
    email_contact = p_email,
    email_contact_token = v_token,
    email_contact_token_expire_le = v_expire,
    email_contact_verifie = false,
    email_contact_verifie_le = NULL
  WHERE id = p_etablissement_id;

  INSERT INTO email_queue (id, type, destinataire_email, data, statut, cree_le)
  VALUES (
    gen_random_uuid(),
    'CONFIRMATION_EMAIL_PRO_ETAB',
    p_email,
    jsonb_build_object(
      'etablissement_id', p_etablissement_id,
      'etablissement_nom', v_etab.nom,
      'token', v_token,
      'expire_le', v_expire
    ),
    'EN_ATTENTE',
    now()
  );

  RETURN jsonb_build_object('success', true, 'email', p_email, 'expire_le', v_expire);
END;
$_$;


ALTER FUNCTION "public"."fn_demander_confirmation_email_etab"("p_etablissement_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_demander_confirmations_presence"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m RECORD;
  v_nb int := 0;
  v_relances int := 0;
  v_alertes_etab int := 0;
  v_url text := 'https://flripxtsyegjshnhzjkz.supabase.co';
  v_token text;
  v_corps text;
  -- Lot 17 : fenêtres en configuration (défauts = anciennes valeurs en dur).
  v_j1_min int := GREATEST(1, fn_param_num('confirmation_j1_min_h', 12)::int);
  v_j1_max int := GREATEST(2, fn_param_num('confirmation_j1_max_h', 36)::int);
  v_relance_max int := GREATEST(3, fn_param_num('relance_presence_max_h', 12)::int);
  v_alerte_etab int := GREATEST(2, fn_param_num('alerte_etab_presence_h', 6)::int);
BEGIN
  BEGIN
    v_token := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
  EXCEPTION WHEN OTHERS THEN v_token := NULL; END;

  -- ① Demande J-1 (existant) — désormais avec PUSH NATIF (A4).
  FOR v_m IN
    SELECT m.id, m.intitule, m.debut_le, m.soignant_assigne_id
    FROM missions m
    WHERE m.statut = 'ASSIGNEE'
      AND m.soignant_assigne_id IS NOT NULL
      AND m.presence_confirmee_le IS NULL
      AND m.debut_le BETWEEN NOW() + make_interval(hours => v_j1_min) AND NOW() + make_interval(hours => v_j1_max)
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.destinataire_id = m.soignant_assigne_id AND n.type = 'RAPPEL_MISSION'
          AND n.lien = '/soignant/missions/' || m.id
          AND n.cree_le > NOW() - INTERVAL '20 hours')
  LOOP
    v_corps := '"' || fn_html_escape(v_m.intitule) || '" démarre le ' ||
      TO_CHAR(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24:MI') ||
      '. Confirme ta présence en 1 clic — l''établissement compte sur toi.';

    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (v_m.soignant_assigne_id, 'RAPPEL_MISSION', 'Ta mission demain — Je serai là ✓',
      v_corps, '/soignant/missions/' || v_m.id, 'SOIGNANT');

    IF v_token IS NOT NULL THEN
      BEGIN
        PERFORM net.http_post(
          url := v_url || '/functions/v1/send-push',
          headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token),
          body := jsonb_build_object(
            'destinataire_id', v_m.soignant_assigne_id, 'type_evenement', 'RAPPEL_MISSION',
            'titre', 'Ta mission demain — Je serai là ✓', 'corps', v_corps,
            'data', jsonb_build_object('mission_id', v_m.id, 'lien', '/soignant/missions/' || v_m.id)
          )
        );
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;

    v_nb := v_nb + 1;
  END LOOP;

  -- ② Relance H-12 → H-2 si toujours pas confirmée (A4).
  FOR v_m IN
    SELECT m.id, m.intitule, m.debut_le, m.soignant_assigne_id
    FROM missions m
    WHERE m.statut = 'ASSIGNEE'
      AND m.soignant_assigne_id IS NOT NULL
      AND m.presence_confirmee_le IS NULL
      AND m.debut_le BETWEEN NOW() + INTERVAL '2 hours' AND NOW() + make_interval(hours => v_relance_max)
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.destinataire_id = m.soignant_assigne_id AND n.type = 'RAPPEL_MISSION'
          AND n.lien = '/soignant/missions/' || m.id || '?relance=1'
          AND n.cree_le > NOW() - INTERVAL '10 hours')
  LOOP
    v_corps := 'Toujours partante pour "' || fn_html_escape(v_m.intitule) || '" (' ||
      TO_CHAR(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'HH24:MI') ||
      ') ? Confirme en 1 clic — sans nouvelle de ta part, l''établissement sera prévenu.';

    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (v_m.soignant_assigne_id, 'RAPPEL_MISSION', '⏰ Dernière ligne droite — confirme ta mission',
      v_corps, '/soignant/missions/' || v_m.id || '?relance=1', 'SOIGNANT');

    IF v_token IS NOT NULL THEN
      BEGIN
        PERFORM net.http_post(
          url := v_url || '/functions/v1/send-push',
          headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token),
          body := jsonb_build_object(
            'destinataire_id', v_m.soignant_assigne_id, 'type_evenement', 'RAPPEL_MISSION',
            'titre', '⏰ Dernière ligne droite — confirme ta mission', 'corps', v_corps,
            'data', jsonb_build_object('mission_id', v_m.id, 'lien', '/soignant/missions/' || v_m.id)
          )
        );
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;

    v_relances := v_relances + 1;
  END LOOP;

  -- ③ Alerte préventive ÉTABLISSEMENT à H-6 si toujours rien (A4).
  FOR v_m IN
    SELECT m.id, m.intitule, m.debut_le, m.etablissement_id
    FROM missions m
    WHERE m.statut = 'ASSIGNEE'
      AND m.soignant_assigne_id IS NOT NULL
      AND m.presence_confirmee_le IS NULL
      AND m.debut_le BETWEEN NOW() + INTERVAL '2 hours' AND NOW() + make_interval(hours => v_alerte_etab)
      AND NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.destinataire_id = m.etablissement_id AND n.type = 'SYSTEM'
          AND n.lien = '/etablissement/missions/' || m.id
          AND n.titre LIKE 'Présence non confirmée%'
          AND n.cree_le > NOW() - INTERVAL '10 hours')
  LOOP
    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (v_m.etablissement_id, 'SYSTEM', 'Présence non confirmée ⚠️',
      'Le soignant de "' || fn_html_escape(v_m.intitule) || '" (' ||
      TO_CHAR(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM HH24:MI') ||
      ') n''a pas confirmé sa présence malgré nos relances. En cas d''absence, un remplacement sera proposé en priorité aux candidats de la mission.',
      '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT');
    v_alertes_etab := v_alertes_etab + 1;
  END LOOP;

  RETURN jsonb_build_object('success', TRUE, 'demandes', v_nb, 'relances', v_relances, 'alertes_etab', v_alertes_etab);
END;
$$;


ALTER FUNCTION "public"."fn_demander_confirmations_presence"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_demander_revue_document"("p_document_id" "uuid", "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_doc public.documents_soignants%ROWTYPE;
  v_revue_id uuid;
  v_motif text := left(btrim(COALESCE(p_motif, '')), 1000);
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF length(v_motif) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MOTIF_INVALIDE');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('revue-document:' || p_document_id::text, 0));
  SELECT * INTO v_doc
  FROM public.documents_soignants
  WHERE id = p_document_id AND soignant_id = v_uid
    AND supprime_le IS NULL AND revoque_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DOCUMENT_INTROUVABLE');
  END IF;

  SELECT id INTO v_revue_id
  FROM public.file_revue_manuelle
  WHERE type_entite = 'TELEVERSEMENT_DOCUMENT'
    AND id_entite = p_document_id
    AND statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE')
  FOR UPDATE;
  IF v_revue_id IS NULL THEN
    INSERT INTO public.file_revue_manuelle (
      type_entite, id_entite, service_en_echec, motif_echec,
      donnees_originales, statut, priorite
    ) VALUES (
      'TELEVERSEMENT_DOCUMENT', p_document_id,
      'REVUE_DEMANDEE_PAR_SOIGNANT', v_motif,
      jsonb_build_object(
        'document_id', p_document_id,
        'soignant_id', v_uid,
        'type_document', v_doc.type_document::text,
        'ancien_statut', v_doc.statut_verification::text,
        'demande_le', now()
      ),
      'EN_ATTENTE', 3
    ) RETURNING id INTO v_revue_id;
  END IF;

  PERFORM set_config('jolene.document_server_update', 'true', true);
  UPDATE public.documents_soignants
  SET statut_verification = 'REVUE_MANUELLE_REQUISE',
      motif_rejet = 'Demande transmise — en attente d''attribution à un membre de l''équipe.',
      verifie_par = NULL,
      verifie_le = NULL,
      verification_attempt_id = NULL,
      modifie_le = now()
  WHERE id = p_document_id;
  PERFORM set_config('jolene.document_server_update', '', true);

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'SOIGNANT',
    p_action := 'VERIFICATION_DOCUMENT',
    p_type_ressource := 'document_soignant',
    p_id_ressource := p_document_id,
    p_details := jsonb_build_object(
      'sous_action', 'REVUE_MANUELLE_DEMANDEE',
      'revue_id', v_revue_id
    )
  );
  RETURN jsonb_build_object(
    'success', true,
    'revue_id', v_revue_id,
    'message', 'Demande transmise — en attente d''attribution.'
  );
END;
$$;


ALTER FUNCTION "public"."fn_demander_revue_document"("p_document_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_deposer_chorus"("p_facture_id" "uuid", "p_chorus_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_facture RECORD;
BEGIN
    SELECT * INTO v_facture FROM factures WHERE id = p_facture_id;
    IF v_facture IS NULL THEN RETURN '{"error":"Facture introuvable"}'::JSONB; END IF;
    IF v_facture.etablissement_id != mon_etablissement_id() AND NOT est_admin() THEN
        RETURN '{"error":"Accès refusé"}'::JSONB;
    END IF;

    UPDATE factures SET
        chorus_pro_statut = 'DEPOSEE',
        chorus_pro_deposee_le = NOW(),
        chorus_pro_id = p_chorus_id
    WHERE id = p_facture_id;

    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_deposer_chorus"("p_facture_id" "uuid", "p_chorus_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_desactiver_mon_token_push"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_token text := trim(COALESCE(p_token, ''));
  v_endpoint text;
  v_count integer := 0;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifie');
  END IF;
  IF length(v_token) < 16 OR length(v_token) > 4096 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Token push invalide');
  END IF;

  -- JSON.stringify(PushSubscription) est normalement stable. L'endpoint sert
  -- de repli pour les navigateurs qui reordonnent les cles JSON entre deux
  -- lectures, toujours dans le perimetre strict auth.uid().
  IF left(v_token, 1) = '{' THEN
    BEGIN
      v_endpoint := NULLIF(trim((v_token::jsonb) ->> 'endpoint'), '');
    EXCEPTION WHEN OTHERS THEN
      v_endpoint := NULL;
    END;
  END IF;

  UPDATE public.tokens_push
  SET actif = false,
      derniere_utilisation = now()
  WHERE utilisateur_id = v_uid
    AND (
      token = v_token
      OR (v_endpoint IS NOT NULL AND endpoint = v_endpoint)
    );
  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'tokens_desactives', v_count,
    'scope', 'CURRENT_DEVICE'
  );
END;
$$;


ALTER FUNCTION "public"."fn_desactiver_mon_token_push"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_detail_facture"("p_facture_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_facture RECORD;
    v_missions JSONB;
BEGIN
    IF v_etab_id IS NULL AND NOT est_admin() THEN
        RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    SELECT * INTO v_facture FROM factures WHERE id = p_facture_id;
    IF v_facture IS NULL THEN RETURN jsonb_build_object('error', 'Facture introuvable'); END IF;
    IF v_facture.etablissement_id != v_etab_id AND NOT est_admin() THEN
        RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    -- PRIORITÉ 1 : missions liées par facture_id
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id', m.id,
            'intitule', m.intitule,
            'service', m.service,
            'debut_le', m.debut_le,
            'fin_le', m.fin_le,
            'duree_heures', m.duree_heures,
            'taux_horaire_base', m.taux_horaire_base,
            'total_brut', m.total_brut,
            'montant_majoration_nuit', COALESCE(m.montant_majoration_nuit, 0),
            'montant_majoration_dimanche', COALESCE(m.montant_majoration_dimanche, 0),
            'montant_majoration_ferie', COALESCE(m.montant_majoration_ferie, 0),
            'taux_ifm', COALESCE(m.taux_ifm, 0),
            'montant_ifm', COALESCE(m.montant_ifm, 0),
            'taux_icp', COALESCE(m.taux_icp, 0),
            'montant_icp', COALESCE(m.montant_icp, 0),
            'taux_commission', m.taux_commission,
            'montant_commission_ht', m.montant_commission_ht,
            'montant_commission_tva', m.montant_commission_tva,
            'montant_commission_ttc', m.montant_commission_ttc,
            'soignant_nom', COALESCE(s.prenom || ' ' || s.nom, ''),
            'profession', m.profession_requise::TEXT,
            'presences', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                    'id', p.id,
                    'pointage_arrivee_le', p.pointage_arrivee_le,
                    'pointage_depart_le', p.pointage_depart_le,
                    'methode_pointage_arrivee', p.methode_pointage_arrivee,
                    'methode_pointage_depart', p.methode_pointage_depart,
                    'heures_reelles', p.heures_reelles,
                    'duree_brute_min', p.duree_brute_min,
                    'duree_nette_min', p.duree_nette_min,
                    'duree_pause_min', p.duree_pause_min,
                    'retard_min', p.retard_min,
                    'depart_anticipe_min', p.depart_anticipe_min,
                    'perimetre_gps_valide', p.perimetre_gps_valide,
                    'alerte_teleportation', p.alerte_teleportation,
                    'valide_par_etablissement', p.valide_par_etablissement
                ) ORDER BY p.pointage_arrivee_le)
                FROM presences p
                WHERE p.mission_id = m.id
            ), '[]'::JSONB)
        ) ORDER BY m.debut_le
    ), '[]'::JSONB)
    INTO v_missions
    FROM missions m
    LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
    WHERE m.facture_id = p_facture_id;

    -- PRIORITÉ 2 : si aucune mission liée par FK, chercher par période
    IF v_missions = '[]'::JSONB AND v_facture.periode_debut IS NOT NULL THEN
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', m.id,
                'intitule', m.intitule,
                'service', m.service,
                'debut_le', m.debut_le,
                'fin_le', m.fin_le,
                'duree_heures', m.duree_heures,
                'taux_horaire_base', m.taux_horaire_base,
                'total_brut', m.total_brut,
                'montant_majoration_nuit', COALESCE(m.montant_majoration_nuit, 0),
                'montant_majoration_dimanche', COALESCE(m.montant_majoration_dimanche, 0),
                'montant_majoration_ferie', COALESCE(m.montant_majoration_ferie, 0),
                'taux_ifm', COALESCE(m.taux_ifm, 0),
                'montant_ifm', COALESCE(m.montant_ifm, 0),
                'taux_icp', COALESCE(m.taux_icp, 0),
                'montant_icp', COALESCE(m.montant_icp, 0),
                'taux_commission', m.taux_commission,
                'montant_commission_ht', m.montant_commission_ht,
                'montant_commission_tva', m.montant_commission_tva,
                'montant_commission_ttc', m.montant_commission_ttc,
                'soignant_nom', COALESCE(s.prenom || ' ' || s.nom, ''),
                'profession', m.profession_requise::TEXT,
                'presences', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'id', p.id,
                        'pointage_arrivee_le', p.pointage_arrivee_le,
                        'pointage_depart_le', p.pointage_depart_le,
                        'methode_pointage_arrivee', p.methode_pointage_arrivee,
                        'methode_pointage_depart', p.methode_pointage_depart,
                        'heures_reelles', p.heures_reelles,
                        'duree_brute_min', p.duree_brute_min,
                        'duree_nette_min', p.duree_nette_min,
                        'duree_pause_min', p.duree_pause_min,
                        'retard_min', p.retard_min,
                        'depart_anticipe_min', p.depart_anticipe_min,
                        'perimetre_gps_valide', p.perimetre_gps_valide,
                        'alerte_teleportation', p.alerte_teleportation,
                        'valide_par_etablissement', p.valide_par_etablissement
                    ) ORDER BY p.pointage_arrivee_le)
                    FROM presences p
                    WHERE p.mission_id = m.id
                ), '[]'::JSONB)
            ) ORDER BY m.debut_le
        ), '[]'::JSONB)
        INTO v_missions
        FROM missions m
        LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
        WHERE m.etablissement_id = v_facture.etablissement_id
        AND m.statut = 'TERMINEE' AND m.commission_facturee = TRUE
        AND m.debut_le >= v_facture.periode_debut::TIMESTAMP
        AND m.debut_le < (v_facture.periode_fin + 1)::TIMESTAMP;
    END IF;

    -- PRIORITÉ 3 : mission unique si facture a mission_id
    IF v_missions = '[]'::JSONB AND v_facture.mission_id IS NOT NULL THEN
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', m.id,
                'intitule', m.intitule,
                'service', m.service,
                'debut_le', m.debut_le,
                'fin_le', m.fin_le,
                'duree_heures', m.duree_heures,
                'taux_horaire_base', m.taux_horaire_base,
                'total_brut', m.total_brut,
                'montant_majoration_nuit', COALESCE(m.montant_majoration_nuit, 0),
                'montant_majoration_dimanche', COALESCE(m.montant_majoration_dimanche, 0),
                'montant_majoration_ferie', COALESCE(m.montant_majoration_ferie, 0),
                'taux_ifm', COALESCE(m.taux_ifm, 0),
                'montant_ifm', COALESCE(m.montant_ifm, 0),
                'taux_icp', COALESCE(m.taux_icp, 0),
                'montant_icp', COALESCE(m.montant_icp, 0),
                'taux_commission', m.taux_commission,
                'montant_commission_ht', m.montant_commission_ht,
                'montant_commission_tva', m.montant_commission_tva,
                'montant_commission_ttc', m.montant_commission_ttc,
                'soignant_nom', COALESCE(s.prenom || ' ' || s.nom, ''),
                'profession', m.profession_requise::TEXT,
                'presences', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'id', p.id,
                        'pointage_arrivee_le', p.pointage_arrivee_le,
                        'pointage_depart_le', p.pointage_depart_le,
                        'methode_pointage_arrivee', p.methode_pointage_arrivee,
                        'methode_pointage_depart', p.methode_pointage_depart,
                        'heures_reelles', p.heures_reelles,
                        'duree_brute_min', p.duree_brute_min,
                        'duree_nette_min', p.duree_nette_min,
                        'duree_pause_min', p.duree_pause_min,
                        'retard_min', p.retard_min,
                        'depart_anticipe_min', p.depart_anticipe_min,
                        'perimetre_gps_valide', p.perimetre_gps_valide,
                        'alerte_teleportation', p.alerte_teleportation,
                        'valide_par_etablissement', p.valide_par_etablissement
                    ) ORDER BY p.pointage_arrivee_le)
                    FROM presences p
                    WHERE p.mission_id = m.id
                ), '[]'::JSONB)
            )
        ), '[]'::JSONB)
        INTO v_missions
        FROM missions m
        LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
        WHERE m.id = v_facture.mission_id;
    END IF;

    RETURN jsonb_build_object(
        'facture', jsonb_build_object(
            'id', v_facture.id, 'numero_facture', v_facture.numero_facture,
            'statut', v_facture.statut, 'montant_ht', v_facture.montant_ht,
            'taux_tva', v_facture.taux_tva, 'montant_tva', v_facture.montant_tva,
            'montant_ttc', v_facture.montant_ttc, 'nombre_missions', v_facture.nombre_missions,
            'mode_paiement', v_facture.mode_paiement,
            'periode_debut', v_facture.periode_debut, 'periode_fin', v_facture.periode_fin,
            'date_emission', v_facture.date_emission, 'date_echeance', v_facture.date_echeance,
            'date_paiement', v_facture.date_paiement
        ),
        'missions', v_missions
    );
END;
$$;


ALTER FUNCTION "public"."fn_detail_facture"("p_facture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_detecter_noshow_et_remplacer"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m record;
  v_escrow public.paiements_escrow%ROWTYPE;
  v_remplacement_id uuid;
  v_traites integer := 0;
  v_remplacements integer := 0;
  v_url text := 'https://flripxtsyegjshnhzjkz.supabase.co';
  v_token text;
  v_s uuid;
  v_corps text;
  v_rows integer;
  v_constraint text;
  v_admin uuid;
  v_blocage_publication jsonb;
  v_refund_result jsonb;
  v_finance_en_revue boolean;
BEGIN
  BEGIN
    v_token := (
      SELECT decrypted_secret FROM vault.decrypted_secrets
       WHERE name = 'service_role_key' LIMIT 1
    );
  EXCEPTION WHEN OTHERS THEN v_token := NULL;
  END;

  FOR v_m IN
    SELECT m.*, e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng,
           e.adresse_ville AS etab_ville
      FROM public.missions m
      JOIN public.etablissements e ON e.id = m.etablissement_id
     WHERE m.statut IN ('ASSIGNEE', 'EN_COURS')
       AND m.soignant_assigne_id IS NOT NULL
       AND COALESCE(m.est_arret_maladie, false) = false
       AND m.debut_le < now() - interval '30 minutes'
       AND m.debut_le > now() - interval '4 hours'
       AND m.fin_le > now() + interval '1 hour'
       AND NOT EXISTS (
         SELECT 1 FROM public.presences p
          WHERE p.mission_id = m.id AND p.soignant_id = m.soignant_assigne_id
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.missions r WHERE r.remplacement_de_mission_id = m.id
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.notifications n
          WHERE n.destinataire_id = m.etablissement_id AND n.type = 'SYSTEM'
            AND n.lien = '/etablissement/missions/' || m.id
            AND n.titre LIKE 'Aucun pointage%'
            AND n.cree_le > now() - interval '6 hours'
       )
     ORDER BY m.id
     FOR UPDATE OF m SKIP LOCKED
  LOOP
    v_remplacement_id := NULL;
    v_escrow := NULL;
    v_blocage_publication := NULL;
    v_refund_result := NULL;
    v_finance_en_revue := false;

    -- Ces contrôles utilisent un nouveau snapshot après l'acquisition du
    -- verrou et couvrent les écritures concurrentes de présence/EPI/remplacement.
    IF COALESCE(v_m.est_arret_maladie, false)
       OR v_m.statut NOT IN ('ASSIGNEE', 'EN_COURS')
       OR EXISTS (
         SELECT 1 FROM public.presences p
          WHERE p.mission_id = v_m.id
            AND p.soignant_id = v_m.soignant_assigne_id
       )
       OR EXISTS (
         SELECT 1 FROM public.missions r
          WHERE r.remplacement_de_mission_id = v_m.id
       ) THEN
      CONTINUE;
    END IF;

    IF COALESCE(v_m.garantie_remplacement, false) THEN
      BEGIN
      -- Le verrou mission est déjà détenu. Verrouiller ensuite l'escrow dans
      -- le même ordre que les RPC de débit empêche un nouveau claim concurrent.
      -- Un débit certain est remboursé avec reverse_transfer ; un appel Stripe
      -- déjà ambigu reste gelé pour rapprochement humain, jamais silencieux.
      SELECT pe.*
        INTO v_escrow
        FROM public.paiements_escrow pe
       WHERE pe.mission_id = v_m.id
       ORDER BY pe.cree_le DESC
       LIMIT 1
       FOR UPDATE;

      IF FOUND THEN
        IF v_escrow.statut = 'INITIE'
           AND v_escrow.stripe_payment_intent_id IS NULL
           AND v_escrow.stripe_charge_id IS NULL
           AND v_escrow.stripe_payout_id IS NULL
           AND COALESCE(v_escrow.tentatives_debit, 0) = 0 THEN
          UPDATE public.paiements_escrow
             SET statut = 'REMBOURSE',
                 erreur = 'No-show avant débit Stripe',
                 modifie_le = now()
           WHERE id = v_escrow.id
             AND statut = 'INITIE'
             AND stripe_payment_intent_id IS NULL
             AND stripe_charge_id IS NULL
             AND stripe_payout_id IS NULL
             AND COALESCE(tentatives_debit, 0) = 0;
          GET DIAGNOSTICS v_rows = ROW_COUNT;
          IF v_rows <> 1 THEN
            RAISE EXCEPTION 'Neutralisation escrow no-show concurrente refusée.'
              USING ERRCODE = 'P0001';
          END IF;
          UPDATE public.escrow_exposition_releases
             SET statut = 'REGLE'
           WHERE paiement_escrow_id = v_escrow.id AND statut = 'ACTIF';
          UPDATE public.escrow_release_queue
             SET statut = 'ECHEC',
                 erreur = 'Mission classée no-show avant débit',
                 traite_le = now()
           WHERE paiement_escrow_id = v_escrow.id
             AND statut IN ('EN_ATTENTE', 'EN_COURS');
          INSERT INTO public.journaux_audit (
            acteur_id, type_acteur, action, type_ressource, id_ressource,
            details, navigateur_acteur
          ) VALUES (
            '00000000-0000-0000-0000-000000000000'::uuid,
            'SYSTEME', 'ADMIN_ACTION', 'paiement_escrow', v_escrow.id,
            jsonb_build_object(
              'evenement', 'ESCROW_ANNULE_NO_SHOW_AVANT_DEBIT',
              'mission_id', v_m.id
            ),
            'fn_detecter_noshow_et_remplacer'
          );
        ELSIF v_escrow.statut IN ('DEBITE', 'DISPONIBLE') THEN
          v_refund_result := public.fn_escrow_rembourser(
            v_escrow.id,
            v_escrow.honoraires_cents,
            true,
            'No-show constaté avant remplacement garanti'
          );
          IF COALESCE((v_refund_result->>'success')::boolean, false) IS NOT TRUE THEN
            RAISE EXCEPTION 'Remboursement escrow no-show impossible: %',
              v_refund_result USING ERRCODE = 'P0001';
          END IF;
        ELSIF v_escrow.statut NOT IN (
          'REMBOURSE_EN_COURS', 'REMBOURSE', 'ECHOUE'
        ) THEN
          v_finance_en_revue := true;
        END IF;
      END IF;

      IF EXISTS (
        SELECT 1 FROM public.stripe_transfers st
        WHERE st.mission_id = v_m.id
          AND st.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
      ) OR EXISTS (
        SELECT 1 FROM public.paiements_soignant ps
        WHERE ps.mission_id = v_m.id
      ) OR EXISTS (
        SELECT 1 FROM public.factures_honoraires fh
        WHERE fh.mission_id = v_m.id
          AND fh.statut NOT IN ('ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION')
      ) THEN
        v_finance_en_revue := true;
      END IF;

      IF v_finance_en_revue THEN
        INSERT INTO public.journaux_audit (
          acteur_id, type_acteur, action, type_ressource, id_ressource,
          details, navigateur_acteur
        ) VALUES (
          '00000000-0000-0000-0000-000000000000'::uuid,
          'SYSTEME', 'ADMIN_ACTION', 'mission', v_m.id,
          jsonb_build_object(
            'evenement', 'NO_SHOW_RAPPROCHEMENT_FINANCIER_REQUIS',
            'paiement_escrow_id', v_escrow.id,
            'escrow_statut', v_escrow.statut
          ),
          'fn_detecter_noshow_et_remplacer'
        );
      END IF;

      -- Le cron est exécuté avec service_role, que le trigger onboarding laisse
      -- volontairement passer. La vérification explicite est donc obligatoire.
      v_blocage_publication := public.fn_blocage_publication_etab(
        v_m.etablissement_id
      );

      IF v_blocage_publication IS NOT NULL OR v_finance_en_revue THEN
        UPDATE public.missions m
           SET statut = 'ABSENCE',
               absence_sans_prevenir = true,
               modifie_le = now()
         WHERE m.id = v_m.id
           AND m.statut = v_m.statut
           AND m.soignant_assigne_id = v_m.soignant_assigne_id
           AND COALESCE(m.est_arret_maladie, false) = false
           AND m.debut_le < now() - interval '30 minutes'
           AND m.debut_le > now() - interval '4 hours'
           AND m.fin_le > now() + interval '1 hour'
           AND NOT EXISTS (
             SELECT 1 FROM public.presences p
              WHERE p.mission_id = m.id
                AND p.soignant_id = m.soignant_assigne_id
           )
           AND NOT EXISTS (
             SELECT 1 FROM public.missions r
              WHERE r.remplacement_de_mission_id = m.id
           );
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows <> 1 THEN
          RAISE EXCEPTION 'Classification no-show concurrente refusée.'
            USING ERRCODE = 'P0004';
        END IF;

        v_traites := v_traites + 1;
        IF v_blocage_publication IS NOT NULL THEN
          FOR v_admin IN
            SELECT ea.user_id FROM public.equipe_admin ea
            WHERE ea.actif AND ea.user_id IS NOT NULL
          LOOP
            INSERT INTO public.notifications (
              destinataire_id, type_destinataire, type, titre, corps, lien,
              type_ressource, id_ressource
            ) VALUES (
              v_admin, 'ADMIN', 'SYSTEM',
              'No-show — remplacement à traiter manuellement ⚠️',
              'Le no-show est enregistré mais la publication automatique est bloquée : '
                || COALESCE(
                  v_blocage_publication->>'message',
                  v_blocage_publication->>'error', 'gate établissement'
                ) || '.',
              '/admin/missions', 'mission', v_m.id
            );
          END LOOP;
        END IF;
        IF v_finance_en_revue THEN
          FOR v_admin IN
            SELECT ea.user_id FROM public.equipe_admin ea
            WHERE ea.actif AND ea.user_id IS NOT NULL
          LOOP
            INSERT INTO public.notifications (
              destinataire_id, type_destinataire, type, titre, corps, lien,
              type_ressource, id_ressource
            ) VALUES (
              v_admin, 'ADMIN', 'SYSTEM',
              'No-show — rapprochement financier requis ⚠️',
              'Le no-show est enregistré, mais le rail financier de la mission originale doit être rapproché avant tout remplacement. Escrow : '
                || COALESCE(v_escrow.statut, 'artefact financier externe') || '.',
              '/admin/finances', 'mission', v_m.id
            );
          END LOOP;
        END IF;
        INSERT INTO public.notifications (
          destinataire_id, type, titre, corps, lien, type_destinataire
        ) VALUES (
          v_m.etablissement_id, 'SYSTEM',
          'Aucun pointage — remplacement en revue ⚠️',
          'Aucun pointage détecté 30 min après le début de « '
            || public.fn_html_escape(v_m.intitule)
            || ' ». Le no-show est enregistré ; la publication automatique du remplacement est suspendue '
            || CASE
                 WHEN v_blocage_publication IS NOT NULL AND v_finance_en_revue
                   THEN 'par un contrôle de conformité et un rapprochement financier.'
                 WHEN v_blocage_publication IS NOT NULL
                   THEN 'par un contrôle de conformité.'
                 ELSE 'dans l’attente du rapprochement financier.'
               END
            || ' L’équipe admin est alertée.',
          '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT'
        );
      ELSE
      -- Le sous-bloc est un sous-transaction : si l'index unique arbitre une
      -- course, le passage temporaire à ABSENCE est lui aussi annulé.
      BEGIN
        UPDATE public.missions m
           SET statut = 'ABSENCE',
               absence_sans_prevenir = true,
               modifie_le = now()
         WHERE m.id = v_m.id
           AND m.statut = v_m.statut
           AND m.soignant_assigne_id = v_m.soignant_assigne_id
           AND COALESCE(m.est_arret_maladie, false) = false
           AND m.debut_le < now() - interval '30 minutes'
           AND m.debut_le > now() - interval '4 hours'
           AND m.fin_le > now() + interval '1 hour'
           AND NOT EXISTS (
             SELECT 1 FROM public.presences p
              WHERE p.mission_id = m.id
                AND p.soignant_id = m.soignant_assigne_id
           )
           AND NOT EXISTS (
             SELECT 1 FROM public.missions r
              WHERE r.remplacement_de_mission_id = m.id
           );
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows <> 1 THEN
          RAISE EXCEPTION 'Classification no-show concurrente refusée.'
            USING ERRCODE = 'P0004';
        END IF;

        INSERT INTO public.missions(
          etablissement_id, intitule, description, service,
          profession_requise, specialite_medicale_requise, accepte_non_specialises,
          debut_le, fin_le, duree_heures, taux_horaire_base,
          type_contrat_recherche, mode_remuneration, retrocession_pct,
          mission_source, statut, mode_attribution,
          est_urgente, niveau_urgence, garantie_remplacement,
          remplacement_de_mission_id
        ) VALUES (
          v_m.etablissement_id,
          'REMPLACEMENT URGENT — ' || v_m.intitule,
          COALESCE(v_m.description, '') || E'\n\n[Mission de remplacement générée automatiquement — garantie Jolene]',
          v_m.service,
          v_m.profession_requise, v_m.specialite_medicale_requise,
          v_m.accepte_non_specialises,
          greatest(v_m.debut_le, now() + interval '15 minutes'), v_m.fin_le,
          round(extract(epoch FROM (
            v_m.fin_le - greatest(v_m.debut_le, now() + interval '15 minutes')
          )) / 3600.0, 2),
          v_m.taux_horaire_base, v_m.type_contrat_recherche,
          v_m.mode_remuneration, v_m.retrocession_pct,
          'REMPLACEMENT', 'OUVERTE', 'PREMIER_ARRIVE',
          true, 3, true, v_m.id
        ) RETURNING id INTO v_remplacement_id;
      EXCEPTION WHEN unique_violation THEN
        GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
        IF v_constraint = 'uniq_missions_remplacement_direct'
           AND EXISTS (
             SELECT 1 FROM public.missions r
              WHERE r.remplacement_de_mission_id = v_m.id
           ) THEN
          RAISE EXCEPTION 'Remplacement no-show concurrent déjà publié.'
            USING ERRCODE = 'P0004';
        END IF;
        RAISE;
      END;

      v_traites := v_traites + 1;
      v_remplacements := v_remplacements + 1;
      v_corps := public.fn_html_escape(v_m.intitule) || ' — ' ||
        COALESCE(v_m.etab_ville, '') || ', MAINTENANT à ' ||
        COALESCE(v_m.taux_horaire_base::text, '?') || ' €/h. Acceptez en 1 clic.';

      -- Les anciens candidats restent prioritaires, mais sont revalidés sur
      -- la profession et le contrat de la nouvelle mission.
      FOR v_s IN
        SELECT c.soignant_id
          FROM public.candidatures c
         WHERE c.mission_id = v_m.id
           AND c.soignant_id IS NOT NULL
           AND c.soignant_id <> v_m.soignant_assigne_id
           AND c.statut::text NOT IN ('ACCEPTEE', 'RETIREE', 'ANNULEE')
           AND public.fn_soignant_eligible_mission(c.soignant_id, v_remplacement_id, true)
           AND NOT public.fn_est_exclu(c.soignant_id, v_m.etablissement_id)
      LOOP
        INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (
          v_s, 'POOL_URGENCE',
          '🎯 Une mission où tu avais postulé se libère — priorité à toi',
          v_corps, '/soignant/missions/' || v_remplacement_id, 'SOIGNANT'
        );
        IF v_token IS NOT NULL THEN
          BEGIN
            PERFORM net.http_post(
              url := v_url || '/functions/v1/send-push',
              headers := jsonb_build_object(
                'Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token
              ),
              body := jsonb_build_object(
                'destinataire_id', v_s, 'type_evenement', 'MISSION_URGENTE',
                'titre', '🎯 Une mission où tu avais postulé se libère',
                'corps', v_corps,
                'data', jsonb_build_object(
                  'mission_id', v_remplacement_id,
                  'lien', '/soignant/missions/' || v_remplacement_id
                )
              )
            );
          EXCEPTION WHEN OTHERS THEN NULL;
          END;
        END IF;
      END LOOP;

      -- Élargissement aux profils hors pool : la compatibilité hiérarchique et
      -- les documents sont ceux de la mission de remplacement.
      FOR v_s IN
        SELECT s.id
          FROM public.soignants s
         WHERE public.fn_soignant_eligible_mission(s.id, v_remplacement_id, true)
           AND COALESCE(s.statut_compte::text, 'ACTIF') = 'ACTIF'
           AND COALESCE(s.disponible_urgence, false) = false
           AND NOT public.fn_est_exclu(s.id, v_m.etablissement_id)
           AND s.id <> v_m.soignant_assigne_id
           AND NOT EXISTS (
             SELECT 1 FROM public.candidatures cb
              WHERE cb.mission_id = v_m.id AND cb.soignant_id = s.id
                AND cb.statut::text NOT IN ('ACCEPTEE', 'RETIREE', 'ANNULEE')
           )
           AND (
             s.adresse_lat IS NULL OR v_m.etab_lat IS NULL
             OR public.fn_haversine_distance_m(
               s.adresse_lat, s.adresse_lng, v_m.etab_lat, v_m.etab_lng
             ) <= COALESCE(s.rayon_deplacement_km, 50) * 1000
           )
         LIMIT 200
      LOOP
        INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (
          v_s, 'POOL_URGENCE',
          '🚨 Remplacement immédiat — premier arrivé, premier servi',
          v_corps, '/soignant/missions/' || v_remplacement_id, 'SOIGNANT'
        );
        IF v_token IS NOT NULL THEN
          BEGIN
            PERFORM net.http_post(
              url := v_url || '/functions/v1/send-push',
              headers := jsonb_build_object(
                'Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token
              ),
              body := jsonb_build_object(
                'destinataire_id', v_s, 'type_evenement', 'MISSION_URGENTE',
                'titre', '🚨 Remplacement immédiat près de chez vous',
                'corps', v_corps,
                'data', jsonb_build_object(
                  'mission_id', v_remplacement_id, 'lien', '/soignant/pool-urgence'
                )
              )
            );
          EXCEPTION WHEN OTHERS THEN NULL;
          END;
        END IF;
      END LOOP;

      INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
      VALUES (
        v_m.etablissement_id, 'SYSTEM', 'Aucun pointage — remplacement lancé 🚨',
        'Aucun pointage détecté 30 min après le début de « ' ||
          public.fn_html_escape(v_m.intitule) ||
          ' ». Garantie remplacement activée : une mission urgente vient d’être diffusée.',
        '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT'
      );
      END IF;
      EXCEPTION WHEN SQLSTATE 'P0004' THEN
        -- Le sous-bloc annule aussi toute neutralisation/refund préparé avant
        -- que le CAS ne découvre une présence ou une mutation concurrente.
        CONTINUE;
      END;
    ELSE
      v_traites := v_traites + 1;
      INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
      VALUES (
        v_m.etablissement_id, 'SYSTEM', 'Aucun pointage détecté ⚠️',
        'Aucun pointage 30 min après le début de « ' ||
          public.fn_html_escape(v_m.intitule) ||
          ' ». Contactez le soignant ou alertez le pool d’urgence depuis la mission.',
        '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT'
      );
    END IF;

    INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (
      v_m.soignant_assigne_id, 'SYSTEM', 'Aucun pointage détecté sur votre mission',
      'Votre mission « ' || public.fn_html_escape(v_m.intitule) ||
        ' » a démarré il y a 30 min sans pointage. Pointez immédiatement ou contactez l’établissement.',
      '/soignant/presences', 'SOIGNANT'
    );
  END LOOP;

  RETURN jsonb_build_object(
    'success', true, 'detectes', v_traites, 'remplacements', v_remplacements
  );
END;
$$;


ALTER FUNCTION "public"."fn_detecter_noshow_et_remplacer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_detecter_teleportation"("p_soignant_id" "uuid", "p_lat" numeric, "p_lng" numeric, "p_horodatage" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_precedent RECORD;
    v_distance_km NUMERIC;
    v_duree_heures NUMERIC;
    v_vitesse_kmh NUMERIC;
    v_vitesse_max CONSTANT NUMERIC := 200.0;
    v_resultat JSONB := '{"suspect": false}'::JSONB;
BEGIN
    SELECT
        COALESCE(p.pointage_depart_le, p.pointage_arrivee_le) AS dernier_horodatage,
        COALESCE(p.depart_lat, p.arrivee_lat) AS derniere_lat,
        COALESCE(p.depart_lng, p.arrivee_lng) AS derniere_lng,
        p.mission_id
    INTO v_precedent
    FROM presences p
    WHERE p.soignant_id = p_soignant_id
      AND COALESCE(p.pointage_depart_le, p.pointage_arrivee_le) IS NOT NULL
      AND COALESCE(p.pointage_depart_le, p.pointage_arrivee_le) < p_horodatage
    ORDER BY COALESCE(p.pointage_depart_le, p.pointage_arrivee_le) DESC
    LIMIT 1;

    IF v_precedent IS NULL OR v_precedent.derniere_lat IS NULL THEN
        RETURN v_resultat;
    END IF;

    -- Distance Haversine (km)
    v_distance_km := 6371 * acos(
        LEAST(1.0,
            cos(radians(v_precedent.derniere_lat)) * cos(radians(p_lat))
            * cos(radians(p_lng) - radians(v_precedent.derniere_lng))
            + sin(radians(v_precedent.derniere_lat)) * sin(radians(p_lat))
        )
    );

    v_duree_heures := EXTRACT(EPOCH FROM (p_horodatage - v_precedent.dernier_horodatage)) / 3600.0;
    IF v_duree_heures < 0.001 THEN v_duree_heures := 0.001; END IF;

    v_vitesse_kmh := v_distance_km / v_duree_heures;

    IF v_vitesse_kmh > v_vitesse_max AND v_distance_km > 5.0 THEN
        v_resultat := jsonb_build_object(
            'suspect', TRUE,
            'type_alerte', 'TELEPORTATION',
            'distance_km', ROUND(v_distance_km, 2),
            'duree_heures', ROUND(v_duree_heures, 4),
            'vitesse_implicite_kmh', ROUND(v_vitesse_kmh, 1),
            'vitesse_max_autorisee_kmh', v_vitesse_max,
            'position_precedente', jsonb_build_object(
                'lat', v_precedent.derniere_lat,
                'lng', v_precedent.derniere_lng,
                'horodatage', v_precedent.dernier_horodatage,
                'mission_id', v_precedent.mission_id
            ),
            'position_actuelle', jsonb_build_object(
                'lat', p_lat, 'lng', p_lng, 'horodatage', p_horodatage
            )
        );
    END IF;

    RETURN v_resultat;
END;
$$;


ALTER FUNCTION "public"."fn_detecter_teleportation"("p_soignant_id" "uuid", "p_lat" numeric, "p_lng" numeric, "p_horodatage" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_detecter_teleportations"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_alertes_count int := 0;
  v_rec RECORD;
  v_vitesse jsonb;
  v_admin_ids uuid[];
  v_soignants_affectes uuid[] := ARRAY[]::uuid[];
  v_sid uuid;
BEGIN
  FOR v_rec IN
    WITH pointages_recents AS (
      SELECT p.soignant_id, p.pointage_arrivee_le AS ts, p.arrivee_lat AS lat, p.arrivee_lng AS lng,
        p.mission_id, p.id AS presence_id, 'arrivee' AS type_p
      FROM public.presences p
      WHERE p.pointage_arrivee_le > NOW() - INTERVAL '24 hours'
        AND p.arrivee_lat IS NOT NULL AND p.arrivee_lng IS NOT NULL
      UNION ALL
      SELECT p.soignant_id, p.pointage_depart_le AS ts, p.depart_lat AS lat, p.depart_lng AS lng,
        p.mission_id, p.id AS presence_id, 'depart' AS type_p
      FROM public.presences p
      WHERE p.pointage_depart_le > NOW() - INTERVAL '24 hours'
        AND p.depart_lat IS NOT NULL AND p.depart_lng IS NOT NULL
    ),
    paires AS (
      SELECT a.soignant_id, a.ts AS ts1, a.lat AS lat1, a.lng AS lng1, a.mission_id AS mission1, a.type_p AS type1,
        LEAD(a.ts) OVER (PARTITION BY a.soignant_id ORDER BY a.ts) AS ts2,
        LEAD(a.lat) OVER (PARTITION BY a.soignant_id ORDER BY a.ts) AS lat2,
        LEAD(a.lng) OVER (PARTITION BY a.soignant_id ORDER BY a.ts) AS lng2,
        LEAD(a.mission_id) OVER (PARTITION BY a.soignant_id ORDER BY a.ts) AS mission2,
        LEAD(a.type_p) OVER (PARTITION BY a.soignant_id ORDER BY a.ts) AS type2,
        LEAD(a.presence_id) OVER (PARTITION BY a.soignant_id ORDER BY a.ts) AS presence2
      FROM pointages_recents a
    )
    SELECT * FROM paires
    WHERE ts2 IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.journaux_audit ja
        WHERE ja.action = 'SYSTEM'
          AND ja.details->>'evenement' = 'TELEPORTATION_DETECTED'
          AND ja.details->>'presence_id_destination' = paires.presence2::text)
  LOOP
    v_vitesse := public.fn_vitesse_entre_pointages(v_rec.lat1, v_rec.lng1, v_rec.ts1, v_rec.lat2, v_rec.lng2, v_rec.ts2);
    IF (v_vitesse->>'calculable')::boolean AND (v_vitesse->>'teleportation')::boolean THEN
      INSERT INTO public.journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
      VALUES (v_rec.soignant_id, 'SOIGNANT', 'SYSTEM', 'presence', v_rec.presence2,
        jsonb_build_object('evenement', 'TELEPORTATION_DETECTED', 'niveau', 'ALERTE',
          'soignant_id', v_rec.soignant_id, 'mission_id_source', v_rec.mission1,
          'mission_id_destination', v_rec.mission2, 'type_pointage_source', v_rec.type1,
          'type_pointage_destination', v_rec.type2, 'presence_id_destination', v_rec.presence2,
          'ts_source', v_rec.ts1, 'ts_destination', v_rec.ts2,
          'distance_m', v_vitesse->>'distance_m', 'duree_h', v_vitesse->>'duree_h', 'vitesse_kmh', v_vitesse->>'vitesse_kmh'));
      UPDATE public.presences SET alerte_teleportation = true, modifie_le = now() WHERE id = v_rec.presence2;

      -- Pénalité automatique anti-triche : événement de score CONTESTABLE (-10 pts).
      -- Garde anti-doublon : un seul FRAUDE_GPS par présence destination.
      IF NOT EXISTS (
        SELECT 1 FROM public.evenements_score_soignant e
        WHERE e.type_evenement = 'FRAUDE_GPS'
          AND e.details->>'presence_id_destination' = v_rec.presence2::text
      ) THEN
        INSERT INTO public.evenements_score_soignant
          (soignant_id, type_evenement, points, motif, contestable, mission_id, details)
        VALUES (v_rec.soignant_id, 'FRAUDE_GPS', -10,
          'Téléportation détectée (vitesse > 200 km/h entre deux pointages GPS)', true, v_rec.mission2,
          jsonb_build_object('presence_id_destination', v_rec.presence2,
            'mission_id_source', v_rec.mission1, 'mission_id_destination', v_rec.mission2,
            'vitesse_kmh', v_vitesse->>'vitesse_kmh', 'distance_m', v_vitesse->>'distance_m',
            'duree_h', v_vitesse->>'duree_h', 'ts_source', v_rec.ts1, 'ts_destination', v_rec.ts2));
        IF NOT (v_rec.soignant_id = ANY(v_soignants_affectes)) THEN
          v_soignants_affectes := array_append(v_soignants_affectes, v_rec.soignant_id);
        END IF;
      END IF;

      v_alertes_count := v_alertes_count + 1;
    END IF;
  END LOOP;

  -- Recalcul du score de fiabilité pour chaque soignant pénalisé.
  IF array_length(v_soignants_affectes, 1) > 0 THEN
    FOREACH v_sid IN ARRAY v_soignants_affectes LOOP
      BEGIN
        PERFORM public.fn_calculer_score_fiabilite_v2(v_sid, 'fraude_gps');
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END LOOP;
  END IF;

  IF v_alertes_count > 0 THEN
    SELECT COALESCE(array_agg(admin_user_id), ARRAY[]::uuid[])
      INTO v_admin_ids
      FROM public.fn_list_admin_user_ids() AS admins(admin_user_id);
    IF array_length(v_admin_ids, 1) > 0 THEN
      INSERT INTO public.externalisation_actions (type_action, payload, source, source_id)
      SELECT 'EMAIL_NOTIF', jsonb_build_object('destinataire_id', uid, 'type', 'ALERTE_TELEPORTATION',
        'data', jsonb_build_object('count', v_alertes_count,
          'lien_admin', 'https://jolene.app/admin/journaux-audit?evenement=TELEPORTATION_DETECTED')), 'CRON_ANTI_TRICHE', NULL FROM unnest(v_admin_ids) AS uid;
      INSERT INTO public.externalisation_actions (type_action, payload, source, source_id)
      SELECT 'PUSH_NOTIF', jsonb_build_object('destinataire_id', uid, 'type_evenement', 'ALERTE_ADMIN',
        'titre', '⚠️ ' || v_alertes_count || ' téléportation' || CASE WHEN v_alertes_count > 1 THEN 's' ELSE '' END || ' détectée' || CASE WHEN v_alertes_count > 1 THEN 's' ELSE '' END,
        'corps', 'Vitesse > 200 km/h entre pointages. Pénalité -10 appliquée (contestable). Vérification requise.', 'lien', '/admin/journaux-audit'), 'CRON_ANTI_TRICHE', NULL FROM unnest(v_admin_ids) AS uid;
    END IF;
  END IF;
  RETURN jsonb_build_object('success', true, 'alertes_count', v_alertes_count, 'soignants_penalises', COALESCE(array_length(v_soignants_affectes, 1), 0));
END;
$$;


ALTER FUNCTION "public"."fn_detecter_teleportations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_diagnostic_coherence_financiere"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_missions_incoherent jsonb;
  v_factures_ecart jsonb;
  v_transfers_orphelins jsonb;
BEGIN
  IF NOT est_admin() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Admin requis');
  END IF;

  -- 1. Missions où total_brut diverge de taux × heures + majorations
  SELECT jsonb_build_object(
    'count', count(*),
    'echantillon', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', id, 'intitule', intitule, 'total_brut', total_brut,
        'attendu', taux_horaire_base * duree_heures
          + COALESCE(montant_majoration_nuit,0)
          + COALESCE(montant_majoration_dimanche,0)
          + COALESCE(montant_majoration_ferie,0),
        'ecart', total_brut - (
          taux_horaire_base * duree_heures
          + COALESCE(montant_majoration_nuit,0)
          + COALESCE(montant_majoration_dimanche,0)
          + COALESCE(montant_majoration_ferie,0)
        )
      ))
      FROM missions m2
      WHERE total_brut IS NOT NULL AND taux_horaire_base IS NOT NULL AND duree_heures IS NOT NULL
        AND abs(total_brut - (
          taux_horaire_base * duree_heures
          + COALESCE(montant_majoration_nuit,0)
          + COALESCE(montant_majoration_dimanche,0)
          + COALESCE(montant_majoration_ferie,0)
        )) > 0.5
      LIMIT 10
    )
  ) INTO v_missions_incoherent
  FROM missions m
  WHERE total_brut IS NOT NULL AND taux_horaire_base IS NOT NULL AND duree_heures IS NOT NULL
    AND abs(total_brut - (
      taux_horaire_base * duree_heures
      + COALESCE(montant_majoration_nuit,0)
      + COALESCE(montant_majoration_dimanche,0)
      + COALESCE(montant_majoration_ferie,0)
    )) > 0.5;

  -- 2. Factures où montant_ht diverge de mission.net_a_payer (>1% ou >1€)
  SELECT jsonb_build_object(
    'count', count(*),
    'echantillon', (
      SELECT jsonb_agg(jsonb_build_object(
        'facture_id', fh.id, 'numero_facture', fh.numero_facture,
        'mission_id', m.id, 'montant_ht', fh.montant_ht,
        'mission_net', m.net_a_payer,
        'ecart', fh.montant_ht - COALESCE(m.net_a_payer, 0)
      ))
      FROM factures_honoraires fh
      JOIN missions m ON m.id = fh.mission_id
      WHERE COALESCE(fh.type_document, 'FACTURE') = 'FACTURE'
        AND fh.statut NOT IN ('BROUILLON','REMPLACEE','ANNULEE')
        AND m.net_a_payer IS NOT NULL AND m.net_a_payer > 0
        AND abs(fh.montant_ht - m.net_a_payer) > GREATEST(m.net_a_payer * 0.01, 1.00)
      LIMIT 10
    )
  ) INTO v_factures_ecart
  FROM factures_honoraires fh
  JOIN missions m ON m.id = fh.mission_id
  WHERE COALESCE(fh.type_document, 'FACTURE') = 'FACTURE'
    AND fh.statut NOT IN ('BROUILLON','REMPLACEE','ANNULEE')
    AND m.net_a_payer IS NOT NULL AND m.net_a_payer > 0
    AND abs(fh.montant_ht - m.net_a_payer) > GREATEST(m.net_a_payer * 0.01, 1.00);

  -- 3. Transfers Stripe orphelins (mission qui n'a plus de facture)
  SELECT jsonb_build_object(
    'count', count(*),
    'echantillon', (
      SELECT jsonb_agg(jsonb_build_object(
        'transfer_id', st.id, 'mission_id', st.mission_id,
        'montant_total', st.montant_total
      ))
      FROM stripe_transfers st2
      WHERE st2.mission_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM factures_honoraires fh
          WHERE fh.mission_id = st2.mission_id
            AND COALESCE(fh.type_document, 'FACTURE') = 'FACTURE'
            AND fh.statut NOT IN ('BROUILLON','ANNULEE')
        )
      LIMIT 10
    )
  ) INTO v_transfers_orphelins
  FROM stripe_transfers st
  WHERE st.mission_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM factures_honoraires fh
      WHERE fh.mission_id = st.mission_id
        AND COALESCE(fh.type_document, 'FACTURE') = 'FACTURE'
        AND fh.statut NOT IN ('BROUILLON','ANNULEE')
    );

  RETURN jsonb_build_object(
    'success', true,
    'genere_le', now(),
    'missions_incoherentes', v_missions_incoherent,
    'factures_ecart_mission', v_factures_ecart,
    'stripe_transfers_orphelins', v_transfers_orphelins
  );
END;
$$;


ALTER FUNCTION "public"."fn_diagnostic_coherence_financiere"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_diffuser_pool_urgence"("p_mission_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_etablissement_id uuid;
BEGIN
  SELECT m.etablissement_id
  INTO v_etablissement_id
  FROM public.missions m
  WHERE m.id = p_mission_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  IF NOT (
    public.est_admin()
    OR v_etablissement_id = public.mon_etablissement_id()
  ) THEN
    RETURN 0;
  END IF;

  RETURN private.fn_diffuser_pool_urgence_interne(p_mission_id);
END;
$$;


ALTER FUNCTION "public"."fn_diffuser_pool_urgence"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_digest_hebdo_cibles"("p_limit" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "prenom" "text", "email" "text", "profession" "text", "nb_missions" bigint, "taux_max" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT s.id, s.prenom::text, s.email::text, s.profession::text,
    (SELECT count(*) FROM public.missions m
      WHERE m.statut = 'OUVERTE' AND public.fn_soignant_eligible_mission(s.id, m.id, false)),
    (SELECT max(m.taux_horaire_base) FROM public.missions m
      WHERE m.statut = 'OUVERTE' AND public.fn_soignant_eligible_mission(s.id, m.id, false))
  FROM public.soignants s
  WHERE s.email IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.missions m
      WHERE m.statut = 'OUVERTE' AND public.fn_soignant_eligible_mission(s.id, m.id, false)
    )
  LIMIT greatest(COALESCE(p_limit, 500), 1);
$$;


ALTER FUNCTION "public"."fn_digest_hebdo_cibles"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_document_marquer_revue_manuelle"("p_document_id" "uuid", "p_attempt_id" "uuid", "p_service" "text", "p_motif" "text", "p_details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_doc public.documents_soignants%ROWTYPE;
  v_revue_id uuid;
  v_motif text := left(COALESCE(NULLIF(btrim(p_motif), ''),
    'Vérification automatique non concluante — revue humaine en attente.'), 1000);
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  IF p_document_id IS NULL THEN
    RAISE EXCEPTION 'Document requis' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('revue-document:' || p_document_id::text, 0));
  SELECT * INTO v_doc
  FROM public.documents_soignants
  WHERE id = p_document_id AND supprime_le IS NULL AND revoque_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DOCUMENT_INACTIF');
  END IF;
  IF p_attempt_id IS NOT NULL
     AND v_doc.verification_attempt_id IS DISTINCT FROM p_attempt_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TENTATIVE_PERIMEE');
  END IF;

  PERFORM set_config('jolene.document_server_update', 'true', true);
  UPDATE public.documents_soignants
  SET statut_verification = 'REVUE_MANUELLE_REQUISE',
      motif_rejet = v_motif,
      verifie_par = NULL,
      verifie_le = NULL,
      verification_attempt_id = NULL,
      modifie_le = now()
  WHERE id = p_document_id;
  PERFORM set_config('jolene.document_server_update', '', true);

  SELECT id INTO v_revue_id
  FROM public.file_revue_manuelle
  WHERE type_entite = 'TELEVERSEMENT_DOCUMENT'
    AND id_entite = p_document_id
    AND statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE')
  FOR UPDATE;
  IF v_revue_id IS NULL THEN
    INSERT INTO public.file_revue_manuelle (
      type_entite, id_entite, service_en_echec, motif_echec,
      donnees_originales, statut, priorite
    ) VALUES (
      'TELEVERSEMENT_DOCUMENT', p_document_id,
      left(COALESCE(NULLIF(btrim(p_service), ''), 'VERIFICATION_DOCUMENT'), 100),
      v_motif,
      jsonb_build_object(
        'document_id', p_document_id,
        'soignant_id', v_doc.soignant_id,
        'type_document', v_doc.type_document::text,
        'code', left(COALESCE(p_details->>'code', 'NON_CONCLUANT'), 100),
        'mis_en_file_le', now()
      ),
      'EN_ATTENTE', 3
    ) RETURNING id INTO v_revue_id;
  ELSE
    UPDATE public.file_revue_manuelle
    SET motif_echec = v_motif,
        service_en_echec = left(COALESCE(NULLIF(btrim(p_service), ''), service_en_echec), 100),
        donnees_originales = COALESCE(donnees_originales, '{}'::jsonb)
          || jsonb_build_object('code', left(COALESCE(p_details->>'code', 'NON_CONCLUANT'), 100),
                                'derniere_tentative_le', now())
    WHERE id = v_revue_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'revue_id', v_revue_id, 'statut', 'EN_ATTENTE_ATTRIBUTION');
END;
$$;


ALTER FUNCTION "public"."fn_document_marquer_revue_manuelle"("p_document_id" "uuid", "p_attempt_id" "uuid", "p_service" "text", "p_motif" "text", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_document_requis_par_mission_active"("p_document_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.documents_soignants ds
    JOIN public.soignants s
      ON s.id = ds.soignant_id
     AND s.supprime_le IS NULL
    JOIN public.missions m
      ON m.soignant_assigne_id = ds.soignant_id
     AND m.statut IN ('ASSIGNEE', 'EN_COURS')
    JOIN public.documents_requis_par_profession drp
      ON drp.profession = s.profession
     AND drp.est_critique IS TRUE
     AND (
       drp.type_exercice_requis = 'TOUS'
       OR (
         drp.type_exercice_requis = 'LIBERAL_ONLY'
         AND m.type_contrat_applique::text = 'LIBERAL'
       )
       OR (
         drp.type_exercice_requis = 'SALARIE_ONLY'
         AND m.type_contrat_applique::text <> 'LIBERAL'
       )
     )
     AND public.fn_type_document_preuve_compatible(
       drp.type_document,
       ds.type_document
     )
    WHERE ds.id = p_document_id
      AND ds.supprime_le IS NULL
      AND ds.revoque_le IS NULL
      AND ds.statut_verification = 'VERIFIE'
      AND NOT (
        drp.type_document = 'RPPS_ADELI'
        AND (COALESCE(s.rpps_verifie, false) OR COALESCE(s.adeli_verifie, false))
      )
      AND (
        drp.a_expiration IS FALSE
        OR (ds.valide_jusqua IS NOT NULL AND ds.valide_jusqua > current_date)
      )
  );
$$;


ALTER FUNCTION "public"."fn_document_requis_par_mission_active"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_documents_ok_pour_mission"("p_soignant_id" "uuid", "p_type_contrat" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_profession public.type_profession;
  v_identifiant_officiel boolean;
  v_regime_liberal boolean;
  v_liberal_actif boolean;
BEGIN
  IF p_soignant_id IS NULL THEN RETURN false; END IF;

  IF current_user NOT IN ('postgres', 'supabase_admin', 'service_role')
     AND COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Calcul documentaire réservé au service interne.'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT profession,
         COALESCE(rpps_verifie, false) OR COALESCE(adeli_verifie, false),
         COALESCE(statut_compte::text, 'ACTIF') = 'ACTIF'
           AND COALESCE(type_exercice, 'SALARIE') IN ('LIBERAL', 'MIXTE')
           AND statut_liberal = 'ACTIF'
           AND siret_liberal ~ '^[0-9]{14}$'
           AND siret_liberal_verifie IS TRUE
           AND siret_liberal_verifie_le IS NOT NULL
           AND siret_liberal_coherence_identite IS TRUE
    INTO v_profession, v_identifiant_officiel, v_liberal_actif
  FROM public.soignants
  WHERE id = p_soignant_id AND supprime_le IS NULL;
  IF NOT FOUND OR v_profession IS NULL THEN RETURN false; END IF;

  v_regime_liberal := upper(COALESCE(p_type_contrat, 'SALARIE')) = 'LIBERAL';
  IF v_regime_liberal AND NOT COALESCE(v_liberal_actif, false) THEN
    RETURN false;
  END IF;

  RETURN NOT EXISTS (
    SELECT 1
    FROM public.documents_requis_par_profession drp
    WHERE drp.profession = v_profession
      AND drp.est_critique IS TRUE
      AND (
        drp.type_exercice_requis = 'TOUS'
        OR (drp.type_exercice_requis = 'LIBERAL_ONLY' AND v_regime_liberal)
        OR (drp.type_exercice_requis = 'SALARIE_ONLY' AND NOT v_regime_liberal)
      )
      AND NOT (
        (drp.type_document = 'RPPS_ADELI' AND v_identifiant_officiel)
        OR EXISTS (
          SELECT 1
          FROM public.documents_soignants ds
          WHERE ds.soignant_id = p_soignant_id
            AND public.fn_type_document_preuve_compatible(
              drp.type_document,
              ds.type_document
            )
            AND ds.statut_verification = 'VERIFIE'
            AND ds.supprime_le IS NULL
            AND ds.revoque_le IS NULL
            AND (
              drp.a_expiration IS FALSE
              OR (ds.valide_jusqua IS NOT NULL AND ds.valide_jusqua > current_date)
            )
            AND (
              drp.type_document <> 'DIPLOME'
              OR v_profession NOT IN ('IADE', 'IBODE')
              OR upper(COALESCE(ds.resultat_ia->>'profession_certifiee', ''))
                   = v_profession::text
            )
        )
      )
  );
END;
$_$;


ALTER FUNCTION "public"."fn_documents_ok_pour_mission"("p_soignant_id" "uuid", "p_type_contrat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_doit_notifier"("p_utilisateur_id" "uuid", "p_type_evenement" "public"."type_evenement_notification", "p_canal" "public"."canal_notification") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_canal_global boolean;
  v_pref_event boolean;
BEGIN
  -- URGENCE : toujours notifier (non désactivable)
  IF p_type_evenement = 'URGENCE' THEN RETURN true; END IF;

  -- Vérifier le canal global
  SELECT CASE p_canal
    WHEN 'EMAIL' THEN canal_email
    WHEN 'SMS' THEN canal_sms
    WHEN 'PUSH' THEN canal_push
    WHEN 'IN_APP' THEN canal_in_app
  END INTO v_canal_global
  FROM preferences_notifications WHERE utilisateur_id = p_utilisateur_id;

  -- Si pas de row : default ON sauf SMS
  IF v_canal_global IS NULL THEN
    v_canal_global := CASE p_canal WHEN 'SMS' THEN false ELSE true END;
  END IF;

  IF NOT v_canal_global THEN RETURN false; END IF;

  -- Préférence par événement (default true)
  SELECT actif INTO v_pref_event
  FROM preferences_notifications_par_evenement
  WHERE utilisateur_id = p_utilisateur_id
    AND type_evenement = p_type_evenement
    AND canal = p_canal;

  RETURN COALESCE(v_pref_event, true);
END;
$$;


ALTER FUNCTION "public"."fn_doit_notifier"("p_utilisateur_id" "uuid", "p_type_evenement" "public"."type_evenement_notification", "p_canal" "public"."canal_notification") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_donner_consentement_ping_gps"("p_consent" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  INSERT INTO public.consentements_ping_gps (soignant_id, consenti, consenti_le, retire_le, maj_le)
  VALUES (
    v_uid,
    p_consent,
    CASE WHEN p_consent THEN now() ELSE NULL END,
    CASE WHEN NOT p_consent THEN now() ELSE NULL END,
    now()
  )
  ON CONFLICT (soignant_id) DO UPDATE SET
    consenti = EXCLUDED.consenti,
    consenti_le = CASE WHEN EXCLUDED.consenti THEN COALESCE(public.consentements_ping_gps.consenti_le, now()) ELSE public.consentements_ping_gps.consenti_le END,
    retire_le = CASE WHEN NOT EXCLUDED.consenti THEN now() ELSE NULL END,
    maj_le = now();

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'SOIGNANT', 'RGPD_CONSENTEMENT_DONNE', 'consentement_ping_gps', v_uid,
    jsonb_build_object(
      'type', 'PING_GPS_BACKGROUND',
      'consenti', p_consent,
      'horodatage', now()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'consenti', p_consent,
    'horodatage', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_donner_consentement_ping_gps"("p_consent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ecrire_audit"("p_acteur_id" "uuid", "p_type_acteur" "text", "p_action" "text", "p_type_ressource" "text" DEFAULT NULL::"text", "p_id_ressource" "uuid" DEFAULT NULL::"uuid", "p_cle_s3" "text" DEFAULT NULL::"text", "p_details" "jsonb" DEFAULT NULL::"jsonb", "p_ip" "inet" DEFAULT NULL::"inet", "p_navigateur" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE v_id UUID;
BEGIN
    INSERT INTO journaux_audit (
        acteur_id, type_acteur, ip_acteur, navigateur_acteur,
        action, type_ressource, id_ressource, cle_s3_ressource, details
    ) VALUES (
        p_acteur_id, p_type_acteur, p_ip, p_navigateur,
        p_action, p_type_ressource, p_id_ressource, p_cle_s3, p_details
    ) RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."fn_ecrire_audit"("p_acteur_id" "uuid", "p_type_acteur" "text", "p_action" "text", "p_type_ressource" "text", "p_id_ressource" "uuid", "p_cle_s3" "text", "p_details" "jsonb", "p_ip" "inet", "p_navigateur" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ecrire_audit_safe"("p_acteur_id" "uuid", "p_type_acteur" "text", "p_action" "text", "p_type_ressource" "text", "p_id_ressource" "uuid", "p_cle_s3" "text" DEFAULT NULL::"text", "p_details" "jsonb" DEFAULT NULL::"jsonb", "p_ip" "inet" DEFAULT NULL::"inet", "p_navigateur" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_uid uuid := auth.uid();
  v_is_service boolean := COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role';
  v_acteur_id uuid := p_acteur_id;
BEGIN
  -- Iter3 sec fix : empêcher impersonation cross-user dans audit log
  IF NOT v_is_service AND NOT est_admin() THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
    END IF;
    v_acteur_id := v_uid;
  END IF;

  -- FIX 05/07/2026 (recette escrow) : les colonnes s'appellent ip_acteur,
  -- navigateur_acteur, cle_s3_ressource — l'INSERT historique visait ip,
  -- navigateur, cle_s3 (inexistantes) → échec 100 % avalé par le catch.
  INSERT INTO journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details, ip_acteur, navigateur_acteur
  ) VALUES (
    v_acteur_id, p_type_acteur, p_action, p_type_ressource, p_id_ressource,
    p_cle_s3, p_details, p_ip, p_navigateur
  ) RETURNING id INTO v_id;
  RETURN jsonb_build_object('success', true, 'id', v_id);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


ALTER FUNCTION "public"."fn_ecrire_audit_safe"("p_acteur_id" "uuid", "p_type_acteur" "text", "p_action" "text", "p_type_ressource" "text", "p_id_ressource" "uuid", "p_cle_s3" "text", "p_details" "jsonb", "p_ip" "inet", "p_navigateur" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_email_documents_expirants"() RETURNS TABLE("email" "text", "prenom" "text", "type_document" "text", "date_expiration" "text", "soignant_id" "uuid")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT ON (s.id, ds.type_document)
        s.email, s.prenom, ds.type_document::TEXT,
        TO_CHAR(ds.valide_jusqua, 'DD/MM/YYYY'), s.id
    FROM documents_soignants ds
    JOIN soignants s ON s.id = ds.soignant_id
    WHERE ds.valide_jusqua BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '30 days'
      AND ds.statut_verification = 'VERIFIE'
      AND ds.supprime_le IS NULL AND s.email IS NOT NULL
      AND NOT EXISTS (
          SELECT 1 FROM emails_envoyes ee
          WHERE ee.destinataire_id = s.id AND ee.type = 'DOCUMENT_EXPIRANT'
            AND ee.cree_le > NOW() - INTERVAL '7 days'
      );
END;
$$;


ALTER FUNCTION "public"."fn_email_documents_expirants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_email_eligible_liberal"() RETURNS TABLE("email" "text", "prenom" "text", "soignant_id" "uuid", "heures" numeric, "taux_prise_en_charge" integer, "montant_offert" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT s.email, s.prenom, s.id, s.heures_plateforme,
        CASE
            WHEN s.heures_plateforme >= 3200 THEN 100
            WHEN s.heures_plateforme >= 2400 THEN 75
            WHEN s.heures_plateforme >= 1600 THEN 50
            WHEN s.heures_plateforme >= 800 THEN 25
            ELSE 0
        END,
        ROUND(450.0 * (CASE
            WHEN s.heures_plateforme >= 3200 THEN 1.0
            WHEN s.heures_plateforme >= 2400 THEN 0.75
            WHEN s.heures_plateforme >= 1600 THEN 0.5
            WHEN s.heures_plateforme >= 800 THEN 0.25
            ELSE 0
        END), 2)
    FROM soignants s
    WHERE s.heures_plateforme >= 800
      AND s.statut_liberal = 'NON_LIBERAL'
      AND s.supprime_le IS NULL AND s.email IS NOT NULL
      AND NOT EXISTS (
          SELECT 1 FROM emails_envoyes ee
          WHERE ee.destinataire_id = s.id AND ee.type = 'ELIGIBLE_LIBERAL'
      )
      AND s.profession IN (SELECT profession FROM professions_liberal_eligible);
END;
$$;


ALTER FUNCTION "public"."fn_email_eligible_liberal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_email_factures_impayees"() RETURNS TABLE("email" "text", "nom_etablissement" "text", "numero_facture" "text", "montant_ttc" "text", "jours_depuis" integer, "etablissement_id" "uuid")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT e.email_contact, e.nom, f.numero_facture,
        ROUND(f.montant_ttc, 2)::TEXT,
        (CURRENT_DATE - f.date_echeance)::INTEGER, e.id
    FROM factures f
    JOIN etablissements e ON e.id = f.etablissement_id
    WHERE f.statut IN ('EMISE', 'EN_RETARD')
      AND f.date_echeance < CURRENT_DATE
      AND e.email_contact IS NOT NULL
      AND NOT EXISTS (
          SELECT 1 FROM emails_envoyes ee
          WHERE ee.type = 'RAPPEL_FACTURE'
            AND ee.sujet LIKE '%' || f.numero_facture || '%'
            AND ee.cree_le > NOW() - INTERVAL '7 days'
      );
END;
$$;


ALTER FUNCTION "public"."fn_email_factures_impayees"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_email_rappels_j1"() RETURNS TABLE("email" "text", "prenom" "text", "mission" "text", "etablissement" "text", "heure_debut" "text", "soignant_id" "uuid")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT s.email, s.prenom, m.intitule, e.nom,
        TO_CHAR(m.debut_le AT TIME ZONE 'Europe/Paris', 'HH24:MI'), s.id
    FROM missions m
    JOIN soignants s ON s.id = m.soignant_assigne_id
    JOIN etablissements e ON e.id = m.etablissement_id
    WHERE m.statut = 'ASSIGNEE'
      AND m.debut_le::DATE = (CURRENT_DATE + INTERVAL '1 day')
      AND s.email IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."fn_email_rappels_j1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_email_recap_hebdo"() RETURNS TABLE("email" "text", "prenom" "text", "soignant_id" "uuid", "missions_terminees" bigint, "heures_semaine" numeric, "gains_semaine" numeric, "score" numeric, "heures_totales" numeric, "missions_dispo" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT s.email, s.prenom, s.id,
    count(m.id) FILTER (
      WHERE m.statut = 'TERMINEE' AND m.fin_le > now() - interval '7 days'
    ),
    COALESCE(sum(m.duree_heures) FILTER (
      WHERE m.statut = 'TERMINEE' AND m.fin_le > now() - interval '7 days'
    ), 0),
    COALESCE(sum(m.net_a_payer) FILTER (
      WHERE m.statut = 'TERMINEE' AND m.fin_le > now() - interval '7 days'
    ), 0),
    s.score_fiabilite, s.heures_cumulees,
    (SELECT count(*) FROM public.missions mo
      WHERE mo.statut = 'OUVERTE'
        AND public.fn_soignant_eligible_mission(s.id, mo.id, false))
  FROM public.soignants s
  LEFT JOIN public.missions m ON m.soignant_assigne_id = s.id
  WHERE s.supprime_le IS NULL AND s.email IS NOT NULL
    AND s.derniere_activite_le > now() - interval '30 days'
  GROUP BY s.id, s.email, s.prenom, s.score_fiabilite, s.heures_cumulees;
END;
$$;


ALTER FUNCTION "public"."fn_email_recap_hebdo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_emettre_alerte_monitoring"("p_type" "text", "p_severite" "text", "p_source" "text", "p_message" "text", "p_details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_id UUID;
BEGIN
  IF NOT fn_est_contexte_cron_ou_admin() THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;
  INSERT INTO alertes_systeme (type_alerte, severite, source, message, details, occurrences, derniere_occurrence)
  VALUES (p_type, p_severite, p_source, p_message, p_details, 1, now())
  ON CONFLICT (source, type_alerte) WHERE resolu_le IS NULL
  DO UPDATE SET
    occurrences = alertes_systeme.occurrences + 1,
    derniere_occurrence = now(),
    severite = EXCLUDED.severite,
    message = EXCLUDED.message,
    details = EXCLUDED.details
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."fn_emettre_alerte_monitoring"("p_type" "text", "p_severite" "text", "p_source" "text", "p_message" "text", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enforce_etablissement_rbac_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_row jsonb;
  v_old_row jsonb;
  v_new_row jsonb;
  v_etab_id uuid;
  v_mission_id uuid;
  v_permission text := TG_ARGV[0];
  v_context text := COALESCE(
    current_setting('jolene.empechement_mission_context', true), ''
  );
BEGIN
  IF auth.uid() IS NULL OR public.est_admin() THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_TABLE_NAME = 'missions'
     AND v_context <> ''
     AND v_context = COALESCE(
       current_setting('jolene.empechement_mission_validated', true), ''
     )
     AND (
       (
         TG_OP = 'UPDATE'
         AND v_context IN (
           'FLAG:' || (to_jsonb(OLD)->>'id') || ':' || auth.uid()::text,
           'CLOSE:' || (to_jsonb(OLD)->>'id') || ':' || auth.uid()::text
         )
       )
       OR (
         TG_OP = 'INSERT'
         AND to_jsonb(NEW)->>'remplacement_de_mission_id' IS NOT NULL
         AND v_context = 'REPLACEMENT:'
           || (to_jsonb(NEW)->>'remplacement_de_mission_id')
           || ':' || auth.uid()::text
       )
     ) THEN
    RETURN NEW;
  END IF;

  -- Conserver les transitions Lot 21 protégées par
  -- fn_protect_candidature_statut. Un soignant peut répondre à sa propre
  -- proposition, y compris pour un profil aussi membre d'un établissement.
  IF TG_TABLE_NAME = 'candidatures' THEN
    v_row := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    IF v_row ->> 'soignant_id' = auth.uid()::text
       OR current_setting('jolene.candidature_rpc_mission_id', true)
            = v_row ->> 'mission_id' THEN
      IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;
  END IF;

  IF public.fn_role_etablissement_courant(NULL) IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_row := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  IF TG_OP = 'UPDATE' THEN
    v_old_row := to_jsonb(OLD);
    v_new_row := to_jsonb(NEW);
  END IF;
  IF COALESCE(v_row ->> 'etablissement_id', '') ~ '^[0-9a-fA-F-]{36}$' THEN
    v_etab_id := (v_row ->> 'etablissement_id')::uuid;
  END IF;
  IF v_etab_id IS NULL
     AND COALESCE(v_row ->> 'mission_id', '') ~ '^[0-9a-fA-F-]{36}$' THEN
    v_mission_id := (v_row ->> 'mission_id')::uuid;
    SELECT m.etablissement_id INTO v_etab_id
    FROM public.missions m WHERE m.id = v_mission_id;
  END IF;

  IF v_etab_id IS NOT NULL
     AND v_permission = 'missions'
     AND TG_TABLE_NAME = 'missions'
     AND TG_OP = 'UPDATE'
     AND public.fn_a_permission_etablissement('pointage', v_etab_id)
     AND (
       v_new_row - ARRAY[
         'code_arrivee', 'code_depart', 'code_pointage_actif',
         'code_pointage_hmac', 'prochain_type_scan', 'nb_scans',
         'presence_confirmee_le', 'modifie_le'
       ]::text[]
     ) = (
       v_old_row - ARRAY[
         'code_arrivee', 'code_depart', 'code_pointage_actif',
         'code_pointage_hmac', 'prochain_type_scan', 'nb_scans',
         'presence_confirmee_le', 'modifie_le'
       ]::text[]
     ) THEN
    RETURN NEW;
  END IF;

  IF v_etab_id IS NULL
     OR NOT public.fn_a_permission_etablissement(v_permission, v_etab_id) THEN
    RAISE EXCEPTION 'Permission etablissement % requise', v_permission
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$_$;


ALTER FUNCTION "public"."fn_enforce_etablissement_rbac_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enregistrer_mon_iban"("p_iban" "text", "p_titulaire" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_soignant public.soignants%ROWTYPE;
  v_rib public.documents_soignants%ROWTYPE;
  v_titulaire_normalise text;
  v_attendu_1 text;
  v_attendu_2 text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  SELECT * INTO v_soignant
  FROM public.soignants
  WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'PROFIL_INTROUVABLE');
  END IF;

  v_titulaire_normalise := btrim(regexp_replace(
    public.fn_normaliser_nom(COALESCE(p_titulaire, '')), '[^a-z0-9]+', ' ', 'g'
  ));
  v_attendu_1 := btrim(regexp_replace(
    public.fn_normaliser_nom(v_soignant.prenom || ' ' || v_soignant.nom), '[^a-z0-9]+', ' ', 'g'
  ));
  v_attendu_2 := btrim(regexp_replace(
    public.fn_normaliser_nom(v_soignant.nom || ' ' || v_soignant.prenom), '[^a-z0-9]+', ' ', 'g'
  ));
  IF v_titulaire_normalise NOT IN (v_attendu_1, v_attendu_2) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'TITULAIRE_NON_CONCORDANT',
      'error', 'Le titulaire doit correspondre exactement à votre identité vérifiée.'
    );
  END IF;

  SELECT * INTO v_rib
  FROM public.documents_soignants
  WHERE soignant_id = v_uid
    AND type_document = 'RIB'
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL AND revoque_le IS NULL
  ORDER BY verifie_le DESC NULLS LAST, televerse_le DESC NULLS LAST, id DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'RIB_VERIFIE_REQUIS',
      'error', 'Téléversez puis faites vérifier le RIB correspondant.'
    );
  END IF;
  RETURN public.fn_lier_iban_verifie_document(v_rib.id, v_rib.s3_cle, p_iban);
END;
$$;


ALTER FUNCTION "public"."fn_enregistrer_mon_iban"("p_iban" "text", "p_titulaire" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enregistrer_numero_dpae"("p_contrat_id" "uuid", "p_dpae_numero" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
  v_numero_trim text;
  v_soignant_id uuid;
  v_mission_id uuid;
  v_soignant_prenom text;
  v_etab_nom text;
  v_mission_intitule text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_dpae_numero IS NULL OR length(trim(p_dpae_numero)) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Numéro DPAE requis');
  END IF;

  v_numero_trim := trim(p_dpae_numero);

  IF v_numero_trim !~ '^[A-Za-z0-9]{8,30}$' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Format invalide : 8 à 30 caractères alphanumériques (lettres et chiffres) requis. Aucun espace ni ponctuation.'
    );
  END IF;

  IF v_numero_trim !~ '[0-9]' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Format invalide : le numéro DPAE doit contenir au moins un chiffre.'
    );
  END IF;

  SELECT cm.etablissement_id, cm.soignant_id, cm.mission_id
    INTO v_etab_id, v_soignant_id, v_mission_id
  FROM public.contrats_mission cm
  WHERE cm.id = p_contrat_id;

  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contrat introuvable');
  END IF;

  IF NOT (est_admin() OR v_etab_id = mon_etablissement_id()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  UPDATE public.contrats_mission
  SET dpae_numero = v_numero_trim,
      dpae_effectuee = true,
      dpae_effectuee_le = COALESCE(dpae_effectuee_le, NOW()),
      modifie_le = NOW()
  WHERE id = p_contrat_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'SYSTEM', 'contrat_mission', p_contrat_id,
    jsonb_build_object(
      'evenement', 'DPAE_NUMERO_ENREGISTRE',
      'dpae_numero', v_numero_trim,
      'enregistre_le', NOW()::text
    )
  );

  IF v_soignant_id IS NOT NULL AND v_mission_id IS NOT NULL THEN
    SELECT prenom INTO v_soignant_prenom FROM public.soignants WHERE id = v_soignant_id;
    SELECT nom INTO v_etab_nom FROM public.etablissements WHERE id = v_etab_id;
    SELECT intitule INTO v_mission_intitule FROM public.missions WHERE id = v_mission_id;

    BEGIN
      PERFORM net.http_post(
        url := 'https://flripxtsyegjshnhzjkz.supabase.co/functions/v1/send-email',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1)
        ),
        body := jsonb_build_object(
          'type', 'DPAE_DECLAREE_SOIGNANT',
          'destinataire_id', v_soignant_id,
          'data', jsonb_build_object(
            'prenom', COALESCE(v_soignant_prenom, ''),
            'etablissement_nom', COALESCE(v_etab_nom, 'L''établissement'),
            'mission_intitule', COALESCE(v_mission_intitule, 'votre mission'),
            'dpae_numero', v_numero_trim,
            'contrat_id', p_contrat_id::text
          )
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object('success', true, 'dpae_numero', v_numero_trim);
END;
$_$;


ALTER FUNCTION "public"."fn_enregistrer_numero_dpae"("p_contrat_id" "uuid", "p_dpae_numero" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_enregistrer_numero_dpae"("p_contrat_id" "uuid", "p_dpae_numero" "text") IS 'Sprint 15 PR 3 : enregistre le n° DPAE URSSAF avec validation format strict + email best-effort au soignant via send-email (template DPAE_DECLAREE_SOIGNANT).';



CREATE OR REPLACE FUNCTION "public"."fn_enregistrer_pings_gps"("p_mission_id" "uuid", "p_pings" "jsonb", "p_terminal_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mission record;
  v_consent record;
  v_ping jsonb;
  v_inserts integer := 0;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  IF p_pings IS NULL OR jsonb_typeof(p_pings) != 'array' OR jsonb_array_length(p_pings) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'PINGS_VIDE');
  END IF;

  -- Limite anti-flood : max 200 pings par batch
  IF jsonb_array_length(p_pings) > 200 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TROP_DE_PINGS');
  END IF;

  -- Mission + soignant assigné
  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MISSION_INTROUVABLE');
  END IF;
  IF v_mission.soignant_assigne_id != v_uid THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  -- Consentement RGPD strict
  SELECT * INTO v_consent FROM public.consentements_ping_gps WHERE soignant_id = v_uid;
  IF v_consent IS NULL OR NOT v_consent.consenti THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CONSENTEMENT_MANQUANT');
  END IF;

  -- Fenêtre temporelle : pings acceptés uniquement entre debut_le -1h et fin_le +2h
  -- (au-delà : ignoré silencieusement, le client recevra success=true mais 0 insertions)
  FOR v_ping IN SELECT * FROM jsonb_array_elements(p_pings)
  LOOP
    DECLARE
      v_h timestamptz := (v_ping->>'horodatage')::timestamptz;
      v_lat numeric := (v_ping->>'lat')::numeric;
      v_lng numeric := (v_ping->>'lng')::numeric;
      v_prec numeric := NULLIF(v_ping->>'precision_m', '')::numeric;
      v_vit numeric := NULLIF(v_ping->>'vitesse_ms', '')::numeric;
      v_cap numeric := NULLIF(v_ping->>'cap_deg', '')::numeric;
      v_alt numeric := NULLIF(v_ping->>'altitude_m', '')::numeric;
      v_src text := COALESCE(v_ping->>'source', 'BACKGROUND');
      v_mock boolean := COALESCE((v_ping->>'mock_detected')::boolean, false);
    BEGIN
      IF v_h IS NULL OR v_lat IS NULL OR v_lng IS NULL THEN
        CONTINUE;
      END IF;
      IF v_h < v_mission.debut_le - INTERVAL '1 hour' OR v_h > v_mission.fin_le + INTERVAL '2 hours' THEN
        CONTINUE;
      END IF;
      IF v_lat < -90 OR v_lat > 90 OR v_lng < -180 OR v_lng > 180 THEN
        CONTINUE;
      END IF;

      INSERT INTO public.pings_gps_mission (
        mission_id, soignant_id, lat, lng, precision_m, vitesse_ms, cap_deg, altitude_m,
        source, mock_detected, horodatage, terminal_id
      ) VALUES (
        p_mission_id, v_uid, v_lat, v_lng, v_prec, v_vit, v_cap, v_alt,
        v_src, v_mock, v_h, p_terminal_id
      );
      v_inserts := v_inserts + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'inserts', v_inserts,
    'ignores', jsonb_array_length(p_pings) - v_inserts
  );
END;
$$;


ALTER FUNCTION "public"."fn_enregistrer_pings_gps"("p_mission_id" "uuid", "p_pings" "jsonb", "p_terminal_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enregistrer_reservation_paiement_mission"("p_mission_id" "uuid", "p_etablissement_id" "uuid", "p_montant_ht" numeric, "p_montant_tva" numeric, "p_montant_ttc" numeric, "p_stripe_payment_intent_id" "text", "p_statut" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_mission record;
  v_paiement public.paiements_mission%ROWTYPE;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  IF p_mission_id IS NULL
     OR p_etablissement_id IS NULL
     OR NULLIF(btrim(p_stripe_payment_intent_id), '') IS NULL
     OR p_stripe_payment_intent_id !~ '^pi_[A-Za-z0-9]+$'
     OR p_statut IS NULL
     OR p_statut NOT IN ('EN_ATTENTE', 'AUTORISE', 'ECHOUE')
     OR p_montant_ht IS NULL
     OR p_montant_tva IS NULL
     OR p_montant_ttc IS NULL
     OR p_montant_ht < 0
     OR p_montant_tva < 0
     OR p_montant_ttc <= 0 THEN
    RAISE EXCEPTION 'Réservation de paiement invalide' USING ERRCODE = '22023';
  END IF;

  SELECT m.id, m.etablissement_id, m.statut::text AS statut,
         m.soignant_assigne_id
    INTO v_mission
  FROM public.missions m
  WHERE m.id = p_mission_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_mission.etablissement_id IS DISTINCT FROM p_etablissement_id THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'MISSION_INTROUVABLE'
    );
  END IF;

  IF v_mission.statut IS DISTINCT FROM 'OUVERTE'
     OR v_mission.soignant_assigne_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'MISSION_STATE_CHANGED'
    );
  END IF;

  SELECT * INTO v_paiement
  FROM public.paiements_mission pm
  WHERE pm.mission_id = p_mission_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_paiement.statut IN ('CAPTURE', 'REMBOURSE') THEN
      RETURN jsonb_build_object(
        'success', false,
        'error_code', 'PAIEMENT_TERMINAL_EXISTANT'
      );
    END IF;

    IF v_paiement.statut = 'AUTORISE'
       AND (
         v_paiement.stripe_payment_intent_id IS DISTINCT FROM p_stripe_payment_intent_id
         OR p_statut <> 'AUTORISE'
       ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error_code', 'PAIEMENT_AUTORISE_EXISTANT'
      );
    END IF;

    UPDATE public.paiements_mission
    SET etablissement_id = p_etablissement_id,
        montant_ht = p_montant_ht,
        montant_tva = p_montant_tva,
        montant_ttc = p_montant_ttc,
        stripe_payment_intent_id = btrim(p_stripe_payment_intent_id),
        statut = p_statut
    WHERE id = v_paiement.id;
  ELSE
    INSERT INTO public.paiements_mission (
      mission_id,
      etablissement_id,
      montant_ht,
      montant_tva,
      montant_ttc,
      stripe_payment_intent_id,
      statut
    ) VALUES (
      p_mission_id,
      p_etablissement_id,
      p_montant_ht,
      p_montant_tva,
      p_montant_ttc,
      btrim(p_stripe_payment_intent_id),
      p_statut
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'stripe_payment_intent_id', btrim(p_stripe_payment_intent_id),
    'statut', p_statut
  );
END;
$_$;


ALTER FUNCTION "public"."fn_enregistrer_reservation_paiement_mission"("p_mission_id" "uuid", "p_etablissement_id" "uuid", "p_montant_ht" numeric, "p_montant_tva" numeric, "p_montant_ttc" numeric, "p_stripe_payment_intent_id" "text", "p_statut" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enregistrer_siret_liberal"("p_siret" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_siret text := regexp_replace(COALESCE(p_siret, ''), '[^0-9]', '', 'g');
  v_soignant record;
  v_verification_complete boolean := false;
  v_previous_system_update text := COALESCE(current_setting('jolene.system_update', true), '');
  v_previous_liberal_transition text := COALESCE(current_setting('jolene.liberal_transition', true), '');
  v_previous_siret_reset text := COALESCE(current_setting('jolene.siret_liberal_reset', true), '');
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE', 'error', 'Non authentifié');
  END IF;
  IF v_siret !~ '^[0-9]{14}$' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'SIRET_INVALIDE', 'error', 'Le SIRET doit contenir 14 chiffres');
  END IF;

  SELECT siret_liberal, statut_liberal, siret_liberal_verifie,
         siret_liberal_verifie_le, siret_liberal_coherence_identite
    INTO v_soignant
  FROM public.soignants
  WHERE id = v_uid AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'SOIGNANT_INTROUVABLE', 'error', 'Soignant introuvable');
  END IF;

  v_verification_complete :=
    v_soignant.siret_liberal_verifie IS TRUE
    AND v_soignant.siret_liberal_verifie_le IS NOT NULL
    AND v_soignant.siret_liberal_coherence_identite IS TRUE;

  -- Rejouer la même demande est sans effet et ne détruit jamais une preuve
  -- déjà obtenue (important après un retry réseau mobile).
  IF v_soignant.siret_liberal IS NOT DISTINCT FROM v_siret THEN
    RETURN jsonb_build_object(
      'success', true,
      'verification_requise', NOT v_verification_complete,
      'statut_liberal', v_soignant.statut_liberal
    );
  END IF;

  IF v_soignant.statut_liberal = 'ACTIF' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'SIRET_LIBERAL_ACTIF_VERROUILLE',
      'error', 'Un SIRET libéral actif ne peut pas être remplacé depuis le profil. Contactez le support.'
    );
  END IF;

  PERFORM set_config('jolene.liberal_transition', 'true', true);
  PERFORM set_config('jolene.system_update', 'true', true);
  PERFORM set_config('jolene.siret_liberal_reset', 'true', true);
  UPDATE public.soignants
  SET siret_liberal = v_siret,
      siret_liberal_verifie = false,
      siret_liberal_verifie_le = NULL,
      siret_liberal_raison_sociale = NULL,
      siret_liberal_coherence_identite = NULL,
      statut_liberal = 'EN_COURS',
      type_exercice = 'SALARIE',
      type_contrat = 'CDD',
      date_passage_liberal = NULL,
      code_ape = NULL,
      modifie_le = now()
  WHERE id = v_uid;

  PERFORM public.fn_calculer_tous_documents_valides(v_uid);
  PERFORM set_config('jolene.system_update', v_previous_system_update, true);
  PERFORM set_config('jolene.liberal_transition', v_previous_liberal_transition, true);
  PERFORM set_config('jolene.siret_liberal_reset', v_previous_siret_reset, true);
  RETURN jsonb_build_object('success', true, 'verification_requise', true);
END;
$_$;


ALTER FUNCTION "public"."fn_enregistrer_siret_liberal"("p_siret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_enregistrer_swipe"("p_mission_id" "uuid", "p_direction" "text", "p_choix_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_direction public.swipe_direction;
  v_mission record;
  v_soignant record;
  v_resolution jsonb;
  v_choix text;
  v_swipe_id uuid;
  v_candidature_id uuid;
  v_planning jsonb;
  v_warning text;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'auth_required'); END IF;
  IF p_direction = 'SUPER_LIKE' THEN p_direction := 'FAVORI'; END IF;
  IF p_direction NOT IN ('LIKE', 'DISLIKE', 'FAVORI') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'direction_invalide');
  END IF;
  v_direction := p_direction::public.swipe_direction;

  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF NOT FOUND OR v_mission.statut <> 'OUVERTE' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'mission_indisponible');
  END IF;
  SELECT * INTO v_soignant FROM public.soignants WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'profil_introuvable'); END IF;
  IF NOT public.fn_soignant_compatible_mission(
    v_soignant.profession, v_soignant.specialite_medicale,
    v_mission.profession_requise, v_mission.specialite_medicale_requise,
    COALESCE(v_mission.accepte_non_specialises, true)
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'profession_incompatible');
  END IF;
  IF public.fn_est_exclu(v_uid, v_mission.etablissement_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'acces_refuse');
  END IF;

  IF v_direction = 'LIKE' THEN
    IF EXISTS (SELECT 1 FROM public.candidatures WHERE mission_id = p_mission_id AND soignant_id = v_uid) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'Vous avez déjà candidaté à cette mission');
    END IF;
    v_planning := public.fn_conflit_planning_soignant(v_uid, p_mission_id);
    IF COALESCE((v_planning->>'conflit')::boolean, false) THEN
      RETURN jsonb_build_object('ok', false, 'error', v_planning->>'message', 'conflit_planning', true);
    END IF;
    v_warning := v_planning->>'warning';

    v_resolution := public.fn_resoudre_contrat_mission(p_mission_id, v_uid, p_choix_contrat);
    IF COALESCE((v_resolution->>'ok')::boolean, false) IS NOT TRUE THEN
      RETURN jsonb_build_object('ok', false) || (v_resolution - 'ok');
    END IF;
    v_choix := v_resolution->>'contrat';
    IF v_choix = 'LIBERAL' AND NOT public.fn_documents_ok_pour_mission(v_uid, 'LIBERAL') THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Les documents requis pour candidater en libéral sont manquants ou expirés.',
        'documents_requis_pour', 'LIBERAL'
      );
    END IF;
  END IF;

  INSERT INTO public.swipes(soignant_id, mission_id, direction)
  VALUES (v_uid, p_mission_id, v_direction)
  ON CONFLICT (soignant_id, mission_id) DO NOTHING
  RETURNING id INTO v_swipe_id;
  IF v_swipe_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'mission_deja_swipee');
  END IF;

  IF v_direction = 'FAVORI' THEN
    INSERT INTO public.missions_sauvegardees(soignant_id, mission_id)
    VALUES (v_uid, p_mission_id)
    ON CONFLICT (soignant_id, mission_id) DO NOTHING;
    RETURN jsonb_build_object('ok', true, 'swipe_id', v_swipe_id, 'direction', 'FAVORI', 'sauvegardee', true);
  ELSIF v_direction = 'LIKE' THEN
    INSERT INTO public.candidatures(mission_id, soignant_id, message, statut, type_contrat_choisi)
    VALUES (p_mission_id, v_uid, NULL, 'EN_ATTENTE', v_choix)
    RETURNING id INTO v_candidature_id;
    INSERT INTO public.notifications(destinataire_id, type_destinataire, type, titre, corps, lien)
    VALUES (
      v_mission.etablissement_id, 'ETABLISSEMENT', 'CANDIDATURE_RECUE',
      '📋 Nouvelle candidature reçue',
      COALESCE(v_soignant.prenom, 'Un soignant') || ' a postulé à votre mission « ' ||
        public.fn_html_escape(v_mission.intitule) || ' ».',
      '/etablissement/missions/' || p_mission_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'swipe_id', v_swipe_id, 'direction', p_direction,
    'candidature_id', v_candidature_id, 'choix_contrat', v_choix,
    'profession_requise', v_mission.profession_requise::text,
    'docs_a_completer', v_direction = 'LIKE' AND NOT public.fn_documents_ok_pour_mission(v_uid, v_choix),
    'warning', v_warning
  );
END;
$$;


ALTER FUNCTION "public"."fn_enregistrer_swipe"("p_mission_id" "uuid", "p_direction" "text", "p_choix_contrat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_envoyer_message"("p_conversation_id" "uuid", "p_contenu" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Non authentifié');
  END IF;
  RETURN private.fn_envoyer_message_interne(
    p_conversation_id,
    p_contenu,
    v_uid,
    public.est_admin(),
    NULL
  );
END;
$$;


ALTER FUNCTION "public"."fn_envoyer_message"("p_conversation_id" "uuid", "p_contenu" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_envoyer_message_contact"("p_sujet" "text", "p_corps" "text", "p_source" "text" DEFAULT 'aide'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_nom text;
  v_email text;
  v_msg_id uuid;
  v_sujet text := pg_catalog.btrim(COALESCE(p_sujet, ''));
  v_corps text := pg_catalog.btrim(COALESCE(p_corps, ''));
  v_source text := COALESCE(
    NULLIF(pg_catalog.btrim(p_source), ''),
    'aide'
  );
  v_url text;
  v_token text;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Non authentifié');
  END IF;
  IF pg_catalog.length(v_sujet) < 1
     OR pg_catalog.length(v_sujet) > 150
     OR pg_catalog.length(v_corps) < 1
     OR pg_catalog.length(v_corps) > 4000 THEN
    RETURN pg_catalog.jsonb_build_object(
      'error', 'Sujet (150 max) et message (4000 max) obligatoires'
    );
  END IF;
  IF pg_catalog.length(v_source) > 120 THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Source invalide');
  END IF;
  IF (
    SELECT pg_catalog.count(*)
    FROM public.messages_contact mc
    WHERE mc.expediteur_id = v_uid
      AND mc.cree_le > pg_catalog.now() - interval '1 hour'
  ) >= 10 THEN
    RETURN pg_catalog.jsonb_build_object(
      'error', 'Trop de demandes. Réessayez dans une heure.'
    );
  END IF;

  IF public.est_admin() THEN
    SELECT
      COALESCE(ea.prenom || ' ' || ea.nom, u.email),
      u.email
    INTO v_nom, v_email
    FROM auth.users u
    LEFT JOIN public.equipe_admin ea
      ON ea.user_id = u.id AND ea.actif IS TRUE
    WHERE u.id = v_uid;
    v_role := 'ADMIN_PLATEFORME';
  ELSE
    SELECT s.prenom || ' ' || s.nom, s.email
    INTO v_nom, v_email
    FROM public.soignants s
    WHERE s.id = v_uid
      AND s.supprime_le IS NULL;
    IF FOUND THEN
      v_role := 'SOIGNANT';
    ELSE
      SELECT e.nom, e.email_contact
      INTO v_nom, v_email
      FROM public.membres_etablissement me
      JOIN public.etablissements e ON e.id = me.etablissement_id
      WHERE me.user_id = v_uid
        AND me.actif IS TRUE
        AND e.supprime_le IS NULL
      ORDER BY
        CASE me.role
          WHEN 'PROPRIETAIRE' THEN 0
          WHEN 'ADMIN_GROUPE' THEN 1
          WHEN 'RH' THEN 2
          ELSE 3
        END,
        me.accepte_le,
        me.id
      LIMIT 1;
      IF NOT FOUND THEN
        -- Compatibilité avec les comptes historiques id établissement = id Auth.
        SELECT e.nom, e.email_contact
        INTO v_nom, v_email
        FROM public.etablissements e
        WHERE e.id = v_uid
          AND e.supprime_le IS NULL;
      END IF;
      IF v_nom IS NOT NULL THEN
        v_role := 'ADMIN_ETABLISSEMENT';
      END IF;
    END IF;
  END IF;

  IF v_email IS NULL THEN
    SELECT u.email INTO v_email FROM auth.users u WHERE u.id = v_uid;
  END IF;
  INSERT INTO public.messages_contact (
    expediteur_id,
    expediteur_role,
    expediteur_nom,
    expediteur_email,
    sujet,
    corps,
    source
  ) VALUES (
    v_uid,
    COALESCE(v_role, 'INCONNU'),
    v_nom,
    v_email,
    v_sujet,
    v_corps,
    v_source
  )
  RETURNING id INTO v_msg_id;

  BEGIN
    INSERT INTO public.notifications (
      destinataire_id,
      type_destinataire,
      type,
      titre,
      corps,
      lien,
      type_ressource,
      id_ressource
    )
    SELECT
      admins.uid,
      'ADMIN',
      'MESSAGE_ADMIN',
      '✉️ Nouveau message — ' || COALESCE(v_nom, 'utilisateur'),
      pg_catalog.left(v_corps, 140),
      '/admin/messages-contact',
      'message_contact',
      v_msg_id
    FROM public.fn_list_admin_user_ids() AS admins(uid);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  BEGIN
    -- L'URL ne doit jamais pointer implicitement vers la production depuis
    -- une branche/staging. Le vault peut la surcharger ; sinon l'issuer du JWT
    -- Supabase vérifié fournit l'URL exacte de l'environnement courant.
    SELECT NULLIF(pg_catalog.btrim(ds.decrypted_secret), '')
    INTO v_url
    FROM vault.decrypted_secrets ds
    WHERE ds.name = 'supabase_url'
    LIMIT 1;
    v_url := COALESCE(
      v_url,
      NULLIF(
        pg_catalog.regexp_replace(
          COALESCE(auth.jwt()->>'iss', ''),
          '/auth/v1/?$',
          ''
        ),
        ''
      )
    );
    v_token := public.fn_lire_secret_cron();
    IF v_token IS NOT NULL AND v_url IS NOT NULL THEN
      PERFORM net.http_post(
        url := v_url || '/functions/v1/notify-support',
        headers := pg_catalog.jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_token
        ),
        body := pg_catalog.jsonb_build_object(
          'sujet', v_sujet,
          'corps', v_corps,
          'expediteur_nom', v_nom,
          'expediteur_email', v_email,
          'source', 'Contact ' || COALESCE(v_role, ''),
          'lien', '/admin/messages-contact'
        )
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN pg_catalog.jsonb_build_object(
    'success', true,
    'message_id', v_msg_id
  );
END;
$_$;


