CREATE OR REPLACE FUNCTION "public"."fn_envoyer_otp_signature"("p_contrat_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid(); v_contrat RECORD; v_role text; v_otp text; v_otp_hash text;
  v_telephone text; v_sig_existante RECORD; v_sms_count int; v_sms_window_start timestamptz;
  v_ip inet; v_rate_check jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE', 'error', 'Non authentifié');
  END IF;
  v_ip := NULLIF(current_setting('request.headers', true)::jsonb->>'x-forwarded-for', '')::inet;
  v_rate_check := public.fn_check_rate_limit_ip_signature(v_ip);
  IF NOT (v_rate_check->>'allowed')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TROP_DE_SMS_IP',
      'error', 'Trop de demandes de signature depuis votre IP. Réessayez dans 1h.',
      'envois_courant', v_rate_check->>'envois_courant', 'max', v_rate_check->>'max');
  END IF;
  SELECT cm.id, cm.soignant_id, cm.etablissement_id, cm.contenu_html, cm.statut,
         cm.signature_soignant, cm.signature_etablissement
  INTO v_contrat FROM public.contrats_mission cm WHERE cm.id = p_contrat_id;
  IF v_contrat IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CONTRAT_INTROUVABLE', 'error', 'Contrat introuvable');
  END IF;
  IF v_contrat.statut IN ('ANNULE', 'EXPIRE') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CONTRAT_INACTIF',
      'error', 'Ce contrat n''est plus actif (statut : ' || v_contrat.statut || ').');
  END IF;
  IF v_contrat.statut = 'SIGNE_COMPLET' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CONTRAT_DEJA_COMPLET',
      'error', 'Ce contrat est déjà entièrement signé.');
  END IF;
  IF v_contrat.soignant_id = v_uid THEN
    v_role := 'soignant';
    SELECT telephone INTO v_telephone FROM public.soignants WHERE id = v_uid;
  ELSIF v_contrat.etablissement_id = v_uid OR mon_etablissement_id() = v_contrat.etablissement_id THEN
    v_role := 'etablissement';
    SELECT telephone_contact INTO v_telephone FROM public.etablissements WHERE id = v_contrat.etablissement_id;
  ELSE
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE', 'error', 'Non autorisé à signer ce contrat');
  END IF;
  IF v_role = 'etablissement' AND v_contrat.signature_soignant IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ETAB_AVANT_SOIGNANT',
      'error', 'Le soignant doit signer en premier. Vous serez notifié(e) par email dès qu''il aura signé.');
  END IF;
  IF v_telephone IS NULL OR v_telephone = '' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TELEPHONE_MANQUANT',
      'error', 'Numéro de téléphone manquant. Mettez à jour votre profil avant de signer.');
  END IF;
  SELECT sms_envoyes_count, sms_premier_envoi_a, statut_signature INTO v_sig_existante
  FROM public.signatures_contrats WHERE contrat_id = p_contrat_id AND signataire_role = v_role;
  IF FOUND THEN
    IF v_sig_existante.statut_signature = 'signe' THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_SIGNE', 'error', 'Vous avez déjà signé ce contrat.');
    END IF;
    IF v_sig_existante.sms_premier_envoi_a IS NULL OR v_sig_existante.sms_premier_envoi_a < NOW() - INTERVAL '24 hours' THEN
      v_sms_count := 1; v_sms_window_start := NOW();
    ELSE
      v_sms_count := COALESCE(v_sig_existante.sms_envoyes_count, 0) + 1;
      v_sms_window_start := v_sig_existante.sms_premier_envoi_a;
      IF v_sms_count > 3 THEN
        RETURN jsonb_build_object('success', false, 'error_code', 'TROP_DE_SMS',
          'error', 'Trop de SMS envoyés (3 max / 24h).',
          'sms_envoyes', v_sms_count - 1,
          'reset_le', (v_sig_existante.sms_premier_envoi_a + INTERVAL '24 hours')::text);
      END IF;
    END IF;
  ELSE
    v_sms_count := 1; v_sms_window_start := NOW();
  END IF;
  v_otp := lpad(floor(random() * 1000000)::text, 6, '0');
  v_otp_hash := encode(digest(v_otp || '|' || p_contrat_id::text || '|' || v_uid::text, 'sha256'), 'hex');
  INSERT INTO public.signatures_contrats (
    contrat_id, signataire_user_id, signataire_role,
    otp_envoye_a, otp_code_hash, statut_signature, audit_trail,
    sms_envoyes_count, sms_premier_envoi_a
  ) VALUES (
    p_contrat_id, v_uid, v_role, NOW(), v_otp_hash, 'otp_envoye',
    jsonb_build_object('otp_envoye_le', NOW()::text, 'sms_count', v_sms_count, 'ip', v_ip::text),
    v_sms_count, v_sms_window_start
  )
  ON CONFLICT (contrat_id, signataire_role) DO UPDATE SET
    otp_envoye_a = NOW(), otp_code_hash = EXCLUDED.otp_code_hash,
    otp_tentatives = 0, statut_signature = 'otp_envoye',
    sms_envoyes_count = v_sms_count, sms_premier_envoi_a = v_sms_window_start,
    modifie_le = NOW(),
    audit_trail = COALESCE(signatures_contrats.audit_trail, '{}'::jsonb) ||
      jsonb_build_object('otp_renvoye_le', NOW()::text, 'sms_count', v_sms_count, 'ip', v_ip::text);
  BEGIN
    PERFORM net.http_post(
      url := 'https://flripxtsyegjshnhzjkz.supabase.co/functions/v1/send-sms',
      headers := jsonb_build_object('Content-Type', 'application/json',
        'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1)),
      body := jsonb_build_object('telephone', v_telephone, 'type', 'OTP_SIGNATURE',
        'contenu', 'Code de signature Jolene : ' || v_otp || ' (valide 10 min). Ne le partagez avec personne.',
        'destinataire_id', v_uid, 'prefix_type', 'SIGNATURE')
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('success', true, 'role', v_role,
    'telephone_masked', regexp_replace(v_telephone, '\d(?=\d{2})', '*', 'g'),
    'expire_dans_minutes', 10,
    'sms_envoyes', v_sms_count, 'sms_restants', GREATEST(0, 3 - v_sms_count));
END;
$$;


ALTER FUNCTION "public"."fn_envoyer_otp_signature"("p_contrat_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_envoyer_otp_telephone"("p_telephone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_telephone text;
  v_code text;
  v_code_hash text;
  v_otp_id uuid;
  v_count_24h integer;
  v_cible_type text;
  v_cible_id uuid;
  v_etablissement_id uuid;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'NON_AUTHENTIFIE',
      'error', 'Session inactive.'
    );
  END IF;

  v_telephone := regexp_replace(btrim(COALESCE(p_telephone, '')), '[\s().-]+', '', 'g');
  IF v_telephone LIKE '00%' THEN v_telephone := '+' || substring(v_telephone FROM 3); END IF;
  IF v_telephone LIKE '0%' THEN v_telephone := '+33' || substring(v_telephone FROM 2); END IF;
  IF v_telephone !~ '^\+[1-9][0-9]{7,14}$' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'TELEPHONE_INVALIDE',
      'error', 'Téléphone invalide. Format attendu : +33 6 12 34 56 78.'
    );
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.soignants
    WHERE id = v_uid AND supprime_le IS NULL
  ) THEN
    v_cible_type := 'SOIGNANT';
    v_cible_id := v_uid;
  ELSE
    v_etablissement_id := public.mon_etablissement_id();
    IF v_etablissement_id IS NULL
       OR NOT public.fn_a_permission_etablissement('profil_etab', v_etablissement_id) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error_code', 'PROFIL_INTROUVABLE',
        'error', 'Aucun profil autorisé pour vérifier ce numéro.'
      );
    END IF;
    v_cible_type := 'ETABLISSEMENT';
    v_cible_id := v_etablissement_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('otp-phone:' || v_uid::text, 0));
  PERFORM public.fn_purger_codes_otp_expires();

  SELECT count(*) INTO v_count_24h
  FROM public.otps_telephone
  WHERE user_id = v_uid
    AND cree_le > now() - interval '24 hours';
  IF v_count_24h >= 3 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'RATE_LIMIT',
      'error', 'Trop d envois (3 SMS par 24 h maximum). Réessayez plus tard.'
    );
  END IF;

  -- Rend immédiatement inutilisables les codes précédents de ce compte.
  UPDATE public.otps_telephone
  SET utilise = true
  WHERE user_id = v_uid AND utilise IS FALSE;

  v_code := public.fn_generer_code_otp_6_chiffres();
  v_code_hash := extensions.crypt(v_code, extensions.gen_salt('bf', 10));

  INSERT INTO public.otps_telephone (
    user_id, telephone, code_hash, cible_type, cible_id
  ) VALUES (
    v_uid, v_telephone, v_code_hash, v_cible_type, v_cible_id
  )
  RETURNING id INTO v_otp_id;

  IF v_cible_type = 'SOIGNANT' THEN
    UPDATE public.soignants
    SET telephone_en_attente_verification = v_telephone,
        modifie_le = now()
    WHERE id = v_cible_id;
  ELSE
    UPDATE public.etablissements
    SET telephone_en_attente_verification = v_telephone,
        modifie_le = now()
    WHERE id = v_cible_id;
  END IF;

  INSERT INTO public.externalisation_actions (
    type_action, payload, source, source_id
  ) VALUES (
    'SMS_NOTIF',
    jsonb_build_object(
      'telephone', v_telephone,
      'type', 'OTP_VERIFICATION_TELEPHONE',
      'destinataire_id', v_uid,
      'cible_type', v_cible_type,
      'cible_id', v_cible_id,
      'data', jsonb_build_object('code', v_code, 'expire_min', 10)
    ),
    'AUTRE',
    v_otp_id
  );

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := v_cible_type,
    p_action := 'SYSTEM',
    p_type_ressource := 'otp_telephone',
    p_id_ressource := v_otp_id,
    p_details := jsonb_build_object(
      'evenement', 'OTP_TELEPHONE_ENVOYE',
      'telephone_last4', right(regexp_replace(v_telephone, '[^0-9]', '', 'g'), 4),
      'cible_type', v_cible_type,
      'cible_id', v_cible_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'otp_id', v_otp_id,
    'expire_min', 10,
    'telephone_last4', right(regexp_replace(v_telephone, '[^0-9]', '', 'g'), 4)
  );
END;
$_$;


ALTER FUNCTION "public"."fn_envoyer_otp_telephone"("p_telephone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_envoyer_rappels_litiges"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_litige RECORD;
  v_destinataire_id UUID;
  v_destinataire_type TEXT;
  v_age_h INT;
  v_rappel_key TEXT;
  v_rappel_libelle TEXT;
  v_nb_rappels INT := 0;
BEGIN
  FOR v_litige IN
    SELECT l.id, l.mission_id, l.soignant_id, l.etablissement_id,
           l.initie_par, l.cree_le, l.reponse, l.type_litige,
           l.derniers_rappels_envoyes
      FROM public.litiges l
     WHERE l.statut IN ('OUVERT', 'EN_DISCUSSION')
       AND NOT l.est_informatif
       AND l.escalade_auto_le IS NULL
       AND (l.reponse IS NULL OR length(trim(l.reponse)) = 0)
  LOOP
    v_age_h := EXTRACT(EPOCH FROM NOW() - v_litige.cree_le)::INT / 3600;

    IF v_age_h >= 120 AND NOT (v_litige.derniers_rappels_envoyes ? 'J+5') THEN
      v_rappel_key := 'J+5';
      v_rappel_libelle := 'Rappel litige 5 jours — dernière relance';
    ELSIF v_age_h >= 72 AND NOT (v_litige.derniers_rappels_envoyes ? 'J+3') THEN
      v_rappel_key := 'J+3';
      v_rappel_libelle := 'Rappel litige 3 jours';
    ELSIF v_age_h >= 24 AND NOT (v_litige.derniers_rappels_envoyes ? 'J+1') THEN
      v_rappel_key := 'J+1';
      v_rappel_libelle := 'Rappel litige 1 jour';
    ELSE
      CONTINUE;
    END IF;

    IF v_litige.initie_par = 'SOIGNANT' THEN
      v_destinataire_id := v_litige.etablissement_id;
      v_destinataire_type := 'ETABLISSEMENT';
    ELSE
      v_destinataire_id := v_litige.soignant_id;
      v_destinataire_type := 'SOIGNANT';
    END IF;

    IF v_destinataire_id IS NULL THEN
      CONTINUE;
    END IF;

    PERFORM public.fn_litige_push_notification(
      v_destinataire_id,
      v_destinataire_type,
      'LITIGE_RAPPEL_' || REPLACE(v_rappel_key, '+', ''),
      v_rappel_libelle,
      'Un litige est en attente de votre réponse depuis ' || v_age_h || 'h. Répondez pour éviter l''escalade.',
      v_litige.id,
      jsonb_build_object(
        'type_litige', v_litige.type_litige,
        'mission_id', v_litige.mission_id,
        'age_heures', v_age_h,
        'rappel', v_rappel_key
      )
    );

    UPDATE public.litiges
       SET derniers_rappels_envoyes = derniers_rappels_envoyes
         || jsonb_build_object(v_rappel_key, NOW())
     WHERE id = v_litige.id;

    v_nb_rappels := v_nb_rappels + 1;
  END LOOP;

  RETURN jsonb_build_object('rappels_envoyes', v_nb_rappels);
END;
$$;


ALTER FUNCTION "public"."fn_envoyer_rappels_litiges"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_envoyer_rappels_litiges"() IS 'Cron : envoie les rappels J+1/J+3/J+5 aux parties sans réponse. Idempotence via derniers_rappels_envoyes.';



CREATE OR REPLACE FUNCTION "public"."fn_envoyer_rappels_notation_j1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_url TEXT;
  v_token TEXT;
  v_mission RECORD;
  v_count_etab INT := 0;
  v_count_soignant INT := 0;
  v_send_email_called BOOLEAN;
BEGIN
  IF NOT (est_admin() OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Accès refusé');
  END IF;

  BEGIN
    v_url := 'https://flripxtsyegjshnhzjkz.supabase.co';
    v_token := public.fn_lire_secret_cron();
  EXCEPTION WHEN OTHERS THEN
    v_url := NULL; v_token := NULL;
  END;

  FOR v_mission IN
    SELECT m.id, m.intitule, m.fin_le, m.etablissement_id, m.soignant_assigne_id
    FROM missions m
    WHERE m.statut = 'TERMINEE'
      AND m.fin_le >= NOW() - INTERVAL '48 hours'
      AND m.fin_le < NOW() - INTERVAL '24 hours'
      AND m.soignant_assigne_id IS NOT NULL
  LOOP
    -- Côté étab
    IF NOT EXISTS (SELECT 1 FROM notifications_notation_j1 WHERE mission_id = v_mission.id AND sens = 'ETAB_VERS_SOIGNANT')
       AND NOT EXISTS (SELECT 1 FROM notations_missions WHERE mission_id = v_mission.id AND sens = 'ETAB_VERS_SOIGNANT')
       AND public.fn_doit_notifier(v_mission.etablissement_id, 'NOTATION_RAPPEL'::type_evenement_notification, 'EMAIL'::canal_notification) THEN
      v_send_email_called := false;
      IF v_url IS NOT NULL AND v_token IS NOT NULL THEN
        BEGIN
          PERFORM net.http_post(
            url := v_url || '/functions/v1/send-email',
            headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_token),
            body := jsonb_build_object(
              'type', 'RAPPEL_NOTATION_ETAB',
              'destinataire_id', v_mission.etablissement_id,
              'data', jsonb_build_object('mission_id', v_mission.id, 'mission_intitule', v_mission.intitule, 'fin_le', v_mission.fin_le)
            )
          );
          v_send_email_called := true;
        EXCEPTION WHEN OTHERS THEN NULL; END;
      END IF;

      IF v_send_email_called THEN
        INSERT INTO notifications_notation_j1 (mission_id, sens, destinataire_id)
        VALUES (v_mission.id, 'ETAB_VERS_SOIGNANT', v_mission.etablissement_id)
        ON CONFLICT (mission_id, sens) DO NOTHING;

        PERFORM public.fn_ecrire_audit_safe(
          p_acteur_id := v_mission.etablissement_id, p_type_acteur := 'SYSTEME',
          p_action := 'RAPPEL_NOTATION_J1_ENVOYE', p_type_ressource := 'mission', p_id_ressource := v_mission.id,
          p_details := jsonb_build_object('sens', 'ETAB_VERS_SOIGNANT', 'send_email_called', true)
        );
        v_count_etab := v_count_etab + 1;
      END IF;
    END IF;

    -- Côté soignant
    IF NOT EXISTS (SELECT 1 FROM notifications_notation_j1 WHERE mission_id = v_mission.id AND sens = 'SOIGNANT_VERS_ETAB')
       AND NOT EXISTS (SELECT 1 FROM notations_missions WHERE mission_id = v_mission.id AND sens = 'SOIGNANT_VERS_ETAB')
       AND public.fn_doit_notifier(v_mission.soignant_assigne_id, 'NOTATION_RAPPEL'::type_evenement_notification, 'EMAIL'::canal_notification) THEN
      v_send_email_called := false;
      IF v_url IS NOT NULL AND v_token IS NOT NULL THEN
        BEGIN
          PERFORM net.http_post(
            url := v_url || '/functions/v1/send-email',
            headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_token),
            body := jsonb_build_object(
              'type', 'RAPPEL_NOTATION_SOIGNANT',
              'destinataire_id', v_mission.soignant_assigne_id,
              'data', jsonb_build_object('mission_id', v_mission.id, 'mission_intitule', v_mission.intitule, 'fin_le', v_mission.fin_le)
            )
          );
          v_send_email_called := true;
        EXCEPTION WHEN OTHERS THEN NULL; END;
      END IF;

      IF v_send_email_called THEN
        INSERT INTO notifications_notation_j1 (mission_id, sens, destinataire_id)
        VALUES (v_mission.id, 'SOIGNANT_VERS_ETAB', v_mission.soignant_assigne_id)
        ON CONFLICT (mission_id, sens) DO NOTHING;

        PERFORM public.fn_ecrire_audit_safe(
          p_acteur_id := v_mission.soignant_assigne_id, p_type_acteur := 'SYSTEME',
          p_action := 'RAPPEL_NOTATION_J1_ENVOYE', p_type_ressource := 'mission', p_id_ressource := v_mission.id,
          p_details := jsonb_build_object('sens', 'SOIGNANT_VERS_ETAB', 'send_email_called', true)
        );
        v_count_soignant := v_count_soignant + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'count_etab', v_count_etab, 'count_soignant', v_count_soignant);
END;
$$;


ALTER FUNCTION "public"."fn_envoyer_rappels_notation_j1"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escalade_remplacement_non_pourvu"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m record;
  v_s uuid;
  v_url text := 'https://flripxtsyegjshnhzjkz.supabase.co';
  v_token text;
  v_corps text;
  v_escalades integer := 0;
  v_notifies integer := 0;
  v_notifies_mission integer;
BEGIN
  BEGIN
    v_token := (
      SELECT decrypted_secret FROM vault.decrypted_secrets
       WHERE name = 'service_role_key' LIMIT 1
    );
  EXCEPTION WHEN OTHERS THEN v_token := NULL;
  END;

  FOR v_m IN
    SELECT m.*, e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng,
           e.adresse_ville AS etab_ville
      FROM public.missions m
      JOIN public.etablissements e ON e.id = m.etablissement_id
     WHERE m.remplacement_de_mission_id IS NOT NULL
       AND m.est_urgente = true
       AND m.statut = 'OUVERTE'
       AND m.cree_le < now() - interval '20 minutes'
       AND m.cree_le > now() - interval '4 hours'
       AND m.debut_le > now() - interval '15 minutes'
       AND NOT EXISTS (
         SELECT 1 FROM public.candidatures c WHERE c.mission_id = m.id
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.notifications n
          WHERE n.type_destinataire = 'ADMIN' AND n.type = 'SYSTEM'
            AND n.titre LIKE 'Remplacement non pourvu%'
            AND n.id_ressource = m.id
            AND n.cree_le > now() - interval '4 hours'
       )
  LOOP
    v_escalades := v_escalades + 1;
    v_notifies_mission := 0;
    v_corps := public.fn_html_escape(v_m.intitule) || ' — ' ||
      COALESCE(v_m.etab_ville, '') || ', URGENT à ' ||
      COALESCE(v_m.taux_horaire_base::text, '?') ||
      ' €/h. Toujours disponible, acceptez en 1 clic !';

    FOR v_s IN
      SELECT s.id
        FROM public.soignants s
       WHERE public.fn_soignant_eligible_mission(s.id, v_m.id, true)
         AND COALESCE(s.statut_compte::text, 'ACTIF') = 'ACTIF'
         AND NOT public.fn_est_exclu(s.id, v_m.etablissement_id)
         AND (
           s.adresse_lat IS NULL OR v_m.etab_lat IS NULL
           OR public.fn_haversine_distance_m(
             s.adresse_lat, s.adresse_lng, v_m.etab_lat, v_m.etab_lng
           ) <= 80000
         )
         AND NOT EXISTS (
           SELECT 1 FROM public.notifications n2
            WHERE n2.destinataire_id = s.id
              AND n2.type_ressource = 'mission' AND n2.id_ressource = v_m.id
         )
       LIMIT 300
    LOOP
      INSERT INTO public.notifications(
        destinataire_id, type, titre, corps, lien, type_destinataire,
        type_ressource, id_ressource
      ) VALUES (
        v_s, 'POOL_URGENCE', '🚨 Remplacement urgent — toujours à pourvoir',
        v_corps, '/soignant/missions/' || v_m.id,
        'SOIGNANT', 'mission', v_m.id
      );
      v_notifies_mission := v_notifies_mission + 1;
      IF v_token IS NOT NULL THEN
        BEGIN
          PERFORM net.http_post(
            url := v_url || '/functions/v1/send-push',
            headers := jsonb_build_object(
              'Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token
            ),
            body := jsonb_build_object(
              'destinataire_id', v_s, 'type_evenement', 'MISSION_URGENTE',
              'titre', '🚨 Remplacement urgent à pourvoir', 'corps', v_corps,
              'data', jsonb_build_object(
                'mission_id', v_m.id, 'lien', '/soignant/pool-urgence'
              )
            )
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END IF;
    END LOOP;
    v_notifies := v_notifies + v_notifies_mission;

    BEGIN
      INSERT INTO public.notifications(
        destinataire_id, type_destinataire, type, titre, corps, lien,
        type_ressource, id_ressource
      )
      SELECT uid, 'ADMIN', 'SYSTEM',
        'Remplacement non pourvu — action requise 🚨',
        'La mission de remplacement « ' || public.fn_html_escape(v_m.intitule) ||
        ' » (' || COALESCE(v_m.etab_ville, '') ||
        ') reste sans candidat 20 min après diffusion. Rayon élargi à 80 km ; une intervention manuelle est conseillée.',
        '/admin/missions', 'mission', v_m.id
      FROM public.fn_list_admin_user_ids() AS admins(uid);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    PERFORM public.fn_ecrire_audit_safe(
      p_acteur_id := v_m.etablissement_id,
      p_type_acteur := 'SYSTEME',
      p_action := 'REMPLACEMENT_ESCALADE',
      p_type_ressource := 'mission',
      p_id_ressource := v_m.id,
      p_details := jsonb_build_object(
        'notifies_elargis', v_notifies_mission,
        'rayon_km', 80,
        'filtre', 'fn_soignant_eligible_mission'
      )
    );
  END LOOP;
  RETURN jsonb_build_object(
    'success', true, 'escalades', v_escalades, 'notifies', v_notifies
  );
END;
$$;


ALTER FUNCTION "public"."fn_escalade_remplacement_non_pourvu"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_confirmer_payout"("p_paiement_escrow_id" "uuid", "p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_paye_le" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.paiements_escrow%ROWTYPE;
BEGIN
  IF COALESCE(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  SELECT pe.*
    INTO v_row
  FROM public.paiements_escrow pe
  JOIN public.stripe_connect_onboarding sco
    ON sco.soignant_id = pe.soignant_id
   AND sco.stripe_account_id = p_stripe_account_id
  WHERE pe.id = p_paiement_escrow_id
    AND pe.stripe_payout_id = p_stripe_payout_id
  FOR UPDATE OF pe;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Payout escrow incohérent' USING ERRCODE = 'P0001';
  END IF;

  IF v_row.statut = 'PAYE' THEN
    RETURN false;
  END IF;

  IF v_row.statut <> 'RELEASE_PLANIFIE' THEN
    RAISE EXCEPTION 'Transition payout escrow invalide depuis %', v_row.statut
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.paiements_escrow
  SET statut = 'PAYE',
      paye_le = COALESCE(p_paye_le, now()),
      erreur = NULL,
      modifie_le = now()
  WHERE id = v_row.id;

  UPDATE public.escrow_release_queue
  SET statut = 'TRAITE',
      traite_le = now(),
      erreur = NULL
  WHERE paiement_escrow_id = v_row.id
    AND statut IN ('EN_COURS', 'EN_ATTENTE');

  PERFORM public.fn_escrow_incrementer_confiance(v_row.etablissement_id);
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_confirmer_payout"("p_paiement_escrow_id" "uuid", "p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_paye_le" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."paiements_escrow" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "mission_id" "uuid" NOT NULL,
    "etablissement_id" "uuid" NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "montant_total_cents" integer NOT NULL,
    "commission_cents" integer NOT NULL,
    "honoraires_cents" integer NOT NULL,
    "methode_debit" "text",
    "stripe_payment_intent_id" "text",
    "stripe_charge_id" "text",
    "stripe_payout_id" "text",
    "statut" "text" DEFAULT 'INITIE'::"text" NOT NULL,
    "available_on" timestamp with time zone,
    "relance_prevue_le" timestamp with time zone,
    "erreur" "text",
    "initie_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "debite_le" timestamp with time zone,
    "disponible_le" timestamp with time zone,
    "release_planifie_le" timestamp with time zone,
    "paye_le" timestamp with time zone,
    "cree_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "modifie_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "debit_prevu_le" timestamp with time zone,
    "premiere_mission_etab" boolean DEFAULT false NOT NULL,
    "tentatives_debit" integer DEFAULT 0 NOT NULL,
    "derniere_tentative_le" timestamp with time zone,
    CONSTRAINT "paiements_escrow_commission_cents_check" CHECK (("commission_cents" >= 0)),
    CONSTRAINT "paiements_escrow_honoraires_cents_check" CHECK (("honoraires_cents" > 0)),
    CONSTRAINT "paiements_escrow_methode_debit_check" CHECK (("methode_debit" = ANY (ARRAY['SEPA'::"text", 'CARTE'::"text", 'VIREMENT_INSTANTANE'::"text"]))),
    CONSTRAINT "paiements_escrow_montant_total_cents_check" CHECK (("montant_total_cents" > 0)),
    CONSTRAINT "paiements_escrow_statut_check" CHECK (("statut" = ANY (ARRAY['INITIE'::"text", 'DEBITE'::"text", 'DISPONIBLE'::"text", 'RELEASE_PLANIFIE'::"text", 'PAYE'::"text", 'ECHOUE'::"text", 'REMBOURSE_EN_COURS'::"text", 'REMBOURSE'::"text", 'DISPUTE'::"text"])))
);


ALTER TABLE "public"."paiements_escrow" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_debits_a_echeance"("p_limit" integer DEFAULT 50) RETURNS SETOF "public"."paiements_escrow"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT pe.*
  FROM public.paiements_escrow pe
  JOIN public.missions m
    ON m.id = pe.mission_id
   AND m.etablissement_id = pe.etablissement_id
   AND m.soignant_assigne_id = pe.soignant_id
  WHERE pe.statut = 'INITIE'
    AND pe.debit_prevu_le <= now()
    AND pe.tentatives_debit < 3
    AND m.statut IN ('ASSIGNEE', 'EN_COURS')
    AND COALESCE(m.est_arret_maladie, false) IS FALSE
    AND NOT EXISTS (
      SELECT 1 FROM public.missions r
      WHERE r.remplacement_de_mission_id = m.id
    )
  ORDER BY pe.debit_prevu_le, pe.id
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."fn_escrow_debits_a_echeance"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_echouer_payout"("p_paiement_escrow_id" "uuid", "p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_detail" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.paiements_escrow%ROWTYPE;
BEGIN
  IF COALESCE(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  SELECT pe.*
    INTO v_row
  FROM public.paiements_escrow pe
  JOIN public.stripe_connect_onboarding sco
    ON sco.soignant_id = pe.soignant_id
   AND sco.stripe_account_id = p_stripe_account_id
  WHERE pe.id = p_paiement_escrow_id
    AND pe.stripe_payout_id = p_stripe_payout_id
  FOR UPDATE OF pe;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Payout escrow incohérent' USING ERRCODE = 'P0001';
  END IF;

  IF v_row.statut = 'ECHOUE' THEN
    RETURN false;
  END IF;

  IF v_row.statut NOT IN ('RELEASE_PLANIFIE', 'PAYE') THEN
    RAISE EXCEPTION 'Transition échec payout invalide depuis %', v_row.statut
      USING ERRCODE = 'P0001';
  END IF;

  PERFORM public.fn_escrow_marquer_incident(
    v_row.id,
    'ECHEC',
    left(COALESCE(p_detail, 'payout Stripe échoué'), 500)
  );

  UPDATE public.escrow_release_queue
  SET statut = 'ECHEC',
      traite_le = now(),
      erreur = left(COALESCE(p_detail, 'payout Stripe échoué'), 500)
  WHERE paiement_escrow_id = v_row.id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_echouer_payout"("p_paiement_escrow_id" "uuid", "p_stripe_payout_id" "text", "p_stripe_account_id" "text", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_enregistrer_exposition"("p_paiement_escrow_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row paiements_escrow%ROWTYPE;
  v_fenetre_jours integer;
BEGIN
  SELECT * INTO v_row FROM paiements_escrow WHERE id = p_paiement_escrow_id;
  IF v_row.id IS NULL THEN
    RETURN;
  END IF;

  v_fenetre_jours := public.fn_param_num('escrow_fenetre_remboursable_jours', 56)::integer;

  INSERT INTO escrow_exposition_releases (
    etablissement_id, paiement_escrow_id, montant_cents,
    debite_le, expire_le, statut
  ) VALUES (
    v_row.etablissement_id, v_row.id, v_row.honoraires_cents,
    now(), now() + make_interval(days => v_fenetre_jours), 'ACTIF'
  )
  ON CONFLICT (paiement_escrow_id) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_enregistrer_exposition"("p_paiement_escrow_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_etab_eligible"("p_etablissement_id" "uuid", "p_montant_cents" integer DEFAULT 0) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_gele boolean := false;
BEGIN
  SELECT gele INTO v_gele
  FROM escrow_etablissement_etat
  WHERE etablissement_id = p_etablissement_id;

  IF COALESCE(v_gele, false) THEN
    RETURN false;
  END IF;

  RETURN public.fn_escrow_exposition_courante(p_etablissement_id)
         + COALESCE(p_montant_cents, 0)
         <= public.fn_escrow_plafond_cents(p_etablissement_id);
END;
$$;


ALTER FUNCTION "public"."fn_escrow_etab_eligible"("p_etablissement_id" "uuid", "p_montant_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_expirer_expositions"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE escrow_exposition_releases
  SET statut = 'EXPIRE'
  WHERE statut = 'ACTIF' AND expire_le < now();
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_expirer_expositions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_exposition_courante"("p_etablissement_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(SUM(montant_cents), 0)::integer
  FROM escrow_exposition_releases
  WHERE etablissement_id = p_etablissement_id AND statut = 'ACTIF';
$$;


ALTER FUNCTION "public"."fn_escrow_exposition_courante"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_geler_etablissement"("p_etablissement_id" "uuid", "p_raison" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO escrow_etablissement_etat (etablissement_id, gele, gele_le, gele_raison, modifie_le)
  VALUES (p_etablissement_id, true, now(), p_raison, now())
  ON CONFLICT (etablissement_id) DO UPDATE
    SET gele = true,
        gele_le = COALESCE(escrow_etablissement_etat.gele_le, now()),
        gele_raison = EXCLUDED.gele_raison,
        modifie_le = now();

  PERFORM public.fn_ecrire_audit_safe(
    '00000000-0000-0000-0000-000000000000'::uuid, 'SYSTEME',
    'ESCROW_ETAB_GELE', 'etablissement', p_etablissement_id,
    NULL, jsonb_build_object('raison', p_raison), NULL, 'fn_escrow_geler_etablissement'
  );
END;
$$;


ALTER FUNCTION "public"."fn_escrow_geler_etablissement"("p_etablissement_id" "uuid", "p_raison" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_incrementer_confiance"("p_etablissement_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO escrow_etablissement_etat (etablissement_id, missions_sans_incident, modifie_le)
  VALUES (p_etablissement_id, 1, now())
  ON CONFLICT (etablissement_id) DO UPDATE
    SET missions_sans_incident = CASE
          WHEN escrow_etablissement_etat.gele THEN escrow_etablissement_etat.missions_sans_incident
          ELSE escrow_etablissement_etat.missions_sans_incident + 1
        END,
        modifie_le = now();
END;
$$;


ALTER FUNCTION "public"."fn_escrow_incrementer_confiance"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_marquer_echec_debit"("p_paiement_escrow_id" "uuid", "p_detail" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.paiements_escrow%ROWTYPE;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  SELECT pe.*
    INTO v_row
  FROM public.paiements_escrow pe
  WHERE pe.id = p_paiement_escrow_id
    AND pe.statut = 'INITIE'
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.paiements_escrow
  SET statut = 'ECHOUE',
      erreur = left(p_detail, 500),
      relance_prevue_le = now() + interval '3 days',
      modifie_le = now()
  WHERE id = v_row.id
    AND statut = 'INITIE';

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  PERFORM public.fn_escrow_geler_etablissement(
    v_row.etablissement_id,
    format(
      'ECHEC escrow mission %s : %s',
      v_row.mission_id,
      COALESCE(left(p_detail, 500), '')
    )
  );

  UPDATE public.escrow_etablissement_etat
  SET missions_sans_incident = 0,
      modifie_le = now()
  WHERE etablissement_id = v_row.etablissement_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_marquer_echec_debit"("p_paiement_escrow_id" "uuid", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_marquer_incident"("p_paiement_escrow_id" "uuid", "p_type_incident" "text", "p_detail" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row paiements_escrow%ROWTYPE;
  v_nouveau_statut text;
BEGIN
  SELECT * INTO v_row FROM paiements_escrow WHERE id = p_paiement_escrow_id;
  IF v_row.id IS NULL THEN
    RETURN;
  END IF;

  v_nouveau_statut := CASE WHEN p_type_incident = 'DISPUTE' THEN 'DISPUTE' ELSE 'ECHOUE' END;

  UPDATE paiements_escrow
  SET statut = v_nouveau_statut,
      erreur = p_detail,
      -- Relance J+3 uniquement sur un échec de débit (pas sur une dispute,
      -- qui suit son propre circuit contentieux).
      relance_prevue_le = CASE WHEN p_type_incident = 'ECHEC' THEN now() + interval '3 days' ELSE relance_prevue_le END,
      modifie_le = now()
  WHERE id = p_paiement_escrow_id;

  -- Gel du ⚡ de l'établissement au premier incident (A2). Réinitialise aussi
  -- le compteur de confiance.
  PERFORM public.fn_escrow_geler_etablissement(
    v_row.etablissement_id,
    format('%s escrow mission %s : %s', p_type_incident, v_row.mission_id, COALESCE(p_detail, ''))
  );

  UPDATE escrow_etablissement_etat
  SET missions_sans_incident = 0, modifie_le = now()
  WHERE etablissement_id = v_row.etablissement_id;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_marquer_incident"("p_paiement_escrow_id" "uuid", "p_type_incident" "text", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_plafond_cents"("p_etablissement_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sans_incident integer := 0;
BEGIN
  SELECT missions_sans_incident INTO v_sans_incident
  FROM escrow_etablissement_etat
  WHERE etablissement_id = p_etablissement_id;

  IF COALESCE(v_sans_incident, 0) >= public.fn_param_num('escrow_missions_confiance_seuil', 3) THEN
    RETURN public.fn_param_num('escrow_plafond_confiance_cents', 500000)::integer;
  END IF;
  RETURN public.fn_param_num('escrow_plafond_base_cents', 200000)::integer;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_plafond_cents"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_releases_a_traiter"("p_limit" integer DEFAULT 50) RETURNS TABLE("queue_id" "uuid", "paiement_escrow_id" "uuid", "mission_id" "uuid", "soignant_id" "uuid", "etablissement_id" "uuid", "honoraires_cents" integer, "escrow_statut" "text", "tentatives" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT q.id, q.paiement_escrow_id, q.mission_id,
         pe.soignant_id, pe.etablissement_id, pe.honoraires_cents,
         pe.statut, q.tentatives
  FROM public.escrow_release_queue q
  JOIN public.paiements_escrow pe
    ON pe.id = q.paiement_escrow_id
   AND pe.mission_id = q.mission_id
  LEFT JOIN public.missions m ON m.id = pe.mission_id
  WHERE q.statut IN ('EN_ATTENTE', 'EN_COURS')
    AND q.prochaine_tentative_le <= now()
    AND (
      pe.statut = 'RELEASE_PLANIFIE'
      OR (
        pe.statut = 'DEBITE'
        AND q.tentatives < 5
        AND m.statut = 'TERMINEE'
        AND m.soignant_assigne_id = pe.soignant_id
        AND m.etablissement_id = pe.etablissement_id
        AND COALESCE(m.est_arret_maladie, false) IS FALSE
        AND NOT EXISTS (
          SELECT 1 FROM public.missions r
          WHERE r.remplacement_de_mission_id = m.id
        )
        AND EXISTS (
          SELECT 1 FROM public.presences p
          WHERE p.mission_id = m.id
            AND COALESCE(p.valide_par_etablissement, false) IS TRUE
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.presences p
          WHERE p.mission_id = m.id
            AND COALESCE(p.valide_par_etablissement, false) IS FALSE
            AND (p.pointage_depart_le IS NOT NULL OR p.motif_litige IS NOT NULL)
        )
      )
    )
  ORDER BY q.prochaine_tentative_le, q.id
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."fn_escrow_releases_a_traiter"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_escrow_releases_a_traiter"("p_limit" integer) IS 'Retourne les releases DEBITE à initier et les RELEASE_PLANIFIE/leases EN_COURS à réconcilier sans double payout.';



CREATE OR REPLACE FUNCTION "public"."fn_escrow_rembourser"("p_paiement_escrow_id" "uuid", "p_montant_honoraires_cts" integer, "p_annulation_totale" boolean DEFAULT false, "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.paiements_escrow%ROWTYPE;
  v_queue public.stripe_refunds_queue%ROWTYPE;
  v_absorbe boolean;
  v_reverse boolean;
  v_fee_cts integer;
  v_montant_total integer;
  v_rows integer;
BEGIN
  SELECT pe.*
    INTO v_row
    FROM public.paiements_escrow pe
   WHERE pe.id = p_paiement_escrow_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ESCROW_INCONNU');
  END IF;

  IF v_row.statut = 'REMBOURSE_EN_COURS' THEN
    SELECT q.*
      INTO v_queue
      FROM public.stripe_refunds_queue q
     WHERE q.paiement_escrow_id = v_row.id
       AND q.statut IN ('EN_ATTENTE', 'EN_COURS')
     ORDER BY q.cree_le DESC
     LIMIT 1;
    RETURN jsonb_build_object(
      'success', true,
      'already_queued', true,
      'queue_id', v_queue.id,
      'statut', v_row.statut
    );
  END IF;

  IF v_row.statut = 'REMBOURSE' THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_refunded', true,
      'statut', v_row.statut
    );
  END IF;

  IF p_montant_honoraires_cts IS NULL
     OR p_montant_honoraires_cts <= 0
     OR p_montant_honoraires_cts > v_row.honoraires_cents THEN
    RETURN jsonb_build_object('success', false, 'error', 'MONTANT_INVALIDE');
  END IF;

  IF v_row.stripe_payment_intent_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'PAS_DE_DEBIT');
  END IF;

  -- Une fois le payout créé, un refund destination-charge et l'annulation du
  -- payout doivent être orchestrés ensemble. Aucun automatisme approximatif.
  IF v_row.statut = 'RELEASE_PLANIFIE' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'PAYOUT_DEJA_PLANIFIE',
      'manual_resolution_required', true
    );
  END IF;

  IF v_row.statut NOT IN ('DEBITE', 'DISPONIBLE', 'PAYE') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'STATUT_REMBOURSEMENT_INVALIDE',
      'statut', v_row.statut
    );
  END IF;

  -- Avant release, le partiel reste interdit : il laisserait un reliquat sur
  -- le compte connecté sans payout correspondant.
  IF NOT p_annulation_totale
     AND p_montant_honoraires_cts < v_row.honoraires_cents
     AND v_row.statut IN ('DEBITE', 'DISPONIBLE') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'REMBOURSEMENT_PARTIEL_PRE_RELEASE_INDISPONIBLE',
      'manual_resolution_required', true
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.stripe_refunds_queue q
     WHERE q.paiement_escrow_id = v_row.id
       AND q.statut IN ('EN_ATTENTE', 'EN_COURS')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'REMBOURSEMENT_DEJA_EN_COURS'
    );
  END IF;

  v_absorbe := v_row.statut = 'PAYE';
  v_reverse := NOT v_absorbe;

  IF p_annulation_totale THEN
    v_fee_cts := v_row.commission_cents;
  ELSE
    v_fee_cts := round(
      v_row.commission_cents::numeric
      * p_montant_honoraires_cts
      / v_row.honoraires_cents
    )::integer;
  END IF;
  v_montant_total := p_montant_honoraires_cts + v_fee_cts;

  IF v_montant_total <= 0 OR v_montant_total > v_row.montant_total_cents THEN
    RETURN jsonb_build_object('success', false, 'error', 'MONTANT_TOTAL_INVALIDE');
  END IF;

  INSERT INTO public.stripe_refunds_queue (
    avoir_id,
    facture_origine_id,
    stripe_payment_intent_id,
    montant_cts,
    statut,
    paiement_escrow_id,
    reverse_transfer,
    refund_application_fee_cts,
    absorbe_plateforme,
    escrow_statut_avant_remboursement
  ) VALUES (
    NULL,
    NULL,
    v_row.stripe_payment_intent_id,
    v_montant_total,
    'EN_ATTENTE',
    v_row.id,
    v_reverse,
    v_fee_cts,
    v_absorbe,
    v_row.statut
  )
  RETURNING * INTO v_queue;

  UPDATE public.paiements_escrow
     SET statut = 'REMBOURSE_EN_COURS',
         erreur = NULL,
         modifie_le = now()
   WHERE id = v_row.id
     AND statut = v_row.statut;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Gel escrow concurrent refusé';
  END IF;

  -- Audit obligatoire dans la même transaction que le gel : le wrapper
  -- `fn_ecrire_audit_safe` avale volontairement ses erreurs et ne convient pas
  -- à une transition financière.
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    details, navigateur_acteur
  ) VALUES (
    '00000000-0000-0000-0000-000000000000'::uuid,
    'SYSTEME',
    'ESCROW_REMBOURSEMENT_ENFILE',
    'mission',
    v_row.mission_id,
    jsonb_build_object(
      'paiement_escrow_id', v_row.id,
      'queue_id', v_queue.id,
      'montant_honoraires_cts', p_montant_honoraires_cts,
      'refund_application_fee_cts', v_fee_cts,
      'montant_total_cts', v_montant_total,
      'reverse_transfer', v_reverse,
      'absorbe_plateforme', v_absorbe,
      'annulation_totale', p_annulation_totale,
      'motif', p_motif
    ),
    'fn_escrow_rembourser'
  );

  RETURN jsonb_build_object(
    'success', true,
    'queue_id', v_queue.id,
    'statut', 'REMBOURSE_EN_COURS',
    'reverse_transfer', v_reverse,
    'absorbe_plateforme', v_absorbe,
    'refund_application_fee_cts', v_fee_cts,
    'montant_total_cts', v_montant_total
  );
END;
$$;


ALTER FUNCTION "public"."fn_escrow_rembourser"("p_paiement_escrow_id" "uuid", "p_montant_honoraires_cts" integer, "p_annulation_totale" boolean, "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_reserver_release"("p_queue_id" "uuid", "p_paiement_escrow_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_autorise boolean;
  v_rows integer;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  SELECT (
      q.statut IN ('EN_ATTENTE', 'EN_COURS')
      AND pe.statut = 'DEBITE'
      AND q.mission_id = pe.mission_id
      AND m.statut = 'TERMINEE'
      AND m.soignant_assigne_id = pe.soignant_id
      AND m.etablissement_id = pe.etablissement_id
      AND COALESCE(m.est_arret_maladie, false) IS FALSE
      AND NOT EXISTS (
        SELECT 1 FROM public.missions r
        WHERE r.remplacement_de_mission_id = m.id
      )
      AND EXISTS (
        SELECT 1 FROM public.presences p
        WHERE p.mission_id = m.id
          AND COALESCE(p.valide_par_etablissement, false) IS TRUE
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.presences p
        WHERE p.mission_id = m.id
          AND COALESCE(p.valide_par_etablissement, false) IS FALSE
          AND (p.pointage_depart_le IS NOT NULL OR p.motif_litige IS NOT NULL)
      )
    )
    INTO v_autorise
  FROM public.escrow_release_queue q
  JOIN public.paiements_escrow pe ON pe.id = q.paiement_escrow_id
  JOIN public.missions m ON m.id = pe.mission_id
  WHERE q.id = p_queue_id
    AND pe.id = p_paiement_escrow_id
  FOR UPDATE OF q, pe, m;

  IF COALESCE(v_autorise, false) IS NOT TRUE THEN
    RETURN false;
  END IF;

  UPDATE public.paiements_escrow
     SET statut = 'RELEASE_PLANIFIE',
         available_on = now(),
         disponible_le = now(),
         release_planifie_le = now(),
         modifie_le = now()
   WHERE id = p_paiement_escrow_id
     AND statut = 'DEBITE';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_reserver_release"("p_queue_id" "uuid", "p_paiement_escrow_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_escrow_reserver_tentative_debit"("p_paiement_escrow_id" "uuid", "p_tentatives_attendues" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_rows integer;
  v_autorise boolean;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  SELECT (
      pe.statut = 'INITIE'
      AND pe.tentatives_debit = COALESCE(p_tentatives_attendues, 0)
      AND m.statut IN ('ASSIGNEE', 'EN_COURS')
      AND m.soignant_assigne_id = pe.soignant_id
      AND m.etablissement_id = pe.etablissement_id
      AND COALESCE(m.est_arret_maladie, false) IS FALSE
      AND NOT EXISTS (
        SELECT 1 FROM public.missions r
        WHERE r.remplacement_de_mission_id = m.id
      )
    )
    INTO v_autorise
  FROM public.paiements_escrow pe
  JOIN public.missions m ON m.id = pe.mission_id
  WHERE pe.id = p_paiement_escrow_id
  FOR UPDATE OF m, pe;

  IF COALESCE(v_autorise, false) IS NOT TRUE THEN
    RETURN false;
  END IF;

  UPDATE public.paiements_escrow
     SET tentatives_debit = tentatives_debit + 1,
         derniere_tentative_le = now(),
         modifie_le = now()
   WHERE id = p_paiement_escrow_id
     AND statut = 'INITIE'
     AND tentatives_debit = COALESCE(p_tentatives_attendues, 0);
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END;
$$;


ALTER FUNCTION "public"."fn_escrow_reserver_tentative_debit"("p_paiement_escrow_id" "uuid", "p_tentatives_attendues" integer) OWNER TO "postgres";


