CREATE OR REPLACE FUNCTION "public"."fn_etablissements_safe"("p_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "nom" "text", "adresse_rue" "text", "adresse_code_postal" "text", "adresse_ville" "text", "adresse_departement" "text", "adresse_lat" numeric, "adresse_lng" numeric, "type" "text", "finess" "text", "taux_majoration_nuit_pourcent" numeric, "taux_majoration_dimanche_pourcent" numeric, "taux_majoration_ferie_pourcent" numeric, "logo_url" "text", "couleur_theme" "text", "paiement_rapide" boolean, "jour_paie_habituel" smallint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT
        e.id, e.nom::TEXT, e.adresse_rue::TEXT, e.adresse_code_postal::TEXT,
        e.adresse_ville::TEXT, e.adresse_departement::TEXT, e.adresse_lat, e.adresse_lng,
        e.type::TEXT, e.finess::TEXT,
        e.taux_majoration_nuit_pourcent, e.taux_majoration_dimanche_pourcent,
        e.taux_majoration_ferie_pourcent, e.logo_url::TEXT, e.couleur_theme::TEXT,
        -- 7c : capacité ⚡ de l'ÉTABLISSEMENT (flag + SEPA). La condition mission
        -- LIBERAL est appliquée par le consommateur (le régime est une propriété
        -- de la mission, jamais de l'établissement).
        -- 7b-D PR 2 (A2) : + éligibilité escrow (pas gelé, sous plafond).
        (public.fn_param_num('feature_paiement_rapide_actif', 0) = 1
         AND e.mode_paiement_commission = 'SEPA_DEBIT'
         AND e.stripe_sepa_payment_method_id IS NOT NULL
         AND public.fn_escrow_etab_eligible(e.id)) AS paiement_rapide,
        e.jour_paie_habituel
    FROM etablissements e
    WHERE e.id = ANY(p_ids)
      AND (
        EXISTS (SELECT 1 FROM missions m WHERE m.etablissement_id = e.id AND m.soignant_assigne_id = auth.uid())
        OR EXISTS (SELECT 1 FROM missions m WHERE m.etablissement_id = e.id AND m.statut = 'OUVERTE')
        OR e.id = mon_etablissement_id()
        OR est_admin()
      );
END;
$$;


ALTER FUNCTION "public"."fn_etablissements_safe"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_etat_onboarding"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
  v_etapes jsonb;
  v_termine_le timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  IF EXISTS (SELECT 1 FROM public.soignants WHERE id = v_uid) THEN
    SELECT onboarding_etapes_completees, onboarding_termine_le
    INTO v_etapes, v_termine_le
    FROM public.soignants WHERE id = v_uid;
    RETURN jsonb_build_object('success', true, 'role', 'SOIGNANT',
                                'etapes', v_etapes,
                                'termine_le', v_termine_le);
  END IF;

  v_etab_id := public.mon_etablissement_id();
  IF v_etab_id IS NOT NULL THEN
    SELECT onboarding_etapes_completees, onboarding_termine_le
    INTO v_etapes, v_termine_le
    FROM public.etablissements WHERE id = v_etab_id;
    RETURN jsonb_build_object('success', true, 'role', 'ETAB',
                                'etapes', v_etapes,
                                'termine_le', v_termine_le);
  END IF;

  RETURN jsonb_build_object('success', false, 'error_code', 'PROFIL_INTROUVABLE');
END;
$$;


ALTER FUNCTION "public"."fn_etat_onboarding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_etat_pointage_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission RECORD;
  v_is_etab boolean;
  v_is_soignant boolean;
  v_segments jsonb;
  v_segment_ouvert boolean;
BEGIN
  SELECT id, etablissement_id, soignant_assigne_id, statut,
         code_pointage_actif, prochain_type_scan, nb_scans, intitule
    INTO v_mission
    FROM missions WHERE id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;

  v_is_etab := est_admin() OR v_mission.etablissement_id = mon_etablissement_id();
  v_is_soignant := v_mission.soignant_assigne_id = auth.uid();

  IF NOT v_is_etab AND NOT v_is_soignant THEN
    RETURN jsonb_build_object('error', 'Accès interdit');
  END IF;

  -- Segments effectifs (les vrais créneaux travaillés, base de la paie)
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object('id', id, 'debut', debut, 'fin', fin) ORDER BY debut), '[]'::jsonb),
    bool_or(fin IS NULL)
    INTO v_segments, v_segment_ouvert
    FROM mission_creneaux
    WHERE mission_id = p_mission_id AND type_creneau = 'EFFECTIF';

  RETURN jsonb_build_object(
    'statut', v_mission.statut,
    'intitule', v_mission.intitule,
    'prochain_type_scan', v_mission.prochain_type_scan,
    'nb_scans', v_mission.nb_scans,
    'segment_ouvert', COALESCE(v_segment_ouvert, false),
    'segments', v_segments,
    -- Visible uniquement par l'établissement (l'affiche au soignant à pointer).
    'code_pointage_actif', CASE WHEN v_is_etab THEN v_mission.code_pointage_actif ELSE NULL END,
    'est_etab', v_is_etab
  );
END;
$$;


ALTER FUNCTION "public"."fn_etat_pointage_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evaluer_alertes_filtres"("p_frequence" "text" DEFAULT NULL::"text") RETURNS TABLE("filtre_id" "uuid", "utilisateur_id" "uuid", "audience" "public"."filtre_audience", "nom" "text", "nb_nouveaux" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  r RECORD;
  v_count integer;
  -- Lot 17 : cap en configuration (défaut = ancienne valeur en dur).
  v_cap_h int := GREATEST(1, fn_param_num('alerte_filtre_cap_h', 20)::int);
BEGIN
  FOR r IN
    SELECT * FROM filtres_sauvegardes
    WHERE alerte_active = true
      AND (
        (p_frequence IS NULL OR frequence_alerte::text = p_frequence)
        AND (
          (frequence_alerte = 'QUOTIDIENNE'   AND dernier_check_le < now() - interval '23 hours') OR
          (frequence_alerte = 'HEBDOMADAIRE'  AND dernier_check_le < now() - interval '6 days 23 hours') OR
          (frequence_alerte = 'IMMEDIATE'     AND dernier_check_le < now() - interval '55 minutes')
        )
      )
  LOOP
    v_count := fn_compter_nouveaux_pour_filtre(r.id, r.dernier_check_le);
    UPDATE filtres_sauvegardes
    SET dernier_check_le = now(),
        nb_resultats_dernier_check = v_count
    WHERE id = r.id;
    IF v_count > 0 THEN
      -- 6c.4 : notification in-app/push (soignant) avec deep-link direct dans
      -- le deck de swipe. L'email (pipeline existant) part en parallèle via
      -- les lignes retournées par cette fonction.
      -- 7d-A2 : CAP DE FRÉQUENCE — au plus une notification MISSION_A_POURVOIR
      -- par N h (param) et par soignant, toutes recherches confondues (anti-spam).
      IF r.audience = 'SOIGNANT_RECHERCHE_MISSIONS' AND NOT EXISTS (
        SELECT 1 FROM notifications n
         WHERE n.destinataire_id = r.utilisateur_id
           AND n.type = 'MISSION_A_POURVOIR'
           AND n.cree_le > now() - make_interval(hours => v_cap_h)
      ) THEN
        INSERT INTO notifications (destinataire_id, type_destinataire, type, titre, corps, lien)
        VALUES (
          r.utilisateur_id, 'SOIGNANT', 'MISSION_A_POURVOIR',
          '✨ ' || v_count || ' nouvelle' || CASE WHEN v_count > 1 THEN 's' ELSE '' END
            || ' mission' || CASE WHEN v_count > 1 THEN 's' ELSE '' END
            || ' pour « ' || r.nom || ' »',
          'De nouvelles missions correspondent à ta recherche sauvegardée — découvre-les avant les autres.',
          '/soignant/recherche-missions?vue=swipe'
        );
      END IF;

      filtre_id := r.id;
      utilisateur_id := r.utilisateur_id;
      audience := r.audience;
      nom := r.nom;
      nb_nouveaux := v_count;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_evaluer_alertes_filtres"("p_frequence" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evaluer_coherence_pointage"("p_pointage_arrivee" timestamp with time zone, "p_pointage_depart" timestamp with time zone, "p_mission_debut" timestamp with time zone, "p_mission_fin" timestamp with time zone, "p_duree_nette_min" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v_incidents jsonb := '[]'::jsonb;
BEGIN
  IF p_pointage_arrivee IS NOT NULL AND p_pointage_arrivee < p_mission_debut - INTERVAL '1 hour' THEN
    v_incidents := v_incidents || jsonb_build_object('code', 'ARRIVEE_TROP_PRECOCE', 'severite', 'WARNING',
      'message', 'Arrivée pointée plus d''1h avant le début prévu',
      'ecart_min', EXTRACT(EPOCH FROM (p_mission_debut - p_pointage_arrivee))/60);
  END IF;
  IF p_pointage_arrivee IS NOT NULL AND p_pointage_arrivee > p_mission_fin THEN
    v_incidents := v_incidents || jsonb_build_object('code', 'ARRIVEE_APRES_FIN', 'severite', 'CRITICAL',
      'message', 'Arrivée pointée après l''heure de fin de mission',
      'ecart_min', EXTRACT(EPOCH FROM (p_pointage_arrivee - p_mission_fin))/60);
  END IF;
  IF p_pointage_arrivee IS NOT NULL AND p_pointage_depart IS NOT NULL
     AND p_pointage_depart < p_pointage_arrivee THEN
    v_incidents := v_incidents || jsonb_build_object('code', 'DEPART_AVANT_ARRIVEE', 'severite', 'CRITICAL',
      'message', 'Heure de départ antérieure à l''arrivée');
  END IF;
  IF p_pointage_depart IS NOT NULL AND p_pointage_depart < p_mission_fin - INTERVAL '4 hours' THEN
    v_incidents := v_incidents || jsonb_build_object('code', 'DEPART_TRES_ANTICIPE', 'severite', 'WARNING',
      'message', 'Départ pointé plus de 4h avant la fin prévue',
      'ecart_min', EXTRACT(EPOCH FROM (p_mission_fin - p_pointage_depart))/60);
  END IF;
  IF p_pointage_depart IS NOT NULL AND p_pointage_depart > p_mission_fin + INTERVAL '4 hours' THEN
    v_incidents := v_incidents || jsonb_build_object('code', 'DEPART_TRES_TARDIF', 'severite', 'WARNING',
      'message', 'Départ pointé plus de 4h après la fin prévue',
      'ecart_min', EXTRACT(EPOCH FROM (p_pointage_depart - p_mission_fin))/60);
  END IF;
  IF p_duree_nette_min IS NOT NULL THEN
    IF p_duree_nette_min <= 0 THEN
      v_incidents := v_incidents || jsonb_build_object('code', 'DUREE_NULLE', 'severite', 'CRITICAL',
        'message', 'Durée nette de mission <= 0 minutes');
    ELSIF p_duree_nette_min > 1440 THEN
      v_incidents := v_incidents || jsonb_build_object('code', 'DUREE_EXCESSIVE', 'severite', 'WARNING',
        'message', 'Durée nette de mission > 24h', 'duree_min', p_duree_nette_min);
    END IF;
  END IF;
  RETURN v_incidents;
END;
$$;


ALTER FUNCTION "public"."fn_evaluer_coherence_pointage"("p_pointage_arrivee" timestamp with time zone, "p_pointage_depart" timestamp with time zone, "p_mission_debut" timestamp with time zone, "p_mission_fin" timestamp with time zone, "p_duree_nette_min" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evaluer_etablissement"("p_mission_id" "uuid", "p_note" integer, "p_commentaire" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
    IF v_mission.statut != 'TERMINEE' THEN RETURN jsonb_build_object('error', 'La mission doit être terminée pour évaluer'); END IF;
    IF v_mission.soignant_assigne_id != auth.uid() THEN RETURN jsonb_build_object('error', 'Non autorisé'); END IF;
    IF p_note < 1 OR p_note > 5 THEN RETURN jsonb_build_object('error', 'La note doit être entre 1 et 5'); END IF;

    IF EXISTS (SELECT 1 FROM evaluations WHERE mission_id = p_mission_id AND evaluateur_id = auth.uid()) THEN
        RETURN jsonb_build_object('error', 'Vous avez déjà évalué cette mission');
    END IF;

    INSERT INTO evaluations (mission_id, evaluateur_id, evalue_id, type_evaluateur, note, commentaire, visible)
    VALUES (p_mission_id, auth.uid(), v_mission.etablissement_id, 'SOIGNANT', p_note, p_commentaire, TRUE);

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_evaluer_etablissement"("p_mission_id" "uuid", "p_note" integer, "p_commentaire" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evaluer_rattachement_etablissement"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_etab record;
  v_methode text := 'ADMIN';
  v_verifie boolean := false;
  v_match_nom boolean := false;
  v_rapprochement jsonb := jsonb_build_object('statut', 'DIRIGEANT_NON_TROUVE');
BEGIN
  IF COALESCE(auth.jwt() ->> 'role', current_setting('request.jwt.claim.role', true), '')
       IS DISTINCT FROM 'service_role'
     AND NOT public.est_admin()
     AND p_etablissement_id IS DISTINCT FROM public.mon_etablissement_id() THEN
    RAISE EXCEPTION 'Non autorisé' USING ERRCODE = '42501';
  END IF;

  SELECT dirigeants, representant_nom, representant_prenom,
         representant_identite_verifiee, representant_identite_resultat_ia,
         justificatif_fonction_verifie
    INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Établissement introuvable' USING ERRCODE = 'P0002';
  END IF;

  IF v_etab.representant_identite_verifiee IS TRUE
     AND NULLIF(btrim(v_etab.representant_nom), '') IS NOT NULL
     AND NULLIF(btrim(v_etab.representant_prenom), '') IS NOT NULL
     AND jsonb_typeof(v_etab.dirigeants) = 'array' THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_etab.dirigeants) AS dirigeants(d)
      WHERE public.fn_normaliser_nom(d ->> 'type_dirigeant') LIKE '%physique%'
        AND public.fn_normaliser_nom(d ->> 'nom')
            = public.fn_normaliser_nom(v_etab.representant_nom)
        AND NOT EXISTS (
          SELECT 1
          FROM unnest(
            regexp_split_to_array(
              public.fn_normaliser_nom(v_etab.representant_prenom),
              ' +'
            )
          ) AS attendu(prenom)
          WHERE attendu.prenom <> ''
            AND NOT (
              attendu.prenom = ANY (
                regexp_split_to_array(
                  public.fn_normaliser_nom(
                    COALESCE(d ->> 'prenoms', d ->> 'prenom')
                  ),
                  ' +'
                )
              )
            )
        )
    ) INTO v_match_nom;

    IF v_match_nom THEN
      v_rapprochement := private.fn_rapprocher_naissance_representant(
        v_etab.representant_identite_resultat_ia,
        v_etab.dirigeants,
        v_etab.representant_nom,
        v_etab.representant_prenom,
        NULL
      );
      IF v_rapprochement ->> 'statut' IN ('CORRESPOND', 'NON_DISPONIBLE') THEN
        v_methode := 'AUTO_DIRIGEANT';
        v_verifie := true;
      END IF;
    END IF;
  END IF;

  IF NOT v_verifie
     AND v_etab.representant_identite_verifiee IS TRUE
     AND v_etab.justificatif_fonction_verifie IS TRUE THEN
    v_methode := 'JUSTIFICATIF';
    v_verifie := true;
  END IF;

  UPDATE public.etablissements
  SET rattachement_methode = v_methode,
      rattachement_verifie = v_verifie,
      rattachement_verifie_le = CASE WHEN v_verifie THEN now() ELSE NULL END,
      modifie_le = now()
  WHERE id = p_etablissement_id;

  RETURN jsonb_build_object(
    'success', true,
    'methode', v_methode,
    'verifie', v_verifie,
    'match_dirigeant', v_match_nom,
    'rapprochement_naissance', v_rapprochement
  );
END;
$$;


ALTER FUNCTION "public"."fn_evaluer_rattachement_etablissement"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evaluer_soignant"("p_mission_id" "uuid", "p_note" integer, "p_commentaire" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_etab_id UUID;
BEGIN
    v_etab_id := mon_etablissement_id();
    IF v_etab_id IS NULL AND NOT est_admin() THEN RETURN jsonb_build_object('error', 'Non autorisé'); END IF;

    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
    IF v_mission.statut != 'TERMINEE' THEN RETURN jsonb_build_object('error', 'La mission doit être terminée pour évaluer'); END IF;
    IF v_mission.etablissement_id != v_etab_id AND NOT est_admin() THEN RETURN jsonb_build_object('error', 'Non autorisé'); END IF;
    IF v_mission.soignant_assigne_id IS NULL THEN RETURN jsonb_build_object('error', 'Aucun soignant assigné'); END IF;
    IF p_note < 1 OR p_note > 5 THEN RETURN jsonb_build_object('error', 'La note doit être entre 1 et 5'); END IF;

    -- Vérifier pas déjà évalué
    IF EXISTS (SELECT 1 FROM evaluations WHERE mission_id = p_mission_id AND evaluateur_id = v_etab_id) THEN
        RETURN jsonb_build_object('error', 'Vous avez déjà évalué cette mission');
    END IF;

    INSERT INTO evaluations (mission_id, evaluateur_id, evalue_id, type_evaluateur, note, commentaire, visible)
    VALUES (p_mission_id, v_etab_id, v_mission.soignant_assigne_id, 'ETABLISSEMENT', p_note, p_commentaire, TRUE);

    -- Notifier le soignant
    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (v_mission.soignant_assigne_id, 'SYSTEM', 
        '⭐ Nouvelle évaluation',
        'Vous avez reçu une évaluation ' || p_note || '/5 pour la mission "' || v_mission.intitule || '".',
        '/soignant/evaluations', 'SOIGNANT');

    RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_evaluer_soignant"("p_mission_id" "uuid", "p_note" integer, "p_commentaire" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evolution_missions_etab"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etab_id UUID;
  v_result JSONB;
  v_six_mois_ago DATE;
BEGIN
  IF NOT est_admin() THEN
    v_etab_id := mon_etablissement_id();
    IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;
  END IF;

  v_six_mois_ago := DATE_TRUNC('month', NOW() - INTERVAL '5 months')::DATE;

  WITH mois_serie AS (
    SELECT (v_six_mois_ago + (n || ' months')::interval)::date AS mois_debut,
           (v_six_mois_ago + ((n+1) || ' months')::interval)::date AS mois_fin,
           TO_CHAR(v_six_mois_ago + (n || ' months')::interval, 'YYYY-MM') AS mois_label
    FROM generate_series(0, 5) AS n
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mois', ms.mois_label,
    'publiees', (
      SELECT COUNT(*) FROM missions m
      WHERE (v_etab_id IS NULL OR m.etablissement_id = v_etab_id)
        AND m.cree_le >= ms.mois_debut AND m.cree_le < ms.mois_fin
    ),
    'assignees', (
      SELECT COUNT(*) FROM missions m
      WHERE (v_etab_id IS NULL OR m.etablissement_id = v_etab_id)
        AND m.statut IN ('ASSIGNEE','EN_COURS','TERMINEE')
        AND m.cree_le >= ms.mois_debut AND m.cree_le < ms.mois_fin
    ),
    'terminees', (
      SELECT COUNT(*) FROM missions m
      WHERE (v_etab_id IS NULL OR m.etablissement_id = v_etab_id)
        AND m.statut = 'TERMINEE'
        AND m.fin_le >= ms.mois_debut AND m.fin_le < ms.mois_fin
    )
  ) ORDER BY ms.mois_label), '[]'::jsonb)
  INTO v_result
  FROM mois_serie ms;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_evolution_missions_etab"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_evolution_score_soignant"("p_limit" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_result JSONB;
  v_limit INT;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  v_limit := LEAST(GREATEST(COALESCE(p_limit, 6), 1), 50);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mois', mois_label, 'score', ROUND(score::numeric, 1),
    'niveau', niveau, 'cree_le', cree_le
  ) ORDER BY mois_label ASC), '[]'::jsonb) INTO v_result
  FROM (
    SELECT DISTINCT ON (TO_CHAR(cree_le, 'YYYY-MM'))
      TO_CHAR(cree_le, 'YYYY-MM') AS mois_label,
      score_total AS score, niveau::text AS niveau, cree_le
    FROM scoring_breakdown
    WHERE soignant_id = v_uid AND cree_le >= NOW() - (v_limit || ' months')::interval
    ORDER BY TO_CHAR(cree_le, 'YYYY-MM'), cree_le DESC
  ) t;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_evolution_score_soignant"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_exclure_utilisateur"("p_exclu_id" "uuid", "p_type" "text", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_type_acteur text;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF p_type NOT IN ('SOIGNANT', 'ETABLISSEMENT') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Type invalide');
  END IF;

  -- Prevent self-exclusion
  IF v_caller_id = p_exclu_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Impossible de s''exclure soi-même');
  END IF;

  -- Check duplicate
  IF EXISTS (SELECT 1 FROM exclusions WHERE exclu_par = v_caller_id AND exclu_id = p_exclu_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Exclusion déjà existante');
  END IF;

  INSERT INTO exclusions (exclu_id, exclu_par, type_exclu_par, motif)
  VALUES (p_exclu_id, v_caller_id, p_type, p_motif);

  -- Determine actor type
  IF p_type = 'ETABLISSEMENT' THEN
    v_type_acteur := 'ADMIN_ETABLISSEMENT';
  ELSE
    v_type_acteur := 'SOIGNANT';
  END IF;

  -- Audit
  PERFORM fn_ecrire_audit_safe(
    v_caller_id, v_type_acteur, 'EXCLUSION_CREEE',
    'exclusion', p_exclu_id, NULL,
    jsonb_build_object('type_exclu_par', p_type, 'motif', COALESCE(p_motif, '')),
    NULL, 'rpc'
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_exclure_utilisateur"("p_exclu_id" "uuid", "p_type" "text", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_executer_modifications_litige"("p_litige_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_litige record;
  v_payload jsonb;
  v_type text;
  v_modifications jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_audit_result jsonb;
  v_rows integer;
  v_internal boolean := COALESCE(
    current_setting('jolene.litige_exec_ok', true), ''
  ) = 'true';
BEGIN
  IF public.est_admin() IS NOT TRUE AND v_internal IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Exécution de l''accord non autorisée'
    );
  END IF;

  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Litige introuvable'
    );
  END IF;

  IF v_litige.modifications_executees IS TRUE THEN
    RETURN jsonb_build_object(
      'success', true,
      'already_executed', true,
      'executees_a', v_litige.modifications_executees_a
    );
  END IF;

  IF v_litige.accord_soignant IS NOT TRUE
     OR v_litige.accord_etablissement IS NOT TRUE
     OR v_litige.accord_soignant_le IS NULL
     OR v_litige.accord_etablissement_le IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Double accord horodaté requis avant exécution'
    );
  END IF;

  v_payload := v_litige.payload_modifications;
  IF v_payload IS NULL THEN
    IF v_litige.statut <> 'RESOLU_ACCORD_PARTIES' THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Statut incompatible avec un accord sans modification'
      );
    END IF;
    v_type := 'ACCORD_SANS_MODIFICATION';
    v_results := jsonb_build_array(
      jsonb_build_object('type', v_type, 'success', true)
    );
  ELSE
    IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_payload->'type') IS DISTINCT FROM 'string'
       OR jsonb_typeof(v_payload->'modifications') IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_payload->'justification') IS DISTINCT FROM 'string'
       OR btrim(v_payload->>'justification') = ''
       OR length(v_payload->>'justification') > 2000
       OR v_payload - ARRAY[
         'type', 'modifications', 'justification'
       ]::text[] <> '{}'::jsonb THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Schéma de proposition stocké invalide'
      );
    END IF;

    v_type := v_payload->>'type';
    v_modifications := v_payload->'modifications';

    IF v_type IN (
      'MODIFICATION_HORAIRES',
      'MODIFICATION_MONTANT',
      'MIXTE'
    ) THEN
      RETURN jsonb_build_object(
        'success', false,
        'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
        'error', 'Cet ajustement doit être appliqué via la résolution financière administrateur.',
        'manual_resolution_required', true,
        'type', v_type
      );
    END IF;

    IF v_type = 'ACCORD_SANS_MODIFICATION' THEN
      IF v_litige.statut <> 'RESOLU_ACCORD_PARTIES'
         OR v_modifications <> '{}'::jsonb THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'Accord sans modification incohérent'
        );
      END IF;
      v_results := jsonb_build_array(
        jsonb_build_object('type', v_type, 'success', true)
      );
    ELSIF v_type = 'ANNULATION_TOTALE' THEN
      IF public.est_admin() IS NOT TRUE
         OR v_litige.statut <> 'REVUE_ADMIN'
         OR jsonb_typeof(v_modifications->'motif_annulation') IS DISTINCT FROM 'string'
         OR btrim(v_modifications->>'motif_annulation') = ''
         OR v_modifications - ARRAY['motif_annulation']::text[]
           <> '{}'::jsonb THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'Annulation totale non autorisée ou mal formée'
        );
      END IF;

      -- Un paiement Connect est une charge plateforme suivie d'un transfer
      -- séparé. Le remboursement de la charge seule ne reprendrait pas les
      -- fonds déjà envoyés au compte connecté. Tant qu'un reversal exact et
      -- atomique n'est pas implémenté, la résolution reste manuelle et
      -- l'accord ne doit surtout pas être marqué exécuté.
      IF EXISTS (
        SELECT 1
          FROM public.stripe_transfers st
         WHERE st.mission_id = v_litige.mission_id
           AND st.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
      ) THEN
        RETURN jsonb_build_object(
          'success', false,
          'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
          'error', 'Le paiement Stripe Connect exige un remboursement et un reversal vérifiés par un administrateur.',
          'manual_resolution_required', true,
          'type', v_type
        );
      END IF;

      v_result := public.fn_annuler_mission_complete(
        v_litige.mission_id,
        v_payload->>'justification',
        p_litige_id
      );
      IF COALESCE(v_result @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'Échec atomique de l''annulation totale: %',
          COALESCE(v_result->>'error', 'résultat interne invalide');
      END IF;
      v_results := jsonb_build_array(v_result);
    ELSIF v_type = 'COMPENSATION_PARTIELLE' THEN
      IF public.est_admin() IS NOT TRUE
         OR v_litige.statut <> 'REVUE_ADMIN'
         OR jsonb_typeof(
           v_modifications->'pourcentage_compensation'
         ) IS DISTINCT FROM 'number'
         OR v_modifications - ARRAY['pourcentage_compensation']::text[]
           <> '{}'::jsonb
         OR (v_modifications->>'pourcentage_compensation')::numeric <= 0
         OR (v_modifications->>'pourcentage_compensation')::numeric > 100 THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'Compensation partielle non autorisée ou mal formée'
        );
      END IF;

      IF EXISTS (
        SELECT 1
          FROM public.stripe_transfers st
         WHERE st.mission_id = v_litige.mission_id
           AND st.statut NOT IN ('ECHOUE', 'ANNULEE', 'REMBOURSE')
      ) THEN
        RETURN jsonb_build_object(
          'success', false,
          'error_code', 'RESOLUTION_FINANCIERE_MANUELLE_REQUISE',
          'error', 'Le paiement Stripe Connect exige un remboursement et un reversal vérifiés par un administrateur.',
          'manual_resolution_required', true,
          'type', v_type
        );
      END IF;

      v_result := public.fn_appliquer_compensation_partielle(
        v_litige.mission_id,
        (v_modifications->>'pourcentage_compensation')::numeric,
        v_payload->>'justification',
        p_litige_id
      );
      IF COALESCE(v_result @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'Échec atomique de la compensation partielle: %',
          COALESCE(v_result->>'error', 'résultat interne invalide');
      END IF;
      v_results := jsonb_build_array(v_result);
    ELSE
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Type de modification non pris en charge'
      );
    END IF;
  END IF;

  UPDATE public.litiges
     SET modifications_executees = true,
         modifications_executees_a = now(),
         modifications_executees_par = v_uid
   WHERE id = p_litige_id
     AND modifications_executees IS NOT TRUE;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Marquage concurrent de l''accord exécuté refusé';
  END IF;

  v_audit_result := public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := CASE
      WHEN public.est_admin() THEN 'ADMIN_PLATEFORME'
      ELSE 'SYSTEME'
    END,
    p_action := 'LITIGE_RESOLUTION',
    p_type_ressource := 'litige',
    p_id_ressource := p_litige_id,
    p_details := jsonb_build_object(
      'evenement', 'LITIGE_MODIFICATIONS_EXECUTEES',
      'type', v_type,
      'mission_id', v_litige.mission_id,
      'results', v_results
    )
  );
  IF COALESCE(v_audit_result @> '{"success": true}'::jsonb, false)
       IS NOT TRUE THEN
    RAISE EXCEPTION 'Audit d''exécution d''accord non écrit: %',
      COALESCE(v_audit_result->>'error', 'résultat interne invalide');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'type', v_type,
    'results', v_results
  );
END;
$$;


ALTER FUNCTION "public"."fn_executer_modifications_litige"("p_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_exiger_conformite_demarrage_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_regime text;
BEGIN
  IF p_mission_id IS NULL OR p_soignant_id IS NULL THEN
    RAISE EXCEPTION 'Mission et soignant requis' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_mission
  FROM public.missions
  WHERE id = p_mission_id
  FOR SHARE;
  IF NOT FOUND
     OR v_mission.soignant_assigne_id IS DISTINCT FROM p_soignant_id THEN
    RAISE EXCEPTION 'Le soignant n''est pas affecté à cette mission.'
      USING ERRCODE = '42501';
  END IF;
  IF v_mission.statut NOT IN ('ASSIGNEE', 'EN_COURS') THEN
    RAISE EXCEPTION 'La mission ne peut pas être démarrée dans son état actuel.'
      USING ERRCODE = '23514';
  END IF;

  -- Snapshot transactionnel des preuves et du profil. L'ordre
  -- mission -> documents -> soignant -> contrats suit celui des triggers de
  -- remplacement/RIB afin d'éviter un deadlock. Une révocation concurrente
  -- finit donc avant ce contrôle, ou attend la fin du démarrage.
  PERFORM 1
  FROM public.documents_soignants ds
  WHERE ds.soignant_id = p_soignant_id
    AND ds.supprime_le IS NULL
    AND ds.revoque_le IS NULL
  ORDER BY ds.id
  FOR SHARE;

  PERFORM 1
  FROM public.soignants s
  WHERE s.id = p_soignant_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profil soignant introuvable.' USING ERRCODE = '23503';
  END IF;

  PERFORM 1
  FROM public.contrats_mission cm
  WHERE cm.mission_id = p_mission_id
    AND cm.soignant_id = p_soignant_id
  ORDER BY cm.id
  FOR SHARE;

  IF NOT EXISTS (
    SELECT 1
    FROM public.contrats_mission cm
    WHERE cm.mission_id = p_mission_id
      AND cm.soignant_id = p_soignant_id
      AND cm.statut = 'SIGNE_COMPLET'
      AND cm.signature_soignant IS TRUE
      AND cm.signature_etablissement IS TRUE
  ) THEN
    RAISE EXCEPTION 'Le contrat signé par les deux parties est requis avant le pointage.'
      USING ERRCODE = '23514';
  END IF;

  v_regime := COALESCE(v_mission.type_contrat_applique::text, 'SALARIE');
  IF NOT public.fn_documents_ok_pour_mission(p_soignant_id, v_regime) THEN
    RAISE EXCEPTION 'Les justificatifs requis ne sont plus tous vérifiés. Déposez ou faites valider la preuve courante avant de démarrer.'
      USING ERRCODE = '23514';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_exiger_conformite_demarrage_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_exiger_reservation_avant_attribution"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_mode text;
  v_paiement public.paiements_mission%ROWTYPE;
BEGIN
  IF NEW.statut IS DISTINCT FROM 'ASSIGNEE'
     OR OLD.statut IS NOT DISTINCT FROM 'ASSIGNEE' THEN
    RETURN NEW;
  END IF;

  SELECT e.mode_paiement_commission
    INTO v_mode
  FROM public.etablissements e
  WHERE e.id = NEW.etablissement_id;

  IF v_mode IS DISTINCT FROM 'STRIPE_RESERVATION'
     OR COALESCE(NEW.montant_commission_ttc, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_paiement
  FROM public.paiements_mission pm
  WHERE pm.mission_id = NEW.id
  FOR UPDATE;

  IF NOT FOUND
     OR v_paiement.etablissement_id IS DISTINCT FROM NEW.etablissement_id
     OR v_paiement.stripe_payment_intent_id IS NULL
     OR v_paiement.statut NOT IN ('AUTORISE', 'CAPTURE')
     OR v_paiement.montant_ttc IS DISTINCT FROM NEW.montant_commission_ttc THEN
    RAISE EXCEPTION 'Autorisation Stripe requise avant attribution de la mission'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_exiger_reservation_avant_attribution"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_expirer_candidatures_missions_demarrees"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_nb integer;
BEGIN
  UPDATE candidatures c
  SET statut = 'EXPIREE'
  FROM missions m
  WHERE m.id = c.mission_id
    AND c.statut IN ('EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB')
    AND m.debut_le <= now();
  GET DIAGNOSTICS v_nb = ROW_COUNT;
  RETURN v_nb;
END;
$$;


ALTER FUNCTION "public"."fn_expirer_candidatures_missions_demarrees"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_expirer_parrainages_inactifs"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_count INT := 0;
BEGIN
  IF NOT (est_admin() OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Accès refusé');
  END IF;

  WITH expired AS (
    UPDATE parrainages SET statut = 'EXPIRED'
    WHERE statut = 'EN_ATTENTE'
      AND cree_le < NOW() - INTERVAL '12 months'
    RETURNING id
  )
  SELECT COUNT(*) INTO v_count FROM expired;

  RETURN jsonb_build_object('success', true, 'count', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_expirer_parrainages_inactifs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_export_fec"("p_annee" integer) RETURNS TABLE("journal_code" "text", "journal_libelle" "text", "ecriture_num" "text", "ecriture_date" "text", "compte_num" "text", "compte_libelle" "text", "comp_aux_num" "text", "comp_aux_libelle" "text", "piece_ref" "text", "piece_date" "text", "ecriture_libelle" "text", "debit" numeric, "credit" numeric, "montant" numeric, "devise" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF NOT est_admin() THEN RETURN; END IF;

    RETURN QUERY
    SELECT
        'VE'::TEXT, 'Ventes'::TEXT,
        f.numero_facture,
        TO_CHAR(f.date_emission, 'YYYYMMDD'),
        '706000'::TEXT, 'Prestations de services'::TEXT,
        e.siret::TEXT, e.nom,
        f.numero_facture, TO_CHAR(f.date_emission, 'YYYYMMDD'),
        'Commission Jolene'::TEXT,
        0::NUMERIC, f.montant_ht,
        f.montant_ttc, 'EUR'::TEXT
    FROM factures f
    JOIN etablissements e ON e.id = f.etablissement_id
    WHERE EXTRACT(YEAR FROM f.date_emission) = p_annee
    ORDER BY f.date_emission;
END;
$$;


ALTER FUNCTION "public"."fn_export_fec"("p_annee" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_exporter_rgpd_etablissement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_result JSONB;
BEGIN
    IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;

    SELECT jsonb_build_object(
        'etablissement', (SELECT row_to_json(e) FROM (
            SELECT nom, type::TEXT, siret, finess, email_contact, telephone_contact,
                adresse_rue, adresse_code_postal, adresse_ville, convention_collective,
                cree_le, modifie_le
            FROM etablissements WHERE id = v_etab_id
        ) e),
        'missions', (SELECT COALESCE(jsonb_agg(row_to_json(m)), '[]') FROM (
            SELECT id, intitule, statut::TEXT, debut_le, fin_le, taux_horaire_base, total_brut, cree_le
            FROM missions WHERE etablissement_id = v_etab_id ORDER BY cree_le DESC LIMIT 200
        ) m),
        'factures', (SELECT COALESCE(jsonb_agg(row_to_json(f)), '[]') FROM (
            SELECT numero_facture, montant_ht, montant_ttc, statut, date_emission, date_paiement
            FROM factures WHERE etablissement_id = v_etab_id ORDER BY date_emission DESC
        ) f),
        'contrats', (SELECT COALESCE(jsonb_agg(row_to_json(c)), '[]') FROM (
            SELECT type_contrat, statut, cree_le, modifie_le
            FROM contrats_mission WHERE etablissement_id = v_etab_id ORDER BY cree_le DESC LIMIT 200
        ) c),
        'export_date', NOW()
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_exporter_rgpd_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_externalisation_echec"("p_id" "uuid", "p_erreur" "text", "p_special_statut" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action public.externalisation_actions%ROWTYPE;
  v_new_tentatives integer;
  v_new_statut text;
  v_next_retry timestamptz;
  v_rows integer;
BEGIN
  IF p_id IS NULL OR btrim(COALESCE(p_erreur, '')) = '' THEN
    RAISE EXCEPTION 'Échec externalisation invalide' USING ERRCODE = '22023';
  END IF;
  SELECT ea.* INTO v_action
  FROM public.externalisation_actions ea
  WHERE ea.id = p_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Action externalisation introuvable' USING ERRCODE = 'P0001';
  END IF;
  IF v_action.statut = 'DONE' THEN
    RETURN jsonb_build_object('success', true, 'already_done', true);
  END IF;
  IF v_action.statut = 'CANCELLED' THEN
    RETURN jsonb_build_object('success', true, 'cancelled', true);
  END IF;

  IF p_special_statut = 'PENDING_AIFE' THEN
    v_new_statut := 'PENDING_AIFE';
    v_next_retry := now() + interval '24 hours';
    v_new_tentatives := v_action.tentatives;
  ELSIF p_special_statut IS NOT NULL THEN
    RAISE EXCEPTION 'Statut spécial externalisation invalide' USING ERRCODE = '22023';
  ELSE
    v_new_tentatives := COALESCE(v_action.tentatives, 0) + 1;
    IF v_new_tentatives >= 3 THEN
      v_new_statut := 'ERROR';
      v_next_retry := NULL;
    ELSIF v_new_tentatives = 1 THEN
      v_new_statut := 'PENDING';
      v_next_retry := now() + interval '1 minute';
    ELSE
      v_new_statut := 'PENDING';
      v_next_retry := now() + interval '5 minutes';
    END IF;
  END IF;

  UPDATE public.externalisation_actions
  SET statut = v_new_statut,
      tentatives = v_new_tentatives,
      derniere_tentative_le = now(),
      derniere_erreur = left(p_erreur, 1000),
      next_retry_at = v_next_retry,
      cron_lock_at = NULL,
      cron_lock_par = NULL,
      traite_le = CASE WHEN v_new_statut = 'ERROR' THEN now() ELSE traite_le END,
      payload = CASE
        WHEN v_new_statut = 'ERROR' AND v_action.type_action = 'SMS_NOTIF' THEN jsonb_set(
          payload #- '{data,code}', '{data,code_purge}', 'true'::jsonb, true
        )
        ELSE payload
      END
  WHERE id = p_id AND statut = v_action.statut;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Échec externalisation concurrent refusé';
  END IF;

  IF v_new_statut = 'ERROR' THEN
    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource, details,
      navigateur_acteur
    ) VALUES (
      '00000000-0000-0000-0000-000000000000'::uuid,
      'SYSTEME', 'SYSTEM', 'externalisation_action', p_id,
      jsonb_build_object(
        'evenement', 'EXTERNALISATION_ECHEC_DEFINITIF',
        'type_action', v_action.type_action,
        'tentatives', v_new_tentatives,
        'derniere_erreur', left(p_erreur, 200)
      ),
      'fn_externalisation_echec'
    );
  END IF;
  RETURN jsonb_build_object(
    'success', true,
    'statut', v_new_statut,
    'tentatives', v_new_tentatives
  );
END;
$$;


ALTER FUNCTION "public"."fn_externalisation_echec"("p_id" "uuid", "p_erreur" "text", "p_special_statut" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_externalisation_succes"("p_id" "uuid", "p_resultat" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action public.externalisation_actions%ROWTYPE;
  v_rows integer;
BEGIN
  IF p_id IS NULL
     OR (p_resultat IS NOT NULL AND jsonb_typeof(p_resultat) <> 'object') THEN
    RAISE EXCEPTION 'Acquittement externalisation invalide' USING ERRCODE = '22023';
  END IF;

  SELECT ea.* INTO v_action
  FROM public.externalisation_actions ea
  WHERE ea.id = p_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Action externalisation introuvable' USING ERRCODE = 'P0001';
  END IF;
  IF v_action.statut = 'DONE' THEN
    RETURN jsonb_build_object('success', true, 'already_done', true);
  END IF;
  IF v_action.statut = 'CANCELLED' THEN
    RAISE EXCEPTION 'Action externalisation annulée' USING ERRCODE = 'P0001';
  END IF;
  IF v_action.statut NOT IN ('PROCESSING', 'PENDING', 'ERROR', 'PENDING_AIFE') THEN
    RAISE EXCEPTION 'État externalisation non acquittable: %', v_action.statut;
  END IF;

  UPDATE public.externalisation_actions
  SET statut = 'DONE',
      traite_le = now(),
      resultat = COALESCE(p_resultat, '{}'::jsonb),
      payload = CASE
        WHEN v_action.type_action = 'SMS_NOTIF' THEN jsonb_set(
          payload #- '{data,code}', '{data,code_purge}', 'true'::jsonb, true
        )
        ELSE payload
      END,
      derniere_erreur = NULL,
      cron_lock_at = NULL,
      cron_lock_par = NULL,
      next_retry_at = NULL
  WHERE id = p_id AND statut = v_action.statut;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Acquittement externalisation concurrent refusé';
  END IF;
  RETURN jsonb_build_object('success', true, 'statut', 'DONE');
END;
$$;


ALTER FUNCTION "public"."fn_externalisation_succes"("p_id" "uuid", "p_resultat" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_externalisations_a_traiter"("p_limit" integer DEFAULT 50, "p_worker_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actions jsonb; v_count int;
  v_worker text := COALESCE(p_worker_id, 'worker_' || substring(md5(random()::text), 1, 8));
BEGIN
  WITH selectionnees AS (
    SELECT id FROM public.externalisation_actions
    WHERE ((statut = 'PENDING' AND (next_retry_at IS NULL OR next_retry_at < NOW()))
        OR (statut = 'PENDING_AIFE' AND next_retry_at IS NOT NULL AND next_retry_at < NOW())
        OR (statut = 'PROCESSING' AND cron_lock_at < NOW() - INTERVAL '10 minutes'))
    ORDER BY cree_le ASC LIMIT p_limit FOR UPDATE SKIP LOCKED
  )
  UPDATE public.externalisation_actions a
  SET statut = 'PROCESSING', cron_lock_at = NOW(), cron_lock_par = v_worker
  FROM selectionnees s WHERE a.id = s.id;

  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'type_action', type_action, 'payload', payload,
    'source', source, 'source_id', source_id, 'tentatives', tentatives
  )), COUNT(*) INTO v_actions, v_count
  FROM public.externalisation_actions
  WHERE cron_lock_par = v_worker AND statut = 'PROCESSING'
    AND cron_lock_at > NOW() - INTERVAL '5 seconds';

  RETURN jsonb_build_object('success', true, 'worker_id', v_worker,
    'count', COALESCE(v_count, 0), 'actions', COALESCE(v_actions, '[]'::jsonb));
END; $$;


ALTER FUNCTION "public"."fn_externalisations_a_traiter"("p_limit" integer, "p_worker_id" "text") OWNER TO "postgres";


