CREATE OR REPLACE FUNCTION "public"."fn_finaliser_attribution_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_soignant record;
  v_etab record;
  v_resolution jsonb;
  v_choix text;
  v_semaine record;
  v_heures_existantes numeric;
  v_heures_externes numeric;
  v_heures_total numeric;
  v_nb_creneaux_valides integer;
  v_type_contrat text;
  v_type_paiement text;
  v_mode_paiement text;
  v_numero text;
  v_html text;
  v_contrat_id uuid;
  v_rows integer;
BEGIN
  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF v_mission.statut <> 'OUVERTE' THEN
    RETURN jsonb_build_object('error', 'Cette mission n''est plus disponible');
  END IF;

  SELECT * INTO v_soignant FROM public.soignants
   WHERE id = p_soignant_id AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profil soignant introuvable'); END IF;

  IF NOT public.fn_soignant_compatible_mission(
    v_soignant.profession, v_soignant.specialite_medicale,
    v_mission.profession_requise, v_mission.specialite_medicale_requise,
    COALESCE(v_mission.accepte_non_specialises, true)
  ) THEN
    RETURN jsonb_build_object(
      'error', 'Ce soignant (' || v_soignant.profession::text ||
        ') n''est pas compatible avec la profession requise par la mission (' ||
        v_mission.profession_requise::text || ').'
    );
  END IF;

  IF public.fn_est_exclu(p_soignant_id, v_mission.etablissement_id) THEN
    RETURN jsonb_build_object('error', 'Accès refusé pour cette mission.');
  END IF;

  v_resolution := public.fn_resoudre_contrat_mission(p_mission_id, p_soignant_id, p_choix_contrat);
  IF COALESCE((v_resolution->>'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_resolution - 'ok';
  END IF;
  v_choix := v_resolution->>'contrat';

  IF NOT public.fn_documents_ok_pour_mission(p_soignant_id, v_choix) THEN
    RETURN jsonb_build_object(
      'error', 'Les documents requis pour une mission ' || lower(v_choix) ||
        ' ne sont pas encore validés.',
      'documents_requis_pour', v_choix,
      'lien_documents', '/soignant/mes-documents'
    );
  END IF;

  -- Sérialise toutes les attributions visant un même soignant dans la
  -- transaction courante. Deux missions acceptées en parallèle ne peuvent
  -- ainsi plus vérifier chacune un planning encore vide puis dépasser 48 h.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('jolene:attribution:' || p_soignant_id::text, 0)
  );

  IF v_choix = 'SALARIE' THEN
    IF COALESCE(v_mission.nb_creneaux, 0) > 1 THEN
      SELECT count(*)::integer INTO v_nb_creneaux_valides
        FROM public.mission_creneaux mc
       WHERE mc.mission_id = p_mission_id
         AND mc.fin IS NOT NULL
         AND mc.type_creneau = CASE
           WHEN EXISTS (
             SELECT 1 FROM public.mission_creneaux p
              WHERE p.mission_id = p_mission_id AND p.type_creneau = 'PREVISIONNEL'
                AND p.fin IS NOT NULL AND NOT p.est_pause
           ) THEN 'PREVISIONNEL'
           ELSE 'EFFECTIF'
         END;
      IF v_nb_creneaux_valides < v_mission.nb_creneaux THEN
        RETURN jsonb_build_object(
          'error', 'Planning hebdomadaire incomplet : impossible de vérifier le plafond de 48 h.',
          'code', 'PLANNING_HEBDOMADAIRE_INDISPONIBLE',
          'creneaux_valides', v_nb_creneaux_valides,
          'creneaux_attendus', v_mission.nb_creneaux
        );
      END IF;
    END IF;

    FOR v_semaine IN
      SELECT * FROM public.fn_semaines_mission(p_mission_id)
    LOOP
      v_heures_existantes := public.fn_heures_soignant_semaine(
        p_soignant_id, v_semaine.semaine_debut, p_mission_id
      );
      SELECT COALESCE(heures_salarie, 0)
        INTO v_heures_externes
        FROM public.attestations_heures_externes
       WHERE soignant_id = p_soignant_id
         AND semaine_du = v_semaine.semaine_debut;
      IF NOT FOUND THEN v_heures_externes := 0; END IF;
      v_heures_total := v_heures_existantes + v_heures_externes + v_semaine.heures;

      IF v_heures_total > 48 THEN
        RETURN jsonb_build_object(
          'error', 'Dépassement du plafond de 48 h pour la semaine du ' ||
            to_char(v_semaine.semaine_debut, 'DD/MM/YYYY') || ' (' ||
            round(v_heures_existantes, 1) || ' h déjà planifiées + ' ||
            round(v_semaine.heures, 1) || ' h pour cette mission + ' ||
            round(v_heures_externes, 1) || ' h ailleurs).',
          'code', 'PLAFOND_48H_HEBDO',
          'semaine_du', v_semaine.semaine_debut,
          'heures_existantes', round(v_heures_existantes, 2),
          'heures_mission', round(v_semaine.heures, 2),
          'heures_externes', round(v_heures_externes, 2),
          'total', round(v_heures_total, 2)
        );
      END IF;
    END LOOP;
  END IF;

  IF v_choix = 'LIBERAL' THEN
    v_type_contrat := 'REMPLACEMENT_LIBERAL';
    v_type_paiement := 'NOTE_HONORAIRES';
    v_mode_paiement := 'STRIPE_CONNECT';
  ELSE
    v_type_contrat := 'CDD';
    v_type_paiement := 'BULLETIN_PAIE';
    v_mode_paiement := 'DIRECT';
  END IF;

  PERFORM set_config('jolene.assignment_rpc_soignant_id', p_soignant_id::text, true);
  UPDATE public.missions
     SET soignant_assigne_id = p_soignant_id,
         statut = 'ASSIGNEE',
         type_contrat_applique = v_choix::public.type_contrat_applique_enum,
         choix_contrat_soignant = v_choix,
         type_paiement_soignant = v_type_paiement,
         mode_paiement_soignant = v_mode_paiement,
         modifie_le = now()
   WHERE id = p_mission_id AND statut = 'OUVERTE';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RETURN jsonb_build_object('error', 'Cette mission vient d''être attribuée.');
  END IF;

  SELECT * INTO v_etab FROM public.etablissements WHERE id = v_mission.etablissement_id;
  v_numero := public.fn_generer_numero_contrat_safe(v_type_contrat);
  SELECT contenu_html INTO v_html
    FROM public.templates_contrat
   WHERE type_contrat = v_type_contrat AND est_actif = true
   LIMIT 1;

  IF v_html IS NOT NULL THEN
    v_html := replace(v_html, '{{etablissement_nom}}', public.fn_html_escape(COALESCE(v_etab.nom, '')));
    v_html := replace(v_html, '{{etablissement_siret}}', public.fn_html_escape(COALESCE(v_etab.siret, '')));
    v_html := replace(v_html, '{{etablissement_finess}}', public.fn_html_escape(COALESCE(v_etab.finess, 'N/A')));
    v_html := replace(v_html, '{{etablissement_adresse}}', public.fn_html_escape(COALESCE(v_etab.adresse_rue || ', ' || v_etab.adresse_code_postal || ' ' || v_etab.adresse_ville, '')));
    v_html := replace(v_html, '{{soignant_prenom}}', public.fn_html_escape(COALESCE(v_soignant.prenom, '')));
    v_html := replace(v_html, '{{soignant_nom}}', public.fn_html_escape(COALESCE(v_soignant.nom, '')));
    v_html := replace(v_html, '{{soignant_rpps}}', public.fn_html_escape(COALESCE(v_soignant.numero_rpps, '')));
    v_html := replace(v_html, '{{soignant_siret}}', public.fn_html_escape(COALESCE(v_soignant.siret_liberal, '')));
    v_html := replace(v_html, '{{profession}}', public.fn_html_escape(v_mission.profession_requise::text));
    v_html := replace(v_html, '{{service}}', public.fn_html_escape(COALESCE(v_mission.service, '')));
    v_html := replace(v_html, '{{debut_date}}', to_char(v_mission.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'));
    v_html := replace(v_html, '{{debut_heure}}', to_char(v_mission.debut_le AT TIME ZONE 'Europe/Paris', 'HH24:MI'));
    v_html := replace(v_html, '{{fin_date}}', to_char(v_mission.fin_le AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'));
    v_html := replace(v_html, '{{fin_heure}}', to_char(v_mission.fin_le AT TIME ZONE 'Europe/Paris', 'HH24:MI'));
    v_html := replace(v_html, '{{duree_heures}}', COALESCE(v_mission.duree_heures::text, ''));
    v_html := replace(v_html, '{{taux_horaire}}', COALESCE(v_mission.taux_horaire_base::text, ''));
    v_html := replace(v_html, '{{retrocession_pct}}', COALESCE(v_mission.retrocession_pct::text, ''));
    v_html := replace(v_html, '{{numero_contrat}}', public.fn_html_escape(v_numero));
    v_html := replace(v_html, '{{date_signature}}', to_char(now() AT TIME ZONE 'Europe/Paris', 'DD/MM/YYYY'));
    v_html := replace(v_html, '{{lieu}}', public.fn_html_escape(COALESCE(v_etab.adresse_ville, '')));
  END IF;

  SELECT id INTO v_contrat_id
    FROM public.contrats_mission
   WHERE mission_id = p_mission_id
     AND soignant_id = p_soignant_id
     AND statut <> 'ANNULE'
   ORDER BY cree_le DESC
   LIMIT 1;

  IF v_contrat_id IS NULL THEN
    INSERT INTO public.contrats_mission(
      mission_id, etablissement_id, soignant_id,
      type_contrat, numero_contrat, contenu_html, statut
    ) VALUES (
      p_mission_id, v_mission.etablissement_id, p_soignant_id,
      v_type_contrat, v_numero, v_html, 'EN_ATTENTE_SIGNATURES'
    ) RETURNING id INTO v_contrat_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'contrat_id', v_contrat_id,
    'contrat_numero', v_numero,
    'choix_applique', v_choix,
    'profession_requise', v_mission.profession_requise::text,
    'type_paiement', v_type_paiement,
    'mode_paiement', v_mode_paiement
  );
END;
$$;


ALTER FUNCTION "public"."fn_finaliser_attribution_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_finaliser_document_verification"("p_document_id" "uuid", "p_attempt_id" "uuid", "p_expected_soignant_id" "uuid", "p_expected_s3_bucket" "text", "p_expected_s3_cle" "text", "p_expected_type_document" "text", "p_expected_nom" "text", "p_expected_prenom" "text", "p_expected_date_naissance" "date", "p_expected_sexe" "text", "p_expected_lieu_naissance" "text", "p_expected_profession" "text", "p_expected_numero_rpps" "text", "p_expected_numero_adeli" "text", "p_expected_rpps_verifie" boolean, "p_expected_adeli_verifie" boolean, "p_statut_verification" "text", "p_motif_rejet" "text" DEFAULT NULL::"text", "p_valide_depuis" "date" DEFAULT NULL::"date", "p_valide_jusqua" "date" DEFAULT NULL::"date", "p_resultat_ia" "jsonb" DEFAULT NULL::"jsonb", "p_nom_extrait_ia" "text" DEFAULT NULL::"text", "p_prenom_extrait_ia" "text" DEFAULT NULL::"text", "p_score_confiance_ia" numeric DEFAULT NULL::numeric, "p_coherence_nom" boolean DEFAULT NULL::boolean, "p_identite_date_naissance" "date" DEFAULT NULL::"date", "p_identite_sexe" "text" DEFAULT NULL::"text", "p_identite_lieu_naissance" "text" DEFAULT NULL::"text", "p_scolarite_formation" "text" DEFAULT NULL::"text", "p_scolarite_annee_validee" integer DEFAULT NULL::integer, "p_scolarite_profession" "text" DEFAULT NULL::"text", "p_licence_valide_jusqua" "date" DEFAULT NULL::"date", "p_licence_specialite" "text" DEFAULT NULL::"text", "p_expected_heures_employeur" "text" DEFAULT NULL::"text", "p_expected_heures_date_debut" "date" DEFAULT NULL::"date", "p_expected_heures_date_fin" "date" DEFAULT NULL::"date", "p_expected_heures_declarees" numeric DEFAULT NULL::numeric, "p_expected_heures_type_preuve" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_doc public.documents_soignants%ROWTYPE;
  v_soignant public.soignants%ROWTYPE;
  v_heures public.heures_externes%ROWTYPE;
  v_statut public.statut_verification;
  v_coherence_nom boolean := p_coherence_nom;
  v_identite boolean;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  IF p_document_id IS NULL OR p_attempt_id IS NULL OR p_expected_soignant_id IS NULL THEN
    RAISE EXCEPTION 'Tentative documentaire incomplète' USING ERRCODE = '22023';
  END IF;
  IF p_statut_verification NOT IN ('VERIFIE', 'EN_ATTENTE', 'REJETE') THEN
    RAISE EXCEPTION 'Verdict documentaire invalide' USING ERRCODE = '22023';
  END IF;
  v_statut := p_statut_verification::public.statut_verification;

  SELECT * INTO v_doc
  FROM public.documents_soignants
  WHERE id = p_document_id
    AND verification_attempt_id = p_attempt_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tentative documentaire périmée' USING ERRCODE = '40001';
  END IF;

  IF v_doc.soignant_id IS DISTINCT FROM p_expected_soignant_id
     OR v_doc.s3_bucket IS DISTINCT FROM p_expected_s3_bucket
     OR v_doc.s3_cle IS DISTINCT FROM p_expected_s3_cle
     OR v_doc.type_document::text IS DISTINCT FROM p_expected_type_document
     OR v_doc.supprime_le IS NOT NULL THEN
    RAISE EXCEPTION 'Source documentaire modifiée pendant la vérification'
      USING ERRCODE = '40001';
  END IF;

  SELECT * INTO v_soignant
  FROM public.soignants
  WHERE id = p_expected_soignant_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Profil soignant introuvable' USING ERRCODE = 'P0002';
  END IF;

  IF v_soignant.nom IS DISTINCT FROM p_expected_nom
     OR v_soignant.prenom IS DISTINCT FROM p_expected_prenom
     OR v_soignant.date_naissance IS DISTINCT FROM p_expected_date_naissance
     OR v_soignant.sexe IS DISTINCT FROM p_expected_sexe
     OR v_soignant.lieu_naissance_commune IS DISTINCT FROM p_expected_lieu_naissance
     OR v_soignant.profession::text IS DISTINCT FROM p_expected_profession
     OR v_soignant.numero_rpps IS DISTINCT FROM p_expected_numero_rpps
     OR v_soignant.numero_adeli IS DISTINCT FROM p_expected_numero_adeli
     OR COALESCE(v_soignant.rpps_verifie, false) IS DISTINCT FROM COALESCE(p_expected_rpps_verifie, false)
     OR COALESCE(v_soignant.adeli_verifie, false) IS DISTINCT FROM COALESCE(p_expected_adeli_verifie, false) THEN
    RAISE EXCEPTION 'Profil modifié pendant la vérification'
      USING ERRCODE = '40001';
  END IF;

  v_identite := v_doc.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR');
  IF v_identite THEN
    v_coherence_nom := public.fn_noms_personne_correspondent(
      v_soignant.nom, v_soignant.prenom, p_nom_extrait_ia, p_prenom_extrait_ia
    );
  END IF;

  IF v_identite AND v_statut = 'VERIFIE' THEN
    IF NOT v_coherence_nom OR p_identite_date_naissance IS NULL THEN
      RAISE EXCEPTION 'Identité extraite incomplète ou incohérente' USING ERRCODE = '23514';
    END IF;
    IF v_soignant.date_naissance IS NOT NULL
       AND v_soignant.date_naissance IS DISTINCT FROM p_identite_date_naissance THEN
      RAISE EXCEPTION 'Date de naissance incohérente' USING ERRCODE = '23514';
    END IF;

    UPDATE public.soignants
    SET date_naissance = COALESCE(date_naissance, p_identite_date_naissance),
        sexe = CASE
          WHEN sexe IS NULL AND p_identite_sexe IN ('M', 'F') THEN p_identite_sexe
          ELSE sexe
        END,
        lieu_naissance_commune = CASE
          WHEN lieu_naissance_commune IS NULL
               AND NULLIF(btrim(p_identite_lieu_naissance), '') IS NOT NULL
            THEN left(btrim(p_identite_lieu_naissance), 120)
          ELSE lieu_naissance_commune
        END,
        modifie_le = now()
    WHERE id = v_soignant.id;
  END IF;

  IF p_scolarite_formation IS NOT NULL
     OR p_scolarite_annee_validee IS NOT NULL
     OR p_scolarite_profession IS NOT NULL THEN
    IF v_statut IS DISTINCT FROM 'VERIFIE'
       OR v_doc.type_document IS DISTINCT FROM 'ATTESTATION_SCOLARITE'
       OR p_scolarite_formation IS NULL
       OR p_scolarite_annee_validee IS NULL
       OR p_scolarite_profession IS DISTINCT FROM v_soignant.profession::text
       OR NOT EXISTS (
         SELECT 1
         FROM public.fn_professions_autorisees_scolarite(
           p_scolarite_formation,
           p_scolarite_annee_validee
         ) AS profession_autorisee
         WHERE profession_autorisee = v_soignant.profession
       ) THEN
      RAISE EXCEPTION 'Effet de scolarité incohérent' USING ERRCODE = '23514';
    END IF;

    UPDATE public.soignants
    SET scolarite_formation = left(p_scolarite_formation, 50),
        scolarite_annee_validee = p_scolarite_annee_validee,
        scolarite_profession_autorisee = v_soignant.profession,
        scolarite_verifiee = true,
        scolarite_verifiee_le = now(),
        est_etudiant = true,
        modifie_le = now()
    WHERE id = v_soignant.id;
  END IF;

  IF p_licence_valide_jusqua IS NOT NULL OR p_licence_specialite IS NOT NULL THEN
    IF v_statut IS DISTINCT FROM 'VERIFIE'
       OR v_doc.type_document IS DISTINCT FROM 'LICENCE_REMPLACEMENT'
       OR v_soignant.profession::text IS DISTINCT FROM 'MEDECIN'
       OR p_licence_valide_jusqua IS NULL
       OR p_licence_valide_jusqua < current_date
       OR NULLIF(btrim(p_licence_specialite), '') IS NULL THEN
      RAISE EXCEPTION 'Effet de licence incohérent' USING ERRCODE = '23514';
    END IF;

    UPDATE public.soignants
    SET licence_remplacement_verifiee = true,
        licence_remplacement_le = now(),
        licence_remplacement_valide_jusqua = p_licence_valide_jusqua,
        licence_remplacement_specialite = left(btrim(p_licence_specialite), 200),
        est_etudiant = true,
        modifie_le = now()
    WHERE id = v_soignant.id;
  END IF;

  IF v_statut = 'VERIFIE'
     AND v_doc.type_document::text IN ('BULLETIN_PAIE', 'ATTESTATION_EMPLOYEUR', 'CERTIFICAT_TRAVAIL') THEN
    SELECT * INTO v_heures
    FROM public.heures_externes
    WHERE document_id = v_doc.id AND soignant_id = v_soignant.id
    FOR SHARE;
    IF NOT FOUND
       OR v_heures.employeur_nom IS DISTINCT FROM p_expected_heures_employeur
       OR v_heures.date_debut IS DISTINCT FROM p_expected_heures_date_debut
       OR v_heures.date_fin IS DISTINCT FROM p_expected_heures_date_fin
       OR v_heures.heures_declarees IS DISTINCT FROM p_expected_heures_declarees
       OR v_heures.type_preuve IS DISTINCT FROM p_expected_heures_type_preuve THEN
      RAISE EXCEPTION 'Déclaration d''heures modifiée pendant la vérification'
        USING ERRCODE = '40001';
    END IF;
  END IF;

  UPDATE public.documents_soignants
  SET resultat_ia = p_resultat_ia,
      nom_extrait_ia = NULLIF(left(btrim(COALESCE(p_nom_extrait_ia, '')), 200), ''),
      prenom_extrait_ia = NULLIF(left(btrim(COALESCE(p_prenom_extrait_ia, '')), 200), ''),
      score_confiance_ia = CASE
        WHEN p_score_confiance_ia IS NULL THEN NULL
        ELSE greatest(0, least(100, p_score_confiance_ia))
      END,
      coherence_nom = v_coherence_nom,
      statut_verification = v_statut,
      motif_rejet = NULLIF(left(COALESCE(p_motif_rejet, ''), 1000), ''),
      valide_depuis = CASE WHEN v_statut = 'REJETE' THEN NULL ELSE p_valide_depuis END,
      valide_jusqua = CASE WHEN v_statut = 'REJETE' THEN NULL ELSE p_valide_jusqua END,
      verifie_le = CASE WHEN v_statut = 'VERIFIE' THEN now() ELSE NULL END,
      verification_attempt_id = NULL,
      modifie_le = now()
  WHERE id = v_doc.id AND verification_attempt_id = p_attempt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tentative documentaire remplacée' USING ERRCODE = '40001';
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."fn_finaliser_document_verification"("p_document_id" "uuid", "p_attempt_id" "uuid", "p_expected_soignant_id" "uuid", "p_expected_s3_bucket" "text", "p_expected_s3_cle" "text", "p_expected_type_document" "text", "p_expected_nom" "text", "p_expected_prenom" "text", "p_expected_date_naissance" "date", "p_expected_sexe" "text", "p_expected_lieu_naissance" "text", "p_expected_profession" "text", "p_expected_numero_rpps" "text", "p_expected_numero_adeli" "text", "p_expected_rpps_verifie" boolean, "p_expected_adeli_verifie" boolean, "p_statut_verification" "text", "p_motif_rejet" "text", "p_valide_depuis" "date", "p_valide_jusqua" "date", "p_resultat_ia" "jsonb", "p_nom_extrait_ia" "text", "p_prenom_extrait_ia" "text", "p_score_confiance_ia" numeric, "p_coherence_nom" boolean, "p_identite_date_naissance" "date", "p_identite_sexe" "text", "p_identite_lieu_naissance" "text", "p_scolarite_formation" "text", "p_scolarite_annee_validee" integer, "p_scolarite_profession" "text", "p_licence_valide_jusqua" "date", "p_licence_specialite" "text", "p_expected_heures_employeur" "text", "p_expected_heures_date_debut" "date", "p_expected_heures_date_fin" "date", "p_expected_heures_declarees" numeric, "p_expected_heures_type_preuve" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_finaliser_type_compte"("p_user_id" "uuid", "p_type_compte" "text", "p_claim_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_type text := upper(trim(COALESCE(p_type_compte, '')));
BEGIN
  IF v_type = 'SOIGNANT' AND NOT EXISTS (
    SELECT 1 FROM public.soignants s WHERE s.id = p_user_id
  ) THEN
    RETURN false;
  ELSIF v_type = 'ETABLISSEMENT' AND NOT EXISTS (
    SELECT 1 FROM public.etablissements e WHERE e.id = p_user_id
  ) THEN
    RETURN false;
  ELSIF v_type NOT IN ('SOIGNANT', 'ETABLISSEMENT') THEN
    RETURN false;
  END IF;

  UPDATE public.types_comptes_auth
  SET finalise_le = COALESCE(finalise_le, now()),
      claim_token = NULL,
      claim_expire_le = NULL
  WHERE user_id = p_user_id
    AND type_compte = v_type
    AND claim_token = p_claim_token
    AND claim_expire_le > now();
  RETURN FOUND;
END;
$$;


ALTER FUNCTION "public"."fn_finaliser_type_compte"("p_user_id" "uuid", "p_type_compte" "text", "p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_geler_mission_a_assignation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etab RECORD;
  v_groupe_taux numeric;
  v_taux_comm_resolved numeric;
  v_champ_modifie text;
  v_new_code text;
  v_duree_jours integer;
  v_strategie public.strategie_facturation;
BEGIN
  IF OLD.statut = 'OUVERTE' AND NEW.statut = 'ASSIGNEE' THEN
    SELECT
      COALESCE(e.taux_majoration_nuit_pourcent, 25) AS taux_nuit,
      COALESCE(e.taux_majoration_dimanche_pourcent, 25) AS taux_dim,
      COALESCE(e.taux_majoration_ferie_pourcent, 50) AS taux_fer,
      COALESCE(e.heure_debut_nuit, '21:00'::time) AS h_debut_nuit,
      COALESCE(e.heure_fin_nuit, '06:00'::time) AS h_fin_nuit,
      e.taux_commission_negocie AS taux_comm_etab,
      e.groupe_sante_id AS groupe_id
    INTO v_etab
    FROM etablissements e WHERE e.id = NEW.etablissement_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Établissement % introuvable', NEW.etablissement_id USING ERRCODE = 'foreign_key_violation'; END IF;

    -- Cascade taux commission : etab > groupe > 15
    IF v_etab.taux_comm_etab IS NOT NULL THEN
      v_taux_comm_resolved := v_etab.taux_comm_etab;
    ELSIF v_etab.groupe_id IS NOT NULL THEN
      SELECT taux_commission_negocie INTO v_groupe_taux
      FROM groupes_sante WHERE id = v_etab.groupe_id;
      v_taux_comm_resolved := COALESCE(v_groupe_taux, 15);
    ELSE
      v_taux_comm_resolved := 15;
    END IF;

    NEW.taux_horaire_base_fige := NEW.taux_horaire_base;
    NEW.taux_majoration_nuit_fige := v_etab.taux_nuit;
    NEW.taux_majoration_dimanche_fige := v_etab.taux_dim;
    NEW.taux_majoration_ferie_fige := v_etab.taux_fer;
    NEW.heure_debut_nuit_fige := v_etab.h_debut_nuit;
    NEW.heure_fin_nuit_fige := v_etab.h_fin_nuit;
    NEW.taux_commission_fige := v_taux_comm_resolved;
    NEW.fige_le := now();

    -- Step A : figer strategie_facturation selon durée
    -- (NEW.fin_le::date - NEW.debut_le::date) = nombre de jours civils.
    -- Mission lun→dim de la même semaine = 6 jours. Mission lun S1 → mar S2 = 8 jours.
    v_duree_jours := (NEW.fin_le::date - NEW.debut_le::date);
    v_strategie := CASE
      WHEN v_duree_jours > 7 THEN 'HEBDO_ET_FINALE'::public.strategie_facturation
      ELSE 'FINALE_UNIQUE'::public.strategie_facturation
    END;
    NEW.strategie_facturation := v_strategie;

    v_new_code := lpad(floor(random() * 1000000)::text, 6, '0');
    WHILE EXISTS (SELECT 1 FROM missions WHERE code_pointage_actif = v_new_code AND id != NEW.id AND statut IN ('ASSIGNEE','EN_COURS')) LOOP
      v_new_code := lpad(floor(random() * 1000000)::text, 6, '0');
    END LOOP;
    NEW.code_pointage_actif := v_new_code;
    NEW.code_pointage_hmac := CASE WHEN current_setting('app.settings.hmac_secret', true) IS NOT NULL
      THEN encode(extensions.hmac(NEW.id::text || ':' || v_new_code, current_setting('app.settings.hmac_secret', true), 'sha256'), 'hex') ELSE NULL END;
    NEW.prochain_type_scan := 'OUVERTURE';
    NEW.nb_scans := 0;

    INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES (auth.uid(), 'SYSTEME', 'GEL_APPLIED', 'mission', NEW.id,
      jsonb_build_object('snapshot', jsonb_build_object(
        'taux_horaire_base_fige', NEW.taux_horaire_base_fige,
        'taux_majoration_nuit_fige', NEW.taux_majoration_nuit_fige,
        'taux_majoration_dimanche_fige', NEW.taux_majoration_dimanche_fige,
        'taux_majoration_ferie_fige', NEW.taux_majoration_ferie_fige,
        'heure_debut_nuit_fige', NEW.heure_debut_nuit_fige,
        'heure_fin_nuit_fige', NEW.heure_fin_nuit_fige,
        'taux_commission_fige', NEW.taux_commission_fige,
        'taux_commission_source', CASE
          WHEN v_etab.taux_comm_etab IS NOT NULL THEN 'etablissement'
          WHEN v_groupe_taux IS NOT NULL THEN 'groupe'
          ELSE 'defaut_15' END,
        'strategie_facturation', NEW.strategie_facturation,
        'duree_jours', v_duree_jours
      ),
      'code_pointage_genere', true,
      'soignant_assigne_id', NEW.soignant_assigne_id));
    RETURN NEW;
  END IF;

  -- Dégel : remet strategie_facturation au défaut FINALE_UNIQUE
  -- (sera re-figée au prochain gel).
  IF NEW.statut = 'OUVERTE' AND OLD.statut != 'OUVERTE' AND OLD.fige_le IS NOT NULL THEN
    INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES (auth.uid(), 'SYSTEME', 'DEGEL_APPLIED', 'mission', OLD.id,
      jsonb_build_object('old_snapshot', jsonb_build_object(
        'taux_horaire_base_fige', OLD.taux_horaire_base_fige,
        'taux_majoration_nuit_fige', OLD.taux_majoration_nuit_fige,
        'taux_majoration_dimanche_fige', OLD.taux_majoration_dimanche_fige,
        'taux_majoration_ferie_fige', OLD.taux_majoration_ferie_fige,
        'heure_debut_nuit_fige', OLD.heure_debut_nuit_fige,
        'heure_fin_nuit_fige', OLD.heure_fin_nuit_fige,
        'taux_commission_fige', OLD.taux_commission_fige,
        'strategie_facturation', OLD.strategie_facturation,
        'fige_le', OLD.fige_le),
      'old_statut', OLD.statut, 'new_statut', 'OUVERTE',
      'nb_scans_before_degel', OLD.nb_scans));
    PERFORM set_config('jolene.sync_in_progress', 'true', true);
    DELETE FROM mission_creneaux WHERE mission_id = OLD.id AND type_creneau = 'EFFECTIF';
    PERFORM set_config('jolene.sync_in_progress', 'false', true);
    NEW.taux_horaire_base_fige := NULL; NEW.taux_majoration_nuit_fige := NULL;
    NEW.taux_majoration_dimanche_fige := NULL; NEW.taux_majoration_ferie_fige := NULL;
    NEW.heure_debut_nuit_fige := NULL; NEW.heure_fin_nuit_fige := NULL;
    NEW.taux_commission_fige := NULL; NEW.fige_le := NULL;
    NEW.code_pointage_actif := NULL; NEW.code_pointage_hmac := NULL;
    NEW.prochain_type_scan := NULL; NEW.nb_scans := 0;
    NEW.debut_effectif := NULL; NEW.fin_effective := NULL; NEW.duree_heures_effective := NULL;
    NEW.strategie_facturation := 'FINALE_UNIQUE'::public.strategie_facturation;
    RETURN NEW;
  END IF;

  -- Block des modifs post-gel (logique inchangée) — strategie_facturation
  -- ajoutée à la liste des champs protégés (D8 figée à l'assignation).
  IF OLD.fige_le IS NOT NULL THEN
    IF current_setting('jolene.admin_override_gel', true) = OLD.id::text
       AND COALESCE(current_setting('jolene.admin_override_reason', true), '') != '' THEN
      DECLARE v_fm jsonb := '{}'::jsonb; v_or text := current_setting('jolene.admin_override_reason', true);
      BEGIN
        IF NEW.taux_horaire_base IS DISTINCT FROM OLD.taux_horaire_base THEN v_fm := v_fm || jsonb_build_object('taux_horaire_base', jsonb_build_object('old', OLD.taux_horaire_base, 'new', NEW.taux_horaire_base)); END IF;
        IF NEW.intitule IS DISTINCT FROM OLD.intitule THEN v_fm := v_fm || jsonb_build_object('intitule', jsonb_build_object('old', OLD.intitule, 'new', NEW.intitule)); END IF;
        IF NEW.profession_requise IS DISTINCT FROM OLD.profession_requise THEN v_fm := v_fm || jsonb_build_object('profession_requise', jsonb_build_object('old', OLD.profession_requise, 'new', NEW.profession_requise)); END IF;
        IF NEW.taux_horaire_base_fige IS DISTINCT FROM OLD.taux_horaire_base_fige THEN v_fm := v_fm || jsonb_build_object('taux_horaire_base_fige', jsonb_build_object('old', OLD.taux_horaire_base_fige, 'new', NEW.taux_horaire_base_fige)); END IF;
        IF NEW.taux_majoration_nuit_fige IS DISTINCT FROM OLD.taux_majoration_nuit_fige THEN v_fm := v_fm || jsonb_build_object('taux_majoration_nuit_fige', jsonb_build_object('old', OLD.taux_majoration_nuit_fige, 'new', NEW.taux_majoration_nuit_fige)); END IF;
        IF NEW.taux_majoration_dimanche_fige IS DISTINCT FROM OLD.taux_majoration_dimanche_fige THEN v_fm := v_fm || jsonb_build_object('taux_majoration_dimanche_fige', jsonb_build_object('old', OLD.taux_majoration_dimanche_fige, 'new', NEW.taux_majoration_dimanche_fige)); END IF;
        IF NEW.taux_majoration_ferie_fige IS DISTINCT FROM OLD.taux_majoration_ferie_fige THEN v_fm := v_fm || jsonb_build_object('taux_majoration_ferie_fige', jsonb_build_object('old', OLD.taux_majoration_ferie_fige, 'new', NEW.taux_majoration_ferie_fige)); END IF;
        IF NEW.heure_debut_nuit_fige IS DISTINCT FROM OLD.heure_debut_nuit_fige THEN v_fm := v_fm || jsonb_build_object('heure_debut_nuit_fige', jsonb_build_object('old', OLD.heure_debut_nuit_fige, 'new', NEW.heure_debut_nuit_fige)); END IF;
        IF NEW.heure_fin_nuit_fige IS DISTINCT FROM OLD.heure_fin_nuit_fige THEN v_fm := v_fm || jsonb_build_object('heure_fin_nuit_fige', jsonb_build_object('old', OLD.heure_fin_nuit_fige, 'new', NEW.heure_fin_nuit_fige)); END IF;
        IF NEW.taux_commission_fige IS DISTINCT FROM OLD.taux_commission_fige THEN v_fm := v_fm || jsonb_build_object('taux_commission_fige', jsonb_build_object('old', OLD.taux_commission_fige, 'new', NEW.taux_commission_fige)); END IF;
        IF NEW.strategie_facturation IS DISTINCT FROM OLD.strategie_facturation THEN v_fm := v_fm || jsonb_build_object('strategie_facturation', jsonb_build_object('old', OLD.strategie_facturation, 'new', NEW.strategie_facturation)); END IF;
        IF NEW.fige_le IS DISTINCT FROM OLD.fige_le THEN v_fm := v_fm || jsonb_build_object('fige_le', jsonb_build_object('old', OLD.fige_le, 'new', NEW.fige_le)); END IF;
        IF v_fm != '{}'::jsonb THEN INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
          VALUES (auth.uid(), 'ADMIN_PLATEFORME', 'OVERRIDE_CHAMP_POST_GEL', 'mission', OLD.id, jsonb_build_object('reason', v_or, 'fields_modified', v_fm)); END IF;
      END;
      RETURN NEW;
    ELSE
      IF NEW.taux_horaire_base IS DISTINCT FROM OLD.taux_horaire_base THEN v_champ_modifie := 'taux_horaire_base';
      ELSIF NEW.intitule IS DISTINCT FROM OLD.intitule THEN v_champ_modifie := 'intitule';
      ELSIF NEW.profession_requise IS DISTINCT FROM OLD.profession_requise THEN v_champ_modifie := 'profession_requise';
      ELSIF NEW.taux_horaire_base_fige IS DISTINCT FROM OLD.taux_horaire_base_fige THEN v_champ_modifie := 'taux_horaire_base_fige';
      ELSIF NEW.taux_majoration_nuit_fige IS DISTINCT FROM OLD.taux_majoration_nuit_fige THEN v_champ_modifie := 'taux_majoration_nuit_fige';
      ELSIF NEW.taux_majoration_dimanche_fige IS DISTINCT FROM OLD.taux_majoration_dimanche_fige THEN v_champ_modifie := 'taux_majoration_dimanche_fige';
      ELSIF NEW.taux_majoration_ferie_fige IS DISTINCT FROM OLD.taux_majoration_ferie_fige THEN v_champ_modifie := 'taux_majoration_ferie_fige';
      ELSIF NEW.heure_debut_nuit_fige IS DISTINCT FROM OLD.heure_debut_nuit_fige THEN v_champ_modifie := 'heure_debut_nuit_fige';
      ELSIF NEW.heure_fin_nuit_fige IS DISTINCT FROM OLD.heure_fin_nuit_fige THEN v_champ_modifie := 'heure_fin_nuit_fige';
      ELSIF NEW.taux_commission_fige IS DISTINCT FROM OLD.taux_commission_fige THEN v_champ_modifie := 'taux_commission_fige';
      ELSIF NEW.strategie_facturation IS DISTINCT FROM OLD.strategie_facturation THEN v_champ_modifie := 'strategie_facturation';
      ELSIF NEW.fige_le IS DISTINCT FROM OLD.fige_le THEN v_champ_modifie := 'fige_le';
      END IF;
      IF v_champ_modifie IS NOT NULL THEN
        RAISE EXCEPTION 'Modification du champ "%" interdite après assignation (gel du %). Pour corriger, override admin tracé requis.',
          v_champ_modifie, OLD.fige_le USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_geler_mission_a_assignation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_code_otp_6_chiffres"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_bytes bytea;
  v_value bigint;
BEGIN
  LOOP
    v_bytes := extensions.gen_random_bytes(4);
    v_value :=
        get_byte(v_bytes, 0)::bigint * 16777216
      + get_byte(v_bytes, 1)::bigint * 65536
      + get_byte(v_bytes, 2)::bigint * 256
      + get_byte(v_bytes, 3)::bigint;

    -- 4 294 000 000 est le plus grand multiple de 1 000 000 inférieur
    -- à 2^32. Le rejet évite tout biais modulo.
    IF v_value < 4294000000 THEN
      RETURN lpad((v_value % 1000000)::text, 6, '0');
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_generer_code_otp_6_chiffres"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_code_parrainage"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_code TEXT;
BEGIN
    v_code := 'JO-' || UPPER(SUBSTRING(encode(extensions.gen_random_bytes(4), 'hex') FROM 1 FOR 6));
    WHILE EXISTS (SELECT 1 FROM soignants WHERE code_parrainage = v_code) LOOP
        v_code := 'JO-' || UPPER(SUBSTRING(encode(extensions.gen_random_bytes(4), 'hex') FROM 1 FOR 6));
    END LOOP;
    RETURN v_code;
END;
$$;


ALTER FUNCTION "public"."fn_generer_code_parrainage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_code_parrainage_etab"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_code TEXT;
BEGIN
  LOOP
    v_code := 'ETB-' || UPPER(substring(encode(gen_random_bytes(6), 'base64') FROM 1 FOR 6));
    v_code := REGEXP_REPLACE(v_code, '[^A-Z0-9-]', '', 'g');
    WHILE LENGTH(v_code) < 10 LOOP
      v_code := v_code || UPPER(substring(encode(gen_random_bytes(2), 'base64') FROM 1 FOR 2));
      v_code := REGEXP_REPLACE(v_code, '[^A-Z0-9-]', '', 'g');
    END LOOP;
    v_code := substring(v_code FROM 1 FOR 10);
    EXIT WHEN NOT EXISTS (SELECT 1 FROM etablissements WHERE code_parrainage = v_code);
  END LOOP;
  RETURN v_code;
END;
$$;


ALTER FUNCTION "public"."fn_generer_code_parrainage_etab"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_code_secours_mission"("p_mission_id" "uuid", "p_type" "text" DEFAULT 'UNIVERSEL'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_mission RECORD;
  v_code text;
  v_code_hash text;
  v_expire_le timestamptz;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF p_type NOT IN ('ARRIVEE', 'DEPART', 'UNIVERSEL') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TYPE_INVALIDE');
  END IF;

  SELECT id, etablissement_id, fin_le, statut INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MISSION_INTROUVABLE');
  END IF;
  IF NOT (est_admin() OR v_mission.etablissement_id = mon_etablissement_id()) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  -- Invalider codes précédents non utilisés du même type
  UPDATE public.codes_secours_mission
  SET utilise = true, utilise_le = NOW()
  WHERE mission_id = p_mission_id AND type = p_type AND utilise = false;

  -- Générer 6 chiffres aléatoires (uniformément distribués 0-999999)
  v_code := lpad((floor(random() * 1000000))::text, 6, '0');
  v_code_hash := crypt(v_code, gen_salt('bf'));

  v_expire_le := LEAST(
    COALESCE(v_mission.fin_le, NOW() + INTERVAL '7 days') + INTERVAL '2 hours',
    NOW() + INTERVAL '7 days'
  );

  INSERT INTO public.codes_secours_mission (mission_id, code_hash, type, expire_le, cree_par)
  VALUES (p_mission_id, v_code_hash, p_type, v_expire_le, v_uid)
  RETURNING id INTO v_id;

  -- Audit (sans le code en clair !)
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'SYSTEM', 'code_secours_mission', v_id,
    jsonb_build_object('evenement', 'CODE_SECOURS_GENERE',
                        'mission_id', p_mission_id, 'type', p_type,
                        'expire_le', v_expire_le)
  );

  -- Retourne le code EN CLAIR (une seule fois — jamais re-affiché)
  RETURN jsonb_build_object(
    'success', true,
    'id', v_id,
    'code', v_code,
    'type', p_type,
    'expire_le', v_expire_le
  );
END;
$$;


ALTER FUNCTION "public"."fn_generer_code_secours_mission"("p_mission_id" "uuid", "p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_donnees_dpae"("p_contrat_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_payload jsonb;
  v_etab_id uuid;
  v_manquants text[] := ARRAY[]::text[];
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT cm.etablissement_id INTO v_etab_id
  FROM public.contrats_mission cm
  WHERE cm.id = p_contrat_id;

  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contrat introuvable');
  END IF;

  IF NOT (est_admin() OR v_etab_id = mon_etablissement_id()) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  SELECT jsonb_build_object(
    'success', true,
    'contrat_id', cm.id,
    'type_contrat', cm.type_contrat,
    'etablissement', jsonb_build_object(
      'nom', e.nom,
      'siret', e.siret,
      'naf', e.siret_code_naf,
      'adresse_rue', e.adresse_rue,
      'adresse_ville', e.adresse_ville,
      'adresse_code_postal', e.adresse_code_postal,
      'telephone', e.telephone_contact,
      'email', e.email_contact,
      'organisme_protection_sociale', 'URSSAF'
    ),
    'salarie', jsonb_build_object(
      'nom', s.nom,
      'prenom', s.prenom,
      'sexe', s.sexe,
      'date_naissance', s.date_naissance,
      'lieu_naissance_commune', s.lieu_naissance_commune,
      'lieu_naissance_departement', s.lieu_naissance_departement,
      'pays_naissance', COALESCE(s.pays_naissance, 'France'),
      'nationalite', COALESCE(s.nationalite, 'Française'),
      'numero_securite_sociale', COALESCE(s.numero_securite_sociale, s.numero_secu),
      'adresse_rue', s.adresse_rue,
      'adresse_code_postal', s.adresse_code_postal,
      'adresse_ville', s.adresse_ville,
      'profession', s.profession,
      'champs_a_completer_sur_net_entreprises', (
        SELECT COALESCE(jsonb_agg(m), '[]'::jsonb) FROM (
          SELECT 'sexe' AS m WHERE s.sexe IS NULL
          UNION ALL SELECT 'lieu_naissance_commune' WHERE s.lieu_naissance_commune IS NULL AND COALESCE(s.pays_naissance, 'France') = 'France'
          UNION ALL SELECT 'lieu_naissance_departement' WHERE s.lieu_naissance_departement IS NULL AND COALESCE(s.pays_naissance, 'France') = 'France'
          UNION ALL SELECT 'pays_naissance' WHERE s.pays_naissance IS NULL
          UNION ALL SELECT 'nationalite' WHERE s.nationalite IS NULL
          UNION ALL SELECT 'numero_securite_sociale' WHERE COALESCE(s.numero_securite_sociale, s.numero_secu) IS NULL
        ) t
      )
    ),
    'embauche', jsonb_build_object(
      'date_prevue', m.debut_le,
      'heure_prevue', to_char(m.debut_le, 'HH24:MI'),
      'date_fin', m.fin_le,
      'type_contrat', cm.type_contrat,
      'duree_heures_prevues', m.duree_heures
    ),
    'urssaf_url', 'https://www.net-entreprises.fr/declaration-prealable-embauche/',
    'note', 'Copiez ces données dans le formulaire DPAE Net-Entreprises. Les champs marqués dans champs_a_completer_sur_net_entreprises ne sont pas encore renseignés par le soignant — demandez-lui de compléter son profil ou saisissez-les manuellement.'
  )
  INTO v_payload
  FROM public.contrats_mission cm
  JOIN public.missions m ON m.id = cm.mission_id
  JOIN public.etablissements e ON e.id = cm.etablissement_id
  JOIN public.soignants s ON s.id = cm.soignant_id
  WHERE cm.id = p_contrat_id;

  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."fn_generer_donnees_dpae"("p_contrat_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_facture"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
    v_mission RECORD;
    v_facture_id UUID;
    v_numero TEXT;
    v_annee TEXT := to_char(NOW(), 'YYYY');
    v_seq INTEGER;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN '{"error":"Mission introuvable"}'::JSONB; END IF;
    IF NOT est_admin() AND v_mission.etablissement_id != mon_etablissement_id() THEN
        RETURN '{"error":"Accès refusé"}'::JSONB;
    END IF;
    IF v_mission.statut != 'TERMINEE' THEN
        RETURN '{"error":"La mission doit être TERMINEE"}'::JSONB;
    END IF;
    IF EXISTS (SELECT 1 FROM factures WHERE mission_id = p_mission_id) THEN
        RETURN '{"error":"Facture déjà existante"}'::JSONB;
    END IF;

    SELECT COALESCE(MAX(CAST(SUBSTRING(numero_facture FROM '\d+$') AS INTEGER)), 0) + 1
    INTO v_seq FROM factures WHERE numero_facture LIKE 'JOL-' || v_annee || '-%';
    v_numero := 'JOL-' || v_annee || '-' || LPAD(v_seq::TEXT, 5, '0');

    INSERT INTO factures (
        numero_facture, etablissement_id, mission_id,
        montant_ht, taux_tva, montant_tva, montant_ttc,
        nombre_missions, statut, date_emission, date_echeance
    ) VALUES (
        v_numero, v_mission.etablissement_id, p_mission_id,
        COALESCE(v_mission.montant_commission_ht, 0),
        20,
        COALESCE(v_mission.montant_commission_tva, 0),
        COALESCE(v_mission.montant_commission_ttc, 0),
        1, 'EMISE', NOW(), (NOW() + INTERVAL '30 days')::DATE
    ) RETURNING id INTO v_facture_id;

    UPDATE missions SET commission_facturee = TRUE, modifie_le = NOW() WHERE id = p_mission_id;

    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (v_mission.etablissement_id, 'FACTURE_EMISE', 'Facture ' || v_numero,
        'Montant TTC : ' || COALESCE(v_mission.montant_commission_ttc, 0) || '€',
        '/etablissement/facturation', 'ETABLISSEMENT');

    RETURN jsonb_build_object('success', true, 'facture_id', v_facture_id, 'numero', v_numero);
END;
$_$;


ALTER FUNCTION "public"."fn_generer_facture"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_facture_honoraires_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_soignant RECORD;
    v_numero TEXT;
    v_facture_id UUID;
    v_existing_id UUID;
    v_periode_debut DATE;
    v_periode_fin DATE;
BEGIN
    SELECT m.*, e.nom AS etab_nom
    INTO v_mission
    FROM missions m
    JOIN etablissements e ON e.id = m.etablissement_id
    WHERE m.id = p_mission_id AND m.statut = 'TERMINEE';

    IF v_mission IS NULL THEN
        RETURN '{"error":"Mission introuvable ou non terminée"}'::JSONB;
    END IF;

    IF v_mission.soignant_assigne_id IS NULL THEN
        RETURN '{"error":"Aucun soignant assigné"}'::JSONB;
    END IF;

    SELECT * INTO v_soignant FROM soignants WHERE id = v_mission.soignant_assigne_id;
    IF v_soignant IS NULL THEN
        RETURN '{"error":"Soignant introuvable"}'::JSONB;
    END IF;

    IF NOT COALESCE(v_soignant.mandat_facturation_signe, FALSE) THEN
        RETURN '{"error":"Le soignant n''a pas encore signé le mandat de facturation"}'::JSONB;
    END IF;

    SELECT id INTO v_existing_id FROM factures_honoraires WHERE mission_id = p_mission_id LIMIT 1;
    IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'facture_id', v_existing_id, 'message', 'Facture déjà existante');
    END IF;

    v_numero := 'FH-' || to_char(now(), 'YYYY-MM') || '-' || lpad(
        (COALESCE((SELECT COUNT(*) FROM factures_honoraires WHERE date_emission >= date_trunc('month', now())), 0) + 1)::TEXT,
        4, '0'
    );

    -- Période de la facture = bornes de la mission (NOT NULL en base)
    v_periode_debut := COALESCE(v_mission.debut_le::date, CURRENT_DATE);
    v_periode_fin := COALESCE(v_mission.fin_le::date, v_mission.debut_le::date, CURRENT_DATE);

    INSERT INTO factures_honoraires (
        numero_facture, soignant_id, etablissement_id, mission_id,
        montant_ht, montant_tva, montant_ttc, taux_tva, exoneration_tva,
        date_emission, date_echeance, statut, mandat_version,
        periode_debut, periode_fin,
        numero_semaine_iso, annee_iso
    ) VALUES (
        v_numero,
        v_mission.soignant_assigne_id,
        v_mission.etablissement_id,
        p_mission_id,
        COALESCE(v_mission.net_a_payer, v_mission.total_brut, 0),
        0,
        COALESCE(v_mission.net_a_payer, v_mission.total_brut, 0),
        0,
        TRUE,
        CURRENT_DATE,
        CURRENT_DATE + INTERVAL '30 days',
        'EMISE',
        v_soignant.mandat_facturation_version,
        v_periode_debut,
        v_periode_fin,
        EXTRACT(WEEK FROM v_periode_debut)::smallint,
        EXTRACT(ISOYEAR FROM v_periode_debut)::smallint
    ) RETURNING id INTO v_facture_id;

    RETURN jsonb_build_object('success', true, 'facture_id', v_facture_id, 'numero', v_numero);
END;
$$;


ALTER FUNCTION "public"."fn_generer_facture_honoraires_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_facture_mensuelle"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_total_ht NUMERIC; v_total_tva NUMERIC; v_total_ttc NUMERIC;
    v_nb INT; v_numero TEXT; v_facture_id UUID;
BEGIN
    IF p_etablissement_id != mon_etablissement_id() AND NOT est_admin() THEN
        RETURN '{"error":"Accès refusé"}'::JSONB;
    END IF;
    SELECT COALESCE(SUM(montant_commission_ht), 0), COALESCE(SUM(montant_commission_tva), 0),
           COALESCE(SUM(montant_commission_ttc), 0), COUNT(*)
    INTO v_total_ht, v_total_tva, v_total_ttc, v_nb
    FROM missions WHERE etablissement_id = p_etablissement_id AND statut = 'TERMINEE' AND commission_facturee = FALSE;
    IF v_total_ht = 0 THEN RETURN '{"error":"Aucune mission à facturer"}'::JSONB; END IF;
    v_numero := fn_generer_numero_facture();
    INSERT INTO factures (etablissement_id, numero_facture, statut, montant_ht, taux_tva, montant_tva, montant_ttc,
        nombre_missions, date_emission, date_echeance, periode_debut, periode_fin)
    VALUES (p_etablissement_id, v_numero, 'EMISE', v_total_ht, 20, v_total_tva, v_total_ttc,
        v_nb, NOW(), (NOW() + INTERVAL '30 days')::DATE,
        DATE_TRUNC('month', NOW())::DATE, (DATE_TRUNC('month', NOW()) + INTERVAL '1 month' - INTERVAL '1 day')::DATE)
    RETURNING id INTO v_facture_id;
    UPDATE missions SET commission_facturee = TRUE, facture_id = v_facture_id
    WHERE etablissement_id = p_etablissement_id AND statut = 'TERMINEE' AND commission_facturee = FALSE;
    RETURN jsonb_build_object('success', true, 'facture_id', v_facture_id, 'numero', v_numero, 'montant_ttc', v_total_ttc, 'nb_missions', v_nb);
END;
$$;


ALTER FUNCTION "public"."fn_generer_facture_mensuelle"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_generer_facture_rate_limited"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_etab_id UUID := mon_etablissement_id();
    v_allowed BOOLEAN;
BEGIN
    IF v_user_id IS NULL OR v_etab_id IS NULL THEN 
        RETURN jsonb_build_object('error', 'Non authentifié'); 
    END IF;
    v_allowed := fn_verifier_rate_limit(v_user_id::TEXT, 'facture', 5, 3600);
    IF NOT v_allowed THEN 
        RETURN jsonb_build_object('error', 'Trop de tentatives. Réessayez dans quelques minutes.'); 
    END IF;
    RETURN fn_generer_facture_mensuelle(v_etab_id);
END;
$$;


