CREATE OR REPLACE FUNCTION "public"."fn_haversine_distance_m"("p_lat1" numeric, "p_lng1" numeric, "p_lat2" numeric, "p_lng2" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
DECLARE
  v_r constant numeric := 6371000;
  v_phi1 numeric; v_phi2 numeric; v_dphi numeric; v_dlambda numeric;
  v_a numeric; v_c numeric;
BEGIN
  IF p_lat1 IS NULL OR p_lng1 IS NULL OR p_lat2 IS NULL OR p_lng2 IS NULL THEN RETURN NULL; END IF;
  v_phi1 := radians(p_lat1); v_phi2 := radians(p_lat2);
  v_dphi := radians(p_lat2 - p_lat1); v_dlambda := radians(p_lng2 - p_lng1);
  v_a := sin(v_dphi/2) * sin(v_dphi/2) + cos(v_phi1) * cos(v_phi2) * sin(v_dlambda/2) * sin(v_dlambda/2);
  v_c := 2 * atan2(sqrt(v_a), sqrt(1 - v_a));
  RETURN round(v_r * v_c);
END;
$$;


ALTER FUNCTION "public"."fn_haversine_distance_m"("p_lat1" numeric, "p_lng1" numeric, "p_lat2" numeric, "p_lng2" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_health_check"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_soignants INTEGER;
    v_missions INTEGER;
    v_dernier_audit TIMESTAMPTZ;
BEGIN
    SELECT COUNT(*) INTO v_soignants FROM soignants WHERE supprime_le IS NULL;
    SELECT COUNT(*) INTO v_missions FROM missions WHERE statut = 'OUVERTE';
    SELECT MAX(cree_le) INTO v_dernier_audit FROM journaux_audit;

    INSERT INTO health_check (service, statut, details)
    VALUES ('API', 'OK', jsonb_build_object(
        'soignants_actifs', v_soignants,
        'missions_ouvertes', v_missions,
        'dernier_audit', v_dernier_audit,
        'timestamp', NOW()
    ));

    RETURN jsonb_build_object(
        'status', 'OK',
        'soignants', v_soignants,
        'missions_ouvertes', v_missions,
        'dernier_audit', v_dernier_audit
    );
END;
$$;


ALTER FUNCTION "public"."fn_health_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_heures_mission_semaine"("p_mission_id" "uuid", "p_semaine_debut" "date") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH bornes AS (
    SELECT
      p_semaine_debut::timestamp AT TIME ZONE 'Europe/Paris' AS debut_ts,
      (p_semaine_debut + 7)::timestamp AT TIME ZONE 'Europe/Paris' AS fin_ts
  ), mission AS (
    SELECT m.* FROM public.missions m WHERE m.id = p_mission_id
  ), type_reference AS (
    SELECT CASE
      WHEN m.statut = 'TERMINEE' AND EXISTS (
        SELECT 1 FROM public.mission_creneaux mc
        WHERE mc.mission_id = m.id
          AND mc.type_creneau = 'EFFECTIF'
          AND mc.fin IS NOT NULL
          AND NOT mc.est_pause
      ) THEN 'EFFECTIF'
      WHEN EXISTS (
        SELECT 1 FROM public.mission_creneaux mc
        WHERE mc.mission_id = m.id
          AND mc.type_creneau = 'PREVISIONNEL'
          AND mc.fin IS NOT NULL
          AND NOT mc.est_pause
      ) THEN 'PREVISIONNEL'
      WHEN EXISTS (
        SELECT 1 FROM public.mission_creneaux mc
        WHERE mc.mission_id = m.id
          AND mc.type_creneau = 'EFFECTIF'
          AND mc.fin IS NOT NULL
          AND NOT mc.est_pause
      ) THEN 'EFFECTIF'
      ELSE NULL
    END AS type_creneau
    FROM mission m
  ), heures_creneaux AS (
    SELECT sum(
      extract(epoch FROM (
        least(mc.fin, b.fin_ts) - greatest(mc.debut, b.debut_ts)
      )) / 3600.0
    ) AS heures
    FROM public.mission_creneaux mc
    CROSS JOIN bornes b
    CROSS JOIN type_reference tr
    WHERE tr.type_creneau IS NOT NULL
      AND mc.mission_id = p_mission_id
      AND mc.type_creneau = tr.type_creneau
      AND mc.fin IS NOT NULL
      AND NOT mc.est_pause
      AND mc.debut < b.fin_ts
      AND mc.fin > b.debut_ts
  ), reference_repli AS (
    SELECT
      CASE WHEN m.statut = 'TERMINEE'
        THEN COALESCE(m.debut_effectif, m.debut_le)
        ELSE m.debut_le
      END AS debut_ref,
      CASE WHEN m.statut = 'TERMINEE'
        THEN COALESCE(m.fin_effective, m.fin_le)
        ELSE m.fin_le
      END AS fin_ref,
      CASE WHEN m.statut = 'TERMINEE'
        THEN COALESCE(
          m.duree_heures_effective,
          m.duree_heures,
          extract(epoch FROM (
            COALESCE(m.fin_effective, m.fin_le)
            - COALESCE(m.debut_effectif, m.debut_le)
          )) / 3600.0,
          0
        )
        ELSE COALESCE(
          m.duree_heures,
          extract(epoch FROM (m.fin_le - m.debut_le)) / 3600.0,
          0
        )
      END::numeric AS duree_ref,
      COALESCE(m.nb_creneaux, 0) AS nb_creneaux
    FROM mission m
  ), heures_repli AS (
    SELECT CASE
      WHEN tr.type_creneau IS NULL
       AND rr.nb_creneaux <= 1
       AND rr.debut_ref < b.fin_ts
       AND rr.fin_ref > b.debut_ts
       AND rr.fin_ref > rr.debut_ref
      THEN rr.duree_ref * (
        extract(epoch FROM (
          least(rr.fin_ref, b.fin_ts) - greatest(rr.debut_ref, b.debut_ts)
        )) / NULLIF(extract(epoch FROM (rr.fin_ref - rr.debut_ref)), 0)
      )
      ELSE 0
    END AS heures
    FROM reference_repli rr
    CROSS JOIN bornes b
    CROSS JOIN type_reference tr
  )
  SELECT round(COALESCE(hc.heures, hr.heures, 0)::numeric, 2)
  FROM heures_creneaux hc CROSS JOIN heures_repli hr;
$$;


ALTER FUNCTION "public"."fn_heures_mission_semaine"("p_mission_id" "uuid", "p_semaine_debut" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_heures_soignant_semaine"("p_soignant_id" "uuid", "p_semaine_debut" "date", "p_exclure_mission_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT round(COALESCE(sum(
    public.fn_heures_mission_semaine(m.id, p_semaine_debut)
  ), 0)::numeric, 2)
  FROM public.missions m
  WHERE m.soignant_assigne_id = p_soignant_id
    AND m.id IS DISTINCT FROM p_exclure_mission_id
    AND m.statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE')
    AND (CASE WHEN m.statut = 'TERMINEE'
      THEN COALESCE(m.debut_effectif, m.debut_le)
      ELSE m.debut_le
    END) < ((p_semaine_debut + 7)::timestamp AT TIME ZONE 'Europe/Paris')
    AND (CASE WHEN m.statut = 'TERMINEE'
      THEN COALESCE(m.fin_effective, m.fin_le)
      ELSE m.fin_le
    END) > (p_semaine_debut::timestamp AT TIME ZONE 'Europe/Paris')
    AND COALESCE(
      m.type_contrat_applique::text,
      NULLIF(upper(m.choix_contrat_soignant), ''),
      CASE WHEN m.type_contrat_recherche::text = 'LIBERAL' THEN 'LIBERAL' ELSE 'SALARIE' END
    ) = 'SALARIE';
$$;


ALTER FUNCTION "public"."fn_heures_soignant_semaine"("p_soignant_id" "uuid", "p_semaine_debut" "date", "p_exclure_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_html_escape"("p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN REPLACE(REPLACE(REPLACE(REPLACE(
        COALESCE(p_text, ''),
        '&', '&amp;'),
        '<', '&lt;'),
        '>', '&gt;'),
        '"', '&quot;');
    -- Apostrophes intentionnellement non encodées
END;
$$;


ALTER FUNCTION "public"."fn_html_escape"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_iban_est_valide"("p_iban" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_iban text := upper(regexp_replace(COALESCE(p_iban, ''), '[^A-Za-z0-9]', '', 'g'));
  v_rearranged text;
  v_char text;
  v_numeric text;
  v_remainder integer := 0;
  i integer;
  j integer;
BEGIN
  IF v_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$' THEN
    RETURN false;
  END IF;

  v_rearranged := substring(v_iban FROM 5) || substring(v_iban FROM 1 FOR 4);
  FOR i IN 1..length(v_rearranged) LOOP
    v_char := substring(v_rearranged FROM i FOR 1);
    v_numeric := CASE
      WHEN v_char ~ '^[A-Z]$' THEN (ascii(v_char) - 55)::text
      ELSE v_char
    END;
    FOR j IN 1..length(v_numeric) LOOP
      v_remainder := (
        v_remainder * 10 + substring(v_numeric FROM j FOR 1)::integer
      ) % 97;
    END LOOP;
  END LOOP;
  RETURN v_remainder = 1;
END;
$_$;


ALTER FUNCTION "public"."fn_iban_est_valide"("p_iban" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_init_proprietaire_etab"("p_etablissement_id" "uuid", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_uid uuid;
  v_membre_id uuid;
BEGIN
  IF v_caller IS NULL THEN
    -- Appel serveur (register-etablissement en service_role)
    v_uid := p_user_id;
    IF v_uid IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
    END IF;
  ELSE
    -- Appel client authentifié : on ignore p_user_id et on vérifie la revendication
    v_uid := v_caller;
    IF NOT (
      est_admin()
      OR EXISTS (
        SELECT 1 FROM auth.users u
        WHERE u.id = v_caller
          AND (u.raw_app_meta_data ->> 'etablissement_id') = p_etablissement_id::text
      )
    ) THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.membres_etablissement
    WHERE etablissement_id = p_etablissement_id AND actif = true
  ) THEN
    RETURN jsonb_build_object('success', true, 'message', 'Membres déjà présents');
  END IF;

  INSERT INTO public.membres_etablissement (
    etablissement_id, user_id, role, accepte_le, actif
  ) VALUES (
    p_etablissement_id, v_uid, 'PROPRIETAIRE', now(), true
  )
  RETURNING id INTO v_membre_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'MODIFICATION_PROFIL', 'membre_etablissement', v_membre_id,
    jsonb_build_object(
      'evenement', 'PROPRIETAIRE_INITIALISE',
      'etablissement_id', p_etablissement_id
    )
  );

  RETURN jsonb_build_object('success', true, 'membre_id', v_membre_id);
END;
$$;


ALTER FUNCTION "public"."fn_init_proprietaire_etab"("p_etablissement_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_initialiser_preferences_matching"("p_pref_nuit" numeric, "p_pref_jour" numeric, "p_pref_weekend" numeric, "p_pref_semaine" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;
  IF p_pref_nuit NOT BETWEEN 0 AND 1 OR p_pref_jour NOT BETWEEN 0 AND 1
     OR p_pref_weekend NOT BETWEEN 0 AND 1 OR p_pref_semaine NOT BETWEEN 0 AND 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Préférences hors bornes [0,1]');
  END IF;

  INSERT INTO public.matching_preferences_soignant
    (soignant_id, pref_nuit, pref_jour, pref_weekend, pref_semaine, nb_signaux, maj_le)
  VALUES (v_uid, p_pref_nuit, p_pref_jour, p_pref_weekend, p_pref_semaine, 0, now())
  ON CONFLICT (soignant_id) DO UPDATE SET
    pref_nuit = EXCLUDED.pref_nuit,
    pref_jour = EXCLUDED.pref_jour,
    pref_weekend = EXCLUDED.pref_weekend,
    pref_semaine = EXCLUDED.pref_semaine,
    maj_le = now()
  WHERE matching_preferences_soignant.nb_signaux = 0;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_initialiser_preferences_matching"("p_pref_nuit" numeric, "p_pref_jour" numeric, "p_pref_weekend" numeric, "p_pref_semaine" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_inscrire_liste_attente_prevoyance"("p_email" "text", "p_niveau" "text" DEFAULT 'INDIFFERENT'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_uid UUID := auth.uid();
  v_email_clean TEXT;
  v_niveau public.niveau_prevoyance_souhaite;
  v_id UUID;
  v_existing UUID;
BEGIN
  v_email_clean := LOWER(TRIM(COALESCE(p_email, '')));
  IF v_email_clean = '' OR v_email_clean !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Email invalide');
  END IF;

  BEGIN
    v_niveau := COALESCE(UPPER(TRIM(p_niveau)), 'INDIFFERENT')::public.niveau_prevoyance_souhaite;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', 'Niveau invalide (BRONZE/ARGENT/OR/INDIFFERENT)');
  END;

  SELECT id INTO v_existing FROM prevoyance_liste_attente WHERE email = v_email_clean;
  IF v_existing IS NOT NULL THEN
    UPDATE prevoyance_liste_attente
    SET niveau_souhaite = v_niveau,
        soignant_id = COALESCE(v_uid, soignant_id),
        mis_a_jour_le = NOW()
    WHERE id = v_existing
    RETURNING id INTO v_id;
  ELSE
    INSERT INTO prevoyance_liste_attente (soignant_id, email, niveau_souhaite)
    VALUES (v_uid, v_email_clean, v_niveau)
    RETURNING id INTO v_id;
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := COALESCE(v_uid, v_id),
    p_type_acteur := CASE WHEN v_uid IS NULL THEN 'SYSTEME' ELSE 'SOIGNANT' END,
    p_action := 'INSCRIPTION_LISTE_ATTENTE_PREVOYANCE',
    p_type_ressource := 'prevoyance_liste_attente',
    p_id_ressource := v_id,
    p_details := jsonb_build_object('email', v_email_clean, 'niveau', v_niveau::text, 'updated', v_existing IS NOT NULL)
  );

  RETURN jsonb_build_object(
    'success', true,
    'id', v_id,
    'updated', v_existing IS NOT NULL,
    'message', 'Vous êtes inscrit·e sur la liste d''attente. Vous serez prévenu·e dès le lancement.'
  );
END;
$_$;


ALTER FUNCTION "public"."fn_inscrire_liste_attente_prevoyance"("p_email" "text", "p_niveau" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_interlocuteurs_conversations"("p_conversation_ids" "uuid"[]) RETURNS TABLE("conversation_id" "uuid", "participant_id" "uuid", "prenom" "text", "nom" "text", "avatar_url" "text", "est_jolene" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;
  IF public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Compte inactif' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(cardinality(p_conversation_ids), 0) = 0 THEN
    RETURN;
  END IF;
  IF cardinality(p_conversation_ids) > 100 THEN
    RAISE EXCEPTION 'Trop de conversations demandées' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH conversations_autorisees AS (
    SELECT
      c.id,
      c.mission_id,
      c.etablissement_id,
      c.soignant_id,
      c.participant_1_id,
      c.participant_2_id
    FROM public.conversations c
    WHERE c.id = ANY(p_conversation_ids)
      AND public.fn_conversation_accessible(c.id)
  ), participants AS (
    SELECT
      c.id AS conversation_id,
      c.mission_id,
      c.etablissement_id,
      COALESCE(c.soignant_id, c.participant_1_id) AS participant_id
    FROM conversations_autorisees c

    UNION ALL

    SELECT
      c.id AS conversation_id,
      c.mission_id,
      c.etablissement_id,
      CASE
        WHEN c.etablissement_id IS NOT NULL
         AND c.soignant_id IS NOT NULL THEN
          private.fn_interlocuteur_operationnel_id(c.etablissement_id)
        ELSE c.participant_2_id
      END AS participant_id
    FROM conversations_autorisees c
  )
  SELECT
    p.conversation_id,
    p.participant_id,
    CASE
      WHEN s.id IS NOT NULL THEN s.prenom
      WHEN e.id IS NOT NULL THEN e.nom
      ELSE 'Jolene'
    END::text AS prenom,
    CASE WHEN s.id IS NOT NULL THEN s.nom ELSE '' END::text AS nom,
    CASE WHEN s.id IS NOT NULL THEN s.avatar_url ELSE e.logo_url END::text,
    (s.id IS NULL AND e.id IS NULL) AS est_jolene
  FROM participants p
  LEFT JOIN public.soignants s
    ON s.id = p.participant_id
   AND s.supprime_le IS NULL
  LEFT JOIN LATERAL (
    SELECT e0.id, e0.nom, e0.logo_url
    FROM public.etablissements e0
    WHERE s.id IS NULL
      AND e0.supprime_le IS NULL
      AND (
        (
          p.etablissement_id IS NOT NULL
          AND e0.id = p.etablissement_id
        )
        OR (
          p.etablissement_id IS NULL
          AND (
            e0.id = p.participant_id
            OR EXISTS (
              SELECT 1
              FROM public.membres_etablissement me
              WHERE me.user_id = p.participant_id
                AND me.etablissement_id = e0.id
                AND me.actif IS TRUE
            )
            OR EXISTS (
              SELECT 1
              FROM auth.users u
              WHERE u.id = p.participant_id
                AND u.raw_app_meta_data ->> 'etablissement_id' = e0.id::text
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.membres_etablissement me
                  WHERE me.user_id = u.id
                )
            )
          )
        )
      )
    ORDER BY
      CASE WHEN e0.id = COALESCE(
        p.etablissement_id,
        (
          SELECT mi.etablissement_id
          FROM public.missions mi
          WHERE mi.id = p.mission_id
        )
      ) THEN 0 ELSE 1 END,
      e0.id
    LIMIT 1
  ) e ON true
  WHERE p.participant_id IS NOT NULL
  ORDER BY p.conversation_id, p.participant_id;
END;
$$;


ALTER FUNCTION "public"."fn_interlocuteurs_conversations"("p_conversation_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_interlocuteurs_conversations"("p_conversation_ids" "uuid"[]) IS 'Projection messagerie nom/avatar des seuls participants de conversations accessibles a l appelant.';



CREATE OR REPLACE FUNCTION "public"."fn_invalider_preuve_identite_siret_manuelle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_document_id uuid := OLD.id;
  v_previous_reset text := COALESCE(
    current_setting('jolene.siret_liberal_reset', true),
    ''
  );
BEGIN
  IF TG_OP = 'UPDATE'
     AND ROW(
       NEW.soignant_id,
       NEW.type_document,
       NEW.s3_bucket,
       NEW.s3_cle,
       NEW.s3_version_id,
       NEW.valide_jusqua,
       NEW.statut_verification,
       NEW.verifie_le,
       NEW.supprime_le,
       NEW.revoque_le,
       NEW.resultat_ia,
       NEW.nom_extrait_ia,
       NEW.prenom_extrait_ia,
       NEW.coherence_nom
     ) IS NOT DISTINCT FROM ROW(
       OLD.soignant_id,
       OLD.type_document,
       OLD.s3_bucket,
       OLD.s3_cle,
       OLD.s3_version_id,
       OLD.valide_jusqua,
       OLD.statut_verification,
       OLD.verifie_le,
       OLD.supprime_le,
       OLD.revoque_le,
       OLD.resultat_ia,
       OLD.nom_extrait_ia,
       OLD.prenom_extrait_ia,
       OLD.coherence_nom
     ) THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('jolene.siret_liberal_reset', 'true', true);
  BEGIN
    UPDATE public.soignants
    SET siret_liberal_verifie = false,
        siret_liberal_verifie_le = NULL,
        siret_liberal_raison_sociale = NULL,
        siret_liberal_coherence_identite = NULL,
        siret_liberal_source_verification = NULL,
        siret_liberal_preuve_siret = NULL,
        siret_liberal_preuve_identite_document_id = NULL,
        siret_liberal_preuve_identite_document_modifie_le = NULL,
        siret_liberal_preuve_identite_s3_bucket = NULL,
        siret_liberal_preuve_identite_s3_cle = NULL,
        siret_liberal_preuve_identite_s3_version_id = NULL,
        siret_liberal_preuve_identite_storage_object_id = NULL,
        siret_liberal_preuve_identite_storage_updated_at = NULL,
        siret_liberal_preuve_identite_valide_jusqua = NULL,
        siret_liberal_preuve_identite_empreinte_sha256 = NULL,
        tous_documents_valides = false,
        modifie_le = now()
    WHERE siret_liberal_preuve_identite_document_id = v_document_id
      AND siret_liberal_source_verification = 'REVUE_MANUELLE_IDENTITE';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('jolene.siret_liberal_reset', v_previous_reset, true);
    RAISE;
  END;
  PERFORM set_config('jolene.siret_liberal_reset', v_previous_reset, true);

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_invalider_preuve_identite_siret_manuelle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_invalider_preuves_identite_sur_changement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_previous_system_update text := COALESCE(current_setting('jolene.system_update', true), '');
  v_previous_siret_reset text := COALESCE(current_setting('jolene.siret_liberal_reset', true), '');
  v_documents_invalides integer := 0;
  v_champs text[] := ARRAY[]::text[];
  v_nom_prenom_modifie boolean;
BEGIN
  IF NEW.prenom IS NOT DISTINCT FROM OLD.prenom
     AND NEW.nom IS NOT DISTINCT FROM OLD.nom
     AND NEW.date_naissance IS NOT DISTINCT FROM OLD.date_naissance THEN
    RETURN NEW;
  END IF;

  IF NEW.prenom IS DISTINCT FROM OLD.prenom THEN v_champs := array_append(v_champs, 'prenom'); END IF;
  IF NEW.nom IS DISTINCT FROM OLD.nom THEN v_champs := array_append(v_champs, 'nom'); END IF;
  IF NEW.date_naissance IS DISTINCT FROM OLD.date_naissance THEN v_champs := array_append(v_champs, 'date_naissance'); END IF;
  v_nom_prenom_modifie := NEW.prenom IS DISTINCT FROM OLD.prenom
    OR NEW.nom IS DISTINCT FROM OLD.nom;

  PERFORM set_config('jolene.system_update', 'true', true);
  PERFORM set_config('jolene.siret_liberal_reset', 'true', true);
  BEGIN
    UPDATE public.documents_soignants
    SET statut_verification = 'EN_ATTENTE',
        motif_rejet = 'Profil d’identité modifié après vérification — nouvelle vérification de la preuve requise.',
        verifie_le = NULL,
        verifie_par = NULL,
        valide_depuis = NULL,
        valide_jusqua = NULL,
        modifie_le = now()
    WHERE soignant_id = NEW.id
      AND statut_verification = 'VERIFIE'
      AND supprime_le IS NULL;
    GET DIAGNOSTICS v_documents_invalides = ROW_COUNT;

    UPDATE public.soignants
    SET identite_verifiee = false,
        diplome_verifie = false,
        tous_documents_valides = false,
        statut_verification_aria = 'EN_ATTENTE',
        siret_liberal_verifie = false,
        siret_liberal_verifie_le = NULL,
        siret_liberal_raison_sociale = NULL,
        siret_liberal_coherence_identite = NULL,
        rpps_verifie = CASE WHEN v_nom_prenom_modifie THEN false ELSE rpps_verifie END,
        rpps_verifie_le = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE rpps_verifie_le END,
        rpps_nom_api = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE rpps_nom_api END,
        rpps_prenom_api = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE rpps_prenom_api END,
        rpps_profession_api = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE rpps_profession_api END,
        adeli_verifie = CASE WHEN v_nom_prenom_modifie THEN false ELSE adeli_verifie END,
        adeli_verifie_le = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE adeli_verifie_le END,
        adeli_nom_api = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE adeli_nom_api END,
        adeli_prenom_api = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE adeli_prenom_api END,
        adeli_profession_api = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE adeli_profession_api END,
        specialite_verifiee = CASE WHEN v_nom_prenom_modifie THEN false ELSE specialite_verifiee END,
        specialite_verifiee_le = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE specialite_verifiee_le END,
        specialite_medicale = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE specialite_medicale END,
        specialite_code = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE specialite_code END,
        specialite_source = CASE WHEN v_nom_prenom_modifie THEN NULL ELSE specialite_source END,
        coherence_identite = 'EN_ATTENTE_REVUE',
        coherence_details = jsonb_build_object(
          'raison', 'PROFIL_IDENTITE_MODIFIE',
          'champs_modifies', to_jsonb(v_champs),
          'documents_invalides', v_documents_invalides,
          'invalide_le', now()
        ),
        modifie_le = now()
    WHERE id = NEW.id;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('jolene.siret_liberal_reset', v_previous_siret_reset, true);
    PERFORM set_config('jolene.system_update', v_previous_system_update, true);
    RAISE;
  END;
  PERFORM set_config('jolene.siret_liberal_reset', v_previous_siret_reset, true);
  PERFORM set_config('jolene.system_update', v_previous_system_update, true);

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := NEW.id,
    p_type_acteur := CASE WHEN auth.uid() = NEW.id THEN 'SOIGNANT' ELSE 'SYSTEME' END,
    p_action := 'IDENTITE_PROFIL_MODIFIEE',
    p_type_ressource := 'soignant',
    p_id_ressource := NEW.id,
    p_details := jsonb_build_object(
      'champs_modifies', to_jsonb(v_champs),
      'preuves_identite_invalidees', v_documents_invalides
    )
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_invalider_preuves_identite_sur_changement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_invalider_provenance_iban_depuis_document"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_document_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
  v_type public.type_document := CASE WHEN TG_OP = 'DELETE' THEN OLD.type_document ELSE NEW.type_document END;
BEGIN
  PERFORM set_config('jolene.bank_server_update', 'true', true);
  UPDATE public.soignants
  SET iban_source_document_id = NULL,
      iban_identite_document_id = NULL,
      iban_source_s3_cle = NULL,
      iban_empreinte_sha256 = NULL,
      iban_verifie_le = NULL,
      iban_titulaire_coherent = false,
      modifie_le = now()
  WHERE iban_source_document_id = v_document_id
     OR iban_identite_document_id = v_document_id;
  PERFORM set_config('jolene.bank_server_update', '', true);

  IF v_type = 'RIB' THEN
    UPDATE public.partages_rib
    SET actif = false,
        expire_le = LEAST(COALESCE(expire_le, now()), now())
    WHERE document_rib_id = v_document_id AND actif IS TRUE;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_invalider_provenance_iban_depuis_document"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_invalider_provenance_iban_sur_identite"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.nom IS DISTINCT FROM OLD.nom
     OR NEW.prenom IS DISTINCT FROM OLD.prenom
     OR NEW.identite_verifiee IS DISTINCT FROM OLD.identite_verifiee
     OR NEW.coherence_identite IS DISTINCT FROM OLD.coherence_identite THEN
    PERFORM set_config('jolene.bank_server_update', 'true', true);
    UPDATE public.soignants
    SET iban_source_document_id = NULL,
        iban_identite_document_id = NULL,
        iban_source_s3_cle = NULL,
        iban_empreinte_sha256 = NULL,
        iban_verifie_le = NULL,
        iban_titulaire_coherent = false,
        modifie_le = now()
    WHERE id = NEW.id;
    PERFORM set_config('jolene.bank_server_update', '', true);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_invalider_provenance_iban_sur_identite"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_invalider_provenance_rib_etablissement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.rib_s3_key IS DISTINCT FROM OLD.rib_s3_key
     OR NEW.nom IS DISTINCT FROM OLD.nom
     OR NEW.siret IS DISTINCT FROM OLD.siret
     OR NEW.siret_raison_sociale IS DISTINCT FROM OLD.siret_raison_sociale
     OR NEW.finess IS DISTINCT FROM OLD.finess
     OR NEW.finess_raison_sociale IS DISTINCT FROM OLD.finess_raison_sociale THEN
    -- BEFORE : la ligne NEW est rendue cohérente avant l'évaluation des
    -- contraintes. Un remplacement de fichier reste donc possible et révoque
    -- atomiquement l'ancien verdict, quelle que soit l'ordre des triggers.
    NEW.rib_ia_resultat := NULL;
    NEW.rib_ia_coherent := NULL;
    NEW.rib_ia_verifie_le := NULL;
    NEW.iban_last4 := NULL;
    NEW.rib_verifie_s3_key := NULL;
    NEW.rib_verifie_source_version := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_invalider_provenance_rib_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_invalider_verifications_etablissement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_identite_changee boolean := false;
  v_justificatif_change boolean := false;
  v_rib_change boolean := false;
  v_contrat_change boolean := false;
  v_finess_change boolean := false;
  v_siret_change boolean := false;
  v_source_changee boolean := false;
BEGIN
  v_identite_changee :=
    NEW.representant_piece_s3_key IS DISTINCT FROM OLD.representant_piece_s3_key
    OR NEW.representant_piece_type_document IS DISTINCT FROM OLD.representant_piece_type_document
    OR NEW.representant_piece_type_mime IS DISTINCT FROM OLD.representant_piece_type_mime
    OR NEW.representant_nom IS DISTINCT FROM OLD.representant_nom
    OR NEW.representant_prenom IS DISTINCT FROM OLD.representant_prenom;
  v_justificatif_change :=
    NEW.justificatif_fonction_s3_key IS DISTINCT FROM OLD.justificatif_fonction_s3_key
    OR NEW.justificatif_fonction_type IS DISTINCT FROM OLD.justificatif_fonction_type
    OR NEW.justificatif_fonction_type_mime IS DISTINCT FROM OLD.justificatif_fonction_type_mime;
  v_rib_change := NEW.rib_s3_key IS DISTINCT FROM OLD.rib_s3_key;
  v_contrat_change := NEW.contrat_url IS DISTINCT FROM OLD.contrat_url;
  v_finess_change :=
    NEW.finess IS DISTINCT FROM OLD.finess
    OR NEW.nom IS DISTINCT FROM OLD.nom
    OR NEW.adresse_rue IS DISTINCT FROM OLD.adresse_rue
    OR NEW.adresse_ville IS DISTINCT FROM OLD.adresse_ville
    OR NEW.adresse_code_postal IS DISTINCT FROM OLD.adresse_code_postal;
  v_siret_change := NEW.siret IS DISTINCT FROM OLD.siret;
  v_source_changee := v_identite_changee OR v_justificatif_change
    OR v_rib_change OR v_contrat_change OR v_finess_change OR v_siret_change;

  IF v_identite_changee THEN
    NEW.representant_identite_verifiee := false;
    NEW.representant_identite_verifiee_le := NULL;
    NEW.representant_identite_resultat_ia := NULL;
  END IF;

  IF v_justificatif_change THEN
    NEW.justificatif_fonction_verifie := false;
    NEW.justificatif_fonction_verifie_le := NULL;
    NEW.justificatif_fonction_resultat_ia := NULL;
  END IF;

  IF v_rib_change THEN
    NEW.rib_ia_resultat := NULL;
    NEW.rib_ia_coherent := NULL;
    NEW.rib_ia_verifie_le := NULL;
    NEW.iban_last4 := NULL;
  END IF;

  IF v_contrat_change THEN
    NEW.contrat_valide := false;
    NEW.contrat_ia_resultat := NULL;
    NEW.contrat_ia_coherent := NULL;
    NEW.contrat_ia_verifie_le := NULL;
    NEW.contrat_uploade_le := CASE
      WHEN NEW.contrat_url IS NULL THEN NULL
      ELSE transaction_timestamp()
    END;
  END IF;

  IF v_finess_change THEN
    NEW.finess_verifie := false;
    NEW.finess_verifie_le := NULL;
    NEW.finess_raison_sociale := NULL;
    NEW.finess_categorie := NULL;
    NEW.finess_secteur := NULL;
    NEW.finess_est_public := NULL;
  END IF;

  IF v_siret_change THEN
    NEW.siret_verifie := false;
    NEW.siret_verifie_le := NULL;
    NEW.siret_raison_sociale := NULL;
    NEW.siret_categorie_juridique := NULL;
    NEW.siret_code_naf := NULL;
    NEW.siret_est_actif := NULL;
    NEW.dirigeants := NULL;
  END IF;

  IF v_siret_change OR NEW.nom IS DISTINCT FROM OLD.nom THEN
    NEW.coherence_identite := NULL;
  END IF;

  -- Le rattachement d'un représentant dépend à la fois de ses preuves et des
  -- dirigeants officiels. Toute altération d'une de ces entrées le remet en
  -- revue ; fn_evaluer_rattachement_etablissement pourra ensuite le recalculer.
  IF v_identite_changee OR v_justificatif_change OR v_siret_change
     OR NEW.representant_identite_verifiee IS DISTINCT FROM OLD.representant_identite_verifiee
     OR NEW.justificatif_fonction_verifie IS DISTINCT FROM OLD.justificatif_fonction_verifie
     OR NEW.dirigeants IS DISTINCT FROM OLD.dirigeants THEN
    NEW.rattachement_verifie := false;
    NEW.rattachement_verifie_le := NULL;
    NEW.rattachement_methode := 'ADMIN';
  END IF;

  -- Le remplacement de n'importe quelle source invalide aussi le verdict
  -- global. Les valeurs sont dérivées exclusivement de OLD et des deltas de
  -- sources ; aucune valeur de statut fournie par le client n'est conservée.
  IF v_source_changee THEN
    NEW.peut_publier_missions := false;
    NEW.statut_verification := CASE
      WHEN OLD.statut_verification IN ('VERIFIE', 'REJETE') THEN 'EN_COURS'
      ELSE OLD.statut_verification
    END;
    NEW.verifie_le := NULL;
    NEW.verifie_par := NULL;
    NEW.motif_rejet := CASE
      WHEN OLD.statut_verification = 'REJETE' THEN NULL
      ELSE OLD.motif_rejet
    END;
  END IF;

  -- Ce trigger s'exécute après trg_auto_valider_etablissement et avant
  -- trg_protect_etablissement_commercial (ordre alphabétique PostgreSQL).
  -- Le protector voit ainsi uniquement la transition canonique ci-dessus.
  IF NOT (
    NEW.siret_verifie IS TRUE
    AND NEW.finess_verifie IS TRUE
    AND NEW.representant_identite_verifiee IS TRUE
    AND NEW.rattachement_verifie IS TRUE
    AND NEW.contrat_service_signe IS TRUE
  ) THEN
    NEW.peut_publier_missions := false;
    IF NEW.statut_verification = 'VERIFIE' THEN
      NEW.statut_verification := 'EN_COURS';
      NEW.verifie_le := NULL;
      NEW.verifie_par := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_invalider_verifications_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_inviter_membre_etab"("p_email" "text", "p_role" "text", "p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
  v_invitation_id uuid;
  v_token text;
  v_perms jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  IF p_role NOT IN ('ADMIN_GROUPE', 'RH', 'POINTAGE_ONLY', 'LECTURE_SEULE') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ROLE_INVALIDE');
  END IF;

  IF p_email IS NULL OR length(trim(p_email)) = 0 OR p_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'EMAIL_INVALIDE');
  END IF;

  v_etab_id := COALESCE(p_etablissement_id, public.mon_etablissement_id());

  -- Vérif autorisation : seul PROPRIETAIRE peut inviter
  SELECT public.fn_mes_permissions_etab(v_etab_id) INTO v_perms;
  IF NOT COALESCE((v_perms->'permissions'->>'gerer_equipe')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE',
                                'error', 'Seul un PROPRIETAIRE peut inviter des membres');
  END IF;

  -- Pas déjà membre actif
  IF EXISTS (
    SELECT 1 FROM public.membres_etablissement m
    JOIN auth.users u ON u.id = m.user_id
    WHERE m.etablissement_id = v_etab_id
      AND lower(u.email) = lower(trim(p_email))
      AND m.actif = true
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_MEMBRE');
  END IF;

  -- Pas déjà invité en attente
  IF EXISTS (
    SELECT 1 FROM public.invitations_etablissement
    WHERE etablissement_id = v_etab_id
      AND lower(email_invite) = lower(trim(p_email))
      AND statut = 'EN_ATTENTE'
      AND expire_le > now()
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'INVITATION_DEJA_EN_ATTENTE');
  END IF;

  INSERT INTO public.invitations_etablissement (
    etablissement_id, email_invite, role_propose, invite_par
  ) VALUES (
    v_etab_id, lower(trim(p_email)), p_role, v_uid
  )
  RETURNING id, token INTO v_invitation_id, v_token;

  -- Audit
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'MODIFICATION_PROFIL', 'invitation_etab', v_invitation_id,
    jsonb_build_object(
      'evenement', 'INVITATION_MEMBRE_CREEE',
      'email', lower(trim(p_email)),
      'role', p_role,
      'etablissement_id', v_etab_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'invitation_id', v_invitation_id,
    'token', v_token,
    'expire_le', (now() + INTERVAL '7 days')
  );
END;
$_$;


ALTER FUNCTION "public"."fn_inviter_membre_etab"("p_email" "text", "p_role" "text", "p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_is_valid_uuid"("p_text" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    PERFORM p_text::UUID;
    RETURN TRUE;
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$$;


ALTER FUNCTION "public"."fn_is_valid_uuid"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_lier_iban_verifie_document"("p_document_id" "uuid", "p_expected_s3_cle" "text", "p_iban" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE
  v_doc public.documents_soignants%ROWTYPE;
  v_soignant public.soignants%ROWTYPE;
  v_identite public.documents_soignants%ROWTYPE;
  v_iban text;
  v_hash text;
  v_titulaire text;
  v_action text;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin', 'service_role') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  v_iban := upper(regexp_replace(COALESCE(p_iban, ''), '[^A-Za-z0-9]', '', 'g'));
  IF NOT public.fn_iban_est_valide(v_iban) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'IBAN_INVALIDE');
  END IF;

  SELECT * INTO v_doc
  FROM public.documents_soignants
  WHERE id = p_document_id
    AND type_document = 'RIB'
    AND s3_cle = p_expected_s3_cle
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL AND revoque_le IS NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'RIB_COURANT_REQUIS');
  END IF;

  SELECT * INTO v_soignant
  FROM public.soignants
  WHERE id = v_doc.soignant_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND
     OR v_soignant.identite_verifiee IS NOT TRUE
     OR v_soignant.coherence_identite IS DISTINCT FROM 'COHERENT' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'IDENTITE_VERIFIEE_REQUISE');
  END IF;

  SELECT * INTO v_identite
  FROM public.documents_soignants
  WHERE soignant_id = v_soignant.id
    AND type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL AND revoque_le IS NULL
  ORDER BY verifie_le DESC NULLS LAST, televerse_le DESC NULLS LAST, id DESC
  LIMIT 1
  FOR SHARE;
  IF NOT FOUND
     OR v_identite.coherence_nom IS NOT TRUE
     OR NOT public.fn_noms_personne_correspondent(
       v_soignant.nom, v_soignant.prenom,
       v_identite.nom_extrait_ia, v_identite.prenom_extrait_ia
     ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'IDENTITE_COURANTE_REQUISE');
  END IF;

  v_hash := encode(
    extensions.digest(convert_to(v_iban || ':' || v_doc.id::text, 'UTF8'), 'sha256'),
    'hex'
  );
  IF COALESCE(v_doc.resultat_ia->>'verdict_serveur', '') <> 'VERIFIE'
     OR COALESCE(v_doc.resultat_ia->>'iban_valide', '') <> 'true'
     OR COALESCE(v_doc.resultat_ia->>'iban_last4', '') <> right(v_iban, 4)
     OR COALESCE(v_doc.resultat_ia->>'iban_preuve_hash_v1', '') <> v_hash
     OR v_doc.coherence_nom IS NOT TRUE
     OR NOT public.fn_noms_personne_correspondent(
       v_soignant.nom, v_soignant.prenom,
       v_doc.nom_extrait_ia, v_doc.prenom_extrait_ia
     ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'RIB_NON_CONCORDANT');
  END IF;

  v_titulaire := btrim(v_soignant.prenom || ' ' || v_soignant.nom);
  v_action := CASE WHEN NULLIF(v_soignant.iban_virement, '') IS NULL
    THEN 'IBAN_RENSEIGNE' ELSE 'IBAN_MODIFIE' END;
  PERFORM set_config('jolene.bank_server_update', 'true', true);
  UPDATE public.soignants
  SET iban_virement = v_iban,
      iban_titulaire = v_titulaire,
      iban_last4 = right(v_iban, 4),
      iban_source_document_id = v_doc.id,
      iban_identite_document_id = v_identite.id,
      iban_source_s3_cle = v_doc.s3_cle,
      iban_empreinte_sha256 = v_hash,
      iban_verifie_le = now(),
      iban_titulaire_coherent = true,
      modifie_le = now()
  WHERE id = v_soignant.id;
  PERFORM set_config('jolene.bank_server_update', '', true);

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_soignant.id,
    p_type_acteur := 'SYSTEME',
    p_action := v_action,
    p_type_ressource := 'soignant',
    p_id_ressource := v_soignant.id,
    p_details := jsonb_build_object(
      'iban_last4', right(v_iban, 4),
      'source_document_id', v_doc.id,
      'identite_document_id', v_identite.id,
      'liaison_directe', true
    )
  );
  RETURN jsonb_build_object(
    'success', true,
    'iban_last4', right(v_iban, 4),
    'titulaire', v_titulaire,
    'source_document_id', v_doc.id
  );
END;
$$;


