CREATE OR REPLACE FUNCTION "public"."fn_lister_api_keys"("p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_admin boolean := public.est_admin();
  v_etab_id uuid;
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifie');
  END IF;

  IF v_is_admin THEN
    v_etab_id := p_etablissement_id;
  ELSE
    v_etab_id := public.mon_etablissement_id();
    IF v_etab_id IS NULL OR NOT public.fn_a_permission_etablissement('api', v_etab_id)
       OR (p_etablissement_id IS NOT NULL AND p_etablissement_id <> v_etab_id) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Acces refuse');
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', k.id,
    'nom', k.nom,
    'cle_api', k.cle_api,
    'permissions', k.permissions,
    'etablissement_id', k.etablissement_id,
    'groupe_sante_id', k.groupe_sante_id,
    'actif', k.actif,
    'derniere_utilisation', k.derniere_utilisation,
    'cree_le', k.cree_le,
    'expire_le', k.expire_le,
    'secret_configure', k.cle_secret_hash IS NOT NULL
  ) ORDER BY k.cree_le DESC), '[]'::jsonb)
  INTO v_result
  FROM public.api_keys k
  WHERE v_etab_id IS NULL OR k.etablissement_id = v_etab_id;

  RETURN jsonb_build_object('success', true, 'keys', v_result);
END;
$$;


ALTER FUNCTION "public"."fn_lister_api_keys"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_lister_conversations_messagerie"("p_avant" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_avant_id" "uuid" DEFAULT NULL::"uuid", "p_limite" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "participant_1_id" "uuid", "participant_2_id" "uuid", "mission_id" "uuid", "etablissement_id" "uuid", "soignant_id" "uuid", "dernier_message_le" timestamp with time zone, "cree_le" timestamp with time zone, "archived_at" timestamp with time zone, "autre_id" "uuid", "dernier_contenu" "text", "non_lus" bigint, "mission_intitule" "text", "ordre_le" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_limite integer := LEAST(
    GREATEST(COALESCE(p_limite, 100), 1),
    100
  );
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;
  IF (p_avant IS NULL) <> (p_avant_id IS NULL) THEN
    RAISE EXCEPTION 'Curseur incomplet' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH page AS (
    SELECT
      c.*,
      COALESCE(c.dernier_message_le, c.cree_le) AS ordre
    FROM public.conversations c
    WHERE public.fn_conversation_accessible(c.id)
      AND (
        p_avant IS NULL
        OR (
          COALESCE(c.dernier_message_le, c.cree_le),
          c.id
        ) < (p_avant, p_avant_id)
      )
    ORDER BY
      COALESCE(c.dernier_message_le, c.cree_le) DESC,
      c.id DESC
    LIMIT v_limite
  )
  SELECT
    p.id,
    p.participant_1_id,
    p.participant_2_id,
    p.mission_id,
    p.etablissement_id,
    p.soignant_id,
    p.dernier_message_le,
    p.cree_le,
    p.archived_at,
    CASE
      WHEN public.est_admin() THEN p.participant_2_id
      WHEN p.soignant_id = v_uid THEN
        private.fn_interlocuteur_operationnel_id(p.etablissement_id)
      WHEN p.soignant_id IS NOT NULL
       AND private.fn_membre_equipe_conversation(v_uid, p.id)
        THEN p.soignant_id
      WHEN v_uid = p.participant_1_id THEN p.participant_2_id
      WHEN v_uid = p.participant_2_id THEN p.participant_1_id
      ELSE p.participant_1_id
    END AS autre_id,
    dernier.contenu,
    CASE
      WHEN p.soignant_id = v_uid THEN (
        SELECT pg_catalog.count(*)
        FROM public.messages_chat mc
        WHERE mc.conversation_id = p.id
          AND mc.lu IS FALSE
          AND mc.auteur_id <> p.soignant_id
      )
      WHEN p.soignant_id IS NOT NULL
       AND private.fn_membre_equipe_conversation(v_uid, p.id) THEN (
        SELECT pg_catalog.count(*)
        FROM public.messages_chat mc
        WHERE mc.conversation_id = p.id
          AND mc.lu IS FALSE
          AND mc.auteur_id = p.soignant_id
      )
      ELSE (
        SELECT pg_catalog.count(*)
        FROM public.messages_chat mc
        WHERE mc.conversation_id = p.id
          AND mc.lu IS FALSE
          AND mc.auteur_id <> v_uid
      )
    END AS non_lus,
    mi.intitule::text,
    p.ordre
  FROM page p
  LEFT JOIN LATERAL (
    SELECT mc.contenu
    FROM public.messages_chat mc
    WHERE mc.conversation_id = p.id
    ORDER BY mc.cree_le DESC, mc.id DESC
    LIMIT 1
  ) dernier ON true
  LEFT JOIN public.missions mi ON mi.id = p.mission_id
  ORDER BY p.ordre DESC, p.id DESC;
END;
$$;


ALTER FUNCTION "public"."fn_lister_conversations_messagerie"("p_avant" timestamp with time zone, "p_avant_id" "uuid", "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_lister_factures_a_regenerer"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "numero_facture" "text", "type_document" "public"."type_document_facture", "soignant_id" "uuid", "cree_le" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
