CREATE OR REPLACE FUNCTION "public"."fn_matching_inverse_dispos"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_soignant record;
  v_count integer;
  v_notifies integer := 0;
  v_url text := 'https://flripxtsyegjshnhzjkz.supabase.co';
  v_token text;
  v_corps text;
  v_cap_h integer := GREATEST(1, public.fn_param_num('alerte_filtre_cap_h', 20)::integer);
BEGIN
  BEGIN
    v_token := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
  EXCEPTION WHEN OTHERS THEN v_token := NULL;
  END;

  FOR v_soignant IN
    SELECT DISTINCT s.id, s.adresse_lat, s.adresse_lng, s.rayon_deplacement_km
    FROM public.soignants s
    JOIN public.disponibilites_soignant d ON d.soignant_id = s.id
    WHERE d.jour BETWEEN current_date AND current_date + 14
      AND s.supprime_le IS NULL
      AND COALESCE(s.statut_compte::text, 'ACTIF') = 'ACTIF'
      AND NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.destinataire_id = s.id AND n.type = 'MISSION_A_POURVOIR'
          AND n.cree_le > now() - make_interval(hours => v_cap_h)
      )
  LOOP
    SELECT count(*) INTO v_count
    FROM public.missions m
    JOIN public.etablissements e ON e.id = m.etablissement_id
    WHERE m.statut = 'OUVERTE'
      AND m.debut_le > now()
      AND m.intitule NOT LIKE '[%'
      AND public.fn_soignant_eligible_mission(v_soignant.id, m.id, true)
      AND NOT public.fn_est_exclu(v_soignant.id, m.etablissement_id)
      AND NOT EXISTS (
        SELECT 1 FROM public.swipes sw
        WHERE sw.mission_id = m.id AND sw.soignant_id = v_soignant.id
      )
      AND (
        v_soignant.adresse_lat IS NULL OR e.adresse_lat IS NULL
        OR public.fn_haversine_distance_m(
          v_soignant.adresse_lat, v_soignant.adresse_lng,
          e.adresse_lat, e.adresse_lng
        ) <= COALESCE(v_soignant.rayon_deplacement_km, 50) * 1000
      )
      AND EXISTS (
        SELECT 1 FROM public.disponibilites_soignant d
        WHERE d.soignant_id = v_soignant.id
          AND d.jour = (m.debut_le AT TIME ZONE 'Europe/Paris')::date
          AND (
            d.creneau = 'JOURNEE'
            OR (d.creneau = 'NUIT' AND (
              extract(hour FROM m.debut_le AT TIME ZONE 'Europe/Paris') >= 20
              OR extract(hour FROM m.debut_le AT TIME ZONE 'Europe/Paris') < 7
            ))
            OR (d.creneau IN ('MATIN', 'APRES_MIDI')
                AND extract(hour FROM m.debut_le AT TIME ZONE 'Europe/Paris') BETWEEN 7 AND 19)
          )
      );

    IF v_count > 0 THEN
      v_corps := v_count || ' mission' || CASE WHEN v_count > 1 THEN 's correspondent' ELSE ' correspond' END ||
        ' à vos disponibilités des deux prochaines semaines.';
      INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
      VALUES (
        v_soignant.id, 'MISSION_A_POURVOIR', '📅 Des missions correspondent à votre planning',
        v_corps, '/soignant/recherche-missions?vue=swipe', 'SOIGNANT'
      );
      IF v_token IS NOT NULL THEN
        BEGIN
          PERFORM net.http_post(
            url := v_url || '/functions/v1/send-push',
            headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token),
            body := jsonb_build_object(
              'destinataire_id', v_soignant.id,
              'type_evenement', 'MISSION_A_POURVOIR',
              'titre', '📅 Des missions correspondent à votre planning',
              'corps', v_corps,
              'data', jsonb_build_object('lien', '/soignant/recherche-missions?vue=swipe')
            )
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END IF;
      v_notifies := v_notifies + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'notifies', v_notifies);
END;
$$;


ALTER FUNCTION "public"."fn_matching_inverse_dispos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_avances_factor"() RETURNS TABLE("id" "uuid", "numero_facture" "text", "etablissement_nom" "text", "mission_intitule" "text", "montant_facture_ttc" numeric, "frais_factor" numeric, "frais_jolene" numeric, "montant_net_soignant" numeric, "statut" "text", "cree_le" timestamp with time zone, "financee_le" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT a.id, fh.numero_facture, e.nom, m.intitule,
           a.montant_facture_ttc, a.frais_factor, a.frais_jolene, a.montant_net_soignant,
           a.statut, a.cree_le, a.financee_le
    FROM factor_advances a
    JOIN factures_honoraires fh ON fh.id = a.facture_honoraire_id
    JOIN etablissements e ON e.id = a.etablissement_id
    LEFT JOIN missions m ON m.id = a.mission_id
    WHERE a.soignant_id = auth.uid()
    ORDER BY a.cree_le DESC;
$$;


ALTER FUNCTION "public"."fn_mes_avances_factor"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_bulletins_paie"() RETURNS TABLE("id" "uuid", "numero_bulletin" "text", "mission_id" "uuid", "etablissement_id" "uuid", "etablissement_nom" "text", "mission_intitule" "text", "periode_debut" "date", "periode_fin" "date", "salaire_brut" numeric, "total_cotisations_salariales" numeric, "net_avant_impot" numeric, "ifm" numeric, "icp" numeric, "statut" "text", "date_emission" "date", "date_paiement" "date", "pdf_s3_key" "text", "cree_le" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT bp.id, bp.numero_bulletin, bp.mission_id, bp.etablissement_id,
    e.nom AS etablissement_nom, m.intitule AS mission_intitule,
    bp.periode_debut, bp.periode_fin,
    bp.salaire_brut, bp.total_cotisations_salariales, bp.net_avant_impot,
    bp.ifm, bp.icp, bp.statut, bp.date_emission, bp.date_paiement,
    bp.pdf_s3_key, bp.cree_le
  FROM bulletins_paie bp
  LEFT JOIN missions m ON m.id = bp.mission_id
  LEFT JOIN etablissements e ON e.id = bp.etablissement_id
  WHERE bp.soignant_id = auth.uid()
  ORDER BY bp.periode_debut DESC, bp.cree_le DESC;
$$;


ALTER FUNCTION "public"."fn_mes_bulletins_paie"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_credits_etab"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etab_id UUID := mon_etablissement_id();
  v_total_dispo NUMERIC;
  v_total_applique NUMERIC;
  v_credits JSONB;
BEGIN
  IF v_etab_id IS NULL AND NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  SELECT COALESCE(SUM(montant_eur) FILTER (WHERE applique_le IS NULL), 0),
         COALESCE(SUM(montant_eur) FILTER (WHERE applique_le IS NOT NULL), 0)
  INTO v_total_dispo, v_total_applique
  FROM credits_etablissement WHERE etablissement_id = v_etab_id OR est_admin();

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'montant_eur', c.montant_eur,
    'motif', c.motif,
    'applique_le', c.applique_le,
    'facture_id', c.facture_id,
    'cree_le', c.cree_le
  ) ORDER BY c.cree_le DESC), '[]'::jsonb)
  INTO v_credits
  FROM credits_etablissement c WHERE c.etablissement_id = v_etab_id OR est_admin();

  RETURN jsonb_build_object(
    'total_disponible_eur', v_total_dispo,
    'total_applique_eur', v_total_applique,
    'credits', v_credits
  );
END;
$$;


ALTER FUNCTION "public"."fn_mes_credits_etab"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_dpae"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_dpae jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'contrat_id', cm.id,
    'mission_id', cm.mission_id,
    'mission_intitule', m.intitule,
    'etablissement_id', m.etablissement_id,
    'etablissement_nom', e.nom,
    'debut_le', m.debut_le,
    'fin_le', m.fin_le,
    'type_contrat', cm.type_contrat,
    'dpae_effectuee', cm.dpae_effectuee,
    'dpae_numero', cm.dpae_numero,
    'dpae_effectuee_le', cm.dpae_effectuee_le,
    'rappel_dpae_affiche', cm.rappel_dpae_affiche,
    'rappel_dpae_affiche_le', cm.rappel_dpae_affiche_le,
    'statut_contrat', cm.statut
  ) ORDER BY m.debut_le DESC), '[]'::jsonb)
  INTO v_dpae
  FROM public.contrats_mission cm
  JOIN public.missions m ON m.id = cm.mission_id
  JOIN public.etablissements e ON e.id = m.etablissement_id
  WHERE cm.soignant_id = v_uid
    AND cm.type_contrat IN ('CDD', 'CDD', 'SALARIE')
    AND cm.statut IN ('SIGNE_COMPLET', 'SIGNE_PARTIEL');

  RETURN jsonb_build_object('success', true, 'dpae', v_dpae);
END;
$$;


ALTER FUNCTION "public"."fn_mes_dpae"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_evaluations_recues"() RETURNS TABLE("mission_id" "uuid", "mission_intitule" "text", "note" integer, "commentaire" "text", "type_evaluateur" "text", "cree_le" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        e.mission_id,
        m.intitule,
        e.note,
        CASE WHEN e.visible THEN e.commentaire ELSE NULL END,
        e.type_evaluateur,
        e.cree_le
    FROM evaluations e
    JOIN missions m ON m.id = e.mission_id
    WHERE e.evalue_id = auth.uid()
    ORDER BY e.cree_le DESC;
    -- PAS de evaluateur_id retourné = anonyme
END;
$$;


ALTER FUNCTION "public"."fn_mes_evaluations_recues"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_evenements_score"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
  v_events jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF EXISTS (SELECT 1 FROM public.soignants WHERE id = v_uid) THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', id, 'type_evenement', type_evenement, 'points', points,
      'points_corriges', points_corriges, 'motif', motif,
      'contestable', contestable AND decision_admin IS NULL AND reclamation_id IS NULL,
      'decision_admin', decision_admin, 'cree_le', cree_le,
      'mission_id', mission_id
    ) ORDER BY cree_le DESC), '[]'::jsonb)
    INTO v_events
    FROM (
      SELECT * FROM public.evenements_score_soignant
      WHERE soignant_id = v_uid
        AND cree_le > NOW() - INTERVAL '12 months'
      ORDER BY cree_le DESC LIMIT p_limit
    ) t;
    RETURN jsonb_build_object('success', true, 'type', 'SOIGNANT', 'events', v_events);
  END IF;

  v_etab_id := mon_etablissement_id();
  IF v_etab_id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', id, 'type_evenement', type_evenement, 'points', points,
      'points_corriges', points_corriges, 'motif', motif,
      'contestable', contestable AND decision_admin IS NULL AND reclamation_id IS NULL,
      'decision_admin', decision_admin, 'cree_le', cree_le,
      'mission_id', mission_id
    ) ORDER BY cree_le DESC), '[]'::jsonb)
    INTO v_events
    FROM (
      SELECT * FROM public.evenements_score_etab
      WHERE etablissement_id = v_etab_id
        AND cree_le > NOW() - INTERVAL '12 months'
      ORDER BY cree_le DESC LIMIT p_limit
    ) t;
    RETURN jsonb_build_object('success', true, 'type', 'ETAB', 'events', v_events);
  END IF;

  RETURN jsonb_build_object('success', false, 'error', 'Profil non identifié');
END;
$$;


ALTER FUNCTION "public"."fn_mes_evenements_score"("p_limit" integer) OWNER TO "postgres";


