CREATE OR REPLACE FUNCTION "public"."fn_mes_matches"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_soignant_id uuid := auth.uid();
  v_matches jsonb;
  v_total_swipes integer;
  v_total_likes integer;
  v_total_matches integer;
  v_taux_match numeric;
BEGIN
  IF v_soignant_id IS NULL THEN
    RETURN jsonb_build_object('error', 'auth_required');
  END IF;

  SELECT count(*) INTO v_total_swipes FROM public.swipes WHERE soignant_id = v_soignant_id;
  SELECT count(*) INTO v_total_likes FROM public.swipes
   WHERE soignant_id = v_soignant_id AND direction IN ('LIKE', 'SUPER_LIKE');

  -- Un "match" = candidature issue d'un like/super-like qui a été ACCEPTÉE par l'étab.
  -- (Auparavant le filtre testait des statuts de MISSION — ASSIGNEE/EN_COURS/TERMINEE —
  --  qu'une candidature ne prend jamais : la page était donc toujours vide.)
  SELECT COALESCE(jsonb_agg(payload ORDER BY (payload->>'updated_at') DESC), '[]'::jsonb)
    INTO v_matches
    FROM (
      SELECT jsonb_build_object(
        'candidature_id', c.id,
        'mission_id', m.id,
        'mission_intitule', m.intitule,
        'mission_debut_le', m.debut_le,
        'mission_fin_le', m.fin_le,
        'mission_taux_horaire_base', m.taux_horaire_base,
        'mission_statut', m.statut,
        'etablissement_id', m.etablissement_id,
        'etablissement_nom', e.nom,
        'etablissement_ville', e.adresse_ville,
        'swipe_direction', s.direction,
        'candidature_statut', c.statut,
        'updated_at', GREATEST(COALESCE(c.acceptee_a, c.traite_le, c.cree_le), s.created_at)
      ) AS payload
        FROM public.candidatures c
        JOIN public.missions m ON m.id = c.mission_id
        JOIN public.etablissements e ON e.id = m.etablissement_id
        JOIN public.swipes s ON s.soignant_id = c.soignant_id AND s.mission_id = c.mission_id
       WHERE c.soignant_id = v_soignant_id
         AND s.direction IN ('LIKE', 'SUPER_LIKE')
         AND c.statut = 'ACCEPTEE'
    ) t;

  v_total_matches := COALESCE(jsonb_array_length(v_matches), 0);
  v_taux_match := CASE
    WHEN v_total_likes > 0 THEN round((v_total_matches::numeric / v_total_likes) * 100, 1)
    ELSE 0
  END;

  RETURN jsonb_build_object(
    'matches', v_matches,
    'stats', jsonb_build_object(
      'total_swipes', v_total_swipes,
      'total_likes', v_total_likes,
      'total_matches', v_total_matches,
      'taux_match', v_taux_match
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_mes_matches"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_notations_recues_avec_stats"("p_periode" "text" DEFAULT 'TOUT'::"text", "p_note_min" integer DEFAULT NULL::integer, "p_etablissement_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid := public.mon_etablissement_id();
  v_target_id uuid;
  v_target_sens public.sens_notation;
  v_seuil_periode timestamptz;
  v_total int;
  v_notations jsonb;
  v_stats jsonb;
  v_etabs_disponibles jsonb;
  v_evolution jsonb;
  v_limit int;
BEGIN
  v_limit := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);

  IF v_etab_id IS NOT NULL THEN
    v_target_id := v_etab_id;
    v_target_sens := 'SOIGNANT_VERS_ETAB';
  ELSIF v_uid IS NOT NULL THEN
    v_target_id := v_uid;
    v_target_sens := 'ETAB_VERS_SOIGNANT';
  ELSE
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  v_seuil_periode := CASE p_periode
    WHEN '3M' THEN now() - INTERVAL '3 months'
    WHEN '6M' THEN now() - INTERVAL '6 months'
    WHEN '12M' THEN now() - INTERVAL '12 months'
    ELSE '1900-01-01'::timestamptz
  END;

  -- Total filtré
  SELECT COUNT(*) INTO v_total
  FROM public.notations_missions n
  JOIN public.missions m ON m.id = n.mission_id
  WHERE n.note_id = v_target_id
    AND n.sens = v_target_sens
    AND n.masque = false
    AND n.publie_le IS NOT NULL
    AND n.cree_le > v_seuil_periode
    AND (p_note_min IS NULL OR ROUND(((n.critere_1 + n.critere_2 + n.critere_3 + n.critere_4) / 4.0)::numeric, 1) >= p_note_min)
    AND (p_etablissement_id IS NULL OR m.etablissement_id = p_etablissement_id);

  -- Liste paginée
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', x.id,
    'mission_id', x.mission_id,
    'mission_intitule', x.mission_intitule,
    'mission_fin_le', x.mission_fin_le,
    'etablissement_id', x.etablissement_id,
    'etablissement_nom', x.etablissement_nom,
    'critere_1', x.critere_1,
    'critere_2', x.critere_2,
    'critere_3', x.critere_3,
    'critere_4', x.critere_4,
    'note_moyenne', ROUND(((x.critere_1 + x.critere_2 + x.critere_3 + x.critere_4) / 4.0)::numeric, 1),
    'commentaire', x.commentaire,
    'signale', x.signale,
    'cree_le', x.cree_le
  ) ORDER BY x.cree_le DESC), '[]'::jsonb)
  INTO v_notations
  FROM (
    SELECT n.id, n.mission_id, m.intitule AS mission_intitule, m.fin_le AS mission_fin_le,
           m.etablissement_id, e.nom AS etablissement_nom,
           n.critere_1, n.critere_2, n.critere_3, n.critere_4, n.commentaire, n.signale, n.cree_le
    FROM public.notations_missions n
    JOIN public.missions m ON m.id = n.mission_id
    LEFT JOIN public.etablissements e ON e.id = m.etablissement_id
    WHERE n.note_id = v_target_id
      AND n.sens = v_target_sens
      AND n.masque = false
      AND n.publie_le IS NOT NULL
      AND n.cree_le > v_seuil_periode
      AND (p_note_min IS NULL OR ROUND(((n.critere_1 + n.critere_2 + n.critere_3 + n.critere_4) / 4.0)::numeric, 1) >= p_note_min)
      AND (p_etablissement_id IS NULL OR m.etablissement_id = p_etablissement_id)
    ORDER BY n.cree_le DESC
    LIMIT v_limit OFFSET p_offset
  ) x;

  -- Stats globales (toutes périodes, pas de filtres pour avoir une vue globale)
  SELECT jsonb_build_object(
    'note_moyenne_globale', COALESCE(ROUND(AVG((n.critere_1 + n.critere_2 + n.critere_3 + n.critere_4) / 4.0)::numeric, 1), 0),
    'total_evaluations', COUNT(*),
    'pct_5_etoiles', CASE WHEN COUNT(*) > 0
      THEN ROUND(100.0 * SUM(CASE WHEN (n.critere_1 + n.critere_2 + n.critere_3 + n.critere_4) >= 19 THEN 1 ELSE 0 END) / COUNT(*), 1)
      ELSE 0 END
  )
  INTO v_stats
  FROM public.notations_missions n
  WHERE n.note_id = v_target_id AND n.sens = v_target_sens AND n.masque = false AND n.publie_le IS NOT NULL;

  -- Évolution 6 derniers mois (note moyenne par mois)
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'mois', to_char(x.mois, 'YYYY-MM'),
    'note_moyenne', ROUND(x.moyenne::numeric, 1),
    'nb', x.nb
  ) ORDER BY x.mois), '[]'::jsonb)
  INTO v_evolution
  FROM (
    SELECT date_trunc('month', n.cree_le) AS mois,
           AVG((n.critere_1 + n.critere_2 + n.critere_3 + n.critere_4) / 4.0) AS moyenne,
           COUNT(*) AS nb
    FROM public.notations_missions n
    WHERE n.note_id = v_target_id
      AND n.sens = v_target_sens
      AND n.masque = false
      AND n.publie_le IS NOT NULL
      AND n.cree_le > now() - INTERVAL '6 months'
    GROUP BY 1
  ) x;

  -- Liste étabs ayant évalué le soignant (pour dropdown filtre)
  IF v_target_sens = 'ETAB_VERS_SOIGNANT' THEN
    SELECT COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', e.id, 'nom', e.nom)), '[]'::jsonb)
    INTO v_etabs_disponibles
    FROM public.notations_missions n
    JOIN public.missions m ON m.id = n.mission_id
    JOIN public.etablissements e ON e.id = m.etablissement_id
    WHERE n.note_id = v_target_id AND n.sens = v_target_sens AND n.masque = false AND n.publie_le IS NOT NULL;
  ELSE
    v_etabs_disponibles := '[]'::jsonb;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'total', v_total,
    'limit', v_limit,
    'offset', p_offset,
    'notations', v_notations,
    'stats', v_stats,
    'evolution_6m', v_evolution,
    'etabs_disponibles', v_etabs_disponibles
  );
END;
$$;


ALTER FUNCTION "public"."fn_mes_notations_recues_avec_stats"("p_periode" "text", "p_note_min" integer, "p_etablissement_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_paiements_escrow"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH base AS (
    SELECT
      pe.mission_id,
      m.intitule                       AS mission_intitule,
      e.nom                            AS etablissement_nom,
      pe.honoraires_cents,
      pe.statut,
      pe.paye_le,
      pe.release_planifie_le,
      pe.disponible_le,
      pe.relance_prevue_le,
      m.debut_le                       AS mission_date,
      COALESCE(pr.travaillee, false)                       AS travaillee,
      COALESCE(pr.bloquante, false)                        AS bloquante,
      COALESCE(pr.a_litige_presence, false)                AS a_litige_presence
    FROM paiements_escrow pe
    JOIN missions m         ON m.id = pe.mission_id
    JOIN etablissements e   ON e.id = pe.etablissement_id
    LEFT JOIN LATERAL (
      SELECT
        bool_or(p.pointage_depart_le IS NOT NULL) AS travaillee,
        bool_or(COALESCE(p.valide_par_etablissement, false) = false
                AND (p.pointage_depart_le IS NOT NULL OR p.motif_litige IS NOT NULL)) AS bloquante,
        bool_or(p.motif_litige IS NOT NULL) AS a_litige_presence
      FROM presences p
      WHERE p.mission_id = pe.mission_id
    ) pr ON true
    WHERE pe.soignant_id = auth.uid()
  ),
  calc AS (
    SELECT
      base.*,
      CASE
        WHEN statut = 'PAYE'                            THEN 'VERSE'
        WHEN statut = 'REMBOURSE' AND paye_le IS NOT NULL THEN 'VERSE'      -- absorption post-versement : le soignant a touché 100 %
        WHEN statut = 'REMBOURSE'                       THEN 'ANNULE'
        WHEN statut = 'ECHOUE'                          THEN 'RETARDE'
        WHEN statut = 'DISPUTE'                         THEN 'LITIGE'
        -- in-flight : INITIE / DEBITE / DISPONIBLE / RELEASE_PLANIFIE
        WHEN travaillee AND NOT bloquante               THEN 'VERSEMENT_EN_COURS'
        WHEN travaillee                                 THEN 'ATTENTE_VALIDATION'
        ELSE 'RESERVE'
      END AS etat
    FROM base
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'mission_id',        mission_id,
      'mission_intitule',  mission_intitule,
      'etablissement_nom', etablissement_nom,
      'honoraires_cents',  honoraires_cents,
      'etat',              etat,
      'date_affichee',     CASE etat
                             WHEN 'VERSE'              THEN paye_le
                             WHEN 'VERSEMENT_EN_COURS' THEN COALESCE(release_planifie_le, disponible_le)
                             WHEN 'RETARDE'            THEN relance_prevue_le
                             ELSE NULL
                           END,
      'mission_date',      mission_date,
      'a_litige',          a_litige_presence OR statut = 'DISPUTE'
    )
    ORDER BY
      -- en cours / attente d'abord, versés/annulés ensuite ; récents d'abord
      CASE etat
        WHEN 'RETARDE' THEN 0 WHEN 'LITIGE' THEN 1
        WHEN 'ATTENTE_VALIDATION' THEN 2 WHEN 'VERSEMENT_EN_COURS' THEN 3
        WHEN 'RESERVE' THEN 4 WHEN 'VERSE' THEN 5 ELSE 6
      END,
      mission_date DESC
  ), '[]'::jsonb)
  FROM calc;
$$;


ALTER FUNCTION "public"."fn_mes_paiements_escrow"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_permissions_etab"("p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_etab_id uuid := COALESCE(p_etablissement_id, public.mon_etablissement_id());
  v_role text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'role', NULL, 'permissions', '{}'::jsonb);
  END IF;
  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'role', NULL, 'etablissement_id', NULL, 'permissions', '{}'::jsonb);
  END IF;

  v_role := public.fn_role_etablissement_courant(v_etab_id);
  IF v_role IS NULL AND NOT public.est_admin() THEN
    RETURN jsonb_build_object('success', true, 'role', NULL, 'etablissement_id', NULL, 'permissions', '{}'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'role', COALESCE(v_role, 'ADMIN_PLATEFORME'),
    'etablissement_id', v_etab_id,
    'permissions', jsonb_build_object(
      'gerer_equipe', public.fn_a_permission_etablissement('gerer_equipe', v_etab_id),
      'supprimer_compte', public.fn_a_permission_etablissement('supprimer_compte', v_etab_id),
      'profil_etab', public.fn_a_permission_etablissement('profil_etab', v_etab_id),
      'paiement', public.fn_a_permission_etablissement('paiement', v_etab_id),
      'missions', public.fn_a_permission_etablissement('missions', v_etab_id),
      'candidatures', public.fn_a_permission_etablissement('candidatures', v_etab_id),
      'contrats', public.fn_a_permission_etablissement('contrats', v_etab_id),
      'pointage', public.fn_a_permission_etablissement('pointage', v_etab_id),
      'rh', public.fn_a_permission_etablissement('rh', v_etab_id),
      'lecture', public.fn_a_permission_etablissement('lecture', v_etab_id)
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_mes_permissions_etab"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_reclamations"("p_statut" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'evenement_type', r.evenement_type,
    'evenement_id', COALESCE(r.evenement_soignant_id, r.evenement_etab_id),
    'motif_categorie', r.motif_categorie,
    'texte_libre', r.texte_libre,
    'justificatif_storage_path', r.justificatif_storage_path,
    'statut', r.statut,
    'decision_admin', r.decision_admin,
    'motif_admin', r.motif_admin,
    'traitee_le', r.traitee_le,
    'cree_le', r.cree_le
  ) ORDER BY r.cree_le DESC), '[]'::jsonb) INTO v_result
  FROM public.reclamations_score r
  WHERE r.contesteur_id = v_uid
    AND (p_statut IS NULL OR r.statut = p_statut);

  RETURN jsonb_build_object('success', true, 'reclamations', v_result);
END;
$$;


ALTER FUNCTION "public"."fn_mes_reclamations"("p_statut" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_revenus_connect"("p_mois_debut" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_debut DATE;
    v_connect_mois NUMERIC;
    v_connect_total NUMERIC;
    v_connect_attente NUMERIC;
    v_paiements_mois NUMERIC;
    v_paiements_total NUMERIC;
    -- Escrow (paiements_escrow) : honoraires_cents en CENTIMES → euros.
    v_escrow_mois NUMERIC;
    v_escrow_total NUMERIC;
    v_escrow_attente NUMERIC;
BEGIN
    v_debut := COALESCE(p_mois_debut, DATE_TRUNC('month', CURRENT_DATE)::DATE);

    -- Stripe Connect transfers (ancien modèle, déjà en euros) — inchangé.
    SELECT COALESCE(SUM(montant_soignant), 0) INTO v_connect_mois
    FROM stripe_transfers WHERE soignant_id = auth.uid() AND statut IN ('TRANSFERE','PAYE') AND transfere_le >= v_debut;

    SELECT COALESCE(SUM(montant_soignant), 0) INTO v_connect_total
    FROM stripe_transfers WHERE soignant_id = auth.uid() AND statut IN ('TRANSFERE','PAYE');

    SELECT COALESCE(SUM(montant_soignant), 0) INTO v_connect_attente
    FROM stripe_transfers WHERE soignant_id = auth.uid() AND statut IN ('EN_ATTENTE');

    -- Paiements manuels confirmés (déjà en euros) — inchangé.
    SELECT COALESCE(SUM(montant_net), 0) INTO v_paiements_mois
    FROM paiements_soignant WHERE soignant_id = auth.uid() AND statut = 'CONFIRME' AND confirme_par_soignant_le >= v_debut;

    SELECT COALESCE(SUM(montant_net), 0) INTO v_paiements_total
    FROM paiements_soignant WHERE soignant_id = auth.uid() AND statut = 'CONFIRME';

    -- Escrow versé (PAYE) — centimes → euros. Missions disjointes de
    -- stripe_transfers (l'escrow remplace le transfer direct) → pas de double-compte.
    SELECT COALESCE(SUM(honoraires_cents), 0) / 100.0 INTO v_escrow_mois
    FROM paiements_escrow WHERE soignant_id = auth.uid() AND statut = 'PAYE' AND paye_le >= v_debut;

    SELECT COALESCE(SUM(honoraires_cents), 0) / 100.0 INTO v_escrow_total
    FROM paiements_escrow WHERE soignant_id = auth.uid() AND statut = 'PAYE';

    -- Escrow in-flight (réservé / en attente / versement en cours) = à venir.
    SELECT COALESCE(SUM(honoraires_cents), 0) / 100.0 INTO v_escrow_attente
    FROM paiements_escrow
    WHERE soignant_id = auth.uid()
      AND statut IN ('INITIE','DEBITE','DISPONIBLE','RELEASE_PLANIFIE');

    RETURN jsonb_build_object(
        'mois_en_cours', v_connect_mois + v_paiements_mois + v_escrow_mois,
        'total', v_connect_total + v_paiements_total + v_escrow_total,
        'en_attente', v_connect_attente + v_escrow_attente,
        'stripe_connect_actif', fn_soignant_stripe_connect_actif(auth.uid())
    );
END;
$$;


ALTER FUNCTION "public"."fn_mes_revenus_connect"("p_mois_debut" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mes_soignants_etablissement"() RETURNS TABLE("id" "uuid", "prenom" "text", "nom" "text", "profession" "text", "telephone" "text", "numero_rpps" "text", "score_fiabilite" numeric, "total_missions_terminees" bigint, "rpps_verifie" boolean, "tous_documents_valides" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT ON (s.id)
        s.id, s.prenom::TEXT, s.nom::TEXT, s.profession::TEXT, s.telephone::TEXT,
        s.numero_rpps::TEXT, s.score_fiabilite,
        (SELECT COUNT(*) FROM missions m2 WHERE m2.soignant_assigne_id = s.id AND m2.statut = 'TERMINEE')::BIGINT,
        s.rpps_verifie, s.tous_documents_valides
    FROM soignants s
    JOIN missions m ON m.soignant_assigne_id = s.id
    WHERE m.etablissement_id = mon_etablissement_id()
      AND m.soignant_assigne_id IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."fn_mes_soignants_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_messagerie_cleanup_periodique"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_typing_supprimes integer;
  v_away_marques integer;
  v_offline_marques integer;
BEGIN
  WITH suppressions AS (
    DELETE FROM public.typing_status
    WHERE started_at < clock_timestamp() - interval '5 seconds'
    RETURNING 1
  )
  SELECT count(*) INTO v_typing_supprimes FROM suppressions;

  WITH mises_a_jour AS (
    UPDATE public.presence_status
    SET status = 'AWAY',
        maj_le = clock_timestamp()
    WHERE status = 'ONLINE'
      AND last_seen_at < clock_timestamp() - interval '1 minute'
      AND last_seen_at >= clock_timestamp() - interval '15 minutes'
    RETURNING 1
  )
  SELECT count(*) INTO v_away_marques FROM mises_a_jour;

  WITH mises_a_jour AS (
    UPDATE public.presence_status
    SET status = 'OFFLINE',
        maj_le = clock_timestamp()
    WHERE status IN ('ONLINE', 'AWAY')
      AND last_seen_at < clock_timestamp() - interval '15 minutes'
    RETURNING 1
  )
  SELECT count(*) INTO v_offline_marques FROM mises_a_jour;

  RETURN jsonb_build_object(
    'typing_supprimes', v_typing_supprimes,
    'away_marques', v_away_marques,
    'offline_marques', v_offline_marques,
    'execute_le', clock_timestamp()
  );
END;
$$;


ALTER FUNCTION "public"."fn_messagerie_cleanup_periodique"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_messages_non_lus"() RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT count(*)::integer
  FROM public.conversations c
  JOIN public.messages_chat mc ON mc.conversation_id = c.id
  WHERE c.archived_at IS NULL
    AND mc.lu IS FALSE
    AND public.fn_conversation_accessible(c.id)
    AND (
      (
        c.soignant_id = auth.uid()
        AND mc.auteur_id <> c.soignant_id
      )
      OR (
        c.soignant_id IS NOT NULL
        AND c.soignant_id IS DISTINCT FROM auth.uid()
        AND private.fn_membre_equipe_conversation(auth.uid(), c.id)
        AND mc.auteur_id = c.soignant_id
      )
      OR (
        c.soignant_id IS NULL
        AND auth.uid() IN (c.participant_1_id, c.participant_2_id)
        AND mc.auteur_id <> auth.uid()
      )
    );
$$;


ALTER FUNCTION "public"."fn_messages_non_lus"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mettre_preuve_etablissement_en_revue_atomique"("p_etablissement_id" "uuid", "p_service" "text", "p_source_snapshot" "jsonb", "p_motif" "text", "p_cause" "text", "p_resultat" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_service text := upper(btrim(COALESCE(p_service, '')));
  v_motif text := left(btrim(COALESCE(p_motif, '')), 1000);
  v_cause text := left(upper(btrim(COALESCE(p_cause, 'INCONNU'))), 100);
  v_applique boolean := false;
  v_revue jsonb;
  v_rattachement jsonb;
  v_version bigint;
  v_source_key text;
  v_resultat jsonb;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  IF p_etablissement_id IS NULL
     OR v_service NOT IN ('VERIFY_PIECE_IDENTITE_ETAB', 'VERIFY_JUSTIFICATIF_FONCTION')
     OR jsonb_typeof(COALESCE(p_source_snapshot, '{}'::jsonb)) <> 'object'
     OR NULLIF(p_source_snapshot->>'verification_source_version', '') IS NULL
     OR length(v_motif) < 10 THEN
    RAISE EXCEPTION 'Mise en revue atomique invalide' USING ERRCODE = '22023';
  END IF;

  v_resultat := COALESCE(p_resultat, '{}'::jsonb) || jsonb_build_object(
    'verdict_final', 'EN_ATTENTE',
    'motif', v_motif,
    'revue_manuelle_requise', true,
    'cause_revue', v_cause,
    'regle_version', '2026-07-14'
  );

  IF v_service = 'VERIFY_PIECE_IDENTITE_ETAB' THEN
    v_source_key := p_source_snapshot->>'representant_piece_s3_key';
    v_applique := public.fn_appliquer_verification_identite_etablissement(
      p_etablissement_id,
      (p_source_snapshot->>'verification_source_version')::bigint,
      v_source_key,
      p_source_snapshot->>'representant_piece_type_mime',
      p_source_snapshot->>'representant_piece_type_document',
      p_source_snapshot->>'representant_nom',
      p_source_snapshot->>'representant_prenom',
      false,
      v_resultat
    );
  ELSE
    v_source_key := p_source_snapshot->>'justificatif_fonction_s3_key';
    v_applique := public.fn_appliquer_verification_fonction_etablissement(
      p_etablissement_id,
      (p_source_snapshot->>'verification_source_version')::bigint,
      v_source_key,
      p_source_snapshot->>'justificatif_fonction_type',
      p_source_snapshot->>'justificatif_fonction_type_mime',
      p_source_snapshot->>'representant_nom',
      p_source_snapshot->>'representant_prenom',
      p_source_snapshot->>'nom',
      p_source_snapshot->>'siret',
      p_source_snapshot->>'siret_raison_sociale',
      p_source_snapshot->>'finess_raison_sociale',
      false,
      v_resultat
    );
  END IF;

  IF v_applique IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'source_changed', true);
  END IF;

  v_rattachement := public.fn_evaluer_rattachement_etablissement(p_etablissement_id);
  UPDATE public.etablissements e
  SET peut_publier_missions = CASE
        WHEN e.siret_verifie IS TRUE
         AND e.siret_est_actif IS NOT FALSE
         AND e.finess_verifie IS TRUE
         AND e.representant_identite_verifiee IS TRUE
         AND e.rattachement_verifie IS TRUE
         AND e.contrat_service_signe IS TRUE
        THEN e.peut_publier_missions
        ELSE false
      END,
      modifie_le = now()
  WHERE e.id = p_etablissement_id;

  v_revue := public.fn_ouvrir_revue_verification_etablissement(
    p_etablissement_id,
    v_service,
    v_motif,
    jsonb_build_object(
      'cause', v_cause,
      'source_version', (p_source_snapshot->>'verification_source_version')::bigint,
      'source_s3_key', v_source_key
    ),
    4
  );
  IF COALESCE((v_revue->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Ouverture de revue non confirmee' USING ERRCODE = 'P0001';
  END IF;
  SELECT verification_source_version INTO v_version
  FROM public.etablissements WHERE id = p_etablissement_id;
  RETURN jsonb_build_object(
    'success', true,
    'revue_id', v_revue->>'revue_id',
    'verification_source_version', v_version,
    'rattachement', v_rattachement
  );
END;
$$;


ALTER FUNCTION "public"."fn_mettre_preuve_etablissement_en_revue_atomique"("p_etablissement_id" "uuid", "p_service" "text", "p_source_snapshot" "jsonb", "p_motif" "text", "p_cause" "text", "p_resultat" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mirror_teleportation_alerte_systeme"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_presence_id uuid;
BEGIN
  IF NEW.action <> 'SYSTEM'
     OR COALESCE(NEW.details ->> 'evenement', '') <> 'TELEPORTATION_DETECTED' THEN
    RETURN NEW;
  END IF;

  v_presence_id := COALESCE(
    CASE WHEN COALESCE(NEW.details ->> 'presence_id_destination', '')
                   ~ '^[0-9a-fA-F-]{36}$'
         THEN (NEW.details ->> 'presence_id_destination')::uuid END,
    CASE WHEN NEW.type_ressource = 'presence' THEN NEW.id_ressource END
  );
  IF v_presence_id IS NULL THEN RETURN NEW; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('teleportation:' || v_presence_id::text, 0));
  IF NOT EXISTS (
    SELECT 1 FROM public.alertes_systeme a
    WHERE a.type_alerte = 'TELEPORTATION_DETECTED'
      AND COALESCE(
        a.details ->> 'presence_id_destination',
        a.details ->> 'presence_id'
      ) = v_presence_id::text
  ) THEN
    INSERT INTO public.alertes_systeme(
      type_alerte, severite, source, message, details
    ) VALUES (
      'TELEPORTATION_DETECTED',
      'CRITICAL',
      'fn_detecter_teleportations',
      format('Teleportation GPS detectee pour la presence %s.', v_presence_id),
      COALESCE(NEW.details, '{}'::jsonb) || jsonb_build_object(
        'presence_id_destination', v_presence_id,
        'journal_audit_id', NEW.id
      )
    );
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_mirror_teleportation_alerte_systeme"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mission_est_de_nuit"("p_debut" timestamp with time zone, "p_fin" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE v_heures_nuit numeric := 0; v_curseur timestamptz; v_curseur_fin timestamptz; v_h_debut int;
BEGIN
  v_curseur := p_debut;
  WHILE v_curseur < p_fin LOOP
    v_curseur_fin := LEAST(v_curseur + INTERVAL '30 minutes', p_fin);
    v_h_debut := EXTRACT(HOUR FROM v_curseur)::int;
    IF v_h_debut >= 21 OR v_h_debut < 6 THEN
      v_heures_nuit := v_heures_nuit + EXTRACT(EPOCH FROM (v_curseur_fin - v_curseur)) / 3600.0;
    END IF;
    v_curseur := v_curseur_fin;
  END LOOP;
  RETURN v_heures_nuit >= 3.0;
END;
$$;


ALTER FUNCTION "public"."fn_mission_est_de_nuit"("p_debut" timestamp with time zone, "p_fin" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mission_publique"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT to_jsonb(t) FROM (
    SELECT m.id, m.intitule, left(COALESCE(m.description, ''), 1500) AS description,
           m.profession_requise::text, m.debut_le, m.fin_le,
           m.taux_horaire_base, m.est_urgente, m.service,
           m.type_contrat_recherche::text,
           m.cree_le, m.modifie_le,
           e.nom AS etablissement_nom, e.type::text AS etablissement_type,
           e.adresse_ville::text AS ville,
           e.adresse_code_postal::text AS code_postal
      FROM public.missions m
      JOIN public.etablissements e ON e.id = m.etablissement_id
     WHERE m.id = p_id
       AND m.statut = 'OUVERTE'
       AND m.debut_le > now()
       AND e.supprime_le IS NULL
       AND COALESCE(e.est_compte_test, false) = false
       AND e.statut_verification = 'VERIFIE'
       AND COALESCE(e.peut_publier_missions, false) = true
       AND e.type <> 'PHARMACIE_OFFICINE'
       AND m.intitule NOT LIKE '[%'
  ) t;
$$;


ALTER FUNCTION "public"."fn_mission_publique"("p_id" "uuid") OWNER TO "postgres";


