CREATE OR REPLACE FUNCTION "public"."fn_mode_exercice"("p_profession" "text", "p_type_etab" "text", "p_finess_secteur" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
