ALTER FUNCTION "public"."fn_mode_exercice"("p_profession" "text", "p_type_etab" "text", "p_finess_secteur" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_mode_paiement_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_connect_actif boolean;
  v_rib_partage boolean;
  v_regime text;
BEGIN
  SELECT m.*, s.type_exercice AS profil_type_exercice,
         s.iban_last4 AS soignant_iban_last4
    INTO v_mission
    FROM public.missions m
    JOIN public.soignants s ON s.id = m.soignant_assigne_id
   WHERE m.id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;

  IF v_mission.etablissement_id IS DISTINCT FROM public.mon_etablissement_id()
     AND v_mission.soignant_assigne_id IS DISTINCT FROM auth.uid()
     AND NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  v_regime := COALESCE(
    v_mission.type_contrat_applique::text,
    CASE WHEN v_mission.type_paiement_soignant = 'NOTE_HONORAIRES' THEN 'LIBERAL' ELSE 'SALARIE' END
  );
  v_connect_actif := v_regime = 'LIBERAL'
    AND public.fn_soignant_stripe_connect_actif(v_mission.soignant_assigne_id);
  v_rib_partage := EXISTS (
    SELECT 1 FROM public.partages_rib
     WHERE mission_id = p_mission_id
       AND actif
       AND (expire_le IS NULL OR expire_le > now())
  );

  RETURN jsonb_build_object(
    'mode_recommande', CASE
      WHEN v_regime = 'LIBERAL' AND v_connect_actif THEN 'STRIPE_CONNECT'
      WHEN v_regime = 'LIBERAL' THEN 'VIREMENT_NOTE_HONORAIRES'
      ELSE 'VIREMENT_PAIE'
    END,
    'type_contrat_applique', v_regime,
    'type_exercice', v_mission.profil_type_exercice,
    'stripe_connect_actif', v_connect_actif,
    'rib_partage', v_rib_partage,
    'iban_last4', v_mission.soignant_iban_last4,
    'montant_soignant', v_mission.net_a_payer,
    'total_brut', v_mission.total_brut,
    'net_estime', v_mission.net_estime,
    'commission_ht', v_mission.montant_commission_ht,
    'commission_ttc', v_mission.montant_commission_ttc,
    'total', COALESCE(v_mission.net_a_payer, 0) + COALESCE(v_mission.montant_commission_ttc, 0)
  );
END;
$$;


ALTER FUNCTION "public"."fn_mode_paiement_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_modifier_filtre_sauvegarde"("p_id" "uuid", "p_nom" "text" DEFAULT NULL::"text", "p_alerte_active" boolean DEFAULT NULL::boolean, "p_frequence_alerte" "public"."filtre_frequence_alerte" DEFAULT NULL::"public"."filtre_frequence_alerte") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_old RECORD;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Non authentifié'); END IF;

  SELECT * INTO v_old FROM filtres_sauvegardes WHERE id = p_id AND utilisateur_id = v_uid;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','Filtre introuvable'); END IF;

  IF p_nom IS NOT NULL AND (length(p_nom) = 0 OR length(p_nom) > 100) THEN
    RETURN jsonb_build_object('error','Nom invalide (1-100 caractères)');
  END IF;

  UPDATE filtres_sauvegardes SET
    nom = COALESCE(p_nom, nom),
    alerte_active = COALESCE(p_alerte_active, alerte_active),
    frequence_alerte = COALESCE(p_frequence_alerte, frequence_alerte)
  WHERE id = p_id;

  PERFORM fn_ecrire_audit_safe(
    p_acteur_id := v_uid, p_type_acteur := 'SOIGNANT',
    p_action := 'FILTRE_MODIFIE', p_type_ressource := 'filtre_sauvegarde',
    p_id_ressource := p_id,
    p_details := jsonb_build_object(
      'nom_avant', v_old.nom, 'nom_apres', COALESCE(p_nom, v_old.nom),
      'alerte_active_avant', v_old.alerte_active,
      'alerte_active_apres', COALESCE(p_alerte_active, v_old.alerte_active),
      'frequence_avant', v_old.frequence_alerte::text,
      'frequence_apres', COALESCE(p_frequence_alerte, v_old.frequence_alerte)::text
    )
  );

  -- Audit toggle alerte
  IF p_alerte_active IS NOT NULL AND p_alerte_active <> v_old.alerte_active THEN
    PERFORM fn_ecrire_audit_safe(
      p_acteur_id := v_uid, p_type_acteur := 'SOIGNANT',
      p_action := CASE WHEN p_alerte_active THEN 'ALERTE_ACTIVEE' ELSE 'ALERTE_DESACTIVEE' END,
      p_type_ressource := 'filtre_sauvegarde', p_id_ressource := p_id,
      p_details := jsonb_build_object('frequence', COALESCE(p_frequence_alerte, v_old.frequence_alerte)::text)
    );
  END IF;

  RETURN jsonb_build_object('success', true);
EXCEPTION
  WHEN unique_violation THEN
    RETURN jsonb_build_object('error', 'Un filtre avec ce nom existe déjà');
END;
$$;


ALTER FUNCTION "public"."fn_modifier_filtre_sauvegarde"("p_id" "uuid", "p_nom" "text", "p_alerte_active" boolean, "p_frequence_alerte" "public"."filtre_frequence_alerte") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_modifier_horaires_presence"("p_presence_id" "uuid", "p_pointage_arrivee_le" timestamp with time zone, "p_pointage_depart_le" timestamp with time zone, "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_presence RECORD;
  v_duree_min int;
BEGIN
  SELECT * INTO v_presence FROM public.presences WHERE id = p_presence_id;
  IF v_presence IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Presence introuvable');
  END IF;

  IF p_pointage_depart_le <= p_pointage_arrivee_le THEN
    RETURN jsonb_build_object('success', false, 'error', 'Heure départ doit être après arrivée');
  END IF;

  v_duree_min := EXTRACT(EPOCH FROM (p_pointage_depart_le - p_pointage_arrivee_le)) / 60;

  UPDATE public.presences SET
    pointage_arrivee_le = p_pointage_arrivee_le,
    pointage_depart_le = p_pointage_depart_le,
    duree_brute_min = v_duree_min,
    duree_nette_min = v_duree_min - COALESCE(duree_pause_min, 0),
    modifie_le = NOW()
  WHERE id = p_presence_id;

  RETURN jsonb_build_object(
    'success', true,
    'presence_id', p_presence_id,
    'nouvelle_duree_min', v_duree_min,
    'duree_h', ROUND(v_duree_min::numeric / 60, 2)
  );
END;
$$;


ALTER FUNCTION "public"."fn_modifier_horaires_presence"("p_presence_id" "uuid", "p_pointage_arrivee_le" timestamp with time zone, "p_pointage_depart_le" timestamp with time zone, "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_modifier_mission_etablissement"("p_mission_id" "uuid", "p_intitule" "text", "p_description" "text" DEFAULT NULL::"text", "p_service" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission missions%ROWTYPE;
BEGIN
  SELECT * INTO v_mission FROM missions WHERE id = p_mission_id AND etablissement_id = mon_etablissement_id();
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable ou accès refusé.');
  END IF;

  IF v_mission.statut <> 'OUVERTE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seules les missions ouvertes peuvent être modifiées.');
  END IF;

  IF p_intitule IS NULL OR length(trim(p_intitule)) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'L''intitulé doit contenir au moins 3 caractères.');
  END IF;

  UPDATE missions SET
    intitule = trim(p_intitule),
    description = p_description,
    service = p_service,
    modifie_le = now()
  WHERE id = p_mission_id;

  PERFORM fn_ecrire_audit_safe(
    auth.uid(), 'ADMIN_ETABLISSEMENT', 'MISSION_MODIFICATION',
    'mission', p_mission_id, NULL,
    jsonb_build_object('intitule', p_intitule, 'service', p_service),
    NULL, NULL
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_modifier_mission_etablissement"("p_mission_id" "uuid", "p_intitule" "text", "p_description" "text", "p_service" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_modifier_mission_etablissement_v2"("p_mission_id" "uuid", "p_intitule" "text", "p_description" "text" DEFAULT NULL::"text", "p_service" "text" DEFAULT NULL::"text", "p_profession_requise" "public"."type_profession" DEFAULT NULL::"public"."type_profession", "p_debut_le" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_fin_le" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_taux_horaire_base" numeric DEFAULT NULL::numeric, "p_est_urgente" boolean DEFAULT false, "p_niveau_urgence" integer DEFAULT 0, "p_mode_attribution" "text" DEFAULT 'PREMIER_ARRIVE'::"text", "p_type_contrat_recherche" "text" DEFAULT 'SALARIE'::"text", "p_specialite_medicale_requise" "text" DEFAULT NULL::"text", "p_accepte_non_specialises" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_etablissement_id uuid := public.mon_etablissement_id();
BEGIN
  SELECT * INTO v_mission
    FROM public.missions
   WHERE id = p_mission_id
     AND (etablissement_id = v_etablissement_id OR public.est_admin());
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mission introuvable ou accès refusé.');
  END IF;
  IF v_mission.statut <> 'OUVERTE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Seules les missions ouvertes peuvent être modifiées.');
  END IF;
  IF p_intitule IS NULL OR length(btrim(p_intitule)) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'L''intitulé doit contenir au moins 3 caractères.');
  END IF;
  IF p_profession_requise IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'La profession requise est obligatoire.');
  END IF;
  IF p_debut_le IS NULL OR p_fin_le IS NULL OR p_fin_le <= p_debut_le THEN
    RETURN jsonb_build_object('success', false, 'error', 'La date de fin doit être postérieure à la date de début.');
  END IF;
  IF p_debut_le < now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Une mission ouverte ne peut pas être déplacée dans le passé.');
  END IF;
  IF p_taux_horaire_base IS NULL OR p_taux_horaire_base <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Le taux horaire doit être supérieur à zéro.');
  END IF;
  IF p_mode_attribution NOT IN ('PREMIER_ARRIVE', 'CANDIDATURE') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Mode d''attribution invalide.');
  END IF;
  IF p_type_contrat_recherche NOT IN ('SALARIE', 'LIBERAL', 'TOUS') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Type de contrat invalide.');
  END IF;
  IF v_mission.nb_creneaux > 1
     AND (p_debut_le IS DISTINCT FROM v_mission.debut_le OR p_fin_le IS DISTINCT FROM v_mission.fin_le) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Les dates d''une mission multi-jours se modifient depuis ses créneaux, pas depuis l''enveloppe globale.'
    );
  END IF;

  UPDATE public.missions
     SET intitule = btrim(p_intitule),
         description = p_description,
         service = NULLIF(btrim(p_service), ''),
         profession_requise = p_profession_requise,
         debut_le = p_debut_le,
         fin_le = p_fin_le,
         taux_horaire_base = p_taux_horaire_base,
         est_urgente = COALESCE(p_est_urgente, false),
         niveau_urgence = CASE WHEN COALESCE(p_est_urgente, false)
           THEN GREATEST(1, LEAST(COALESCE(p_niveau_urgence, 1), 3)) ELSE 0 END,
         mode_attribution = p_mode_attribution,
         type_contrat_recherche = p_type_contrat_recherche,
         specialite_medicale_requise = CASE
           WHEN p_profession_requise = 'MEDECIN' THEN NULLIF(btrim(p_specialite_medicale_requise), '')
           ELSE NULL
         END,
         accepte_non_specialises = CASE
           WHEN p_profession_requise IN ('IBODE', 'IADE') THEN COALESCE(p_accepte_non_specialises, true)
           ELSE true
         END,
         modifie_le = now()
   WHERE id = p_mission_id;

  -- Relire la ligne après les triggers de matrice et de calcul : le contrat
  -- retourné/audité est celui réellement appliqué, pas la préférence envoyée.
  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;

  PERFORM public.fn_ecrire_audit_safe(
    auth.uid(),
    CASE WHEN public.est_admin() THEN 'ADMIN' ELSE 'ADMIN_ETABLISSEMENT' END,
    'MISSION_MODIFICATION', 'mission', p_mission_id, NULL,
    jsonb_build_object(
      'profession_requise', v_mission.profession_requise,
      'debut_le', v_mission.debut_le,
      'fin_le', v_mission.fin_le,
      'taux_horaire_base', v_mission.taux_horaire_base,
      'type_contrat_recherche', v_mission.type_contrat_recherche,
      'mode_attribution', v_mission.mode_attribution,
      'est_urgente', v_mission.est_urgente
    ),
    NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'mission_id', p_mission_id,
    'profession_requise', v_mission.profession_requise,
    'type_contrat_recherche', v_mission.type_contrat_recherche
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'sqlstate', SQLSTATE);
END;
$$;


ALTER FUNCTION "public"."fn_modifier_mission_etablissement_v2"("p_mission_id" "uuid", "p_intitule" "text", "p_description" "text", "p_service" "text", "p_profession_requise" "public"."type_profession", "p_debut_le" timestamp with time zone, "p_fin_le" timestamp with time zone, "p_taux_horaire_base" numeric, "p_est_urgente" boolean, "p_niveau_urgence" integer, "p_mode_attribution" "text", "p_type_contrat_recherche" "text", "p_specialite_medicale_requise" "text", "p_accepte_non_specialises" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_modifier_mon_etablissement"("p_nom" "text" DEFAULT NULL::"text", "p_finess" "text" DEFAULT NULL::"text", "p_adresse_rue" "text" DEFAULT NULL::"text", "p_adresse_ville" "text" DEFAULT NULL::"text", "p_adresse_code_postal" "text" DEFAULT NULL::"text", "p_adresse_departement" "text" DEFAULT NULL::"text", "p_email_contact" "text" DEFAULT NULL::"text", "p_telephone" "text" DEFAULT NULL::"text", "p_adresse_lat" numeric DEFAULT NULL::numeric, "p_adresse_lng" numeric DEFAULT NULL::numeric, "p_taux_majoration_nuit" numeric DEFAULT NULL::numeric, "p_taux_majoration_dimanche" numeric DEFAULT NULL::numeric, "p_taux_majoration_ferie" numeric DEFAULT NULL::numeric, "p_couleur_theme" "text" DEFAULT NULL::"text", "p_convention_collective" "text" DEFAULT NULL::"text", "p_mode_paiement_commission" "text" DEFAULT NULL::"text", "p_logo_url" "text" DEFAULT NULL::"text", "p_contrat_url" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_etab_id uuid := public.mon_etablissement_id();
  v_etab record;
  v_ip inet;
  v_user_agent text;
  v_headers jsonb;
  v_champs_modifies jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR v_etab_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Établissement non trouvé');
  END IF;

  IF p_couleur_theme IS NOT NULL
     AND p_couleur_theme !~ '^#[0-9a-fA-F]{6}$' THEN
    RETURN jsonb_build_object('error', 'Couleur invalide (format #RRGGBB)');
  END IF;

  IF p_mode_paiement_commission IS NOT NULL
     AND p_mode_paiement_commission NOT IN (
       'FACTURE_MENSUELLE', 'SEPA_DEBIT', 'CHORUS_PRO'
     ) THEN
    RETURN jsonb_build_object('error', 'Mode de paiement non autorisé');
  END IF;

  SELECT e.mode_paiement_commission,
         COALESCE(e.est_secteur_public, false) AS est_secteur_public,
         e.stripe_customer_id,
         e.stripe_sepa_payment_method_id
    INTO v_etab
  FROM public.etablissements e
  WHERE e.id = v_etab_id
    AND e.supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Établissement non trouvé');
  END IF;

  -- Une valeur historique inchangée ne bloque pas la sauvegarde du profil.
  -- Les prérequis sont exigés au moment exact où un nouveau mode est choisi.
  IF p_mode_paiement_commission IS DISTINCT FROM v_etab.mode_paiement_commission THEN
    IF p_mode_paiement_commission = 'CHORUS_PRO'
       AND NOT v_etab.est_secteur_public THEN
      RETURN jsonb_build_object(
        'error',
        'Chorus Pro est réservé aux établissements publics vérifiés.'
      );
    END IF;

    IF p_mode_paiement_commission = 'SEPA_DEBIT'
       AND (
         v_etab.stripe_customer_id IS NULL
         OR v_etab.stripe_customer_id !~ '^cus_[A-Za-z0-9]+$'
         OR v_etab.stripe_sepa_payment_method_id IS NULL
         OR v_etab.stripe_sepa_payment_method_id !~ '^pm_[A-Za-z0-9]+$'
       ) THEN
      RETURN jsonb_build_object(
        'error',
        'Confirmez d’abord votre mandat SEPA avant de choisir le prélèvement automatique.'
      );
    END IF;
  END IF;

  -- La GUC ne contourne dans le protector que les anciens champs commerciaux,
  -- après ses contrôles de conformité. Elle est révoquée immédiatement après
  -- l'UPDATE et ne sort jamais de cette transaction RPC.
  PERFORM pg_catalog.set_config('app.internal_operation', 'true', true);

  UPDATE public.etablissements
  SET nom = COALESCE(p_nom, nom),
      finess = COALESCE(p_finess, finess),
      adresse_rue = COALESCE(p_adresse_rue, adresse_rue),
      adresse_ville = COALESCE(p_adresse_ville, adresse_ville),
      adresse_code_postal = COALESCE(p_adresse_code_postal, adresse_code_postal),
      adresse_departement = COALESCE(p_adresse_departement, adresse_departement),
      email_contact = COALESCE(p_email_contact, email_contact),
      telephone_contact = COALESCE(p_telephone, telephone_contact),
      adresse_lat = COALESCE(p_adresse_lat, adresse_lat),
      adresse_lng = COALESCE(p_adresse_lng, adresse_lng),
      taux_majoration_nuit_pourcent = COALESCE(
        p_taux_majoration_nuit, taux_majoration_nuit_pourcent
      ),
      taux_majoration_dimanche_pourcent = COALESCE(
        p_taux_majoration_dimanche, taux_majoration_dimanche_pourcent
      ),
      taux_majoration_ferie_pourcent = COALESCE(
        p_taux_majoration_ferie, taux_majoration_ferie_pourcent
      ),
      couleur_theme = COALESCE(p_couleur_theme, couleur_theme),
      convention_collective = COALESCE(p_convention_collective, convention_collective),
      mode_paiement_commission = COALESCE(
        p_mode_paiement_commission, mode_paiement_commission
      ),
      logo_url = COALESCE(p_logo_url, logo_url),
      contrat_url = COALESCE(p_contrat_url, contrat_url),
      contrat_uploade_le = CASE
        WHEN p_contrat_url IS NOT NULL THEN transaction_timestamp()
        ELSE contrat_uploade_le
      END,
      contrat_valide = CASE
        WHEN p_contrat_url IS NOT NULL THEN false
        ELSE contrat_valide
      END,
      modifie_le = transaction_timestamp()
  WHERE id = v_etab_id;

  PERFORM pg_catalog.set_config('app.internal_operation', 'false', true);

  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_ip := NULLIF(
      btrim(split_part(COALESCE(v_headers->>'x-forwarded-for', ''), ',', 1)),
      ''
    )::inet;
    v_user_agent := NULLIF(v_headers->>'user-agent', '');
  EXCEPTION WHEN OTHERS THEN
    v_ip := NULL;
    v_user_agent := NULL;
  END;

  IF p_nom IS NOT NULL OR p_finess IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"identite"'::jsonb;
  END IF;
  IF p_adresse_rue IS NOT NULL OR p_adresse_ville IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"adresse"'::jsonb;
  END IF;
  IF p_email_contact IS NOT NULL OR p_telephone IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"contact"'::jsonb;
  END IF;
  IF p_taux_majoration_nuit IS NOT NULL
     OR p_taux_majoration_dimanche IS NOT NULL
     OR p_taux_majoration_ferie IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"taux_majoration"'::jsonb;
  END IF;
  IF p_convention_collective IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"convention_collective"'::jsonb;
  END IF;
  IF p_mode_paiement_commission IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"mode_paiement"'::jsonb;
  END IF;
  IF p_contrat_url IS NOT NULL THEN
    v_champs_modifies := v_champs_modifies || '"contrat"'::jsonb;
  END IF;

  PERFORM public.fn_ecrire_audit(
    auth.uid(),
    'ADMIN_ETABLISSEMENT',
    'ETABLISSEMENT_MODIFICATION',
    'etablissement',
    v_etab_id,
    NULL,
    jsonb_build_object('champs_modifies', v_champs_modifies),
    v_ip,
    v_user_agent
  );

  RETURN jsonb_build_object('success', true);
END;
$_$;


ALTER FUNCTION "public"."fn_modifier_mon_etablissement"("p_nom" "text", "p_finess" "text", "p_adresse_rue" "text", "p_adresse_ville" "text", "p_adresse_code_postal" "text", "p_adresse_departement" "text", "p_email_contact" "text", "p_telephone" "text", "p_adresse_lat" numeric, "p_adresse_lng" numeric, "p_taux_majoration_nuit" numeric, "p_taux_majoration_dimanche" numeric, "p_taux_majoration_ferie" numeric, "p_couleur_theme" "text", "p_convention_collective" "text", "p_mode_paiement_commission" "text", "p_logo_url" "text", "p_contrat_url" "text") OWNER TO "postgres";


