CREATE OR REPLACE FUNCTION "public"."fn_next_bulletin_paie_number"("p_soignant_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_siret text;
  v_annee text := to_char(CURRENT_DATE, 'YYYY');
  v_seq int;
  v_lock_key bigint;
BEGIN
  -- Advisory lock par soignant pour éviter les collisions de séquence
  v_lock_key := ('x' || substring(md5(p_soignant_id::text || ':bp') from 1 for 16))::bit(64)::bigint;
  PERFORM pg_advisory_xact_lock(v_lock_key);

  SELECT COALESCE(siret_liberal, '') INTO v_siret FROM soignants WHERE id = p_soignant_id;
  IF v_siret IS NULL OR length(v_siret) < 8 THEN
    v_siret := substring(p_soignant_id::text from 1 for 8);
  ELSE
    v_siret := substring(v_siret from 1 for 8);
  END IF;

  SELECT COALESCE(MAX(
    NULLIF(regexp_replace(numero_bulletin, '^BP-[^-]+-[0-9]{4}-', ''), '')::int
  ), 0) + 1
  INTO v_seq
  FROM bulletins_paie
  WHERE soignant_id = p_soignant_id
    AND numero_bulletin LIKE 'BP-' || v_siret || '-' || v_annee || '-%';

  RETURN format('BP-%s-%s-%s', v_siret, v_annee, lpad(v_seq::text, 5, '0'));
END;
$$;


ALTER FUNCTION "public"."fn_next_bulletin_paie_number"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_no_overlap_creneaux"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM mission_creneaux
    WHERE mission_id = NEW.mission_id
      AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND type_creneau = NEW.type_creneau
      AND NEW.debut < fin AND NEW.fin > debut
  ) THEN
    RAISE EXCEPTION 'Chevauchement de créneaux dans la même mission (type=%)', NEW.type_creneau
      USING ERRCODE = 'exclusion_violation';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_no_overlap_creneaux"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_noms_personne_correspondent"("p_nom_attendu" "text", "p_prenom_attendu" "text", "p_nom_extrait" "text", "p_prenom_extrait" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH valeurs AS (
    SELECT
      regexp_split_to_array(NULLIF(btrim(regexp_replace(public.fn_normaliser_nom(p_nom_attendu), '[^a-z0-9]+', ' ', 'g')), ''), ' +') AS nom_attendu,
      regexp_split_to_array(NULLIF(btrim(regexp_replace(public.fn_normaliser_nom(p_nom_extrait), '[^a-z0-9]+', ' ', 'g')), ''), ' +') AS nom_extrait,
      regexp_split_to_array(NULLIF(btrim(regexp_replace(public.fn_normaliser_nom(p_prenom_attendu), '[^a-z0-9]+', ' ', 'g')), ''), ' +') AS prenom_attendu,
      regexp_split_to_array(NULLIF(btrim(regexp_replace(public.fn_normaliser_nom(p_prenom_extrait), '[^a-z0-9]+', ' ', 'g')), ''), ' +') AS prenom_extrait
  ), controle AS (
    SELECT *,
      CASE WHEN cardinality(nom_attendu) <= cardinality(nom_extrait)
        THEN nom_attendu <@ nom_extrait ELSE nom_extrait <@ nom_attendu END AS nom_ok,
      EXISTS (
        SELECT 1 FROM unnest(prenom_attendu) AS attendu(token)
        WHERE attendu.token = ANY(prenom_extrait)
      ) AS prenom_ok
    FROM valeurs
  )
  SELECT COALESCE(
    cardinality(nom_attendu) > 0
    AND cardinality(nom_extrait) > 0
    AND cardinality(prenom_attendu) > 0
    AND cardinality(prenom_extrait) > 0
    AND nom_ok AND prenom_ok,
    false
  )
  FROM controle;
$$;


ALTER FUNCTION "public"."fn_noms_personne_correspondent"("p_nom_attendu" "text", "p_prenom_attendu" "text", "p_nom_extrait" "text", "p_prenom_extrait" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_normaliser_nom"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT btrim(lower(translate(
    coalesce(p, ''),
    'àâäáãéèêëíìîïóòôöõúùûüçñ',
    'aaaaaeeeeiiiiooooouuuucn'
  )));
$$;


ALTER FUNCTION "public"."fn_normaliser_nom"("p" "text") OWNER TO "postgres";


