CREATE OR REPLACE FUNCTION "public"."fn_notifier_candidature_acceptee"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_titre" "text" DEFAULT NULL::"text", "p_corps" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_conversation_id uuid;
  v_notification_id uuid;
  v_lien text;
  v_titre text;
  v_corps text;
BEGIN
  SELECT mi.*
  INTO v_mission
  FROM public.missions mi
  WHERE mi.id = p_mission_id
    AND mi.soignant_assigne_id = p_soignant_id
    AND mi.statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE')
    AND EXISTS (
      SELECT 1
      FROM public.candidatures c
      WHERE c.mission_id = mi.id
        AND c.soignant_id = p_soignant_id
        AND c.statut = 'ACCEPTEE'
    )
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'error', 'Mission non attribuée à ce soignant'
    );
  END IF;

  -- Sérialise aussi deux appels Edge simultanés, sans supprimer l'historique
  -- existant et sans dépendre d'un index partiel difficile à upsert.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'CANDIDATURE_ACCEPTEE:' || p_mission_id::text || ':' ||
      p_soignant_id::text,
      0
    )
  );

  v_conversation_id := public.fn_creer_conversation_si_absente(
    p_mission_id,
    p_soignant_id,
    v_mission.etablissement_id
  );
  v_lien := CASE
    WHEN v_conversation_id IS NOT NULL
      THEN '/soignant/messagerie?conv=' || v_conversation_id::text
    ELSE '/soignant/missions/' || p_mission_id::text
  END;
  v_titre := COALESCE(
    NULLIF(pg_catalog.btrim(p_titre), ''),
    'Candidature acceptée'
  );
  v_corps := COALESCE(
    NULLIF(pg_catalog.btrim(p_corps), ''),
    'Votre candidature pour « ' || v_mission.intitule ||
      ' » a été acceptée. Signez votre contrat.'
  );

  SELECT n.id
  INTO v_notification_id
  FROM public.notifications n
  WHERE n.destinataire_id = p_soignant_id
    AND n.type_destinataire = 'SOIGNANT'
    AND n.type = 'CANDIDATURE_ACCEPTEE'
    AND n.type_ressource = 'mission'
    AND n.id_ressource = p_mission_id
  ORDER BY n.cree_le DESC, n.id
  LIMIT 1
  FOR UPDATE;

  IF v_notification_id IS NULL THEN
    INSERT INTO public.notifications (
      destinataire_id,
      type_destinataire,
      type,
      titre,
      corps,
      lien,
      type_ressource,
      id_ressource
    ) VALUES (
      p_soignant_id,
      'SOIGNANT',
      'CANDIDATURE_ACCEPTEE',
      v_titre,
      v_corps,
      v_lien,
      'mission',
      p_mission_id
    )
    RETURNING id INTO v_notification_id;
  ELSE
    UPDATE public.notifications
    SET titre = v_titre,
        corps = v_corps,
        lien = v_lien,
        type_ressource = 'mission',
        id_ressource = p_mission_id
    WHERE id = v_notification_id;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'success', true,
    'notification_id', v_notification_id,
    'conversation_id', v_conversation_id,
    'lien', v_lien
  );
END;
$$;


ALTER FUNCTION "public"."fn_notifier_candidature_acceptee"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_titre" "text", "p_corps" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_notifier_documents_expirants"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_doc RECORD;
    v_count INTEGER := 0;
BEGIN
    FOR v_doc IN
        SELECT ds.soignant_id, ds.type_document, ds.valide_jusqua,
               s.prenom, s.nom
        FROM documents_soignants ds
        JOIN soignants s ON s.id = ds.soignant_id
        WHERE ds.valide_jusqua BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '30 days'
          AND ds.statut_verification = 'VERIFIE'
          AND ds.supprime_le IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM notifications n
              WHERE n.destinataire_id = ds.soignant_id
                AND n.type = 'DOCUMENT_EXPIRANT'
                AND n.id_ressource = ds.id
                AND n.cree_le > NOW() - INTERVAL '7 days'
          )
    LOOP
        PERFORM fn_creer_notification(
            v_doc.soignant_id, 'SOIGNANT', 'DOCUMENT_EXPIRANT',
            'Document bientôt expiré',
            'Votre ' || v_doc.type_document || ' expire le ' || TO_CHAR(v_doc.valide_jusqua, 'DD/MM/YYYY') || '. Pensez à le renouveler.',
            '/soignant/documents',
            'document', v_doc.soignant_id
        );
        v_count := v_count + 1;
    END LOOP;
    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_notifier_documents_expirants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_notifier_favoris_expirants"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_nb integer := 0;
  r RECORD;
BEGIN
  FOR r IN
    SELECT ms.id AS sauvegarde_id, ms.soignant_id, m.id AS mission_id, m.intitule,
           to_char(m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24hMI') AS debut_txt
    FROM missions_sauvegardees ms
    JOIN missions m ON m.id = ms.mission_id
    WHERE ms.notifie_expiration = false
      AND m.statut = 'OUVERTE'
      AND m.debut_le > now()
      AND m.debut_le <= now() + interval '48 hours'
      AND NOT EXISTS (
        SELECT 1 FROM candidatures c
        WHERE c.mission_id = m.id AND c.soignant_id = ms.soignant_id
      )
  LOOP
    INSERT INTO notifications (destinataire_id, type_destinataire, type, titre, corps, lien)
    VALUES (
      r.soignant_id, 'SOIGNANT', 'FAVORI_MISSION_EXPIRE',
      '⭐ Ta mission sauvegardée démarre bientôt',
      '« ' || r.intitule || ' » démarre le ' || r.debut_txt || ' — postule avant qu''elle ne parte.',
      '/soignant/missions/' || r.mission_id
    );
    UPDATE missions_sauvegardees SET notifie_expiration = true WHERE id = r.sauvegarde_id;
    v_nb := v_nb + 1;
  END LOOP;
  RETURN v_nb;
END;
$$;


ALTER FUNCTION "public"."fn_notifier_favoris_expirants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obligations_financieres"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid := mon_etablissement_id();
  v_total_soignants_du numeric := 0;
  v_total_commissions_du numeric := 0;
  v_lignes jsonb := '[]'::jsonb;
BEGIN
  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Etablissement introuvable');
  END IF;

  WITH obligations AS (
    SELECT
      ('facture:' || fh.id::text) AS payment_key,
      m.id::text AS mission_id,
      fh.id::text AS facture_honoraires_id,
      m.intitule,
      m.debut_le,
      m.fin_le,
      fh.periode_debut,
      fh.periode_fin,
      fh.est_facture_finale_mission,
      fh.montant_ttc AS total_brut,
      fh.montant_ttc AS net_a_payer,
      COALESCE(fc.montant_ttc, 0) AS montant_commission_ttc,
      m.soignant_assigne_id::text AS soignant_id,
      GREATEST(0, EXTRACT(EPOCH FROM (
        LEAST(m.fin_le, (fh.periode_fin + 1)::timestamptz)
        - GREATEST(m.debut_le, fh.periode_debut::timestamptz)
      )) / 3600) AS heures,
      (CURRENT_DATE - fh.periode_fin)::integer AS jours_depuis_fin,
      COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
      s.profession::text AS soignant_profession,
      s.type_exercice AS soignant_type_exercice,
      m.type_contrat_applique::text AS type_contrat_applique,
      m.type_paiement_soignant AS type_paiement_soignant,
      COALESCE(m.mode_paiement_soignant, 'STRIPE_CONNECT') AS mode_paiement_soignant,
      (s.stripe_account_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.stripe_connect_onboarding sco
        WHERE sco.soignant_id = s.id
          AND sco.charges_enabled = true
          AND sco.payouts_enabled = true
      )) AS soignant_stripe_connect,
      EXISTS (
        SELECT 1 FROM public.paiements_soignant p
        WHERE p.mission_id = m.id AND p.statut = 'CONTESTE'
      ) AS a_paiement_conteste,
      (
        SELECT p.id::text FROM public.paiements_soignant p
        WHERE p.mission_id = m.id AND p.statut = 'CONTESTE'
        ORDER BY p.cree_le DESC LIMIT 1
      ) AS paiement_conteste_id,
      fh.periode_fin::timestamptz AS ordre_fin
    FROM public.factures_honoraires fh
    JOIN public.missions m ON m.id = fh.mission_id
    JOIN public.soignants s ON s.id = fh.soignant_id
    LEFT JOIN public.factures fc
      ON fc.facture_honoraire_id = fh.id
     AND fc.type_document = 'FACTURE'
     AND fc.statut NOT IN ('ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION')
    WHERE fh.etablissement_id = v_etab_id
      AND fh.type_document = 'FACTURE'
      AND fh.statut IN ('EMISE', 'EN_RETARD')
      AND m.type_contrat_applique = 'LIBERAL'
      AND m.statut IN ('EN_COURS', 'TERMINEE')
      AND (m.statut = 'TERMINEE' OR (NOT fh.est_facture_finale_mission AND fh.periode_fin < CURRENT_DATE))
      AND NOT EXISTS (
        SELECT 1 FROM public.paiements_soignant p
        WHERE p.facture_honoraire_id = fh.id
          AND p.statut IN ('DECLARE', 'CONFIRME', 'RESOLU')
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.stripe_transfers st
        WHERE st.facture_honoraire_id = fh.id
          AND st.statut IN ('TRANSFERE', 'CHARGE_REUSSI', 'PAYE')
      )

    UNION ALL

    SELECT
      ('mission:' || m.id::text), m.id::text, NULL::text, m.intitule,
      m.debut_le, m.fin_le, m.debut_le::date, m.fin_le::date, true,
      m.total_brut, m.net_a_payer, m.montant_commission_ttc,
      m.soignant_assigne_id::text,
      EXTRACT(EPOCH FROM (m.fin_le - m.debut_le)) / 3600,
      EXTRACT(DAY FROM now() - m.fin_le)::integer,
      COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, ''),
      s.profession::text, s.type_exercice,
      m.type_contrat_applique::text, m.type_paiement_soignant,
      m.mode_paiement_soignant, false,
      EXISTS (
        SELECT 1 FROM public.paiements_soignant p
        WHERE p.mission_id = m.id AND p.statut = 'CONTESTE'
      ),
      (
        SELECT p.id::text FROM public.paiements_soignant p
        WHERE p.mission_id = m.id AND p.statut = 'CONTESTE'
        ORDER BY p.cree_le DESC LIMIT 1
      ),
      m.fin_le
    FROM public.missions m
    JOIN public.soignants s ON s.id = m.soignant_assigne_id
    WHERE m.etablissement_id = v_etab_id
      AND m.statut = 'TERMINEE'
      AND m.type_contrat_applique = 'SALARIE'
      AND NOT EXISTS (
        SELECT 1 FROM public.paiements_soignant p
        WHERE p.mission_id = m.id AND p.statut IN ('DECLARE', 'CONFIRME', 'RESOLU')
      )
  )
  SELECT
    COALESCE(sum(o.net_a_payer), 0),
    COALESCE(jsonb_agg(to_jsonb(o) - 'ordre_fin' ORDER BY o.ordre_fin), '[]'::jsonb)
  INTO v_total_soignants_du, v_lignes
  FROM obligations o;

  SELECT COALESCE(sum(f.montant_ttc), 0)
  INTO v_total_commissions_du
  FROM public.factures f
  WHERE f.etablissement_id = v_etab_id
    AND f.statut IN ('EMISE', 'EN_RETARD');

  RETURN jsonb_build_object(
    'total_du', v_total_soignants_du + v_total_commissions_du,
    'total_soignants_du', v_total_soignants_du,
    'total_commissions_du', v_total_commissions_du,
    'nb_missions_non_payees', jsonb_array_length(v_lignes),
    'nb_paiements_en_attente', (
      SELECT count(*) FROM public.paiements_soignant
      WHERE etablissement_id = v_etab_id AND statut = 'DECLARE'
    ),
    'nb_factures_impayees', (
      SELECT count(*) FROM public.factures
      WHERE etablissement_id = v_etab_id AND statut IN ('EMISE', 'EN_RETARD')
    ),
    'nb_factures_commission_historique', (
      SELECT count(*) FROM public.factures
      WHERE etablissement_id = v_etab_id AND statut IN ('PAYEE', 'ANNULEE')
    ),
    'missions_non_payees', v_lignes,
    'paiements_soignants_en_attente', COALESCE((
      SELECT jsonb_agg(row_to_json(x)) FROM (
        SELECT p.id::text AS paiement_id, p.mission_id::text, p.montant_net,
          p.methode, p.reference_virement, p.date_paiement, p.statut,
          m.intitule AS mission_intitule,
          COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
          s.profession::text AS soignant_profession,
          COALESCE(p.facture_honoraire_id::text, (
            SELECT fh.id::text FROM public.factures_honoraires fh
            WHERE fh.mission_id = m.id ORDER BY fh.date_emission DESC LIMIT 1
          )) AS facture_honoraires_id
        FROM public.paiements_soignant p
        JOIN public.missions m ON m.id = p.mission_id
        JOIN public.soignants s ON s.id = p.soignant_id
        WHERE p.etablissement_id = v_etab_id AND p.statut = 'DECLARE'
        ORDER BY p.date_paiement DESC
      ) x
    ), '[]'::jsonb),
    'paiements_soignants_confirmes', COALESCE((
      SELECT jsonb_agg(row_to_json(x)) FROM (
        SELECT p.id::text AS paiement_id, p.mission_id::text, p.montant_net,
          p.methode, p.reference_virement, p.date_paiement,
          p.confirme_par_soignant_le, m.intitule AS mission_intitule,
          COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
          p.facture_honoraire_id::text AS facture_honoraires_id
        FROM public.paiements_soignant p
        JOIN public.missions m ON m.id = p.mission_id
        JOIN public.soignants s ON s.id = p.soignant_id
        WHERE p.etablissement_id = v_etab_id AND p.statut = 'CONFIRME'
        ORDER BY p.confirme_par_soignant_le DESC LIMIT 10
      ) x
    ), '[]'::jsonb),
    'factures_impayees', COALESCE((
      SELECT jsonb_agg(row_to_json(x)) FROM (
        SELECT f.id::text AS facture_id, f.numero_facture, f.montant_ht,
          f.montant_tva, f.montant_ttc, f.nombre_missions, f.date_echeance,
          f.statut, f.stripe_hosted_url, f.est_secteur_public,
          f.chorus_pro_statut, f.chorus_pro_numero_flux
        FROM public.factures f
        WHERE f.etablissement_id = v_etab_id
          AND f.statut IN ('EMISE', 'EN_RETARD', 'VIREMENT_DECLARE')
        ORDER BY f.date_echeance
      ) x
    ), '[]'::jsonb),
    'factures_commission_historique', COALESCE((
      SELECT jsonb_agg(row_to_json(x)) FROM (
        SELECT f.id::text AS facture_id, f.numero_facture, f.statut,
          f.montant_ttc, f.nombre_missions, f.date_emission, f.date_paiement,
          f.mode_paiement, f.virement_reference, f.stripe_payment_intent_id,
          f.mission_id::text AS mission_id, f.facture_honoraire_id::text,
          f.est_secteur_public, f.chorus_pro_statut
        FROM public.factures f
        WHERE f.etablissement_id = v_etab_id AND f.statut IN ('PAYEE', 'ANNULEE')
        ORDER BY f.date_paiement DESC NULLS LAST, f.date_emission DESC LIMIT 10
      ) x
    ), '[]'::jsonb),
    'missions_non_facturees', '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."fn_obligations_financieres"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obtenir_apercu_filtre"("p_filtre_id" "uuid", "p_since" timestamp with time zone, "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_filtre RECORD;
  v_result jsonb;
  v_profession text;
  v_taux_min numeric;
  v_urgentes_only boolean;
BEGIN
  SELECT * INTO v_filtre FROM filtres_sauvegardes WHERE id = p_filtre_id;
  IF NOT FOUND THEN RETURN '[]'::jsonb; END IF;

  IF v_filtre.audience = 'SOIGNANT_RECHERCHE_MISSIONS' THEN
    v_profession := v_filtre.filtres->>'profession';
    v_taux_min := COALESCE((v_filtre.filtres->>'tauxMin')::numeric, 0);
    v_urgentes_only := COALESCE((v_filtre.filtres->>'urgentesOnly')::boolean, false);
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', m.id, 'intitule', m.intitule, 'profession', m.profession_requise::text,
      'etablissement', e.nom, 'ville', e.adresse_ville,
      'taux_horaire', m.taux_horaire_base,
      'debut_le', m.debut_le, 'fin_le', m.fin_le,
      'urgente', COALESCE(m.est_urgente, false)
    ) ORDER BY m.cree_le DESC), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT * FROM missions m2
      WHERE m2.statut = 'OUVERTE' AND m2.cree_le > p_since
        AND (v_profession IS NULL OR v_profession = '' OR m2.profession_requise::text = v_profession)
        AND COALESCE(m2.taux_horaire_base, 0) >= v_taux_min
        AND (NOT v_urgentes_only OR COALESCE(m2.est_urgente, false) = true)
      ORDER BY m2.cree_le DESC LIMIT p_limit
    ) m
    LEFT JOIN etablissements e ON e.id = m.etablissement_id;
  ELSIF v_filtre.audience = 'ETAB_RECHERCHE_SOIGNANTS' THEN
    v_profession := v_filtre.filtres->>'profession';
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', s.id, 'prenom', s.prenom,
      'nom_initiale', LEFT(s.nom, 1) || '.',
      'profession', s.profession::text,
      'note_moyenne', s.note_moyenne
    ) ORDER BY s.cree_le DESC), '[]'::jsonb)
    INTO v_result
    FROM (
      SELECT * FROM soignants s2
      WHERE s2.cree_le > p_since
        AND COALESCE(s2.tous_documents_valides, false) = true
        AND (v_profession IS NULL OR v_profession = '' OR s2.profession::text = v_profession)
      ORDER BY s2.cree_le DESC LIMIT p_limit
    ) s;
  ELSE
    v_result := '[]'::jsonb;
  END IF;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_apercu_filtre"("p_filtre_id" "uuid", "p_since" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obtenir_conversation"("p_autre_id" "uuid", "p_mission_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_conv_id uuid;
  v_mon_id uuid := auth.uid();
  v_autorise boolean := false;
  v_est_admin boolean := false;
  v_participant_1 uuid;
  v_participant_2 uuid;
  v_etablissement_id uuid;
  v_soignant_id uuid;
  v_contact_etablissement_id uuid;
BEGIN
  IF v_mon_id IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;

  IF p_autre_id IS NULL OR p_autre_id = v_mon_id THEN
    RAISE EXCEPTION 'Interlocuteur invalide' USING ERRCODE = '22023';
  END IF;

  v_est_admin := public.est_admin();
  IF v_est_admin THEN
    IF p_mission_id IS NULL THEN
      v_autorise :=
        private.fn_soignant_messagerie_actif(p_autre_id)
        OR EXISTS (
          SELECT 1
          FROM public.etablissements e
          WHERE private.fn_interlocuteur_operationnel_actif(p_autre_id, e.id)
        );
    ELSE
      SELECT EXISTS (
        SELECT 1
        FROM public.missions mi
        WHERE mi.id = p_mission_id
          AND (
            (
              private.fn_soignant_lie_mission(p_autre_id, mi.id)
              AND private.fn_soignant_messagerie_actif(p_autre_id)
            )
            OR private.fn_interlocuteur_operationnel_actif(
              p_autre_id,
              mi.etablissement_id
            )
          )
      ) INTO v_autorise;
    END IF;
  ELSE
    v_autorise := private.fn_relation_messagerie_autorisee(
      v_mon_id,
      p_autre_id,
      p_mission_id
    );
  END IF;

  IF v_autorise IS NOT TRUE THEN
    RAISE EXCEPTION 'Conversation non autorisée' USING ERRCODE = '42501';
  END IF;

  -- Les fils de mission non administratifs appartiennent au couple métier
  -- établissement × soignant. Un second RH retrouve donc le fil canonique au
  -- lieu d'en créer un nouveau avec son propre UUID Auth.
  IF v_est_admin IS NOT TRUE AND p_mission_id IS NOT NULL THEN
    SELECT mi.etablissement_id
    INTO v_etablissement_id
    FROM public.missions mi
    WHERE mi.id = p_mission_id;

    IF private.fn_soignant_lie_mission(v_mon_id, p_mission_id)
       AND private.fn_soignant_messagerie_actif(v_mon_id)
       AND private.fn_interlocuteur_operationnel_actif(
         p_autre_id,
         v_etablissement_id
       ) THEN
      v_soignant_id := v_mon_id;
    ELSIF private.fn_soignant_lie_mission(p_autre_id, p_mission_id)
       AND private.fn_soignant_messagerie_actif(p_autre_id)
       AND private.fn_interlocuteur_operationnel_actif(
         v_mon_id,
         v_etablissement_id
       ) THEN
      v_soignant_id := p_autre_id;
    END IF;

    IF v_soignant_id IS NOT NULL THEN
      v_contact_etablissement_id :=
        private.fn_interlocuteur_operationnel_id(v_etablissement_id);
    END IF;
  END IF;

  IF v_soignant_id IS NOT NULL
     AND v_contact_etablissement_id IS NOT NULL THEN
    v_participant_1 := LEAST(
      v_soignant_id,
      v_contact_etablissement_id
    );
    v_participant_2 := GREATEST(
      v_soignant_id,
      v_contact_etablissement_id
    );
  ELSE
    v_etablissement_id := NULL;
    v_soignant_id := NULL;
    v_participant_1 := LEAST(v_mon_id, p_autre_id);
    v_participant_2 := GREATEST(v_mon_id, p_autre_id);
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      COALESCE(v_etablissement_id::text, v_participant_1::text) || ':' ||
      COALESCE(v_soignant_id::text, v_participant_2::text) || ':' ||
      COALESCE(p_mission_id::text, 'sans-mission'),
      0
    )
  );

  SELECT c.id
  INTO v_conv_id
  FROM public.conversations c
  WHERE (
      (
        v_etablissement_id IS NOT NULL
        AND c.etablissement_id = v_etablissement_id
        AND c.soignant_id = v_soignant_id
      )
      OR (
        (
          v_etablissement_id IS NULL
          OR (
            c.etablissement_id IS NULL
            AND c.soignant_id IS NULL
          )
        )
        AND c.participant_1_id = v_participant_1
        AND c.participant_2_id = v_participant_2
      )
    )
    AND (
      (p_mission_id IS NOT NULL AND c.mission_id = p_mission_id)
      OR (p_mission_id IS NULL AND c.mission_id IS NULL)
    )
  ORDER BY
    CASE
      WHEN c.etablissement_id = v_etablissement_id
       AND c.soignant_id = v_soignant_id THEN 0
      ELSE 1
    END,
    CASE WHEN c.mission_id IS NULL THEN 0 ELSE 1 END,
    c.dernier_message_le DESC NULLS LAST,
    c.cree_le DESC NULLS LAST,
    c.id
  LIMIT 1;

  IF v_conv_id IS NOT NULL
     AND v_etablissement_id IS NOT NULL
     AND v_soignant_id IS NOT NULL THEN
    UPDATE public.conversations
    SET etablissement_id = v_etablissement_id,
        soignant_id = v_soignant_id
    WHERE id = v_conv_id
      AND etablissement_id IS NULL
      AND soignant_id IS NULL;
  END IF;

  IF v_conv_id IS NULL THEN
    INSERT INTO public.conversations (
      participant_1_id,
      participant_2_id,
      mission_id,
      etablissement_id,
      soignant_id
    ) VALUES (
      v_participant_1,
      v_participant_2,
      p_mission_id,
      v_etablissement_id,
      v_soignant_id
    )
    RETURNING id INTO v_conv_id;
  END IF;

  RETURN v_conv_id;
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_conversation"("p_autre_id" "uuid", "p_mission_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_obtenir_conversation"("p_autre_id" "uuid", "p_mission_id" "uuid") IS 'Crée ou retrouve une conversation après validation de la relation mission, match accepté ou Pool Urgence ; admin AAL2 borné aux endpoints de mission.';



CREATE OR REPLACE FUNCTION "public"."fn_obtenir_conversation_pool_etablissement"("p_soignant_id" "uuid", "p_etablissement_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_contact_id uuid;
  v_conversation_id uuid;
  v_participant_1 uuid;
  v_participant_2 uuid;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;
  IF public.fn_a_permission_etablissement(
       'candidatures', p_etablissement_id
     ) IS NOT TRUE
     OR private.fn_interlocuteur_operationnel_actif(
       v_uid, p_etablissement_id
     ) IS NOT TRUE
     OR private.fn_soignant_messagerie_actif(p_soignant_id) IS NOT TRUE
     OR NOT EXISTS (
       SELECT 1
       FROM public.fn_pool_urgence_etablissement(p_etablissement_id) pool
       WHERE pool.soignant_id = p_soignant_id
     ) THEN
    RAISE EXCEPTION 'Conversation non autorisée' USING ERRCODE = '42501';
  END IF;

  v_contact_id :=
    private.fn_interlocuteur_operationnel_id(p_etablissement_id);
  IF v_contact_id IS NULL THEN
    RAISE EXCEPTION 'Interlocuteur établissement indisponible'
      USING ERRCODE = '55000';
  END IF;

  v_participant_1 := LEAST(v_contact_id, p_soignant_id);
  v_participant_2 := GREATEST(v_contact_id, p_soignant_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_etablissement_id::text || ':' || p_soignant_id::text ||
      ':pool',
      0
    )
  );

  SELECT c.id INTO v_conversation_id
  FROM public.conversations c
  WHERE c.etablissement_id = p_etablissement_id
    AND c.soignant_id = p_soignant_id
    AND c.mission_id IS NULL
  ORDER BY c.cree_le, c.id
  LIMIT 1;

  IF v_conversation_id IS NULL THEN
    INSERT INTO public.conversations (
      participant_1_id,
      participant_2_id,
      mission_id,
      etablissement_id,
      soignant_id
    ) VALUES (
      v_participant_1,
      v_participant_2,
      NULL,
      p_etablissement_id,
      p_soignant_id
    )
    RETURNING id INTO v_conversation_id;
  END IF;

  RETURN v_conversation_id;
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_conversation_pool_etablissement"("p_soignant_id" "uuid", "p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obtenir_donnees_template_serie"("p_envoi_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_envoi RECORD;
  v_data jsonb := '{}'::jsonb;
  v_count integer;
BEGIN
  SELECT * INTO v_envoi FROM serie_email_envois WHERE id = p_envoi_id;
  IF NOT FOUND THEN RETURN '{}'::jsonb; END IF;

  IF v_envoi.serie = 'SOIGNANT_ONBOARDING' THEN
    SELECT jsonb_build_object(
      'prenom', s.prenom, 'nom', s.nom, 'profession', s.profession,
      'lien_dashboard', 'https://jolene.app/soignant'
    ) INTO v_data FROM soignants s WHERE s.id = v_envoi.utilisateur_id;

    IF v_envoi.etape = 'J3' THEN
      SELECT count(*) INTO v_count FROM missions WHERE statut = 'OUVERTE';
      v_data := v_data || jsonb_build_object('nb_missions_actives', v_count);
    END IF;
    IF v_envoi.etape = 'J7' THEN
      SELECT count(*) INTO v_count FROM candidatures WHERE soignant_id = v_envoi.utilisateur_id;
      v_data := v_data || jsonb_build_object('nb_candidatures', v_count);
    END IF;
  ELSIF v_envoi.serie = 'ETAB_ONBOARDING' THEN
    SELECT jsonb_build_object(
      'nom_etablissement', e.nom, 'type_etablissement', e.type::text,
      'contrat_signe', e.contrat_service_signe,
      'lien_dashboard', 'https://jolene.app/etablissement'
    ) INTO v_data FROM etablissements e WHERE e.id = v_envoi.utilisateur_id;

    IF v_envoi.etape = 'J3' OR v_envoi.etape = 'J7' THEN
      SELECT count(*) INTO v_count FROM missions WHERE etablissement_id = v_envoi.utilisateur_id;
      v_data := v_data || jsonb_build_object('nb_missions_publiees', v_count);
    END IF;
    IF v_envoi.etape = 'J7' THEN
      SELECT count(*) INTO v_count FROM candidatures c
      JOIN missions m ON m.id = c.mission_id
      WHERE m.etablissement_id = v_envoi.utilisateur_id;
      v_data := v_data || jsonb_build_object('nb_candidatures_recues', v_count);
    END IF;
  END IF;

  RETURN v_data;
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_donnees_template_serie"("p_envoi_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obtenir_mes_parrainages"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_filleuls JSONB; v_parrain_info JSONB; v_total_gains NUMERIC; v_nb_primes_versees INT;
  v_prime integer := (public.fn_param_num('prime_parrainage_eur', 25))::integer;
  v_seuil_gmv numeric := public.fn_param_num('seuil_gmv_parrainage_eur', 500);
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Non authentifié'); END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id',p.id,'filleul_id',p.filleul_id,'prenom',s.prenom,'statut',p.statut,'cree_le',p.cree_le,
    'filleul_active_le',p.filleul_active_le,
    'commission_cumulee_filleul',COALESCE(p.commission_cumulee_filleul,0),
    'gmv_cumule_filleul',COALESCE(p.gmv_cumule_filleul,0),
    'reste_gmv_avant_prime',GREATEST(0, v_seuil_gmv - COALESCE(p.gmv_cumule_filleul,0)),
    'seuil_gmv',v_seuil_gmv,
    'seuil_atteint',(COALESCE(p.gmv_cumule_filleul,0) >= v_seuil_gmv
                     AND COALESCE(p.commission_cumulee_filleul,0) >= 4 * v_prime),
    'prime_versee_le',p.prime_versee_le,'premiere_mission_le',s.premiere_mission_le,
    'bonus_heures',COALESCE(p.bonus_heures_parrain,0)
  ) ORDER BY p.cree_le DESC), '[]'::jsonb)
  INTO v_filleuls
  FROM parrainages p JOIN soignants s ON s.id = p.filleul_id WHERE p.parrain_id = v_uid;
  SELECT COUNT(*), COALESCE(SUM(v_prime),0) INTO v_nb_primes_versees, v_total_gains
    FROM parrainages WHERE parrain_id = v_uid AND statut = 'PRIME_VERSEE';
  SELECT jsonb_build_object('parrain_prenom',sp.prenom,'statut',p.statut,'prime_versee_le',p.prime_versee_le)
    INTO v_parrain_info FROM parrainages p JOIN soignants sp ON sp.id = p.parrain_id WHERE p.filleul_id = v_uid LIMIT 1;
  RETURN jsonb_build_object('filleuls',v_filleuls,'total_gains_eur',v_total_gains,
    'nb_primes_versees',v_nb_primes_versees,'prime_eur',v_prime,'seuil_gmv_eur',v_seuil_gmv,
    'mon_parrain',COALESCE(v_parrain_info,'null'::jsonb));
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_mes_parrainages"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obtenir_mes_preferences_notifications"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_global jsonb;
  v_par_evenement jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Non authentifié'); END IF;

  SELECT to_jsonb(p) - 'utilisateur_id' INTO v_global
  FROM preferences_notifications p WHERE utilisateur_id = v_uid;

  -- Si pas de row, créer la row default
  IF v_global IS NULL THEN
    INSERT INTO preferences_notifications (utilisateur_id) VALUES (v_uid)
    ON CONFLICT (utilisateur_id) DO NOTHING;
    SELECT to_jsonb(p) - 'utilisateur_id' INTO v_global
    FROM preferences_notifications p WHERE utilisateur_id = v_uid;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'type_evenement', type_evenement,
    'canal', canal,
    'actif', actif
  )), '[]'::jsonb) INTO v_par_evenement
  FROM preferences_notifications_par_evenement WHERE utilisateur_id = v_uid;

  RETURN jsonb_build_object('global', v_global, 'par_evenement', v_par_evenement);
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_mes_preferences_notifications"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_obtenir_missions_swipe"("p_limit" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_soignant public.soignants%ROWTYPE;
  v_missions jsonb;
  v_flag_pr boolean := (public.fn_param_num('feature_paiement_rapide_actif', 0) = 1);
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('missions', '[]'::jsonb, 'error', 'auth_required'); END IF;
  SELECT * INTO v_soignant FROM public.soignants WHERE id = v_uid;

  SELECT COALESCE(jsonb_agg(payload ORDER BY tri DESC), '[]'::jsonb)
    INTO v_missions
    FROM (
      SELECT (COALESCE(ms.score_global, 0) + floor(random() * 13))::int AS tri,
        jsonb_build_object(
          'mission_id', m.id,
          'intitule', m.intitule,
          'profession_requise', m.profession_requise,
          'etablissement_id', m.etablissement_id,
          'etablissement_nom', e.nom,
          'etablissement_ville', e.adresse_ville,
          'etablissement_code_postal', e.adresse_code_postal,
          'etablissement_logo_url', e.logo_url,
          'etablissement_score', e.score_qualite,
          'taux_horaire_base', m.taux_horaire_base,
          'duree_heures', m.duree_heures,
          'debut_le', m.debut_le,
          'fin_le', m.fin_le,
          'est_urgente', m.est_urgente,
          'service', m.service,
          'type_contrat_applique', m.type_contrat_applique,
          'type_contrat_recherche', m.type_contrat_recherche,
          'nb_creneaux', m.nb_creneaux,
          'total_brut', m.total_brut,
          'net_a_payer', m.net_a_payer,
          'net_estime', m.net_estime,
          'montant_ifm', COALESCE(m.montant_ifm, 0),
          'montant_icp', COALESCE(m.montant_icp, 0),
          'montant_majoration_nuit', COALESCE(m.montant_majoration_nuit, 0),
          'montant_majoration_dimanche', COALESCE(m.montant_majoration_dimanche, 0),
          'montant_majoration_ferie', COALESCE(m.montant_majoration_ferie, 0),
          'score', COALESCE(ms.score_global, 0),
          'breakdown', COALESCE(ms.breakdown, '{}'::jsonb),
          'paiement_rapide', (
            v_flag_pr AND m.type_contrat_recherche = 'LIBERAL'
            AND e.mode_paiement_commission = 'SEPA_DEBIT'
            AND e.stripe_sepa_payment_method_id IS NOT NULL
            AND public.fn_escrow_etab_eligible(m.etablissement_id)
          ),
          'distance_km', CASE
            WHEN v_soignant.adresse_lat IS NOT NULL AND v_soignant.adresse_lng IS NOT NULL
             AND e.adresse_lat IS NOT NULL AND e.adresse_lng IS NOT NULL
            THEN round((public.fn_haversine_distance_m(
              v_soignant.adresse_lat, v_soignant.adresse_lng,
              e.adresse_lat, e.adresse_lng
            ) / 1000.0)::numeric, 1)
            ELSE NULL
          END
        ) AS payload
      FROM public.missions m
      JOIN public.etablissements e ON e.id = m.etablissement_id
      LEFT JOIN public.matching_scores ms ON ms.mission_id = m.id AND ms.soignant_id = v_uid
      WHERE m.statut = 'OUVERTE'
        AND m.debut_le > now()
        AND (COALESCE(e.est_compte_test, false) = false OR COALESCE(v_soignant.est_compte_test, false))
        AND (m.intitule NOT LIKE '[%' OR v_soignant.email LIKE 'playwright-%')
        AND public.fn_soignant_eligible_mission(v_uid, m.id, false)
        AND (v_soignant.taux_horaire_minimum IS NULL OR m.taux_horaire_base IS NULL
             OR m.taux_horaire_base >= v_soignant.taux_horaire_minimum)
        AND NOT EXISTS (
          SELECT 1 FROM public.swipes sw WHERE sw.soignant_id = v_uid AND sw.mission_id = m.id
        )
      ORDER BY COALESCE(ms.score_global, 0) DESC, m.est_urgente DESC, m.cree_le DESC
      LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 20), 100))
    ) q;

  RETURN jsonb_build_object('missions', v_missions);
END;
$$;


ALTER FUNCTION "public"."fn_obtenir_missions_swipe"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ouvrir_litige_rate_limited"("p_mission_id" "uuid", "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  RETURN public.fn_ouvrir_litige_rate_limited(
    p_mission_id, 'AUTRE'::public.type_litige, p_motif
  );
END;
$$;


ALTER FUNCTION "public"."fn_ouvrir_litige_rate_limited"("p_mission_id" "uuid", "p_motif" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ouvrir_litige_rate_limited"("p_mission_id" "uuid", "p_motif" "text") IS 'DEPRECATED + AUDITED (FIX 2). Wrapper rétrocompat 2-arg → 3-arg. Logge LITIGE_OUVERTURE_LEGACY avant délégation. À supprimer en Sub-PR 3.';



CREATE OR REPLACE FUNCTION "public"."fn_ouvrir_litige_rate_limited"("p_mission_id" "uuid", "p_type_litige" "public"."type_litige", "p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_mission record;
  v_existing integer;
  v_recent integer;
  v_initie_par text;
  v_etab_id uuid;
  v_soignant_id uuid;
  v_presence_id uuid;
  v_rate_limit integer;
  v_litige_id uuid;
  v_est_informatif boolean;
  v_fenetre_ouverte boolean;
  v_facture_id uuid;
  v_mon_etablissement_id uuid;
BEGIN
  IF v_user_id IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;
  IF length(trim(COALESCE(p_motif, ''))) < 10
     OR length(trim(COALESCE(p_motif, ''))) > 2000 THEN
    RETURN jsonb_build_object(
      'error', 'Le motif doit contenir entre 10 et 2 000 caractères.'
    );
  END IF;

  v_mon_etablissement_id := public.mon_etablissement_id();
  SELECT m.id, m.etablissement_id, m.soignant_assigne_id, m.statut
    INTO v_mission
    FROM public.missions m
   WHERE m.id = p_mission_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;

  IF v_mission.soignant_assigne_id = v_user_id THEN
    v_initie_par := 'SOIGNANT';
    v_etab_id := v_mission.etablissement_id;
    v_soignant_id := v_user_id;
  ELSIF v_mission.etablissement_id = v_mon_etablissement_id
        AND public.fn_a_permission_etablissement(
          'contrats', v_mission.etablissement_id
        ) IS TRUE THEN
    v_initie_par := 'ETABLISSEMENT';
    v_etab_id := v_mission.etablissement_id;
    v_soignant_id := v_mission.soignant_assigne_id;
  ELSE
    RETURN jsonb_build_object(
      'error', 'Vous n''êtes pas partie prenante de cette mission.'
    );
  END IF;

  SELECT count(*)
    INTO v_existing
    FROM public.litiges l
   WHERE l.mission_id = p_mission_id
     AND l.type_litige = p_type_litige
     AND l.statut IN (
       'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS',
       'REVUE_ADMIN'
     );
  IF v_existing > 0 THEN
    RETURN jsonb_build_object(
      'error', 'Un litige de ce type est déjà ouvert pour cette mission.'
    );
  END IF;

  v_rate_limit := COALESCE(
    (
      SELECT pl.valeur::integer
        FROM public.parametres_litiges pl
       WHERE pl.cle = 'rate_limit_litiges_par_heure'
    ),
    3
  );
  SELECT count(*)
    INTO v_recent
    FROM public.litiges l
   WHERE (
     l.soignant_id = v_user_id
     OR l.etablissement_id = v_mon_etablissement_id
   )
     AND l.cree_le > now() - interval '1 hour';
  IF v_recent >= v_rate_limit THEN
    RETURN jsonb_build_object(
      'error', 'Trop de litiges ouverts récemment. Réessayez plus tard.'
    );
  END IF;

  IF p_type_litige IN (
    'DESACCORD_MONTANT_FACTURE', 'NON_PAIEMENT', 'FRAIS_COMPLEMENTAIRES'
  ) THEN
    SELECT f.id
      INTO v_facture_id
      FROM public.factures_honoraires f
     WHERE f.mission_id = p_mission_id
       AND f.type_document = 'FACTURE'
       AND f.statut IN ('EMISE', 'EN_RETARD', 'PAYEE')
     ORDER BY f.date_emission DESC NULLS LAST
     LIMIT 1
     FOR UPDATE;
    IF v_facture_id IS NULL THEN
      RETURN jsonb_build_object(
        'error',
        'Aucune facture contestable (ÉMISE, EN RETARD ou PAYÉE) pour cette mission.'
      );
    END IF;
  ELSIF p_type_litige = 'DESACCORD_HEURES_POINTAGE' THEN
    -- Le désaccord peut précéder la facturation : on le laisse s'ouvrir, mais
    -- on rattache immédiatement tout document actif afin que l'accord horaires
    -- puisse suivre la résolution financière sans sélection ambiguë.
    SELECT f.id
      INTO v_facture_id
      FROM public.factures_honoraires f
     WHERE f.mission_id = p_mission_id
       AND f.type_document = 'FACTURE'
       AND f.statut IN ('BROUILLON', 'EMISE', 'EN_RETARD', 'PAYEE')
     ORDER BY f.date_emission DESC NULLS LAST
     LIMIT 1
     FOR UPDATE;
  END IF;

  v_fenetre_ouverte := public.fn_fenetre_contestation_ouverte(
    p_type_litige, p_mission_id, v_facture_id
  );
  v_est_informatif := NOT v_fenetre_ouverte;
  IF v_est_informatif
     AND p_type_litige NOT IN (
       'COMPORTEMENT_SOIGNANT',
       'COMPORTEMENT_ETABLISSEMENT',
       'CONDITIONS_MISSION_NON_RESPECTEES'
     ) THEN
    RETURN jsonb_build_object(
      'error',
      'Fenêtre de contestation fermée pour ce type de litige. Contactez le support.'
    );
  END IF;

  SELECT p.id
    INTO v_presence_id
    FROM public.presences p
   WHERE p.mission_id = p_mission_id
   ORDER BY p.cree_le DESC
   LIMIT 1;

  INSERT INTO public.litiges (
    mission_id, soignant_id, etablissement_id, presence_id, facture_id,
    initie_par, motif, statut, type_litige, est_informatif
  ) VALUES (
    p_mission_id, v_soignant_id, v_etab_id, v_presence_id, v_facture_id,
    v_initie_par, trim(p_motif), 'OUVERT', p_type_litige, v_est_informatif
  )
  RETURNING id INTO v_litige_id;

  PERFORM public.fn_ecrire_audit(
    v_user_id, v_initie_par, 'LITIGE_OUVERTURE',
    'litige', v_litige_id, NULL,
    jsonb_build_object(
      'mission_id', p_mission_id,
      'type_litige', p_type_litige,
      'initie_par', v_initie_par,
      'est_informatif', v_est_informatif,
      'facture_id', v_facture_id
    ),
    NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'litige_id', v_litige_id,
    'est_informatif', v_est_informatif,
    'facture_id', v_facture_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_ouvrir_litige_rate_limited"("p_mission_id" "uuid", "p_type_litige" "public"."type_litige", "p_motif" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_ouvrir_litige_rate_limited"("p_mission_id" "uuid", "p_type_litige" "public"."type_litige", "p_motif" "text") IS 'Ouvre un litige typé avec rate limit et vérification de fenêtre. Signature canonique (3 args).';



CREATE OR REPLACE FUNCTION "public"."fn_ouvrir_revue_siret_liberal_soignant"("p_soignant_id" "uuid", "p_code" "text", "p_donnees" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_revue_id uuid;
  v_code text := upper(btrim(COALESCE(p_code, '')));
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  IF p_soignant_id IS NULL OR v_code <> 'IDENTITE_NON_CONFIRMABLE' THEN
    RAISE EXCEPTION 'Demande de revue SIRET invalide' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.soignants s
    WHERE s.id = p_soignant_id AND s.supprime_le IS NULL
  ) THEN
    RAISE EXCEPTION 'Soignant introuvable' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_soignant_id::text || '|VERIFY_SIRET_IDENTITE_NON_CONCLUANTE', 0)
  );
  SELECT r.id INTO v_revue_id
  FROM public.file_revue_manuelle r
  WHERE r.type_entite = 'SOIGNANT'
    AND r.id_entite = p_soignant_id
    AND r.service_en_echec = 'VERIFY_SIRET_IDENTITE_NON_CONCLUANTE'
    AND r.statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE')
  ORDER BY r.cree_le DESC LIMIT 1 FOR UPDATE;

  IF v_revue_id IS NULL THEN
    INSERT INTO public.file_revue_manuelle (
      type_entite, id_entite, service_en_echec, motif_echec,
      donnees_originales, statut, priorite, expire_le
    ) VALUES (
      'SOIGNANT', p_soignant_id, 'VERIFY_SIRET_IDENTITE_NON_CONCLUANTE',
      'Le registre ne publie pas assez de traits civils pour confirmer automatiquement le titulaire du SIRET.',
      COALESCE(p_donnees, '{}'::jsonb) || jsonb_build_object(
        'code', v_code,
        'demande_le', now()
      ),
      'EN_ATTENTE', 4, now() + interval '7 days'
    ) RETURNING id INTO v_revue_id;
  ELSE
    UPDATE public.file_revue_manuelle
    SET donnees_originales = COALESCE(donnees_originales, '{}'::jsonb)
          || COALESCE(p_donnees, '{}'::jsonb)
          || jsonb_build_object('derniere_relance_le', now()),
        expire_le = greatest(COALESCE(expire_le, now()), now() + interval '7 days')
    WHERE id = v_revue_id;
  END IF;
  RETURN jsonb_build_object('success', true, 'revue_id', v_revue_id);
END;
$$;


ALTER FUNCTION "public"."fn_ouvrir_revue_siret_liberal_soignant"("p_soignant_id" "uuid", "p_code" "text", "p_donnees" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_ouvrir_revue_verification_etablissement"("p_etablissement_id" "uuid", "p_service" "text", "p_motif" "text", "p_donnees" "jsonb" DEFAULT '{}'::"jsonb", "p_priorite" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_revue_id uuid;
  v_service text := upper(btrim(COALESCE(p_service, '')));
  v_motif text := left(btrim(COALESCE(p_motif, '')), 1000);
  v_priorite integer := greatest(1, least(COALESCE(p_priorite, 3), 5));
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  IF p_etablissement_id IS NULL
     OR v_service NOT IN (
       'VERIFY_PIECE_IDENTITE_ETAB',
       'VERIFY_JUSTIFICATIF_FONCTION',
       'VERIFY_FINESS_RECOUPEMENT',
       'VERIFY_RIB_ETABLISSEMENT'
     )
     OR length(v_motif) < 10 THEN
    RAISE EXCEPTION 'Demande de revue etablissement invalide'
      USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.etablissements e
    WHERE e.id = p_etablissement_id AND e.supprime_le IS NULL
  ) THEN
    RAISE EXCEPTION 'Etablissement introuvable' USING ERRCODE = 'P0002';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(p_etablissement_id::text || '|' || v_service, 0)
  );

  SELECT r.id
    INTO v_revue_id
  FROM public.file_revue_manuelle r
  WHERE r.type_entite = 'ETABLISSEMENT'
    AND r.id_entite = p_etablissement_id
    AND r.service_en_echec = v_service
    AND r.statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE')
  ORDER BY r.cree_le DESC
  LIMIT 1
  FOR UPDATE;

  IF v_revue_id IS NULL THEN
    INSERT INTO public.file_revue_manuelle (
      type_entite, id_entite, service_en_echec, motif_echec,
      donnees_originales, statut, priorite, expire_le
    ) VALUES (
      'ETABLISSEMENT', p_etablissement_id, v_service, v_motif,
      COALESCE(p_donnees, '{}'::jsonb) || jsonb_build_object(
        'etablissement_id', p_etablissement_id,
        'demande_le', now()
      ),
      'EN_ATTENTE', v_priorite, now() + interval '7 days'
    )
    RETURNING id INTO v_revue_id;
  ELSE
    UPDATE public.file_revue_manuelle
    SET motif_echec = v_motif,
        donnees_originales = COALESCE(donnees_originales, '{}'::jsonb)
          || COALESCE(p_donnees, '{}'::jsonb)
          || jsonb_build_object('derniere_relance_le', now()),
        priorite = greatest(priorite, v_priorite),
        expire_le = greatest(COALESCE(expire_le, now()), now() + interval '7 days')
    WHERE id = v_revue_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'revue_id', v_revue_id);
END;
$$;


ALTER FUNCTION "public"."fn_ouvrir_revue_verification_etablissement"("p_etablissement_id" "uuid", "p_service" "text", "p_motif" "text", "p_donnees" "jsonb", "p_priorite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_paiements_etablissement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_result JSONB;
BEGIN
    IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Établissement introuvable'); END IF;
    
    SELECT jsonb_build_object(
        'total_paye', COALESCE((SELECT SUM(montant_net) FROM paiements_soignant WHERE etablissement_id = v_etab_id AND statut IN ('DECLARE','CONFIRME')), 0),
        'total_en_attente', COALESCE((SELECT SUM(montant_net) FROM paiements_soignant WHERE etablissement_id = v_etab_id AND statut = 'DECLARE'), 0),
        'total_confirme', COALESCE((SELECT SUM(montant_net) FROM paiements_soignant WHERE etablissement_id = v_etab_id AND statut = 'CONFIRME'), 0),
        'total_conteste', COALESCE((SELECT SUM(montant_net) FROM paiements_soignant WHERE etablissement_id = v_etab_id AND statut = 'CONTESTE'), 0),
        'nb_paiements', (SELECT COUNT(*) FROM paiements_soignant WHERE etablissement_id = v_etab_id),
        'commissions_ht', COALESCE((SELECT SUM(montant_ht) FROM factures WHERE etablissement_id = v_etab_id AND statut != 'ANNULEE'), 0),
        'commissions_ttc', COALESCE((SELECT SUM(montant_ttc) FROM factures WHERE etablissement_id = v_etab_id AND statut != 'ANNULEE'), 0),
        'missions_a_payer', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT m.id::TEXT AS mission_id, m.intitule, m.fin_le, m.total_brut,
                    m.type_paiement_soignant, m.net_a_payer, m.mode_paiement_soignant,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
                    s.type_exercice AS soignant_type_exercice,
                    -- ★ Vérifier que le Stripe Connect est COMPLÈTEMENT opérationnel
                    (s.stripe_account_id IS NOT NULL AND EXISTS(
                        SELECT 1 FROM stripe_connect_onboarding sco
                        WHERE sco.soignant_id = s.id 
                        AND sco.charges_enabled = TRUE 
                        AND sco.payouts_enabled = TRUE
                    )) AS soignant_stripe_connect,
                    EXTRACT(DAY FROM NOW() - m.fin_le)::INT AS jours_depuis_fin
                FROM missions m
                JOIN soignants s ON s.id = m.soignant_assigne_id
                WHERE m.etablissement_id = v_etab_id
                AND m.statut = 'TERMINEE'
                AND m.soignant_assigne_id IS NOT NULL
                AND NOT EXISTS (
                    SELECT 1 FROM paiements_soignant p
                    WHERE p.mission_id = m.id AND p.statut IN ('DECLARE','CONFIRME')
                )
                ORDER BY m.fin_le ASC
            ) x
        ), '[]'::JSONB),
        'paiements_recents', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT p.id::TEXT AS paiement_id, p.mission_id::TEXT, p.montant_net, p.methode, 
                    p.statut, p.date_paiement, p.reference_virement,
                    p.confirme_par_soignant, p.confirme_par_soignant_le, p.conteste, p.motif_contestation,
                    p.echeance_le,
                    m.intitule AS mission_intitule,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom
                FROM paiements_soignant p
                JOIN missions m ON m.id = p.mission_id
                JOIN soignants s ON s.id = p.soignant_id
                WHERE p.etablissement_id = v_etab_id
                ORDER BY p.cree_le DESC LIMIT 20
            ) x
        ), '[]'::JSONB)
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_paiements_etablissement"() OWNER TO "postgres";


