CREATE OR REPLACE FUNCTION "public"."fn_parrainage_etab_crediter_palier"("p_parrainage_id" "uuid", "p_montant_eur" integer, "p_palier" integer, "p_gmv_cents" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_p RECORD;
  v_filleul_nom text;
  v_parrain_nom text;
  v_credit_parrain uuid;
  v_credit_filleul uuid;
BEGIN
  SELECT * INTO v_p FROM parrainages_etablissements WHERE id = p_parrainage_id;
  IF v_p.id IS NULL THEN RETURN; END IF;

  SELECT nom INTO v_filleul_nom FROM etablissements WHERE id = v_p.filleul_etab_id;
  SELECT nom INTO v_parrain_nom FROM etablissements WHERE id = v_p.parrain_etab_id;

  INSERT INTO credits_etablissement (etablissement_id, montant_eur, motif, parrainage_id)
  VALUES (v_p.parrain_etab_id, p_montant_eur, 'PARRAINAGE', v_p.id)
  RETURNING id INTO v_credit_parrain;

  INSERT INTO credits_etablissement (etablissement_id, montant_eur, motif, parrainage_id)
  VALUES (v_p.filleul_etab_id, p_montant_eur, 'PARRAINAGE', v_p.id)
  RETURNING id INTO v_credit_filleul;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_p.parrain_etab_id, p_type_acteur := 'SYSTEME',
    p_action := 'CREDIT_PARRAINAGE_CREE', p_type_ressource := 'parrainage_etab',
    p_id_ressource := v_p.id,
    p_details := jsonb_build_object(
      'palier', p_palier, 'montant_eur', p_montant_eur,
      'credit_parrain_id', v_credit_parrain, 'credit_filleul_id', v_credit_filleul,
      'gmv_cents', p_gmv_cents, 'filleul_etab_id', v_p.filleul_etab_id)
  );

  INSERT INTO notifications (destinataire_id, type_destinataire, type, titre, corps, lien)
  VALUES (
    v_p.parrain_etab_id, 'ETABLISSEMENT', 'CREDIT_PARRAINAGE',
    '🎉 +' || p_montant_eur || '€ de crédit Jolene !',
    'Votre filleul ' || COALESCE(v_filleul_nom, 'établissement') || ' a franchi le palier '
      || p_palier || '. ' || p_montant_eur || '€ de crédit ont été ajoutés et seront déduits de votre prochaine facture commission.',
    '/etablissement/parrainage'
  );

  INSERT INTO notifications (destinataire_id, type_destinataire, type, titre, corps, lien)
  VALUES (
    v_p.filleul_etab_id, 'ETABLISSEMENT', 'CREDIT_PARRAINAGE',
    '🎉 +' || p_montant_eur || '€ de crédit parrainage !',
    'Grâce au parrainage de ' || COALESCE(v_parrain_nom, 'votre parrain') || ', vous avez franchi le palier '
      || p_palier || ' : ' || p_montant_eur || '€ de crédit ont été ajoutés et seront déduits de votre prochaine facture commission.',
    '/etablissement/parrainage'
  );
END;
$$;


ALTER FUNCTION "public"."fn_parrainage_etab_crediter_palier"("p_parrainage_id" "uuid", "p_montant_eur" integer, "p_palier" integer, "p_gmv_cents" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_parrainage_verifier_seuils"("p_parrainage_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_p public.parrainages%ROWTYPE;
  v_prime integer := public.fn_param_num('prime_parrainage_eur', 25)::integer;
  v_seuil_gmv numeric := public.fn_param_num('seuil_gmv_parrainage_eur', 500);
  v_nb_fraude_signals integer;
  v_rows integer;
  v_audit jsonb;
BEGIN
  SELECT p.*
    INTO v_p
    FROM public.parrainages p
   WHERE p.id = p_parrainage_id
   FOR UPDATE;
  IF NOT FOUND OR v_p.statut <> 'FILLEUL_ACTIF' THEN
    RETURN;
  END IF;

  IF COALESCE(v_p.gmv_cumule_filleul, 0) < v_seuil_gmv
     OR COALESCE(v_p.commission_cumulee_filleul, 0) < 4 * v_prime THEN
    RETURN;
  END IF;

  SELECT count(*)
    INTO v_nb_fraude_signals
    FROM public.parrainage_fraude_signals pfs
   WHERE pfs.parrainage_id = v_p.id
     AND pfs.type = 'MEME_IP';
  IF v_nb_fraude_signals > 0 THEN
    UPDATE public.parrainages
       SET statut = 'FRAUDE'
     WHERE id = v_p.id
       AND statut = 'FILLEUL_ACTIF';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Transition fraude parrainage concurrente';
    END IF;
    v_audit := public.fn_ecrire_audit_safe(
      v_p.parrain_id, 'SYSTEME', 'PARRAINAGE_SOIGNANT_FRAUDE',
      'parrainage', v_p.id, NULL,
      jsonb_build_object(
        'filleul_id', v_p.filleul_id,
        'commission_cumulee', v_p.commission_cumulee_filleul,
        'gmv_cumule', v_p.gmv_cumule_filleul,
        'raison', 'MEME_IP détectée à inscription'
      ), NULL, 'fn_parrainage_verifier_seuils'
    );
    IF COALESCE(v_audit @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Audit fraude parrainage non écrit';
    END IF;
    INSERT INTO public.notifications (
      destinataire_id, type_destinataire, type, titre, corps, lien
    )
    SELECT admins.admin_user_id, 'ADMIN', 'SYSTEM',
           'Parrainage fraude détectée',
           'Parrainage ' || v_p.id::text
             || ' : même IP parrain/filleul. Versement bloqué.',
           '/admin/utilisateurs'
      FROM public.fn_list_admin_user_ids() AS admins(admin_user_id);
    RETURN;
  END IF;

  UPDATE public.parrainages
     SET statut = 'VALIDE_EN_ATTENTE_SEUIL'
   WHERE id = v_p.id
     AND statut = 'FILLEUL_ACTIF';
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Validation parrainage concurrente';
  END IF;

  INSERT INTO public.externalisation_actions (
    type_action, payload, source, source_id
  ) VALUES (
    'RECOMPENSE_PARRAINAGE_SOIGNANT',
    jsonb_build_object(
      'parrainage_id', v_p.id,
      'parrain_id', v_p.parrain_id,
      'filleul_id', v_p.filleul_id,
      'montant_parrain', v_prime,
      'montant_filleul', v_prime,
      'commission_cumulee', v_p.commission_cumulee_filleul,
      'gmv_cumule', v_p.gmv_cumule_filleul
    ),
    'parrainage_soignant',
    v_p.id
  )
  ON CONFLICT (type_action, source, source_id)
    WHERE type_action = 'RECOMPENSE_PARRAINAGE_SOIGNANT'
      AND source = 'parrainage_soignant'
      AND source_id IS NOT NULL
  DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Action de récompense parrainage déjà présente';
  END IF;

  v_audit := public.fn_ecrire_audit_safe(
    v_p.parrain_id, 'SYSTEME', 'PARRAINAGE_SOIGNANT_SEUIL_ATTEINT',
    'parrainage', v_p.id, NULL,
    jsonb_build_object(
      'filleul_id', v_p.filleul_id,
      'commission_cumulee', v_p.commission_cumulee_filleul,
      'gmv_cumule', v_p.gmv_cumule_filleul,
      'prime_due_eur', v_prime
    ), NULL, 'fn_parrainage_verifier_seuils'
  );
  IF COALESCE(v_audit @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Audit seuil parrainage non écrit';
  END IF;

  INSERT INTO public.notifications (
    destinataire_id, type_destinataire, type, titre, corps, lien
  ) VALUES
    (
      v_p.parrain_id, 'SOIGNANT', 'PARRAINAGE',
      'Prime de parrainage validée',
      'Votre filleul a atteint le seuil. La prime de ' || v_prime
        || '€ est due et son paiement est en cours de traitement.',
      '/soignant/parrainage'
    ),
    (
      v_p.filleul_id, 'SOIGNANT', 'PARRAINAGE',
      'Prime de parrainage validée',
      'Le seuil est atteint. Votre prime de ' || v_prime
        || '€ est due et son paiement est en cours de traitement.',
      '/soignant/parrainage'
    );
END;
$$;


ALTER FUNCTION "public"."fn_parrainage_verifier_seuils"("p_parrainage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peut_deposer_justificatif"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND public.fn_compte_auth_actif()
    AND p_name IS NOT NULL
    AND p_name NOT LIKE '%..%'
    AND split_part(p_name, '/', 1) = auth.uid()::text;
$$;


ALTER FUNCTION "public"."fn_peut_deposer_justificatif"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peut_gerer_objet_jolene"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'storage'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND public.fn_compte_auth_actif()
    AND (
      split_part(p_name, '/', 1) = auth.uid()::text
      OR public.est_admin()
      OR EXISTS (
        SELECT 1
        FROM public.membres_etablissement me
        WHERE me.user_id = auth.uid()
          AND me.actif
          AND me.role IN ('PROPRIETAIRE', 'ADMIN_GROUPE')
          AND split_part(p_name, '/', 1) = me.etablissement_id::text
      )
    );
$$;


ALTER FUNCTION "public"."fn_peut_gerer_objet_jolene"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peut_lire_justificatif"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND public.fn_compte_auth_actif()
    AND (
      public.est_admin()
      OR public.fn_peut_deposer_justificatif(p_name)
      OR EXISTS (
        SELECT 1 FROM public.missions m
        WHERE m.justificatif_honoraires_cle = p_name
          AND (
            m.soignant_assigne_id = auth.uid()
            OR public.fn_a_permission_etablissement('lecture_paiement', m.etablissement_id)
          )
      )
      OR EXISTS (
        SELECT 1 FROM public.evenements_score_soignant e
        LEFT JOIN public.missions m ON m.id = e.mission_id
        WHERE e.justificatif_storage_path = p_name
          AND (
            e.soignant_id = auth.uid()
            OR public.fn_a_permission_etablissement('candidatures', m.etablissement_id)
          )
      )
      OR EXISTS (
        SELECT 1 FROM public.evenements_score_etab e
        LEFT JOIN public.missions m ON m.id = e.mission_id
        WHERE e.justificatif_storage_path = p_name
          AND (
            public.fn_a_permission_etablissement('profil_etab', e.etablissement_id)
            OR m.soignant_assigne_id = auth.uid()
          )
      )
      OR EXISTS (
        SELECT 1 FROM public.reclamations_score r
        WHERE r.justificatif_storage_path = p_name
          AND r.contesteur_id = auth.uid()
      )
    );
$$;


ALTER FUNCTION "public"."fn_peut_lire_justificatif"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_peut_lire_objet_jolene"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'storage'
    AS $$
  SELECT auth.uid() IS NOT NULL
    AND public.fn_compte_auth_actif()
    AND (
      public.fn_peut_gerer_objet_jolene(p_name)
      OR EXISTS (
        SELECT 1
        FROM public.documents_soignants ds
        JOIN public.partages_rib pr ON pr.document_rib_id = ds.id
        WHERE ds.s3_bucket = 'jolene-documents'
          AND ds.s3_cle = p_name
          AND ds.type_document = 'RIB'
          AND ds.statut_verification = 'VERIFIE'
          AND ds.supprime_le IS NULL
          AND ds.revoque_le IS NULL
          AND ds.resultat_ia->>'verdict_serveur' = 'VERIFIE'
          AND pr.soignant_id = ds.soignant_id
          AND pr.etablissement_id = public.mon_etablissement_id()
          AND pr.actif IS TRUE
          AND (pr.expire_le IS NULL OR pr.expire_le > now())
      )
    );
$$;


ALTER FUNCTION "public"."fn_peut_lire_objet_jolene"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_planifier_serie_onboarding"("p_utilisateur_id" "uuid", "p_serie" "public"."serie_onboarding_type") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  -- J0 retiré : BIENVENUE_SOIGNANT/BIENVENUE_ETABLISSEMENT envoyé immédiatement
  -- par register-soignant/register-etablissement remplit ce rôle. La série
  -- de relances commence à J+1.
  INSERT INTO serie_email_envois (utilisateur_id, serie, etape, planifie_le, statut)
  VALUES
    (p_utilisateur_id, p_serie, 'J1', now() + INTERVAL '1 day', 'PLANIFIE'),
    (p_utilisateur_id, p_serie, 'J3', now() + INTERVAL '3 days', 'PLANIFIE'),
    (p_utilisateur_id, p_serie, 'J7', now() + INTERVAL '7 days', 'PLANIFIE')
  ON CONFLICT (utilisateur_id, serie, etape) DO NOTHING;
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_planifier_serie_onboarding"("p_utilisateur_id" "uuid", "p_serie" "public"."serie_onboarding_type") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pointer_arrivee"("p_mission_id" "uuid", "p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_precision" numeric DEFAULT NULL::numeric, "p_terminal_id" "text" DEFAULT NULL::"text", "p_modele" "text" DEFAULT NULL::"text", "p_code_arrivee" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission RECORD;
  v_contrat RECORD;
  v_etab RECORD;
  v_distance_m numeric;
  v_perimetre_ok boolean;
  v_methode text;
  v_warnings jsonb := '[]'::jsonb;
BEGIN
  SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN RETURN '{"error":"Mission introuvable"}'::JSONB; END IF;
  IF v_mission.soignant_assigne_id != auth.uid() THEN RETURN '{"error":"Accès refusé"}'::JSONB; END IF;
  IF v_mission.statut NOT IN ('ASSIGNEE', 'EN_COURS') THEN RETURN '{"error":"Mission non active"}'::JSONB; END IF;

  SELECT * INTO v_contrat FROM contrats_mission WHERE mission_id = p_mission_id AND statut = 'SIGNE_COMPLET';
  IF v_contrat IS NULL THEN RETURN '{"error":"Le contrat doit être signé avant le pointage."}'::JSONB; END IF;

  IF EXISTS (SELECT 1 FROM presences WHERE mission_id = p_mission_id AND soignant_id = auth.uid()) THEN
    RETURN '{"error":"Vous avez déjà pointé votre arrivée."}'::JSONB;
  END IF;

  SELECT adresse_lat, adresse_lng, COALESCE(tolerance_pointage_m, 500) AS tolerance_m
    INTO v_etab FROM etablissements WHERE id = v_mission.etablissement_id;

  IF p_code_arrivee IS NOT NULL THEN
    IF p_code_arrivee != v_mission.code_arrivee THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'CODE_INCORRECT', 'error', 'Code de pointage incorrect.');
    END IF;
    v_methode := 'CODE';
    v_perimetre_ok := true;
    v_distance_m := NULL;
  ELSE
    IF p_lat IS NULL OR p_lng IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'GPS_MANQUANT',
        'error', 'Coordonnées GPS requises (ou utilisez le code de secours).');
    END IF;
    IF v_etab.adresse_lat IS NULL OR v_etab.adresse_lng IS NULL THEN
      v_distance_m := NULL;
      v_perimetre_ok := false;
    ELSE
      v_distance_m := public.fn_haversine_distance_m(p_lat, p_lng, v_etab.adresse_lat::numeric, v_etab.adresse_lng::numeric);
      v_perimetre_ok := v_distance_m <= v_etab.tolerance_m;
      IF NOT v_perimetre_ok THEN
        RETURN jsonb_build_object('success', false, 'error_code', 'HORS_PERIMETRE',
          'error', 'Vous êtes à ' || v_distance_m::int || 'm de l''établissement (tolérance ' || v_etab.tolerance_m || 'm). Utilisez le code fourni par l''établissement.',
          'distance_m', v_distance_m, 'tolerance_m', v_etab.tolerance_m);
      END IF;
    END IF;
    v_methode := 'GPS';
  END IF;

  IF v_contrat.type_contrat IN ('CDD', 'CDD', 'SALARIE')
     AND COALESCE(v_contrat.dpae_numero, '') = '' THEN
    v_warnings := v_warnings || jsonb_build_object(
      'code', 'DPAE_NON_REGULARISEE',
      'message', 'Votre DPAE URSSAF n''est pas encore enregistrée dans Jolene. L''établissement doit régulariser la déclaration auprès de l''URSSAF et saisir le numéro dans la plateforme.',
      'severite', 'warning'
    );

    BEGIN
      PERFORM net.http_post(
        url := 'https://flripxtsyegjshnhzjkz.supabase.co/functions/v1/send-push',
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1)
        ),
        body := jsonb_build_object(
          'destinataire_id', v_mission.etablissement_id,
          'type_evenement', 'DPAE_NON_REGULARISEE_POINTAGE',
          'titre', '⚠️ DPAE à régulariser',
          'corps', 'Le soignant vient de pointer sur le contrat ' || COALESCE(v_contrat.numero_contrat, '') || ' mais le numéro URSSAF n''est pas saisi. À régulariser sous 24h.',
          'data', jsonb_build_object('contrat_id', v_contrat.id::text, 'mission_id', p_mission_id::text)
        )
      );
    EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  INSERT INTO presences (
    mission_id, soignant_id, pointage_arrivee_le,
    arrivee_lat, arrivee_lng, arrivee_precision_gps_m,
    arrivee_id_terminal, arrivee_modele_terminal,
    methode_pointage_arrivee, distance_etablissement_m, perimetre_gps_valide
  ) VALUES (
    p_mission_id, auth.uid(), NOW(), p_lat, p_lng, p_precision,
    p_terminal_id, p_modele, v_methode, v_distance_m, v_perimetre_ok
  );

  UPDATE missions SET statut = 'EN_COURS', modifie_le = NOW()
   WHERE id = p_mission_id AND statut = 'ASSIGNEE';

  RETURN jsonb_build_object(
    'success', true,
    'methode', v_methode,
    'distance_m', v_distance_m,
    'perimetre_valide', v_perimetre_ok,
    'warnings', v_warnings
  );
END;
$$;


ALTER FUNCTION "public"."fn_pointer_arrivee"("p_mission_id" "uuid", "p_lat" numeric, "p_lng" numeric, "p_precision" numeric, "p_terminal_id" "text", "p_modele" "text", "p_code_arrivee" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pointer_debut_pause"("p_presence_id" "uuid", "p_motif" "text" DEFAULT 'DEJEUNER'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_presence RECORD;
    v_pause_en_cours RECORD;
    v_pause_id UUID;
BEGIN
    SELECT * INTO v_presence FROM presences WHERE id = p_presence_id;
    IF v_presence IS NULL THEN RETURN jsonb_build_object('error', 'Présence introuvable'); END IF;
    IF v_presence.soignant_id != auth.uid() THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;
    IF v_presence.pointage_arrivee_le IS NULL THEN RETURN jsonb_build_object('error', 'Vous devez d''abord pointer votre arrivée'); END IF;
    IF v_presence.pointage_depart_le IS NOT NULL THEN RETURN jsonb_build_object('error', 'La mission est déjà terminée'); END IF;

    -- Vérifier pas de pause déjà en cours
    SELECT * INTO v_pause_en_cours FROM pauses_presence 
    WHERE presence_id = p_presence_id AND fin_le IS NULL;
    IF v_pause_en_cours.id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'Vous avez déjà une pause en cours. Terminez-la avant d''en commencer une autre.');
    END IF;

    INSERT INTO pauses_presence (presence_id, soignant_id, motif)
    VALUES (p_presence_id, auth.uid(), COALESCE(p_motif, 'DEJEUNER'))
    RETURNING id INTO v_pause_id;

    RETURN jsonb_build_object('success', true, 'pause_id', v_pause_id, 'debut', NOW());
END;
$$;


ALTER FUNCTION "public"."fn_pointer_debut_pause"("p_presence_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pointer_depart"("p_presence_id" "uuid", "p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_precision" numeric DEFAULT NULL::numeric, "p_terminal_id" "text" DEFAULT NULL::"text", "p_modele" "text" DEFAULT NULL::"text", "p_code_depart" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_presence RECORD; v_mission RECORD; v_etab RECORD;
  v_distance_m numeric; v_perimetre_ok boolean; v_methode text;
BEGIN
  SELECT * INTO v_presence FROM presences WHERE id = p_presence_id;
  IF v_presence IS NULL THEN RETURN '{"error":"Présence introuvable"}'::JSONB; END IF;
  IF v_presence.soignant_id != auth.uid() THEN RETURN '{"error":"Accès refusé"}'::JSONB; END IF;
  IF v_presence.pointage_depart_le IS NOT NULL THEN RETURN '{"error":"Départ déjà pointé"}'::JSONB; END IF;
  SELECT * INTO v_mission FROM missions WHERE id = v_presence.mission_id;
  SELECT adresse_lat, adresse_lng, COALESCE(tolerance_pointage_m, 500) AS tolerance_m
  INTO v_etab FROM etablissements WHERE id = v_mission.etablissement_id;
  IF p_code_depart IS NOT NULL THEN
    IF p_code_depart != v_mission.code_depart THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'CODE_INCORRECT', 'error', 'Code de départ incorrect.');
    END IF;
    v_methode := 'CODE'; v_perimetre_ok := true; v_distance_m := NULL;
  ELSE
    IF p_lat IS NULL OR p_lng IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'GPS_MANQUANT',
        'error', 'Coordonnées GPS requises (ou utilisez le code de secours).');
    END IF;
    IF v_etab.adresse_lat IS NULL OR v_etab.adresse_lng IS NULL THEN
      v_distance_m := NULL; v_perimetre_ok := false;
    ELSE
      v_distance_m := public.fn_haversine_distance_m(p_lat, p_lng, v_etab.adresse_lat::numeric, v_etab.adresse_lng::numeric);
      v_perimetre_ok := v_distance_m <= v_etab.tolerance_m;
      IF NOT v_perimetre_ok THEN
        RETURN jsonb_build_object('success', false, 'error_code', 'HORS_PERIMETRE',
          'error', 'Vous êtes à ' || v_distance_m::int || 'm de l''établissement (tolérance ' || v_etab.tolerance_m || 'm). Utilisez le code fourni par l''établissement.',
          'distance_m', v_distance_m, 'tolerance_m', v_etab.tolerance_m);
      END IF;
    END IF;
    v_methode := 'GPS';
  END IF;
  UPDATE presences SET
    pointage_depart_le = NOW(),
    depart_lat = p_lat, depart_lng = p_lng,
    depart_precision_gps_m = p_precision,
    depart_id_terminal = p_terminal_id,
    depart_modele_terminal = p_modele,
    methode_pointage_depart = v_methode,
    distance_etablissement_m = COALESCE(distance_etablissement_m, v_distance_m),
    perimetre_gps_valide = CASE WHEN perimetre_gps_valide IS NOT TRUE THEN v_perimetre_ok ELSE perimetre_gps_valide END
  WHERE id = p_presence_id;
  RETURN jsonb_build_object('success', true, 'methode', v_methode,
    'distance_m', v_distance_m, 'perimetre_valide', v_perimetre_ok);
END;
$$;


ALTER FUNCTION "public"."fn_pointer_depart"("p_presence_id" "uuid", "p_lat" numeric, "p_lng" numeric, "p_precision" numeric, "p_terminal_id" "text", "p_modele" "text", "p_code_depart" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pointer_fin_pause"("p_presence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_presence RECORD;
    v_pause RECORD;
    v_duree NUMERIC;
    v_total_pauses NUMERIC;
BEGIN
    SELECT * INTO v_presence FROM presences WHERE id = p_presence_id;
    IF v_presence IS NULL THEN RETURN jsonb_build_object('error', 'Présence introuvable'); END IF;
    IF v_presence.soignant_id != auth.uid() THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;

    -- Trouver la pause en cours
    SELECT * INTO v_pause FROM pauses_presence 
    WHERE presence_id = p_presence_id AND fin_le IS NULL;
    IF v_pause IS NULL THEN
        RETURN jsonb_build_object('error', 'Aucune pause en cours');
    END IF;

    -- Fermer la pause
    UPDATE pauses_presence SET fin_le = NOW() WHERE id = v_pause.id;

    v_duree := ROUND(EXTRACT(EPOCH FROM (NOW() - v_pause.debut_le)) / 60, 2);

    -- Calculer le total des pauses pour cette présence
    SELECT COALESCE(SUM(
        CASE WHEN fin_le IS NOT NULL THEN EXTRACT(EPOCH FROM (fin_le - debut_le)) / 60
        ELSE EXTRACT(EPOCH FROM (NOW() - debut_le)) / 60 END
    ), 0) INTO v_total_pauses FROM pauses_presence WHERE presence_id = p_presence_id;

    -- Mettre à jour le total sur la présence
    UPDATE presences SET 
        duree_pause_min = ROUND(v_total_pauses, 2),
        modifie_le = NOW()
    WHERE id = p_presence_id;

    RETURN jsonb_build_object('success', true, 'duree_cette_pause_min', v_duree, 'total_pauses_min', ROUND(v_total_pauses, 2));
END;
$$;


ALTER FUNCTION "public"."fn_pointer_fin_pause"("p_presence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pool_urgence_etablissement"("p_etablissement_id" "uuid") RETURNS TABLE("soignant_id" "uuid", "prenom" "text", "nom" "text", "profession" "text", "score_fiabilite" integer, "pool_urgence_rayon_km" integer, "distance_km" numeric, "missions_urgence_terminees" bigint, "en_mission_maintenant" boolean, "derniere_mission_chez_nous" timestamp with time zone, "bio" "text", "avatar_url" "text", "est_favori" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_etab public.etablissements%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;
  IF public.fn_a_permission_etablissement(
       'candidatures', p_etablissement_id
     ) IS NOT TRUE THEN
    RAISE EXCEPTION
      'Accès refusé : pool urgence réservé aux responsables de l’établissement'
      USING ERRCODE = '42501';
  END IF;

  SELECT e.* INTO v_etab
  FROM public.etablissements e
  WHERE e.id = p_etablissement_id
    AND e.supprime_le IS NULL;
  IF NOT FOUND THEN RETURN; END IF;

  RETURN QUERY
  SELECT
    s.id,
    s.prenom::text,
    s.nom::text,
    s.profession::text,
    CASE
      WHEN COALESCE(s.total_missions_terminees, 0) >= 3
      THEN s.score_fiabilite::integer
      ELSE NULL
    END,
    COALESCE(s.urgence_rayon_km, 15)::integer,
    CASE
      WHEN s.adresse_lat IS NOT NULL
       AND s.adresse_lng IS NOT NULL
       AND v_etab.adresse_lat IS NOT NULL
       AND v_etab.adresse_lng IS NOT NULL THEN
        pg_catalog.round((
          6371 * pg_catalog.acos(least(
            1.0::double precision,
            greatest(
              (-1.0)::double precision,
              pg_catalog.cos(pg_catalog.radians(v_etab.adresse_lat))
                * pg_catalog.cos(pg_catalog.radians(s.adresse_lat))
                * pg_catalog.cos(
                    pg_catalog.radians(s.adresse_lng)
                    - pg_catalog.radians(v_etab.adresse_lng)
                  )
                + pg_catalog.sin(pg_catalog.radians(v_etab.adresse_lat))
                  * pg_catalog.sin(pg_catalog.radians(s.adresse_lat))
            )
          ))
        )::numeric, 1)
      ELSE NULL
    END,
    (
      SELECT pg_catalog.count(*)::bigint
      FROM public.missions m
      WHERE m.soignant_assigne_id = s.id
        AND COALESCE(m.est_urgente, false) IS TRUE
        AND m.statut = 'TERMINEE'
    ),
    EXISTS (
      SELECT 1
      FROM public.missions m
      WHERE m.soignant_assigne_id = s.id
        AND m.statut = 'EN_COURS'
        AND pg_catalog.now() BETWEEN m.debut_le AND m.fin_le
    ),
    (
      SELECT pg_catalog.max(m2.fin_le)
      FROM public.missions m2
      WHERE m2.soignant_assigne_id = s.id
        AND m2.etablissement_id = p_etablissement_id
        AND m2.statut = 'TERMINEE'
    ),
    s.bio::text,
    s.avatar_url::text,
    EXISTS (
      SELECT 1
      FROM public.favoris_etab_soignant f
      WHERE f.soignant_id = s.id
        AND f.etablissement_id = p_etablissement_id
    )
  FROM public.soignants s
  WHERE private.fn_soignant_messagerie_actif(s.id)
    AND COALESCE(s.disponible_urgence, false) IS TRUE
    AND public.fn_documents_ok_pour_mission(s.id, 'TOUS')
    AND NOT public.fn_est_exclu(s.id, p_etablissement_id)
    AND (
      EXISTS (
        SELECT 1
        FROM public.missions m
        WHERE m.etablissement_id = p_etablissement_id
          AND m.statut IN (
            'OUVERTE', 'ASSIGNEE', 'EN_COURS', 'ABSENCE', 'LITIGE'
          )
          AND public.fn_soignant_compatible_mission(
            s.profession,
            s.specialite_medicale,
            m.profession_requise,
            m.specialite_medicale_requise,
            COALESCE(m.accepte_non_specialises, true)
          )
      )
      OR NOT EXISTS (
        SELECT 1
        FROM public.missions m
        WHERE m.etablissement_id = p_etablissement_id
          AND m.statut IN (
            'OUVERTE', 'ASSIGNEE', 'EN_COURS', 'ABSENCE', 'LITIGE'
          )
      )
    )
  ORDER BY
    CASE
      WHEN COALESCE(s.total_missions_terminees, 0) >= 3
      THEN s.score_fiabilite
      ELSE NULL
    END DESC NULLS LAST,
    CASE
      WHEN s.adresse_lat IS NOT NULL
       AND s.adresse_lng IS NOT NULL
       AND v_etab.adresse_lat IS NOT NULL
       AND v_etab.adresse_lng IS NOT NULL THEN
        6371 * pg_catalog.acos(least(
          1.0::double precision,
          greatest(
            (-1.0)::double precision,
            pg_catalog.cos(pg_catalog.radians(v_etab.adresse_lat))
              * pg_catalog.cos(pg_catalog.radians(s.adresse_lat))
              * pg_catalog.cos(
                  pg_catalog.radians(s.adresse_lng)
                  - pg_catalog.radians(v_etab.adresse_lng)
                )
              + pg_catalog.sin(pg_catalog.radians(v_etab.adresse_lat))
                * pg_catalog.sin(pg_catalog.radians(s.adresse_lat))
          )
        ))
      ELSE NULL
    END NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."fn_pool_urgence_etablissement"("p_etablissement_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_pool_urgence_etablissement"("p_etablissement_id" "uuid") IS 'Pool réservé aux rôles établissement opérationnels ; filtrage par profession requise de chaque mission, dont IADE/IBODE compatibles avec IDE.';



CREATE OR REPLACE FUNCTION "public"."fn_pool_urgence_missions_pour_soignant"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_soignant record;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  SELECT * INTO v_soignant FROM public.soignants WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profil soignant introuvable'); END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', m.id,
    'intitule', m.intitule,
    'profession_requise', m.profession_requise::text,
    'specialite_medicale_requise', m.specialite_medicale_requise,
    'type_contrat_recherche', m.type_contrat_recherche,
    'taux_horaire_base', m.taux_horaire_base,
    'debut_le', m.debut_le,
    'fin_le', m.fin_le,
    'service', m.service,
    'etablissement_nom', e.nom,
    'etablissement_ville', e.adresse_ville,
    'distance_km', CASE
      WHEN e.adresse_lat IS NOT NULL AND v_soignant.adresse_lat IS NOT NULL
      THEN round((public.fn_haversine_distance_m(
        v_soignant.adresse_lat, v_soignant.adresse_lng,
        e.adresse_lat, e.adresse_lng
      ) / 1000.0)::numeric, 1)
      ELSE NULL
    END,
    'deja_candidate', EXISTS (
      SELECT 1 FROM public.candidatures c WHERE c.mission_id = m.id AND c.soignant_id = v_uid
    ),
    'statut_candidature', (
      SELECT statut FROM public.candidatures c
      WHERE c.mission_id = m.id AND c.soignant_id = v_uid LIMIT 1
    )
  ) ORDER BY m.debut_le), '[]'::jsonb)
  INTO v_result
  FROM public.missions m
  JOIN public.etablissements e ON e.id = m.etablissement_id
  WHERE m.statut = 'OUVERTE'
    AND COALESCE(m.est_urgente, false)
    AND m.debut_le > now()
    AND public.fn_soignant_eligible_mission(v_uid, m.id, false)
    AND NOT public.fn_est_exclu(v_uid, m.etablissement_id)
    AND (
      e.adresse_lat IS NULL OR v_soignant.adresse_lat IS NULL
      OR public.fn_haversine_distance_m(
        v_soignant.adresse_lat, v_soignant.adresse_lng,
        e.adresse_lat, e.adresse_lng
      ) <= COALESCE(v_soignant.urgence_rayon_km, 30) * 1000
    );

  RETURN jsonb_build_object(
    'missions', v_result,
    'pool_actif', COALESCE(v_soignant.disponible_urgence, false),
    'rayon_km', COALESCE(v_soignant.urgence_rayon_km, 30),
    'sms_opt_in', COALESCE(v_soignant.pool_urgence_sms_opt_in, false)
  );
END;
$$;


ALTER FUNCTION "public"."fn_pool_urgence_missions_pour_soignant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_postuler_mission"("p_mission_id" "uuid", "p_message" "text" DEFAULT NULL::"text", "p_choix_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_soignant record;
  v_resolution jsonb;
  v_choix text;
  v_candidature_id uuid;
  v_docs_ok boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF v_mission.statut <> 'OUVERTE' THEN RETURN jsonb_build_object('error', 'Cette mission n''est plus disponible'); END IF;
  IF v_mission.mode_attribution <> 'CANDIDATURE' THEN
    RETURN jsonb_build_object('error', 'Cette mission n''accepte pas les candidatures');
  END IF;

  SELECT * INTO v_soignant FROM public.soignants
   WHERE id = auth.uid() AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profil soignant introuvable'); END IF;
  IF COALESCE(v_soignant.statut_compte::text, 'ACTIF') <> 'ACTIF' THEN
    RETURN jsonb_build_object('error', 'Votre compte ne permet pas de candidater. Contactez bonjour@jolene.app.');
  END IF;
  IF NOT public.fn_soignant_compatible_mission(
    v_soignant.profession, v_soignant.specialite_medicale,
    v_mission.profession_requise, v_mission.specialite_medicale_requise,
    COALESCE(v_mission.accepte_non_specialises, true)
  ) THEN
    RETURN jsonb_build_object(
      'error', 'Votre profession ne correspond pas à la mission requise (' ||
        v_mission.profession_requise::text || ').'
    );
  END IF;
  IF public.fn_est_exclu(auth.uid(), v_mission.etablissement_id) THEN
    RETURN jsonb_build_object('error', 'Accès refusé.');
  END IF;

  v_resolution := public.fn_resoudre_contrat_mission(p_mission_id, auth.uid(), p_choix_contrat);
  IF COALESCE((v_resolution->>'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_resolution - 'ok';
  END IF;
  v_choix := v_resolution->>'contrat';

  IF EXISTS (
    SELECT 1 FROM public.candidatures
     WHERE mission_id = p_mission_id AND soignant_id = auth.uid()
  ) THEN
    RETURN jsonb_build_object('error', 'Vous avez déjà postulé à cette mission');
  END IF;

  -- La candidature salariée reste ouverte même si les documents SALARIE_ONLY
  -- doivent être complétés ; l'attribution, elle, reste bloquée jusqu'à validation.
  v_docs_ok := public.fn_documents_ok_pour_mission(auth.uid(), v_choix);
  IF v_choix = 'LIBERAL' AND NOT v_docs_ok THEN
    RETURN jsonb_build_object(
      'error', 'Les documents requis pour candidater en libéral sont manquants ou expirés.',
      'documents_requis_pour', 'LIBERAL',
      'lien_documents', '/soignant/mes-documents'
    );
  END IF;

  INSERT INTO public.candidatures(
    mission_id, soignant_id, message, statut, type_contrat_choisi
  ) VALUES (
    p_mission_id, auth.uid(), public.fn_html_escape(p_message), 'EN_ATTENTE', v_choix
  ) RETURNING id INTO v_candidature_id;

  INSERT INTO public.notifications(destinataire_id, type_destinataire, type, titre, corps, lien)
  VALUES (
    v_mission.etablissement_id, 'ETABLISSEMENT', 'CANDIDATURE_RECUE',
    '📋 Nouvelle candidature reçue',
    COALESCE(v_soignant.prenom, 'Un soignant') || ' a postulé à votre mission « ' ||
      public.fn_html_escape(v_mission.intitule) || ' ».',
    '/etablissement/missions/' || p_mission_id
  );

  IF NOT v_docs_ok THEN
    INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
    SELECT auth.uid(), 'RAPPEL_DOCUMENTS', 'Complétez vos documents salariés',
      'Votre candidature est envoyée. Les documents requis pour le CDD doivent être validés avant que l''établissement puisse vous accepter.',
      '/soignant/mes-documents', 'SOIGNANT'
    WHERE NOT EXISTS (
      SELECT 1 FROM public.notifications
       WHERE destinataire_id = auth.uid()
         AND type = 'RAPPEL_DOCUMENTS'
         AND cree_le > now() - interval '24 hours'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'candidature_id', v_candidature_id,
    'choix_contrat', v_choix,
    'profession_requise', v_mission.profession_requise::text,
    'docs_a_completer', NOT v_docs_ok,
    'documents_requis_pour', v_choix
  );
END;
$$;


ALTER FUNCTION "public"."fn_postuler_mission"("p_mission_id" "uuid", "p_message" "text", "p_choix_contrat" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_postuler_mission"("p_mission_id" "uuid", "p_message" "text", "p_choix_contrat" "text") IS 'E16 — Persiste type_contrat_choisi dans candidatures pour defi URSSAF.';



CREATE OR REPLACE FUNCTION "public"."fn_postuler_mission_rate_limited"("p_mission_id" "uuid", "p_message" "text" DEFAULT NULL::"text", "p_choix_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;
  -- 20 candidatures / heure / utilisateur (même seuil que l'ancien wrapper).
  IF NOT fn_verifier_rate_limit(v_user_id::text, 'candidature', 20, 3600) THEN
    RETURN jsonb_build_object('error', 'Trop de candidatures en peu de temps. Réessayez plus tard.');
  END IF;
  RETURN fn_postuler_mission(p_mission_id, p_message, p_choix_contrat);
END;
$$;


ALTER FUNCTION "public"."fn_postuler_mission_rate_limited"("p_mission_id" "uuid", "p_message" "text", "p_choix_contrat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_pre_request_compte_actif"() RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_claims jsonb := COALESCE(
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb,
    '{}'::jsonb
  );
BEGIN
  IF COALESCE(v_claims->>'role', '') = 'authenticated'
     AND NOT public.fn_compte_auth_actif() THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Compte suspendu, supprimé ou désactivé';
  END IF;
END;
$$;


ALTER FUNCTION "public"."fn_pre_request_compte_actif"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_preparer_facture_commission_periode"("p_facture_honoraire_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_fh public.factures_honoraires%ROWTYPE;
  v_mission public.missions%ROWTYPE;
  v_etab public.etablissements%ROWTYPE;
  v_existing public.factures%ROWTYPE;
  v_total_precedent numeric := 0;
  v_ttc numeric(10,2);
  v_ht numeric(10,2);
  v_tva numeric(10,2);
  v_numero text;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_fh
  FROM public.factures_honoraires
  WHERE id = p_facture_honoraire_id
    AND type_document = 'FACTURE'
    AND statut IN ('EMISE', 'EN_RETARD', 'PAYEE')
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Facture d''honoraires introuvable ou non payable' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_existing
  FROM public.factures
  WHERE facture_honoraire_id = v_fh.id
    AND type_document = 'FACTURE'
    AND statut NOT IN ('ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION')
  FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', true,
      'facture_id', v_existing.id,
      'numero_facture', v_existing.numero_facture,
      'montant_ttc', v_existing.montant_ttc,
      'existing', true
    );
  END IF;

  SELECT * INTO v_mission FROM public.missions WHERE id = v_fh.mission_id FOR UPDATE;
  SELECT * INTO v_etab FROM public.etablissements WHERE id = v_fh.etablissement_id;
  IF NOT FOUND OR v_mission.id IS NULL OR v_etab.id IS NULL
     OR v_mission.type_contrat_applique <> 'LIBERAL'
     OR v_mission.soignant_assigne_id <> v_fh.soignant_id
     OR v_mission.etablissement_id <> v_fh.etablissement_id
     OR COALESCE(v_mission.net_a_payer, 0) <= 0
     OR COALESCE(v_mission.montant_commission_ttc, 0) <= 0 THEN
    RAISE EXCEPTION 'Mission incohérente pour la facture de commission' USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(sum(f.montant_ttc), 0)
  INTO v_total_precedent
  FROM public.factures f
  WHERE f.mission_id = v_mission.id
    AND f.facture_honoraire_id IS NOT NULL
    AND f.type_document = 'FACTURE'
    AND f.statut NOT IN ('ANNULEE', 'REMPLACEE', 'ERREUR_GENERATION');

  IF v_fh.est_facture_finale_mission THEN
    v_ttc := round(GREATEST(v_mission.montant_commission_ttc - v_total_precedent, 0), 2);
  ELSE
    v_ttc := round(
      LEAST(
        v_mission.montant_commission_ttc - v_total_precedent,
        v_mission.montant_commission_ttc * v_fh.montant_ttc / v_mission.net_a_payer
      ),
      2
    );
  END IF;
  IF v_ttc <= 0 THEN
    RAISE EXCEPTION 'Commission de période nulle ou déjà intégralement facturée' USING ERRCODE = '23514';
  END IF;

  v_ht := round(v_ttc / 1.20, 2);
  v_tva := v_ttc - v_ht;
  v_numero := 'JOL-' || to_char(CURRENT_DATE, 'YYYY') || '-H-' || upper(left(replace(v_fh.id::text, '-', ''), 10));

  INSERT INTO public.factures (
    etablissement_id, mission_id, facture_honoraire_id, numero_facture,
    periode_debut, periode_fin, montant_ht, taux_tva, montant_tva, montant_ttc,
    nombre_missions, statut, date_emission, date_echeance,
    est_secteur_public, mode_paiement, chorus_pro_statut, type_document
  ) VALUES (
    v_fh.etablissement_id, v_fh.mission_id, v_fh.id, v_numero,
    v_fh.periode_debut, v_fh.periode_fin, v_ht, 20, v_tva, v_ttc,
    1, 'EMISE', now(), CURRENT_DATE + 30,
    COALESCE(v_etab.est_secteur_public, false),
    CASE WHEN COALESCE(v_etab.est_secteur_public, false) THEN 'CHORUS_PRO' ELSE 'STRIPE' END,
    CASE WHEN COALESCE(v_etab.est_secteur_public, false) THEN 'A_DEPOSER' ELSE 'NON_APPLICABLE' END,
    'FACTURE'
  )
  RETURNING * INTO v_existing;

  IF v_fh.est_facture_finale_mission THEN
    UPDATE public.missions
    SET commission_facturee = true,
        facture_id = v_existing.id,
        modifie_le = now()
    WHERE id = v_mission.id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'facture_id', v_existing.id,
    'numero_facture', v_existing.numero_facture,
    'montant_ttc', v_existing.montant_ttc,
    'est_secteur_public', v_existing.est_secteur_public,
    'existing', false
  );
END;
$$;


ALTER FUNCTION "public"."fn_preparer_facture_commission_periode"("p_facture_honoraire_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_preparer_identite_document"("p_soignant_id" "uuid", "p_date_naissance" "date", "p_sexe" "text" DEFAULT NULL::"text", "p_lieu_naissance" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_soignant public.soignants%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Accès réservé au service de vérification' USING ERRCODE = '42501';
  END IF;
  IF p_soignant_id IS NULL OR p_date_naissance IS NULL THEN
    RETURN jsonb_build_object('date_naissance_correspond', false, 'error_code', 'IDENTITE_INCOMPLETE');
  END IF;

  SELECT * INTO v_soignant
  FROM public.soignants
  WHERE id = p_soignant_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('date_naissance_correspond', false, 'error_code', 'SOIGNANT_INTROUVABLE');
  END IF;
  IF v_soignant.date_naissance IS NOT NULL
     AND v_soignant.date_naissance IS DISTINCT FROM p_date_naissance THEN
    RETURN jsonb_build_object('date_naissance_correspond', false, 'error_code', 'DATE_NAISSANCE_INCOHERENTE');
  END IF;

  UPDATE public.soignants
  SET date_naissance = COALESCE(date_naissance, p_date_naissance),
      sexe = CASE
        WHEN sexe IS NULL AND p_sexe IN ('M', 'F') THEN p_sexe
        ELSE sexe
      END,
      lieu_naissance_commune = CASE
        WHEN lieu_naissance_commune IS NULL AND NULLIF(btrim(p_lieu_naissance), '') IS NOT NULL
          THEN left(btrim(p_lieu_naissance), 120)
        ELSE lieu_naissance_commune
      END,
      modifie_le = now()
  WHERE id = p_soignant_id;

  RETURN jsonb_build_object('date_naissance_correspond', true);
END;
$$;


ALTER FUNCTION "public"."fn_preparer_identite_document"("p_soignant_id" "uuid", "p_date_naissance" "date", "p_sexe" "text", "p_lieu_naissance" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_presences_detail_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_mission RECORD;
    v_presence RECORD;
    v_pauses JSONB;
BEGIN
    SELECT * INTO v_mission FROM missions WHERE id = p_mission_id;
    IF v_mission IS NULL THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;

    IF v_mission.etablissement_id != mon_etablissement_id() AND NOT est_admin() 
       AND v_mission.soignant_assigne_id != auth.uid() THEN
        RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    SELECT * INTO v_presence FROM presences WHERE mission_id = p_mission_id LIMIT 1;

    IF v_presence IS NULL THEN
        RETURN jsonb_build_object('pointage_effectue', false, 'heures_planifiees', v_mission.duree_heures);
    END IF;

    -- Récupérer les pauses détaillées
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', pp.id, 'debut', pp.debut_le, 'fin', pp.fin_le, 
        'duree_min', pp.duree_min, 'motif', pp.motif, 'en_cours', pp.fin_le IS NULL
    ) ORDER BY pp.debut_le), '[]'::JSONB) INTO v_pauses
    FROM pauses_presence pp WHERE pp.presence_id = v_presence.id;

    RETURN jsonb_build_object(
        'pointage_effectue', true,
        'heures_planifiees', v_mission.duree_heures,
        'heures_reelles', v_presence.heures_reelles,
        'pointage_arrivee', v_presence.pointage_arrivee_le,
        'pointage_depart', v_presence.pointage_depart_le,
        'methode_arrivee', v_presence.methode_pointage_arrivee,
        'methode_depart', v_presence.methode_pointage_depart,
        'retard_min', v_presence.retard_min,
        'depart_anticipe_min', v_presence.depart_anticipe_min,
        'duree_brute_min', v_presence.duree_brute_min,
        'duree_pause_min', v_presence.duree_pause_min,
        'duree_nette_min', v_presence.duree_nette_min,
        'nb_pauses', jsonb_array_length(v_pauses),
        'pauses', v_pauses,
        'distance_m', v_presence.distance_etablissement_m,
        'perimetre_valide', v_presence.perimetre_gps_valide,
        'alerte_teleportation', v_presence.alerte_teleportation,
        'alertes', v_presence.alertes_fraude,
        'valide', v_presence.valide_par_etablissement
    );
END;
$$;


