CREATE OR REPLACE FUNCTION "public"."fn_proposer_accord_partie"("p_litige_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etablissement_id uuid;
  v_litige record;
  v_role text;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  v_etablissement_id := public.mon_etablissement_id();
  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
     AND (
       l.soignant_id = v_uid
       OR (
         l.etablissement_id = v_etablissement_id
         AND public.fn_a_permission_etablissement(
           'contrats', l.etablissement_id
         ) IS TRUE
       )
     )
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Litige introuvable ou accès refusé'
    );
  END IF;
  IF v_litige.statut NOT IN ('OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Litige déjà en médiation ou résolu'
    );
  END IF;
  IF v_litige.payload_modifications IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'La proposition existante doit être traitée via son payload exact'
    );
  END IF;

  v_role := CASE
    WHEN v_litige.soignant_id = v_uid THEN 'soignant'
    ELSE 'etablissement'
  END;

  UPDATE public.litiges
     SET statut = 'MEDIATION_EN_COURS'
   WHERE id = p_litige_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := CASE
      WHEN v_role = 'etablissement' THEN 'ADMIN_ETABLISSEMENT'
      ELSE 'SOIGNANT'
    END,
    p_action := 'MEDIATION_OUVERTE',
    p_type_ressource := 'litige',
    p_id_ressource := p_litige_id,
    p_details := jsonb_build_object('initie_par', v_role)
  );

  PERFORM public.fn_creer_notification(
    p_destinataire_id := CASE
      WHEN v_role = 'etablissement' THEN v_litige.soignant_id
      ELSE v_litige.etablissement_id
    END,
    p_type_destinataire := CASE
      WHEN v_role = 'etablissement' THEN 'SOIGNANT'
      ELSE 'ETABLISSEMENT'
    END,
    p_type := 'LITIGE_MEDIATION',
    p_titre := 'Médiation litige proposée',
    p_corps := 'L''autre partie propose une médiation amiable. Vous avez 7 jours pour discuter et confirmer un accord.',
    p_lien := CASE
      WHEN v_role = 'etablissement' THEN '/soignant/litiges'
      ELSE '/etablissement/litiges'
    END,
    p_type_ressource := 'litige',
    p_id_ressource := p_litige_id
  );

  RETURN jsonb_build_object('success', true, 'statut', 'MEDIATION_EN_COURS');
END;
$$;


ALTER FUNCTION "public"."fn_proposer_accord_partie"("p_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_proposer_cloture_litige"("p_litige_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.fn_cloturer_litige(p_litige_id, NULL);
  IF v_result ? 'error' THEN
    RETURN v_result;
  END IF;
  IF v_result->>'statut' = 'RESOLU_ACCORD_PARTIES' THEN
    RETURN jsonb_build_object(
      'success', true,
      'statut', 'cloture_validee',
      'message', 'Litige clôturé à l''amiable'
    );
  END IF;
  RETURN jsonb_build_object(
    'success', true,
    'statut', 'en_attente',
    'details', v_result
  );
END;
$$;


ALTER FUNCTION "public"."fn_proposer_cloture_litige"("p_litige_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_proposer_mission_soignant"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_soignant record;
  v_resolution jsonb;
  v_choix text;
  v_candidature_id uuid;
BEGIN
  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission introuvable'); END IF;
  IF NOT public.est_admin()
     AND v_mission.etablissement_id IS DISTINCT FROM public.mon_etablissement_id() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;
  IF v_mission.statut <> 'OUVERTE' THEN
    RETURN jsonb_build_object('error', 'La mission n’est plus ouverte');
  END IF;

  SELECT * INTO v_soignant
    FROM public.soignants
   WHERE id = p_soignant_id AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Soignant introuvable'); END IF;
  IF NOT public.fn_soignant_compatible_mission(
    v_soignant.profession, v_soignant.specialite_medicale,
    v_mission.profession_requise, v_mission.specialite_medicale_requise,
    COALESCE(v_mission.accepte_non_specialises, true)
  ) THEN
    RETURN jsonb_build_object(
      'error', 'Ce soignant n’est pas compatible avec la profession requise par la mission (' ||
        v_mission.profession_requise::text || ').'
    );
  END IF;
  IF public.fn_est_exclu(p_soignant_id, v_mission.etablissement_id) THEN
    RETURN jsonb_build_object('error', 'Ce soignant est dans votre liste d’exclusions.');
  END IF;

  v_resolution := public.fn_resoudre_contrat_mission(
    p_mission_id, p_soignant_id, p_choix_contrat
  );
  IF COALESCE((v_resolution->>'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_resolution - 'ok';
  END IF;
  v_choix := v_resolution->>'contrat';
  IF NOT public.fn_documents_ok_pour_mission(p_soignant_id, v_choix) THEN
    RETURN jsonb_build_object(
      'error', 'Ce soignant n’a pas encore les documents validés pour une mission ' || lower(v_choix) || '.',
      'documents_requis_pour', v_choix
    );
  END IF;

  -- La carte affiche une fenêtre de réponse de 2 h : la même règle est
  -- appliquée en base avant de rechercher un doublon actif.
  UPDATE public.candidatures
     SET statut = 'EXPIREE', traite_le = now()
   WHERE mission_id = p_mission_id
     AND soignant_id = p_soignant_id
     AND statut = 'PROPOSEE'
     AND cree_le < now() - interval '2 hours';

  IF EXISTS (
    SELECT 1 FROM public.candidatures
     WHERE mission_id = p_mission_id
       AND soignant_id = p_soignant_id
       AND statut IN ('EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB', 'PROPOSEE', 'ACCEPTEE')
  ) THEN
    RETURN jsonb_build_object('error', 'Cette mission a déjà été proposée à ce soignant.');
  END IF;

  INSERT INTO public.candidatures(
    mission_id, soignant_id, statut, type_contrat_choisi
  ) VALUES (
    p_mission_id, p_soignant_id, 'PROPOSEE', v_choix
  ) RETURNING id INTO v_candidature_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := auth.uid(),
    p_type_acteur := CASE WHEN public.est_admin() THEN 'ADMIN' ELSE 'ADMIN_ETABLISSEMENT' END,
    p_action := 'MISSION_PROPOSEE_SOIGNANT',
    p_type_ressource := 'candidature',
    p_id_ressource := v_candidature_id,
    p_details := jsonb_build_object(
      'mission_id', p_mission_id,
      'soignant_id', p_soignant_id,
      'profession_requise', v_mission.profession_requise::text,
      'type_contrat_choisi', v_choix
    )
  );

  INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (
    p_soignant_id, 'CANDIDATURE_PROPOSEE', 'Mission proposée',
    'Un établissement vous propose la mission « ' || public.fn_html_escape(v_mission.intitule) ||
      ' » en ' || lower(v_choix) || '.',
    '/soignant/missions/' || p_mission_id, 'SOIGNANT'
  );

  RETURN jsonb_build_object(
    'success', true,
    'candidature_id', v_candidature_id,
    'choix_persiste', v_choix,
    'profession_requise', v_mission.profession_requise::text
  );
END;
$$;


ALTER FUNCTION "public"."fn_proposer_mission_soignant"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_proposer_mission_soignant"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text") IS 'E16 ajoute p_choix_contrat strict pour MIXTE TOUS persiste type_contrat_choisi dans candidatures evite propositions orphelines';



CREATE OR REPLACE FUNCTION "public"."fn_protect_adeli_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF auth.role() = 'service_role'
     OR auth.uid() IS NULL
     OR public.est_admin()
     OR COALESCE(current_setting('jolene.system_update', true), '') = 'true' THEN
    RETURN NEW;
  END IF;
  IF OLD.id = auth.uid() THEN
    NEW.adeli_verifie := OLD.adeli_verifie;
    NEW.adeli_verifie_le := OLD.adeli_verifie_le;
    NEW.adeli_nom_api := OLD.adeli_nom_api;
    NEW.adeli_prenom_api := OLD.adeli_prenom_api;
    NEW.adeli_profession_api := OLD.adeli_profession_api;
    IF OLD.adeli_verifie IS TRUE THEN
      NEW.numero_adeli := OLD.numero_adeli;
      NEW.profession := OLD.profession;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_adeli_verification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_api_key_secrets"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.cle_api IS DISTINCT FROM OLD.cle_api THEN
    RAISE EXCEPTION 'La clé API ne peut pas être modifiée après création';
  END IF;
  IF NEW.cle_secret IS DISTINCT FROM OLD.cle_secret THEN
    RAISE EXCEPTION 'Le secret API ne peut pas être modifié après création';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_api_key_secrets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_bulletin_paie_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_role text := current_setting('role', true);
  v_is_admin boolean;
BEGIN
  -- Bypass : service_role et admins peuvent tout
  v_is_admin := COALESCE((SELECT public.est_admin()), false);
  IF v_role = 'service_role' OR v_is_admin THEN
    NEW.modifie_le := now();
    RETURN NEW;
  END IF;

  IF OLD.statut = 'EMIS' OR OLD.statut = 'PAYE' THEN
    IF NEW.numero_bulletin IS DISTINCT FROM OLD.numero_bulletin
       OR NEW.salaire_brut IS DISTINCT FROM OLD.salaire_brut
       OR NEW.total_cotisations_salariales IS DISTINCT FROM OLD.total_cotisations_salariales
       OR NEW.net_avant_impot IS DISTINCT FROM OLD.net_avant_impot
       OR NEW.periode_debut IS DISTINCT FROM OLD.periode_debut
       OR NEW.periode_fin IS DISTINCT FROM OLD.periode_fin
       OR NEW.soignant_id IS DISTINCT FROM OLD.soignant_id
       OR NEW.mission_id IS DISTINCT FROM OLD.mission_id
       OR NEW.etablissement_id IS DISTINCT FROM OLD.etablissement_id
       OR NEW.date_emission IS DISTINCT FROM OLD.date_emission
    THEN
      RAISE EXCEPTION 'Bulletin de paie % : modification interdite après émission (art. L3243-4 CTW). Champs verrouillés : numero, montants, dates, identités.',
        OLD.numero_bulletin;
    END IF;
  END IF;

  NEW.modifie_le := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_bulletin_paie_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_candidature_statut"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role' THEN
    RETURN NEW;
  END IF;
  IF auth.uid() IS NULL OR public.est_admin() THEN RETURN NEW; END IF;

  IF current_setting('jolene.candidature_rpc_mission_id', true) = OLD.mission_id::text THEN
    IF NEW.mission_id IS DISTINCT FROM OLD.mission_id
       OR NEW.soignant_id IS DISTINCT FROM OLD.soignant_id THEN
      RAISE EXCEPTION 'Modification interdite';
    END IF;
    IF OLD.statut = 'PROPOSEE'
       AND NEW.statut IN ('ACCEPTEE', 'REFUSEE', 'EXPIREE') THEN
      NEW.message := OLD.message;
      RETURN NEW;
    END IF;
    IF OLD.statut IN ('EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB', 'PROPOSEE')
       AND NEW.statut = 'REFUSEE' THEN
      NEW.message := OLD.message;
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'Transition de statut candidature non autorisée: % → %', OLD.statut, NEW.statut;
  END IF;

  IF auth.uid() = OLD.soignant_id THEN
    IF NEW.mission_id IS DISTINCT FROM OLD.mission_id
       OR NEW.soignant_id IS DISTINCT FROM OLD.soignant_id THEN
      RAISE EXCEPTION 'Modification interdite';
    END IF;
    IF NEW.statut IS DISTINCT FROM OLD.statut THEN
      IF OLD.statut IN ('EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB')
         AND NEW.statut = 'ANNULEE' THEN
        RETURN NEW;
      ELSIF OLD.statut = 'ACCEPTEE'
            AND NEW.statut = 'ANNULEE'
            AND COALESCE(current_setting('jolene.annulation_soignant_ctx', true), '') = 'true' THEN
        RETURN NEW;
      ELSE
        RAISE EXCEPTION 'Vous ne pouvez pas modifier le statut de votre candidature (% → %)',
          OLD.statut, NEW.statut;
      END IF;
    END IF;
    IF NEW.message IS DISTINCT FROM OLD.message AND OLD.statut <> 'EN_ATTENTE' THEN
      RAISE EXCEPTION 'Vous ne pouvez plus modifier votre message';
    END IF;
    NEW.motif_refus := OLD.motif_refus;
    NEW.traite_le := OLD.traite_le;
    RETURN NEW;
  END IF;

  IF public.mon_etablissement_id() IS NOT NULL THEN
    IF NEW.mission_id IS DISTINCT FROM OLD.mission_id
       OR NEW.soignant_id IS DISTINCT FROM OLD.soignant_id THEN
      RAISE EXCEPTION 'Modification interdite';
    END IF;
    IF NEW.statut IS DISTINCT FROM OLD.statut
       AND NOT (
         (OLD.statut = 'EN_ATTENTE' AND NEW.statut IN ('ACCEPTEE', 'REFUSEE'))
         OR (OLD.statut = 'EN_ATTENTE_VALIDATION_ETAB' AND NEW.statut IN ('ACCEPTEE', 'REFUSEE'))
         OR (OLD.statut = 'PROPOSEE' AND NEW.statut IN ('ACCEPTEE', 'REFUSEE', 'EXPIREE'))
       ) THEN
      RAISE EXCEPTION 'Transition de statut candidature non autorisée: % → %', OLD.statut, NEW.statut;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'Accès refusé à cette candidature';
END;
$$;


ALTER FUNCTION "public"."fn_protect_candidature_statut"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_contrat_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Si le caller est le soignant, on ne laisse passer que ses propres champs de signature
  IF OLD.soignant_id = auth.uid()
     AND NOT public.est_admin()
     AND NOT public.est_admin_etablissement() THEN
    NEW.signature_etablissement := OLD.signature_etablissement;
    NEW.signature_etablissement_le := OLD.signature_etablissement_le;
    NEW.signature_image_etablissement := OLD.signature_image_etablissement;
    NEW.signature_ip_etablissement := OLD.signature_ip_etablissement;
    NEW.signature_navigateur_etablissement := OLD.signature_navigateur_etablissement;
    NEW.contenu_html := OLD.contenu_html;
    -- Statut : verrouillé SAUF transition de signature légitime déclenchée par
    -- fn_signer_contrat_soignant (drapeau de session, non posable côté client).
    IF NOT (current_setting('jolene.signature_soignant_en_cours', true) = '1'
            AND NEW.statut IN ('SIGNE_SOIGNANT', 'SIGNE_COMPLET')) THEN
      NEW.statut := OLD.statut;
    END IF;
    NEW.numero_contrat := OLD.numero_contrat;
    NEW.type_contrat := OLD.type_contrat;
    NEW.etablissement_id := OLD.etablissement_id;
    NEW.mission_id := OLD.mission_id;
    NEW.pdf_cle_s3 := OLD.pdf_cle_s3;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_contrat_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_creneaux_si_facture"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission_id uuid;
  v_type_creneau text;
  v_has_facture boolean;
  v_correction_mission uuid;
  v_correction_reason text;
  v_fige_le timestamptz;
  v_override_gel_mission uuid;
  v_override_gel_reason text;
BEGIN
  v_mission_id := COALESCE(NEW.mission_id, OLD.mission_id);
  v_type_creneau := COALESCE(NEW.type_creneau, OLD.type_creneau);

  -- CHECK 1 (CP5b): PREVISIONNEL immutables après gel
  IF v_type_creneau = 'PREVISIONNEL' THEN
    SELECT fige_le INTO v_fige_le FROM missions WHERE id = v_mission_id;

    IF v_fige_le IS NOT NULL THEN
      v_override_gel_mission := NULLIF(current_setting('jolene.admin_override_gel', true), '')::uuid;
      v_override_gel_reason := NULLIF(current_setting('jolene.admin_override_reason', true), '');

      IF v_override_gel_mission = v_mission_id AND v_override_gel_reason IS NOT NULL THEN
        INSERT INTO journaux_audit
          (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
        VALUES (
          auth.uid(), 'ADMIN_PLATEFORME', 'OVERRIDE_CHAMP_POST_GEL', 'mission_creneaux',
          COALESCE(NEW.id, OLD.id),
          jsonb_build_object(
            'reason', v_override_gel_reason,
            'mission_id', v_mission_id,
            'operation', TG_OP,
            'type_creneau', 'PREVISIONNEL'
          )
        );
      ELSE
        RAISE EXCEPTION 'Créneaux PREVISIONNEL immutables après gel (mission gelée le %). Les créneaux prévisionnels ne peuvent pas être modifiés après assignation. Pour corriger, un admin doit définir jolene.admin_override_gel et jolene.admin_override_reason.',
          v_fige_le USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;

  -- CHECK 2 (CP3): Facture émise bloque TOUS les créneaux
  SELECT EXISTS (
    SELECT 1 FROM factures_honoraires
    WHERE mission_id = v_mission_id
      AND statut NOT IN ('BROUILLON', 'ANNULEE')
  ) INTO v_has_facture;

  IF NOT v_has_facture THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  v_correction_mission := NULLIF(current_setting('jolene.admin_correction_mission_id', true), '')::uuid;
  v_correction_reason := NULLIF(current_setting('jolene.admin_correction_reason', true), '');

  IF v_correction_mission = v_mission_id AND v_correction_reason IS NOT NULL THEN
    INSERT INTO invoice_audit_log (invoice_id, action, performed_by, payload_before)
    SELECT fh.id, 'CRENEAUX_MODIFIED_POST_FACTURE', auth.uid(),
      jsonb_build_object(
        'reason', v_correction_reason,
        'mission_id', v_mission_id,
        'operation', TG_OP,
        'creneau_id', COALESCE(NEW.id, OLD.id)
      )
    FROM factures_honoraires fh
    WHERE fh.mission_id = v_mission_id AND fh.statut NOT IN ('BROUILLON', 'ANNULEE')
    LIMIT 1;

    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  RAISE EXCEPTION 'Impossible de modifier les créneaux : une facture émise existe pour cette mission (mission_id=%). Pour corriger, un admin doit définir jolene.admin_correction_mission_id et jolene.admin_correction_reason.',
    v_mission_id USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION "public"."fn_protect_creneaux_si_facture"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_document_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT est_admin() THEN
    IF NEW.statut_verification IS DISTINCT FROM OLD.statut_verification THEN
      RAISE EXCEPTION 'Modification du statut de vérification interdite';
    END IF;
    IF NEW.verifie_par IS DISTINCT FROM OLD.verifie_par THEN
      RAISE EXCEPTION 'Modification du vérificateur interdite';
    END IF;
    IF NEW.verifie_le IS DISTINCT FROM OLD.verifie_le THEN
      RAISE EXCEPTION 'Modification de la date de vérification interdite';
    END IF;
    IF NEW.motif_rejet IS DISTINCT FROM OLD.motif_rejet THEN
      RAISE EXCEPTION 'Modification du motif de rejet interdite';
    END IF;
    IF NEW.est_critique IS DISTINCT FROM OLD.est_critique THEN
      RAISE EXCEPTION 'Modification du caractère critique interdite';
    END IF;
    IF NEW.rappel_j7_envoye IS DISTINCT FROM OLD.rappel_j7_envoye
       OR NEW.rappel_j30_envoye IS DISTINCT FROM OLD.rappel_j30_envoye
       OR NEW.rappel_expire_envoye IS DISTINCT FROM OLD.rappel_expire_envoye THEN
      RAISE EXCEPTION 'Modification des rappels interdite';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_document_verification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_etablissement_commercial"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_jwt_role text := COALESCE(
    auth.jwt()->>'role',
    current_setting('request.jwt.claim.role', true),
    ''
  );
  v_is_service_role boolean;
  v_is_internal boolean;
  v_identite_changee boolean;
  v_justificatif_change boolean;
  v_rib_change boolean;
  v_contrat_change boolean;
  v_finess_change boolean;
  v_siret_change boolean;
  v_source_changee boolean;
  v_signature_active_le timestamptz;
  v_signature_transition boolean := false;
  v_revocation_globale boolean := false;
  v_rattachement_invalide boolean := false;
  v_rattachement_attendu boolean := false;
  v_methode_attendue text := 'ADMIN';
  v_match_dirigeant boolean := false;
BEGIN
  v_is_service_role := v_jwt_role = 'service_role'
    OR (auth.uid() IS NULL AND v_jwt_role <> 'anon');
  IF v_is_service_role OR public.est_admin() THEN
    RETURN NEW;
  END IF;

  v_identite_changee :=
    NEW.representant_piece_s3_key IS DISTINCT FROM OLD.representant_piece_s3_key
    OR NEW.representant_piece_type_document IS DISTINCT FROM OLD.representant_piece_type_document
    OR NEW.representant_piece_type_mime IS DISTINCT FROM OLD.representant_piece_type_mime
    OR NEW.representant_nom IS DISTINCT FROM OLD.representant_nom
    OR NEW.representant_prenom IS DISTINCT FROM OLD.representant_prenom;
  v_justificatif_change :=
    NEW.justificatif_fonction_s3_key IS DISTINCT FROM OLD.justificatif_fonction_s3_key
    OR NEW.justificatif_fonction_type IS DISTINCT FROM OLD.justificatif_fonction_type
    OR NEW.justificatif_fonction_type_mime IS DISTINCT FROM OLD.justificatif_fonction_type_mime;
  v_rib_change := NEW.rib_s3_key IS DISTINCT FROM OLD.rib_s3_key;
  v_contrat_change := NEW.contrat_url IS DISTINCT FROM OLD.contrat_url;
  v_finess_change :=
    NEW.finess IS DISTINCT FROM OLD.finess
    OR NEW.nom IS DISTINCT FROM OLD.nom
    OR NEW.adresse_rue IS DISTINCT FROM OLD.adresse_rue
    OR NEW.adresse_ville IS DISTINCT FROM OLD.adresse_ville
    OR NEW.adresse_code_postal IS DISTINCT FROM OLD.adresse_code_postal;
  v_siret_change := NEW.siret IS DISTINCT FROM OLD.siret;
  v_source_changee := v_identite_changee OR v_justificatif_change
    OR v_rib_change OR v_contrat_change OR v_finess_change OR v_siret_change;

  IF v_identite_changee THEN
    IF NEW.representant_identite_verifiee IS DISTINCT FROM false
       OR NEW.representant_identite_verifiee_le IS NOT NULL
       OR NEW.representant_identite_resultat_ia IS NOT NULL THEN
      RAISE EXCEPTION 'Révocation identité non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.representant_identite_verifiee IS DISTINCT FROM OLD.representant_identite_verifiee
     OR NEW.representant_identite_verifiee_le IS DISTINCT FROM OLD.representant_identite_verifiee_le
     OR NEW.representant_identite_resultat_ia IS DISTINCT FROM OLD.representant_identite_resultat_ia THEN
    RAISE EXCEPTION 'Écriture directe du verdict identité interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_justificatif_change THEN
    IF NEW.justificatif_fonction_verifie IS DISTINCT FROM false
       OR NEW.justificatif_fonction_verifie_le IS NOT NULL
       OR NEW.justificatif_fonction_resultat_ia IS NOT NULL THEN
      RAISE EXCEPTION 'Révocation justificatif non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.justificatif_fonction_verifie IS DISTINCT FROM OLD.justificatif_fonction_verifie
     OR NEW.justificatif_fonction_verifie_le IS DISTINCT FROM OLD.justificatif_fonction_verifie_le
     OR NEW.justificatif_fonction_resultat_ia IS DISTINCT FROM OLD.justificatif_fonction_resultat_ia THEN
    RAISE EXCEPTION 'Écriture directe du verdict justificatif interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_rib_change THEN
    IF NEW.rib_ia_resultat IS NOT NULL OR NEW.rib_ia_coherent IS NOT NULL
       OR NEW.rib_ia_verifie_le IS NOT NULL OR NEW.iban_last4 IS NOT NULL THEN
      RAISE EXCEPTION 'Révocation RIB non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.rib_ia_resultat IS DISTINCT FROM OLD.rib_ia_resultat
     OR NEW.rib_ia_coherent IS DISTINCT FROM OLD.rib_ia_coherent
     OR NEW.rib_ia_verifie_le IS DISTINCT FROM OLD.rib_ia_verifie_le
     OR NEW.iban_last4 IS DISTINCT FROM OLD.iban_last4 THEN
    RAISE EXCEPTION 'Écriture directe du verdict RIB interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_contrat_change THEN
    IF NEW.contrat_valide IS DISTINCT FROM false
       OR NEW.contrat_ia_resultat IS NOT NULL OR NEW.contrat_ia_coherent IS NOT NULL
       OR NEW.contrat_ia_verifie_le IS NOT NULL
       OR NEW.contrat_uploade_le IS DISTINCT FROM (CASE
         WHEN NEW.contrat_url IS NULL THEN NULL
         ELSE transaction_timestamp()
       END) THEN
      RAISE EXCEPTION 'Révocation contrat non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.contrat_valide IS DISTINCT FROM OLD.contrat_valide
     OR NEW.contrat_ia_resultat IS DISTINCT FROM OLD.contrat_ia_resultat
     OR NEW.contrat_ia_coherent IS DISTINCT FROM OLD.contrat_ia_coherent
     OR NEW.contrat_ia_verifie_le IS DISTINCT FROM OLD.contrat_ia_verifie_le
     OR NEW.contrat_uploade_le IS DISTINCT FROM OLD.contrat_uploade_le THEN
    RAISE EXCEPTION 'Écriture directe du verdict contrat interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_finess_change THEN
    IF NEW.finess_verifie IS DISTINCT FROM false OR NEW.finess_verifie_le IS NOT NULL
       OR NEW.finess_raison_sociale IS NOT NULL OR NEW.finess_categorie IS NOT NULL
       OR NEW.finess_secteur IS NOT NULL OR NEW.finess_est_public IS NOT NULL THEN
      RAISE EXCEPTION 'Révocation FINESS non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.finess_verifie IS DISTINCT FROM OLD.finess_verifie
     OR NEW.finess_verifie_le IS DISTINCT FROM OLD.finess_verifie_le
     OR NEW.finess_raison_sociale IS DISTINCT FROM OLD.finess_raison_sociale
     OR NEW.finess_categorie IS DISTINCT FROM OLD.finess_categorie
     OR NEW.finess_secteur IS DISTINCT FROM OLD.finess_secteur
     OR NEW.finess_est_public IS DISTINCT FROM OLD.finess_est_public THEN
    RAISE EXCEPTION 'Écriture directe du verdict FINESS interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_siret_change THEN
    IF NEW.siret_verifie IS DISTINCT FROM false OR NEW.siret_verifie_le IS NOT NULL
       OR NEW.siret_raison_sociale IS NOT NULL OR NEW.siret_categorie_juridique IS NOT NULL
       OR NEW.siret_code_naf IS NOT NULL OR NEW.siret_est_actif IS NOT NULL
       OR NEW.dirigeants IS NOT NULL THEN
      RAISE EXCEPTION 'Révocation SIRET non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.siret_verifie IS DISTINCT FROM OLD.siret_verifie
     OR NEW.siret_verifie_le IS DISTINCT FROM OLD.siret_verifie_le
     OR NEW.siret_raison_sociale IS DISTINCT FROM OLD.siret_raison_sociale
     OR NEW.siret_categorie_juridique IS DISTINCT FROM OLD.siret_categorie_juridique
     OR NEW.siret_code_naf IS DISTINCT FROM OLD.siret_code_naf
     OR NEW.siret_est_actif IS DISTINCT FROM OLD.siret_est_actif
     OR NEW.dirigeants IS DISTINCT FROM OLD.dirigeants THEN
    RAISE EXCEPTION 'Écriture directe du verdict SIRET interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_siret_change OR NEW.nom IS DISTINCT FROM OLD.nom THEN
    IF NEW.coherence_identite IS NOT NULL THEN
      RAISE EXCEPTION 'Révocation de cohérence identité non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.coherence_identite IS DISTINCT FROM OLD.coherence_identite THEN
    RAISE EXCEPTION 'Écriture directe de la cohérence identité interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Une mise à jour de rattachement par la RPC publique est admise seulement
  -- si elle reproduit exactement le calcul serveur et l'horodatage de la
  -- transaction. Une valeur arbitraire envoyée via PostgREST ne peut donc pas
  -- promouvoir le dossier.
  IF NEW.representant_identite_verifiee IS TRUE
     AND NULLIF(btrim(NEW.representant_nom), '') IS NOT NULL
     AND jsonb_typeof(NEW.dirigeants) = 'array' THEN
    SELECT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(NEW.dirigeants) AS d
      WHERE public.fn_normaliser_nom(d->>'type_dirigeant') LIKE '%physique%'
        AND public.fn_normaliser_nom(d->>'nom') = public.fn_normaliser_nom(NEW.representant_nom)
        AND NULLIF(public.fn_normaliser_nom(NEW.representant_prenom), '') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM unnest(regexp_split_to_array(public.fn_normaliser_nom(NEW.representant_prenom), ' +')) AS attendu(prenom)
          WHERE attendu.prenom <> ''
            AND NOT (
              attendu.prenom = ANY (
                regexp_split_to_array(public.fn_normaliser_nom(d->>'prenoms'), ' +')
              )
            )
        )
    ) INTO v_match_dirigeant;
  END IF;
  IF v_match_dirigeant THEN
    v_rattachement_attendu := true;
    v_methode_attendue := 'AUTO_DIRIGEANT';
  ELSIF NEW.representant_identite_verifiee IS TRUE
        AND NEW.justificatif_fonction_verifie IS TRUE THEN
    v_rattachement_attendu := true;
    v_methode_attendue := 'JUSTIFICATIF';
  END IF;

  v_rattachement_invalide := v_identite_changee OR v_justificatif_change
    OR v_siret_change
    OR NEW.representant_identite_verifiee IS DISTINCT FROM OLD.representant_identite_verifiee
    OR NEW.justificatif_fonction_verifie IS DISTINCT FROM OLD.justificatif_fonction_verifie
    OR NEW.dirigeants IS DISTINCT FROM OLD.dirigeants;

  IF NEW.rattachement_verifie IS DISTINCT FROM OLD.rattachement_verifie
     OR NEW.rattachement_verifie_le IS DISTINCT FROM OLD.rattachement_verifie_le
     OR NEW.rattachement_methode IS DISTINCT FROM OLD.rattachement_methode THEN
    IF v_rattachement_invalide THEN
      IF NEW.rattachement_verifie IS DISTINCT FROM false
         OR NEW.rattachement_verifie_le IS NOT NULL
         OR NEW.rattachement_methode IS DISTINCT FROM 'ADMIN' THEN
        RAISE EXCEPTION 'Révocation de rattachement non canonique'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    ELSE
      IF NEW.rattachement_verifie IS DISTINCT FROM v_rattachement_attendu
         OR NEW.rattachement_methode IS DISTINCT FROM v_methode_attendue
         OR NEW.rattachement_verifie_le IS DISTINCT FROM (CASE
           WHEN v_rattachement_attendu THEN transaction_timestamp()
           ELSE NULL
         END) THEN
        RAISE EXCEPTION 'Transition de rattachement non calculée depuis les sources'
          USING ERRCODE = 'insufficient_privilege';
      END IF;
    END IF;
  END IF;

  -- L'état du contrat de service vient exclusivement de la ligne de signature
  -- active. La signature/révocation fonctionne sans GUC de contournement.
  SELECT signed_at INTO v_signature_active_le
  FROM public.contrats_service_signatures
  WHERE etablissement_id = NEW.id AND revoked_at IS NULL
  LIMIT 1;
  v_signature_transition :=
    NEW.contrat_service_signe IS DISTINCT FROM OLD.contrat_service_signe
    OR NEW.contrat_service_signe_le IS DISTINCT FROM OLD.contrat_service_signe_le;
  IF v_signature_transition AND (
    NEW.contrat_service_signe IS DISTINCT FROM (v_signature_active_le IS NOT NULL)
    OR NEW.contrat_service_signe_le IS DISTINCT FROM v_signature_active_le
  ) THEN
    RAISE EXCEPTION 'État du contrat de service sans preuve active'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  v_revocation_globale := v_source_changee
    OR (v_signature_transition
      AND OLD.contrat_service_signe IS TRUE
      AND NEW.contrat_service_signe IS FALSE)
    OR (
      OLD.statut_verification = 'VERIFIE'
      AND NOT (
        NEW.siret_verifie IS TRUE
        AND NEW.finess_verifie IS TRUE
        AND NEW.representant_identite_verifiee IS TRUE
        AND NEW.rattachement_verifie IS TRUE
        AND NEW.contrat_service_signe IS TRUE
      )
      AND NEW.statut_verification = 'EN_COURS'
      AND NEW.peut_publier_missions IS FALSE
    );
  IF v_revocation_globale THEN
    IF NEW.peut_publier_missions IS DISTINCT FROM false
       OR NEW.statut_verification IS DISTINCT FROM (CASE
         WHEN v_source_changee
              AND OLD.statut_verification IN ('VERIFIE', 'REJETE') THEN 'EN_COURS'
         WHEN NOT v_source_changee
              AND OLD.statut_verification = 'VERIFIE' THEN 'EN_COURS'
         ELSE OLD.statut_verification
       END)
       OR NEW.verifie_le IS NOT NULL OR NEW.verifie_par IS NOT NULL
       OR NEW.motif_rejet IS DISTINCT FROM (CASE
         WHEN v_source_changee AND OLD.statut_verification = 'REJETE' THEN NULL
         ELSE OLD.motif_rejet
       END) THEN
      RAISE EXCEPTION 'Révocation globale non canonique'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  ELSIF NEW.statut_verification IS DISTINCT FROM OLD.statut_verification
     OR NEW.peut_publier_missions IS DISTINCT FROM OLD.peut_publier_missions
     OR NEW.verifie_le IS DISTINCT FROM OLD.verifie_le
     OR NEW.verifie_par IS DISTINCT FROM OLD.verifie_par
     OR NEW.motif_rejet IS DISTINCT FROM OLD.motif_rejet THEN
    RAISE EXCEPTION 'Écriture directe du statut de vérification interdite'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Compatibilité avec les anciennes fonctions internes commerciales. Ce
  -- marqueur est évalué seulement après tous les contrôles de conformité.
  v_is_internal := COALESCE(current_setting('app.internal_operation', true), '') = 'true';
  IF v_is_internal THEN
    RETURN NEW;
  END IF;

  IF NEW.taux_commission_negocie IS DISTINCT FROM OLD.taux_commission_negocie THEN RAISE EXCEPTION 'Modification du taux de commission non autorisée'; END IF;
  IF NEW.stripe_customer_id IS DISTINCT FROM OLD.stripe_customer_id THEN RAISE EXCEPTION 'Modification du Stripe ID non autorisée'; END IF;
  IF NEW.palier_commission_id IS DISTINCT FROM OLD.palier_commission_id THEN RAISE EXCEPTION 'Modification du palier non autorisée'; END IF;
  IF NEW.formule_abonnement IS DISTINCT FROM OLD.formule_abonnement THEN RAISE EXCEPTION 'Modification de la formule non autorisée'; END IF;
  IF NEW.mode_facturation IS DISTINCT FROM OLD.mode_facturation THEN RAISE EXCEPTION 'Modification du mode de facturation non autorisée'; END IF;
  IF NEW.chorus_pro_actif IS DISTINCT FROM OLD.chorus_pro_actif THEN RAISE EXCEPTION 'Modification Chorus Pro non autorisée'; END IF;
  IF NEW.chorus_pro_identifiant IS DISTINCT FROM OLD.chorus_pro_identifiant THEN RAISE EXCEPTION 'Modification Chorus Pro non autorisée'; END IF;
  IF NEW.delai_paiement_jours IS DISTINCT FROM OLD.delai_paiement_jours THEN RAISE EXCEPTION 'Modification du délai non autorisée'; END IF;
  IF NEW.missions_mois_precedent IS DISTINCT FROM OLD.missions_mois_precedent THEN RAISE EXCEPTION 'Modification compteur non autorisée'; END IF;
  IF NEW.palier_recalcule_le IS DISTINCT FROM OLD.palier_recalcule_le THEN RAISE EXCEPTION 'Modification date recalcul non autorisée'; END IF;
  IF NEW.groupe_sante_id IS DISTINCT FROM OLD.groupe_sante_id THEN RAISE EXCEPTION 'Modification du groupe non autorisée'; END IF;
  IF NEW.note_moyenne IS DISTINCT FROM OLD.note_moyenne THEN RAISE EXCEPTION 'Modification de la note non autorisée'; END IF;
  IF NEW.est_secteur_public IS DISTINCT FROM OLD.est_secteur_public THEN RAISE EXCEPTION 'Modification du secteur public non autorisée'; END IF;
  IF NEW.mode_paiement_commission IS DISTINCT FROM OLD.mode_paiement_commission THEN RAISE EXCEPTION 'Modification du mode de paiement non autorisée'; END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_etablissement_commercial"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_etablissement_storage_paths"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR public.est_admin() THEN RETURN NEW; END IF;
  IF NOT public.fn_a_permission_etablissement('profil_etab', NEW.id) THEN
    RAISE EXCEPTION 'Permission profil etablissement requise' USING ERRCODE = '42501';
  END IF;

  IF NEW.rib_s3_key IS DISTINCT FROM OLD.rib_s3_key
     AND NEW.rib_s3_key IS NOT NULL
     AND NEW.rib_s3_key NOT LIKE NEW.id::text || '/%' THEN
    RAISE EXCEPTION 'Chemin RIB non autorise' USING ERRCODE = '42501';
  END IF;
  IF NEW.representant_piece_s3_key IS DISTINCT FROM OLD.representant_piece_s3_key
     AND NEW.representant_piece_s3_key IS NOT NULL
     AND NEW.representant_piece_s3_key NOT LIKE NEW.id::text || '/%' THEN
    RAISE EXCEPTION 'Chemin piece identite non autorise' USING ERRCODE = '42501';
  END IF;
  IF NEW.justificatif_fonction_s3_key IS DISTINCT FROM OLD.justificatif_fonction_s3_key
     AND NEW.justificatif_fonction_s3_key IS NOT NULL
     AND NEW.justificatif_fonction_s3_key NOT LIKE NEW.id::text || '/%' THEN
    RAISE EXCEPTION 'Chemin justificatif non autorise' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_protect_etablissement_storage_paths"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_protect_facture_honoraire_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(current_setting('request.jwt.claim.role', true) = 'service_role', auth.uid() IS NULL) THEN
    RETURN NEW;
  END IF;
  IF est_admin() THEN RETURN NEW; END IF;
  IF OLD.statut = 'BROUILLON' THEN RETURN NEW; END IF;

  IF NEW.montant_ht IS DISTINCT FROM OLD.montant_ht THEN
    RAISE EXCEPTION 'Facture honoraire émise : montant_ht verrouillé';
  END IF;
  IF NEW.montant_ttc IS DISTINCT FROM OLD.montant_ttc THEN
    RAISE EXCEPTION 'Facture honoraire émise : montant_ttc verrouillé';
  END IF;
  IF NEW.montant_tva IS DISTINCT FROM OLD.montant_tva THEN
    RAISE EXCEPTION 'Facture honoraire émise : montant_tva verrouillé';
  END IF;
  IF NEW.taux_tva IS DISTINCT FROM OLD.taux_tva THEN
    RAISE EXCEPTION 'Facture honoraire émise : taux_tva verrouillé';
  END IF;
  IF NEW.numero_facture IS DISTINCT FROM OLD.numero_facture THEN
    RAISE EXCEPTION 'Facture honoraire émise : numero_facture verrouillé';
  END IF;
  IF NEW.soignant_id IS DISTINCT FROM OLD.soignant_id THEN
    RAISE EXCEPTION 'Facture honoraire émise : soignant_id verrouillé';
  END IF;
  IF NEW.etablissement_id IS DISTINCT FROM OLD.etablissement_id THEN
    RAISE EXCEPTION 'Facture honoraire émise : etablissement_id verrouillé';
  END IF;
  IF NEW.mission_id IS DISTINCT FROM OLD.mission_id THEN
    RAISE EXCEPTION 'Facture honoraire émise : mission_id verrouillé';
  END IF;
  IF NEW.date_emission IS DISTINCT FROM OLD.date_emission THEN
    RAISE EXCEPTION 'Facture honoraire émise : date_emission verrouillée';
  END IF;
  IF NEW.type_document IS DISTINCT FROM OLD.type_document THEN
    RAISE EXCEPTION 'Facture honoraire émise : type_document verrouillé';
  END IF;
  IF NEW.facture_precedente_id IS DISTINCT FROM OLD.facture_precedente_id THEN
    RAISE EXCEPTION 'Facture honoraire émise : facture_precedente_id verrouillé';
  END IF;

  RETURN NEW;
END;
$$;


