CREATE OR REPLACE FUNCTION "public"."fn_proteger_document_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text := COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', true), ''),
    auth.jwt() ->> 'role',
    ''
  );
BEGIN
  IF v_role = 'service_role'
     OR auth.uid() IS NULL
     OR COALESCE(current_setting('jolene.system_update', true), '') = 'true'
     OR COALESCE(current_setting('jolene.document_server_update', true), '') = 'true'
     OR COALESCE(current_setting('jolene.document_moderation_rpc', true), '') = 'true' THEN
    RETURN NEW;
  END IF;

  IF NEW.statut_verification IS DISTINCT FROM OLD.statut_verification
     OR NEW.verifie_par IS DISTINCT FROM OLD.verifie_par
     OR NEW.verifie_le IS DISTINCT FROM OLD.verifie_le
     OR NEW.valide_depuis IS DISTINCT FROM OLD.valide_depuis
     OR NEW.valide_jusqua IS DISTINCT FROM OLD.valide_jusqua
     OR NEW.motif_rejet IS DISTINCT FROM OLD.motif_rejet
     OR NEW.est_critique IS DISTINCT FROM OLD.est_critique
     OR NEW.resultat_ia IS DISTINCT FROM OLD.resultat_ia
     OR NEW.score_confiance_ia IS DISTINCT FROM OLD.score_confiance_ia
     OR NEW.nom_extrait_ia IS DISTINCT FROM OLD.nom_extrait_ia
     OR NEW.prenom_extrait_ia IS DISTINCT FROM OLD.prenom_extrait_ia
     OR NEW.coherence_nom IS DISTINCT FROM OLD.coherence_nom
     OR NEW.verification_attempt_id IS DISTINCT FROM OLD.verification_attempt_id THEN
    RAISE EXCEPTION 'Les champs de vérification documentaire ne sont modifiables que par le parcours sécurisé'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.soignant_id IS DISTINCT FROM OLD.soignant_id THEN
    RAISE EXCEPTION 'Modification du propriétaire interdite'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_proteger_document_verification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_proteger_ecriture_document_soignant"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF auth.role() = 'service_role' OR v_uid IS NULL OR public.est_admin() THEN
    RETURN NEW;
  END IF;
  IF COALESCE(current_setting('jolene.document_server_update', true), '') = 'true' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.soignant_id IS DISTINCT FROM v_uid THEN
      RAISE EXCEPTION 'Propriétaire de document invalide' USING ERRCODE = '42501';
    END IF;
    IF NEW.s3_bucket IS DISTINCT FROM 'jolene-documents'
       OR NEW.s3_cle NOT LIKE v_uid::text || '/documents/%'
       OR NEW.s3_cle LIKE '%..%' THEN
      RAISE EXCEPTION 'Chemin de document invalide' USING ERRCODE = '42501';
    END IF;
    NEW.statut_verification := 'EN_ATTENTE';
    NEW.verifie_par := NULL;
    NEW.verifie_le := NULL;
    NEW.motif_rejet := NULL;
    NEW.valide_depuis := NULL;
    NEW.valide_jusqua := NULL;
    NEW.resultat_ia := NULL;
    NEW.nom_extrait_ia := NULL;
    NEW.prenom_extrait_ia := NULL;
    NEW.coherence_nom := NULL;
    NEW.score_confiance_ia := NULL;
    SELECT COALESCE(bool_or(est_critique), false) INTO NEW.est_critique
    FROM public.documents_requis_par_profession drp
    JOIN public.soignants s ON s.id = v_uid AND s.profession = drp.profession
    WHERE drp.type_document = NEW.type_document;
    RETURN NEW;
  END IF;

  IF NEW.soignant_id IS DISTINCT FROM OLD.soignant_id
     OR NEW.type_document IS DISTINCT FROM OLD.type_document
     OR NEW.s3_bucket IS DISTINCT FROM OLD.s3_bucket
     OR NEW.s3_cle IS DISTINCT FROM OLD.s3_cle
     OR NEW.s3_version_id IS DISTINCT FROM OLD.s3_version_id
     OR NEW.nom_fichier IS DISTINCT FROM OLD.nom_fichier
     OR NEW.type_mime IS DISTINCT FROM OLD.type_mime
     OR NEW.taille_octets IS DISTINCT FROM OLD.taille_octets
     OR NEW.valide_depuis IS DISTINCT FROM OLD.valide_depuis
     OR NEW.valide_jusqua IS DISTINCT FROM OLD.valide_jusqua
     OR NEW.statut_verification IS DISTINCT FROM OLD.statut_verification
     OR NEW.verifie_par IS DISTINCT FROM OLD.verifie_par
     OR NEW.verifie_le IS DISTINCT FROM OLD.verifie_le
     OR NEW.motif_rejet IS DISTINCT FROM OLD.motif_rejet
     OR NEW.est_critique IS DISTINCT FROM OLD.est_critique
     OR NEW.resultat_ia IS DISTINCT FROM OLD.resultat_ia
     OR NEW.nom_extrait_ia IS DISTINCT FROM OLD.nom_extrait_ia
     OR NEW.prenom_extrait_ia IS DISTINCT FROM OLD.prenom_extrait_ia
     OR NEW.coherence_nom IS DISTINCT FROM OLD.coherence_nom
     OR NEW.score_confiance_ia IS DISTINCT FROM OLD.score_confiance_ia THEN
    RAISE EXCEPTION 'Modification de preuve ou de validation interdite' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_proteger_ecriture_document_soignant"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_proteger_heures_externes_soignants"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF COALESCE(
       current_setting('jolene.heures_externes_server_update', true), ''
     ) IS DISTINCT FROM 'true' THEN
    RAISE EXCEPTION 'Écriture directe des heures externes interdite'
      USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'UPDATE' AND (
       NEW.soignant_id IS DISTINCT FROM OLD.soignant_id
    OR NEW.etablissement_nom IS DISTINCT FROM OLD.etablissement_nom
    OR NEW.etablissement_type IS DISTINCT FROM OLD.etablissement_type
    OR NEW.date_debut IS DISTINCT FROM OLD.date_debut
    OR NEW.date_fin IS DISTINCT FROM OLD.date_fin
    OR NEW.heures_declarees IS DISTINCT FROM OLD.heures_declarees
    OR NEW.attestation_url IS DISTINCT FROM OLD.attestation_url
    OR NEW.attestation_nom_fichier IS DISTINCT FROM OLD.attestation_nom_fichier
  ) THEN
    NEW.version_source := gen_random_uuid();
    NEW.statut_validation := 'EN_ATTENTE';
    NEW.commentaire_validation := NULL;
    NEW.valide_par := NULL;
    NEW.valide_le := NULL;
    NEW.heures_extraites_ia := NULL;
    NEW.resultat_ia := NULL;
    NEW.coherence_ia := NULL;
    NEW.verifie_ia_le := NULL;
    NEW.empreinte_preuve_sha256 := NULL;
    NEW.source_validation_serveur := NULL;
    NEW.empreinte_snapshot_source := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_proteger_heures_externes_soignants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_proteger_provenance_iban_soignant"() RETURNS "trigger"
