  v_jours numeric := public.fn_param_num('notation_publication_jours', 7);
  v_count int;
BEGIN
  UPDATE notations_missions
  SET publie_le = NOW()
  WHERE publie_le IS NULL
    AND cree_le + make_interval(days => v_jours::int) < NOW();
