CREATE OR REPLACE FUNCTION "public"."fn_rebooker_soignant"("p_soignant_id" "uuid", "p_mission_modele_id" "uuid", "p_debut" timestamp with time zone, "p_fin" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m record;
  v_s record;
  v_new_id uuid;
  v_resolution jsonb;
BEGIN
  SELECT * INTO v_m FROM public.missions WHERE id = p_mission_modele_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Mission modèle introuvable'); END IF;
  IF v_m.etablissement_id <> public.mon_etablissement_id() AND NOT public.est_admin() THEN
    RETURN jsonb_build_object('error', 'Non autorisé');
  END IF;
  IF p_debut IS NULL OR p_fin IS NULL OR p_fin <= p_debut OR p_debut < now() THEN
    RETURN jsonb_build_object('error', 'Dates invalides (le début doit être dans le futur).');
  END IF;
  SELECT * INTO v_s FROM public.soignants WHERE id = p_soignant_id AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Soignant introuvable'); END IF;
  IF NOT public.fn_soignant_compatible_mission(
    v_s.profession, v_s.specialite_medicale,
    v_m.profession_requise, v_m.specialite_medicale_requise,
    COALESCE(v_m.accepte_non_specialises, true)
  ) THEN
    RETURN jsonb_build_object('error', 'Le soignant n’est pas compatible avec la profession requise par la mission modèle.');
  END IF;
  IF public.fn_est_exclu(p_soignant_id, v_m.etablissement_id) THEN
    RETURN jsonb_build_object('error', 'Ce soignant est dans votre liste d’exclusions.');
  END IF;
  v_resolution := public.fn_resoudre_contrat_mission(
    p_mission_modele_id, p_soignant_id, NULL
  );
  IF COALESCE((v_resolution->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE((v_resolution->>'choix_requis')::boolean, false) IS NOT TRUE THEN
    RETURN v_resolution - 'ok';
  END IF;

  INSERT INTO public.missions(
    etablissement_id, intitule, description, service,
    profession_requise, specialite_medicale_requise, accepte_non_specialises,
    debut_le, fin_le, duree_heures, taux_horaire_base,
    type_contrat_recherche, statut, mode_attribution, est_urgente,
    garantie_remplacement, mission_source
  ) VALUES (
    v_m.etablissement_id, v_m.intitule, v_m.description, v_m.service,
    v_m.profession_requise, v_m.specialite_medicale_requise, v_m.accepte_non_specialises,
    p_debut, p_fin, round(extract(epoch FROM (p_fin - p_debut)) / 3600.0, 2),
    v_m.taux_horaire_base, v_m.type_contrat_recherche, 'OUVERTE', 'CANDIDATURE',
    false, COALESCE(v_m.garantie_remplacement, false), 'REBOOK'
  ) RETURNING id INTO v_new_id;

  INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
  VALUES (
    p_soignant_id, 'CANDIDATURE_PROPOSEE', 'Un établissement veut retravailler avec vous ⭐',
    public.fn_html_escape(v_m.intitule) || ' du ' ||
      to_char(p_debut AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24:MI') || ' au ' ||
      to_char(p_fin AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24:MI') || ' à ' ||
      COALESCE(v_m.taux_horaire_base::text, '?') || ' €/h — vous êtes leur premier choix, postulez en 1 clic.',
    '/soignant/missions/' || v_new_id, 'SOIGNANT'
  );
  RETURN jsonb_build_object('success', true, 'mission_id', v_new_id);
END;
$$;


ALTER FUNCTION "public"."fn_rebooker_soignant"("p_soignant_id" "uuid", "p_mission_modele_id" "uuid", "p_debut" timestamp with time zone, "p_fin" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalculer_commissions_post_litige"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission            RECORD;
  v_new_brut           NUMERIC(12,2);
  v_new_commission_ht  NUMERIC(12,2);
  v_new_commission_tva NUMERIC(12,2);
  v_new_commission_ttc NUMERIC(12,2);
  v_delta_ht           NUMERIC(12,2);
  v_delta_tva          NUMERIC(12,2);
  v_delta_ttc          NUMERIC(12,2);
  v_doc_number         TEXT;
  v_doc_type           TEXT;
  v_processed_unbilled INT := 0;
  v_avoirs_emis        INT := 0;
  v_fc_emises          INT := 0;
  v_notifs_envoyees    INT := 0;
  v_mission_intitule   TEXT;
  v_litige_id          UUID;
BEGIN
  FOR v_mission IN
    SELECT id, taux_commission, facture_id, commission_facturee,
           montant_commission_ht, etablissement_id, intitule
      FROM public.missions
     WHERE commission_a_recalculer = TRUE
  LOOP
    SELECT COALESCE(SUM(fh.montant_signe), 0) INTO v_new_brut
      FROM public.factures_honoraires fh
     WHERE fh.mission_id = v_mission.id
       AND fh.statut NOT IN ('ANNULEE', 'REMPLACEE')
       AND fh.statut_litige <> 'EN_ATTENTE_LITIGE';

    v_new_commission_ht  := ROUND(v_new_brut * COALESCE(v_mission.taux_commission, 15) / 100.0, 2);
    v_new_commission_tva := ROUND(v_new_commission_ht * 0.20, 2);
    v_new_commission_ttc := v_new_commission_ht + v_new_commission_tva;

    IF v_mission.facture_id IS NULL
       AND COALESCE(v_mission.commission_facturee, FALSE) = FALSE THEN
      UPDATE public.missions
         SET montant_commission_ht  = v_new_commission_ht,
             montant_commission_tva = v_new_commission_tva,
             montant_commission_ttc = v_new_commission_ttc,
             commission_a_recalculer = FALSE
       WHERE id = v_mission.id;
      v_processed_unbilled := v_processed_unbilled + 1;
      CONTINUE;
    END IF;

    v_delta_ht := COALESCE(v_mission.montant_commission_ht, 0) - v_new_commission_ht;

    IF v_delta_ht = 0 THEN
      UPDATE public.missions SET commission_a_recalculer = FALSE
       WHERE id = v_mission.id;
      v_processed_unbilled := v_processed_unbilled + 1;
      CONTINUE;
    END IF;

    v_delta_tva := ROUND(abs(v_delta_ht) * 0.20, 2);
    v_delta_ttc := abs(v_delta_ht) + v_delta_tva;

    IF v_delta_ht > 0 THEN
      v_doc_number := public.next_avoir_commission_number(v_mission.etablissement_id);
      v_doc_type := 'AVOIR';
      INSERT INTO public.factures (
        etablissement_id, numero_facture, type_document, facture_precedente_id,
        montant_ht, montant_tva, montant_ttc, nombre_missions,
        statut, date_emission, date_echeance, periode_debut, periode_fin
      ) VALUES (
        v_mission.etablissement_id, v_doc_number, 'AVOIR', v_mission.facture_id,
        v_delta_ht, v_delta_tva, v_delta_ttc, 1,
        'EMISE', now(), (now() + INTERVAL '30 days')::date,
        date_trunc('month', now())::date,
        (date_trunc('month', now()) + INTERVAL '1 month' - INTERVAL '1 day')::date
      );
      v_avoirs_emis := v_avoirs_emis + 1;
    ELSE
      v_doc_number := public.next_facture_complementaire_number(v_mission.etablissement_id);
      v_doc_type := 'FACTURE_COMPLEMENTAIRE';
      INSERT INTO public.factures (
        etablissement_id, numero_facture, type_document, facture_precedente_id,
        montant_ht, montant_tva, montant_ttc, nombre_missions,
        statut, date_emission, date_echeance, periode_debut, periode_fin
      ) VALUES (
        v_mission.etablissement_id, v_doc_number, 'FACTURE_COMPLEMENTAIRE',
        v_mission.facture_id,
        abs(v_delta_ht), v_delta_tva, v_delta_ttc, 1,
        'EMISE', now(), (now() + INTERVAL '30 days')::date,
        date_trunc('month', now())::date,
        (date_trunc('month', now()) + INTERVAL '1 month' - INTERVAL '1 day')::date
      );
      v_fc_emises := v_fc_emises + 1;
    END IF;

    UPDATE public.missions
       SET montant_commission_ht  = v_new_commission_ht,
           montant_commission_tva = v_new_commission_tva,
           montant_commission_ttc = v_new_commission_ttc,
           commission_a_recalculer = FALSE
     WHERE id = v_mission.id;

    SELECT DISTINCT fh.litige_id INTO v_litige_id
      FROM public.factures_honoraires fh
     WHERE fh.mission_id = v_mission.id
       AND fh.litige_id IS NOT NULL
     ORDER BY fh.litige_id
     LIMIT 1;

    v_mission_intitule := COALESCE(v_mission.intitule, 'Mission #' || v_mission.id::text);

    PERFORM public.fn_litige_push_notification(
      v_mission.etablissement_id,
      'ETABLISSEMENT',
      'COMMISSION_AJUSTEE',
      CASE WHEN v_doc_type = 'AVOIR'
        THEN 'Avoir commission ' || v_doc_number || ' émis'
        ELSE 'Facture complémentaire ' || v_doc_number || ' émise'
      END,
      CASE WHEN v_doc_type = 'AVOIR'
        THEN 'Un avoir de ' || v_delta_ttc || ' € a été émis sur la commission de la mission "' || v_mission_intitule || '". Déduit de votre prochaine facture mensuelle.'
        ELSE 'Une facture complémentaire de ' || v_delta_ttc || ' € a été émise sur la commission de la mission "' || v_mission_intitule || '". Due aux conditions habituelles.'
      END,
      v_litige_id,
      jsonb_build_object(
        'type_document', v_doc_type,
        'numero_document', v_doc_number,
        'montant', v_delta_ttc,
        'mission_id', v_mission.id,
        'mission_intitule', v_mission_intitule,
        'etablissement_id', v_mission.etablissement_id
      )
    );
    v_notifs_envoyees := v_notifs_envoyees + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'processed_unbilled', v_processed_unbilled,
    'deferred_to_fix9_billed', 0,
    'avoirs_commission_emis', v_avoirs_emis,
    'factures_complementaires_emises', v_fc_emises,
    'notifications_envoyees', v_notifs_envoyees
  );
END;
$$;


ALTER FUNCTION "public"."fn_recalculer_commissions_post_litige"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_recalculer_commissions_post_litige"() IS 'CP-LITIGES-7a FIX 8+9+Bloc4 — recalcule les commissions Jolene post-litige. Non facturées : MAJ directe. Déjà facturées : AVOIR ou FACTURE_COMPLEMENTAIRE selon delta, avec push COMMISSION_AJUSTEE à tous les représentants légaux de l''étab. Appelée AVANT fn_auto_facturation_mensuelle.';



CREATE OR REPLACE FUNCTION "public"."fn_recalculer_palier_commission"("p_etablissement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_count INTEGER; v_groupe_id UUID; v_palier RECORD;
    v_ancien_taux NUMERIC; v_nouveau_taux NUMERIC; v_remise_groupe NUMERIC := 0;
BEGIN
    SELECT COALESCE(taux_commission_negocie, 15.00) INTO v_ancien_taux FROM etablissements WHERE id = p_etablissement_id;
    SELECT groupe_sante_id INTO v_groupe_id FROM etablissements WHERE id = p_etablissement_id;

    IF v_groupe_id IS NOT NULL THEN
        SELECT COALESCE(remise_groupe_pourcent, 0) INTO v_remise_groupe FROM groupes_sante WHERE id = v_groupe_id;
        SELECT COUNT(*) INTO v_count FROM missions m JOIN etablissements e ON e.id = m.etablissement_id
        WHERE e.groupe_sante_id = v_groupe_id AND m.statut = 'TERMINEE'
          AND m.fin_le >= date_trunc('month', NOW()) - INTERVAL '1 month' AND m.fin_le < date_trunc('month', NOW());
    ELSE
        SELECT COUNT(*) INTO v_count FROM missions m
        WHERE m.etablissement_id = p_etablissement_id AND m.statut = 'TERMINEE'
          AND m.fin_le >= date_trunc('month', NOW()) - INTERVAL '1 month' AND m.fin_le < date_trunc('month', NOW());
    END IF;

    SELECT * INTO v_palier FROM paliers_commission
    WHERE est_actif = TRUE AND missions_min <= v_count AND (missions_max IS NULL OR missions_max >= v_count)
    ORDER BY ordre DESC LIMIT 1;

    IF FOUND AND v_palier.id IS NOT NULL THEN
        v_nouveau_taux := GREATEST(5.00, v_palier.taux_commission - v_remise_groupe);

        -- Bypass trigger fn_protect_etablissement_commercial via session GUC
        -- (l'ancienne version utilisait ALTER TABLE DISABLE TRIGGER mais
        -- celui-ci provoque "cannot ALTER TABLE because it is being used
        -- by active queries" quand on est dans une boucle qui scanne la
        -- même table — cas de fn_recalculer_tous_paliers).
        PERFORM set_config('app.internal_operation', 'true', true);

        UPDATE etablissements SET taux_commission_negocie = v_nouveau_taux, palier_commission_id = v_palier.id,
            missions_mois_precedent = v_count, palier_recalcule_le = CURRENT_DATE, modifie_le = NOW()
        WHERE id = p_etablissement_id;

        IF v_groupe_id IS NOT NULL THEN
            UPDATE etablissements SET taux_commission_negocie = v_nouveau_taux, palier_commission_id = v_palier.id,
                missions_mois_precedent = v_count, palier_recalcule_le = CURRENT_DATE, modifie_le = NOW()
            WHERE groupe_sante_id = v_groupe_id;
        END IF;

        PERFORM set_config('app.internal_operation', 'false', true);
    END IF;

    RETURN jsonb_build_object('etablissement_id', p_etablissement_id, 'missions_mois_precedent', v_count,
        'ancien_taux', v_ancien_taux, 'nouveau_taux', COALESCE(v_nouveau_taux, v_ancien_taux),
        'palier', COALESCE(v_palier.nom, 'Découverte'), 'remise_groupe', v_remise_groupe, 'groupe_cumul', v_groupe_id IS NOT NULL);
END;
$$;


ALTER FUNCTION "public"."fn_recalculer_palier_commission"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalculer_preuves_etudiant"("p_soignant_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_profession public.type_profession;
  v_scolarite_doc_id uuid;
  v_scolarite_formation text;
  v_scolarite_annee integer;
  v_scolarite_verifiee_le timestamptz;
  v_licence_doc_id uuid;
  v_licence_verifiee_le timestamptz;
  v_licence_valide_jusqua date;
  v_licence_specialite text;
  v_previous_system_update text := COALESCE(
    current_setting('jolene.system_update', true),
    ''
  );
BEGIN
  IF p_soignant_id IS NULL THEN
    RETURN;
  END IF;

  SELECT s.profession
  INTO v_profession
  FROM public.soignants s
  WHERE s.id = p_soignant_id
    AND s.supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT
    ds.id,
    x.formation,
    x.annee_validee,
    ds.verifie_le
  INTO
    v_scolarite_doc_id,
    v_scolarite_formation,
    v_scolarite_annee,
    v_scolarite_verifiee_le
  FROM public.documents_soignants ds
  CROSS JOIN LATERAL (
    SELECT
      upper(NULLIF(btrim(ds.resultat_ia->>'scolarite_formation'), '')) AS formation,
      CASE
        WHEN COALESCE(ds.resultat_ia->>'scolarite_annee_validee', '') ~ '^\d{1,2}$'
          THEN (ds.resultat_ia->>'scolarite_annee_validee')::integer
        ELSE NULL
      END AS annee_validee
  ) x
  WHERE ds.soignant_id = p_soignant_id
    AND ds.type_document = 'ATTESTATION_SCOLARITE'
    AND ds.statut_verification = 'VERIFIE'
    AND ds.supprime_le IS NULL
    AND ds.verifie_le IS NOT NULL
    AND ds.coherence_nom IS TRUE
    AND ds.valide_depuis IS NOT NULL
    AND ds.valide_depuis BETWEEN current_date - 400 AND current_date
    AND (ds.valide_jusqua IS NULL OR ds.valide_jusqua > current_date)
    AND COALESCE(ds.resultat_ia->>'verdict_serveur', '') = 'VERIFIE'
    AND COALESCE(ds.resultat_ia->>'type_correspond', 'false') = 'true'
    AND COALESCE(ds.resultat_ia->>'document_lisible', 'false') = 'true'
    AND COALESCE(ds.resultat_ia->>'document_complet', 'false') = 'true'
    AND x.formation = ANY (ARRAY[
      'IFSI', 'IFAS', 'MEDECINE_DFGSM', 'MEDECINE_DFASM', 'PHARMACIE',
      'MAIEUTIQUE', 'ODONTOLOGIE', 'KINE', 'ERGOTHERAPIE',
      'PSYCHOMOTRICITE', 'MANIP_RADIO'
    ])
    AND x.annee_validee BETWEEN 0 AND CASE x.formation
      WHEN 'IFSI' THEN 3
      WHEN 'IFAS' THEN 1
      WHEN 'MEDECINE_DFGSM' THEN 3
      WHEN 'MEDECINE_DFASM' THEN 3
      WHEN 'PHARMACIE' THEN 9
      WHEN 'MAIEUTIQUE' THEN 6
      WHEN 'ODONTOLOGIE' THEN 9
      WHEN 'KINE' THEN 5
      WHEN 'ERGOTHERAPIE' THEN 3
      WHEN 'PSYCHOMOTRICITE' THEN 3
      WHEN 'MANIP_RADIO' THEN 3
      ELSE -1
    END
    AND EXISTS (
      SELECT 1
      FROM public.fn_professions_autorisees_scolarite(
        x.formation,
        x.annee_validee
      ) AS autorisee(profession)
      WHERE autorisee.profession = v_profession
    )
  ORDER BY ds.valide_depuis DESC, ds.verifie_le DESC, ds.id DESC
  LIMIT 1;

  SELECT
    ds.id,
    ds.verifie_le,
    ds.valide_jusqua,
    left(btrim(ds.resultat_ia->>'licence_remplacement_specialite'), 200)
  INTO
    v_licence_doc_id,
    v_licence_verifiee_le,
    v_licence_valide_jusqua,
    v_licence_specialite
  FROM public.documents_soignants ds
  WHERE ds.soignant_id = p_soignant_id
    AND v_profession = 'MEDECIN'
    AND ds.type_document = 'LICENCE_REMPLACEMENT'
    AND ds.statut_verification = 'VERIFIE'
    AND ds.supprime_le IS NULL
    AND ds.verifie_le IS NOT NULL
    AND ds.coherence_nom IS TRUE
    AND ds.valide_depuis IS NOT NULL
    AND ds.valide_depuis <= current_date
    AND ds.valide_jusqua IS NOT NULL
    AND ds.valide_jusqua > current_date
    AND ds.valide_jusqua <= (ds.valide_depuis + interval '13 months')::date
    AND NULLIF(btrim(ds.resultat_ia->>'licence_remplacement_specialite'), '') IS NOT NULL
    AND COALESCE(ds.resultat_ia->>'verdict_serveur', '') = 'VERIFIE'
    AND COALESCE(ds.resultat_ia->>'type_correspond', 'false') = 'true'
    AND COALESCE(ds.resultat_ia->>'document_lisible', 'false') = 'true'
    AND COALESCE(ds.resultat_ia->>'document_complet', 'false') = 'true'
  ORDER BY ds.valide_jusqua DESC, ds.verifie_le DESC, ds.id DESC
  LIMIT 1;

  -- Le garde-fou de profil n'accepte ces champs serveur que pendant cette
  -- cascade bornée. La valeur est restaurée avant de rendre la main.
  PERFORM set_config('jolene.system_update', 'true', true);
  BEGIN
    UPDATE public.soignants s
    SET scolarite_formation = CASE
          WHEN v_scolarite_doc_id IS NOT NULL THEN v_scolarite_formation
          ELSE NULL
        END,
        scolarite_annee_validee = CASE
          WHEN v_scolarite_doc_id IS NOT NULL THEN v_scolarite_annee
          ELSE NULL
        END,
        scolarite_profession_autorisee = CASE
          WHEN v_scolarite_doc_id IS NOT NULL THEN v_profession
          ELSE NULL
        END,
        scolarite_verifiee = v_scolarite_doc_id IS NOT NULL,
        scolarite_verifiee_le = CASE
          WHEN v_scolarite_doc_id IS NOT NULL THEN v_scolarite_verifiee_le
          ELSE NULL
        END,
        licence_remplacement_verifiee = v_licence_doc_id IS NOT NULL,
        licence_remplacement_le = CASE
          WHEN v_licence_doc_id IS NOT NULL THEN v_licence_verifiee_le
          ELSE NULL
        END,
        licence_remplacement_valide_jusqua = CASE
          WHEN v_licence_doc_id IS NOT NULL THEN v_licence_valide_jusqua
          ELSE NULL
        END,
        licence_remplacement_specialite = CASE
          WHEN v_licence_doc_id IS NOT NULL THEN v_licence_specialite
          ELSE NULL
        END,
        modifie_le = now()
    WHERE s.id = p_soignant_id;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'jolene.system_update',
      v_previous_system_update,
      true
    );
    RAISE;
  END;
  PERFORM set_config(
    'jolene.system_update',
    v_previous_system_update,
    true
  );
END;
$_$;


ALTER FUNCTION "public"."fn_recalculer_preuves_etudiant"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_recalculer_score_fiabilite_soignant"("p_soignant_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_new_score NUMERIC;
BEGIN
  UPDATE soignants SET
    score_fiabilite = GREATEST(0, LEAST(100,
      50.0
      + (COALESCE(total_missions_terminees, 0) * 2.0)
      - (COALESCE(total_missions_annulees, 0) * 8.0)
      - (COALESCE(total_absences, 0) * 25.0)
      - (COALESCE(total_retards_pointage, 0) * 3.0)
      - (COALESCE(total_litiges_perdus, 0) * 10.0)
      + CASE WHEN COALESCE(total_missions_terminees, 0) > 20 THEN 10.0 ELSE 0 END
      + CASE WHEN COALESCE(total_absences, 0) = 0 AND COALESCE(total_missions_terminees, 0) > 5 THEN 5.0 ELSE 0 END
      + CASE WHEN COALESCE(prevoyance_inscrit, false) THEN 3.0 ELSE 0 END
    )),
    modifie_le = NOW()
  WHERE id = p_soignant_id
  RETURNING score_fiabilite INTO v_new_score;

  RETURN v_new_score;
END;
$$;


