CREATE OR REPLACE FUNCTION "public"."fn_reinitialiser_ma_profession"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.soignants s
    WHERE s.id = v_uid AND s.supprime_le IS NULL
      AND COALESCE(s.rpps_verifie, false) = false
      AND COALESCE(s.adeli_verifie, false) = false
      AND COALESCE(s.diplome_verifie, false) = false
      AND COALESCE(s.tous_documents_valides, false) = false
  ) OR EXISTS (
    SELECT 1 FROM public.documents_soignants d
    WHERE d.soignant_id = v_uid AND d.supprime_le IS NULL
      AND d.statut_verification = 'VERIFIE'
  ) OR EXISTS (
    SELECT 1 FROM public.missions m
    WHERE m.soignant_assigne_id = v_uid
      AND m.statut IN ('ASSIGNEE', 'EN_COURS')
  ) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'PROFESSION_VERROUILLEE',
      'error', 'La profession est verrouillée après vérification ou attribution.'
    );
  END IF;

  PERFORM set_config('jolene.system_update', 'true', true);
  UPDATE public.soignants
  SET profession = NULL,
      specialite_medicale = NULL,
      specialite_code = NULL,
      specialite_source = NULL,
      modifie_le = now()
  WHERE id = v_uid;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'SOIGNANT',
    p_action := 'MODIFICATION_PROFIL',
    p_type_ressource := 'soignant',
    p_id_ressource := v_uid,
    p_details := jsonb_build_object('champs_modifies', jsonb_build_array('profession_reinitialisee'))
  );
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_reinitialiser_ma_profession"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rejeter_virement_admin"("p_facture_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_facture RECORD;
BEGIN
  IF NOT est_admin() THEN
    RETURN json_build_object('error', 'Réservé aux administrateurs');
  END IF;

  SELECT id, statut INTO v_facture FROM factures WHERE id = p_facture_id;

  IF NOT FOUND THEN
    RETURN json_build_object('error', 'Facture introuvable');
  END IF;

  IF v_facture.statut != 'VIREMENT_DECLARE' THEN
    RETURN json_build_object('error', 'Cette facture n''est pas en attente de vérification de virement');
  END IF;

  UPDATE factures
     SET statut = 'EMISE',
         virement_reference = NULL,
         mode_paiement = 'STRIPE',
         modifie_le = now()
   WHERE id = p_facture_id;

  RETURN json_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_rejeter_virement_admin"("p_facture_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_relancer_candidatures_en_attente"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_nb integer := 0;
  v_delai interval := (public.fn_param_num('delai_relance_candidatures_h', 24)::text || ' hours')::interval;
BEGIN
  FOR r IN
    SELECT m.id, m.etablissement_id, m.intitule,
           count(c.id) AS nb_attente,
           min(c.cree_le) AS plus_ancienne
    FROM missions m
    JOIN candidatures c ON c.mission_id = m.id AND c.statut = 'EN_ATTENTE'
    WHERE m.statut = 'OUVERTE'
    GROUP BY m.id, m.etablissement_id, m.intitule, m.derniere_relance_candidatures_le
    HAVING min(c.cree_le) < now() - v_delai
       AND (m.derniere_relance_candidatures_le IS NULL
            OR m.derniere_relance_candidatures_le < now() - v_delai)
  LOOP
    PERFORM public.fn_creer_notification(
      r.etablissement_id, 'ETABLISSEMENT', 'RAPPEL_CANDIDATURES',
      r.nb_attente || ' candidature(s) en attente',
      'Vous avez ' || r.nb_attente || ' candidature(s) à traiter sur « ' || r.intitule ||
        ' », dont la plus ancienne depuis plus de 24h. Répondez vite pour ne pas perdre le soignant.',
      '/etablissement/missions/' || r.id::text,
      'mission', r.id
    );
    UPDATE missions SET derniere_relance_candidatures_le = now() WHERE id = r.id;
    v_nb := v_nb + 1;
  END LOOP;
  RETURN v_nb;
END;
$$;


ALTER FUNCTION "public"."fn_relancer_candidatures_en_attente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_relancer_missions_sans_candidat"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m record;
  v_missions_relancees integer := 0;
  v_soignants_notifies integer := 0;
  v_nb integer;
BEGIN
  FOR v_m IN
    SELECT m.id, m.intitule, m.profession_requise, m.type_contrat_recherche,
           m.taux_horaire_base, m.debut_le, m.etablissement_id,
           e.nom AS etab_nom, e.adresse_ville AS etab_ville,
           e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng
      FROM public.missions m
      JOIN public.etablissements e ON e.id = m.etablissement_id
     WHERE m.statut = 'OUVERTE'
       AND m.mode_attribution = 'CANDIDATURE'
       AND m.debut_le > now()
       AND m.cree_le < now() - interval '24 hours'
       AND COALESCE(m.relances_sans_candidat, 0) < 2
       AND (m.derniere_relance_sans_candidat_le IS NULL
            OR m.derniere_relance_sans_candidat_le < now() - interval '48 hours')
       AND NOT EXISTS (
         SELECT 1 FROM public.candidatures c
          WHERE c.mission_id = m.id AND c.statut = 'EN_ATTENTE'
       )
     LIMIT 200
  LOOP
    INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
    VALUES (
      v_m.etablissement_id, 'MISSION_NON_POURVUE',
      'Aucun candidat pour « ' || public.fn_html_escape(v_m.intitule) || ' »',
      'Votre mission du ' || to_char(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM') ||
      ' n’a pas encore de candidat. Les soignants compatibles viennent d’être notifiés. Vérifiez le taux horaire ou alertez le pool d’urgence.',
      '/etablissement/missions/' || v_m.id, 'ETABLISSEMENT'
    );

    WITH cibles AS (
      SELECT s.id
        FROM public.soignants s
       WHERE public.fn_soignant_eligible_mission(s.id, v_m.id, true)
         AND COALESCE(s.statut_compte::text, 'ACTIF') = 'ACTIF'
         AND NOT public.fn_est_exclu(s.id, v_m.etablissement_id)
         AND NOT EXISTS (
           SELECT 1 FROM public.candidatures c
            WHERE c.mission_id = v_m.id AND c.soignant_id = s.id
         )
         AND NOT EXISTS (
           SELECT 1 FROM public.notifications n
            WHERE n.destinataire_id = s.id AND n.type = 'MISSION_A_POURVOIR'
              AND n.lien = '/soignant/missions/' || v_m.id
         )
         AND (
           s.adresse_lat IS NULL OR v_m.etab_lat IS NULL
           OR public.fn_haversine_distance_m(
             s.adresse_lat, s.adresse_lng, v_m.etab_lat, v_m.etab_lng
           ) <= COALESCE(s.rayon_deplacement_km, 50) * 1000
         )
       LIMIT 25
    )
    INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
    SELECT id, 'MISSION_A_POURVOIR',
      'Mission ' || v_m.profession_requise::text || ' à pourvoir près de chez vous',
      public.fn_html_escape(v_m.intitule) || ' — ' || COALESCE(v_m.etab_ville, '') || ', le ' ||
      to_char(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM') || ' à ' ||
      COALESCE(v_m.taux_horaire_base::text, '?') || ' €/h. L’établissement cherche encore — postulez vite.',
      '/soignant/missions/' || v_m.id, 'SOIGNANT'
    FROM cibles;
    GET DIAGNOSTICS v_nb = ROW_COUNT;
    v_soignants_notifies := v_soignants_notifies + v_nb;

    UPDATE public.missions
       SET relances_sans_candidat = COALESCE(relances_sans_candidat, 0) + 1,
           derniere_relance_sans_candidat_le = now()
     WHERE id = v_m.id;
    v_missions_relancees := v_missions_relancees + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'missions_relancees', v_missions_relancees,
    'soignants_notifies', v_soignants_notifies
  );
END;
$$;


ALTER FUNCTION "public"."fn_relancer_missions_sans_candidat"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_relancer_signatures_contrats"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_contrat RECORD;
    v_count INTEGER := 0;
    v_destinataire UUID;
BEGIN
    FOR v_contrat IN
        SELECT c.id, c.mission_id, c.soignant_id, c.etablissement_id,
               c.signature_soignant, c.signature_etablissement, c.cree_le,
               m.intitule
        FROM contrats_mission c
        JOIN missions m ON m.id = c.mission_id
        WHERE c.statut IN ('EN_ATTENTE_SIGNATURES', 'SIGNE_SOIGNANT', 'SIGNE_ETABLISSEMENT')
          AND c.cree_le + INTERVAL '24 hours' < NOW()
          AND c.cree_le + INTERVAL '72 hours' > NOW()
    LOOP
        -- Qui n'a pas signé ?
        IF NOT v_contrat.signature_soignant THEN
            v_destinataire := v_contrat.soignant_id;
        ELSIF NOT v_contrat.signature_etablissement THEN
            v_destinataire := v_contrat.etablissement_id;
        ELSE
            CONTINUE;
        END IF;

        -- Éviter les doublons de notification (max 1 relance par jour)
        IF NOT EXISTS (
            SELECT 1 FROM notifications
            WHERE id_ressource = v_contrat.id
              AND type = 'CONTRAT_A_SIGNER'
              AND cree_le > NOW() - INTERVAL '24 hours'
        ) THEN
            INSERT INTO notifications (destinataire_id, type_destinataire, type, titre, corps, lien, type_ressource, id_ressource)
            VALUES (
                v_destinataire,
                CASE WHEN v_destinataire = v_contrat.soignant_id THEN 'SOIGNANT' ELSE 'ETABLISSEMENT' END,
                'CONTRAT_A_SIGNER',
                'Rappel : contrat à signer',
                'Le contrat pour la mission "' || v_contrat.intitule || '" attend votre signature.',
                '/contrat/' || v_contrat.id::TEXT,
                'contrat',
                v_contrat.id
            );
            v_count := v_count + 1;
        END IF;
    END LOOP;

    -- Auto-annulation après 72h sans signature complète
    UPDATE contrats_mission SET statut = 'EXPIRE', modifie_le = NOW()
    WHERE statut IN ('EN_ATTENTE_SIGNATURES', 'SIGNE_SOIGNANT', 'SIGNE_ETABLISSEMENT')
      AND cree_le + INTERVAL '72 hours' < NOW();

    -- Annuler les missions correspondantes
    UPDATE missions SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = NOW()
    WHERE id IN (
        SELECT mission_id FROM contrats_mission
        WHERE statut = 'EXPIRE' AND modifie_le > NOW() - INTERVAL '1 minute'
    ) AND statut = 'ASSIGNEE';

    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_relancer_signatures_contrats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_relancer_validation_presence"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_soignant uuid := auth.uid();
  v_mission RECORD;
  v_intitule text;
BEGIN
  IF v_soignant IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NON_AUTHENTIFIE');
  END IF;

  SELECT id, etablissement_id, intitule INTO v_mission
  FROM missions
  WHERE id = p_mission_id AND soignant_assigne_id = v_soignant;
  IF v_mission.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'MISSION_INCONNUE');
  END IF;

  -- Il doit exister une présence à pointage complet non encore validée
  -- (miroir du gate 7b-B). Sinon il n'y a rien à relancer.
  IF NOT EXISTS (
    SELECT 1 FROM presences p
    WHERE p.mission_id = p_mission_id
      AND COALESCE(p.valide_par_etablissement, false) = false
      AND p.pointage_depart_le IS NOT NULL
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'RIEN_A_VALIDER');
  END IF;

  -- Throttle 24h : pas deux relances pour la même mission dans la journée.
  IF EXISTS (
    SELECT 1 FROM notifications
    WHERE type = 'RAPPEL_VALIDATION_PRESENCE'
      AND id_ressource = p_mission_id
      AND cree_le > now() - interval '24 hours'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'DEJA_RELANCE',
      'message', 'Tu as déjà relancé cet établissement aujourd''hui. Il a été notifié.');
  END IF;

  v_intitule := COALESCE(v_mission.intitule, 'une mission');

  INSERT INTO notifications (destinataire_id, type_destinataire, type, titre, corps, lien, type_ressource, id_ressource)
  VALUES (
    v_mission.etablissement_id, 'ETABLISSEMENT', 'RAPPEL_VALIDATION_PRESENCE',
    '⏳ Une présence attend votre validation',
    'Le soignant de « ' || v_intitule || ' » attend la validation de ses présences pour être payé. Merci de valider depuis vos présences.',
    '/etablissement/presences', 'mission', p_mission_id
  );

  PERFORM public.fn_ecrire_audit_safe(
    v_soignant, 'SOIGNANT', 'PRESENCE_RELANCE_VALIDATION', 'mission', p_mission_id,
    NULL, jsonb_build_object('etablissement_id', v_mission.etablissement_id), NULL, 'fn_relancer_validation_presence'
  );

  RETURN jsonb_build_object('success', true,
    'message', 'Établissement relancé. Il a été notifié de valider tes présences.');
END;
$$;


ALTER FUNCTION "public"."fn_relancer_validation_presence"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_remplacer_document_soignant"("p_type_document" "text", "p_libelle" "text", "p_s3_cle" "text", "p_nom_fichier" "text", "p_type_mime" "text", "p_taille_octets" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_type public.type_document;
  v_doc_id uuid;
  v_doc_est_actif boolean;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_enum e
    JOIN pg_type t ON t.oid = e.enumtypid
    JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE n.nspname = 'public' AND t.typname = 'type_document'
      AND e.enumlabel = p_type_document
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TYPE_DOCUMENT_INVALIDE');
  END IF;
  v_type := p_type_document::public.type_document;

  IF p_s3_cle IS NULL
     OR length(p_s3_cle) > 512
     OR p_s3_cle NOT LIKE v_uid::text || '/documents/' || p_type_document || '/%'
     OR p_s3_cle LIKE '%..%'
     OR p_s3_cle LIKE E'%\\%'
     OR split_part(p_s3_cle, '/', 4) !~ '^[A-Za-z0-9._-]+$' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CHEMIN_DOCUMENT_INVALIDE');
  END IF;
  IF p_type_mime NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'image/webp')
     OR p_taille_octets IS NULL OR p_taille_octets < 1
     OR p_taille_octets > 10485760
     OR NULLIF(btrim(COALESCE(p_nom_fichier, '')), '') IS NULL
     OR length(p_nom_fichier) > 255
     OR length(COALESCE(p_libelle, '')) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'METADONNEES_DOCUMENT_INVALIDES');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('document:' || p_s3_cle, 0));
  SELECT id, supprime_le IS NULL AND revoque_le IS NULL
  INTO v_doc_id, v_doc_est_actif
  FROM public.documents_soignants
  WHERE soignant_id = v_uid AND s3_bucket = 'jolene-documents' AND s3_cle = p_s3_cle
  ORDER BY televerse_le DESC NULLS LAST
  LIMIT 1;
  IF v_doc_id IS NOT NULL THEN
    IF v_doc_est_actif IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'success', false,
        'error_code', 'DOCUMENT_INACTIF'
      );
    END IF;
    RETURN jsonb_build_object('success', true, 'document_id', v_doc_id, 'idempotent', true);
  END IF;

  PERFORM set_config('jolene.document_server_update', 'true', true);
  INSERT INTO public.documents_soignants (
    soignant_id, type_document, libelle, s3_bucket, s3_cle,
    nom_fichier, type_mime, taille_octets, statut_verification,
    verifie_par, verifie_le, resultat_ia
  ) VALUES (
    v_uid, v_type, NULLIF(left(btrim(COALESCE(p_libelle, '')), 500), ''),
    'jolene-documents', p_s3_cle, left(btrim(p_nom_fichier), 255),
    p_type_mime, p_taille_octets, 'EN_ATTENTE', NULL, NULL, NULL
  ) RETURNING id INTO v_doc_id;
  PERFORM set_config('jolene.document_server_update', '', true);

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'SOIGNANT',
    p_action := 'DOCUMENT_TELEVERSEMENT',
    p_type_ressource := 'document_soignant',
    p_id_ressource := v_doc_id,
    p_cle_s3 := p_s3_cle,
    p_details := jsonb_build_object(
      'type_document', p_type_document,
      'taille_octets', p_taille_octets,
      'remplacement_atomique', true
    )
  );
  RETURN jsonb_build_object('success', true, 'document_id', v_doc_id, 'idempotent', false);
END;
$_$;


ALTER FUNCTION "public"."fn_remplacer_document_soignant"("p_type_document" "text", "p_libelle" "text", "p_s3_cle" "text", "p_nom_fichier" "text", "p_type_mime" "text", "p_taille_octets" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_remplacer_preuve_etablissement"("p_etablissement_id" "uuid", "p_preuve" "text", "p_nouvelle_s3_key" "text", "p_type_mime" "text", "p_type_document" "text", "p_version_attendue" bigint, "p_representant_nom" "text" DEFAULT NULL::"text", "p_representant_prenom" "text" DEFAULT NULL::"text", "p_acteur_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_acteur_id uuid;
  v_role text := COALESCE(
    auth.jwt() ->> 'role',
    current_setting('request.jwt.claim.role', true),
    ''
  );
  v_etab public.etablissements%ROWTYPE;
  v_ancienne_s3_key text;
  v_ancien_resultat jsonb;
  v_version_nouvelle bigint;
  v_est_admin boolean := false;
BEGIN
  v_acteur_id := COALESCE(v_uid, p_acteur_id);
  v_est_admin := v_uid IS NOT NULL AND public.est_admin();
  IF v_role IS DISTINCT FROM 'service_role'
     AND NOT v_est_admin
     AND (
       v_uid IS NULL
       OR p_etablissement_id IS DISTINCT FROM public.mon_etablissement_id()
     ) THEN
    RAISE EXCEPTION 'Gestionnaire établissement autorisé requis'
      USING ERRCODE = '42501';
  END IF;

  IF p_preuve NOT IN ('IDENTITE', 'FONCTION')
     OR NULLIF(btrim(p_nouvelle_s3_key), '') IS NULL
     OR p_nouvelle_s3_key LIKE '%..%'
     OR position(chr(92) in p_nouvelle_s3_key) > 0
     OR p_nouvelle_s3_key NOT LIKE p_etablissement_id::text || '/%' THEN
    RAISE EXCEPTION 'Source documentaire invalide' USING ERRCODE = '22023';
  END IF;

  IF p_type_mime NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'image/webp') THEN
    RAISE EXCEPTION 'Type MIME non autorisé' USING ERRCODE = '22023';
  END IF;
  IF p_preuve = 'IDENTITE'
     AND p_type_document NOT IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR') THEN
    RAISE EXCEPTION 'Type de pièce d identité invalide' USING ERRCODE = '22023';
  END IF;
  IF p_preuve = 'FONCTION'
     AND p_type_document NOT IN (
       'ATTESTATION_EMPLOYEUR', 'DELEGATION_SIGNATURE', 'FICHE_POSTE',
       'CONTRAT_TRAVAIL', 'DECISION_NOMINATION'
     ) THEN
    RAISE EXCEPTION 'Type de justificatif invalide' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_etab
  FROM public.etablissements
  WHERE id = p_etablissement_id AND supprime_le IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Établissement introuvable' USING ERRCODE = 'P0002';
  END IF;
  IF v_etab.verification_source_version IS DISTINCT FROM p_version_attendue THEN
    RAISE EXCEPTION 'Le dossier a changé : rechargez avant de téléverser'
      USING ERRCODE = '40001';
  END IF;

  IF p_preuve = 'IDENTITE' THEN
    IF NULLIF(btrim(p_representant_nom), '') IS NULL
       OR NULLIF(btrim(p_representant_prenom), '') IS NULL THEN
      RAISE EXCEPTION 'Nom et prénom du représentant requis'
        USING ERRCODE = '22023';
    END IF;
    v_ancienne_s3_key := v_etab.representant_piece_s3_key;
    v_ancien_resultat := v_etab.representant_identite_resultat_ia;
    IF v_ancienne_s3_key IS NOT DISTINCT FROM p_nouvelle_s3_key THEN
      RAISE EXCEPTION 'Une nouvelle clé immuable est requise'
        USING ERRCODE = '22023';
    END IF;
    UPDATE public.etablissements
    SET representant_nom = btrim(p_representant_nom),
        representant_prenom = btrim(p_representant_prenom),
        representant_piece_s3_key = p_nouvelle_s3_key,
        representant_piece_type_mime = p_type_mime,
        representant_piece_type_document = p_type_document,
        modifie_le = now()
    WHERE id = p_etablissement_id;
  ELSE
    v_ancienne_s3_key := v_etab.justificatif_fonction_s3_key;
    v_ancien_resultat := v_etab.justificatif_fonction_resultat_ia;
    IF v_ancienne_s3_key IS NOT DISTINCT FROM p_nouvelle_s3_key THEN
      RAISE EXCEPTION 'Une nouvelle clé immuable est requise'
        USING ERRCODE = '22023';
    END IF;
    UPDATE public.etablissements
    SET justificatif_fonction_s3_key = p_nouvelle_s3_key,
        justificatif_fonction_type_mime = p_type_mime,
        justificatif_fonction_type = p_type_document,
        modifie_le = now()
    WHERE id = p_etablissement_id;
  END IF;

  SELECT verification_source_version INTO v_version_nouvelle
  FROM public.etablissements
  WHERE id = p_etablissement_id;

  INSERT INTO public.etablissement_preuve_audit (
    etablissement_id, preuve, evenement, acteur_id, source_version,
    source_s3_key, source_snapshot
  ) VALUES (
    p_etablissement_id, p_preuve, 'REMPLACEMENT', v_acteur_id,
    p_version_attendue, v_ancienne_s3_key,
    jsonb_strip_nulls(jsonb_build_object(
      'ancienne_s3_key', v_ancienne_s3_key,
      'nouvelle_s3_key', p_nouvelle_s3_key,
      'ancien_resultat', v_ancien_resultat,
      'nouvelle_type_mime', p_type_mime,
      'nouveau_type_document', p_type_document,
      'representant_nom', CASE WHEN p_preuve = 'IDENTITE' THEN btrim(p_representant_nom) ELSE v_etab.representant_nom END,
      'representant_prenom', CASE WHEN p_preuve = 'IDENTITE' THEN btrim(p_representant_prenom) ELSE v_etab.representant_prenom END
    ))
  );

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details
  ) VALUES (
    v_acteur_id,
    CASE WHEN v_est_admin THEN 'ADMIN_PLATEFORME' ELSE 'ADMIN_ETABLISSEMENT' END,
    'DOCUMENT_TELEVERSEMENT', 'etablissement', p_etablissement_id,
    p_nouvelle_s3_key,
    jsonb_build_object(
      'sous_action', 'REMPLACEMENT_PREUVE_ETABLISSEMENT',
      'preuve', p_preuve,
      'source_version', p_version_attendue,
      'ancienne_s3_key', v_ancienne_s3_key,
      'nouvelle_s3_key', p_nouvelle_s3_key
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'ancienne_s3_key', v_ancienne_s3_key,
    'nouvelle_s3_key', p_nouvelle_s3_key,
    'verification_source_version', v_version_nouvelle
  );
END;
$$;


ALTER FUNCTION "public"."fn_remplacer_preuve_etablissement"("p_etablissement_id" "uuid", "p_preuve" "text", "p_nouvelle_s3_key" "text", "p_type_mime" "text", "p_type_document" "text", "p_version_attendue" bigint, "p_representant_nom" "text", "p_representant_prenom" "text", "p_acteur_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_remplacer_preuves_documentaires_actives"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_classe text;
  v_ids_revoques jsonb := '[]'::jsonb;
  v_document_server_update_precedent text := COALESCE(
    current_setting('jolene.document_server_update', true),
    ''
  );
BEGIN
  IF NEW.supprime_le IS NOT NULL OR NEW.revoque_le IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_classe := CASE
    WHEN NEW.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
      THEN 'IDENTITE_OFFICIELLE'
    ELSE NEW.type_document::text
  END;
  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.soignant_id::text || ':preuve:' || v_classe, 0)
  );

  PERFORM set_config('jolene.document_replacement', 'true', true);
  -- La révocation invalide aussi l'identifiant CAS d'une analyse IA en vol.
  -- Le trigger de protection documentaire n'autorise cette écriture sensible
  -- que sous le contexte serveur borné au trigger de remplacement.
  PERFORM set_config('jolene.document_server_update', 'true', true);
  WITH revoquees AS (
    UPDATE public.documents_soignants precedent
    SET supprime_le = now(),
        revoque_le = now(),
        revoque_raison = 'REMPLACEMENT',
        remplace_par_document_id = NEW.id,
        verification_attempt_id = NULL,
        modifie_le = now()
    WHERE precedent.soignant_id = NEW.soignant_id
      AND precedent.id IS DISTINCT FROM NEW.id
      AND precedent.supprime_le IS NULL
      AND precedent.revoque_le IS NULL
      AND CASE
        WHEN precedent.type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
          THEN 'IDENTITE_OFFICIELLE'
        ELSE precedent.type_document::text
      END = v_classe
    RETURNING precedent.id
  )
  SELECT COALESCE(jsonb_agg(id), '[]'::jsonb)
    INTO v_ids_revoques
  FROM revoquees;
  PERFORM set_config(
    'jolene.document_server_update',
    v_document_server_update_precedent,
    true
  );
  PERFORM set_config('jolene.document_replacement', '', true);

  IF jsonb_array_length(v_ids_revoques) > 0 THEN
    PERFORM public.fn_ecrire_audit_safe(
      p_acteur_id := NEW.soignant_id,
      p_type_acteur := 'SOIGNANT',
      p_action := 'VERIFICATION_DOCUMENT',
      p_type_ressource := 'document_soignant',
      p_id_ressource := NEW.id,
      p_details := jsonb_build_object(
        'sous_action', 'REMPLACEMENT_PREUVE',
        'classe_preuve', v_classe,
        'documents_revoques', v_ids_revoques
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_remplacer_preuves_documentaires_actives"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_repartition_heures_soignant"("p_periode_jours" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_periode INTEGER;
  v_since TIMESTAMPTZ;
  v_total NUMERIC;
  v_nuit NUMERIC;
  v_dimanche NUMERIC;
  v_ferie NUMERIC;
  v_jour NUMERIC;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;

  v_periode := GREATEST(COALESCE(p_periode_jours, 30), 1);
  v_since := NOW() - (v_periode || ' days')::interval;

  SELECT
    COALESCE(SUM(duree_heures), 0),
    COALESCE(SUM(heures_nuit), 0),
    COALESCE(SUM(heures_dimanche), 0),
    COALESCE(SUM(heures_ferie), 0)
  INTO v_total, v_nuit, v_dimanche, v_ferie
  FROM missions
  WHERE soignant_assigne_id = v_uid
    AND statut = 'TERMINEE'
    AND fin_le >= v_since;

  v_jour := GREATEST(v_total - (v_nuit + v_dimanche + v_ferie), 0);

  RETURN jsonb_build_object(
    'total_heures', ROUND(v_total::numeric, 1),
    'periode_jours', v_periode,
    'jour', ROUND(v_jour::numeric, 1),
    'nuit', ROUND(v_nuit::numeric, 1),
    'dimanche', ROUND(v_dimanche::numeric, 1),
    'ferie', ROUND(v_ferie::numeric, 1)
  );
END;
$$;


ALTER FUNCTION "public"."fn_repartition_heures_soignant"("p_periode_jours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_repondre_litige"("p_litige_id" "uuid", "p_reponse" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_litige record;
  v_auteur text;
  v_type_acteur text;
  v_reponse_safe text;
  v_date_str text;
  v_ip inet;
  v_user_agent text;
  v_headers jsonb;
  v_etablissement_id uuid;
  v_est_admin boolean := false;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  v_etablissement_id := public.mon_etablissement_id();
  v_est_admin := public.est_admin();
  SELECT l.*
    INTO v_litige
    FROM public.litiges l
   WHERE l.id = p_litige_id
     AND (
       l.soignant_id = v_uid
       OR (
         l.etablissement_id = v_etablissement_id
         AND public.fn_a_permission_etablissement(
           'contrats', l.etablissement_id
         ) IS TRUE
       )
       OR v_est_admin
     )
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Litige introuvable ou accès refusé');
  END IF;
  IF v_litige.statut NOT IN (
    'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS'
  ) THEN
    RETURN jsonb_build_object('error', 'Ce litige est déjà clôturé');
  END IF;

  IF v_uid = v_litige.soignant_id THEN
    v_auteur := 'Soignant';
    v_type_acteur := 'SOIGNANT';
  ELSIF v_etablissement_id = v_litige.etablissement_id
        AND public.fn_a_permission_etablissement(
          'contrats', v_litige.etablissement_id
        ) IS TRUE THEN
    v_auteur := 'Établissement';
    v_type_acteur := 'ADMIN_ETABLISSEMENT';
  ELSIF v_est_admin THEN
    v_auteur := 'Admin';
    v_type_acteur := 'ADMIN_PLATEFORME';
  ELSE
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  v_reponse_safe := left(
    regexp_replace(
      COALESCE(NULLIF(trim(p_reponse), ''), ''), '<[^>]*>', '', 'g'
    ),
    2000
  );
  IF length(v_reponse_safe) < 10 THEN
    RETURN jsonb_build_object(
      'error', 'La réponse doit contenir au moins 10 caractères'
    );
  END IF;
  v_date_str := to_char(now(), 'DD/MM/YYYY HH24:MI');

  UPDATE public.litiges
     SET reponse = CASE
       WHEN reponse IS NOT NULL AND reponse <> '' THEN
         reponse || E'\n---\n[' || v_date_str || '] '
           || v_auteur || ': ' || v_reponse_safe
       ELSE '[' || v_date_str || '] ' || v_auteur || ': ' || v_reponse_safe
     END,
     statut = CASE
       WHEN statut IN ('EN_MEDIATION', 'MEDIATION_EN_COURS') THEN statut
       ELSE 'EN_DISCUSSION'
     END
   WHERE id = p_litige_id;

  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_ip := NULLIF(
      trim(split_part(COALESCE(v_headers->>'x-forwarded-for', ''), ',', 1)),
      ''
    )::inet;
    v_user_agent := NULLIF(v_headers->>'user-agent', '');
  EXCEPTION WHEN OTHERS THEN
    v_ip := NULL;
    v_user_agent := NULL;
  END;

  PERFORM public.fn_ecrire_audit(
    v_uid, v_type_acteur, 'LITIGE_REPONSE',
    'litige', p_litige_id, NULL,
    jsonb_build_object(
      'mission_id', v_litige.mission_id,
      'motif_original', v_litige.motif,
      'auteur_reponse', v_auteur,
      'reponse_length', length(v_reponse_safe),
      'nouveau_statut', CASE
        WHEN v_litige.statut IN ('EN_MEDIATION', 'MEDIATION_EN_COURS')
          THEN v_litige.statut
        ELSE 'EN_DISCUSSION'
      END
    ),
    v_ip, v_user_agent
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_repondre_litige"("p_litige_id" "uuid", "p_reponse" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_repondre_proposition"("p_candidature_id" "uuid", "p_accepter" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_candidature record;
  v_result jsonb;
BEGIN
  SELECT c.* INTO v_candidature
    FROM public.candidatures c
   WHERE c.id = p_candidature_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Candidature introuvable'); END IF;
  IF v_candidature.soignant_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;
  IF v_candidature.statut <> 'PROPOSEE' THEN
    RETURN jsonb_build_object('error', 'Cette proposition n’est plus en attente');
  END IF;

  PERFORM set_config(
    'jolene.candidature_rpc_mission_id',
    v_candidature.mission_id::text,
    true
  );
  IF v_candidature.cree_le < now() - interval '2 hours' THEN
    UPDATE public.candidatures
       SET statut = 'EXPIREE', traite_le = now()
     WHERE id = p_candidature_id;
    RETURN jsonb_build_object('error', 'Cette proposition a expiré');
  END IF;

  IF NOT p_accepter THEN
    UPDATE public.candidatures
       SET statut = 'REFUSEE', traite_le = now()
     WHERE id = p_candidature_id;
    RETURN jsonb_build_object('success', true, 'message', 'Proposition refusée');
  END IF;

  v_result := public.fn_finaliser_attribution_mission(
    v_candidature.mission_id,
    v_candidature.soignant_id,
    v_candidature.type_contrat_choisi
  );
  IF COALESCE((v_result->>'success')::boolean, false) IS NOT TRUE THEN
    RETURN v_result;
  END IF;

  UPDATE public.candidatures
     SET statut = 'ACCEPTEE', traite_le = now()
   WHERE id = p_candidature_id;
  UPDATE public.candidatures
     SET statut = 'REFUSEE', motif_refus = 'Mission attribuée', traite_le = now()
   WHERE mission_id = v_candidature.mission_id
     AND id <> p_candidature_id
     AND statut IN ('EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB', 'PROPOSEE');

  RETURN v_result || jsonb_build_object('message', 'Proposition acceptée');
END;
$$;


ALTER FUNCTION "public"."fn_repondre_proposition"("p_candidature_id" "uuid", "p_accepter" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_repondre_proposition"("p_candidature_id" "uuid", "p_accepter" boolean) IS 'E16 transmet candidature.type_contrat_choisi a fn_accepter_mission. RAISE E16_CANDIDATURE_ORPHELINE si MIXTE TOUS sans choix.';



CREATE OR REPLACE FUNCTION "public"."fn_reserver_type_compte"("p_user_id" "uuid", "p_type_compte" "text", "p_claim_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_type_demande text := upper(trim(COALESCE(p_type_compte, '')));
  v_type_reserve text;
  v_role_auth text;
  v_soignant boolean;
  v_etablissement boolean;
  v_membre_etablissement boolean;
  v_finalise_le timestamptz;
  v_claim_token uuid;
  v_claim_expire_le timestamptz;
  v_frais boolean;
BEGIN
  IF p_user_id IS NULL OR p_claim_token IS NULL
     OR v_type_demande NOT IN ('SOIGNANT', 'ETABLISSEMENT') THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'ACCOUNT_TYPE_INVALID');
  END IF;

  -- Un seul gagnant, y compris entre register-soignant et
  -- register-etablissement lances exactement au meme instant.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));

  SELECT u.raw_app_meta_data ->> 'role'
  INTO v_role_auth
  FROM auth.users u
  WHERE u.id = p_user_id
    AND u.deleted_at IS NULL
    AND (u.banned_until IS NULL OR u.banned_until <= now());

  IF NOT FOUND THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'ACCOUNT_AUTH_INACTIVE');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.soignants s WHERE s.id = p_user_id),
         EXISTS (SELECT 1 FROM public.etablissements e WHERE e.id = p_user_id),
         EXISTS (SELECT 1 FROM public.membres_etablissement m WHERE m.user_id = p_user_id)
  INTO v_soignant, v_etablissement, v_membre_etablissement;

  -- Un profil historiquement croise n'est jamais « repare » automatiquement :
  -- aucun profil ni aucune donnee de test n'est supprime par la migration.
  IF v_soignant AND (v_etablissement OR v_membre_etablissement) THEN
    RETURN jsonb_build_object('allowed', false, 'code', 'ACCOUNT_PROFILE_CONFLICT');
  END IF;

  SELECT t.type_compte, t.finalise_le, t.claim_token, t.claim_expire_le
  INTO v_type_reserve, v_finalise_le, v_claim_token, v_claim_expire_le
  FROM public.types_comptes_auth t
  WHERE t.user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_type_reserve := CASE
      WHEN v_role_auth = 'ADMIN_PLATEFORME' THEN 'ADMIN'
      WHEN v_role_auth = 'SOIGNANT' OR v_soignant THEN 'SOIGNANT'
      WHEN v_role_auth IN ('ADMIN_ETABLISSEMENT', 'ETABLISSEMENT', 'ADMIN_GROUPE')
        OR v_etablissement OR v_membre_etablissement THEN 'ETABLISSEMENT'
      ELSE v_type_demande
    END;

    v_finalise_le := CASE
      WHEN v_soignant OR v_etablissement OR v_membre_etablissement OR v_role_auth IS NOT NULL
        THEN now()
      ELSE NULL
    END;
    INSERT INTO public.types_comptes_auth (
      user_id, type_compte, finalise_le, claim_token, claim_expire_le
    )
    VALUES (
      p_user_id,
      v_type_reserve,
      v_finalise_le,
      CASE WHEN v_finalise_le IS NULL THEN p_claim_token ELSE NULL END,
      CASE WHEN v_finalise_le IS NULL THEN now() + interval '15 minutes' ELSE NULL END
    );
  END IF;

  IF v_type_reserve <> v_type_demande THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'ACCOUNT_TYPE_MISMATCH',
      'existing_type', v_type_reserve
    );
  END IF;

  -- Un profil deja finalise doit se connecter; l'Edge Function ne doit surtout
  -- pas le supprimer au titre d'une compensation d'inscription.
  IF (v_type_demande = 'SOIGNANT' AND v_soignant)
     OR (v_type_demande = 'ETABLISSEMENT' AND (v_etablissement OR v_membre_etablissement)) THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'ACCOUNT_ALREADY_REGISTERED',
      'existing_type', v_type_reserve
    );
  END IF;

  IF v_finalise_le IS NOT NULL THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'ACCOUNT_REGISTRATION_INCOMPLETE',
      'existing_type', v_type_reserve
    );
  END IF;

  IF v_claim_token IS NOT NULL
     AND v_claim_token <> p_claim_token
     AND COALESCE(v_claim_expire_le, '-infinity'::timestamptz) > now() THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'code', 'ACCOUNT_REGISTRATION_IN_PROGRESS',
      'existing_type', v_type_reserve
    );
  END IF;

  -- Une reservation abandonnee est recuperable apres un delai court. Un appel
  -- concurrent du meme type ne partage jamais le droit de compensation Auth.
  UPDATE public.types_comptes_auth
  SET claim_token = p_claim_token,
      claim_expire_le = now() + interval '15 minutes'
  WHERE user_id = p_user_id;

  v_frais := v_finalise_le IS NULL
    AND v_role_auth IS NULL
    AND NOT v_soignant
    AND NOT v_etablissement
    AND NOT v_membre_etablissement;

  RETURN jsonb_build_object(
    'allowed', true,
    'fresh', v_frais,
    'type_compte', v_type_reserve
  );
END;
$$;


ALTER FUNCTION "public"."fn_reserver_type_compte"("p_user_id" "uuid", "p_type_compte" "text", "p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reset_onboarding"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  IF EXISTS (SELECT 1 FROM public.soignants WHERE id = v_uid) THEN
    UPDATE public.soignants
    SET onboarding_etapes_completees = '[]'::jsonb,
        onboarding_termine_le = NULL
    WHERE id = v_uid;
    RETURN jsonb_build_object('success', true, 'role', 'SOIGNANT');
  END IF;

  v_etab_id := public.mon_etablissement_id();
  IF v_etab_id IS NOT NULL THEN
    UPDATE public.etablissements
    SET onboarding_etapes_completees = '[]'::jsonb,
        onboarding_termine_le = NULL
    WHERE id = v_etab_id;
    RETURN jsonb_build_object('success', true, 'role', 'ETAB');
  END IF;

  RETURN jsonb_build_object('success', false, 'error_code', 'PROFIL_INTROUVABLE');
END;
$$;


ALTER FUNCTION "public"."fn_reset_onboarding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_resolve_template_contrat"("p_type_contrat" "text", "p_profession" "text", "p_type_etab" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_slug text;
  v_template RECORD;
  v_profession_court text;
BEGIN
  -- Tentative de matching spécifique : LIBERAL_<PROFESSION>_<TYPE_ETAB>
  IF p_type_contrat IN ('REMPLACEMENT_LIBERAL', 'LIBERAL') AND p_profession IS NOT NULL AND p_type_etab IS NOT NULL THEN
    -- Normalisation profession : enlever "_LIBERAL" / "IDE_LIBERAL" → "IDE", garder MEDECIN, DENTISTE, etc.
    v_profession_court := regexp_replace(upper(p_profession), '_LIBERAL$', '');
    v_slug := 'LIBERAL_' || v_profession_court || '_' || upper(p_type_etab);
    SELECT type_contrat, nom, version INTO v_template
    FROM public.templates_contrat
    WHERE type_contrat = v_slug AND est_actif = true
    ORDER BY version DESC LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true, 'slug', v_template.type_contrat,
        'nom', v_template.nom, 'version', v_template.version,
        'match', 'specifique'
      );
    END IF;
  END IF;

  -- Fallback : master
  IF p_type_contrat IN ('REMPLACEMENT_LIBERAL', 'LIBERAL') THEN
    v_slug := 'REMPLACEMENT_LIBERAL';
  ELSE
    v_slug := p_type_contrat; -- CDD, etc.
  END IF;

  SELECT type_contrat, nom, version INTO v_template
  FROM public.templates_contrat
  WHERE type_contrat = v_slug AND est_actif = true
  ORDER BY version DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Aucun template actif pour ' || v_slug);
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'slug', v_template.type_contrat,
    'nom', v_template.nom, 'version', v_template.version,
    'match', 'master_fallback'
  );
END;
$_$;


ALTER FUNCTION "public"."fn_resolve_template_contrat"("p_type_contrat" "text", "p_profession" "text", "p_type_etab" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_resoudre_alerte"("p_id" "uuid", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT est_admin() THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;
  UPDATE alertes_systeme SET resolu_le = now(), resolu_motif = p_motif WHERE id = p_id AND resolu_le IS NULL;
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_resoudre_alerte"("p_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_resoudre_contrat_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_mission record;
  v_soignant record;
  v_etablissement record;
  v_recherche text;
  v_choix text;
  v_mode jsonb;
  v_liberal_verifie boolean := false;
BEGIN
  SELECT id, profession_requise, type_contrat_recherche, etablissement_id
    INTO v_mission
  FROM public.missions
  WHERE id = p_mission_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Mission introuvable');
  END IF;

  SELECT id, COALESCE(type_exercice, 'SALARIE') AS type_exercice,
         preference_contrat_mixte, COALESCE(est_compte_test, false) AS est_compte_test
    INTO v_soignant
  FROM public.soignants
  WHERE id = p_soignant_id AND supprime_le IS NULL;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Profil soignant introuvable');
  END IF;

  v_liberal_verifie := public.fn_soignant_liberal_actif_verifie(p_soignant_id);

  SELECT type::text AS type_etablissement,
         COALESCE(est_secteur_public, false) AS est_public,
         COALESCE(est_compte_test, false) AS est_compte_test
    INTO v_etablissement
  FROM public.etablissements
  WHERE id = v_mission.etablissement_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Établissement introuvable');
  END IF;

  IF v_etablissement.est_compte_test AND NOT v_soignant.est_compte_test THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Mission de démonstration non disponible');
  END IF;

  IF p_choix_contrat IS NOT NULL
     AND upper(p_choix_contrat) NOT IN ('SALARIE', 'LIBERAL') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Choix de contrat invalide');
  END IF;

  v_recherche := CASE
    WHEN upper(COALESCE(v_mission.type_contrat_recherche::text, 'SALARIE'))
           IN ('SALARIE', 'LIBERAL', 'TOUS')
      THEN upper(COALESCE(v_mission.type_contrat_recherche::text, 'SALARIE'))
    ELSE 'SALARIE'
  END;

  IF v_recherche = 'SALARIE' THEN
    -- Le diplôme ou le statut du profil ne bloque jamais une mission salariée.
    v_choix := 'SALARIE';
  ELSIF v_recherche = 'LIBERAL' THEN
    IF v_soignant.type_exercice NOT IN ('LIBERAL', 'MIXTE')
       OR NOT v_liberal_verifie THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Cette mission est proposée en libéral ; activez un profil libéral avec SIRET et identité vérifiés.'
      );
    END IF;
    v_choix := 'LIBERAL';
  ELSE
    v_choix := upper(p_choix_contrat);

    IF v_choix = 'LIBERAL' AND NOT v_liberal_verifie THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Votre profil libéral doit être actif, avec SIRET et identité vérifiés.'
      );
    END IF;

    IF v_choix IS NULL THEN
      IF v_soignant.type_exercice = 'MIXTE' AND v_liberal_verifie THEN
        v_choix := CASE
          WHEN upper(COALESCE(v_soignant.preference_contrat_mixte, ''))
                 IN ('SALARIE', 'LIBERAL')
            THEN upper(v_soignant.preference_contrat_mixte)
          ELSE NULL
        END;
        IF v_choix IS NULL THEN
          RETURN jsonb_build_object(
            'ok', false,
            'choix_requis', true,
            'error', 'Choisissez votre mode de contrat.',
            'options', jsonb_build_array(
              jsonb_build_object('value', 'SALARIE', 'label', 'Salarié (CDD / bulletin de paie)'),
              jsonb_build_object('value', 'LIBERAL', 'label', 'Libéral (note d''honoraires)')
            )
          );
        END IF;
      ELSIF v_soignant.type_exercice = 'LIBERAL' AND v_liberal_verifie THEN
        v_choix := 'LIBERAL';
      ELSE
        -- Valeur de profil héritée/incohérente : aucun contrat libéral implicite.
        v_choix := 'SALARIE';
      END IF;
    END IF;

    IF v_choix = 'LIBERAL'
       AND (v_soignant.type_exercice NOT IN ('LIBERAL', 'MIXTE')
            OR NOT v_liberal_verifie) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', 'Votre profil n''est pas activé pour un contrat libéral vérifié.'
      );
    END IF;
  END IF;

  IF v_choix = 'LIBERAL' THEN
    v_mode := public.fn_mode_exercice(
      v_mission.profession_requise::text,
      v_etablissement.type_etablissement,
      CASE WHEN v_etablissement.est_public THEN 'PUBLIC' ELSE NULL END
    );
    IF COALESCE(v_mode->>'niveau', 'NON_PROPOSE') <> 'AUTORISE' THEN
      RETURN jsonb_build_object(
        'ok', false,
        'error', COALESCE(v_mode->>'source_libelle', 'Cette mission est proposée en salarié.'),
        'niveau', COALESCE(v_mode->>'niveau', 'NON_PROPOSE')
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'contrat', v_choix,
    'profession_requise', v_mission.profession_requise::text,
    'type_contrat_recherche', v_recherche
  );
END;
$$;


ALTER FUNCTION "public"."fn_resoudre_contrat_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_resoudre_contrat_mission"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_choix_contrat" "text") IS 'Lot 21 D4 — résout le contrat depuis la profession requise par la mission et sa matrice, jamais depuis le diplôme du profil.';



CREATE OR REPLACE FUNCTION "public"."fn_resoudre_litige"("p_litige_id" "uuid", "p_statut" "text", "p_resolution" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_litige RECORD;
    v_mission RECORD;
    v_score_avant NUMERIC;
    v_score_apres NUMERIC;
BEGIN
    IF NOT est_admin() THEN
        RETURN '{"error":"Seul l''administrateur peut résoudre un litige"}'::JSONB;
    END IF;
    IF p_statut NOT IN ('RESOLU_SOIGNANT', 'RESOLU_ETABLISSEMENT', 'RESOLU_ADMIN', 'FERME') THEN
        RETURN '{"error":"Statut invalide"}'::JSONB;
    END IF;

    SELECT *
      INTO v_litige
      FROM public.litiges
     WHERE id = p_litige_id
     FOR UPDATE;
    IF v_litige IS NULL THEN
      RETURN '{"error":"Litige introuvable"}'::jsonb;
    END IF;
    IF v_litige.statut = 'REVUE_ADMIN'
       OR v_litige.payload_modifications IS NOT NULL THEN
      RETURN jsonb_build_object(
        'error',
        'Accord structuré à traiter via le parcours financier administrateur'
      );
    END IF;
    IF v_litige.statut NOT IN (
      'OUVERT', 'EN_DISCUSSION', 'EN_MEDIATION', 'MEDIATION_EN_COURS'
    ) THEN
      RETURN jsonb_build_object(
        'error', 'Litige déjà résolu ou non modifiable'
      );
    END IF;

    SELECT * INTO v_mission
      FROM public.missions
     WHERE id = v_litige.mission_id;

    UPDATE litiges SET
        statut = p_statut,
        resolution = p_resolution,
        resolu_par = auth.uid(),
        resolu_le = NOW()
    WHERE id = p_litige_id;

    IF p_statut = 'RESOLU_SOIGNANT' THEN
        IF v_mission.statut = 'LITIGE' THEN
            UPDATE missions SET statut = 'TERMINEE', modifie_le = NOW() WHERE id = v_litige.mission_id;
        END IF;
        UPDATE presences SET valide_par_etablissement = TRUE, valide_le = NOW(), motif_litige = NULL
        WHERE mission_id = v_litige.mission_id AND soignant_id = v_litige.soignant_id;
        UPDATE soignants SET score_fiabilite = LEAST(100, COALESCE(score_fiabilite, 50) + 3), modifie_le = NOW()
        WHERE id = v_litige.soignant_id;

    ELSIF p_statut = 'RESOLU_ETABLISSEMENT' THEN
        IF v_mission.statut = 'LITIGE' THEN
            UPDATE missions SET statut = 'ANNULEE_PAR_ETABLISSEMENT', modifie_le = NOW() WHERE id = v_litige.mission_id;
        END IF;
        UPDATE presences SET valide_par_etablissement = FALSE, motif_litige = p_resolution
        WHERE mission_id = v_litige.mission_id AND soignant_id = v_litige.soignant_id;

        SELECT score_fiabilite INTO v_score_avant FROM soignants WHERE id = v_litige.soignant_id;

        UPDATE soignants SET total_litiges_perdus = COALESCE(total_litiges_perdus, 0) + 1, modifie_le = NOW()
        WHERE id = v_litige.soignant_id;

        v_score_apres := public.fn_recalculer_score_fiabilite_soignant(v_litige.soignant_id);

        PERFORM public.fn_ecrire_audit_safe(
          p_acteur_id := v_litige.soignant_id,
          p_type_acteur := 'SYSTEME',
          p_action := 'SCORE_FIABILITE_PENALITE_LITIGE',
          p_type_ressource := 'litige',
          p_id_ressource := p_litige_id,
          p_details := jsonb_build_object(
            'mission_id', v_litige.mission_id,
            'score_avant', v_score_avant,
            'score_apres', v_score_apres,
            'delta', COALESCE(v_score_apres, 0) - COALESCE(v_score_avant, 0)
          )
        );

    ELSIF p_statut = 'RESOLU_ADMIN' THEN
        IF v_mission.statut = 'LITIGE' THEN
            UPDATE missions SET statut = 'TERMINEE', modifie_le = NOW() WHERE id = v_litige.mission_id;
        END IF;
        UPDATE presences SET valide_par_etablissement = TRUE, valide_le = NOW()
        WHERE mission_id = v_litige.mission_id AND soignant_id = v_litige.soignant_id;

    ELSIF p_statut = 'FERME' THEN
        IF v_mission.statut = 'LITIGE' THEN
            UPDATE missions SET statut = 'TERMINEE', modifie_le = NOW() WHERE id = v_litige.mission_id;
        END IF;
        UPDATE presences SET valide_par_etablissement = TRUE, valide_le = NOW()
        WHERE mission_id = v_litige.mission_id AND soignant_id = v_litige.soignant_id;
    END IF;

    INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire) VALUES
    (v_litige.soignant_id, 'SYSTEM',
        CASE p_statut
            WHEN 'RESOLU_SOIGNANT' THEN 'Litige résolu en votre faveur ✅'
            WHEN 'RESOLU_ETABLISSEMENT' THEN 'Litige résolu en faveur de l''établissement'
            WHEN 'RESOLU_ADMIN' THEN 'Litige résolu par l''administrateur'
            WHEN 'FERME' THEN 'Litige clôturé ✅'
        END,
        COALESCE(p_resolution, 'Le litige a été résolu.'),
        '/soignant/missions', 'SOIGNANT'),
    (v_litige.etablissement_id, 'SYSTEM',
        CASE p_statut
            WHEN 'RESOLU_SOIGNANT' THEN 'Litige résolu en faveur du soignant'
            WHEN 'RESOLU_ETABLISSEMENT' THEN 'Litige résolu en votre faveur ✅'
            WHEN 'RESOLU_ADMIN' THEN 'Litige résolu par l''administrateur'
            WHEN 'FERME' THEN 'Litige clôturé ✅'
        END,
        COALESCE(p_resolution, 'Le litige a été résolu.'),
        '/etablissement/missions', 'ETABLISSEMENT');

    PERFORM fn_ecrire_audit_safe(
        auth.uid(), 'ADMIN_PLATEFORME', 'MISSION_LITIGE',
        'litige', p_litige_id, NULL,
        jsonb_build_object('resolution', p_statut, 'mission_id', v_litige.mission_id,
            'soignant_id', v_litige.soignant_id, 'details', p_resolution),
        NULL, 'rpc'
    );

    RETURN jsonb_build_object('success', true, 'statut', p_statut,
        'mission_statut', CASE
            WHEN p_statut = 'RESOLU_ETABLISSEMENT' THEN 'ANNULEE_PAR_ETABLISSEMENT'
            ELSE 'TERMINEE' END);
END;
$$;


ALTER FUNCTION "public"."fn_resoudre_litige"("p_litige_id" "uuid", "p_statut" "text", "p_resolution" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_resoudre_revue_verification_etablissement"("p_etablissement_id" "uuid", "p_service" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_service text := upper(btrim(COALESCE(p_service, '')));
  v_count integer;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;
  IF p_etablissement_id IS NULL
     OR v_service NOT IN (
       'VERIFY_PIECE_IDENTITE_ETAB',
       'VERIFY_JUSTIFICATIF_FONCTION',
       'VERIFY_FINESS_RECOUPEMENT',
       'VERIFY_RIB_ETABLISSEMENT'
     ) THEN
    RAISE EXCEPTION 'Resolution de revue etablissement invalide'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.file_revue_manuelle
  SET statut = 'RESOLU_AUTO',
      notes_resolution = 'Verification automatique reussie lors d une nouvelle tentative.',
      revu_le = COALESCE(revu_le, now()),
      resolu_le = now()
  WHERE type_entite = 'ETABLISSEMENT'
    AND id_entite = p_etablissement_id
    AND service_en_echec = v_service
    AND statut IN ('EN_ATTENTE', 'EN_COURS_REVUE', 'ESCALADE');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_resoudre_revue_verification_etablissement"("p_etablissement_id" "uuid", "p_service" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_retirer_candidature"("p_candidature_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_statut text;
  v_owner uuid;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT statut, soignant_id INTO v_statut, v_owner
  FROM public.candidatures WHERE id = p_candidature_id;

  IF v_statut IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Candidature introuvable');
  END IF;
  IF v_owner <> v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;
  IF v_statut <> 'EN_ATTENTE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'La candidature a déjà été traitée et ne peut plus être retirée ici.');
  END IF;

  DELETE FROM public.candidatures WHERE id = p_candidature_id;
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_retirer_candidature"("p_candidature_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_retirer_exclusion"("p_exclu_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_id uuid := auth.uid();
  v_exclusion_id uuid;
  v_type text;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT id, type_exclu_par INTO v_exclusion_id, v_type
  FROM exclusions
  WHERE exclu_par = v_caller_id AND exclu_id = p_exclu_id
  LIMIT 1;

  IF v_exclusion_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Exclusion introuvable');
  END IF;

  DELETE FROM exclusions WHERE id = v_exclusion_id;

  PERFORM fn_ecrire_audit_safe(
    v_caller_id,
    CASE WHEN v_type = 'ETABLISSEMENT' THEN 'ADMIN_ETABLISSEMENT' ELSE 'SOIGNANT' END,
    'EXCLUSION_SUPPRIMEE',
    'exclusion', p_exclu_id, NULL,
    jsonb_build_object('exclusion_id', v_exclusion_id),
    NULL, 'rpc'
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_retirer_exclusion"("p_exclu_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_reverifier_blocage_etab"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id uuid := mon_etablissement_id();
    v_paiements_retard_nb int;
    v_factures_retard_nb int;
BEGIN
    IF v_etab_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM etablissements WHERE id = v_etab_id AND bloque_auto_le IS NOT NULL) THEN
        RETURN jsonb_build_object('success', TRUE, 'debloque', FALSE, 'message', 'Votre compte n''est pas bloqué.');
    END IF;

    -- Mêmes critères que fn_gerer_blocage_etabs (seuil 45 jours)
    SELECT COUNT(*) INTO v_paiements_retard_nb
    FROM missions m
    WHERE m.etablissement_id = v_etab_id
      AND m.type_contrat_applique = 'SALARIE'
      AND m.statut = 'TERMINEE'
      AND m.fin_le < NOW() - INTERVAL '45 days'
      AND NOT EXISTS (
          SELECT 1 FROM paiements_soignant ps
          WHERE ps.mission_id = m.id AND ps.statut IN ('DECLARE', 'CONFIRME'));

    SELECT COUNT(*) INTO v_factures_retard_nb
    FROM factures f
    WHERE f.etablissement_id = v_etab_id
      AND f.statut IN ('EMISE', 'EN_RETARD')
      AND f.date_emission < NOW() - INTERVAL '45 days';

    IF v_paiements_retard_nb = 0 AND v_factures_retard_nb = 0 THEN
        UPDATE etablissements SET bloque_auto_le = NULL, bloque_auto_raisons = NULL WHERE id = v_etab_id;
        INSERT INTO historique_blocages_etablissements (etablissement_id, action)
        VALUES (v_etab_id, 'DEBLOCAGE');
        INSERT INTO notifications (destinataire_id, type, titre, corps, lien, type_destinataire)
        VALUES (v_etab_id, 'SYSTEM', 'Publication de missions reactivee',
            'Vos obligations sont régularisées : votre compte est à nouveau autorisé à publier des missions.',
            '/etablissement/tableau-de-bord', 'ETABLISSEMENT');
        RETURN jsonb_build_object('success', TRUE, 'debloque', TRUE);
    END IF;

    RETURN jsonb_build_object('success', TRUE, 'debloque', FALSE,
        'paiements_retard_nb', v_paiements_retard_nb,
        'factures_retard_nb', v_factures_retard_nb,
        'message', 'Des obligations restent en retard — régularisez-les puis réessayez.');
END;
$$;


ALTER FUNCTION "public"."fn_reverifier_blocage_etab"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoquer_api_key"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean := public.est_admin();
  v_target public.api_keys%ROWTYPE;
BEGIN
  SELECT * INTO v_target FROM public.api_keys WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Cle introuvable'); END IF;
  IF NOT v_is_admin AND (
    v_target.etablissement_id IS DISTINCT FROM public.mon_etablissement_id()
    OR NOT public.fn_a_permission_etablissement('api', v_target.etablissement_id)
  ) THEN RETURN jsonb_build_object('error', 'Acces refuse'); END IF;

  UPDATE public.api_keys SET actif = false WHERE id = p_id;
  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_actor,
    p_type_acteur := CASE WHEN v_is_admin THEN 'ADMIN_PLATEFORME' ELSE 'ADMIN_ETABLISSEMENT' END,
    p_action := 'API_KEY_REVOQUEE', p_type_ressource := 'api_key', p_id_ressource := p_id,
    p_details := jsonb_build_object('id', p_id)
  );
  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."fn_revoquer_api_key"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoquer_contrat_service"("p_motif" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid := public.mon_etablissement_id();
  v_sig_id uuid;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() OR v_etab_id IS NULL
     OR NOT public.fn_a_permission_etablissement('profil_etab', v_etab_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Accès refusé');
  END IF;
  IF NULLIF(btrim(p_motif), '') IS NULL OR length(btrim(p_motif)) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Motif de révocation requis (10 caractères minimum)');
  END IF;
  SELECT id INTO v_sig_id FROM public.contrats_service_signatures
  WHERE etablissement_id = v_etab_id AND revoked_at IS NULL FOR UPDATE;
  IF v_sig_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun contrat actif à révoquer');
  END IF;

  UPDATE public.contrats_service_signatures
  SET revoked_at = now(), motif_revocation = left(btrim(p_motif), 1000)
  WHERE id = v_sig_id;
  UPDATE public.etablissements
  SET contrat_service_signe = false,
      contrat_service_signe_le = NULL,
      peut_publier_missions = false,
      statut_verification = CASE WHEN statut_verification = 'VERIFIE' THEN 'EN_COURS' ELSE statut_verification END,
      verifie_le = NULL,
      verifie_par = NULL,
      modifie_le = now()
  WHERE id = v_etab_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid, p_type_acteur := 'ADMIN_ETABLISSEMENT',
    p_action := 'CONTRAT_SIGNE', p_type_ressource := 'etablissement',
    p_id_ressource := v_etab_id,
    p_details := jsonb_build_object('type', 'contrat_service_jolene_revoque', 'motif', left(btrim(p_motif), 1000))
  );
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_revoquer_contrat_service"("p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoquer_mandat_facturation"("p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_signature_id uuid;
  v_version text;
  v_signed_at timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM soignants
    WHERE id = v_uid AND mandat_facturation_signe = true
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Aucun mandat actif à révoquer');
  END IF;

  UPDATE mandats_facturation_signatures
  SET revoked_at = now()
  WHERE soignant_id = v_uid AND revoked_at IS NULL
  RETURNING id, version, signed_at INTO v_signature_id, v_version, v_signed_at;

  UPDATE soignants
  SET mandat_facturation_signe = false,
      mandat_facturation_signe_le = NULL,
      mandat_facturation_version = NULL
  WHERE id = v_uid;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'SOIGNANT',
    p_action := 'MANDAT_FACTURATION_REVOQUE',
    p_type_ressource := 'mandat_facturation',
    p_id_ressource := v_signature_id,
    p_details := jsonb_build_object(
      'version', v_version,
      'signed_at', v_signed_at,
      'revoked_at', now(),
      'motif', p_motif
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'signature_id', v_signature_id,
    'version', v_version,
    'revoked_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_revoquer_mandat_facturation"("p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoquer_membre"("p_membre_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_membre RECORD;
  v_perms jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  SELECT * INTO v_membre FROM public.membres_etablissement WHERE id = p_membre_id;
  IF v_membre IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'MEMBRE_INTROUVABLE');
  END IF;

  SELECT public.fn_mes_permissions_etab(v_membre.etablissement_id) INTO v_perms;
  IF NOT COALESCE((v_perms->'permissions'->>'gerer_equipe')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE');
  END IF;

  -- Empêcher la révocation du dernier PROPRIETAIRE
  IF v_membre.role = 'PROPRIETAIRE' AND NOT EXISTS (
    SELECT 1 FROM public.membres_etablissement
    WHERE etablissement_id = v_membre.etablissement_id
      AND role = 'PROPRIETAIRE'
      AND actif = true
      AND id != p_membre_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DERNIER_PROPRIETAIRE');
  END IF;

  UPDATE public.membres_etablissement
  SET actif = false, maj_le = now()
  WHERE id = p_membre_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details
  ) VALUES (
    v_uid, 'ADMIN_ETABLISSEMENT', 'MODIFICATION_PROFIL', 'membre_etablissement', p_membre_id,
    jsonb_build_object(
      'evenement', 'MEMBRE_REVOQUE',
      'role', v_membre.role,
      'etablissement_id', v_membre.etablissement_id
    )
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_revoquer_membre"("p_membre_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_revoquer_siret_liberal_soignant"("p_soignant_id" "uuid", "p_siret_attendu" "text", "p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_soignant record;
  v_code text := upper(left(btrim(COALESCE(p_code, '')), 100));
  v_audit jsonb;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  IF p_soignant_id IS NULL
     OR COALESCE(p_siret_attendu, '') !~ '^[0-9]{14}$'
     OR v_code = '' THEN
    RAISE EXCEPTION 'Revocation SIRET invalide' USING ERRCODE = '22023';
  END IF;

  SELECT s.siret_liberal, s.siret_liberal_verifie
    INTO v_soignant
  FROM public.soignants s
  WHERE s.id = p_soignant_id AND s.supprime_le IS NULL
  FOR UPDATE;

  IF NOT FOUND OR v_soignant.siret_liberal IS DISTINCT FROM p_siret_attendu THEN
    RETURN false;
  END IF;

  UPDATE public.soignants
  SET siret_liberal_verifie = false,
      siret_liberal_verifie_le = NULL,
      siret_liberal_raison_sociale = NULL,
      siret_liberal_coherence_identite = NULL,
      tous_documents_valides = false,
      modifie_le = now()
  WHERE id = p_soignant_id;

  v_audit := public.fn_ecrire_audit_safe(
    p_acteur_id := p_soignant_id,
    p_type_acteur := 'SYSTEME',
    p_action := 'VERIFICATION_DOCUMENT',
    p_type_ressource := 'soignant',
    p_id_ressource := p_soignant_id,
    p_details := jsonb_build_object(
      'sous_action', 'REVOQUER_SIRET_LIBERAL',
      'code', v_code,
      'siret_last4', right(p_siret_attendu, 4),
      'source', 'fn_revoquer_siret_liberal_soignant'
    )
  );
  IF COALESCE(v_audit @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Audit de revocation SIRET non ecrit';
  END IF;

  PERFORM public.fn_calculer_tous_documents_valides(p_soignant_id);
  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."fn_revoquer_siret_liberal_soignant"("p_soignant_id" "uuid", "p_siret_attendu" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rgpd_exporter_donnees_soignant"("p_soignant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := p_soignant_id;
  v_result jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Identifiant soignant manquant');
  END IF;

  -- Anti-IDOR : un utilisateur authentifié ne peut exporter que ses propres
  -- données. auth.uid() NULL (service_role / contexte admin) : pas de restriction.
  IF auth.uid() IS NOT NULL AND auth.uid() <> v_uid THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  SELECT jsonb_build_object(
    'export_date', NOW(),
    'utilisateur_id', v_uid,
    'profil', (SELECT to_jsonb(s.*) - 'numero_secu' - 'numero_securite_sociale' FROM soignants s WHERE id = v_uid),
    'missions', (SELECT COALESCE(jsonb_agg(to_jsonb(m.*) - 'taux_commission' - 'montant_commission_ht' - 'montant_commission_tva' - 'montant_commission_ttc' ORDER BY m.cree_le DESC), '[]'::jsonb) FROM missions m WHERE m.soignant_assigne_id = v_uid),
    'candidatures', (SELECT COALESCE(jsonb_agg(to_jsonb(c.*) ORDER BY c.cree_le DESC), '[]'::jsonb) FROM candidatures c WHERE c.soignant_id = v_uid),
    'presences', (SELECT COALESCE(jsonb_agg(to_jsonb(p.*) ORDER BY p.cree_le DESC), '[]'::jsonb) FROM presences p WHERE p.soignant_id = v_uid),
    'factures_honoraires', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',f.id,'numero_facture',f.numero_facture,'mission_id',f.mission_id,'etablissement_id',f.etablissement_id,'montant_ht',f.montant_ht,'montant_ttc',f.montant_ttc,'taux_tva',f.taux_tva,'exoneration_tva',f.exoneration_tva,'date_emission',f.date_emission,'date_echeance',f.date_echeance,'date_paiement',f.date_paiement,'statut',f.statut,'type_document',f.type_document,'pdf_s3_key',f.pdf_s3_key) ORDER BY f.date_emission DESC), '[]'::jsonb) FROM factures_honoraires f WHERE f.soignant_id = v_uid),
    'bulletins_paie', (SELECT COALESCE(jsonb_agg(to_jsonb(b.*) ORDER BY b.periode_debut DESC), '[]'::jsonb) FROM bulletins_paie b WHERE b.soignant_id = v_uid),
    'cotisations_sociales', (SELECT COALESCE(jsonb_agg(to_jsonb(c.*) ORDER BY c.calcule_le DESC), '[]'::jsonb) FROM cotisations_sociales c WHERE c.soignant_id = v_uid),
    'mandats_facturation', (SELECT COALESCE(jsonb_agg(jsonb_build_object('version',version,'signed_at',signed_at,'revoked_at',revoked_at,'ip_address',ip_address,'contenu_hash',contenu_hash) ORDER BY signed_at DESC), '[]'::jsonb) FROM mandats_facturation_signatures WHERE soignant_id = v_uid),
    'cessions_creance', (SELECT COALESCE(jsonb_agg(to_jsonb(c.*) ORDER BY c.signed_at DESC), '[]'::jsonb) FROM cessions_creance c WHERE c.soignant_id = v_uid),
    'factor_advances', (SELECT COALESCE(jsonb_agg(to_jsonb(fa.*) ORDER BY fa.cree_le DESC), '[]'::jsonb) FROM factor_advances fa WHERE fa.soignant_id = v_uid),
    'paiements_soignant', (SELECT COALESCE(jsonb_agg(to_jsonb(p.*) ORDER BY p.cree_le DESC), '[]'::jsonb) FROM paiements_soignant p WHERE p.soignant_id = v_uid),
    'contrats_mission', (SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'mission_id',mission_id,'type_contrat',type_contrat,'numero_contrat',numero_contrat,'statut',statut,'signature_soignant_le',signature_soignant_le,'signature_etablissement_le',signature_etablissement_le,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM contrats_mission WHERE soignant_id = v_uid),
    'documents', (SELECT COALESCE(jsonb_agg(jsonb_build_object('type',type_document,'libelle',libelle,'statut_verification',statut_verification,'valide_jusqua',valide_jusqua,'televerse_le',televerse_le) ORDER BY televerse_le DESC), '[]'::jsonb) FROM documents_soignants WHERE soignant_id = v_uid AND supprime_le IS NULL),
    'evaluations_recues', (SELECT COALESCE(jsonb_agg(jsonb_build_object('mission_id',mission_id,'note',note,'commentaire',commentaire,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM evaluations WHERE evalue_id = v_uid),
    'evaluations_donnees', (SELECT COALESCE(jsonb_agg(jsonb_build_object('mission_id',mission_id,'note',note,'commentaire',commentaire,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM evaluations WHERE evaluateur_id = v_uid),
    'messages_chat', (SELECT COALESCE(jsonb_agg(jsonb_build_object('conversation_id',conversation_id,'contenu',contenu,'cree_le',cree_le,'lu',lu) ORDER BY cree_le DESC), '[]'::jsonb) FROM messages_chat WHERE auteur_id = v_uid),
    'messages_litige', (SELECT COALESCE(jsonb_agg(jsonb_build_object('litige_id',litige_id,'type_auteur',type_auteur,'contenu',contenu,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM messages_litige WHERE auteur_id = v_uid),
    'messages_mission', (SELECT COALESCE(jsonb_agg(jsonb_build_object('mission_id',mission_id,'type_auteur',type_auteur,'contenu',contenu,'lu',lu,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM messages_mission WHERE auteur_id = v_uid),
    'notifications', (SELECT COALESCE(jsonb_agg(jsonb_build_object('type',type,'titre',titre,'corps',corps,'lue',lue,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM notifications WHERE destinataire_id = v_uid),
    'partages_rib', (SELECT COALESCE(jsonb_agg(jsonb_build_object('etablissement_id',etablissement_id,'mission_id',mission_id,'partage_le',partage_le,'consulte_le',consulte_le,'expire_le',expire_le,'actif',actif)), '[]'::jsonb) FROM partages_rib WHERE soignant_id = v_uid),
    'parrainages', (SELECT COALESCE(jsonb_agg(jsonb_build_object('role', CASE WHEN parrain_id = v_uid THEN 'parrain' ELSE 'filleul' END,'code_parrainage',code_parrainage,'statut',statut,'valide_le',valide_le,'cree_le',cree_le)), '[]'::jsonb) FROM parrainages WHERE parrain_id = v_uid OR filleul_id = v_uid),
    'preferences_notifications', (SELECT to_jsonb(p) - 'utilisateur_id' FROM preferences_notifications p WHERE utilisateur_id = v_uid),
    'preferences_notifications_par_evenement', (SELECT COALESCE(jsonb_agg(jsonb_build_object('type_evenement',type_evenement,'canal',canal,'actif',actif)), '[]'::jsonb) FROM preferences_notifications_par_evenement WHERE utilisateur_id = v_uid),
    'serie_email_envois', (SELECT COALESCE(jsonb_agg(jsonb_build_object('serie',serie,'etape',etape,'planifie_le',planifie_le,'envoye_le',envoye_le,'statut',statut,'skip_raison',skip_raison) ORDER BY planifie_le DESC), '[]'::jsonb) FROM serie_email_envois WHERE utilisateur_id = v_uid),
    'filtres_sauvegardes', (SELECT COALESCE(jsonb_agg(jsonb_build_object('nom',nom,'audience',audience,'filtres',filtres,'alerte_active',alerte_active,'frequence_alerte',frequence_alerte,'dernier_check_le',dernier_check_le,'nb_resultats_dernier_check',nb_resultats_dernier_check,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM filtres_sauvegardes WHERE utilisateur_id = v_uid),
    'favoris_etablissements', (SELECT COALESCE(jsonb_agg(jsonb_build_object('etablissement_id', etablissement_id, 'cree_le', cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM favoris_soignant_etab WHERE soignant_id = v_uid),
    'prevoyance_liste_attente', (SELECT COALESCE(jsonb_agg(jsonb_build_object('email', email, 'niveau_souhaite', niveau_souhaite, 'cree_le', cree_le, 'mis_a_jour_le', mis_a_jour_le)), '[]'::jsonb) FROM prevoyance_liste_attente WHERE soignant_id = v_uid),
    'notations_donnees', (SELECT COALESCE(jsonb_agg(jsonb_build_object('mission_id',mission_id,'sens',sens,'critere_1',critere_1,'critere_2',critere_2,'critere_3',critere_3,'critere_4',critere_4,'commentaire',commentaire,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM notations_missions WHERE notateur_id = v_uid),
    'notations_recues', (SELECT COALESCE(jsonb_agg(jsonb_build_object('mission_id',mission_id,'sens',sens,'critere_1',critere_1,'critere_2',critere_2,'critere_3',critere_3,'critere_4',critere_4,'commentaire',commentaire,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM notations_missions WHERE note_id = v_uid AND masque = false),
    'scoring_breakdown_historique', (SELECT COALESCE(jsonb_agg(jsonb_build_object('score_total',score_total,'niveau',niveau,'en_periode_probatoire',en_periode_probatoire,'composantes_actives_count',composantes_actives_count,'litiges_malus',litiges_malus,'absence_sans_prevenir_malus',absence_sans_prevenir_malus,'bonus_super_actif',bonus_super_actif,'raison_recalcul',raison_recalcul,'cree_le',cree_le) ORDER BY cree_le DESC), '[]'::jsonb) FROM scoring_breakdown WHERE soignant_id = v_uid)
  ) INTO v_result;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'SOIGNANT',
    p_action := 'RGPD_EXPORT_DONNEES',
    p_type_ressource := 'soignant',
    p_id_ressource := v_uid,
    p_details := jsonb_build_object('version', 'v10_restaure_couverture_v9_30_cles')
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_rgpd_exporter_donnees_soignant"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rgpd_exporter_rate_limited"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_allowed BOOLEAN;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Non authentifié');
    END IF;

    -- Garde-fou léger anti-abus : 30 exports / heure (au lieu de 2 / 24h).
    v_allowed := fn_verifier_rate_limit(v_user_id::TEXT, 'rgpd_export', 30, 3600);
    IF NOT v_allowed THEN
        RETURN jsonb_build_object('error', 'Trop d''exports en peu de temps. Réessayez dans quelques minutes.');
    END IF;

    RETURN fn_rgpd_exporter_donnees_soignant(v_user_id);
END;
$$;


ALTER FUNCTION "public"."fn_rgpd_exporter_rate_limited"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rgpd_purge_automatique_inactifs"() RETURNS TABLE("soignant_purge_id" "uuid", "derniere_activite" timestamp with time zone, "action_effectuee" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_date_limite TIMESTAMPTZ := NOW() - INTERVAL '2 years';
    v_sg RECORD;
BEGIN
    FOR v_sg IN
        SELECT s.id, s.email, s.derniere_activite_le
        FROM soignants s
        WHERE s.derniere_activite_le < v_date_limite
          AND s.supprime_le IS NULL
          AND NOT EXISTS (
              SELECT 1 FROM missions m
              WHERE m.soignant_assigne_id = s.id
                AND m.statut IN ('ASSIGNEE', 'EN_COURS', 'LITIGE')
          )
    LOOP
        -- Anonymiser les données personnelles
        UPDATE soignants SET
            prenom = 'ANONYMISE', nom = 'ANONYMISE',
            email = 'purge_' || v_sg.id || '@anonymise.local',
            telephone = NULL, date_naissance = NULL,
            adresse_lat = NULL, adresse_lng = NULL,
            supprime_le = NOW(), modifie_le = NOW()
        WHERE id = v_sg.id;

        -- Anonymiser les documents
        UPDATE documents_soignants SET
            s3_cle = 'PURGE', nom_fichier = 'PURGE',
            supprime_le = NOW(), modifie_le = NOW()
        WHERE soignant_id = v_sg.id;

        -- Anonymiser les données de terminaux dans les présences
        UPDATE presences SET
            arrivee_id_terminal = NULL, depart_id_terminal = NULL,
            arrivee_ip = NULL, depart_ip = NULL
        WHERE soignant_id = v_sg.id;

        -- Écrire dans le journal d'audit
        PERFORM fn_ecrire_audit(
            NULL, 'SYSTEME', 'RGPD_SUPPRESSION_DONNEES',
            'soignant', v_sg.id, NULL,
            jsonb_build_object(
                'motif', 'Purge automatique : inactivité > 2 ans',
                'derniere_activite', v_sg.derniere_activite_le
            )
        );

        INSERT INTO demandes_rgpd (demandeur_id, type_demandeur, type_demande, statut, motif, termine_le)
        VALUES (v_sg.id, 'SOIGNANT', 'PURGE_AUTOMATIQUE', 'TERMINEE',
                'Purge auto inactivité > 2 ans (Art. 17 RGPD)', NOW());

        soignant_purge_id := v_sg.id;
        derniere_activite := v_sg.derniere_activite_le;
        action_effectuee := 'ANONYMISE_ET_SUPPRIME';
        RETURN NEXT;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."fn_rgpd_purge_automatique_inactifs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_rib_etablissement_courant_verifie"("p_etablissement_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  SELECT EXISTS (
    SELECT 1 FROM public.etablissements e
    WHERE e.id = p_etablissement_id
      AND e.supprime_le IS NULL
      AND e.rib_ia_coherent IS TRUE
      AND e.rib_ia_verifie_le IS NOT NULL
      AND e.rib_verifie_s3_key = e.rib_s3_key
      AND e.rib_verifie_source_version IS NOT NULL
      AND e.iban_last4 ~ '^[A-Z0-9]{4}$'
  );
$_$;


ALTER FUNCTION "public"."fn_rib_etablissement_courant_verifie"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_role_etablissement_courant"("p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RETURN NULL;
  END IF;

  SELECT m.role INTO v_role
  FROM public.membres_etablissement m
  JOIN public.etablissements e ON e.id = m.etablissement_id
  WHERE m.user_id = v_uid
    AND m.actif = true
    AND e.supprime_le IS NULL
    AND (p_etablissement_id IS NULL OR m.etablissement_id = p_etablissement_id)
  ORDER BY CASE m.role WHEN 'PROPRIETAIRE' THEN 1 WHEN 'ADMIN_GROUPE' THEN 2 ELSE 3 END
  LIMIT 1;

  IF v_role IS NOT NULL THEN
    RETURN v_role;
  END IF;

  -- Compatibilite des comptes historiques : le compte Auth et la ligne
  -- etablissement partagent le meme UUID. Un simple etablissement_id stale
  -- dans app_metadata ne suffit jamais a recreer une appartenance revoquee.
  SELECT 'PROPRIETAIRE' INTO v_role
  FROM auth.users u
  JOIN public.etablissements e ON e.id = u.id
  WHERE u.id = v_uid
    AND u.raw_app_meta_data ->> 'role' IN ('ADMIN_ETABLISSEMENT', 'ETABLISSEMENT')
    AND e.supprime_le IS NULL
    AND (p_etablissement_id IS NULL OR e.id = p_etablissement_id)
  LIMIT 1;

  RETURN v_role;
END;
$$;


ALTER FUNCTION "public"."fn_role_etablissement_courant"("p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sanitiser_html"("p_html" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF p_html IS NULL THEN RETURN NULL; END IF;
    -- Supprimer les balises script
    p_html := regexp_replace(p_html, '<script[^>]*>.*?</script>', '', 'gi');
    -- Supprimer les événements JavaScript inline
    p_html := regexp_replace(p_html, '\son\w+\s*=\s*"[^"]*"', '', 'gi');
    p_html := regexp_replace(p_html, '\son\w+\s*=\s*''[^'']*''', '', 'gi');
    -- Supprimer les iframes
    p_html := regexp_replace(p_html, '<iframe[^>]*>.*?</iframe>', '', 'gi');
    -- Supprimer les liens javascript:
    p_html := regexp_replace(p_html, 'javascript\s*:', '', 'gi');
    -- Supprimer les data: URLs dans les attributs
    p_html := regexp_replace(p_html, 'data\s*:[^"''>\s]+', '', 'gi');
    RETURN p_html;
END;
$$;


ALTER FUNCTION "public"."fn_sanitiser_html"("p_html" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sauvegarder_profil"("p_data" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid UUID := auth.uid();
BEGIN
    IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
    
    PERFORM set_config('jolene.rpc_update', 'true', true);
    
    UPDATE soignants SET
        telephone = COALESCE((p_data->>'telephone'), telephone),
        date_naissance = COALESCE((p_data->>'date_naissance')::DATE, date_naissance),
        adresse_rue = COALESCE((p_data->>'adresse_rue'), adresse_rue),
        adresse_ville = COALESCE((p_data->>'adresse_ville'), adresse_ville),
        adresse_code_postal = COALESCE((p_data->>'adresse_code_postal'), adresse_code_postal),
        adresse_lat = COALESCE((p_data->>'adresse_lat')::NUMERIC, adresse_lat),
        adresse_lng = COALESCE((p_data->>'adresse_lng')::NUMERIC, adresse_lng),
        rayon_deplacement_km = COALESCE((p_data->>'rayon_deplacement_km')::INT, rayon_deplacement_km),
        numero_adeli = COALESCE((p_data->>'numero_adeli'), numero_adeli),
        avatar_url = COALESCE((p_data->>'avatar_url'), avatar_url),
        bio = COALESCE((p_data->>'bio'), bio),
        annees_experience = COALESCE((p_data->>'annees_experience')::INT, annees_experience),
        taux_horaire_minimum = COALESCE((p_data->>'taux_horaire_minimum')::NUMERIC, taux_horaire_minimum),
        type_exercice = COALESCE((p_data->>'type_exercice'), type_exercice),
        ville_recherche = COALESCE((p_data->>'ville_recherche'), ville_recherche),
        ville_urgence = COALESCE((p_data->>'ville_urgence'), ville_urgence),
        disponible_urgence = COALESCE((p_data->>'disponible_urgence')::BOOLEAN, disponible_urgence),
        urgence_rayon_km = COALESCE((p_data->>'urgence_rayon_km')::INT, urgence_rayon_km),
        attestation_cumul_activite = COALESCE((p_data->>'attestation_cumul_activite')::BOOLEAN, attestation_cumul_activite),
        est_cumul_activite = COALESCE((p_data->>'est_cumul_activite')::BOOLEAN, est_cumul_activite),
        est_salarie_etablissement = COALESCE((p_data->>'est_salarie_etablissement')::BOOLEAN, est_salarie_etablissement),
        consentement_gps = COALESCE((p_data->>'consentement_gps')::BOOLEAN, consentement_gps),
        types_contrat_acceptes = COALESCE((p_data->>'types_contrat_acceptes'), types_contrat_acceptes),
        specialites = CASE WHEN p_data ? 'specialites' THEN ARRAY(SELECT jsonb_array_elements_text(p_data->'specialites')) ELSE specialites END,
        attestation_cumul_le = CASE WHEN (p_data->>'attestation_cumul_activite')::BOOLEAN = TRUE THEN NOW() ELSE attestation_cumul_le END,
        consentement_gps_le = CASE WHEN p_data ? 'consentement_gps' THEN NOW() ELSE consentement_gps_le END,
        modifie_le = NOW()
    WHERE id = v_uid;
    
    RETURN jsonb_build_object('success', TRUE);
END;
$$;


ALTER FUNCTION "public"."fn_sauvegarder_profil"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_scanner_code_pointage"("p_code" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission RECORD; v_now timestamptz := now(); v_arrondi timestamptz;
  v_dernier_scan timestamptz; v_premier_prevu timestamptz; v_dernier_prevu timestamptz;
  v_est_en_avance boolean := false; v_validation_requise boolean := false;
  v_creneau_id uuid; v_creneau_debut timestamptz;
  v_new_code text; v_new_hmac text; v_scan_numero smallint;
BEGIN
  SELECT id, soignant_assigne_id, code_pointage_actif, prochain_type_scan, nb_scans, statut
  INTO v_mission FROM missions WHERE code_pointage_actif = p_code AND statut IN ('ASSIGNEE','EN_COURS') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Code de pointage invalide ou expiré.' USING ERRCODE = 'no_data_found'; END IF;
  IF auth.uid() != v_mission.soignant_assigne_id THEN RAISE EXCEPTION 'Vous n''êtes pas assigné(e) à cette mission.' USING ERRCODE = 'insufficient_privilege'; END IF;

  SELECT scanne_le INTO v_dernier_scan FROM scans_pointage WHERE mission_id = v_mission.id ORDER BY numero_scan DESC LIMIT 1;
  IF v_dernier_scan IS NOT NULL AND v_now - v_dernier_scan < INTERVAL '2 minutes' THEN
    RAISE EXCEPTION 'Scan déjà pris en compte. Prochain scan possible dans % secondes.',
      CEIL(EXTRACT(EPOCH FROM (v_dernier_scan + INTERVAL '2 minutes' - v_now))) USING ERRCODE = 'check_violation';
  END IF;

  v_scan_numero := COALESCE(v_mission.nb_scans, 0) + 1;
  v_arrondi := fn_arrondir_quart_heure(v_now);

  IF v_mission.prochain_type_scan = 'OUVERTURE' THEN
    -- GATE LÉGAL : aucun pointage d'arrivée/reprise sans contrat signé complet.
    IF NOT EXISTS (SELECT 1 FROM contrats_mission WHERE mission_id = v_mission.id AND statut = 'SIGNE_COMPLET') THEN
      RAISE EXCEPTION 'Le contrat doit être signé avant le pointage.' USING ERRCODE = 'check_violation';
    END IF;

    SELECT MIN(debut) INTO v_premier_prevu FROM mission_creneaux WHERE mission_id = v_mission.id AND type_creneau = 'PREVISIONNEL';
    IF v_premier_prevu IS NOT NULL AND v_now < v_premier_prevu - INTERVAL '15 minutes' THEN
      RAISE EXCEPTION 'Pointage trop tôt. Mission commence à %. Possible à partir de %.',
        TO_CHAR(v_premier_prevu AT TIME ZONE 'Europe/Paris', 'HH24:MI'),
        TO_CHAR((v_premier_prevu - INTERVAL '15 minutes') AT TIME ZONE 'Europe/Paris', 'HH24:MI') USING ERRCODE = 'check_violation';
    END IF;
    v_est_en_avance := (v_premier_prevu IS NOT NULL AND v_now < v_premier_prevu);
    SELECT MAX(fin) INTO v_dernier_prevu FROM mission_creneaux WHERE mission_id = v_mission.id AND type_creneau = 'PREVISIONNEL';
    v_validation_requise := v_est_en_avance OR (v_dernier_prevu IS NOT NULL AND v_now > v_dernier_prevu + INTERVAL '24 hours');

    INSERT INTO mission_creneaux (mission_id, debut, fin, est_pause, ordre, type_creneau)
    VALUES (v_mission.id, v_arrondi, NULL, false,
      COALESCE((SELECT MAX(ordre)+1 FROM mission_creneaux WHERE mission_id = v_mission.id), 1), 'EFFECTIF')
    RETURNING id INTO v_creneau_id;

    INSERT INTO scans_pointage (mission_id, soignant_id, code_saisi, numero_scan, type_scan, scanne_le, horodatage_arrondi, creneau_effectif_id, est_en_avance, validation_etab_requise, latitude, longitude, precision_gps_m, id_terminal, ip_address)
    VALUES (v_mission.id, auth.uid(), p_code, v_scan_numero, 'OUVERTURE', v_now, v_arrondi, v_creneau_id, v_est_en_avance, v_validation_requise,
      (p_metadata->>'latitude')::numeric, (p_metadata->>'longitude')::numeric, (p_metadata->>'precision_gps_m')::numeric, p_metadata->>'id_terminal', (p_metadata->>'ip_address')::inet);

    IF NOT EXISTS (SELECT 1 FROM presences WHERE mission_id = v_mission.id AND soignant_id = auth.uid()) THEN
      INSERT INTO presences (mission_id, soignant_id, pointage_arrivee_le,
        arrivee_lat, arrivee_lng, arrivee_precision_gps_m, arrivee_id_terminal, methode_pointage_arrivee)
      VALUES (v_mission.id, auth.uid(), v_arrondi,
        (p_metadata->>'latitude')::numeric, (p_metadata->>'longitude')::numeric,
        (p_metadata->>'precision_gps_m')::numeric, p_metadata->>'id_terminal', 'CODE');
      UPDATE missions SET statut = 'EN_COURS', modifie_le = now()
        WHERE id = v_mission.id AND statut = 'ASSIGNEE';
    ELSE
      UPDATE presences SET pointage_depart_le = NULL, modifie_le = now()
        WHERE mission_id = v_mission.id AND soignant_id = auth.uid();
    END IF;

  ELSE -- FERMETURE
    SELECT id, debut INTO v_creneau_id, v_creneau_debut FROM mission_creneaux
    WHERE mission_id = v_mission.id AND type_creneau = 'EFFECTIF' AND fin IS NULL ORDER BY debut DESC LIMIT 1;
    IF v_creneau_id IS NULL THEN RAISE EXCEPTION 'Aucun créneau effectif ouvert à fermer.' USING ERRCODE = 'no_data_found'; END IF;

    IF v_arrondi <= v_creneau_debut THEN
      v_arrondi := v_creneau_debut + INTERVAL '15 minutes';
    END IF;

    UPDATE mission_creneaux SET fin = v_arrondi WHERE id = v_creneau_id;

    SELECT MAX(fin) INTO v_dernier_prevu FROM mission_creneaux WHERE mission_id = v_mission.id AND type_creneau = 'PREVISIONNEL';
    v_validation_requise := (v_dernier_prevu IS NOT NULL AND v_now > v_dernier_prevu + INTERVAL '24 hours');

    INSERT INTO scans_pointage (mission_id, soignant_id, code_saisi, numero_scan, type_scan, scanne_le, horodatage_arrondi, creneau_effectif_id, est_en_avance, validation_etab_requise, latitude, longitude, precision_gps_m, id_terminal, ip_address)
    VALUES (v_mission.id, auth.uid(), p_code, v_scan_numero, 'FERMETURE', v_now, v_arrondi, v_creneau_id, false, v_validation_requise,
      (p_metadata->>'latitude')::numeric, (p_metadata->>'longitude')::numeric, (p_metadata->>'precision_gps_m')::numeric, p_metadata->>'id_terminal', (p_metadata->>'ip_address')::inet);

    UPDATE presences SET
      pointage_depart_le = v_arrondi,
      depart_lat = (p_metadata->>'latitude')::numeric,
      depart_lng = (p_metadata->>'longitude')::numeric,
      methode_pointage_depart = 'CODE',
      heures_reelles = (
        SELECT COALESCE(ROUND(SUM(EXTRACT(EPOCH FROM (fin - debut)) / 3600.0)::numeric, 2), 0)
        FROM mission_creneaux
        WHERE mission_id = v_mission.id AND type_creneau = 'EFFECTIF'
          AND fin IS NOT NULL AND NOT est_pause
      ),
      modifie_le = now()
    WHERE mission_id = v_mission.id AND soignant_id = auth.uid();
  END IF;

  v_new_code := lpad(floor(random() * 1000000)::text, 6, '0');
  WHILE EXISTS (SELECT 1 FROM missions WHERE code_pointage_actif = v_new_code AND id != v_mission.id AND statut IN ('ASSIGNEE','EN_COURS')) LOOP
    v_new_code := lpad(floor(random() * 1000000)::text, 6, '0');
  END LOOP;
  v_new_hmac := CASE WHEN current_setting('app.settings.hmac_secret', true) IS NOT NULL
    THEN encode(extensions.hmac(v_mission.id::text || ':' || v_new_code, current_setting('app.settings.hmac_secret', true), 'sha256'), 'hex') ELSE NULL END;

  UPDATE missions SET code_pointage_actif = v_new_code, code_pointage_hmac = v_new_hmac,
    prochain_type_scan = CASE WHEN v_mission.prochain_type_scan = 'OUVERTURE' THEN 'FERMETURE' ELSE 'OUVERTURE' END,
    nb_scans = v_scan_numero WHERE id = v_mission.id;

  RETURN jsonb_build_object('nouveau_code', v_new_code, 'nouveau_hmac', v_new_hmac,
    'type_scan_effectue', v_mission.prochain_type_scan,
    'prochain_type_scan', CASE WHEN v_mission.prochain_type_scan = 'OUVERTURE' THEN 'FERMETURE' ELSE 'OUVERTURE' END,
    'creneau_effectif_id', v_creneau_id, 'horodatage_arrondi', v_arrondi,
    'numero_scan', v_scan_numero, 'validation_etab_requise', v_validation_requise);
END;
$$;


ALTER FUNCTION "public"."fn_scanner_code_pointage"("p_code" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_score_etab_public"("p_etab_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_a_eu_mission BOOLEAN := false;
  v_nb_evals INT := 0;
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  SELECT EXISTS (SELECT 1 FROM missions WHERE etablissement_id = p_etab_id AND soignant_assigne_id = v_uid)
  INTO v_a_eu_mission;
  IF NOT v_a_eu_mission AND NOT est_admin() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  -- Gate Finding #2 : compte d'évaluations SOIGNANT_VERS_ETAB PUBLIÉES.
  SELECT COUNT(*) INTO v_nb_evals
  FROM notations_missions
  WHERE note_id = p_etab_id AND sens = 'SOIGNANT_VERS_ETAB'
    AND masque = false AND publie_le IS NOT NULL;

  SELECT jsonb_build_object(
    'etablissement_id', e.id, 'nom', e.nom,
    'nb_evaluations_publiees', v_nb_evals,
    -- score/niveau masqués tant que < 3 évaluations publiées (→ badge « Nouveau »)
    'score_qualite', CASE WHEN v_nb_evals >= 3 THEN e.score_qualite ELSE NULL END,
    'niveau', CASE WHEN v_nb_evals >= 3 THEN e.niveau ELSE NULL END
  ) INTO v_result FROM etablissements e WHERE e.id = p_etab_id;
  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."fn_score_etab_public"("p_etab_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_semaines_mission"("p_mission_id" "uuid") RETURNS TABLE("semaine_debut" "date", "heures" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  WITH bornes AS (
    SELECT
      date_trunc(
        'week',
        (CASE WHEN m.statut = 'TERMINEE'
          THEN COALESCE(m.debut_effectif, m.debut_le)
          ELSE m.debut_le
        END) AT TIME ZONE 'Europe/Paris'
      )::date AS premiere,
      date_trunc(
        'week',
        ((CASE WHEN m.statut = 'TERMINEE'
          THEN COALESCE(m.fin_effective, m.fin_le)
          ELSE m.fin_le
        END) - interval '1 microsecond') AT TIME ZONE 'Europe/Paris'
      )::date AS derniere
    FROM public.missions m
    WHERE m.id = p_mission_id
  ), semaines AS (
    SELECT (b.premiere + (n * 7))::date AS semaine_debut
    FROM bornes b
    CROSS JOIN LATERAL generate_series(
      0, ((b.derniere - b.premiere) / 7)::integer
    ) AS n
  )
  SELECT s.semaine_debut, h.heures
  FROM semaines s
  CROSS JOIN LATERAL (
    SELECT public.fn_heures_mission_semaine(
      p_mission_id, s.semaine_debut
    ) AS heures
  ) h
  WHERE h.heures > 0
  ORDER BY s.semaine_debut;
$$;


ALTER FUNCTION "public"."fn_semaines_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_service_finaliser_heures_externes"("p_id" "uuid", "p_snapshot_source" "jsonb", "p_empreinte_preuve_sha256" "text", "p_verdict" "text", "p_rejet_conclusif" boolean, "p_heures_extraites" integer, "p_coherence" boolean, "p_resultat_ia" "jsonb", "p_commentaire" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'storage', 'extensions'
    AS $_$
DECLARE
  v_ligne public.heures_externes_soignants%ROWTYPE;
  v_snapshot jsonb;
  v_empreinte_snapshot text;
  v_statut text;
  v_source text;
  v_preuve_dupliquee boolean;
  v_row_count integer;
  v_commentaire text;
  v_resultat jsonb;
  v_guc_precedent text := COALESCE(
    current_setting('jolene.heures_externes_server_update', true), ''
  );
BEGIN
  IF COALESCE(
       auth.jwt() ->> 'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Finaliseur réservé au service_role'
      USING ERRCODE = '42501';
  END IF;

  IF p_verdict NOT IN ('EN_ATTENTE', 'REJETE') THEN
    RAISE EXCEPTION 'Le verdict automatique ne peut jamais être VALIDE'
      USING ERRCODE = '22023';
  END IF;
  IF p_empreinte_preuve_sha256 IS NULL
     OR p_empreinte_preuve_sha256 !~ '^[0-9a-f]{64}$'
     OR p_resultat_ia IS NULL
     OR jsonb_typeof(p_resultat_ia) IS DISTINCT FROM 'object'
     OR pg_column_size(p_resultat_ia) > 65536
     OR char_length(COALESCE(p_commentaire, '')) > 1000
     OR (
       p_heures_extraites IS NOT NULL
       AND (p_heures_extraites < 0 OR p_heures_extraites > 10000)
     ) THEN
    RAISE EXCEPTION 'Résultat de vérification invalide'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ligne
  FROM public.heures_externes_soignants
  WHERE id = p_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error_code', 'INTROUVABLE'
    );
  END IF;

  v_snapshot := private.fn_snapshot_heures_externes(v_ligne);
  v_empreinte_snapshot := private.fn_empreinte_snapshot_heures_externes(v_ligne);
  IF p_snapshot_source IS DISTINCT FROM v_snapshot
     OR v_ligne.statut_validation IS DISTINCT FROM 'EN_ATTENTE' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'CONFLIT_SOURCE',
      'error', 'La déclaration a changé pendant la vérification.'
    );
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('heures-preuve:' || p_empreinte_preuve_sha256, 0)
  );
  SELECT EXISTS (
    SELECT 1
    FROM public.heures_externes_soignants autre
    WHERE autre.id <> v_ligne.id
      AND autre.empreinte_preuve_sha256 = p_empreinte_preuve_sha256
      AND autre.statut_validation IN ('EN_ATTENTE', 'VALIDE')
  ) INTO v_preuve_dupliquee;

  -- Même un résultat IA entièrement concordant reste en revue humaine au
  -- lancement. REJETE n'est accepté que pour une invalidité concluante fournie
  -- explicitement par le service (signature/type de fichier ou non-attestation
  -- lisible à haute confiance).
  IF p_verdict = 'REJETE' AND COALESCE(p_rejet_conclusif, false) THEN
    v_statut := 'REJETE';
    v_source := 'IA_REJET_CONCLUSIF';
  ELSE
    v_statut := 'EN_ATTENTE';
    v_source := 'IA_REVUE';
  END IF;

  v_commentaire := CASE
    WHEN v_preuve_dupliquee AND v_statut = 'EN_ATTENTE' THEN
      'Cette preuve binaire est déjà rattachée à une autre déclaration. Revue manuelle obligatoire.'
    ELSE NULLIF(left(btrim(COALESCE(p_commentaire, '')), 1000), '')
  END;
  v_resultat := p_resultat_ia || jsonb_build_object(
    'decision_serveur', v_statut,
    'rejet_conclusif_serveur',
      (v_statut = 'REJETE' AND COALESCE(p_rejet_conclusif, false)),
    'preuve_dupliquee_serveur', v_preuve_dupliquee,
    'empreinte_snapshot_source', v_empreinte_snapshot,
    'regle_version', 'heures-externes-p0-2026-07-14'
  );

  PERFORM set_config('jolene.heures_externes_server_update', 'true', true);
  UPDATE public.heures_externes_soignants h
  SET statut_validation = v_statut,
      heures_extraites_ia = p_heures_extraites,
      coherence_ia = p_coherence,
      resultat_ia = v_resultat,
      commentaire_validation = v_commentaire,
      verifie_ia_le = now(),
      valide_par = NULL,
      valide_le = NULL,
      empreinte_preuve_sha256 = p_empreinte_preuve_sha256,
      source_validation_serveur = v_source,
      empreinte_snapshot_source = v_empreinte_snapshot,
      mis_a_jour_le = now()
  WHERE h.id = v_ligne.id
    AND h.version_source = v_ligne.version_source
    AND h.statut_validation = 'EN_ATTENTE'
    AND private.fn_empreinte_snapshot_heures_externes(h) = v_empreinte_snapshot;
  GET DIAGNOSTICS v_row_count = ROW_COUNT;
  PERFORM set_config(
    'jolene.heures_externes_server_update', v_guc_precedent, true
  );
  IF v_row_count <> 1 THEN
    RAISE EXCEPTION 'Conflit CAS pendant la finalisation des heures externes'
      USING ERRCODE = '40001';
  END IF;

  -- VERIFICATION_DOCUMENT est une action autorisée. Pas de wrapper safe : si
  -- l'audit échoue, le verdict est annulé dans la même transaction.
  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    cle_s3_ressource, details, navigateur_acteur
  ) VALUES (
    v_ligne.soignant_id, 'SYSTEME', 'VERIFICATION_DOCUMENT',
    'heures_externes_soignants', v_ligne.id, v_ligne.attestation_url,
    jsonb_build_object(
      'sous_action', 'HEURES_EXTERNES_VERIFICATION_AUTO',
      'decision', v_statut,
      'rejet_conclusif', (v_statut = 'REJETE'),
      'preuve_dupliquee', v_preuve_dupliquee,
      'heures_declarees', v_ligne.heures_declarees,
      'heures_extraites', p_heures_extraites,
      'empreinte_snapshot_source', v_empreinte_snapshot
    ),
    'edge-function/verify-heures-externes'
  );

  RETURN jsonb_build_object(
    'success', true,
    'statut', v_statut,
    'preuve_dupliquee', v_preuve_dupliquee,
    'empreinte_snapshot_source', v_empreinte_snapshot
  );
END;
$_$;


ALTER FUNCTION "public"."fn_service_finaliser_heures_externes"("p_id" "uuid", "p_snapshot_source" "jsonb", "p_empreinte_preuve_sha256" "text", "p_verdict" "text", "p_rejet_conclusif" boolean, "p_heures_extraites" integer, "p_coherence" boolean, "p_resultat_ia" "jsonb", "p_commentaire" "text") OWNER TO "postgres";


