    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  NEW.mis_a_jour_le = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_set_mis_a_jour_le"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_set_user_role"("p_user_id" "uuid", "p_role" "text", "p_etablissement_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Vérification : cette fonction ne doit être appelée que par service_role
    -- En contexte authenticated, auth.uid() est défini
    -- En contexte service_role, auth.uid() est NULL
    IF auth.uid() IS NOT NULL THEN
        -- C'est un utilisateur authentifié qui essaie d'appeler → REFUS
        RAISE EXCEPTION 'INTERDIT : seul le serveur peut attribuer des rôles.';
    END IF;

    IF p_role NOT IN ('SOIGNANT', 'ADMIN_ETABLISSEMENT', 'ADMIN_PLATEFORME') THEN
        RAISE EXCEPTION 'Rôle invalide.';
    END IF;

    UPDATE auth.users SET raw_app_meta_data =
        COALESCE(raw_app_meta_data, '{}'::jsonb)
        || jsonb_build_object('role', p_role)
        || CASE WHEN p_etablissement_id IS NOT NULL
            THEN jsonb_build_object('etablissement_id', p_etablissement_id::TEXT)
            ELSE '{}'::jsonb END
    WHERE id = p_user_id;
END;
$$;


ALTER FUNCTION "public"."fn_set_user_role"("p_user_id" "uuid", "p_role" "text", "p_etablissement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signaler_notation"("p_notation_id" "uuid", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_etab_id UUID := mon_etablissement_id();
  v_notation RECORD;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT * INTO v_notation FROM notations_missions WHERE id = p_notation_id;
  IF v_notation IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Notation introuvable');
  END IF;

  -- Seule la cible (note_id) peut signaler — soit soignant, soit étab via mon_etablissement_id()
  IF v_notation.note_id <> v_uid AND v_notation.note_id <> COALESCE(v_etab_id, '00000000-0000-0000-0000-000000000000'::uuid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Vous ne pouvez signaler que les notations vous concernant');
  END IF;

  IF v_notation.signale = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'Notation déjà signalée');
  END IF;

  UPDATE notations_missions SET signale = true, mis_a_jour_le = NOW()
  WHERE id = p_notation_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := CASE WHEN v_etab_id IS NOT NULL THEN 'ADMIN_ETABLISSEMENT' ELSE 'SOIGNANT' END,
    p_action := 'NOTATION_SIGNALE',
    p_type_ressource := 'notation',
    p_id_ressource := p_notation_id,
    p_details := jsonb_build_object('motif', p_motif, 'mission_id', v_notation.mission_id)
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_signaler_notation"("p_notation_id" "uuid", "p_motif" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signaler_utilisateur"("p_cible_id" "uuid", "p_cible_type" "text", "p_categorie" "text", "p_motif" "text", "p_mission_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_me uuid := auth.uid();
  v_signaleur_type text;
  v_id uuid;
  v_admin RECORD;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Non authentifié'); END IF;
  IF p_cible_type NOT IN ('SOIGNANT','ETABLISSEMENT') THEN RETURN jsonb_build_object('success', false, 'error', 'Cible invalide'); END IF;
  IF p_categorie IS NULL OR p_categorie NOT IN ('COMPORTEMENT_INAPPROPRIE','FRAUDE_SUSPECTEE','FAUX_DOCUMENT','NON_PROFESSIONNALISME','SECURITE_DANGER','USURPATION_IDENTITE','AUTRE') THEN RETURN jsonb_build_object('success', false, 'error', 'Catégorie invalide'); END IF;
  IF p_motif IS NULL OR length(trim(p_motif)) < 10 THEN RETURN jsonb_build_object('success', false, 'error', 'Motif obligatoire (10 caractères minimum).'); END IF;
  IF p_cible_id = v_me THEN RETURN jsonb_build_object('success', false, 'error', 'Vous ne pouvez pas vous signaler vous-même.'); END IF;
  IF EXISTS (SELECT 1 FROM soignants WHERE id = v_me) THEN v_signaleur_type := 'SOIGNANT';
  ELSIF EXISTS (SELECT 1 FROM etablissements WHERE id = v_me) THEN v_signaleur_type := 'ETABLISSEMENT';
  ELSE RETURN jsonb_build_object('success', false, 'error', 'Profil signaleur inconnu'); END IF;
  INSERT INTO public.signalements (signaleur_id, signaleur_type, cible_id, cible_type, categorie, motif, mission_id)
  VALUES (v_me, v_signaleur_type, p_cible_id, p_cible_type, p_categorie, trim(p_motif), p_mission_id) RETURNING id INTO v_id;
  FOR v_admin IN SELECT id FROM auth.users WHERE raw_app_meta_data->>'role' = 'ADMIN_PLATEFORME' LOOP
    INSERT INTO public.notifications (destinataire_id, type_destinataire, type, titre, corps, type_ressource, id_ressource)
    VALUES (v_admin.id, 'ADMIN', 'SYSTEM', '🚩 Nouveau signalement utilisateur',
      'Un ' || lower(v_signaleur_type) || ' a signalé un ' || lower(p_cible_type) || ' (' || p_categorie || ').',
      'signalement', v_id);
  END LOOP;
  PERFORM public.fn_ecrire_audit_safe(p_acteur_id := v_me, p_type_acteur := v_signaleur_type,
    p_action := 'SIGNALEMENT_UTILISATEUR', p_type_ressource := 'signalement', p_id_ressource := v_id,
    p_details := jsonb_build_object('cible_id', p_cible_id, 'cible_type', p_cible_type, 'categorie', p_categorie));
  RETURN jsonb_build_object('success', true, 'signalement_id', v_id);
END; $$;


ALTER FUNCTION "public"."fn_signaler_utilisateur"("p_cible_id" "uuid", "p_cible_type" "text", "p_categorie" "text", "p_motif" "text", "p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_attestation_sante"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_ip inet;
  v_user_agent text;
  v_headers jsonb;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM soignants WHERE id = v_user_id) THEN
    RETURN jsonb_build_object('error', 'Soignant introuvable');
  END IF;

  UPDATE soignants
  SET attestation_sante_signee_le = now(),
      modifie_le = now()
  WHERE id = v_user_id;

  -- Capture IP + User-Agent pour non-répudiation (signature médicale)
  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
    v_ip := NULLIF(trim(split_part(coalesce(v_headers->>'x-forwarded-for', ''), ',', 1)), '')::inet;
    v_user_agent := NULLIF(v_headers->>'user-agent', '');
  EXCEPTION WHEN OTHERS THEN
    v_ip := NULL; v_user_agent := NULL;
  END;

  PERFORM fn_ecrire_audit(
    v_user_id, 'SOIGNANT', 'ATTESTATION_SANTE_SIGNEE',
    'soignant', v_user_id, NULL,
    jsonb_build_object(
      'vaccinations', true,
      'medecine_travail', true,
      'horodatage', now()
    ),
    v_ip, v_user_agent
  );

  RETURN jsonb_build_object('success', true, 'signe_le', now());
END;
$$;


ALTER FUNCTION "public"."fn_signer_attestation_sante"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_cession_creance"("p_facture_honoraire_id" "uuid", "p_version" "text", "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_contenu_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_facture RECORD;
    v_existing_id UUID;
    v_cession_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN '{"error":"Non authentifié"}'::JSONB;
    END IF;

    -- Vérifier que la facture appartient bien au soignant
    SELECT * INTO v_facture
    FROM factures_honoraires
    WHERE id = p_facture_honoraire_id AND soignant_id = v_user_id;

    IF v_facture IS NULL THEN
        RETURN '{"error":"Facture introuvable ou non autorisée"}'::JSONB;
    END IF;

    -- Une seule cession par facture
    SELECT id INTO v_existing_id FROM cessions_creance WHERE facture_honoraire_id = p_facture_honoraire_id;
    IF v_existing_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'cession_id', v_existing_id, 'message', 'Cession déjà existante');
    END IF;

    INSERT INTO cessions_creance (
        soignant_id, facture_honoraire_id, montant,
        version_texte, contenu_hash, ip_address, user_agent
    ) VALUES (
        v_user_id, p_facture_honoraire_id, v_facture.montant_ttc,
        p_version, p_contenu_hash, p_ip, p_user_agent
    ) RETURNING id INTO v_cession_id;

    RETURN jsonb_build_object('success', true, 'cession_id', v_cession_id);
END;
$$;


ALTER FUNCTION "public"."fn_signer_cession_creance"("p_facture_honoraire_id" "uuid", "p_version" "text", "p_ip" "text", "p_user_agent" "text", "p_contenu_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_contrat_etablissement"("p_contrat_id" "uuid", "p_signature_image" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_contrat RECORD;
BEGIN
    SELECT * INTO v_contrat FROM contrats_mission WHERE id = p_contrat_id;
    IF v_contrat IS NULL THEN RETURN '{"error":"Contrat introuvable"}'::JSONB; END IF;
    IF v_contrat.etablissement_id != mon_etablissement_id() AND NOT est_admin() THEN
        RETURN '{"error":"Ce contrat ne vous concerne pas"}'::JSONB;
    END IF;
    IF v_contrat.signature_etablissement = TRUE THEN RETURN '{"error":"Déjà signé"}'::JSONB; END IF;

    UPDATE contrats_mission SET
        signature_etablissement = TRUE,
        signature_etablissement_le = NOW(),
        signature_image_etablissement = p_signature_image,
        signature_navigateur_etablissement = current_setting('request.headers', true)::JSON->>'user-agent',
        statut = CASE
            WHEN signature_soignant = TRUE THEN 'SIGNE_COMPLET'
            ELSE 'SIGNE_ETABLISSEMENT'
        END,
        modifie_le = NOW()
    WHERE id = p_contrat_id;

    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_signer_contrat_etablissement"("p_contrat_id" "uuid", "p_signature_image" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_contrat_otp"("p_contrat_id" "uuid", "p_otp_code" "text", "p_hash_document" "text" DEFAULT NULL::"text", "p_signature_image" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sig RECORD;
  v_contrat RECORD;
  v_expected_hash text;
  v_role text;
  v_ip inet;
  v_ua text;
  v_other_signed boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE', 'error', 'Non authentifié');
  END IF;

  SELECT cm.signature_soignant, cm.signature_etablissement, cm.statut
  INTO v_contrat
  FROM public.contrats_mission cm WHERE cm.id = p_contrat_id;

  IF v_contrat IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CONTRAT_INTROUVABLE', 'error', 'Contrat introuvable');
  END IF;

  SELECT * INTO v_sig FROM public.signatures_contrats
  WHERE contrat_id = p_contrat_id AND signataire_user_id = v_uid
  ORDER BY cree_le DESC LIMIT 1;

  IF v_sig IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'OTP_NON_DEMANDE',
      'error', 'Aucune demande OTP en cours. Cliquez d''abord sur "Recevoir un code SMS".');
  END IF;

  IF v_sig.statut_signature = 'signe' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_SIGNE',
      'error', 'Vous avez déjà signé ce contrat le ' ||
        COALESCE(to_char(v_sig.signe_a, 'DD/MM/YYYY HH24:MI'), '—') || '.',
      'signe_a', v_sig.signe_a);
  END IF;

  -- Ordre obligatoire (vérif redondante avec fn_envoyer_otp_signature)
  IF v_sig.signataire_role = 'etablissement' AND v_contrat.signature_soignant IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ETAB_AVANT_SOIGNANT',
      'error', 'Le soignant doit signer en premier.');
  END IF;

  IF v_sig.otp_tentatives >= 5 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'TROP_DE_TENTATIVES',
      'error', 'Trop de tentatives. Renvoyez un nouveau code SMS.');
  END IF;

  IF v_sig.otp_envoye_a IS NULL OR v_sig.otp_envoye_a < NOW() - INTERVAL '10 minutes' THEN
    UPDATE public.signatures_contrats
    SET statut_signature = 'expire', modifie_le = NOW()
    WHERE id = v_sig.id;
    RETURN jsonb_build_object('success', false, 'error_code', 'OTP_EXPIRE',
      'error', 'Code expiré. Renvoyez un nouveau code SMS.');
  END IF;

  v_expected_hash := encode(digest(p_otp_code || '|' || p_contrat_id::text || '|' || v_uid::text, 'sha256'), 'hex');
  IF v_expected_hash != v_sig.otp_code_hash THEN
    UPDATE public.signatures_contrats
    SET otp_tentatives = otp_tentatives + 1, modifie_le = NOW()
    WHERE id = v_sig.id;
    RETURN jsonb_build_object('success', false, 'error_code', 'OTP_INCORRECT',
      'error', 'Code incorrect.',
      'tentatives_restantes', 5 - (v_sig.otp_tentatives + 1));
  END IF;

  v_role := v_sig.signataire_role;
  v_ip := NULLIF(current_setting('request.headers', true)::jsonb->>'x-forwarded-for', '')::inet;
  v_ua := current_setting('request.headers', true)::jsonb->>'user-agent';

  UPDATE public.signatures_contrats
  SET statut_signature = 'signe',
      otp_valide_a = NOW(),
      signe_a = NOW(),
      ip_signature = v_ip,
      user_agent = v_ua,
      hash_document = p_hash_document,
      signature_image_base64 = p_signature_image,
      modifie_le = NOW(),
      audit_trail = COALESCE(audit_trail, '{}'::jsonb)
        || jsonb_build_object('signe_le', NOW()::text, 'tentatives', v_sig.otp_tentatives + 1)
  WHERE id = v_sig.id;

  IF v_role = 'soignant' THEN
    UPDATE public.contrats_mission
    SET signature_soignant = true,
        signature_soignant_le = NOW(),
        signature_ip_soignant = COALESCE(v_ip, signature_ip_soignant),
        signature_navigateur_soignant = COALESCE(v_ua, signature_navigateur_soignant),
        signature_image_soignant = COALESCE(p_signature_image, signature_image_soignant),
        mode_signature = 'JOLENE_OTP'
    WHERE id = p_contrat_id;
  ELSE
    UPDATE public.contrats_mission
    SET signature_etablissement = true,
        signature_etablissement_le = NOW(),
        signature_ip_etablissement = COALESCE(v_ip, signature_ip_etablissement),
        signature_navigateur_etablissement = COALESCE(v_ua, signature_navigateur_etablissement),
        signature_image_etablissement = COALESCE(p_signature_image, signature_image_etablissement),
        mode_signature = 'JOLENE_OTP'
    WHERE id = p_contrat_id;
  END IF;

  SELECT (signature_soignant = true AND signature_etablissement = true) INTO v_other_signed
  FROM public.contrats_mission WHERE id = p_contrat_id;

  IF v_other_signed THEN
    UPDATE public.contrats_mission
    SET statut = 'SIGNE_COMPLET', modifie_le = NOW()
    WHERE id = p_contrat_id AND statut != 'SIGNE_COMPLET';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'contrat_complet', v_other_signed
  );
END;
$$;


ALTER FUNCTION "public"."fn_signer_contrat_otp"("p_contrat_id" "uuid", "p_otp_code" "text", "p_hash_document" "text", "p_signature_image" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_contrat_service"("p_version" "text", "p_ip" "text", "p_user_agent" "text", "p_contenu_hash" "text", "p_signature_s3_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'storage', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid := public.mon_etablissement_id();
  v_etab record;
  v_headers jsonb;
  v_real_ip text;
  v_user_agent text;
  v_canonical_hash text;
  v_signature_le timestamptz;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() OR v_etab_id IS NULL
     OR NOT public.fn_a_permission_etablissement('profil_etab', v_etab_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Accès refusé');
  END IF;
  IF p_version IS DISTINCT FROM 'v1.0' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Version du contrat non reconnue');
  END IF;
  IF p_signature_s3_key IS NULL
     OR p_signature_s3_key NOT LIKE v_uid::text || '/signatures/contrat-service-%'
     OR p_signature_s3_key LIKE '%..%'
     OR NOT EXISTS (
       SELECT 1 FROM storage.objects o
       WHERE o.bucket_id = 'jolene-documents'
         AND o.name = p_signature_s3_key
         AND COALESCE(o.metadata->>'mimetype', '') IN ('image/png', 'image/jpeg')
     ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Signature électronique manquante ou invalide');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_etab_id::text, 0));
  IF EXISTS (
    SELECT 1 FROM public.contrats_service_signatures
    WHERE etablissement_id = v_etab_id AND revoked_at IS NULL
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contrat déjà signé et actif');
  END IF;

  SELECT id, nom, siret, type, adresse_rue, adresse_code_postal,
         adresse_ville, email_contact, representant_nom, representant_prenom
    INTO v_etab
  FROM public.etablissements
  WHERE id = v_etab_id AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Établissement introuvable'); END IF;

  -- Cette empreinte ne dépend d'aucune valeur envoyée par le navigateur. Elle
  -- lie la version du modèle et les données légales relues en base.
  v_canonical_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'template_fingerprint', '11202a832970b69fcccbcdb95f079cd3d2d4b7bfbf4dc39d64ff961100c547f8',
    'version', 'v1.0',
    'etablissement_id', v_etab.id,
    'nom', COALESCE(v_etab.nom, ''),
    'siret', COALESCE(v_etab.siret, ''),
    'type', COALESCE(v_etab.type::text, ''),
    'adresse_rue', COALESCE(v_etab.adresse_rue, ''),
    'adresse_code_postal', COALESCE(v_etab.adresse_code_postal, ''),
    'adresse_ville', COALESCE(v_etab.adresse_ville, ''),
    'email_contact', COALESCE(v_etab.email_contact, ''),
    'representant_nom', COALESCE(v_etab.representant_nom, ''),
    'representant_prenom', COALESCE(v_etab.representant_prenom, '')
  )::text, 'UTF8'), 'sha256'), 'hex');

  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_headers := '{}'::jsonb;
  END;
  v_real_ip := COALESCE(
    NULLIF(v_headers->>'cf-connecting-ip', ''),
    NULLIF(split_part(COALESCE(v_headers->>'x-forwarded-for', ''), ',', 1), ''),
    NULLIF(v_headers->>'x-real-ip', ''),
    'unknown'
  );
  v_user_agent := left(COALESCE(NULLIF(v_headers->>'user-agent', ''), NULLIF(p_user_agent, ''), 'unknown'), 500);

  INSERT INTO public.contrats_service_signatures
    (etablissement_id, version, ip_address, user_agent, contenu_hash, signature_s3_key)
  VALUES
    (v_etab_id, 'v1.0', v_real_ip, v_user_agent, v_canonical_hash, p_signature_s3_key)
  RETURNING signed_at INTO v_signature_le;

  UPDATE public.etablissements
  SET contrat_service_signe = true,
      contrat_service_signe_le = v_signature_le,
      modifie_le = now()
  WHERE id = v_etab_id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'ADMIN_ETABLISSEMENT',
    p_action := 'CONTRAT_SIGNE',
    p_type_ressource := 'etablissement',
    p_id_ressource := v_etab_id,
    p_details := jsonb_build_object(
      'type', 'contrat_service_jolene', 'version', 'v1.0',
      'empreinte_serveur', true, 'has_signature_image', true
    )
  );
  RETURN jsonb_build_object('success', true, 'version', 'v1.0', 'contenu_hash', v_canonical_hash);
END;
$$;


ALTER FUNCTION "public"."fn_signer_contrat_service"("p_version" "text", "p_ip" "text", "p_user_agent" "text", "p_contenu_hash" "text", "p_signature_s3_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_contrat_soignant"("p_contrat_id" "uuid", "p_signature_image" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_contrat RECORD;
BEGIN
    SELECT * INTO v_contrat FROM contrats_mission WHERE id = p_contrat_id;
    IF v_contrat IS NULL THEN RETURN '{"error":"Contrat introuvable"}'::JSONB; END IF;
    IF v_contrat.soignant_id != auth.uid() THEN RETURN '{"error":"Ce contrat ne vous concerne pas"}'::JSONB; END IF;
    IF v_contrat.signature_soignant = TRUE THEN RETURN '{"error":"Déjà signé"}'::JSONB; END IF;

    -- Autorise la transition de statut de signature dans le trigger de protection
    PERFORM set_config('jolene.signature_soignant_en_cours', '1', true);

    UPDATE contrats_mission SET
        signature_soignant = TRUE,
        signature_soignant_le = NOW(),
        signature_image_soignant = p_signature_image,
        signature_navigateur_soignant = current_setting('request.headers', true)::JSON->>'user-agent',
        statut = CASE
            WHEN signature_etablissement = TRUE THEN 'SIGNE_COMPLET'
            ELSE 'SIGNE_SOIGNANT'
        END,
        modifie_le = NOW()
    WHERE id = p_contrat_id;

    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_signer_contrat_soignant"("p_contrat_id" "uuid", "p_signature_image" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_signer_mandat_facturation"("p_version" "text", "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_contenu_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_signature_id UUID;
    v_mission_id UUID;
    v_backfill INT := 0;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN '{"error":"Non authentifié"}'::JSONB;
    END IF;

    -- Vérifier que c'est bien un soignant
    IF NOT EXISTS (SELECT 1 FROM soignants WHERE id = v_user_id AND supprime_le IS NULL) THEN
        RETURN '{"error":"Seuls les soignants peuvent signer ce mandat"}'::JSONB;
    END IF;

    -- Enregistrer la signature (audit)
    INSERT INTO mandats_facturation_signatures (soignant_id, version, ip_address, user_agent, contenu_hash)
    VALUES (v_user_id, p_version, p_ip, p_user_agent, p_contenu_hash)
    RETURNING id INTO v_signature_id;

    -- Mettre à jour le soignant
    UPDATE soignants SET
        mandat_facturation_signe = TRUE,
        mandat_facturation_signe_le = now(),
        mandat_facturation_version = p_version
    WHERE id = v_user_id;

    -- BACKFILL : rattraper les factures d'honoraires non générées faute de mandat.
    -- On reproduit les prédicats des deux générateurs existants :
    --   (A) honoraires "classiques" (non rétrocession) → généré par le trigger TERMINEE
    --       si mandat signé. Gardé sur type_contrat_applique = 'LIBERAL' pour ne PAS
    --       facturer en honoraires les missions SALARIÉES d'un soignant MIXTE.
    --   (B) rétrocession confirmée (honoraires_confirmes_le NOT NULL) → généré par
    --       confirm/cron si mandat signé. RETROCESSION est par nature libéral.
    -- fn_generer_facture_honoraires_mission est idempotente (no-op si facture existe).
    FOR v_mission_id IN
        SELECT m.id
        FROM missions m
        WHERE m.soignant_assigne_id = v_user_id
          AND m.statut = 'TERMINEE'
          AND COALESCE(m.net_a_payer, m.total_brut, 0) > 0
          AND NOT EXISTS (SELECT 1 FROM factures_honoraires fh WHERE fh.mission_id = m.id)
          AND (
                (m.mode_remuneration IS DISTINCT FROM 'RETROCESSION' AND m.type_contrat_applique = 'LIBERAL')
             OR (m.mode_remuneration = 'RETROCESSION' AND m.honoraires_confirmes_le IS NOT NULL)
          )
    LOOP
        PERFORM fn_generer_facture_honoraires_mission(v_mission_id);
        v_backfill := v_backfill + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'signature_id', v_signature_id,
        'version', p_version,
        'signed_at', now(),
        'factures_regenerees', v_backfill
    );
END;
$$;


ALTER FUNCTION "public"."fn_signer_mandat_facturation"("p_version" "text", "p_ip" "text", "p_user_agent" "text", "p_contenu_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sms_doit_envoyer"("p_destinataire_id" "uuid", "p_type" "text", "p_fenetre_minutes" integer DEFAULT 5) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_existe BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM sms_envoyes
    WHERE destinataire_id = p_destinataire_id
      AND type = p_type
      AND statut IN ('SENT','DELIVERED','PENDING')
      AND cree_le > NOW() - (p_fenetre_minutes || ' minutes')::INTERVAL
  ) INTO v_existe;
  RETURN NOT v_existe;
END;
$$;


ALTER FUNCTION "public"."fn_sms_doit_envoyer"("p_destinataire_id" "uuid", "p_type" "text", "p_fenetre_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignant_compatible_mission"("p_soignant_profession" "public"."type_profession", "p_soignant_specialite" "text", "p_mission_profession" "public"."type_profession", "p_mission_specialite" "text", "p_accepte_non_specialises" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    -- La profession requise par la mission prime. Un match exact est accepté ;
    -- pour les médecins, la souplesse ne porte que sur la spécialité médicale.
    WHEN p_soignant_profession = p_mission_profession THEN
      CASE
        WHEN p_mission_profession = 'MEDECIN'
             AND p_mission_specialite IS NOT NULL
             AND p_mission_specialite <> '' THEN
          COALESCE(p_accepte_non_specialises, true)
          OR COALESCE(p_soignant_specialite, '') = p_mission_specialite
        ELSE TRUE
      END
    -- IADE et IBODE sont aussi IDE : ils peuvent candidater à une mission IDE,
    -- laquelle reste résolue selon la cellule IDE de la matrice.
    WHEN p_mission_profession = 'IDE'
         AND p_soignant_profession IN ('IBODE', 'IADE') THEN TRUE
    -- Le sens inverse est interdit : une mission IADE/IBODE ne peut pas être
    -- transformée en mission d'assistance ouverte à un IDE non spécialisé.
    ELSE FALSE
  END;
$$;


ALTER FUNCTION "public"."fn_soignant_compatible_mission"("p_soignant_profession" "public"."type_profession", "p_soignant_specialite" "text", "p_mission_profession" "public"."type_profession", "p_mission_specialite" "text", "p_accepte_non_specialises" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_soignant_compatible_mission"("p_soignant_profession" "public"."type_profession", "p_soignant_specialite" "text", "p_mission_profession" "public"."type_profession", "p_mission_specialite" "text", "p_accepte_non_specialises" boolean) IS 'Compatibilité lue sur la profession requise : match exact, plus IADE/IBODE vers mission IDE uniquement. Une mission IADE/IBODE exige la spécialité correspondante.';



CREATE OR REPLACE FUNCTION "public"."fn_soignant_dpae_complet"("p_soignant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_s RECORD;
  v_manquants text[] := ARRAY[]::text[];
BEGIN
  IF NOT (p_soignant_id = auth.uid() OR est_admin()) THEN
    RETURN jsonb_build_object('complet', false, 'manquants', ARRAY['non_autorise']);
  END IF;
  SELECT sexe, lieu_naissance_commune, lieu_naissance_departement, pays_naissance, nationalite,
         COALESCE(numero_securite_sociale, numero_secu) AS nir, date_naissance, adresse_rue, adresse_ville
  INTO v_s FROM public.soignants WHERE id = p_soignant_id;
  IF v_s IS NULL THEN
    RETURN jsonb_build_object('complet', false, 'manquants', ARRAY['profil_introuvable']);
  END IF;
  IF v_s.sexe IS NULL THEN v_manquants := array_append(v_manquants, 'sexe'); END IF;
  IF v_s.date_naissance IS NULL THEN v_manquants := array_append(v_manquants, 'date_naissance'); END IF;
  IF v_s.pays_naissance IS NULL THEN v_manquants := array_append(v_manquants, 'pays_naissance'); END IF;
  IF v_s.nationalite IS NULL THEN v_manquants := array_append(v_manquants, 'nationalite'); END IF;
  IF COALESCE(v_s.pays_naissance, 'France') = 'France' THEN
    IF v_s.lieu_naissance_commune IS NULL THEN v_manquants := array_append(v_manquants, 'lieu_naissance_commune'); END IF;
    IF v_s.lieu_naissance_departement IS NULL THEN v_manquants := array_append(v_manquants, 'lieu_naissance_departement'); END IF;
  END IF;
  IF v_s.nir IS NULL OR v_s.nir = '' THEN v_manquants := array_append(v_manquants, 'numero_securite_sociale'); END IF;
  IF v_s.adresse_rue IS NULL OR v_s.adresse_rue = '' THEN v_manquants := array_append(v_manquants, 'adresse'); END IF;
  RETURN jsonb_build_object('complet', array_length(v_manquants, 1) IS NULL, 'manquants', v_manquants);
END;
$$;


ALTER FUNCTION "public"."fn_soignant_dpae_complet"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignant_eligible_mission"("p_soignant_id" "uuid", "p_mission_id" "uuid", "p_exiger_documents" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_soignant record;
  v_type text;
  v_resolution jsonb;
BEGIN
  SELECT m.profession_requise, m.specialite_medicale_requise,
         COALESCE(m.accepte_non_specialises, true) AS accepte_non_specialises,
         COALESCE(m.type_contrat_recherche::text, 'SALARIE') AS type_contrat_recherche,
         m.remplacement_de_mission_id,
         COALESCE(e.est_compte_test, false) AS est_compte_test
    INTO v_mission
    FROM public.missions m
    JOIN public.etablissements e ON e.id = m.etablissement_id
   WHERE m.id = p_mission_id AND m.statut = 'OUVERTE';
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT profession, specialite_medicale,
         COALESCE(type_exercice, 'SALARIE') AS type_exercice,
         COALESCE(est_compte_test, false) AS est_compte_test
    INTO v_soignant
    FROM public.soignants
   WHERE id = p_soignant_id
     AND supprime_le IS NULL
     AND COALESCE(statut_compte::text, 'ACTIF') = 'ACTIF';
  IF NOT FOUND THEN RETURN false; END IF;

  IF v_soignant.est_compte_test IS DISTINCT FROM v_mission.est_compte_test THEN
    RETURN false;
  END IF;

  -- Aucun assigné remplacé, ni auteur d'une attestation EPI, ne peut revenir
  -- par un descendant de la chaîne. L'ascendance récursive couvre aussi
  -- EPI(A) -> remplacement B -> no-show(B) -> remplacement C.
  IF v_mission.remplacement_de_mission_id IS NOT NULL
     AND EXISTS (
       WITH RECURSIVE ascendance AS (
         SELECT m.id, m.soignant_assigne_id, m.remplacement_de_mission_id
         FROM public.missions m
         WHERE m.id = v_mission.remplacement_de_mission_id
         UNION
         SELECT parent.id, parent.soignant_assigne_id,
                parent.remplacement_de_mission_id
         FROM public.missions parent
         JOIN ascendance enfant
           ON parent.id = enfant.remplacement_de_mission_id
       )
       SELECT 1
       FROM ascendance a
       WHERE a.soignant_assigne_id = p_soignant_id
          OR EXISTS (
            SELECT 1
            FROM public.journaux_audit ja
            WHERE ja.acteur_id = p_soignant_id
              AND ja.action = 'ANNULATION_EMPECHEMENT_IMPERIEUX'
              AND ja.type_ressource = 'mission'
              AND ja.id_ressource = a.id
          )
     ) THEN
    RETURN false;
  END IF;

  IF NOT public.fn_soignant_compatible_mission(
    v_soignant.profession, v_soignant.specialite_medicale,
    v_mission.profession_requise, v_mission.specialite_medicale_requise,
    v_mission.accepte_non_specialises
  ) THEN
    RETURN false;
  END IF;

  v_resolution := public.fn_resoudre_contrat_mission(
    p_mission_id, p_soignant_id, NULL
  );
  IF COALESCE((v_resolution->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE((v_resolution->>'choix_requis')::boolean, false) IS NOT TRUE THEN
    RETURN false;
  END IF;
  IF NOT p_exiger_documents THEN RETURN true; END IF;

  IF COALESCE((v_resolution->>'choix_requis')::boolean, false) THEN
    RETURN public.fn_documents_ok_pour_mission(p_soignant_id, 'SALARIE')
      OR (v_soignant.type_exercice IN ('LIBERAL', 'MIXTE')
          AND public.fn_documents_ok_pour_mission(p_soignant_id, 'LIBERAL'));
  END IF;
  v_type := v_resolution->>'contrat';
  IF v_type = 'LIBERAL' THEN
    RETURN public.fn_documents_ok_pour_mission(p_soignant_id, 'LIBERAL');
  END IF;
  RETURN public.fn_documents_ok_pour_mission(p_soignant_id, 'SALARIE');
END;
$$;


ALTER FUNCTION "public"."fn_soignant_eligible_mission"("p_soignant_id" "uuid", "p_mission_id" "uuid", "p_exiger_documents" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignant_liberal_actif_verifie"("p_soignant_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  SELECT EXISTS (
    SELECT 1
    FROM public.soignants s
    WHERE s.id = p_soignant_id
      AND s.supprime_le IS NULL
      AND COALESCE(s.statut_compte::text, 'ACTIF') = 'ACTIF'
      AND COALESCE(s.type_exercice, 'SALARIE') IN ('LIBERAL', 'MIXTE')
      AND s.statut_liberal = 'ACTIF'
      AND s.siret_liberal ~ '^[0-9]{14}$'
      AND s.siret_liberal_verifie IS TRUE
      AND s.siret_liberal_verifie_le IS NOT NULL
      AND s.siret_liberal_coherence_identite IS TRUE
  );
$_$;


ALTER FUNCTION "public"."fn_soignant_liberal_actif_verifie"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignant_pour_etablissement"("p_soignant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_a_mission_aujourdhui BOOLEAN;
    v_a_relation_contractuelle BOOLEAN;
BEGIN
    IF NOT est_admin() AND v_etab_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM missions
        WHERE soignant_assigne_id = p_soignant_id
          AND etablissement_id = v_etab_id
          AND statut IN ('ASSIGNEE','EN_COURS','TERMINEE','ABSENCE','LITIGE')
    ) INTO v_a_relation_contractuelle;

    SELECT EXISTS (
        SELECT 1 FROM missions
        WHERE soignant_assigne_id = p_soignant_id
          AND etablissement_id = v_etab_id
          AND statut IN ('ASSIGNEE','EN_COURS')
          AND debut_le::DATE <= CURRENT_DATE + 1
    ) INTO v_a_mission_aujourdhui;

    RETURN (
        SELECT jsonb_build_object(
            'id', id,
            'prenom', prenom,
            'nom', CASE
                WHEN est_admin() OR v_a_relation_contractuelle THEN nom
                ELSE LEFT(COALESCE(nom, ''), 1) || '.'
            END,
            'nom_anonymise', NOT (est_admin() OR v_a_relation_contractuelle),
            'profession', profession::TEXT,
            'specialite_medicale', specialite_medicale,
            'telephone', CASE WHEN v_a_mission_aujourdhui OR est_admin() THEN telephone ELSE NULL END,
            'numero_rpps', numero_rpps,
            'score_fiabilite', score_fiabilite,
            'note_moyenne', note_moyenne,
            'nb_evaluations', nb_evaluations,
            'total_missions_terminees', total_missions_terminees,
            'rpps_verifie', rpps_verifie,
            'tous_documents_valides', tous_documents_valides,
            'avatar_url', avatar_url,
            'type_exercice', COALESCE(type_exercice, 'SALARIE'),
            'bio', bio,
            'annees_experience', annees_experience,
            'specialites', specialites,
            'disponible_urgence', disponible_urgence,
            'est_etudiant', est_etudiant,
            'etudiant_details', etudiant_details
        )
        FROM soignants WHERE id = p_soignant_id AND supprime_le IS NULL
    );
END;
$$;


ALTER FUNCTION "public"."fn_soignant_pour_etablissement"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignant_score_breakdown"("p_soignant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_b public.scoring_breakdown;
BEGIN
  SELECT * INTO v_b FROM public.scoring_breakdown
   WHERE soignant_id = p_soignant_id
   ORDER BY cree_le DESC LIMIT 1;

  IF v_b.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'composantes', '[]'::jsonb);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'score_total', v_b.score_total,
    'niveau', v_b.niveau,
    'composantes', jsonb_build_array(
      jsonb_build_object('cle','notation_etab','label','Notations reçues','poids',35,'valeur', v_b.notation_etab_soignant_pct),
      jsonb_build_object('cle','presentisme','label','Présentéisme','poids',20,'valeur', v_b.presentisme_pct),
      jsonb_build_object('cle','ponctualite','label','Ponctualité','poids',15,'valeur', v_b.ponctualite_pct),
      jsonb_build_object('cle','reactivite','label','Réactivité','poids',10,'valeur', v_b.reactivite_pct),
      jsonb_build_object('cle','anciennete','label','Ancienneté / volume','poids',10,'valeur', v_b.anciennete_volume_pct),
      jsonb_build_object('cle','notation_soignant_etab','label','Notes données aux établissements','poids',10,'valeur', v_b.notation_soignant_etab_pct)
    )
  );
END;
$$;


ALTER FUNCTION "public"."fn_soignant_score_breakdown"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignant_stripe_connect_actif"("p_soignant_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Seul le soignant lui-même, l'étab de sa mission, ou admin/service_role
    IF p_soignant_id != auth.uid() 
       AND NOT est_admin()
       AND COALESCE(current_setting('request.jwt.claim.role', true), '') != 'service_role'
       AND NOT EXISTS(SELECT 1 FROM missions m WHERE m.soignant_assigne_id = p_soignant_id AND m.etablissement_id = mon_etablissement_id() AND m.statut IN ('ASSIGNEE','EN_COURS','TERMINEE'))
    THEN
        RETURN FALSE; -- Ne pas exposer l'info
    END IF;

    RETURN EXISTS (
        SELECT 1 FROM stripe_connect_onboarding 
        WHERE soignant_id = p_soignant_id 
        AND onboarding_complete = TRUE 
        AND charges_enabled = TRUE 
        AND payouts_enabled = TRUE
        AND statut = 'COMPLET'
    );
END;
$$;


ALTER FUNCTION "public"."fn_soignant_stripe_connect_actif"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignants_inactifs_a_relancer"("p_limit" integer DEFAULT 150) RETURNS TABLE("id" "uuid", "prenom" "text", "email" "text", "profession" "text", "nb_missions_ouvertes" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT s.id, s.prenom, s.email, s.profession::text,
    (SELECT count(*) FROM public.missions m
      WHERE m.statut = 'OUVERTE'
        AND public.fn_soignant_eligible_mission(s.id, m.id, false))
  FROM public.soignants s
  WHERE s.cree_le < now() - interval '3 days'
    AND s.email IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.candidatures c WHERE c.soignant_id = s.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.relances_soignants r
       WHERE r.soignant_id = s.id AND r.envoye_le > now() - interval '14 days'
    )
  ORDER BY s.cree_le DESC
  LIMIT greatest(COALESCE(p_limit, 150), 1);
$$;


ALTER FUNCTION "public"."fn_soignants_inactifs_a_relancer"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soignants_urgence"("p_mission_id" "uuid") RETURNS TABLE("soignant_id" "uuid", "id" "uuid", "prenom" "text", "nom" "text", "score_fiabilite" integer, "distance_km" numeric, "urgence_rayon_km" integer, "telephone" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
BEGIN
  SELECT m.id, m.etablissement_id, e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng
    INTO v_mission
    FROM public.missions m
    JOIN public.etablissements e ON e.id = m.etablissement_id
   WHERE m.id = p_mission_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF NOT (public.est_admin() OR v_mission.etablissement_id = public.mon_etablissement_id()) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT s.id, s.id, s.prenom::text, s.nom::text,
    COALESCE(s.score_fiabilite, 0)::integer,
    CASE WHEN s.adresse_lat IS NOT NULL AND v_mission.etab_lat IS NOT NULL
      THEN round((public.fn_haversine_distance_m(
        s.adresse_lat, s.adresse_lng, v_mission.etab_lat, v_mission.etab_lng
      ) / 1000.0)::numeric, 1)
      ELSE NULL
    END,
    COALESCE(s.urgence_rayon_km, 15)::integer,
    s.telephone::text
  FROM public.soignants s
  WHERE COALESCE(s.disponible_urgence, false)
    AND public.fn_soignant_eligible_mission(s.id, p_mission_id, true)
    AND NOT public.fn_est_exclu(s.id, v_mission.etablissement_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.missions ma
      WHERE ma.soignant_assigne_id = s.id AND ma.statut = 'EN_COURS'
        AND now() BETWEEN ma.debut_le AND ma.fin_le
    )
    AND (
      s.adresse_lat IS NULL OR v_mission.etab_lat IS NULL
      OR public.fn_haversine_distance_m(
        s.adresse_lat, s.adresse_lng, v_mission.etab_lat, v_mission.etab_lng
      ) <= COALESCE(s.urgence_rayon_km, 15) * 1000
    )
  ORDER BY s.score_fiabilite DESC NULLS LAST, distance_km NULLS LAST;
END;
$$;


ALTER FUNCTION "public"."fn_soignants_urgence"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_soumettre_reclamation"("p_categorie" "text", "p_sujet" "text", "p_details" "text", "p_mission_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ DECLARE v_user_id UUID := auth.uid(); v_role TEXT; v_type TEXT; v_reclamation_id UUID; BEGIN IF v_user_id IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF; SELECT raw_app_meta_data ->> 'role' INTO v_role FROM auth.users WHERE id = v_user_id; IF v_role IN ('SOIGNANT') THEN v_type := 'SOIGNANT'; ELSIF v_role IN ('ADMIN_ETABLISSEMENT', 'ETABLISSEMENT') THEN v_type := 'ETABLISSEMENT'; ELSE RETURN jsonb_build_object('error', 'Rôle non autorisé'); END IF; INSERT INTO reclamations (utilisateur_id, type_utilisateur, categorie, sujet, details, mission_id) VALUES (v_user_id, v_type, p_categorie, p_sujet, p_details, p_mission_id) RETURNING id INTO v_reclamation_id; PERFORM fn_ecrire_audit_safe(v_user_id, v_type, 'RECLAMATION_CREEE', 'reclamation', v_reclamation_id, NULL, jsonb_build_object('categorie', p_categorie, 'sujet', p_sujet), NULL, NULL); RETURN jsonb_build_object('id', v_reclamation_id, 'statut', 'EN_ATTENTE'); END; $$;


ALTER FUNCTION "public"."fn_soumettre_reclamation"("p_categorie" "text", "p_sujet" "text", "p_details" "text", "p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_souscrire_prevoyance"("p_plan_id" "uuid", "p_numero_contrat" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_plan RECORD;
BEGIN
    IF auth.uid() IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.soignants s
      WHERE s.id = auth.uid()
        AND s.supprime_le IS NULL
    ) THEN
      RETURN jsonb_build_object('error', 'Acces refuse');
    END IF;

    SELECT * INTO v_plan FROM plans_prevoyance WHERE id = p_plan_id AND est_actif = TRUE;
    IF v_plan IS NULL THEN RETURN '{"error":"Plan introuvable"}'::JSONB; END IF;

    INSERT INTO public.souscriptions_prevoyance (soignant_id, plan_id, statut)
    VALUES (auth.uid(), p_plan_id, 'ACTIF')
    ON CONFLICT (soignant_id, plan_id) DO NOTHING;

    UPDATE soignants SET
        prevoyance_inscrit = TRUE,
        prevoyance_fournisseur = v_plan.fournisseur,
        prevoyance_numero_contrat = p_numero_contrat,
        modifie_le = NOW()
    WHERE id = auth.uid();

    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_souscrire_prevoyance"("p_plan_id" "uuid", "p_numero_contrat" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stats_dashboard_etablissement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_stats JSONB;
    v_pool_urgence_count INT;
    v_messages_non_lus INT;
    v_missions_a_payer INT;
    v_debut_mois TIMESTAMPTZ;
    v_terminees_ce_mois INT;
    v_soignants_ce_mois INT;
    v_commissions_impayees NUMERIC;
    v_nb_factures_impayees INT;
    v_litiges_ouverts INT;
BEGIN
    IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Établissement introuvable'); END IF;
    
    v_debut_mois := DATE_TRUNC('month', NOW());
    
    SELECT COUNT(*) INTO v_pool_urgence_count FROM fn_pool_urgence_etablissement(v_etab_id);
    
    SELECT COUNT(*) INTO v_messages_non_lus
    FROM messages_chat mc JOIN conversations c ON c.id = mc.conversation_id
    WHERE (c.participant_1_id = v_etab_id OR c.participant_2_id = v_etab_id)
    AND mc.auteur_id != v_etab_id AND mc.lu = FALSE;
    
    SELECT COUNT(*) INTO v_missions_a_payer
    FROM missions m WHERE m.etablissement_id = v_etab_id AND m.statut = 'TERMINEE' AND m.soignant_assigne_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM paiements_soignant p WHERE p.mission_id = m.id AND p.statut IN ('DECLARE','CONFIRME'));
    
    SELECT COUNT(*) INTO v_terminees_ce_mois
    FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois;
    
    SELECT COUNT(DISTINCT soignant_assigne_id) INTO v_soignants_ce_mois
    FROM missions WHERE etablissement_id = v_etab_id AND soignant_assigne_id IS NOT NULL
    AND statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE') AND debut_le >= v_debut_mois;
    
    SELECT COALESCE(SUM(montant_ttc), 0), COUNT(*)
    INTO v_commissions_impayees, v_nb_factures_impayees
    FROM factures WHERE etablissement_id = v_etab_id AND statut IN ('EMISE', 'EN_RETARD');
    
    -- Litiges ouverts
    SELECT COUNT(*) INTO v_litiges_ouverts
    FROM litiges WHERE etablissement_id = v_etab_id 
    AND statut IN ('OUVERT', 'EN_COURS', 'EN_DISCUSSION', 'EN_MEDIATION', 'CONTESTEE');
    
    SELECT jsonb_build_object(
        'a_deja_publie', (SELECT COUNT(*) > 0 FROM missions WHERE etablissement_id = v_etab_id),
        'total_missions', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id),
        'missions_ouvertes', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'OUVERTE'),
        'missions_assignees', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'ASSIGNEE'),
        'missions_en_cours', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'EN_COURS'),
        'missions_terminees', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE'),
        'missions_terminees_ce_mois', v_terminees_ce_mois,
        'soignants_ce_mois', v_soignants_ce_mois,
        'commissions_cumulees', COALESCE((SELECT SUM(montant_ht) FROM factures WHERE etablissement_id = v_etab_id AND statut != 'ANNULEE'), 0),
        'commissions_impayees', v_commissions_impayees,
        'nb_factures_impayees', v_nb_factures_impayees,
        'pool_urgence_count', v_pool_urgence_count,
        'messages_non_lus', v_messages_non_lus,
        'missions_a_payer', v_missions_a_payer,
        'litiges_ouverts', v_litiges_ouverts,
        'candidatures_en_attente', (
            SELECT COUNT(*) FROM candidatures c JOIN missions m ON m.id = c.mission_id
            WHERE m.etablissement_id = v_etab_id AND c.statut = 'EN_ATTENTE'
        ),
        'candidatures_recentes', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT c.id::TEXT AS candidature_id, m.intitule AS mission_intitule,
                    m.id::TEXT AS mission_id,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
                    s.profession::TEXT AS soignant_profession,
                    s.score_fiabilite AS soignant_score, c.cree_le
                FROM candidatures c JOIN missions m ON m.id = c.mission_id JOIN soignants s ON s.id = c.soignant_id
                WHERE m.etablissement_id = v_etab_id AND c.statut = 'EN_ATTENTE'
                ORDER BY c.cree_le DESC LIMIT 5
            ) x
        ), '[]'::JSONB),
        'missions_assignees_detail', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT m.id::TEXT AS mission_id, m.intitule, m.debut_le, m.fin_le,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
                    s.profession::TEXT AS soignant_profession, s.score_fiabilite AS soignant_score
                FROM missions m JOIN soignants s ON s.id = m.soignant_assigne_id
                WHERE m.etablissement_id = v_etab_id AND m.statut = 'ASSIGNEE'
                ORDER BY m.debut_le ASC
            ) x
        ), '[]'::JSONB)
    ) INTO v_stats;
    
    RETURN v_stats;
END;
$$;


ALTER FUNCTION "public"."fn_stats_dashboard_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stats_etab_complements"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etab_id UUID;
  v_debut_mois TIMESTAMPTZ;
  v_debut_mois_precedent TIMESTAMPTZ;
  v_fin_mois_precedent TIMESTAMPTZ;
  v_soignants_mois_precedent INT;
  v_cout_brut_ce_mois NUMERIC;
  v_heures_ce_mois NUMERIC;
  v_missions_pourvues_ce_mois INT;
  v_missions_publiees_ce_mois INT;
BEGIN
  IF NOT est_admin() THEN
    v_etab_id := mon_etablissement_id();
    IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Accès refusé'); END IF;
  END IF;

  v_debut_mois := DATE_TRUNC('month', NOW());
  v_debut_mois_precedent := DATE_TRUNC('month', NOW() - INTERVAL '1 month');
  v_fin_mois_precedent := v_debut_mois;

  SELECT COUNT(DISTINCT soignant_assigne_id) INTO v_soignants_mois_precedent
  FROM missions
  WHERE (v_etab_id IS NULL OR etablissement_id = v_etab_id)
    AND soignant_assigne_id IS NOT NULL
    AND statut IN ('ASSIGNEE','EN_COURS','TERMINEE')
    AND debut_le >= v_debut_mois_precedent AND debut_le < v_fin_mois_precedent;

  SELECT COALESCE(SUM(total_brut), 0), COALESCE(SUM(duree_heures), 0)
  INTO v_cout_brut_ce_mois, v_heures_ce_mois
  FROM missions
  WHERE (v_etab_id IS NULL OR etablissement_id = v_etab_id)
    AND statut = 'TERMINEE' AND fin_le >= v_debut_mois;

  SELECT
    COUNT(*) FILTER (WHERE statut IN ('ASSIGNEE','EN_COURS','TERMINEE')),
    COUNT(*)
  INTO v_missions_pourvues_ce_mois, v_missions_publiees_ce_mois
  FROM missions
  WHERE (v_etab_id IS NULL OR etablissement_id = v_etab_id)
    AND cree_le >= v_debut_mois;

  RETURN jsonb_build_object(
    'soignants_mois_precedent', v_soignants_mois_precedent,
    'cout_brut_ce_mois', v_cout_brut_ce_mois,
    'heures_ce_mois', v_heures_ce_mois,
    'missions_pourvues_ce_mois', v_missions_pourvues_ce_mois,
    'missions_publiees_ce_mois', v_missions_publiees_ce_mois
  );
END;
$$;


ALTER FUNCTION "public"."fn_stats_etab_complements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stats_rh_etablissement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_etab_id UUID := mon_etablissement_id();
    v_result JSONB;
    v_debut_mois TIMESTAMPTZ;
    v_debut_mois_prec TIMESTAMPTZ;
    v_mois_fr TEXT[];
BEGIN
    IF v_etab_id IS NULL THEN RETURN jsonb_build_object('error', 'Établissement introuvable'); END IF;
    
    v_debut_mois := DATE_TRUNC('month', NOW());
    v_debut_mois_prec := DATE_TRUNC('month', NOW() - INTERVAL '1 month');
    v_mois_fr := ARRAY['Janvier','Février','Mars','Avril','Mai','Juin','Juillet','Août','Septembre','Octobre','Novembre','Décembre'];
    
    SELECT jsonb_build_object(
        'terminees_total', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE'),
        'terminees_mois_prec', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois_prec AND fin_le < v_debut_mois),
        'terminees_ce_mois', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois),
        
        'cout_total_termine', COALESCE((SELECT SUM(total_brut) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE'), 0),
        'cout_mois_prec', COALESCE((SELECT SUM(total_brut) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois_prec AND fin_le < v_debut_mois), 0),
        'cout_ce_mois', COALESCE((SELECT SUM(total_brut) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois), 0),
        'commission_mois_prec', COALESCE((SELECT SUM(montant_commission_ttc) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois_prec AND fin_le < v_debut_mois), 0),
        'commission_ce_mois', COALESCE((SELECT SUM(montant_commission_ttc) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE' AND fin_le >= v_debut_mois), 0),
        'heures_terminees', COALESCE((SELECT SUM(EXTRACT(EPOCH FROM (fin_le - debut_le))/3600) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE'), 0),
        
        'cout_moyen_heure', COALESCE((
            SELECT ROUND((SUM(total_brut) / NULLIF(SUM(EXTRACT(EPOCH FROM (fin_le - debut_le))/3600), 0))::NUMERIC, 2)
            FROM missions WHERE etablissement_id = v_etab_id AND statut = 'TERMINEE'
        ), 0),
        
        'assignees_total', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'ASSIGNEE'),
        'cout_previsionnel_brut', COALESCE((SELECT SUM(total_brut) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'ASSIGNEE'), 0),
        'commission_previsionnelle', COALESCE((SELECT SUM(montant_commission_ttc) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'ASSIGNEE'), 0),
        'cout_previsionnel_total', COALESCE((SELECT SUM(total_brut + COALESCE(montant_commission_ttc, 0)) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'ASSIGNEE'), 0),
        'heures_prevues', COALESCE((SELECT SUM(EXTRACT(EPOCH FROM (fin_le - debut_le))/3600) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'ASSIGNEE'), 0),
        
        'ouvertes_total', (SELECT COUNT(*) FROM missions WHERE etablissement_id = v_etab_id AND statut = 'OUVERTE'),
        
        'taux_remplissage', COALESCE((
            SELECT ROUND(
                (COUNT(*) FILTER (WHERE statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE'))::NUMERIC /
                 NULLIF(COUNT(*) FILTER (WHERE statut NOT IN ('ANNULEE_PAR_ETABLISSEMENT', 'ANNULEE_PAR_SOIGNANT')), 0)
                ) * 100, 0)
            FROM missions WHERE etablissement_id = v_etab_id
        ), 0),
        
        'soignants_total', (SELECT COUNT(DISTINCT soignant_assigne_id) FROM missions WHERE etablissement_id = v_etab_id AND soignant_assigne_id IS NOT NULL AND statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE')),
        'soignants_ce_mois', (SELECT COUNT(DISTINCT soignant_assigne_id) FROM missions WHERE etablissement_id = v_etab_id AND soignant_assigne_id IS NOT NULL AND statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE') AND debut_le >= v_debut_mois),
        
        'top_soignants', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT s.id::TEXT AS soignant_id, COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS nom,
                    s.profession::TEXT, s.score_fiabilite, s.note_moyenne,
                    COUNT(*) AS nb_missions, SUM(m.total_brut) AS total_facture
                FROM missions m JOIN soignants s ON s.id = m.soignant_assigne_id
                WHERE m.etablissement_id = v_etab_id AND m.statut = 'TERMINEE'
                GROUP BY s.id ORDER BY nb_missions DESC LIMIT 5
            ) x
        ), '[]'::JSONB),
        
        -- ★ NOUVEAU : Détail missions mois précédent
        'missions_mois_prec', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT m.id::TEXT AS mission_id, m.intitule, m.debut_le, m.fin_le, m.total_brut,
                    m.montant_commission_ttc, EXTRACT(EPOCH FROM (m.fin_le - m.debut_le))/3600 AS heures,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
                    s.profession::TEXT AS soignant_profession
                FROM missions m LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
                WHERE m.etablissement_id = v_etab_id AND m.statut = 'TERMINEE'
                AND m.fin_le >= v_debut_mois_prec AND m.fin_le < v_debut_mois
                ORDER BY m.fin_le DESC
            ) x
        ), '[]'::JSONB),
        
        -- ★ NOUVEAU : Détail missions ce mois
        'missions_ce_mois', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT m.id::TEXT AS mission_id, m.intitule, m.debut_le, m.fin_le, m.total_brut,
                    m.montant_commission_ttc, EXTRACT(EPOCH FROM (m.fin_le - m.debut_le))/3600 AS heures,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom,
                    s.profession::TEXT AS soignant_profession
                FROM missions m LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
                WHERE m.etablissement_id = v_etab_id AND m.statut = 'TERMINEE'
                AND m.fin_le >= v_debut_mois
                ORDER BY m.fin_le DESC
            ) x
        ), '[]'::JSONB),
        
        'prochaines_missions', COALESCE((
            SELECT jsonb_agg(row_to_json(x)) FROM (
                SELECT m.id::TEXT AS mission_id, m.intitule, m.debut_le, m.fin_le, m.total_brut,
                    m.montant_commission_ttc, m.statut::TEXT,
                    COALESCE(s.prenom, '') || ' ' || COALESCE(s.nom, '') AS soignant_nom
                FROM missions m LEFT JOIN soignants s ON s.id = m.soignant_assigne_id
                WHERE m.etablissement_id = v_etab_id AND m.statut IN ('OUVERTE', 'ASSIGNEE', 'EN_COURS')
                AND m.debut_le >= NOW()
                ORDER BY m.debut_le ASC LIMIT 10
            ) x
        ), '[]'::JSONB),
        
        'mois_en_cours', v_mois_fr[EXTRACT(MONTH FROM NOW())::INT] || ' ' || EXTRACT(YEAR FROM NOW())::TEXT,
        'mois_precedent', v_mois_fr[EXTRACT(MONTH FROM NOW() - INTERVAL '1 month')::INT] || ' ' || EXTRACT(YEAR FROM NOW() - INTERVAL '1 month')::TEXT
    ) INTO v_result;
    
    RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_stats_rh_etablissement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_connect_rapprocher_facture"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid", "p_facture_honoraires_id" "uuid", "p_facture_commission_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_stripe_transfer_id" "text", "p_montant_soignant_cts" integer, "p_montant_commission_cts" integer, "p_montant_total_cts" integer, "p_rapproche_le" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_fh public.factures_honoraires%ROWTYPE;
  v_commission public.factures%ROWTYPE;
  v_transfer public.stripe_transfers%ROWTYPE;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;
  IF p_montant_soignant_cts <= 0
     OR p_montant_commission_cts <= 0
     OR p_montant_total_cts <> p_montant_soignant_cts + p_montant_commission_cts
     OR NULLIF(p_stripe_checkout_session_id, '') IS NULL
     OR NULLIF(p_stripe_payment_intent_id, '') IS NULL
     OR NULLIF(p_stripe_charge_id, '') IS NULL
     OR NULLIF(p_stripe_transfer_id, '') IS NULL THEN
    RAISE EXCEPTION 'Paramètres de rapprochement invalides' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id FOR UPDATE;
  SELECT * INTO v_fh FROM public.factures_honoraires WHERE id = p_facture_honoraires_id FOR UPDATE;
  SELECT * INTO v_commission FROM public.factures WHERE id = p_facture_commission_id FOR UPDATE;
  SELECT * INTO v_transfer
  FROM public.stripe_transfers
  WHERE mission_id = p_mission_id
    AND facture_honoraire_id = p_facture_honoraires_id
    AND stripe_checkout_session_id = p_stripe_checkout_session_id
  FOR UPDATE;

  IF v_mission.id IS NULL
     OR v_mission.statut NOT IN ('EN_COURS', 'TERMINEE')
     OR v_mission.type_contrat_applique <> 'LIBERAL'
     OR v_mission.soignant_assigne_id <> p_soignant_id
     OR v_mission.etablissement_id <> p_etablissement_id
     OR v_fh.id IS NULL
     OR v_fh.mission_id <> p_mission_id
     OR v_fh.soignant_id <> p_soignant_id
     OR v_fh.etablissement_id <> p_etablissement_id
     OR v_fh.statut NOT IN ('EMISE', 'EN_RETARD', 'PAYEE')
     OR round(v_fh.montant_ttc * 100)::integer <> p_montant_soignant_cts
     OR v_commission.id IS NULL
     OR v_commission.facture_honoraire_id <> v_fh.id
     OR v_commission.mission_id <> p_mission_id
     OR v_commission.etablissement_id <> p_etablissement_id
     OR v_commission.statut NOT IN ('EMISE', 'EN_RETARD', 'PAYEE')
     OR round(v_commission.montant_ttc * 100)::integer <> p_montant_commission_cts
     OR v_transfer.id IS NULL
     OR v_transfer.statut NOT IN ('TRANSFERE', 'CHARGE_REUSSI', 'PAYE')
     OR v_transfer.stripe_payment_intent_id <> p_stripe_payment_intent_id
     OR v_transfer.stripe_transfer_id <> p_stripe_transfer_id
     OR (v_transfer.stripe_charge_id IS NOT NULL AND v_transfer.stripe_charge_id <> p_stripe_charge_id)
     OR round(v_transfer.montant_soignant * 100)::integer <> p_montant_soignant_cts
     OR round(v_transfer.montant_commission * 100)::integer <> p_montant_commission_cts
     OR round(v_transfer.montant_total * 100)::integer <> p_montant_total_cts THEN
    RAISE EXCEPTION 'Identité du rapprochement Connect incohérente' USING ERRCODE = '23514';
  END IF;
  IF v_mission.statut = 'EN_COURS'
     AND (v_fh.est_facture_finale_mission OR v_fh.periode_fin >= CURRENT_DATE) THEN
    RAISE EXCEPTION 'Période hebdomadaire non close' USING ERRCODE = '23514';
  END IF;

  UPDATE public.stripe_transfers
  SET statut = 'TRANSFERE',
      stripe_charge_id = p_stripe_charge_id,
      transfere_le = COALESCE(transfere_le, p_rapproche_le),
      erreur = NULL
  WHERE id = v_transfer.id;

  INSERT INTO public.paiements_soignant (
    mission_id, facture_honoraire_id, soignant_id, etablissement_id,
    montant_net, methode, reference_virement, date_paiement, statut,
    confirme_par_etablissement, confirme_par_etablissement_le,
    confirme_par_soignant, confirme_par_soignant_le, stripe_transfer_id
  ) VALUES (
    p_mission_id, v_fh.id, p_soignant_id, p_etablissement_id,
    p_montant_soignant_cts::numeric / 100, 'NOTE_HONORAIRES',
    'STRIPE-' || p_stripe_transfer_id, p_rapproche_le::date, 'CONFIRME',
    true, p_rapproche_le, true, p_rapproche_le, p_stripe_transfer_id
  )
  ON CONFLICT (stripe_transfer_id) WHERE stripe_transfer_id IS NOT NULL
  DO NOTHING;

  UPDATE public.factures_honoraires
  SET statut = 'PAYEE',
      date_paiement = p_rapproche_le::date,
      stripe_payment_intent_id = p_stripe_payment_intent_id,
      modifie_le = now()
  WHERE id = v_fh.id
    AND (stripe_payment_intent_id IS NULL OR stripe_payment_intent_id = p_stripe_payment_intent_id);

  UPDATE public.factures
  SET statut = 'PAYEE',
      date_paiement = p_rapproche_le,
      stripe_payment_intent_id = p_stripe_payment_intent_id,
      mode_paiement = 'STRIPE',
      modifie_le = now()
  WHERE id = v_commission.id
    AND (stripe_payment_intent_id IS NULL OR stripe_payment_intent_id = p_stripe_payment_intent_id);

  UPDATE public.missions
  SET mode_paiement_soignant = 'STRIPE_CONNECT',
      commission_facturee = commission_facturee OR v_fh.est_facture_finale_mission,
      facture_id = CASE WHEN v_fh.est_facture_finale_mission THEN v_commission.id ELSE facture_id END,
      modifie_le = now()
  WHERE id = p_mission_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource, details, navigateur_acteur
  ) VALUES (
    p_soignant_id, 'SYSTEME', 'FINANCE_TRANSFER_CONNECT', 'facture_honoraires', v_fh.id,
    jsonb_build_object(
      'mission_id', p_mission_id,
      'stripe_transfer_id', p_stripe_transfer_id,
      'stripe_charge_id', p_stripe_charge_id,
      'stripe_payment_intent_id', p_stripe_payment_intent_id,
      'stripe_session_id', p_stripe_checkout_session_id,
      'facture_commission_id', v_commission.id,
      'montant_cents', p_montant_soignant_cts,
      'evenement', 'CONNECT_FACTURE_RAPPROCHEMENT_ATOMIQUE'
    ),
    'fn_stripe_connect_rapprocher_facture'
  );

  RETURN jsonb_build_object(
    'success', true,
    'stripe_transfer_id', p_stripe_transfer_id,
    'facture_honoraires_id', v_fh.id,
    'facture_commission_id', v_commission.id
  );
END;
$$;


ALTER FUNCTION "public"."fn_stripe_connect_rapprocher_facture"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid", "p_facture_honoraires_id" "uuid", "p_facture_commission_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_stripe_transfer_id" "text", "p_montant_soignant_cts" integer, "p_montant_commission_cts" integer, "p_montant_total_cts" integer, "p_rapproche_le" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_connect_rapprocher_local"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid", "p_facture_honoraires_id" "uuid", "p_facture_commission_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_stripe_transfer_id" "text", "p_montant_soignant_cts" integer, "p_montant_commission_cts" integer, "p_montant_total_cts" integer, "p_rapproche_le" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_mission public.missions%ROWTYPE;
  v_transfer public.stripe_transfers%ROWTYPE;
  v_honoraires public.factures_honoraires%ROWTYPE;
  v_commission public.factures%ROWTYPE;
  v_numero_commission text;
  v_rows integer;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  IF p_mission_id IS NULL OR p_soignant_id IS NULL OR p_etablissement_id IS NULL
     OR p_facture_honoraires_id IS NULL
     OR p_stripe_checkout_session_id !~ '^cs_[A-Za-z0-9_]+$'
     OR p_stripe_payment_intent_id !~ '^pi_[A-Za-z0-9]+$'
     OR p_stripe_charge_id !~ '^ch_[A-Za-z0-9]+'
     OR p_stripe_transfer_id !~ '^tr_[A-Za-z0-9]+$'
     OR p_montant_soignant_cts <= 0
     OR p_montant_commission_cts <= 0
     OR p_montant_total_cts <> p_montant_soignant_cts + p_montant_commission_cts THEN
    RAISE EXCEPTION 'Paramètres de rapprochement Connect invalides'
      USING ERRCODE = '22023';
  END IF;

  SELECT m.* INTO v_mission
  FROM public.missions m
  WHERE m.id = p_mission_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_mission.etablissement_id <> p_etablissement_id
     OR v_mission.soignant_assigne_id <> p_soignant_id
     OR v_mission.statut <> 'TERMINEE'
     OR v_mission.type_contrat_applique <> 'LIBERAL'
     OR round(v_mission.net_a_payer * 100)::integer <> p_montant_soignant_cts
     OR round(v_mission.montant_commission_ttc * 100)::integer <> p_montant_commission_cts THEN
    RAISE EXCEPTION 'Mission Connect incohérente' USING ERRCODE = 'P0001';
  END IF;

  SELECT st.* INTO v_transfer
  FROM public.stripe_transfers st
  WHERE st.mission_id = p_mission_id
    AND st.stripe_checkout_session_id = p_stripe_checkout_session_id
  ORDER BY st.cree_le DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND
     OR v_transfer.soignant_id <> p_soignant_id
     OR v_transfer.etablissement_id <> p_etablissement_id
     OR round(v_transfer.montant_soignant * 100)::integer <> p_montant_soignant_cts
     OR round(v_transfer.montant_commission * 100)::integer <> p_montant_commission_cts
     OR round(v_transfer.montant_total * 100)::integer <> p_montant_total_cts
     OR v_transfer.statut NOT IN ('EN_ATTENTE', 'ECHOUE', 'CHARGE_REUSSI', 'TRANSFERE', 'PAYE')
     OR (v_transfer.stripe_payment_intent_id IS NOT NULL
         AND v_transfer.stripe_payment_intent_id <> p_stripe_payment_intent_id)
     OR (v_transfer.stripe_transfer_id IS NOT NULL
         AND v_transfer.stripe_transfer_id <> p_stripe_transfer_id) THEN
    RAISE EXCEPTION 'Trace Connect incohérente' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.stripe_transfers
  SET statut = CASE
        WHEN statut = 'PAYE' THEN 'PAYE'
        ELSE 'TRANSFERE'
      END,
      stripe_payment_intent_id = p_stripe_payment_intent_id,
      stripe_charge_id = p_stripe_charge_id,
      stripe_transfer_id = p_stripe_transfer_id,
      transfere_le = COALESCE(transfere_le, p_rapproche_le, now()),
      erreur = NULL
  WHERE id = v_transfer.id;

  SELECT fh.* INTO v_honoraires
  FROM public.factures_honoraires fh
  WHERE fh.id = p_facture_honoraires_id
  FOR UPDATE;
  IF NOT FOUND
     OR v_honoraires.type_document <> 'FACTURE'
     OR v_honoraires.mission_id <> p_mission_id
     OR v_honoraires.soignant_id <> p_soignant_id
     OR v_honoraires.etablissement_id <> p_etablissement_id
     OR round(v_honoraires.montant_ttc * 100)::integer <> p_montant_soignant_cts
     OR v_honoraires.statut NOT IN ('EMISE', 'EN_RETARD', 'PAYEE')
     OR (v_honoraires.stripe_payment_intent_id IS NOT NULL
         AND v_honoraires.stripe_payment_intent_id <> p_stripe_payment_intent_id) THEN
    RAISE EXCEPTION 'Facture honoraires Connect incohérente' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.factures_honoraires
  SET statut = 'PAYEE',
      stripe_payment_intent_id = p_stripe_payment_intent_id,
      date_paiement = COALESCE(date_paiement, (COALESCE(p_rapproche_le, now()))::date),
      modifie_le = now()
  WHERE id = v_honoraires.id;

  IF p_facture_commission_id IS NOT NULL THEN
    SELECT f.* INTO v_commission
    FROM public.factures f
    WHERE f.id = p_facture_commission_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_commission.type_document <> 'FACTURE'
       OR v_commission.mission_id <> p_mission_id
       OR v_commission.etablissement_id <> p_etablissement_id
       OR round(v_commission.montant_ttc * 100)::integer <> p_montant_commission_cts
       OR v_commission.statut NOT IN ('EMISE', 'EN_RETARD', 'PAYEE')
       OR (v_commission.stripe_payment_intent_id IS NOT NULL
           AND v_commission.stripe_payment_intent_id <> p_stripe_payment_intent_id) THEN
      RAISE EXCEPTION 'Facture commission Connect incohérente' USING ERRCODE = 'P0001';
    END IF;
    UPDATE public.factures
    SET statut = 'PAYEE',
        stripe_payment_intent_id = p_stripe_payment_intent_id,
        date_paiement = COALESCE(date_paiement, p_rapproche_le, now()),
        mode_paiement = 'STRIPE',
        modifie_le = now()
    WHERE id = v_commission.id;
  ELSE
    v_numero_commission := 'FACT-STRIPE-'
      || to_char(COALESCE(p_rapproche_le, now()), 'YYYY-MM-DD')
      || '-' || split_part(p_mission_id::text, '-', 1);
    INSERT INTO public.factures (
      etablissement_id, mission_id, numero_facture,
      montant_ht, montant_tva, montant_ttc, taux_tva, nombre_missions,
      statut, date_emission, date_paiement, mode_paiement,
      stripe_payment_intent_id, type_document
    ) VALUES (
      p_etablissement_id, p_mission_id, v_numero_commission,
      v_mission.montant_commission_ht,
      v_mission.montant_commission_tva,
      v_mission.montant_commission_ttc,
      20, 1,
      'PAYEE', COALESCE(p_rapproche_le, now()), COALESCE(p_rapproche_le, now()),
      'STRIPE', p_stripe_payment_intent_id, 'FACTURE'
    )
    ON CONFLICT (numero_facture) DO NOTHING;

    SELECT f.* INTO v_commission
    FROM public.factures f
    WHERE f.numero_facture = v_numero_commission
    FOR UPDATE;
    IF NOT FOUND
       OR v_commission.mission_id <> p_mission_id
       OR v_commission.etablissement_id <> p_etablissement_id
       OR v_commission.statut <> 'PAYEE'
       OR v_commission.stripe_payment_intent_id <> p_stripe_payment_intent_id
       OR round(v_commission.montant_ttc * 100)::integer <> p_montant_commission_cts THEN
      RAISE EXCEPTION 'Création facture commission Connect incohérente'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  INSERT INTO public.paiements_soignant (
    mission_id, soignant_id, etablissement_id, montant_net, methode,
    reference_virement, date_paiement, statut,
    confirme_par_etablissement, confirme_par_etablissement_le,
    confirme_par_soignant, confirme_par_soignant_le, stripe_transfer_id
  ) VALUES (
    p_mission_id, p_soignant_id, p_etablissement_id,
    p_montant_soignant_cts::numeric / 100, 'NOTE_HONORAIRES',
    'STRIPE-' || p_stripe_transfer_id,
    (COALESCE(p_rapproche_le, now()))::date, 'CONFIRME',
    true, COALESCE(p_rapproche_le, now()),
    true, COALESCE(p_rapproche_le, now()), p_stripe_transfer_id
  )
  ON CONFLICT (stripe_transfer_id) WHERE stripe_transfer_id IS NOT NULL
  DO NOTHING;

  SELECT count(*) INTO v_rows
  FROM public.paiements_soignant ps
  WHERE ps.stripe_transfer_id = p_stripe_transfer_id
    AND ps.mission_id = p_mission_id
    AND ps.soignant_id = p_soignant_id
    AND ps.etablissement_id = p_etablissement_id
    AND round(ps.montant_net * 100)::integer = p_montant_soignant_cts
    AND ps.statut = 'CONFIRME';
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Paiement soignant Connect incohérent' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.missions
  SET mode_paiement_soignant = 'STRIPE_CONNECT',
      commission_facturee = true,
      modifie_le = now()
  WHERE id = p_mission_id;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    details, navigateur_acteur
  ) VALUES (
    p_soignant_id,
    'SYSTEME',
    'FINANCE_TRANSFER_CONNECT',
    'mission',
    p_mission_id,
    jsonb_build_object(
      'stripe_transfer_id', p_stripe_transfer_id,
      'stripe_charge_id', p_stripe_charge_id,
      'stripe_payment_intent_id', p_stripe_payment_intent_id,
      'stripe_session_id', p_stripe_checkout_session_id,
      'facture_honoraires_id', p_facture_honoraires_id,
      'facture_commission_id', v_commission.id,
      'montant_cents', p_montant_soignant_cts,
      'evenement', 'CONNECT_RAPPROCHEMENT_LOCAL_ATOMIQUE'
    ),
    'fn_stripe_connect_rapprocher_local'
  );

  RETURN jsonb_build_object(
    'success', true,
    'stripe_transfer_id', p_stripe_transfer_id,
    'facture_commission_id', v_commission.id
  );
END;
$_$;


ALTER FUNCTION "public"."fn_stripe_connect_rapprocher_local"("p_mission_id" "uuid", "p_soignant_id" "uuid", "p_etablissement_id" "uuid", "p_facture_honoraires_id" "uuid", "p_facture_commission_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text", "p_stripe_charge_id" "text", "p_stripe_transfer_id" "text", "p_montant_soignant_cts" integer, "p_montant_commission_cts" integer, "p_montant_total_cts" integer, "p_rapproche_le" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_lier_payout_transfers"("p_stripe_payout_id" "text", "p_soignant_id" "uuid", "p_stripe_transfer_ids" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated integer := 0;
BEGIN
  IF COALESCE(current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(btrim(COALESCE(p_stripe_payout_id, '')), '') IS NULL
     OR p_soignant_id IS NULL THEN
    RAISE EXCEPTION 'Paramètres payout invalides' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(array_length(p_stripe_transfer_ids, 1), 0) = 0 THEN
    RETURN 0;
  END IF;

  PERFORM 1
  FROM public.stripe_transfers st
  WHERE st.soignant_id = p_soignant_id
    AND st.stripe_transfer_id = ANY(p_stripe_transfer_ids)
  FOR UPDATE;

  IF EXISTS (
    SELECT 1
    FROM public.stripe_transfers st
    WHERE st.soignant_id = p_soignant_id
      AND st.stripe_transfer_id = ANY(p_stripe_transfer_ids)
      AND st.stripe_payout_id IS NOT NULL
      AND st.stripe_payout_id <> p_stripe_payout_id
  ) THEN
    RAISE EXCEPTION 'Transfer déjà lié à un autre payout' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.stripe_transfers st
  SET stripe_payout_id = p_stripe_payout_id
  WHERE st.soignant_id = p_soignant_id
    AND st.stripe_transfer_id = ANY(p_stripe_transfer_ids)
    AND (st.stripe_payout_id IS NULL OR st.stripe_payout_id = p_stripe_payout_id);

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."fn_stripe_lier_payout_transfers"("p_stripe_payout_id" "text", "p_soignant_id" "uuid", "p_stripe_transfer_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_payment_flow_adopter_legacy"("p_flow" "text", "p_owner_token" "text", "p_facture_id" "uuid", "p_stripe_checkout_session_id" "text" DEFAULT NULL::"text", "p_stripe_payment_intent_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_resources text[];
  v_resource text;
  v_stripe_lock_keys text[];
  v_legacy_owner_token text := 'legacy:' || p_facture_id::text;
  v_facture_payment_intent_id text;
  v_etablissement_id uuid;
  v_conflict public.stripe_payment_flow_claims%ROWTYPE;
  v_session_ids text[];
  v_intent_ids text[];
  v_legacy_count integer;
  v_desired_count integer;
  v_claim_count integer;
  v_audit jsonb;
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;
  IF p_flow NOT IN ('CHECKOUT_INVOICE', 'SEPA_INVOICE')
     OR NULLIF(btrim(p_owner_token), '') IS NULL
     OR p_facture_id IS NULL
     OR (p_stripe_checkout_session_id IS NULL AND p_stripe_payment_intent_id IS NULL)
     OR (
       p_flow = 'SEPA_INVOICE'
       AND (
         p_stripe_checkout_session_id IS NOT NULL
         OR p_stripe_payment_intent_id IS NULL
       )
     )
     OR (
       p_stripe_checkout_session_id IS NOT NULL
       AND p_stripe_checkout_session_id !~ '^cs_(test|live)_[A-Za-z0-9]+$'
     )
     OR (
       p_stripe_payment_intent_id IS NOT NULL
       AND p_stripe_payment_intent_id !~ '^pi_[A-Za-z0-9]+$'
     ) THEN
    RAISE EXCEPTION 'Paramètres d''adoption Stripe legacy invalides' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(DISTINCT r.resource_key ORDER BY r.resource_key)
  INTO v_resources
  FROM (
    SELECT 'FACTURE:' || p_facture_id::text AS resource_key
    UNION ALL
    SELECT 'MISSION:' || f.mission_id::text
    FROM public.factures f
    WHERE f.id = p_facture_id AND f.mission_id IS NOT NULL
    UNION ALL
    SELECT 'MISSION:' || m.id::text
    FROM public.missions m
    WHERE m.facture_id = p_facture_id
  ) r;

  FOREACH v_resource IN ARRAY v_resources LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_resource, 0));
  END LOOP;

  SELECT array_agg(lock_key ORDER BY lock_key)
  INTO v_stripe_lock_keys
  FROM unnest(ARRAY[
    CASE
      WHEN p_stripe_checkout_session_id IS NOT NULL
      THEN 'STRIPE_SESSION:' || p_stripe_checkout_session_id
    END,
    CASE
      WHEN p_stripe_payment_intent_id IS NOT NULL
      THEN 'STRIPE_INTENT:' || p_stripe_payment_intent_id
    END
  ]) AS locks(lock_key)
  WHERE lock_key IS NOT NULL;
  FOREACH v_resource IN ARRAY v_stripe_lock_keys LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_resource, 0));
  END LOOP;

  SELECT f.stripe_payment_intent_id, f.etablissement_id
  INTO v_facture_payment_intent_id, v_etablissement_id
  FROM public.factures f
  WHERE f.id = p_facture_id
    AND f.type_document = 'FACTURE'
    AND f.statut <> 'ANNULEE'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Facture legacy introuvable ou non payable' USING ERRCODE = 'P0002';
  END IF;
  IF v_facture_payment_intent_id IS NOT NULL
     AND v_facture_payment_intent_id IS DISTINCT FROM p_stripe_payment_intent_id THEN
    RAISE EXCEPTION 'PaymentIntent Stripe legacy différent de la facture' USING ERRCODE = '23514';
  END IF;

  -- Toute collision Connect, tout autre flux, ou même un owner legacy qui ne
  -- correspond pas exactement à la facture bloque l'adoption.
  SELECT c.*
  INTO v_conflict
  FROM public.stripe_payment_flow_claims c
  WHERE c.resource_key = ANY(v_resources)
    AND NOT (
      (c.flow = 'LEGACY_UNKNOWN' AND c.owner_token = v_legacy_owner_token)
      OR (c.flow = p_flow AND c.owner_token = p_owner_token)
    )
  ORDER BY c.resource_key
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'Claim Stripe concurrent incompatible: %', v_conflict.resource_key
      USING ERRCODE = '40001';
  END IF;

  SELECT c.*
  INTO v_conflict
  FROM public.stripe_payment_flow_claims c
  WHERE (
      (
        p_stripe_checkout_session_id IS NOT NULL
        AND c.stripe_checkout_session_id = p_stripe_checkout_session_id
      )
      OR (
        p_stripe_payment_intent_id IS NOT NULL
        AND c.stripe_payment_intent_id = p_stripe_payment_intent_id
      )
    )
    AND NOT (
      (c.flow = 'LEGACY_UNKNOWN' AND c.owner_token = v_legacy_owner_token)
      OR (c.flow = p_flow AND c.owner_token = p_owner_token)
    )
  ORDER BY c.resource_key
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'Objet Stripe déjà revendiqué par un autre paiement: %', v_conflict.resource_key
      USING ERRCODE = '23505';
  END IF;

  SELECT
    count(*) FILTER (
      WHERE c.flow = 'LEGACY_UNKNOWN' AND c.owner_token = v_legacy_owner_token
    ),
    count(*) FILTER (
      WHERE c.flow = p_flow AND c.owner_token = p_owner_token
    ),
    count(*),
    array_agg(DISTINCT c.stripe_checkout_session_id)
      FILTER (WHERE c.stripe_checkout_session_id IS NOT NULL),
    array_agg(DISTINCT c.stripe_payment_intent_id)
      FILTER (WHERE c.stripe_payment_intent_id IS NOT NULL)
  INTO
    v_legacy_count,
    v_desired_count,
    v_claim_count,
    v_session_ids,
    v_intent_ids
  FROM public.stripe_payment_flow_claims c
  WHERE c.resource_key = ANY(v_resources);

  IF v_legacy_count = 0 AND v_desired_count = 0 THEN
    RAISE EXCEPTION 'Aucun claim Stripe legacy à adopter' USING ERRCODE = 'P0002';
  END IF;
  IF COALESCE(array_length(v_session_ids, 1), 0) > 1
     OR COALESCE(array_length(v_intent_ids, 1), 0) > 1 THEN
    RAISE EXCEPTION 'Claims Stripe legacy incohérents' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(array_length(v_session_ids, 1), 0) = 1
     AND v_session_ids[1] IS DISTINCT FROM p_stripe_checkout_session_id THEN
    RAISE EXCEPTION 'Checkout Session legacy différente de la preuve Stripe' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(array_length(v_intent_ids, 1), 0) = 1
     AND v_intent_ids[1] IS DISTINCT FROM p_stripe_payment_intent_id THEN
    RAISE EXCEPTION 'PaymentIntent legacy différent de la preuve Stripe' USING ERRCODE = '23514';
  END IF;

  UPDATE public.stripe_payment_flow_claims c
  SET
    flow = p_flow,
    owner_token = p_owner_token,
    stripe_checkout_session_id = p_stripe_checkout_session_id,
    stripe_payment_intent_id = p_stripe_payment_intent_id,
    modifie_le = now()
  WHERE c.resource_key = ANY(v_resources)
    AND (
      (c.flow = 'LEGACY_UNKNOWN' AND c.owner_token = v_legacy_owner_token)
      OR (c.flow = p_flow AND c.owner_token = p_owner_token)
    );

  INSERT INTO public.stripe_payment_flow_claims (
    resource_key,
    flow,
    owner_token,
    stripe_checkout_session_id,
    stripe_payment_intent_id
  )
  SELECT
    r.resource_key,
    p_flow,
    p_owner_token,
    p_stripe_checkout_session_id,
    p_stripe_payment_intent_id
  FROM unnest(v_resources) AS r(resource_key)
  ON CONFLICT (resource_key) DO NOTHING;

  SELECT count(*)
  INTO v_claim_count
  FROM public.stripe_payment_flow_claims c
  WHERE c.resource_key = ANY(v_resources)
    AND c.flow = p_flow
    AND c.owner_token = p_owner_token
    AND c.stripe_checkout_session_id IS NOT DISTINCT FROM p_stripe_checkout_session_id
    AND c.stripe_payment_intent_id IS NOT DISTINCT FROM p_stripe_payment_intent_id;

  IF v_claim_count <> cardinality(v_resources) THEN
    RAISE EXCEPTION 'Adoption Stripe legacy non atomique' USING ERRCODE = '40001';
  END IF;

  v_audit := public.fn_ecrire_audit_safe(
    v_etablissement_id,
    'SYSTEME',
    'ADMIN_ACTION',
    'facture',
    p_facture_id,
    NULL,
    jsonb_build_object(
      'evenement', 'FACTURE_LEGACY_STRIPE_ADOPTEE',
      'flow', p_flow,
      'stripe_session_id', p_stripe_checkout_session_id,
      'stripe_payment_intent_id', p_stripe_payment_intent_id,
      'adoption_effective', v_legacy_count > 0
    ),
    NULL,
    'fn_stripe_payment_flow_adopter_legacy'
  );
  IF COALESCE(v_audit @> '{"success": true}'::jsonb, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Audit adoption Stripe legacy non écrit';
  END IF;

  RETURN jsonb_build_object(
    'adopted', v_legacy_count > 0,
    'flow', p_flow,
    'owner_token', p_owner_token,
    'resources', v_resources,
    'stripe_checkout_session_id', p_stripe_checkout_session_id,
    'stripe_payment_intent_id', p_stripe_payment_intent_id
  );
END;
$_$;


ALTER FUNCTION "public"."fn_stripe_payment_flow_adopter_legacy"("p_flow" "text", "p_owner_token" "text", "p_facture_id" "uuid", "p_stripe_checkout_session_id" "text", "p_stripe_payment_intent_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_payment_flow_claim"("p_flow" "text", "p_owner_token" "text", "p_facture_id" "uuid" DEFAULT NULL::"uuid", "p_mission_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_resources text[];
  v_resource text;
  v_conflict public.stripe_payment_flow_claims%ROWTYPE;
  v_session_ids text[];
  v_intent_ids text[];
BEGIN
  IF COALESCE(auth.jwt()->>'role', current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;
  IF p_flow NOT IN ('CHECKOUT_INVOICE', 'SEPA_INVOICE', 'CONNECT_MISSION', 'CONNECT_INVOICE')
     OR NULLIF(btrim(p_owner_token), '') IS NULL
     OR ((p_facture_id IS NULL) = (p_mission_id IS NULL)) THEN
    RAISE EXCEPTION 'Paramètres de claim Stripe invalides' USING ERRCODE = '22023';
  END IF;

  IF p_facture_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.factures f
      WHERE f.id = p_facture_id
        AND f.type_document = 'FACTURE'
        AND f.statut <> 'ANNULEE'
    ) THEN
      RAISE EXCEPTION 'Facture de claim introuvable ou non payable' USING ERRCODE = 'P0002';
    END IF;
    IF p_flow = 'CONNECT_INVOICE' THEN
      v_resources := ARRAY['FACTURE:' || p_facture_id::text];
    ELSE
      SELECT array_agg(DISTINCT r.resource_key ORDER BY r.resource_key)
      INTO v_resources
      FROM (
        SELECT 'FACTURE:' || p_facture_id::text AS resource_key
        UNION ALL
        SELECT 'MISSION:' || f.mission_id::text
        FROM public.factures f
        WHERE f.id = p_facture_id AND f.mission_id IS NOT NULL
        UNION ALL
        SELECT 'MISSION:' || m.id::text
        FROM public.missions m
        WHERE m.facture_id = p_facture_id
      ) r;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.missions m WHERE m.id = p_mission_id) THEN
      RAISE EXCEPTION 'Mission de claim introuvable' USING ERRCODE = 'P0002';
    END IF;
    v_resources := ARRAY['MISSION:' || p_mission_id::text];
  END IF;

  FOREACH v_resource IN ARRAY v_resources LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(v_resource, 0));
  END LOOP;

  SELECT c.* INTO v_conflict
  FROM public.stripe_payment_flow_claims c
  WHERE c.resource_key = ANY(v_resources)
    AND (c.flow <> p_flow OR c.owner_token <> p_owner_token)
  ORDER BY c.resource_key
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'acquired', false,
      'flow', v_conflict.flow,
      'owner_token', v_conflict.owner_token,
      'resources', v_resources,
      'stripe_checkout_session_id', v_conflict.stripe_checkout_session_id,
      'stripe_payment_intent_id', v_conflict.stripe_payment_intent_id
    );
  END IF;

  INSERT INTO public.stripe_payment_flow_claims (resource_key, flow, owner_token)
  SELECT r.resource_key, p_flow, p_owner_token
  FROM unnest(v_resources) AS r(resource_key)
  ON CONFLICT (resource_key) DO NOTHING;

  SELECT
    array_agg(DISTINCT c.stripe_checkout_session_id)
      FILTER (WHERE c.stripe_checkout_session_id IS NOT NULL),
    array_agg(DISTINCT c.stripe_payment_intent_id)
      FILTER (WHERE c.stripe_payment_intent_id IS NOT NULL)
  INTO v_session_ids, v_intent_ids
  FROM public.stripe_payment_flow_claims c
  WHERE c.resource_key = ANY(v_resources)
    AND c.flow = p_flow
    AND c.owner_token = p_owner_token;

  IF COALESCE(array_length(v_session_ids, 1), 0) > 1
     OR COALESCE(array_length(v_intent_ids, 1), 0) > 1 THEN
    RAISE EXCEPTION 'Claims Stripe du même flux incohérents' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(array_length(v_session_ids, 1), 0) = 1 THEN
    UPDATE public.stripe_payment_flow_claims c
    SET stripe_checkout_session_id = v_session_ids[1], modifie_le = now()
    WHERE c.resource_key = ANY(v_resources)
      AND c.flow = p_flow
      AND c.owner_token = p_owner_token
      AND c.stripe_checkout_session_id IS NULL;
  END IF;
  IF COALESCE(array_length(v_intent_ids, 1), 0) = 1 THEN
    UPDATE public.stripe_payment_flow_claims c
    SET stripe_payment_intent_id = v_intent_ids[1], modifie_le = now()
    WHERE c.resource_key = ANY(v_resources)
      AND c.flow = p_flow
      AND c.owner_token = p_owner_token
      AND c.stripe_payment_intent_id IS NULL;
  END IF;

  RETURN jsonb_build_object(
    'acquired', true,
    'flow', p_flow,
    'owner_token', p_owner_token,
    'resources', v_resources,
    'stripe_checkout_session_id', v_session_ids[1],
    'stripe_payment_intent_id', v_intent_ids[1]
  );
END;
$$;


ALTER FUNCTION "public"."fn_stripe_payment_flow_claim"("p_flow" "text", "p_owner_token" "text", "p_facture_id" "uuid", "p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_refund_rapprocher"("p_queue_id" "uuid", "p_stripe_refund_id" "text", "p_resultat" "text", "p_detail" "text" DEFAULT NULL::"text", "p_finalise_le" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_queue public.stripe_refunds_queue%ROWTYPE;
  v_avoir public.factures_honoraires%ROWTYPE;
  v_escrow public.paiements_escrow%ROWTYPE;
  v_rows integer;
  v_legacy_escrow boolean := false;
BEGIN
  IF COALESCE(
       auth.jwt()->>'role',
       current_setting('request.jwt.claim.role', true),
       ''
     ) <> 'service_role'
     AND session_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Service role requis' USING ERRCODE = '42501';
  END IF;

  IF p_queue_id IS NULL
     OR p_resultat NOT IN ('SUCCEEDED', 'FAILED', 'CANCELED') THEN
    RAISE EXCEPTION 'Rapprochement refund invalide' USING ERRCODE = '22023';
  END IF;

  -- Un refund effectivement créé porte toujours son identifiant Stripe. Un
  -- échec de validation/création peut être terminal avant que Stripe n'ait
  -- créé le moindre objet ; NULL reste alors une provenance explicite.
  IF p_resultat IN ('SUCCEEDED', 'CANCELED')
     AND (p_stripe_refund_id IS NULL
          OR p_stripe_refund_id !~ '^re_[A-Za-z0-9]+$') THEN
    RAISE EXCEPTION 'Identifiant Stripe refund requis' USING ERRCODE = '22023';
  END IF;
  IF p_stripe_refund_id IS NOT NULL
     AND p_stripe_refund_id !~ '^re_[A-Za-z0-9]+$' THEN
    RAISE EXCEPTION 'Identifiant Stripe refund invalide' USING ERRCODE = '22023';
  END IF;

  SELECT q.*
    INTO v_queue
    FROM public.stripe_refunds_queue q
   WHERE q.id = p_queue_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Queue refund introuvable' USING ERRCODE = 'P0001';
  END IF;

  IF v_queue.stripe_refund_id IS NOT NULL
     AND v_queue.stripe_refund_id <> p_stripe_refund_id THEN
    RAISE EXCEPTION 'Refund Stripe différent déjà lié à la queue'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_resultat = 'SUCCEEDED' AND v_queue.statut = 'TRAITE' THEN
    IF v_queue.stripe_refund_id = p_stripe_refund_id THEN
      RETURN jsonb_build_object('success', true, 'already_processed', true);
    END IF;
    RAISE EXCEPTION 'Queue traitée sans le refund attendu' USING ERRCODE = 'P0001';
  END IF;

  IF p_resultat IN ('FAILED', 'CANCELED') AND v_queue.statut = 'ECHEC' THEN
    IF v_queue.stripe_refund_id IS NOT DISTINCT FROM p_stripe_refund_id THEN
      RETURN jsonb_build_object('success', true, 'already_processed', true);
    END IF;
    RAISE EXCEPTION 'Queue en échec sans le refund attendu' USING ERRCODE = 'P0001';
  END IF;

  IF v_queue.statut NOT IN ('EN_ATTENTE', 'EN_COURS') THEN
    RAISE EXCEPTION 'Transition refund interdite depuis %', v_queue.statut
      USING ERRCODE = 'P0001';
  END IF;

  IF p_resultat = 'SUCCEEDED' THEN
    IF v_queue.avoir_id IS NOT NULL THEN
      SELECT fh.*
        INTO v_avoir
        FROM public.factures_honoraires fh
       WHERE fh.id = v_queue.avoir_id
         AND fh.type_document = 'AVOIR'
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Avoir de la queue introuvable' USING ERRCODE = 'P0001';
      END IF;
      IF round(abs(v_avoir.montant_ttc) * 100)::integer <> v_queue.montant_cts THEN
        RAISE EXCEPTION 'Montant de l''avoir incohérent avec la queue'
          USING ERRCODE = 'P0001';
      END IF;

      IF v_avoir.statut = 'REMBOURSE' THEN
        IF v_avoir.reference_remboursement IS DISTINCT FROM p_stripe_refund_id THEN
          RAISE EXCEPTION 'Avoir déjà rapproché avec une autre référence'
            USING ERRCODE = 'P0001';
        END IF;
      ELSE
        UPDATE public.factures_honoraires
           SET statut = 'REMBOURSE',
               date_remboursement = COALESCE(p_finalise_le, now()),
               reference_remboursement = p_stripe_refund_id
         WHERE id = v_avoir.id
           AND statut IN ('EMISE', 'EN_RETARD');
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows <> 1 THEN
          RAISE EXCEPTION 'État de l''avoir non remboursable: %', v_avoir.statut
            USING ERRCODE = 'P0001';
        END IF;
      END IF;
    END IF;

    IF v_queue.paiement_escrow_id IS NOT NULL THEN
      SELECT pe.*
        INTO v_escrow
        FROM public.paiements_escrow pe
       WHERE pe.id = v_queue.paiement_escrow_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Escrow de la queue introuvable' USING ERRCODE = 'P0001';
      END IF;

      IF v_escrow.statut = 'REMBOURSE' THEN
        -- Compatibilité défensive pour une éventuelle ligne créée avant cette
        -- migration. La production était vide lors de l'audit pré-déploiement.
        v_legacy_escrow := true;
      ELSIF v_escrow.statut = 'REMBOURSE_EN_COURS' THEN
        UPDATE public.paiements_escrow
           SET statut = 'REMBOURSE',
               erreur = NULL,
               modifie_le = now()
         WHERE id = v_escrow.id
           AND statut = 'REMBOURSE_EN_COURS';
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows <> 1 THEN
          RAISE EXCEPTION 'Finalisation escrow concurrente refusée';
        END IF;
      ELSE
        RAISE EXCEPTION 'État escrow incompatible avec refund réussi: %',
          v_escrow.statut USING ERRCODE = 'P0001';
      END IF;

      UPDATE public.escrow_exposition_releases
         SET statut = 'REGLE'
       WHERE paiement_escrow_id = v_escrow.id
         AND statut = 'ACTIF';
    END IF;

    UPDATE public.stripe_refunds_queue
       SET statut = 'TRAITE',
           stripe_refund_id = p_stripe_refund_id,
           traite_le = COALESCE(p_finalise_le, now()),
           dernier_essai_le = now(),
           erreur = NULL
     WHERE id = v_queue.id
       AND statut IN ('EN_ATTENTE', 'EN_COURS');
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows <> 1 THEN
      RAISE EXCEPTION 'Finalisation queue concurrente refusée';
    END IF;

    INSERT INTO public.journaux_audit (
      acteur_id, type_acteur, action, type_ressource, id_ressource,
      details, navigateur_acteur
    ) VALUES (
      '00000000-0000-0000-0000-000000000000'::uuid,
      'SYSTEME',
      CASE
        WHEN v_queue.avoir_id IS NOT NULL THEN 'AVOIR_REMBOURSEMENT_CONFIRME'
        WHEN v_queue.paiement_escrow_id IS NOT NULL THEN 'ESCROW_REMBOURSE'
        ELSE 'FINANCE_CHARGE_REFUNDED'
      END,
      CASE
        WHEN v_queue.avoir_id IS NOT NULL THEN 'facture_honoraires'
        WHEN v_queue.paiement_escrow_id IS NOT NULL THEN 'paiement_escrow'
        ELSE 'stripe_refunds_queue'
      END,
      COALESCE(v_queue.avoir_id, v_queue.paiement_escrow_id, v_queue.id),
      jsonb_build_object(
        'queue_id', v_queue.id,
        'stripe_refund_id', p_stripe_refund_id,
        'stripe_payment_intent_id', v_queue.stripe_payment_intent_id,
        'montant_cts', v_queue.montant_cts
      ),
      'fn_stripe_refund_rapprocher'
    );

    RETURN jsonb_build_object(
      'success', true,
      'resultat', 'SUCCEEDED',
      'legacy_escrow', v_legacy_escrow
    );
  END IF;

  -- failed/canceled : le remboursement n'a pas eu lieu. Restaurer l'escrow
  -- exactement dans son état antérieur ; ne jamais solder son exposition.
  IF v_queue.paiement_escrow_id IS NOT NULL THEN
    SELECT pe.*
      INTO v_escrow
      FROM public.paiements_escrow pe
     WHERE pe.id = v_queue.paiement_escrow_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Escrow de la queue introuvable' USING ERRCODE = 'P0001';
    END IF;

    IF v_escrow.statut = 'REMBOURSE_EN_COURS' THEN
      IF v_queue.escrow_statut_avant_remboursement NOT IN (
        'DEBITE', 'DISPONIBLE', 'PAYE'
      ) THEN
        RAISE EXCEPTION 'État escrow antérieur absent ou invalide'
          USING ERRCODE = 'P0001';
      END IF;
      UPDATE public.paiements_escrow
         SET statut = v_queue.escrow_statut_avant_remboursement,
             erreur = left(COALESCE(p_detail, p_resultat), 500),
             modifie_le = now()
       WHERE id = v_escrow.id
         AND statut = 'REMBOURSE_EN_COURS';
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows <> 1 THEN
        RAISE EXCEPTION 'Restauration escrow concurrente refusée';
      END IF;
    ELSIF v_escrow.statut <> 'REMBOURSE' THEN
      RAISE EXCEPTION 'État escrow incompatible avec refund échoué: %',
        v_escrow.statut USING ERRCODE = 'P0001';
    END IF;
  END IF;

  UPDATE public.stripe_refunds_queue
     SET statut = 'ECHEC',
         stripe_refund_id = COALESCE(p_stripe_refund_id, stripe_refund_id),
         dernier_essai_le = now(),
         erreur = left(COALESCE(p_detail, p_resultat), 500)
   WHERE id = v_queue.id
     AND statut IN ('EN_ATTENTE', 'EN_COURS');
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows <> 1 THEN
    RAISE EXCEPTION 'Échec queue concurrent refusé';
  END IF;

  INSERT INTO public.journaux_audit (
    acteur_id, type_acteur, action, type_ressource, id_ressource,
    details, navigateur_acteur
  ) VALUES (
    '00000000-0000-0000-0000-000000000000'::uuid,
    'SYSTEME',
    'ADMIN_ACTION',
    'stripe_refunds_queue',
    v_queue.id,
    jsonb_build_object(
      'evenement', 'FINANCE_REFUND_TERMINE_SANS_SUCCES',
      'queue_id', v_queue.id,
      'stripe_refund_id', p_stripe_refund_id,
      'resultat', p_resultat,
      'detail', p_detail
    ),
    'fn_stripe_refund_rapprocher'
  );

  RETURN jsonb_build_object('success', true, 'resultat', p_resultat);
END;
$_$;


ALTER FUNCTION "public"."fn_stripe_refund_rapprocher"("p_queue_id" "uuid", "p_stripe_refund_id" "text", "p_resultat" "text", "p_detail" "text", "p_finalise_le" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_webhook_event_claim"("p_event_id" "text", "p_event_type" "text", "p_payload" "jsonb", "p_source_webhook" "text", "p_livemode" boolean) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inserted integer := 0;
  v_claimed integer := 0;
  v_traite_le timestamptz;
BEGIN
  IF NOT (
    public.est_admin()
    OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role'
  ) THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  IF p_source_webhook NOT IN ('PLATFORM', 'CONNECT') THEN
    RAISE EXCEPTION 'Source webhook invalide' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.stripe_webhook_events (
    event_id,
    event_type,
    payload,
    source_webhook,
    livemode,
    traitement_commence_le,
    tentatives
  ) VALUES (
    p_event_id,
    p_event_type,
    p_payload,
    p_source_webhook,
    p_livemode,
    now(),
    1
  )
  ON CONFLICT (event_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 1 THEN
    RETURN 'CLAIMED';
  END IF;

  SELECT traite_le
    INTO v_traite_le
  FROM public.stripe_webhook_events
  WHERE event_id = p_event_id;

  IF v_traite_le IS NOT NULL THEN
    RETURN 'PROCESSED';
  END IF;

  -- Reprise possible après cinq minutes. Une Edge Function ne doit pas rester
  -- active aussi longtemps ; ce lease couvre un crash sans bloquer l'event à vie.
  UPDATE public.stripe_webhook_events
  SET traitement_commence_le = now(),
      tentatives = tentatives + 1,
      erreur = NULL,
      event_type = p_event_type,
      payload = p_payload,
      source_webhook = p_source_webhook,
      livemode = p_livemode
  WHERE event_id = p_event_id
    AND traite_le IS NULL
    AND (
      traitement_commence_le IS NULL
      OR traitement_commence_le < now() - interval '5 minutes'
    );

  GET DIAGNOSTICS v_claimed = ROW_COUNT;
  IF v_claimed = 1 THEN
    RETURN 'CLAIMED';
  END IF;

  RETURN 'PROCESSING';
END;
$$;


ALTER FUNCTION "public"."fn_stripe_webhook_event_claim"("p_event_id" "text", "p_event_type" "text", "p_payload" "jsonb", "p_source_webhook" "text", "p_livemode" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_stripe_webhook_event_is_new"("p_event_id" "text", "p_event_type" "text", "p_payload" "jsonb" DEFAULT NULL::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT (est_admin() OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role') THEN
    RAISE EXCEPTION 'Accès refusé' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.stripe_webhook_events (event_id, event_type, payload)
  VALUES (p_event_id, p_event_type, p_payload)
  ON CONFLICT (event_id) DO NOTHING;

  -- TRUE tant que l'event n'a PAS été traité avec succès (traite_le IS NULL) :
  -- couvre le nouvel event ET le retry Stripe d'un event qui avait échoué.
  -- FALSE seulement si déjà traité avec succès → idempotence.
  -- (Avant : « AND recu_le > NOW() - INTERVAL '1 minute' » faisait que tout retry
  -- Stripe arrivant >1 min après l'échec initial était faussement considéré
  -- « déjà traité » → l'edge renvoyait 200, Stripe arrêtait de réessayer, et le
  -- webhook en échec était définitivement perdu.)
  RETURN EXISTS (
    SELECT 1 FROM public.stripe_webhook_events
    WHERE event_id = p_event_id AND traite_le IS NULL
  );
END;
$$;


ALTER FUNCTION "public"."fn_stripe_webhook_event_is_new"("p_event_id" "text", "p_event_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_suggestions_missions_pour_soignant"("p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_soignant record;
  v_result jsonb;
  v_limit integer;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  v_limit := least(greatest(COALESCE(p_limit, 5), 1), 10);
  SELECT * INTO v_soignant FROM public.soignants WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profil soignant introuvable'); END IF;

  WITH candidates AS (
    SELECT m.id, m.intitule, m.profession_requise, m.specialite_medicale_requise,
      m.type_contrat_recherche, m.taux_horaire_base, m.debut_le, m.fin_le,
      m.est_urgente, m.cree_le, m.etablissement_id,
      e.nom AS etab_nom, e.adresse_ville AS etab_ville,
      e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng,
      (SELECT round(avg(note)::numeric, 2) FROM public.evaluations ev
       JOIN public.missions m2 ON m2.id = ev.mission_id
       WHERE m2.etablissement_id = m.etablissement_id AND ev.note IS NOT NULL) AS etab_note_moyenne,
      CASE WHEN e.adresse_lat IS NOT NULL AND v_soignant.adresse_lat IS NOT NULL THEN
        round((6371 * 2 * asin(sqrt(
          power(sin(radians(v_soignant.adresse_lat - e.adresse_lat) / 2), 2) +
          cos(radians(e.adresse_lat)) * cos(radians(v_soignant.adresse_lat)) *
          power(sin(radians(v_soignant.adresse_lng - e.adresse_lng) / 2), 2)
        )))::numeric, 1)
      ELSE NULL END AS distance_km
    FROM public.missions m
    LEFT JOIN public.etablissements e ON e.id = m.etablissement_id
    WHERE m.statut = 'OUVERTE'
      AND m.debut_le > now()
      AND public.fn_soignant_eligible_mission(v_uid, m.id, false)
      AND NOT public.fn_est_exclu(v_uid, m.etablissement_id)
      AND NOT EXISTS (
        SELECT 1 FROM public.candidatures c
         WHERE c.mission_id = m.id AND c.soignant_id = v_uid
      )
      AND (
        v_soignant.rayon_deplacement_km IS NULL OR e.adresse_lat IS NULL
        OR v_soignant.adresse_lat IS NULL OR
        (6371 * 2 * asin(sqrt(
          power(sin(radians(v_soignant.adresse_lat - e.adresse_lat) / 2), 2) +
          cos(radians(e.adresse_lat)) * cos(radians(v_soignant.adresse_lat)) *
          power(sin(radians(v_soignant.adresse_lng - e.adresse_lng) / 2), 2)
        ))) <= v_soignant.rayon_deplacement_km
      )
      AND COALESCE(m.taux_horaire_base, 0) >= COALESCE(v_soignant.taux_horaire_minimum, 0)
  ), ranked AS (
    SELECT *, row_number() OVER (
      ORDER BY est_urgente DESC, distance_km ASC NULLS LAST,
               etab_note_moyenne DESC NULLS LAST, cree_le DESC
    ) AS rn
    FROM candidates
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id, 'intitule', r.intitule,
    'profession_requise', r.profession_requise::text,
    'specialite_medicale_requise', r.specialite_medicale_requise,
    'type_contrat_recherche', r.type_contrat_recherche,
    'taux_horaire_base', r.taux_horaire_base,
    'debut_le', r.debut_le, 'fin_le', r.fin_le,
    'est_urgente', r.est_urgente, 'etablissement_id', r.etablissement_id,
    'etab_nom', r.etab_nom, 'etab_ville', r.etab_ville,
    'etab_note_moyenne', r.etab_note_moyenne, 'distance_km', r.distance_km
  ) ORDER BY r.rn), '[]'::jsonb)
    INTO v_result
    FROM (SELECT * FROM ranked WHERE rn <= v_limit) r;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_suggestions_missions_pour_soignant"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_suis_soignant_reel"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
