CREATE OR REPLACE FUNCTION "public"."fn_supprimer_api_key"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean := public.est_admin();
  v_target public.api_keys%ROWTYPE;
BEGIN
  SELECT * INTO v_target FROM public.api_keys WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Cle introuvable'); END IF;
  IF NOT v_is_admin AND (
    v_target.etablissement_id IS DISTINCT FROM public.mon_etablissement_id()
    OR NOT public.fn_a_permission_etablissement('api', v_target.etablissement_id)
  ) THEN RETURN jsonb_build_object('error', 'Acces refuse'); END IF;

  DELETE FROM public.api_keys WHERE id = p_id;
  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_actor,
    p_type_acteur := CASE WHEN v_is_admin THEN 'ADMIN_PLATEFORME' ELSE 'ADMIN_ETABLISSEMENT' END,
    p_action := 'API_KEY_SUPPRIMEE', p_type_ressource := 'api_key', p_id_ressource := p_id,
    p_details := jsonb_build_object('id', p_id, 'nom', v_target.nom)
  );
  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."fn_supprimer_api_key"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_supprimer_compte_etablissement_rate_limited"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_allowed boolean;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;

  v_allowed := public.fn_verifier_rate_limit(v_uid::text, 'supprimer_compte_etablissement', 1, 86400);
  IF NOT v_allowed THEN
    RETURN jsonb_build_object('error', 'Demande de suppression déjà en cours.');
  END IF;

  RETURN public.fn_supprimer_mon_compte_etablissement();
END;
$$;


ALTER FUNCTION "public"."fn_supprimer_compte_etablissement_rate_limited"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_supprimer_compte_rate_limited"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_allowed BOOLEAN;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Non authentifié');
    END IF;
    
    v_allowed := fn_verifier_rate_limit(v_user_id::TEXT, 'supprimer_compte', 1, 86400);
    IF NOT v_allowed THEN
        RETURN jsonb_build_object('error', 'Demande de suppression déjà en cours.');
    END IF;
    
    RETURN fn_supprimer_mon_compte();
END;
$$;


ALTER FUNCTION "public"."fn_supprimer_compte_rate_limited"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_supprimer_filtre_sauvegarde"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_old RECORD;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error','Non authentifié'); END IF;

  SELECT * INTO v_old FROM filtres_sauvegardes WHERE id = p_id AND utilisateur_id = v_uid;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','Filtre introuvable'); END IF;

  DELETE FROM filtres_sauvegardes WHERE id = p_id;

  PERFORM fn_ecrire_audit_safe(
    p_acteur_id := v_uid, p_type_acteur := 'SOIGNANT',
    p_action := 'FILTRE_SUPPRIME', p_type_ressource := 'filtre_sauvegarde',
    p_id_ressource := p_id,
    p_details := jsonb_build_object('nom', v_old.nom, 'audience', v_old.audience::text)
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_supprimer_filtre_sauvegarde"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_supprimer_mes_tokens_push"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_count int;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Non authentifié'); END IF;
  DELETE FROM public.tokens_push WHERE utilisateur_id = v_uid;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('success', true, 'tokens_supprimes', v_count);
END;
$$;


