CREATE OR REPLACE FUNCTION "public"."fn_supprimer_mon_compte"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
    v_missions_futures INTEGER;
    v_hash TEXT;
    v_uid UUID := auth.uid();
BEGIN
    SELECT COUNT(*) INTO v_missions_futures FROM missions
    WHERE soignant_assigne_id = v_uid AND statut IN ('ASSIGNEE','EN_COURS') AND fin_le > NOW();
    IF v_missions_futures > 0 THEN
        RETURN jsonb_build_object('error', 'Vous avez ' || v_missions_futures || ' mission(s) en cours.');
    END IF;
    v_hash := encode(digest(v_uid::TEXT || NOW()::TEXT, 'sha256'), 'hex');
    UPDATE soignants SET
        prenom = 'Soignant', nom = 'Supprimé',
        email = v_hash || '@supprime.jolene.app',
        telephone = NULL, adresse_rue = NULL, adresse_ville = NULL,
        adresse_code_postal = NULL, numero_secu = NULL,
        numero_securite_sociale = NULL,
        lieu_naissance_commune = NULL, lieu_naissance_departement = NULL,
        pays_naissance = NULL, nationalite = NULL, sexe = NULL,
        date_naissance = NULL, siret_liberal = NULL,
        numero_tva = NULL, bio = NULL, specialites = NULL,
        avatar_url = NULL, adresse_lat = NULL, adresse_lng = NULL,
        numero_rpps = NULL, numero_adeli = NULL,
        iban_last4 = NULL, stripe_account_id = NULL,
        psc_sub = NULL, psc_linked_le = NULL, psc_last_login = NULL,
        mandat_facturation_signe = FALSE, mandat_facturation_signe_le = NULL,
        sms_actif = FALSE, sms_consent_le = NULL,
        supprime_le = NOW()
    WHERE id = v_uid;
    UPDATE evaluations SET commentaire = NULL WHERE evaluateur_id = v_uid OR evalue_id = v_uid;
    DELETE FROM tokens_push WHERE utilisateur_id = v_uid;
    DELETE FROM tokens_calendrier WHERE soignant_id = v_uid;
    UPDATE messages_mission SET contenu = '[Message supprimé]' WHERE auteur_id = v_uid;
    UPDATE messages_chat SET contenu = '[Message supprimé]' WHERE auteur_id = v_uid;
    DELETE FROM attestations_heures_externes WHERE soignant_id = v_uid;
    DELETE FROM favoris_soignant_etab WHERE soignant_id = v_uid;
    DELETE FROM reclamations_scoring WHERE soignant_id = v_uid;
    DELETE FROM notifications WHERE destinataire_id = v_uid;
    UPDATE parrainages SET parrain_id = NULL WHERE parrain_id = v_uid;
    UPDATE parrainages SET filleul_id = NULL WHERE filleul_id = v_uid;
    UPDATE presences SET
        arrivee_lat = NULL, arrivee_lng = NULL, depart_lat = NULL, depart_lng = NULL,
        arrivee_precision_gps_m = NULL, depart_precision_gps_m = NULL,
        arrivee_id_terminal = NULL, depart_id_terminal = NULL,
        arrivee_modele_terminal = NULL, depart_modele_terminal = NULL
    WHERE soignant_id = v_uid;
    DELETE FROM pings_gps_mission WHERE soignant_id = v_uid;
    DELETE FROM consentements_ping_gps WHERE soignant_id = v_uid;
    UPDATE scans_pointage SET
        latitude = NULL, longitude = NULL, precision_gps_m = NULL,
        id_terminal = NULL, ip_address = NULL, distance_etablissement_m = NULL
    WHERE soignant_id = v_uid;
    UPDATE documents_soignants SET supprime_le = NOW() WHERE soignant_id = v_uid;
    UPDATE partages_rib SET actif = FALSE WHERE soignant_id = v_uid;
    UPDATE stripe_connect_onboarding SET
        stripe_account_id = 'SUPPRIME_' || LEFT(v_hash, 20), iban_last4 = NULL, erreur_onboarding = NULL
    WHERE soignant_id = v_uid;
    UPDATE candidatures SET message = NULL WHERE soignant_id = v_uid;
    UPDATE contrats_mission SET
        signature_ip_soignant = NULL, signature_navigateur_soignant = NULL, signature_image_soignant = NULL
    WHERE soignant_id = v_uid;
    DELETE FROM conversions_liberal WHERE soignant_id = v_uid;
    DELETE FROM heures_externes WHERE soignant_id = v_uid;
    DELETE FROM pauses_presence WHERE soignant_id = v_uid;
    DELETE FROM souscriptions_prevoyance WHERE soignant_id = v_uid;
    DELETE FROM suivi_conversion_3200h WHERE soignant_id = v_uid;
    DELETE FROM mandats_facturation_signatures WHERE soignant_id = v_uid;
    DELETE FROM cessions_creance WHERE soignant_id = v_uid;
    UPDATE factures_honoraires SET soignant_id = v_uid WHERE soignant_id = v_uid;
    DELETE FROM factor_advances WHERE soignant_id = v_uid;
    DELETE FROM psc_auth_sessions WHERE cree_le < NOW();
    DELETE FROM email_queue WHERE destinataire_id = v_uid;
    UPDATE sms_envoyes SET telephone = 'SUPPRIME', destinataire_id = NULL WHERE destinataire_id = v_uid;
    DELETE FROM cotisations_sociales WHERE soignant_id = v_uid;
    DELETE FROM conformite_travail WHERE soignant_id = v_uid;
    UPDATE messages_litige SET contenu = '[Message supprimé]' WHERE auteur_id = v_uid;
    UPDATE stripe_transfers SET soignant_id = NULL WHERE soignant_id = v_uid;
    UPDATE paiements_soignant SET soignant_id = NULL WHERE soignant_id = v_uid;
    INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES (v_uid, 'SOIGNANT', 'RGPD_SUPPRESSION_COMPTE', 'soignant', v_uid,
        jsonb_build_object('anonymise', true, 'tables_nettoyees', ARRAY[
            'soignants','evaluations','tokens_push','tokens_calendrier','messages_mission','messages_chat',
            'attestations_heures_externes','favoris','reclamations_scoring','parrainages','notifications',
            'presences','pings_gps_mission','consentements_ping_gps','scans_pointage',
            'documents_soignants','partages_rib','stripe_connect_onboarding','candidatures',
            'contrats_mission','conversions_liberal','heures_externes','pauses_presence',
            'souscriptions_prevoyance','suivi_conversion_3200h',
            'mandats_facturation_signatures','cessions_creance','factures_honoraires','factor_advances',
            'email_queue','sms_envoyes','cotisations_sociales','conformite_travail',
            'messages_litige','stripe_transfers','paiements_soignant']));
    RETURN jsonb_build_object('success', true, 'message', 'Votre compte a été supprimé et vos données anonymisées.');
END;
$$;


ALTER FUNCTION "public"."fn_supprimer_mon_compte"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_supprimer_mon_compte_etablissement"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_etab_id uuid;
  v_missions_actives int;
  v_factures_impayees int;
  v_hash text;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;

  SELECT id INTO v_etab_id FROM etablissements WHERE id = v_uid;
  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Aucun établissement lié à ce compte');
  END IF;

  -- Garde-fou : missions actives
  SELECT count(*) INTO v_missions_actives FROM missions
   WHERE etablissement_id = v_etab_id
     AND statut IN ('OUVERTE','ASSIGNEE','EN_COURS','LITIGE')
     AND fin_le > NOW();
  IF v_missions_actives > 0 THEN
    RETURN jsonb_build_object('success', false, 'error',
      format('Vous avez %s mission(s) ouverte(s) ou en cours.', v_missions_actives));
  END IF;

  -- Garde-fou : factures impayées (la suppression n'efface pas une dette)
  SELECT count(*) INTO v_factures_impayees FROM factures
   WHERE etablissement_id = v_etab_id AND statut IN ('EN_ATTENTE','EN_RETARD');
  IF v_factures_impayees > 0 THEN
    RETURN jsonb_build_object('success', false, 'error',
      format('%s facture(s) impayée(s). Réglez-les avant suppression.', v_factures_impayees));
  END IF;

  -- Bypass trigger fn_protect_etablissement_commercial pour anonymisation
  PERFORM set_config('app.internal_operation', 'true', true);
  v_hash := encode(extensions.digest(v_etab_id::text || NOW()::text, 'sha256'), 'hex');

  -- Anonymisation établissement
  UPDATE etablissements SET
    nom = 'Établissement supprimé',
    siret = '99' || LPAD(LEFT(REGEXP_REPLACE(v_hash, '[^0-9]', '', 'g'), 12), 12, '0'),
    finess = NULL,
    email_contact = v_hash || '@supprime.jolene.app',
    telephone_contact = NULL,
    adresse_rue = '[SUPPRIMÉ]',
    adresse_ville = '[SUPPRIMÉ]',
    adresse_code_postal = '00000',
    adresse_departement = NULL, adresse_lat = NULL, adresse_lng = NULL,
    description = NULL, logo_url = NULL, horaires_ouverture = NULL,
    contrat_url = NULL,
    siret_raison_sociale = NULL, siret_categorie_juridique = NULL,
    siret_code_naf = NULL, siret_est_actif = false,
    chorus_pro_actif = false, chorus_pro_identifiant = NULL,
    sms_actif = false, sms_consent_le = NULL,
    peut_publier_missions = false,
    bloque_auto_le = NOW(),
    bloque_auto_raisons = jsonb_build_array('COMPTE_SUPPRIME_RGPD'),
    supprime_le = NOW(),
    stripe_sepa_payment_method_id = NULL
  WHERE id = v_etab_id;

  -- Tables liées
  DELETE FROM admins_groupe_sante WHERE utilisateur_id = v_uid;
  DELETE FROM tokens_push WHERE utilisateur_id = v_uid;
  DELETE FROM notifications WHERE destinataire_id = v_uid;

  UPDATE messages_chat SET contenu = '[Message supprimé]' WHERE auteur_id = v_uid;
  UPDATE messages_mission SET contenu = '[Message supprimé]' WHERE auteur_id = v_uid;
  UPDATE messages_litige SET contenu = '[Message supprimé]' WHERE auteur_id = v_uid;

  UPDATE evaluations SET commentaire = NULL
   WHERE evaluateur_id = v_uid OR evalue_id = v_uid;

  DELETE FROM exclusions WHERE exclu_par = v_uid OR exclu_id = v_uid;

  UPDATE partages_rib SET actif = false, expire_le = NOW()
   WHERE etablissement_id = v_etab_id;

  -- Contrats : on conserve (preuves légales) mais anonymise IP/UA
  UPDATE contrats_mission SET
    signature_ip_etablissement = NULL,
    signature_navigateur_etablissement = NULL,
    signature_image_etablissement = NULL
   WHERE etablissement_id = v_etab_id;

  DELETE FROM email_queue WHERE destinataire_id = v_uid;
  UPDATE sms_envoyes SET telephone = 'SUPPRIME', destinataire_id = NULL
   WHERE destinataire_id = v_uid;

  DELETE FROM calendar_events_sync WHERE connection_id IN
    (SELECT id FROM calendar_connections WHERE utilisateur_id = v_uid);
  DELETE FROM calendar_connections WHERE utilisateur_id = v_uid;
  DELETE FROM api_keys WHERE etablissement_id = v_etab_id;

  -- Audit (type_acteur ADMIN_ETABLISSEMENT, action RGPD_SUPPRESSION_COMPTE_ETABLISSEMENT)
  INSERT INTO journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
  VALUES (v_uid, 'ADMIN_ETABLISSEMENT', 'RGPD_SUPPRESSION_COMPTE_ETABLISSEMENT', 'etablissement', v_etab_id,
    jsonb_build_object('anonymise', true));

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Établissement anonymisé. Factures conservées 10 ans (LPF L102 B).',
    'etablissement_id', v_etab_id
  );
END;
$$;


ALTER FUNCTION "public"."fn_supprimer_mon_compte_etablissement"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_supprimer_mon_compte_etablissement"() IS 'Suppression compte établissement (RGPD art. 17) avec anonymisation. Bloque si missions actives ou factures impayées. Conserve factures + audit (LPF 10 ans).';



CREATE OR REPLACE FUNCTION "public"."fn_swan_webhook_finaliser"("p_event_id" "text", "p_statut" "text", "p_transaction_snapshot" "jsonb" DEFAULT NULL::"jsonb", "p_error_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_snapshot_keys text[];
BEGIN
  IF p_statut NOT IN ('TRAITE', 'IGNORE', 'ERREUR') THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'STATUT_INVALIDE');
  END IF;
  IF p_transaction_snapshot IS NOT NULL THEN
    IF jsonb_typeof(p_transaction_snapshot) <> 'object' THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'SNAPSHOT_INVALIDE');
    END IF;
    SELECT array_agg(key ORDER BY key) INTO v_snapshot_keys
    FROM jsonb_object_keys(p_transaction_snapshot) AS key;
    IF NOT COALESCE(
      v_snapshot_keys <@ ARRAY[
        'account_id_matches', 'amount_cents', 'currency', 'event_status_matches',
        'id', 'status', 'type'
      ]::text[],
      true
    ) THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'SNAPSHOT_CHAMP_INTERDIT');
    END IF;
  END IF;

  UPDATE public.swan_webhook_events
  SET statut = p_statut,
      transaction_snapshot = p_transaction_snapshot,
      derniere_erreur = CASE
        WHEN p_statut = 'ERREUR' THEN left(COALESCE(NULLIF(btrim(p_error_code), ''), 'ERREUR_INCONNUE'), 200)
        ELSE NULL
      END,
      traite_le = CASE WHEN p_statut IN ('TRAITE', 'IGNORE') THEN now() ELSE NULL END
  WHERE event_id = p_event_id
    AND statut = 'PROCESSING';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CLAIM_ABSENT');
  END IF;
  RETURN jsonb_build_object('success', true, 'statut', p_statut);
END;
$$;


ALTER FUNCTION "public"."fn_swan_webhook_finaliser"("p_event_id" "text", "p_statut" "text", "p_transaction_snapshot" "jsonb", "p_error_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_swan_webhook_reclamer"("p_event_id" "text", "p_event_type" "text", "p_resource_id" "text", "p_project_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_event public.swan_webhook_events%ROWTYPE;
BEGIN
  IF p_event_id IS NULL OR p_resource_id IS NULL OR p_project_id IS NULL
     OR p_event_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'
     OR p_resource_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'
     OR p_project_id !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'
     OR NULLIF(btrim(p_event_type), '') IS NULL OR length(p_event_type) > 100 THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'ENVELOPPE_INVALIDE');
  END IF;

  INSERT INTO public.swan_webhook_events (
    event_id, event_type, resource_id, project_id
  ) VALUES (
    p_event_id, btrim(p_event_type), p_resource_id, p_project_id
  ) ON CONFLICT (event_id) DO NOTHING;

  SELECT * INTO v_event
  FROM public.swan_webhook_events
  WHERE event_id = p_event_id
  FOR UPDATE;

  -- Un eventId ne peut jamais être réutilisé avec une autre enveloppe.
  IF v_event.event_type IS DISTINCT FROM btrim(p_event_type)
     OR v_event.resource_id IS DISTINCT FROM p_resource_id
     OR v_event.project_id IS DISTINCT FROM p_project_id THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'EVENT_ID_REUTILISE');
  END IF;

  IF v_event.statut IN ('TRAITE', 'IGNORE') THEN
    RETURN jsonb_build_object('success', true, 'claim', 'DEJA_TRAITE', 'statut', v_event.statut);
  END IF;

  IF v_event.statut = 'PROCESSING'
     AND v_event.traitement_commence_le > now() - interval '2 minutes' THEN
    RETURN jsonb_build_object('success', true, 'claim', 'EN_COURS');
  END IF;

  UPDATE public.swan_webhook_events
  SET statut = 'PROCESSING',
      tentatives = tentatives + 1,
      traitement_commence_le = now(),
      derniere_erreur = NULL
  WHERE event_id = p_event_id;

  RETURN jsonb_build_object('success', true, 'claim', 'ACQUIS');
END;
$_$;


ALTER FUNCTION "public"."fn_swan_webhook_reclamer"("p_event_id" "text", "p_event_type" "text", "p_resource_id" "text", "p_project_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_sync_mission_creneaux"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission_id uuid; v_old_mission_id uuid; v_debut timestamptz; v_fin timestamptz;
  v_duree numeric; v_nb integer; v_debut_eff timestamptz; v_fin_eff timestamptz;
  v_duree_eff numeric; v_duree_phase2 numeric;
BEGIN
  IF current_setting('jolene.sync_in_progress', true) = 'true' THEN RETURN NULL; END IF;
  IF TG_OP = 'DELETE' THEN v_mission_id := OLD.mission_id; v_old_mission_id := NULL;
  ELSIF TG_OP = 'UPDATE' AND OLD.mission_id IS DISTINCT FROM NEW.mission_id THEN
    v_mission_id := NEW.mission_id; v_old_mission_id := OLD.mission_id;
  ELSE v_mission_id := NEW.mission_id; v_old_mission_id := NULL; END IF;

  SELECT MIN(debut), MAX(fin),
    COALESCE(SUM(CASE WHEN NOT est_pause THEN EXTRACT(EPOCH FROM (fin - debut)) / 3600.0 ELSE 0 END), 0), COUNT(*)
  INTO v_debut, v_fin, v_duree, v_nb
  FROM mission_creneaux WHERE mission_id = v_mission_id AND type_creneau = 'PREVISIONNEL';
  SELECT MIN(debut), MAX(fin),
    COALESCE(SUM(CASE WHEN NOT est_pause THEN EXTRACT(EPOCH FROM (fin - debut)) / 3600.0 ELSE 0 END), 0)
  INTO v_debut_eff, v_fin_eff, v_duree_eff
  FROM mission_creneaux WHERE mission_id = v_mission_id AND type_creneau = 'EFFECTIF' AND fin IS NOT NULL;
  IF v_duree_eff = 0 AND v_debut_eff IS NULL THEN v_duree_eff := NULL; END IF;
  v_duree_phase2 := GREATEST(COALESCE(v_duree_eff, 0), COALESCE(v_duree, 0));

  PERFORM set_config('jolene.sync_in_progress', 'true', true);
  IF v_nb > 0 THEN UPDATE missions SET debut_le = v_debut, fin_le = v_fin, nb_creneaux = v_nb WHERE id = v_mission_id;
  ELSE UPDATE missions SET nb_creneaux = 0 WHERE id = v_mission_id; END IF;
  PERFORM set_config('jolene.sync_in_progress', 'false', true);

  IF v_nb > 0 OR v_duree_eff IS NOT NULL THEN
    UPDATE missions SET duree_heures = ROUND(v_duree_phase2::numeric, 2),
      debut_effectif = v_debut_eff, fin_effective = v_fin_eff,
      duree_heures_effective = CASE WHEN v_duree_eff IS NOT NULL THEN ROUND(v_duree_eff::numeric, 2) ELSE NULL END
    WHERE id = v_mission_id;
  ELSE UPDATE missions SET duree_heures = NULL, debut_effectif = NULL, fin_effective = NULL, duree_heures_effective = NULL WHERE id = v_mission_id; END IF;

  IF v_old_mission_id IS NOT NULL THEN
    SELECT MIN(debut), MAX(fin),
      COALESCE(SUM(CASE WHEN NOT est_pause THEN EXTRACT(EPOCH FROM (fin - debut)) / 3600.0 ELSE 0 END), 0), COUNT(*)
    INTO v_debut, v_fin, v_duree, v_nb
    FROM mission_creneaux WHERE mission_id = v_old_mission_id AND type_creneau = 'PREVISIONNEL';
    SELECT MIN(debut), MAX(fin),
      COALESCE(SUM(CASE WHEN NOT est_pause THEN EXTRACT(EPOCH FROM (fin - debut)) / 3600.0 ELSE 0 END), 0)
    INTO v_debut_eff, v_fin_eff, v_duree_eff
    FROM mission_creneaux WHERE mission_id = v_old_mission_id AND type_creneau = 'EFFECTIF' AND fin IS NOT NULL;
    IF v_duree_eff = 0 AND v_debut_eff IS NULL THEN v_duree_eff := NULL; END IF;
    v_duree_phase2 := GREATEST(COALESCE(v_duree_eff, 0), COALESCE(v_duree, 0));
    PERFORM set_config('jolene.sync_in_progress', 'true', true);
    IF v_nb > 0 THEN UPDATE missions SET debut_le = v_debut, fin_le = v_fin, nb_creneaux = v_nb WHERE id = v_old_mission_id;
    ELSE UPDATE missions SET nb_creneaux = 0 WHERE id = v_old_mission_id; END IF;
    PERFORM set_config('jolene.sync_in_progress', 'false', true);
    IF v_nb > 0 OR v_duree_eff IS NOT NULL THEN
      UPDATE missions SET duree_heures = ROUND(v_duree_phase2::numeric, 2),
        debut_effectif = v_debut_eff, fin_effective = v_fin_eff,
        duree_heures_effective = CASE WHEN v_duree_eff IS NOT NULL THEN ROUND(v_duree_eff::numeric, 2) ELSE NULL END
      WHERE id = v_old_mission_id;
    ELSE UPDATE missions SET duree_heures = NULL, debut_effectif = NULL, fin_effective = NULL, duree_heures_effective = NULL WHERE id = v_old_mission_id; END IF;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_sync_mission_creneaux"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_terminer_mission"("p_mission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mission record;
  v_nb_presences integer;
BEGIN
  SELECT * INTO v_mission
  FROM public.missions WHERE id = p_mission_id;
  IF v_mission IS NULL THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;
  IF NOT public.est_admin()
     AND v_mission.etablissement_id <> public.mon_etablissement_id() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;
  IF v_mission.statut <> 'EN_COURS' THEN
    RETURN jsonb_build_object(
      'error', 'La mission doit être EN_COURS pour être terminée. Statut actuel : '
        || v_mission.statut
    );
  END IF;
  IF v_mission.est_arret_maladie IS TRUE THEN
    RETURN jsonb_build_object(
      'error_code', 'RECONCILIATION_HEURES_REQUISE',
      'error', 'Mission interrompue : validation admin des heures effectives requise avant clôture.'
    );
  END IF;
  SELECT count(*) INTO v_nb_presences
  FROM public.presences WHERE mission_id = p_mission_id;
  IF v_nb_presences = 0 AND NOT public.est_admin() THEN
    RETURN jsonb_build_object(
      'error', 'Impossible de terminer : aucune présence enregistrée. Le soignant doit pointer son arrivée et son départ.'
    );
  END IF;
  UPDATE public.missions
     SET statut = 'TERMINEE', terminee_le = now(), modifie_le = now()
   WHERE id = p_mission_id;
  IF v_mission.soignant_assigne_id IS NOT NULL THEN
    INSERT INTO public.notifications (
      destinataire_id, type, titre, corps, lien, type_destinataire
    ) VALUES (
      v_mission.soignant_assigne_id, 'SYSTEM', 'Mission terminée ✅',
      'La mission "' || v_mission.intitule
        || '" est terminée. Consultez vos gains.',
      '/soignant/mes-gains', 'SOIGNANT'
    );
  END IF;
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_terminer_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_test_purge_mission"("p_mission_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r RECORD;
  v_intitule text;
BEGIN
  SELECT intitule INTO v_intitule FROM missions WHERE id = p_mission_id;
  IF v_intitule IS NULL THEN RETURN; END IF;
  -- Garde-fou : réservé STRICTEMENT aux missions de test (jamais de données réelles).
  IF v_intitule NOT LIKE '[pw-test%' AND v_intitule NOT LIKE '[playwright-test]%' THEN
    RAISE EXCEPTION 'fn_test_purge_mission reserve aux missions de test (intitule=%)', v_intitule;
  END IF;

  -- messages_chat : enfant de conversations (FK conversation_id, pas mission_id).
  DELETE FROM messages_chat WHERE conversation_id IN (SELECT id FROM conversations WHERE mission_id = p_mission_id);

  -- Toutes les tables ayant une FK directe vers missions.id (hors auto-référence missions).
  FOR r IN
    SELECT c.conrelid::regclass::text AS tbl, a.attname AS col
    FROM pg_constraint c
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
    WHERE c.contype = 'f' AND c.confrelid = 'public.missions'::regclass
      AND c.conrelid <> 'public.missions'::regclass
  LOOP
    EXECUTE format('DELETE FROM %s WHERE %I = $1', r.tbl, r.col) USING p_mission_id;
  END LOOP;

  DELETE FROM missions WHERE id = p_mission_id;
END;
$_$;


ALTER FUNCTION "public"."fn_test_purge_mission"("p_mission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_test_seed_heures_externes_validees"("p_soignant_id" "uuid", "p_heures" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions'
    AS $$
DECLARE
  v_soignant record;
  v_id uuid;
  v_previous_server_update text := COALESCE(
    current_setting('jolene.heures_externes_server_update', true), ''
  );
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Seed heures externes reserve au service_role'
      USING ERRCODE = '42501';
  END IF;
  IF p_heures IS NULL OR p_heures <= 0 OR p_heures > 10000
     OR p_heures <> trunc(p_heures) THEN
    RAISE EXCEPTION 'Les heures de fixture doivent etre un entier entre 1 et 10000'
      USING ERRCODE = '22023';
  END IF;

  SELECT s.id, s.email, s.est_compte_test, s.type_exercice
  INTO v_soignant
  FROM public.soignants s
  WHERE s.id = p_soignant_id
  FOR UPDATE;
  IF NOT FOUND
     OR COALESCE(v_soignant.est_compte_test, false) IS NOT TRUE
     OR lower(v_soignant.email) NOT LIKE 'playwright-test-caregiver-%@jolene.app'
     OR COALESCE(v_soignant.type_exercice, 'SALARIE') NOT IN ('LIBERAL', 'MIXTE') THEN
    RAISE EXCEPTION 'Seed refuse : profil Playwright liberal ephemere requis'
      USING ERRCODE = '42501';
  END IF;

  SELECT h.id
  INTO v_id
  FROM public.heures_externes_soignants h
  WHERE h.soignant_id = p_soignant_id
    AND h.source_validation_serveur = 'TEST_FIXTURE_SERVICE_ROLE'
    AND h.statut_validation = 'VALIDE'
    AND h.heures_declarees = p_heures::integer
    AND h.empreinte_snapshot_source =
        private.fn_empreinte_snapshot_heures_externes(h)
  LIMIT 1;
  IF FOUND THEN
    PERFORM private.fn_resynchroniser_compteurs_soignant(p_soignant_id);
    RETURN v_id;
  END IF;

  -- Les lignes de fixtures sont liees au profil ephemere (ON DELETE CASCADE).
  -- Remplacer une ancienne valeur technique ne touche donc jamais les donnees
  -- de demo ni une preuve reelle.
  DELETE FROM public.heures_externes_soignants h
  WHERE h.soignant_id = p_soignant_id
    AND h.source_validation_serveur = 'TEST_FIXTURE_SERVICE_ROLE';

  PERFORM set_config(
    'jolene.heures_externes_server_update', 'true', true
  );
  INSERT INTO public.heures_externes_soignants (
    soignant_id,
    etablissement_nom,
    etablissement_type,
    date_debut,
    date_fin,
    heures_declarees,
    attestation_url,
    attestation_nom_fichier,
    statut_validation,
    source_validation_serveur
  ) VALUES (
    p_soignant_id,
    'Fixture Playwright ephemere',
    'HOPITAL_PUBLIC',
    date '2018-01-01',
    date '2021-12-31',
    p_heures::integer,
    p_soignant_id::text || '/heures-externes/fixture-playwright.pdf',
    'fixture-playwright.pdf',
    'EN_ATTENTE',
    'TEST_FIXTURE_SERVICE_ROLE'
  )
  RETURNING id INTO v_id;

  UPDATE public.heures_externes_soignants h
  SET statut_validation = 'VALIDE',
      valide_le = now(),
      commentaire_validation = 'Fixture E2E service_role ephemere',
      empreinte_preuve_sha256 = encode(
        extensions.digest(
          convert_to('playwright:' || p_soignant_id::text, 'UTF8'),
          'sha256'
        ),
        'hex'
      ),
      empreinte_snapshot_source =
        private.fn_empreinte_snapshot_heures_externes(h),
      mis_a_jour_le = now()
  WHERE h.id = v_id;

  PERFORM set_config(
    'jolene.heures_externes_server_update', v_previous_server_update, true
  );
  PERFORM private.fn_resynchroniser_compteurs_soignant(p_soignant_id);
  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'jolene.heures_externes_server_update', v_previous_server_update, true
  );
  RAISE;
END;
$$;


ALTER FUNCTION "public"."fn_test_seed_heures_externes_validees"("p_soignant_id" "uuid", "p_heures" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_test_seed_mission"("p_data" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_id uuid;
  v_cols text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'fn_test_seed_mission réservé au service_role (seed E2E uniquement)';
  END IF;
  PERFORM set_config('app.internal_operation', 'true', true);
  PERFORM set_config('jolene.creer_mission_context', 'true', true);
  v_cols := (SELECT string_agg(quote_ident(key), ',') FROM jsonb_object_keys(p_data) AS key);
  EXECUTE format(
    'INSERT INTO public.missions (%s) SELECT %s FROM jsonb_populate_record(NULL::public.missions, $1) RETURNING id',
    v_cols, v_cols
  ) USING p_data INTO v_id;
  RETURN v_id;
END;
$_$;


ALTER FUNCTION "public"."fn_test_seed_mission"("p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_test_update_mission"("p_mission_id" "uuid", "p_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_set text;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'fn_test_update_mission réservé au service_role (seed E2E uniquement)';
  END IF;
  PERFORM set_config('app.internal_operation', 'true', true);
  PERFORM set_config('jolene.creer_mission_context', 'true', true);
  PERFORM set_config('app.test_bypass_protections', 'true', true);
  v_set := (SELECT string_agg(format('%I = r.%I', key, key), ',') FROM jsonb_object_keys(p_data) AS key);
  EXECUTE format(
    'UPDATE public.missions m SET %s FROM jsonb_populate_record(NULL::public.missions, $1) r WHERE m.id = $2',
    v_set
  ) USING p_data, p_mission_id;
  PERFORM set_config('app.test_bypass_protections', '', true);
END;
$_$;


ALTER FUNCTION "public"."fn_test_update_mission"("p_mission_id" "uuid", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_toggle_favori_etablissement"("p_etablissement_id" "uuid", "p_actif" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_etab_existe BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  SELECT EXISTS (SELECT 1 FROM etablissements WHERE id = p_etablissement_id) INTO v_etab_existe;
  IF NOT v_etab_existe THEN
    RETURN jsonb_build_object('success', false, 'error', 'Établissement introuvable');
  END IF;

  IF p_actif THEN
    INSERT INTO favoris_soignant_etab (soignant_id, etablissement_id)
    VALUES (v_uid, p_etablissement_id)
    ON CONFLICT (soignant_id, etablissement_id) DO NOTHING;
    PERFORM public.fn_ecrire_audit_safe(v_uid, 'SOIGNANT', 'FAVORI_AJOUTE', 'etablissement', p_etablissement_id, NULL, jsonb_build_object('sens', 'soignant_etab'));
  ELSE
    DELETE FROM favoris_soignant_etab
    WHERE soignant_id = v_uid AND etablissement_id = p_etablissement_id;
    PERFORM public.fn_ecrire_audit_safe(v_uid, 'SOIGNANT', 'FAVORI_RETIRE', 'etablissement', p_etablissement_id, NULL, jsonb_build_object('sens', 'soignant_etab'));
  END IF;

  RETURN jsonb_build_object('success', true, 'actif', p_actif);
END;
$$;


ALTER FUNCTION "public"."fn_toggle_favori_etablissement"("p_etablissement_id" "uuid", "p_actif" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_toggle_pool_urgence"("p_actif" boolean, "p_rayon_km" integer DEFAULT 15, "p_creneaux" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_soignant record;
  v_salarie_ok boolean;
  v_liberal_ok boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('error', 'Non authentifié'); END IF;
  SELECT id, COALESCE(type_exercice, 'SALARIE') AS type_exercice INTO v_soignant
    FROM public.soignants WHERE id = v_uid AND supprime_le IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Profil soignant introuvable'); END IF;
  IF p_rayon_km IS NULL OR p_rayon_km < 1 OR p_rayon_km > 200 THEN
    RETURN jsonb_build_object('error', 'Le rayon doit être compris entre 1 et 200 km.');
  END IF;

  IF p_actif THEN
    v_salarie_ok := public.fn_documents_ok_pour_mission(v_uid, 'SALARIE');
    v_liberal_ok := v_soignant.type_exercice IN ('LIBERAL', 'MIXTE')
      AND public.fn_documents_ok_pour_mission(v_uid, 'LIBERAL');
    IF NOT v_salarie_ok AND NOT v_liberal_ok THEN
      RETURN jsonb_build_object(
        'error', 'Validez les documents d’au moins un type de mission (salariée ou libérale) pour rejoindre le pool urgence.',
        'documents_salarie_ok', false,
        'documents_liberal_ok', false
      );
    END IF;
  END IF;

  UPDATE public.soignants
     SET disponible_urgence = COALESCE(p_actif, false),
         urgence_rayon_km = p_rayon_km,
         urgence_creneaux = p_creneaux,
         modifie_le = now()
   WHERE id = v_uid;

  RETURN jsonb_build_object(
    'success', true,
    'disponible_urgence', COALESCE(p_actif, false),
    'documents_salarie_ok', COALESCE(v_salarie_ok, false),
    'documents_liberal_ok', COALESCE(v_liberal_ok, false)
  );
END;
$$;


ALTER FUNCTION "public"."fn_toggle_pool_urgence"("p_actif" boolean, "p_rayon_km" integer, "p_creneaux" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_toggle_pool_urgence_sms"("p_actif" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non authentifié');
  END IF;

  UPDATE soignants
  SET pool_urgence_sms_opt_in = COALESCE(p_actif, false)
  WHERE id = v_uid AND supprime_le IS NULL;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Profil soignant introuvable');
  END IF;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := 'SOIGNANT',
    p_action := 'POOL_URGENCE_SMS_TOGGLE',
    p_type_ressource := 'soignant',
    p_id_ressource := v_uid,
    p_details := jsonb_build_object('actif', p_actif)
  );

  RETURN jsonb_build_object('success', true, 'pool_urgence_sms_opt_in', COALESCE(p_actif, false));
END;
$$;


ALTER FUNCTION "public"."fn_toggle_pool_urgence_sms"("p_actif" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_top_etablissements_soignant"("p_limit" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_result JSONB;
  v_limit INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('error', 'Non authentifié');
  END IF;
  v_limit := LEAST(GREATEST(COALESCE(p_limit, 3), 1), 10);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'etablissement_id', etablissement_id,
    'nom', nom,
    'ville', ville,
    'logo_url', logo_url,
    'nb_missions', nb_missions,
    'derniere_mission_le', derniere_mission_le
  ) ORDER BY nb_missions DESC, derniere_mission_le DESC NULLS LAST), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      m.etablissement_id,
      e.nom,
      e.adresse_ville AS ville,
      e.logo_url,
      count(*) AS nb_missions,
      max(m.fin_le) AS derniere_mission_le
    FROM missions m
    JOIN etablissements e ON e.id = m.etablissement_id
    WHERE m.soignant_assigne_id = v_uid AND m.statut = 'TERMINEE'
    GROUP BY m.etablissement_id, e.nom, e.adresse_ville, e.logo_url
    ORDER BY count(*) DESC, max(m.fin_le) DESC NULLS LAST
    LIMIT v_limit
  ) t;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_top_etablissements_soignant"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_top_soignants"("p_profession" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "prenom" "text", "nom" "text", "profession" "text", "note_moyenne" numeric, "nb_evaluations" integer, "score_fiabilite" integer, "total_missions_terminees" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN QUERY
    SELECT s.id, s.prenom, s.nom, s.profession::TEXT, s.note_moyenne, s.nb_evaluations,
           ROUND(COALESCE(s.score_fiabilite, 0))::integer AS score_fiabilite,
           s.total_missions_terminees
    FROM soignants s
    WHERE s.supprime_le IS NULL
    AND s.est_compte_test = false
    AND fn_documents_ok_pour_mission(s.id, 'TOUS')
    AND (p_profession IS NULL OR s.profession::TEXT = p_profession)
    ORDER BY s.note_moyenne DESC NULLS LAST, s.score_fiabilite DESC, s.total_missions_terminees DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."fn_top_soignants"("p_profession" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_traiter_candidature"("p_candidature_id" "uuid", "p_decision" "text", "p_motif" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_candidature public.candidatures%ROWTYPE;
  v_mission public.missions%ROWTYPE;
  v_mission_id uuid;
  v_result jsonb;
  v_notification jsonb;
BEGIN
  IF p_decision IS NULL
     OR p_decision NOT IN ('ACCEPTEE', 'REFUSEE') THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Décision invalide');
  END IF;

  -- Ordre global de verrouillage : mission avant candidature. Deux candidats
  -- traités simultanément pour la même mission ne peuvent ainsi pas former le
  -- cycle candidature A -> mission -> candidature B.
  SELECT c.mission_id INTO v_mission_id
  FROM public.candidatures c
  WHERE c.id = p_candidature_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Candidature introuvable');
  END IF;

  SELECT mi.* INTO v_mission
  FROM public.missions mi
  WHERE mi.id = v_mission_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Mission introuvable');
  END IF;

  SELECT c.* INTO v_candidature
  FROM public.candidatures c
  WHERE c.id = p_candidature_id
    AND c.mission_id = v_mission_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Candidature introuvable');
  END IF;
  IF public.fn_a_permission_etablissement(
       'candidatures',
       v_mission.etablissement_id
     ) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object('error', 'Non autorisé');
  END IF;
  IF v_candidature.statut::text NOT IN (
    'EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB'
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'error', 'Cette candidature a déjà été traitée.'
    );
  END IF;

  IF p_decision = 'REFUSEE' THEN
    UPDATE public.candidatures
    SET statut = 'REFUSEE', motif_refus = p_motif,
        traite_le = pg_catalog.now()
    WHERE id = p_candidature_id;

    INSERT INTO public.notifications (
      destinataire_id, type, titre, corps, lien, type_destinataire
    ) VALUES (
      v_candidature.soignant_id,
      'CANDIDATURE_REFUSEE',
      'Candidature non retenue',
      'Votre candidature pour « ' || v_mission.intitule ||
        ' » n''a pas été retenue.' ||
        CASE WHEN p_motif IS NOT NULL
          THEN ' Motif : ' || p_motif
          ELSE ''
        END,
      '/soignant/missions',
      'SOIGNANT'
    );
    RETURN pg_catalog.jsonb_build_object('success', true);
  END IF;

  v_result := public.fn_finaliser_attribution_mission(
    v_candidature.mission_id,
    v_candidature.soignant_id,
    v_candidature.type_contrat_choisi
  );
  IF COALESCE((v_result->>'success')::boolean, false) IS NOT TRUE THEN
    IF v_result->>'documents_requis_pour' IS NOT NULL THEN
      INSERT INTO public.notifications (
        destinataire_id, type, titre, corps, lien, type_destinataire
      )
      SELECT
        v_candidature.soignant_id,
        'RAPPEL_DOCUMENTS',
        'Un établissement veut accepter votre candidature',
        'Complétez les documents requis pour la mission ' ||
          pg_catalog.lower(v_result->>'documents_requis_pour') ||
          ' afin de finaliser votre contrat.',
        '/soignant/mes-documents',
        'SOIGNANT'
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.notifications n
        WHERE n.destinataire_id = v_candidature.soignant_id
          AND n.type = 'RAPPEL_DOCUMENTS'
          AND n.cree_le > pg_catalog.now() - interval '6 hours'
      );
    END IF;
    RETURN v_result;
  END IF;

  UPDATE public.candidatures
  SET statut = 'ACCEPTEE', traite_le = pg_catalog.now()
  WHERE id = p_candidature_id;
  UPDATE public.candidatures
  SET statut = 'REFUSEE',
      motif_refus = 'Un autre candidat a été sélectionné',
      traite_le = pg_catalog.now()
  WHERE mission_id = v_candidature.mission_id
    AND id <> p_candidature_id
    AND statut::text IN ('EN_ATTENTE', 'EN_ATTENTE_VALIDATION_ETAB');

  v_notification := public.fn_notifier_candidature_acceptee(
    v_candidature.mission_id,
    v_candidature.soignant_id,
    'Candidature acceptée',
    'Votre candidature pour « ' || v_mission.intitule ||
      ' » a été acceptée. Signez votre contrat.'
  );
  IF COALESCE((v_notification->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Notification d''acceptation impossible : %',
      COALESCE(v_notification->>'error', 'erreur inconnue');
  END IF;

  IF v_result->>'choix_applique' = 'LIBERAL'
     AND NOT COALESCE((
       SELECT s.mandat_facturation_signe
       FROM public.soignants s
       WHERE s.id = v_candidature.soignant_id
     ), false) THEN
    INSERT INTO public.notifications (
      destinataire_id, type, titre, corps, lien, type_destinataire
    ) VALUES (
      v_candidature.soignant_id,
      'CONTRAT_A_SIGNER',
      '✍️ Signez votre mandat de facturation',
      'Votre mission « ' || v_mission.intitule ||
        ' » est confirmée en libéral. Signez le mandat avant son démarrage.',
      '/soignant/mandat-facturation',
      'SOIGNANT'
    );
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."fn_traiter_candidature"("p_candidature_id" "uuid", "p_decision" "text", "p_motif" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_traiter_candidature"("p_candidature_id" "uuid", "p_decision" "text", "p_motif" "text") IS 'E16 — Lit candidature.type_contrat_choisi, RAISE E16_CANDIDATURE_ORPHELINE si MIXTE×TOUS sans choix, persiste 4 champs missions cohérents.';



CREATE OR REPLACE FUNCTION "public"."fn_traiter_reclamation"("p_reclamation_id" "uuid", "p_statut" "text", "p_points_restaures" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_recl RECORD;
BEGIN
    IF NOT est_admin() THEN RETURN '{"error":"Accès refusé"}'::JSONB; END IF;
    SELECT * INTO v_recl FROM reclamations_scoring WHERE id = p_reclamation_id;
    IF v_recl IS NULL THEN RETURN '{"error":"Réclamation introuvable"}'::JSONB; END IF;
    UPDATE reclamations_scoring SET statut = p_statut, points_restaures = p_points_restaures, traite_par = auth.uid(), traite_le = NOW() WHERE id = p_reclamation_id;
    IF p_statut = 'ACCEPTEE' AND p_points_restaures > 0 THEN
        UPDATE soignants SET score_fiabilite = LEAST(100, score_fiabilite + p_points_restaures), modifie_le = NOW() WHERE id = v_recl.soignant_id;
    END IF;
    RETURN '{"success":true}'::JSONB;
END;
$$;


ALTER FUNCTION "public"."fn_traiter_reclamation"("p_reclamation_id" "uuid", "p_statut" "text", "p_points_restaures" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_traiter_reclamation_generale"("p_reclamation_id" "uuid", "p_statut" "text", "p_reponse" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ DECLARE v_admin_id UUID := auth.uid(); BEGIN IF NOT est_admin() THEN RETURN jsonb_build_object('error', 'Accès réservé aux administrateurs'); END IF; UPDATE reclamations SET statut = p_statut, reponse_admin = COALESCE(p_reponse, reponse_admin), traite_par = v_admin_id, traite_le = now() WHERE id = p_reclamation_id; RETURN jsonb_build_object('ok', true); END; $$;


ALTER FUNCTION "public"."fn_traiter_reclamation_generale"("p_reclamation_id" "uuid", "p_statut" "text", "p_reponse" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_absence_event_score"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.absence_sans_prevenir IS TRUE
     AND COALESCE(OLD.absence_sans_prevenir, FALSE) IS DISTINCT FROM TRUE
     AND NEW.soignant_assigne_id IS NOT NULL THEN
    INSERT INTO evenements_score_soignant (soignant_id, type_evenement, points, motif, contestable, mission_id)
    SELECT NEW.soignant_assigne_id, 'NO_SHOW', -30,
           'Absence sans prévenir sur la mission "' || COALESCE(NEW.intitule, '') || '"',
           TRUE, NEW.id
    WHERE NOT EXISTS (
      SELECT 1 FROM evenements_score_soignant
      WHERE mission_id = NEW.id AND soignant_id = NEW.soignant_assigne_id AND type_evenement = 'NO_SHOW');
  END IF;
  RETURN NEW;
END;
$$;


