CREATE OR REPLACE FUNCTION "public"."fn_trg_escrow_creer_a_confirmation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab           etablissements%ROWTYPE;
  v_soignant_id    uuid;
  v_commission_c   integer;
  v_honoraires_c   integer;
  v_total_c        integer;
  v_premiere       boolean;
  v_marge_jours    integer;
  v_methode        text;
  v_debit_prevu    timestamptz;
BEGIN
  -- Garde flag : escrow éteint → no-op total (tout le trafic actuel).
  IF public.fn_param_num('feature_paiement_rapide_actif', 0) <> 1 THEN
    RETURN NEW;
  END IF;

  -- Escrow réservé au LIBERAL (le régime SALARIE ne passe jamais par Stripe).
  IF NEW.type_contrat_applique <> 'LIBERAL' THEN
    RETURN NEW;
  END IF;

  v_soignant_id := NEW.soignant_assigne_id;
  IF v_soignant_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Déjà un escrow pour cette mission (re-confirmation, idempotence).
  IF EXISTS (SELECT 1 FROM paiements_escrow WHERE mission_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_etab FROM etablissements WHERE id = NEW.etablissement_id;

  -- Mandat SEPA obligatoire : sans lui, pas d'escrow → régime standard (A4).
  IF v_etab.mode_paiement_commission <> 'SEPA_DEBIT'
     OR v_etab.stripe_sepa_payment_method_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_commission_c := ROUND(COALESCE(NEW.montant_commission_ttc, 0) * 100)::integer;
  v_honoraires_c := ROUND(COALESCE(NEW.net_a_payer, 0) * 100)::integer;
  v_total_c := v_commission_c + v_honoraires_c;

  IF v_honoraires_c <= 0 THEN
    RETURN NEW;
  END IF;

  -- Plafond A2 : l'exposition courante + ce montant doit rester sous le plafond,
  -- et l'établissement ne doit pas être gelé. Sinon → régime standard.
  IF NOT public.fn_escrow_etab_eligible(NEW.etablissement_id, v_honoraires_c) THEN
    RETURN NEW;
  END IF;

  -- 1re mission escrow de cet établissement (A2) → débit immédiat.
  v_premiere := NOT EXISTS (
    SELECT 1 FROM paiements_escrow WHERE etablissement_id = NEW.etablissement_id
  );

  v_marge_jours := public.fn_param_num('escrow_sepa_marge_jours', 8)::integer;

  -- A4 + A2 : méthode et timing du débit.
  IF v_premiere THEN
    -- 1re mission : débit immédiat, Jolene fronte sous plafond.
    v_methode := 'VIREMENT_INSTANTANE';
    v_debit_prevu := now();
  ELSIF NEW.debut_le - now() >= make_interval(days => v_marge_jours) THEN
    -- Marge suffisante : SEPA différé, débit initié à J-7 du début.
    v_methode := 'SEPA';
    v_debit_prevu := GREATEST(now(), NEW.debut_le - interval '7 days');
  ELSE
    -- Marge courte : débit immédiat.
    v_methode := 'VIREMENT_INSTANTANE';
    v_debit_prevu := now();
  END IF;

  INSERT INTO paiements_escrow (
    mission_id, etablissement_id, soignant_id,
    montant_total_cents, commission_cents, honoraires_cents,
    methode_debit, statut, debit_prevu_le, premiere_mission_etab
  ) VALUES (
    NEW.id, NEW.etablissement_id, v_soignant_id,
    v_total_c, v_commission_c, v_honoraires_c,
    v_methode, 'INITIE', v_debit_prevu, v_premiere
  );

  PERFORM public.fn_ecrire_audit_safe(
    '00000000-0000-0000-0000-000000000000'::uuid, 'SYSTEME',
    'ESCROW_INITIE', 'mission', NEW.id, NULL,
    jsonb_build_object(
      'etablissement_id', NEW.etablissement_id, 'soignant_id', v_soignant_id,
      'total_cents', v_total_c, 'honoraires_cents', v_honoraires_c,
      'commission_cents', v_commission_c, 'methode', v_methode,
      'premiere_mission_etab', v_premiere, 'debit_prevu_le', v_debit_prevu
    ), NULL, 'fn_trg_escrow_creer_a_confirmation'
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_escrow_creer_a_confirmation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_escrow_enqueue_on_debite"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.statut <> 'DEBITE' OR NEW.statut = OLD.statut THEN RETURN NEW; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.missions m
    WHERE m.id = NEW.mission_id
      AND m.statut = 'TERMINEE'
      AND m.soignant_assigne_id = NEW.soignant_id
      AND m.etablissement_id = NEW.etablissement_id
      AND COALESCE(m.est_arret_maladie, false) IS FALSE
      AND NOT EXISTS (
        SELECT 1 FROM public.missions r
        WHERE r.remplacement_de_mission_id = m.id
      )
  ) THEN RETURN NEW; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.presences p
    WHERE p.mission_id = NEW.mission_id
      AND COALESCE(p.valide_par_etablissement, false) IS TRUE
  ) OR EXISTS (
    SELECT 1 FROM public.presences p
    WHERE p.mission_id = NEW.mission_id
      AND COALESCE(p.valide_par_etablissement, false) IS FALSE
      AND (p.pointage_depart_le IS NOT NULL OR p.motif_litige IS NOT NULL)
  ) THEN RETURN NEW; END IF;

  INSERT INTO public.escrow_release_queue (paiement_escrow_id, mission_id)
  VALUES (NEW.id, NEW.mission_id)
  ON CONFLICT (paiement_escrow_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_escrow_enqueue_on_debite"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_escrow_enqueue_on_terminee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_escrow_id uuid;
BEGIN
  IF NEW.statut <> 'TERMINEE' OR OLD.statut = 'TERMINEE'
     OR NEW.soignant_assigne_id IS NULL
     OR COALESCE(NEW.est_arret_maladie, false) IS TRUE
     OR EXISTS (
       SELECT 1 FROM public.missions r
       WHERE r.remplacement_de_mission_id = NEW.id
     ) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.presences p
    WHERE p.mission_id = NEW.id
      AND COALESCE(p.valide_par_etablissement, false) IS TRUE
  ) OR EXISTS (
    SELECT 1 FROM public.presences p
    WHERE p.mission_id = NEW.id
      AND COALESCE(p.valide_par_etablissement, false) IS FALSE
      AND (p.pointage_depart_le IS NOT NULL OR p.motif_litige IS NOT NULL)
  ) THEN RETURN NEW; END IF;

  SELECT pe.id INTO v_escrow_id
  FROM public.paiements_escrow pe
  WHERE pe.mission_id = NEW.id
    AND pe.soignant_id = NEW.soignant_assigne_id
    AND pe.etablissement_id = NEW.etablissement_id
    AND pe.statut = 'DEBITE';
  IF v_escrow_id IS NOT NULL THEN
    INSERT INTO public.escrow_release_queue (paiement_escrow_id, mission_id)
    VALUES (v_escrow_id, NEW.id)
    ON CONFLICT (paiement_escrow_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_escrow_enqueue_on_terminee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_escrow_release_check"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_escrow_id uuid;
BEGIN
  SELECT pe.id INTO v_escrow_id
  FROM public.paiements_escrow pe
  JOIN public.missions m
    ON m.id = pe.mission_id
   AND m.soignant_assigne_id = pe.soignant_id
   AND m.etablissement_id = pe.etablissement_id
  WHERE pe.mission_id = NEW.mission_id
    AND pe.statut = 'DEBITE'
    AND m.statut = 'TERMINEE'
    AND COALESCE(m.est_arret_maladie, false) IS FALSE
    AND NOT EXISTS (
      SELECT 1 FROM public.missions r
      WHERE r.remplacement_de_mission_id = m.id
    );
  IF v_escrow_id IS NULL THEN RETURN NEW; END IF;

  IF EXISTS (
    SELECT 1 FROM public.presences p
    WHERE p.mission_id = NEW.mission_id
      AND COALESCE(p.valide_par_etablissement, false) IS FALSE
      AND (p.pointage_depart_le IS NOT NULL OR p.motif_litige IS NOT NULL)
  ) THEN RETURN NEW; END IF;

  INSERT INTO public.escrow_release_queue (paiement_escrow_id, mission_id)
  VALUES (v_escrow_id, NEW.mission_id)
  ON CONFLICT (paiement_escrow_id) DO NOTHING;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_escrow_release_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_favori_nouvelle_mission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_etab record;
  v_soignant_id uuid;
  v_url text := 'https://flripxtsyegjshnhzjkz.supabase.co';
  v_token text;
BEGIN
  IF TG_OP <> 'INSERT'
     OR NEW.statut <> 'OUVERTE'
     OR NEW.remplacement_de_mission_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id, nom, adresse_ville
  INTO v_etab
  FROM public.etablissements
  WHERE id = NEW.etablissement_id;

  BEGIN
    v_token := (
      SELECT decrypted_secret
      FROM vault.decrypted_secrets
      WHERE name = 'service_role_key'
      LIMIT 1
    );
  EXCEPTION WHEN OTHERS THEN
    v_token := NULL;
  END;
  IF COALESCE(current_setting('app.test_mode', true), '') = 'true' THEN
    v_token := NULL;
  END IF;

  FOR v_soignant_id IN
    SELECT f.soignant_id
    FROM public.favoris_soignant_etab f
    JOIN public.soignants s
      ON s.id = f.soignant_id
     AND s.supprime_le IS NULL
    WHERE f.etablissement_id = NEW.etablissement_id
      AND public.fn_soignant_eligible_mission(s.id, NEW.id, false)
  LOOP
    IF public.fn_doit_notifier(
      v_soignant_id,
      'FAVORI_NOUVELLE_MISSION'::type_evenement_notification,
      'IN_APP'::canal_notification
    ) THEN
      INSERT INTO public.notifications (
        destinataire_id, type_destinataire, type, titre, corps, lien,
        type_ressource, id_ressource
      ) VALUES (
        v_soignant_id,
        'SOIGNANT',
        'FAVORI_NOUVELLE_MISSION',
        '⭐ Nouvelle mission chez ' || v_etab.nom,
        v_etab.nom || ' a publié "'
          || COALESCE(NEW.intitule, NEW.profession_requise::text)
          || '" à ' || COALESCE(v_etab.adresse_ville, 'votre zone')
          || ' · ' || COALESCE(NEW.taux_horaire_base::text, '?') || '€/h.',
        '/soignant/missions/' || NEW.id::text,
        'mission',
        NEW.id
      );
    END IF;

    IF v_token IS NOT NULL
       AND public.fn_doit_notifier(
         v_soignant_id,
         'FAVORI_NOUVELLE_MISSION'::type_evenement_notification,
         'EMAIL'::canal_notification
       ) THEN
      BEGIN
        PERFORM net.http_post(
          url := v_url || '/functions/v1/send-email',
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || v_token
          ),
          body := jsonb_build_object(
            'type', 'FAVORI_NOUVELLE_MISSION',
            'destinataire_id', v_soignant_id,
            'data', jsonb_build_object(
              'mission_id', NEW.id,
              'mission_intitule', NEW.intitule,
              'etab_nom', v_etab.nom,
              'etab_ville', v_etab.adresse_ville,
              'taux_horaire', NEW.taux_horaire_base,
              'debut_le', NEW.debut_le
            )
          )
        );
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_favori_nouvelle_mission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trg_gate_assignation_paiement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mode text;
  v_mandat boolean;
BEGIN
  IF NEW.soignant_assigne_id IS NOT NULL
     AND (OLD.soignant_assigne_id IS NULL OR OLD.soignant_assigne_id <> NEW.soignant_assigne_id)
     AND auth.uid() IS NOT NULL
     AND NOT est_admin() THEN
    SELECT mode_paiement_commission, stripe_sepa_payment_method_id IS NOT NULL
    INTO v_mode, v_mandat
    FROM etablissements WHERE id = NEW.etablissement_id;

    IF v_mode IS NULL THEN
      RAISE EXCEPTION 'Cette mission ne peut pas être attribuée : l''établissement doit d''abord configurer un mode de paiement (Paramètres → Facturation).';
    END IF;
    IF v_mode = 'SEPA_DEBIT' AND NOT v_mandat THEN
      RAISE EXCEPTION 'Cette mission ne peut pas être attribuée : le mandat SEPA de l''établissement n''est pas encore posé (IBAN à ajouter dans Paramètres → Facturation).';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


