CREATE OR REPLACE FUNCTION "public"."fn_trg_verifier_onboarding_etab"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_blocage jsonb;
BEGIN
  IF public.est_admin() OR auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  v_blocage := public.fn_blocage_publication_etab(NEW.etablissement_id);
  IF v_blocage IS NOT NULL THEN
    RAISE EXCEPTION '%', COALESCE(
      v_blocage->>'message', v_blocage->>'error',
      'Publication de mission interdite'
    ) USING ERRCODE = 'check_violation', DETAIL = v_blocage::text;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trg_verifier_onboarding_etab"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trigger_regen_pdf_immediate"("p_facture_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url TEXT;
  v_key TEXT;
  v_request_id BIGINT;
BEGIN
  IF p_facture_id IS NULL THEN RETURN NULL; END IF;

  SELECT valeur INTO v_url
    FROM public.parametres_litiges WHERE cle = 'generate_invoice_url';
  IF v_url IS NULL OR length(v_url) = 0 THEN
    RETURN NULL;
  END IF;

  BEGIN
    SELECT decrypted_secret INTO v_key
      FROM vault.decrypted_secrets
     WHERE name = 'service_role_key'
     LIMIT 1;
  EXCEPTION WHEN OTHERS THEN
    v_key := NULL;
  END;
  IF v_key IS NULL OR length(v_key) = 0 THEN
    RETURN NULL;
  END IF;

  SELECT net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    body := jsonb_build_object(
      'facture_id', p_facture_id,
      'service_role_reason', 'admin_resoudre_litige_immediate'
    )
  ) INTO v_request_id;

  RETURN v_request_id;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_regen_pdf_immediate"("p_facture_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_trigger_regen_pdf_immediate"("p_facture_id" "uuid") IS 'CP-LITIGES-7a FIX 18 — déclenche regen PDF immédiat via pg_net. Retourne net.http_post request_id ou NULL si URL/secret manquant.';



CREATE OR REPLACE FUNCTION "public"."fn_tripwire_alerte"("p_sujet" "text", "p_corps" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF public.fn_param_num('alertes_tripwire_actives', 1) <> 1 THEN
    RETURN;
  END IF;

  -- 1. Alerte in-app CRITICAL dans le canal (visible cockpit, dédupliquée).
  BEGIN
    INSERT INTO public.alertes_systeme (type_alerte, severite, source, message, details, occurrences, derniere_occurrence, email_envoye_le)
    VALUES ('TRIPWIRE_PREMIER_EURO', 'CRITICAL', p_sujet, p_sujet, jsonb_build_object('corps', p_corps), 1, now(), now())
    ON CONFLICT (source, type_alerte) WHERE resolu_le IS NULL
    DO UPDATE SET occurrences = alertes_systeme.occurrences + 1, derniere_occurrence = now(), email_envoye_le = now(), details = EXCLUDED.details;
  EXCEPTION WHEN OTHERS THEN
    NULL; -- non bloquant.
  END;

  -- 2. Email (inchangé — edge notify-support).
  BEGIN
    PERFORM net.http_post(
      url := 'https://flripxtsyegjshnhzjkz.supabase.co/functions/v1/notify-support',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1)
      ),
      body := jsonb_build_object('sujet', p_sujet, 'corps', p_corps, 'source', 'tripwire-paiement')
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- non bloquant : une alerte ratée ne casse jamais le flux métier.
  END;
END;
$$;


ALTER FUNCTION "public"."fn_tripwire_alerte"("p_sujet" "text", "p_corps" "text") OWNER TO "postgres";


