CREATE OR REPLACE FUNCTION "public"."fn_typing_start"("p_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'NON_AUTHENTIFIE' USING ERRCODE = '28000';
  END IF;

  IF public.fn_conversation_accessible(p_conversation_id) IS NOT TRUE
     OR private.fn_peut_ecrire_conversation(
       v_uid,
       p_conversation_id
     ) IS NOT TRUE THEN
    RAISE EXCEPTION 'NON_AUTORISE' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.typing_status (
    conversation_id,
    user_id,
    started_at
  ) VALUES (
    p_conversation_id,
    v_uid,
    clock_timestamp()
  )
  ON CONFLICT (conversation_id, user_id) DO UPDATE
  SET started_at = excluded.started_at;
END;
$$;


ALTER FUNCTION "public"."fn_typing_start"("p_conversation_id" "uuid") OWNER TO "postgres";


