    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN;
  END IF;

  DELETE FROM public.typing_status
  WHERE conversation_id = p_conversation_id
    AND user_id = v_uid;
END;
