CREATE OR REPLACE FUNCTION "public"."fn_uploader_contrat_travail_mission"("p_mission_id" "uuid", "p_pdf_s3_key" "text", "p_nom_fichier" "text", "p_taille_octets" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_etab_id uuid;
  v_soignant_id uuid;
  v_existing_id uuid;
  v_action text;
BEGIN
  -- Récupérer etab + soignant de la mission
  SELECT etablissement_id, soignant_assigne_id
  INTO v_etab_id, v_soignant_id
  FROM public.missions
  WHERE id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Mission introuvable');
  END IF;

  -- Vérification : actor doit être l'établissement (ou admin)
  IF NOT est_admin() AND v_etab_id IS DISTINCT FROM mon_etablissement_id() THEN
    RETURN jsonb_build_object('error', 'Accès refusé');
  END IF;

  IF v_soignant_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Mission sans soignant assigné');
  END IF;

  -- INSERT ou UPDATE (idempotent par mission_id)
  SELECT id INTO v_existing_id FROM public.contrats_travail_missions WHERE mission_id = p_mission_id;

  IF v_existing_id IS NULL THEN
    INSERT INTO public.contrats_travail_missions (mission_id, etablissement_id, soignant_id, pdf_s3_key, nom_fichier, taille_octets, uploaded_by, uploaded_at)
    VALUES (p_mission_id, v_etab_id, v_soignant_id, p_pdf_s3_key, p_nom_fichier, p_taille_octets, v_actor, now());
    v_action := 'CONTRAT_TRAVAIL_UPLOADE';
  ELSE
    UPDATE public.contrats_travail_missions
    SET pdf_s3_key = p_pdf_s3_key,
        nom_fichier = p_nom_fichier,
        taille_octets = p_taille_octets,
        uploaded_at = now(),
        uploaded_by = v_actor
    WHERE id = v_existing_id;
    v_action := 'CONTRAT_TRAVAIL_REMPLACE';
  END IF;

  PERFORM fn_ecrire_audit_safe(
    v_actor,
    CASE WHEN est_admin() THEN 'ADMIN_PLATEFORME' ELSE 'ADMIN_ETABLISSEMENT' END,
    v_action, 'mission', p_mission_id,
    NULL, jsonb_build_object('nom_fichier', p_nom_fichier, 'taille_octets', p_taille_octets),
    NULL, NULL
  );

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."fn_uploader_contrat_travail_mission"("p_mission_id" "uuid", "p_pdf_s3_key" "text", "p_nom_fichier" "text", "p_taille_octets" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_upsert_token_push"("p_token" "text", "p_plateforme" "text" DEFAULT 'WEB'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_token text := trim(COALESCE(p_token, ''));
  v_plateforme text := upper(trim(COALESCE(p_plateforme, '')));
  v_json jsonb;
  v_endpoint text;
  v_p256dh text;
  v_auth_key text;
BEGIN
  IF v_uid IS NULL OR NOT public.fn_compte_auth_actif() THEN
    RAISE EXCEPTION 'Non authentifie' USING ERRCODE = '42501';
  END IF;
  IF length(v_token) < 16 OR length(v_token) > 4096 THEN
    RAISE EXCEPTION 'Token push invalide' USING ERRCODE = '22023';
  END IF;
  IF v_plateforme NOT IN ('WEB', 'IOS', 'ANDROID') THEN
    RAISE EXCEPTION 'Plateforme push invalide' USING ERRCODE = '22023';
  END IF;

  -- Une subscription PushManager reste du Web Push meme si le user-agent est
  -- Safari iOS/Chrome Android et que l'ancien client l'etiquette IOS/ANDROID.
  IF left(v_token, 1) = '{' THEN
    v_plateforme := 'WEB';
    BEGIN
      v_json := v_token::jsonb;
      v_endpoint := NULLIF(trim(v_json ->> 'endpoint'), '');
      v_p256dh := NULLIF(trim(v_json -> 'keys' ->> 'p256dh'), '');
      v_auth_key := NULLIF(trim(v_json -> 'keys' ->> 'auth'), '');
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Abonnement Web Push JSON invalide' USING ERRCODE = '22023';
    END;
    -- Allowlist fournisseur stricte : cet endpoint sera appele depuis l'Edge
    -- Function. Autoriser une URL HTTPS arbitraire creerait un SSRF aveugle.
    -- L'ancrage impose aussi l'absence de userinfo et de port explicite.
    IF v_endpoint IS NULL
       OR length(v_endpoint) > 2048
       OR v_endpoint !~* '^https://(fcm[.]googleapis[.]com|updates[.]push[.]services[.]mozilla[.]com|([a-z0-9-]+[.])+push[.]apple[.]com|([a-z0-9-]+[.])*notify[.]windows[.]com)(/|$)'
       OR v_p256dh IS NULL OR length(v_p256dh) > 512
       OR v_auth_key IS NULL OR length(v_auth_key) > 512 THEN
      RAISE EXCEPTION 'Abonnement Web Push incomplet' USING ERRCODE = '22023';
    END IF;
  ELSIF v_plateforme = 'WEB' THEN
    RAISE EXCEPTION 'Abonnement Web Push JSON requis' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tokens_push(
    utilisateur_id, token, plateforme, endpoint, p256dh, auth_key,
    actif, derniere_utilisation
  ) VALUES (
    v_uid, v_token, v_plateforme, v_endpoint, v_p256dh, v_auth_key,
    true, now()
  )
  ON CONFLICT (token) DO UPDATE SET
    utilisateur_id = EXCLUDED.utilisateur_id,
    plateforme = EXCLUDED.plateforme,
    endpoint = EXCLUDED.endpoint,
    p256dh = EXCLUDED.p256dh,
    auth_key = EXCLUDED.auth_key,
    actif = true,
    derniere_utilisation = now();
END;
$_$;


ALTER FUNCTION "public"."fn_upsert_token_push"("p_token" "text", "p_plateforme" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_user_id_pour_etablissement"("p_etablissement_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_autorise boolean;
BEGIN
  IF v_caller IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RAISE EXCEPTION 'Non authentifié' USING ERRCODE = '28000';
  END IF;

  v_autorise :=
       public.est_admin()
    OR EXISTS (
      SELECT 1
      FROM public.membres_etablissement me
      JOIN public.etablissements e ON e.id = me.etablissement_id
      WHERE me.user_id = v_caller
        AND me.etablissement_id = p_etablissement_id
        AND me.actif IS TRUE
        AND e.supprime_le IS NULL
    )
    OR (
      v_caller = p_etablissement_id
      AND EXISTS (
        SELECT 1
        FROM auth.users u
        JOIN public.etablissements e ON e.id = u.id
        WHERE u.id = v_caller
          AND e.supprime_le IS NULL
          AND u.deleted_at IS NULL
          AND u.email_confirmed_at IS NOT NULL
          AND (u.banned_until IS NULL OR u.banned_until <= pg_catalog.now())
          AND u.raw_app_meta_data ->> 'role' IN (
            'ADMIN_ETABLISSEMENT', 'ETABLISSEMENT', 'ADMIN_GROUPE'
          )
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.membres_etablissement me
        WHERE me.user_id = v_caller
          AND me.etablissement_id = p_etablissement_id
      )
    )
    OR EXISTS (
      SELECT 1
      FROM public.missions m
      WHERE m.etablissement_id = p_etablissement_id
        AND m.soignant_assigne_id = v_caller
    )
    OR EXISTS (
      SELECT 1
      FROM public.candidatures c
      JOIN public.missions m ON m.id = c.mission_id
      WHERE m.etablissement_id = p_etablissement_id
        AND c.soignant_id = v_caller
        AND c.statut = 'ACCEPTEE'
    );

  IF COALESCE(v_autorise, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Non autorisé' USING ERRCODE = '42501';
  END IF;

  RETURN private.fn_interlocuteur_operationnel_id(p_etablissement_id);
END;
$$;


ALTER FUNCTION "public"."fn_user_id_pour_etablissement"("p_etablissement_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_user_id_pour_etablissement"("p_etablissement_id" "uuid") IS 'Résout un interlocuteur Auth actif pour un établissement autorisé : membre actif, fallback UUID historique, puis app_metadata serveur.';



CREATE OR REPLACE FUNCTION "public"."fn_vagues_notification_urgentes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_m record;
  v_s record;
  v_taille integer;
  v_envoyes integer := 0;
  v_missions integer := 0;
  v_nu_missions integer := 0;
  v_nu_envoyes integer := 0;
  v_url text := 'https://flripxtsyegjshnhzjkz.supabase.co';
  v_token text;
  v_corps text;
  v_t1 integer := GREATEST(1, public.fn_param_num('vague_taille_1', 10)::integer);
  v_t2 integer := GREATEST(1, public.fn_param_num('vague_taille_2', 30)::integer);
  v_t3 integer := GREATEST(1, public.fn_param_num('vague_taille_3', 60)::integer);
  v_d2 integer := GREATEST(1, public.fn_param_num('vague_delai_2_min', 15)::integer);
  v_d3 integer := GREATEST(1, public.fn_param_num('vague_delai_3_min', 30)::integer);
  v_cap integer := GREATEST(1, public.fn_param_num('vague_cap_push_24h', 3)::integer);
  v_fenetre_h integer := GREATEST(1, public.fn_param_num('vague_fenetre_urgente_h', 48)::integer);
  v_nu_delai_h integer := GREATEST(1, public.fn_param_num('vague_non_urgente_delai_h', 4)::integer);
  v_nu_taille integer := GREATEST(1, public.fn_param_num('vague_non_urgente_taille', 20)::integer);
  v_nu_cap integer := GREATEST(1, public.fn_param_num('vague_non_urgente_cap_24h', 2)::integer);
BEGIN
  BEGIN
    v_token := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'service_role_key' LIMIT 1);
  EXCEPTION WHEN OTHERS THEN v_token := NULL;
  END;

  FOR v_m IN
    SELECT m.id, m.intitule, m.taux_horaire_base, m.debut_le, m.cree_le,
           m.etablissement_id, e.adresse_ville AS etab_ville,
           e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng
    FROM public.missions m
    JOIN public.etablissements e ON e.id = m.etablissement_id
    WHERE m.statut = 'OUVERTE'
      AND m.est_urgente
      AND m.remplacement_de_mission_id IS NULL
      AND m.debut_le BETWEEN now() AND now() + make_interval(hours => v_fenetre_h)
      AND m.intitule NOT LIKE '[%'
      AND NOT EXISTS (SELECT 1 FROM public.candidatures c WHERE c.mission_id = m.id)
  LOOP
    v_missions := v_missions + 1;
    v_taille := CASE
      WHEN v_m.cree_le > now() - make_interval(mins => v_d2) THEN v_t1
      WHEN v_m.cree_le > now() - make_interval(mins => v_d3) THEN v_t2
      ELSE v_t3
    END;
    v_corps := public.fn_html_escape(v_m.intitule) || ' — ' || COALESCE(v_m.etab_ville, '') ||
      ', débute le ' || to_char(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24:MI') ||
      ' à ' || COALESCE(v_m.taux_horaire_base::text, '?') || ' €/h.';

    FOR v_s IN
      SELECT s.id AS soignant_id
      FROM public.soignants s
      LEFT JOIN public.matching_scores ms ON ms.soignant_id = s.id AND ms.mission_id = v_m.id
      WHERE public.fn_soignant_eligible_mission(s.id, v_m.id, true)
        AND NOT public.fn_est_exclu(s.id, v_m.etablissement_id)
        AND NOT EXISTS (SELECT 1 FROM public.swipes sw WHERE sw.mission_id = v_m.id AND sw.soignant_id = s.id)
        AND (s.adresse_lat IS NULL OR v_m.etab_lat IS NULL
             OR public.fn_haversine_distance_m(s.adresse_lat, s.adresse_lng, v_m.etab_lat, v_m.etab_lng)
                <= COALESCE(s.rayon_deplacement_km, 50) * 1000)
        AND NOT EXISTS (
          SELECT 1 FROM public.notifications n
          WHERE n.destinataire_id = s.id AND n.type = 'MISSION_URGENTE'
            AND n.lien = '/soignant/missions/' || v_m.id
        )
        AND (
          SELECT count(*) FROM public.notifications n2
          WHERE n2.destinataire_id = s.id AND n2.type = 'MISSION_URGENTE'
            AND n2.cree_le > now() - interval '24 hours'
        ) < v_cap
      ORDER BY COALESCE(ms.score_global, 0) DESC,
        public.fn_haversine_distance_m(
          COALESCE(s.adresse_lat, 0), COALESCE(s.adresse_lng, 0),
          COALESCE(v_m.etab_lat, 0), COALESCE(v_m.etab_lng, 0)
        ) ASC
      LIMIT v_taille
    LOOP
      INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
      VALUES (
        v_s.soignant_id, 'MISSION_URGENTE', '⚡ Mission urgente sélectionnée pour vous',
        v_corps, '/soignant/missions/' || v_m.id, 'SOIGNANT'
      );
      IF v_token IS NOT NULL THEN
        BEGIN
          PERFORM net.http_post(
            url := v_url || '/functions/v1/send-push',
            headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token),
            body := jsonb_build_object(
              'destinataire_id', v_s.soignant_id,
              'type_evenement', 'MISSION_URGENTE',
              'titre', '⚡ Mission urgente sélectionnée pour vous',
              'corps', v_corps,
              'data', jsonb_build_object('mission_id', v_m.id, 'lien', '/soignant/missions/' || v_m.id)
            )
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END IF;
      v_envoyes := v_envoyes + 1;
    END LOOP;
  END LOOP;

  FOR v_m IN
    SELECT m.id, m.intitule, m.taux_horaire_base, m.debut_le, m.etablissement_id,
           e.adresse_ville AS etab_ville, e.adresse_lat AS etab_lat, e.adresse_lng AS etab_lng
    FROM public.missions m
    JOIN public.etablissements e ON e.id = m.etablissement_id
    WHERE m.statut = 'OUVERTE'
      AND NOT m.est_urgente
      AND m.remplacement_de_mission_id IS NULL
      AND m.cree_le < now() - make_interval(hours => v_nu_delai_h)
      AND m.debut_le > now()
      AND m.intitule NOT LIKE '[%'
      AND NOT EXISTS (SELECT 1 FROM public.candidatures c WHERE c.mission_id = m.id)
      AND NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.type = 'MISSION_A_POURVOIR' AND n.lien = '/soignant/missions/' || m.id
      )
  LOOP
    v_nu_missions := v_nu_missions + 1;
    v_corps := public.fn_html_escape(v_m.intitule) || ' — ' || COALESCE(v_m.etab_ville, '') ||
      ', débute le ' || to_char(v_m.debut_le AT TIME ZONE 'Europe/Paris', 'DD/MM à HH24:MI') ||
      ' à ' || COALESCE(v_m.taux_horaire_base::text, '?') || ' €/h. Personne n''a encore postulé.';

    FOR v_s IN
      SELECT s.id AS soignant_id
      FROM public.soignants s
      LEFT JOIN public.matching_scores ms ON ms.soignant_id = s.id AND ms.mission_id = v_m.id
      WHERE public.fn_soignant_eligible_mission(s.id, v_m.id, true)
        AND NOT public.fn_est_exclu(s.id, v_m.etablissement_id)
        AND NOT EXISTS (SELECT 1 FROM public.swipes sw WHERE sw.mission_id = v_m.id AND sw.soignant_id = s.id)
        AND (s.adresse_lat IS NULL OR v_m.etab_lat IS NULL
             OR public.fn_haversine_distance_m(s.adresse_lat, s.adresse_lng, v_m.etab_lat, v_m.etab_lng)
                <= COALESCE(s.rayon_deplacement_km, 50) * 1000)
        AND (
          SELECT count(*) FROM public.notifications n2
          WHERE n2.destinataire_id = s.id AND n2.type = 'MISSION_A_POURVOIR'
            AND n2.cree_le > now() - interval '24 hours'
        ) < v_nu_cap
      ORDER BY COALESCE(ms.score_global, 0) DESC
      LIMIT v_nu_taille
    LOOP
      INSERT INTO public.notifications(destinataire_id, type, titre, corps, lien, type_destinataire)
      VALUES (
        v_s.soignant_id, 'MISSION_A_POURVOIR', '✨ Une mission sélectionnée pour vous',
        v_corps, '/soignant/missions/' || v_m.id, 'SOIGNANT'
      );
      IF v_token IS NOT NULL THEN
        BEGIN
          PERFORM net.http_post(
            url := v_url || '/functions/v1/send-push',
            headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_token),
            body := jsonb_build_object(
              'destinataire_id', v_s.soignant_id,
              'type_evenement', 'MISSION_A_POURVOIR',
              'titre', '✨ Une mission sélectionnée pour vous',
              'corps', v_corps,
              'data', jsonb_build_object('mission_id', v_m.id, 'lien', '/soignant/missions/' || v_m.id)
            )
          );
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
      END IF;
      v_nu_envoyes := v_nu_envoyes + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'missions', v_missions,
    'notifications', v_envoyes,
    'missions_non_urgentes', v_nu_missions,
    'notifications_non_urgentes', v_nu_envoyes
  );
END;
$$;


ALTER FUNCTION "public"."fn_vagues_notification_urgentes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_alerte_presence"("p_presence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_presence RECORD;
    v_etab_id UUID := mon_etablissement_id();
BEGIN
    SELECT p.*, m.etablissement_id FROM presences p 
    JOIN missions m ON m.id = p.mission_id 
    WHERE p.id = p_presence_id INTO v_presence;
    
    IF v_presence IS NULL THEN RETURN jsonb_build_object('error', 'Présence introuvable'); END IF;
    
    IF v_presence.etablissement_id != v_etab_id AND NOT est_admin() THEN
        RETURN jsonb_build_object('error', 'Accès refusé');
    END IF;
    
    UPDATE presences SET 
        valide_par_etablissement = TRUE, 
        valide_le = NOW()
    WHERE id = p_presence_id;
    
    RETURN jsonb_build_object('success', TRUE, 'message', 'Présence validée');
END;
$$;


ALTER FUNCTION "public"."fn_valider_alerte_presence"("p_presence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_code_secours"("p_mission_id" "uuid", "p_code" "text", "p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_precision" numeric DEFAULT NULL::numeric, "p_terminal_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_mission RECORD;
  v_code_row RECORD;
  v_presence RECORD;
  v_type_detecte text;
  v_now timestamptz := NOW();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF p_code IS NULL OR p_code !~ '^[0-9]{6}$' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CODE_FORMAT_INVALIDE',
                                'error', 'Le code doit être 6 chiffres.');
  END IF;

  SELECT * INTO v_mission FROM public.missions WHERE id = p_mission_id;
  IF v_mission IS NULL OR v_mission.soignant_assigne_id != v_uid THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTORISE',
                                'error', 'Vous n''êtes pas assigné à cette mission.');
  END IF;

  -- Trouver le code matching (non utilisé, non expiré)
  -- Boucle car bcrypt nécessite la comparaison hash par hash
  SELECT * INTO v_code_row FROM public.codes_secours_mission
  WHERE mission_id = p_mission_id
    AND utilise = false
    AND expire_le > v_now
    AND code_hash = crypt(p_code, code_hash)
  LIMIT 1;

  IF v_code_row IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CODE_INVALIDE',
                                'error', 'Code incorrect, déjà utilisé ou expiré.');
  END IF;

  -- Déterminer type pointage selon presences
  SELECT * INTO v_presence FROM public.presences
  WHERE mission_id = v_mission.id AND soignant_id = v_uid LIMIT 1;

  IF v_code_row.type = 'ARRIVEE' THEN
    v_type_detecte := 'ARRIVEE';
  ELSIF v_code_row.type = 'DEPART' THEN
    v_type_detecte := 'DEPART';
  ELSE
    v_type_detecte := CASE WHEN v_presence IS NULL THEN 'ARRIVEE' ELSE 'DEPART' END;
  END IF;

  -- Vérifs identiques scan QR
  IF v_type_detecte = 'ARRIVEE' AND v_presence.id IS NOT NULL AND v_presence.pointage_arrivee_le IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_POINTE');
  END IF;
  IF v_type_detecte = 'DEPART' THEN
    IF v_presence IS NULL OR v_presence.pointage_arrivee_le IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEPART_SANS_ARRIVEE');
    END IF;
    IF v_presence.pointage_depart_le IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEPART_DEJA_POINTE');
    END IF;
    IF v_now < v_presence.pointage_arrivee_le + INTERVAL '30 minutes' THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEPART_TROP_RAPIDE');
    END IF;
  END IF;

  -- Marquer code utilisé
  UPDATE public.codes_secours_mission SET
    utilise = true, utilise_le = v_now, utilise_par = v_uid
  WHERE id = v_code_row.id;

  -- INSERT/UPDATE presence
  IF v_type_detecte = 'ARRIVEE' THEN
    IF v_presence IS NULL THEN
      INSERT INTO public.presences (
        mission_id, soignant_id, pointage_arrivee_le,
        arrivee_lat, arrivee_lng, arrivee_precision_gps_m,
        arrivee_id_terminal, methode_pointage_arrivee
      ) VALUES (v_mission.id, v_uid, v_now, p_lat, p_lng, p_precision,
        p_terminal_id, 'CODE_SECOURS');
    ELSE
      UPDATE public.presences SET
        pointage_arrivee_le = v_now,
        arrivee_lat = p_lat, arrivee_lng = p_lng,
        arrivee_precision_gps_m = p_precision,
        arrivee_id_terminal = p_terminal_id,
        methode_pointage_arrivee = 'CODE_SECOURS'
      WHERE id = v_presence.id;
    END IF;
    UPDATE public.missions SET statut = 'EN_COURS', modifie_le = NOW()
    WHERE id = v_mission.id AND statut = 'ASSIGNEE';
  ELSE
    UPDATE public.presences SET
      pointage_depart_le = v_now,
      depart_lat = p_lat, depart_lng = p_lng,
      depart_precision_gps_m = p_precision,
      depart_id_terminal = p_terminal_id,
      methode_pointage_depart = 'CODE_SECOURS'
    WHERE id = v_presence.id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'methode_detectee', v_type_detecte,
    'mission_id', v_mission.id,
    'horodatage', v_now
  );
END;
$_$;


ALTER FUNCTION "public"."fn_valider_code_secours"("p_mission_id" "uuid", "p_code" "text", "p_lat" numeric, "p_lng" numeric, "p_precision" numeric, "p_terminal_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_presence"("p_presence_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid;
  v_presence record;
BEGIN
  v_etab_id := mon_etablissement_id();
  IF v_etab_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  SELECT p.* INTO v_presence
  FROM presences p
  JOIN missions m ON m.id = p.mission_id
  WHERE p.id = p_presence_id
    AND m.etablissement_id = v_etab_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Présence introuvable');
  END IF;

  IF v_presence.valide_par_etablissement = true THEN
    RETURN jsonb_build_object('success', false, 'error', 'Déjà validée');
  END IF;

  UPDATE presences
  SET valide_par_etablissement = true,
      valide_le = now(),
      modifie_le = now()
  WHERE id = p_presence_id;

  -- Lot 13 : la transition est auditée CÔTÉ SQL (l'audit client seul manquait
  -- tout chemin non-UI) et le soignant est notifié (déclencheur du paiement).
  PERFORM fn_ecrire_audit(
    v_etab_id, 'ETABLISSEMENT', 'PRESENCE_VALIDATION', 'presence',
    p_presence_id, NULL,
    jsonb_build_object('mission_id', v_presence.mission_id, 'soignant_id', v_presence.soignant_id)
  );
  BEGIN
    PERFORM fn_creer_notification(
      p_destinataire_id   := v_presence.soignant_id,
      p_type_destinataire := 'SOIGNANT',
      p_type              := 'PRESENCE_VALIDEE',
      p_titre             := 'Présence validée',
      p_corps             := 'Vos heures ont été validées par l''établissement. Le paiement suit son cours.',
      p_lien              := '/soignant/presences',
      p_type_ressource    := 'presence',
      p_id_ressource      := p_presence_id
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- une notif ratée ne doit jamais annuler une validation.
  END;

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION "public"."fn_valider_presence"("p_presence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_presences_72h_auto"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count int;
  v_delai interval := ((public.fn_param_num('delai_autovalidation_presence_h', 72))::text || ' hours')::interval;
BEGIN
  UPDATE public.presences
  SET valide_auto_72h_le = NOW(), valide_par_etablissement = true,
      valide_le = COALESCE(valide_le, NOW()), modifie_le = NOW()
  WHERE pointage_depart_le IS NOT NULL
    AND pointage_depart_le < NOW() - v_delai
    AND COALESCE(valide_par_etablissement, false) = false
    AND motif_litige IS NULL
    AND valide_auto_72h_le IS NULL
    AND COALESCE(alerte_teleportation, false) = false
    AND (alertes_fraude IS NULL OR alertes_fraude = '[]'::JSONB);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count > 0 THEN
    INSERT INTO public.journaux_audit (acteur_id, type_acteur, action, type_ressource, id_ressource, details)
    VALUES ('00000000-0000-0000-0000-000000000000', 'SYSTEME', 'SYSTEM', 'cron', NULL,
      jsonb_build_object('evenement', 'PRESENCES_VALIDEES_AUTO_72H', 'count', v_count, 'exec_le', NOW()));
  END IF;
  RETURN jsonb_build_object('success', true, 'count_validees', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_valider_presences_72h_auto"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_presences_lot"("p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_etab_id uuid;
  v_count integer;
  v_presence_ids jsonb := '[]'::jsonb;
  v_validees jsonb := '[]'::jsonb;
  v_row jsonb;
BEGIN
  v_etab_id := public.mon_etablissement_id();
  IF v_etab_id IS NULL
     OR public.fn_a_permission_etablissement('pointage', v_etab_id) IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'Non autorisé');
  END IF;

  WITH maj AS (
    UPDATE public.presences p
       SET valide_par_etablissement = true,
           valide_le = now(),
           modifie_le = now()
      FROM public.missions m
     WHERE p.id = ANY(p_ids)
       AND p.mission_id = m.id
       AND m.etablissement_id = v_etab_id
       AND p.valide_par_etablissement = false
       AND p.perimetre_gps_valide = true
       AND COALESCE(p.alerte_teleportation, false) = false
    RETURNING p.id, p.mission_id, p.soignant_id
  )
  SELECT count(*)::integer,
         COALESCE(jsonb_agg(maj.id), '[]'::jsonb),
         COALESCE(
           jsonb_agg(jsonb_build_object(
             'presence_id', maj.id,
             'mission_id', maj.mission_id,
             'soignant_id', maj.soignant_id
           )),
           '[]'::jsonb
         )
    INTO v_count, v_presence_ids, v_validees
    FROM maj;

  IF v_count > 0 THEN
    PERFORM public.fn_ecrire_audit(
      v_etab_id,
      'ETABLISSEMENT',
      'PRESENCE_VALIDATION_LOT',
      'presence',
      NULL,
      NULL,
      jsonb_build_object(
        'nb_validees', v_count,
        'presence_ids', v_presence_ids
      )
    );

    FOR v_row IN
      SELECT value FROM jsonb_array_elements(v_validees)
    LOOP
      BEGIN
        PERFORM public.fn_creer_notification(
          p_destinataire_id   := (v_row->>'soignant_id')::uuid,
          p_type_destinataire := 'SOIGNANT',
          p_type              := 'PRESENCE_VALIDEE',
          p_titre             := 'Présence validée',
          p_corps             := 'Vos heures ont été validées par l''établissement. Le paiement suit son cours.',
          p_lien              := '/soignant/presences',
          p_type_ressource    := 'presence',
          p_id_ressource      := (v_row->>'presence_id')::uuid
        );
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('success', true, 'nb_validees', v_count);
END;
$$;


ALTER FUNCTION "public"."fn_valider_presences_lot"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_scan_qr"("p_token" "text", "p_lat" numeric DEFAULT NULL::numeric, "p_lng" numeric DEFAULT NULL::numeric, "p_precision" numeric DEFAULT NULL::numeric, "p_terminal_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_qr RECORD;
  v_mission RECORD;
  v_etab RECORD;
  v_presence RECORD;
  v_type_detecte text;
  v_distance_m numeric;
  v_perimetre_ok boolean;
  v_now timestamptz := NOW();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;

  SELECT * INTO v_qr FROM public.qr_codes_mission WHERE token = p_token AND actif = true;
  IF v_qr IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'QR_INVALIDE',
                                'error', 'QR non valide ou déjà invalidé.');
  END IF;

  IF v_qr.expire_le < v_now THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'QR_EXPIRE',
                                'error', 'Ce QR a expiré. Demandez à l''établissement de régénérer.');
  END IF;

  SELECT * INTO v_mission FROM public.missions WHERE id = v_qr.mission_id;
  -- FIX : IS DISTINCT FROM (sémantique NULL correcte) — refuse aussi les
  -- missions sans assigné, qui passaient le garde `!=` (NULL ≠ TRUE).
  IF v_mission.id IS NULL OR v_mission.soignant_assigne_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'QR_MISSION_AUTRE',
                                'error', 'Ce QR ne correspond pas à votre mission active.');
  END IF;

  -- Cohérence temporelle
  IF v_now < v_mission.debut_le - INTERVAL '1 hour' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'HEURE_TROP_TOT',
                                'error', 'Trop tôt pour pointer. Mission démarre à ' ||
                                  to_char(v_mission.debut_le, 'DD/MM HH24:MI') || '.');
  END IF;
  IF v_now > COALESCE(v_mission.fin_le, v_now + INTERVAL '1 day') + INTERVAL '2 hours' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'HEURE_TROP_TARD',
                                'error', 'Trop tard pour pointer. Mission terminée depuis plus de 2 heures.');
  END IF;

  -- Détecter le type de pointage selon presences existantes
  SELECT * INTO v_presence FROM public.presences
  WHERE mission_id = v_mission.id AND soignant_id = v_uid LIMIT 1;

  IF v_qr.type = 'ARRIVEE' THEN
    v_type_detecte := 'ARRIVEE';
  ELSIF v_qr.type = 'DEPART' THEN
    v_type_detecte := 'DEPART';
  ELSE
    -- UNIVERSEL : pas de presence → ARRIVEE, sinon DEPART
    v_type_detecte := CASE WHEN v_presence IS NULL THEN 'ARRIVEE' ELSE 'DEPART' END;
  END IF;

  -- Vérif double pointage / cohérence départ > arrivée + 30 min
  IF v_type_detecte = 'ARRIVEE' AND v_presence.id IS NOT NULL AND v_presence.pointage_arrivee_le IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'DEJA_POINTE',
                                'error', 'Vous avez déjà pointé votre arrivée.');
  END IF;
  IF v_type_detecte = 'DEPART' THEN
    IF v_presence IS NULL OR v_presence.pointage_arrivee_le IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEPART_SANS_ARRIVEE',
                                  'error', 'Vous devez d''abord pointer votre arrivée.');
    END IF;
    IF v_presence.pointage_depart_le IS NOT NULL THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEPART_DEJA_POINTE',
                                  'error', 'Vous avez déjà pointé votre départ.');
    END IF;
    IF v_now < v_presence.pointage_arrivee_le + INTERVAL '30 minutes' THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'DEPART_TROP_RAPIDE',
                                  'error', 'Vous ne pouvez pointer votre départ moins de 30 minutes après l''arrivée.');
    END IF;
  END IF;

  -- Double sécurité GPS : calcul distance si coords fournies (non bloquant)
  IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    SELECT adresse_lat, adresse_lng, COALESCE(tolerance_pointage_m, 100) AS tolerance_m
    INTO v_etab FROM public.etablissements WHERE id = v_mission.etablissement_id;
    IF v_etab.adresse_lat IS NOT NULL AND v_etab.adresse_lng IS NOT NULL THEN
      v_distance_m := public.fn_haversine_distance_m(
        p_lat, p_lng, v_etab.adresse_lat::numeric, v_etab.adresse_lng::numeric);
      v_perimetre_ok := v_distance_m <= GREATEST(v_etab.tolerance_m, 1000);
      -- Si distance > 1 km : alerte admin mais pas bloquant (QR = source de vérité)
      IF v_distance_m > 1000 THEN
        INSERT INTO public.journaux_audit (
          acteur_id, type_acteur, action, type_ressource, id_ressource, details
        ) VALUES (
          v_uid, 'SOIGNANT', 'SYSTEM', 'presence', v_mission.id,
          jsonb_build_object(
            'evenement', 'QR_SCAN_GPS_ELOIGNE',
            'niveau', 'WARNING',
            'mission_id', v_mission.id,
            'distance_m', v_distance_m,
            'qr_id', v_qr.id
          )
        );
      END IF;
    END IF;
  END IF;

  -- Insert ou Update presence
  IF v_type_detecte = 'ARRIVEE' THEN
    IF v_presence IS NULL THEN
      INSERT INTO public.presences (
        mission_id, soignant_id, pointage_arrivee_le,
        arrivee_lat, arrivee_lng, arrivee_precision_gps_m,
        arrivee_id_terminal,
        methode_pointage_arrivee, qr_token_arrivee,
        distance_etablissement_m, perimetre_gps_valide
      ) VALUES (
        v_mission.id, v_uid, v_now,
        p_lat, p_lng, p_precision,
        p_terminal_id,
        'QR', p_token,
        v_distance_m, v_perimetre_ok
      );
    ELSE
      UPDATE public.presences SET
        pointage_arrivee_le = v_now,
        arrivee_lat = p_lat, arrivee_lng = p_lng,
        arrivee_precision_gps_m = p_precision,
        arrivee_id_terminal = p_terminal_id,
        methode_pointage_arrivee = 'QR',
        qr_token_arrivee = p_token,
        distance_etablissement_m = COALESCE(v_distance_m, distance_etablissement_m),
        perimetre_gps_valide = COALESCE(v_perimetre_ok, perimetre_gps_valide)
      WHERE id = v_presence.id;
    END IF;
    UPDATE public.missions SET statut = 'EN_COURS', modifie_le = NOW()
    WHERE id = v_mission.id AND statut = 'ASSIGNEE';
  ELSE  -- DEPART
    UPDATE public.presences SET
      pointage_depart_le = v_now,
      depart_lat = p_lat, depart_lng = p_lng,
      depart_precision_gps_m = p_precision,
      depart_id_terminal = p_terminal_id,
      methode_pointage_depart = 'QR',
      qr_token_depart = p_token,
      distance_etablissement_m = COALESCE(distance_etablissement_m, v_distance_m),
      perimetre_gps_valide = COALESCE(perimetre_gps_valide, v_perimetre_ok)
    WHERE id = v_presence.id;
  END IF;

  -- Incrémenter compteur QR
  UPDATE public.qr_codes_mission SET
    nb_scans = nb_scans + 1, dernier_scan_le = v_now
  WHERE id = v_qr.id;

  RETURN jsonb_build_object(
    'success', true,
    'methode_detectee', v_type_detecte,
    'mission_id', v_mission.id,
    'distance_m', v_distance_m,
    'perimetre_valide', v_perimetre_ok,
    'horodatage', v_now
  );
END;
$$;


ALTER FUNCTION "public"."fn_valider_scan_qr"("p_token" "text", "p_lat" numeric, "p_lng" numeric, "p_precision" numeric, "p_terminal_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_valider_transition_statut_mission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_transitions_valides text[][];
    v_valide boolean := false;
    v_pair text[];
BEGIN
    IF NEW.statut IS NOT DISTINCT FROM OLD.statut THEN
        RETURN NEW;
    END IF;

    v_transitions_valides := ARRAY[
        ARRAY['OUVERTE', 'ASSIGNEE'],
        ARRAY['OUVERTE', 'ANNULEE_PAR_ETABLISSEMENT'],
        ARRAY['OUVERTE', 'EXPIREE'],
        ARRAY['ASSIGNEE', 'EN_COURS'],
        ARRAY['ASSIGNEE', 'OUVERTE'],
        ARRAY['ASSIGNEE', 'ANNULEE_PAR_ETABLISSEMENT'],
        ARRAY['ASSIGNEE', 'ANNULEE_PAR_SOIGNANT'],
        ARRAY['ASSIGNEE', 'ABSENCE'],
        ARRAY['ASSIGNEE', 'EXPIREE'],
        ARRAY['EN_COURS', 'TERMINEE'],
        ARRAY['EN_COURS', 'ABSENCE'],
        ARRAY['EN_COURS', 'LITIGE'],
        ARRAY['EN_COURS', 'ANNULEE_PAR_ETABLISSEMENT'],
        ARRAY['LITIGE', 'TERMINEE'],
        ARRAY['LITIGE', 'ANNULEE_PAR_ETABLISSEMENT']
    ];

    FOREACH v_pair SLICE 1 IN ARRAY v_transitions_valides LOOP
        IF OLD.statut::text = v_pair[1] AND NEW.statut::text = v_pair[2] THEN
            v_valide := true;
            EXIT;
        END IF;
    END LOOP;

    IF NOT v_valide AND NOT est_admin() THEN
        RAISE EXCEPTION 'Transition de statut invalide : % → %', OLD.statut, NEW.statut;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_valider_transition_statut_mission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_api_key"("p_cle_api" "text", "p_cle_secret" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE
  v_key public.api_keys%ROWTYPE;
  v_valid boolean := false;
BEGIN
  IF p_cle_api IS NULL OR p_cle_secret IS NULL OR length(p_cle_secret) > 256 THEN
    RETURN jsonb_build_object('valid', false);
  END IF;
  SELECT * INTO v_key
  FROM public.api_keys
  WHERE cle_api = p_cle_api
    AND actif = true
    AND (expire_le IS NULL OR expire_le > now())
  LIMIT 1;
  IF NOT FOUND OR v_key.etablissement_id IS NULL OR v_key.cle_secret_hash IS NULL THEN
    RETURN jsonb_build_object('valid', false);
  END IF;

  IF v_key.cle_secret_hash ~ '^[0-9a-fA-F]{64}$' THEN
    v_valid := lower(v_key.cle_secret_hash) = public._sha256_hex(p_cle_secret);
  ELSIF v_key.cle_secret_hash LIKE '$2%' THEN
    v_valid := v_key.cle_secret_hash = extensions.crypt(p_cle_secret, v_key.cle_secret_hash);
  END IF;
  IF NOT v_valid THEN RETURN jsonb_build_object('valid', false); END IF;

  UPDATE public.api_keys SET derniere_utilisation = now() WHERE id = v_key.id;
  RETURN jsonb_build_object(
    'valid', true,
    'id', v_key.id,
    'etablissement_id', v_key.etablissement_id,
    'groupe_sante_id', v_key.groupe_sante_id,
    'permissions', v_key.permissions
  );
END;
$_$;


ALTER FUNCTION "public"."fn_verifier_api_key"("p_cle_api" "text", "p_cle_secret" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_coherence_documents"("p_soignant_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_service_role boolean := COALESCE(
    auth.jwt()->>'role',
    current_setting('request.jwt.claim.role', true),
    ''
  ) = 'service_role';
  v_soignant_id uuid := COALESCE(p_soignant_id, v_uid);
  v_soignant record;
  v_docs jsonb;
  v_docs_sans_nom integer;
  v_noms_extraits text[];
  v_coherent boolean := true;
  v_problemes text[] := ARRAY[]::text[];
BEGIN
  IF NOT v_is_service_role
     AND (
       v_uid IS NULL
       OR public.fn_compte_auth_actif() IS NOT TRUE
     ) THEN
    RAISE EXCEPTION 'Accès refusé'
      USING ERRCODE = '42501';
  END IF;

  IF v_soignant_id IS DISTINCT FROM v_uid AND NOT v_is_service_role THEN
    IF NOT public.est_admin_valide() THEN
      RAISE EXCEPTION 'Accès refusé'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT prenom, nom
    INTO v_soignant
    FROM public.soignants
   WHERE id = v_soignant_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Soignant introuvable');
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
    'type', d.type_document,
    'nom_extrait', d.nom_extrait_ia,
    'prenom_extrait', d.prenom_extrait_ia,
    'coherence_nom', d.coherence_nom,
    'score_confiance', d.score_confiance_ia,
    'statut', d.statut_verification
  ))
    INTO v_docs
    FROM public.documents_soignants d
   WHERE d.soignant_id = v_soignant_id
     AND d.supprime_le IS NULL
     AND d.statut_verification IN ('VERIFIE', 'EN_ATTENTE');

  IF v_docs IS NULL OR jsonb_array_length(v_docs) = 0 THEN
    RETURN jsonb_build_object(
      'coherent', true,
      'message', 'Pas assez de documents vérifiés',
      'documents', '[]'::jsonb
    );
  END IF;

  SELECT count(*)
    INTO v_docs_sans_nom
    FROM jsonb_array_elements(v_docs) elem
   WHERE elem->>'nom_extrait' IS NULL
      OR trim(elem->>'nom_extrait') = '';

  IF v_docs_sans_nom > 0 THEN
    v_problemes := array_append(
      v_problemes,
      format(
        '%s document(s) sans nom lisible — cohérence non vérifiable sur ces pièces',
        v_docs_sans_nom
      )
    );
  END IF;

  SELECT array_agg(DISTINCT upper(trim(elem->>'nom_extrait')))
    INTO v_noms_extraits
    FROM jsonb_array_elements(v_docs) elem
   WHERE elem->>'nom_extrait' IS NOT NULL
     AND trim(elem->>'nom_extrait') <> '';

  IF array_length(v_noms_extraits, 1) > 1 THEN
    v_coherent := false;
    v_problemes := array_append(
      v_problemes,
      'Noms différents détectés entre documents : '
        || array_to_string(v_noms_extraits, ', ')
    );
  END IF;

  IF v_noms_extraits IS NOT NULL AND array_length(v_noms_extraits, 1) > 0 THEN
    DECLARE
      v_profil_nom text := upper(trim(v_soignant.nom));
      v_match boolean := false;
    BEGIN
      FOR i IN 1..array_length(v_noms_extraits, 1) LOOP
        IF v_noms_extraits[i] LIKE '%' || v_profil_nom || '%'
           OR v_profil_nom LIKE '%' || v_noms_extraits[i] || '%' THEN
          v_match := true;
        END IF;
      END LOOP;

      IF NOT v_match THEN
        v_coherent := false;
        v_problemes := array_append(
          v_problemes,
          'Nom du profil (' || v_soignant.nom || ') ne correspond pas aux documents'
        );
      END IF;
    END;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(v_docs) elem
     WHERE (elem->>'coherence_nom')::boolean = false
  ) THEN
    v_coherent := false;
    v_problemes := array_append(
      v_problemes,
      'Un ou plusieurs documents ont un nom incohérent avec le profil'
    );
  END IF;

  -- Revue admin best-effort : l'alerte ne doit jamais rendre la vérification
  -- documentaire indisponible.
  IF NOT v_coherent THEN
    BEGIN
      INSERT INTO public.journaux_audit (
        acteur_id, type_acteur, action, type_ressource, id_ressource, details
      ) VALUES (
        v_soignant_id,
        'SYSTEM',
        'COHERENCE_DOCUMENTS_ALERTE',
        'soignant',
        v_soignant_id,
        jsonb_build_object(
          'problemes', to_jsonb(v_problemes),
          'profil_nom', v_soignant.nom,
          'profil_prenom', v_soignant.prenom
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'coherent', v_coherent,
    'problemes', to_jsonb(v_problemes),
    'documents', v_docs,
    'profil_nom', v_soignant.nom,
    'profil_prenom', v_soignant.prenom,
    'docs_sans_nom_lisible', v_docs_sans_nom
  );
END;
$$;


ALTER FUNCTION "public"."fn_verifier_coherence_documents"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_coherence_identite"("p_soignant_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_soignant public.soignants%ROWTYPE;
  v_doc_identite public.documents_soignants%ROWTYPE;
  v_date_document date;
  v_date_brute text;
  v_doc_found boolean := false;
  v_nom_ok boolean := false;
  v_date_ok boolean := false;
  v_all_ok boolean := false;
  v_details jsonb;
  v_previous_system_update text := COALESCE(current_setting('jolene.system_update', true), '');
BEGIN
  SELECT * INTO v_soignant FROM public.soignants WHERE id = p_soignant_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'Soignant introuvable'); END IF;

  SELECT * INTO v_doc_identite
  FROM public.documents_soignants
  WHERE soignant_id = p_soignant_id
    AND type_document IN ('CARTE_IDENTITE', 'PASSEPORT', 'TITRE_SEJOUR')
    AND statut_verification = 'VERIFIE'
    AND supprime_le IS NULL
  ORDER BY COALESCE(verifie_le, televerse_le) DESC, televerse_le DESC
  LIMIT 1;
  v_doc_found := FOUND;

  IF v_doc_found THEN
    v_nom_ok := public.fn_noms_personne_correspondent(
      v_soignant.nom,
      v_soignant.prenom,
      v_doc_identite.nom_extrait_ia,
      v_doc_identite.prenom_extrait_ia
    );
    v_date_brute := v_doc_identite.resultat_ia->>'date_naissance_extraite';
    IF v_date_brute ~ '^\d{4}-\d{2}-\d{2}$' THEN
      BEGIN
        v_date_document := v_date_brute::date;
        IF to_char(v_date_document, 'YYYY-MM-DD') IS DISTINCT FROM v_date_brute THEN
          v_date_document := NULL;
        END IF;
      EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
        v_date_document := NULL;
      END;
    END IF;
    v_date_ok := v_soignant.date_naissance IS NOT NULL
      AND v_date_document IS NOT NULL
      AND v_soignant.date_naissance = v_date_document;
  END IF;

  v_all_ok := v_doc_found AND v_nom_ok AND v_date_ok;
  v_details := jsonb_build_object(
    'type_document', CASE WHEN v_doc_identite.id IS NULL THEN NULL ELSE v_doc_identite.type_document::text END,
    'document_id', v_doc_identite.id,
    'nom_prenom_correspondent', v_nom_ok,
    'date_naissance_correspond', v_date_ok,
    'verifie_le', now()
  );

  PERFORM set_config('jolene.system_update', 'true', true);
  UPDATE public.soignants
  SET coherence_identite = CASE
        WHEN v_doc_identite.id IS NULL THEN 'NON_VERIFIE'
        WHEN v_all_ok THEN 'COHERENT'
        ELSE 'INCOHERENT'
      END,
      coherence_details = v_details,
      identite_verifiee = v_all_ok,
      modifie_le = now()
  WHERE id = p_soignant_id;
  PERFORM set_config('jolene.system_update', v_previous_system_update, true);

  IF NOT v_all_ok AND v_doc_identite.id IS NOT NULL THEN
    INSERT INTO public.file_revue_manuelle (
      type_entite, id_entite, service_en_echec, motif_echec,
      donnees_originales, statut, priorite
    ) VALUES (
      'SOIGNANT', p_soignant_id, 'COHERENCE_IDENTITE',
      'La pièce d''identité ne correspond pas exactement au nom, au prénom et à la date de naissance du profil.',
      v_details, 'EN_ATTENTE', 4
    ) ON CONFLICT DO NOTHING;
  END IF;
  RETURN jsonb_build_object('coherent', v_all_ok, 'details', v_details);
END;
$_$;


ALTER FUNCTION "public"."fn_verifier_coherence_identite"("p_soignant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_coherence_publication"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Si quelqu'un tente de mettre peut_publier = TRUE sans être VERIFIE
    IF NEW.peut_publier_missions = TRUE AND NEW.statut_verification != 'VERIFIE' THEN
        -- Service role / admin peut forcer
        IF COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role' 
           OR auth.uid() IS NULL OR est_admin() THEN
            RETURN NEW; -- Admin override autorisé
        END IF;
        RAISE EXCEPTION 'Impossible de publier sans être vérifié';
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_verifier_coherence_publication"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_documents_expirants"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_doc record;
  v_sid uuid;
BEGIN
  FOR v_doc IN
    SELECT d.id, d.soignant_id, d.type_document, d.valide_jusqua, s.prenom, s.email
    FROM public.documents_soignants d
    JOIN public.soignants s ON s.id = d.soignant_id
    WHERE d.valide_jusqua IS NOT NULL
      AND d.valide_jusqua BETWEEN current_date AND current_date + 30
      AND d.supprime_le IS NULL
      AND d.statut_verification = 'VERIFIE'
      AND d.rappel_j30_envoye IS FALSE
  LOOP
    UPDATE public.documents_soignants SET rappel_j30_envoye = true WHERE id = v_doc.id;
    INSERT INTO public.notifications (
      destinataire_id, type, titre, corps, lien, type_destinataire
    ) VALUES (
      v_doc.soignant_id, 'DOCUMENT_EXPIRANT', 'Document bientôt expiré ⚠️',
      'Votre ' || v_doc.type_document || ' expire le ' || v_doc.valide_jusqua,
      '/soignant/documents', 'SOIGNANT'
    );
    v_count := v_count + 1;
  END LOOP;

  FOR v_doc IN
    SELECT d.id, d.soignant_id, d.type_document, d.valide_jusqua
    FROM public.documents_soignants d
    WHERE d.valide_jusqua IS NOT NULL
      AND d.valide_jusqua BETWEEN current_date AND current_date + 7
      AND d.supprime_le IS NULL
      AND d.rappel_j7_envoye IS FALSE
  LOOP
    UPDATE public.documents_soignants SET rappel_j7_envoye = true WHERE id = v_doc.id;
    INSERT INTO public.notifications (
      destinataire_id, type, titre, corps, lien, type_destinataire
    ) VALUES (
      v_doc.soignant_id, 'DOCUMENT_EXPIRANT', '⚠️ Document expire dans 7 jours',
      'Votre ' || v_doc.type_document || ' expire le ' || v_doc.valide_jusqua || '. Renouvelez-le maintenant.',
      '/soignant/documents', 'SOIGNANT'
    );
    v_count := v_count + 1;
  END LOOP;

  FOR v_sid IN
    SELECT DISTINCT d.soignant_id
    FROM public.documents_soignants d
    JOIN public.soignants s ON s.id = d.soignant_id
    JOIN public.documents_requis_par_profession r
      ON r.profession = s.profession
     AND public.fn_type_document_preuve_compatible(r.type_document, d.type_document)
    WHERE d.valide_jusqua < current_date
      AND d.supprime_le IS NULL
      AND r.est_critique IS TRUE
  LOOP
    PERFORM public.fn_calculer_tous_documents_valides(v_sid);
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."fn_verifier_documents_expirants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_otp_telephone"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_otp public.otps_telephone%ROWTYPE;
  v_cible_type text;
  v_cible_id uuid;
  v_etablissement_id uuid;
BEGIN
  IF v_uid IS NULL OR public.fn_compte_auth_actif() IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'NON_AUTHENTIFIE');
  END IF;
  IF p_code IS NULL OR p_code !~ '^[0-9]{6}$' THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CODE_INVALIDE');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('otp-phone:' || v_uid::text, 0));
  PERFORM public.fn_purger_codes_otp_expires();

  SELECT * INTO v_otp
  FROM public.otps_telephone
  WHERE user_id = v_uid
    AND utilise IS FALSE
    AND expire_le > now()
  ORDER BY cree_le DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'OTP_INEXISTANT_OU_EXPIRE'
    );
  END IF;
  IF v_otp.tentatives >= 5 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'TROP_TENTATIVES',
      'error', 'Trop de tentatives. Demandez un nouveau code.'
    );
  END IF;

  UPDATE public.otps_telephone
  SET tentatives = tentatives + 1
  WHERE id = v_otp.id;

  IF extensions.crypt(p_code, v_otp.code_hash) <> v_otp.code_hash THEN
    RETURN jsonb_build_object(
      'success', false,
      'error_code', 'CODE_INCORRECT',
      'tentatives_restantes', greatest(0, 5 - (v_otp.tentatives + 1))
    );
  END IF;

  v_cible_type := v_otp.cible_type;
  v_cible_id := v_otp.cible_id;
  -- Compatibilité des OTP historiques créés avant l'ajout de la cible figée.
  IF v_cible_type IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM public.soignants
      WHERE id = v_uid AND supprime_le IS NULL
    ) THEN
      v_cible_type := 'SOIGNANT';
      v_cible_id := v_uid;
    ELSE
      v_etablissement_id := public.mon_etablissement_id();
      IF v_etablissement_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error_code', 'PROFIL_INTROUVABLE');
      END IF;
      v_cible_type := 'ETABLISSEMENT';
      v_cible_id := v_etablissement_id;
    END IF;
  END IF;

  IF v_cible_type = 'SOIGNANT' THEN
    IF v_cible_id IS DISTINCT FROM v_uid THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'CIBLE_INVALIDE');
    END IF;
    UPDATE public.soignants
    SET telephone = v_otp.telephone,
        telephone_verifie = true,
        telephone_verifie_le = now(),
        telephone_en_attente_verification = NULL,
        modifie_le = now()
    WHERE id = v_cible_id AND supprime_le IS NULL;
  ELSIF v_cible_type = 'ETABLISSEMENT' THEN
    IF public.mon_etablissement_id() IS DISTINCT FROM v_cible_id
       OR NOT public.fn_a_permission_etablissement('profil_etab', v_cible_id) THEN
      RETURN jsonb_build_object('success', false, 'error_code', 'CIBLE_INVALIDE');
    END IF;
    UPDATE public.etablissements
    SET telephone_contact = v_otp.telephone,
        telephone_verifie = true,
        telephone_verifie_le = now(),
        telephone_en_attente_verification = NULL,
        modifie_le = now()
    WHERE id = v_cible_id AND supprime_le IS NULL;
  ELSE
    RETURN jsonb_build_object('success', false, 'error_code', 'CIBLE_INVALIDE');
  END IF;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error_code', 'CIBLE_INTROUVABLE');
  END IF;

  UPDATE public.otps_telephone
  SET utilise = true
  WHERE id = v_otp.id;

  -- Le SMS a nécessairement été reçu pour que le code puisse être fourni. On
  -- expurge néanmoins explicitement toute action encore présente ou retraitée.
  UPDATE public.externalisation_actions
  SET payload = jsonb_set(
        payload #- '{data,code}',
        '{data,code_purge}',
        'true'::jsonb,
        true
      )
  WHERE type_action = 'SMS_NOTIF'
    AND source = 'AUTRE'
    AND source_id = v_otp.id;

  PERFORM public.fn_ecrire_audit_safe(
    p_acteur_id := v_uid,
    p_type_acteur := v_cible_type,
    p_action := 'SYSTEM',
    p_type_ressource := 'otp_telephone',
    p_id_ressource := v_otp.id,
    p_details := jsonb_build_object(
      'evenement', 'OTP_TELEPHONE_VERIFIE',
      'telephone_last4', right(regexp_replace(v_otp.telephone, '[^0-9]', '', 'g'), 4),
      'cible_type', v_cible_type,
      'cible_id', v_cible_id
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'telephone_last4', right(regexp_replace(v_otp.telephone, '[^0-9]', '', 'g'), 4),
    'cible_type', v_cible_type
  );
END;
$_$;


ALTER FUNCTION "public"."fn_verifier_otp_telephone"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_pointages_incoherents"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_presence record;
  v_mission record;
  v_incidents jsonb;
  v_incident jsonb;
  v_severite_max text;
  v_count_verifiees integer := 0;
  v_count_alertes integer := 0;
BEGIN
  -- Vérifie les presences :
  --  - pas encore vérifiées (coherence_verifiee_le IS NULL)
  --  - dont la mission est terminée depuis au moins 1h (ou pointage arrivée >2h sans départ)
  FOR v_presence IN
    SELECT p.*
    FROM public.presences p
    JOIN public.missions m ON m.id = p.mission_id
    WHERE p.coherence_verifiee_le IS NULL
      AND (
        (p.pointage_depart_le IS NOT NULL AND m.fin_le < now() - INTERVAL '1 hour')
        OR (p.pointage_arrivee_le IS NOT NULL AND p.pointage_depart_le IS NULL AND m.fin_le < now() - INTERVAL '6 hours')
      )
    LIMIT 500
  LOOP
    SELECT * INTO v_mission FROM public.missions WHERE id = v_presence.mission_id;
    CONTINUE WHEN v_mission IS NULL;

    v_incidents := public.fn_evaluer_coherence_pointage(
      v_presence.pointage_arrivee_le,
      v_presence.pointage_depart_le,
      v_mission.debut_le,
      v_mission.fin_le,
      v_presence.duree_nette_min
    );

    -- Cas spécial : arrivée sans départ après fin mission + 6h
    IF v_presence.pointage_arrivee_le IS NOT NULL
       AND v_presence.pointage_depart_le IS NULL
       AND v_mission.fin_le < now() - INTERVAL '6 hours' THEN
      v_incidents := v_incidents || jsonb_build_object(
        'code', 'DEPART_MANQUANT',
        'severite', 'CRITICAL',
        'message', 'Arrivée pointée mais aucun départ enregistré'
      );
    END IF;

    -- Calcule sévérité max
    v_severite_max := NULL;
    FOR v_incident IN SELECT * FROM jsonb_array_elements(v_incidents)
    LOOP
      IF v_incident->>'severite' = 'CRITICAL' THEN
        v_severite_max := 'CRITICAL';
        EXIT;
      ELSIF v_incident->>'severite' = 'WARNING' AND v_severite_max IS NULL THEN
        v_severite_max := 'WARNING';
      END IF;
    END LOOP;

    -- Marque la presence comme vérifiée
    UPDATE public.presences
    SET coherence_verifiee_le = now(),
        coherence_incidents = v_incidents
    WHERE id = v_presence.id;
    v_count_verifiees := v_count_verifiees + 1;

    -- Crée une alerte_systeme si incident détecté
    IF jsonb_array_length(v_incidents) > 0 THEN
      INSERT INTO public.alertes_systeme (
        type_alerte, severite, source, message, details
      ) VALUES (
        'POINTAGE_INCOHERENT',
        COALESCE(v_severite_max, 'WARNING'),
        'cron:jolene_verifier_pointages_incoherents',
        format('Incident pointage mission %s (soignant %s)', v_mission.id, v_presence.soignant_id),
        jsonb_build_object(
          'mission_id', v_mission.id,
          'presence_id', v_presence.id,
          'soignant_id', v_presence.soignant_id,
          'etablissement_id', v_mission.etablissement_id,
          'mission_debut', v_mission.debut_le,
          'mission_fin', v_mission.fin_le,
          'pointage_arrivee', v_presence.pointage_arrivee_le,
          'pointage_depart', v_presence.pointage_depart_le,
          'duree_nette_min', v_presence.duree_nette_min,
          'incidents', v_incidents
        )
      );
      v_count_alertes := v_count_alertes + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'verifiees', v_count_verifiees,
    'alertes', v_count_alertes,
    'horodatage', now()
  );
END;
$$;


ALTER FUNCTION "public"."fn_verifier_pointages_incoherents"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_pre_facturation"("p_mission_id" "uuid", "p_periode_debut" "date" DEFAULT NULL::"date", "p_periode_fin" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_mission RECORD;
  v_nb_effectif_ouvert integer;
  v_nb_effectif_ferme integer;
  v_nb_previsionnel integer;
  v_duree_previsionnelle numeric;
  v_duree_effective numeric;
  v_ecart_heures numeric;
  v_ecart_pourcent numeric;
  v_source text;
  v_periode_active boolean;
BEGIN
  SELECT id, duree_heures, duree_heures_effective, statut, debut_le, fin_le
  INTO v_mission
  FROM missions WHERE id = p_mission_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Mission % introuvable.', p_mission_id
      USING ERRCODE = 'no_data_found';
  END IF;

  v_periode_active := (p_periode_debut IS NOT NULL AND p_periode_fin IS NOT NULL);

  SELECT
    COUNT(*) FILTER (WHERE type_creneau='EFFECTIF' AND fin IS NULL),
    COUNT(*) FILTER (WHERE type_creneau='EFFECTIF' AND fin IS NOT NULL),
    COUNT(*) FILTER (WHERE type_creneau='PREVISIONNEL')
  INTO v_nb_effectif_ouvert, v_nb_effectif_ferme, v_nb_previsionnel
  FROM mission_creneaux
  WHERE mission_id = p_mission_id
    AND (
      NOT v_periode_active
      OR (debut::date <= p_periode_fin AND COALESCE(fin::date, debut::date) >= p_periode_debut)
    );

  IF v_nb_effectif_ouvert > 0 THEN
    RAISE EXCEPTION 'Facturation bloquée : % créneau(x) effectif(s) ouvert(s) sur la période. Utilisez fn_declarer_fin_retroactive.',
      v_nb_effectif_ouvert USING ERRCODE = 'check_violation';
  END IF;

  SELECT
    COALESCE(ROUND(SUM(EXTRACT(EPOCH FROM (fin - debut)) / 3600.0)
             FILTER (WHERE type_creneau='PREVISIONNEL' AND NOT est_pause)::numeric, 2), 0),
    COALESCE(ROUND(SUM(EXTRACT(EPOCH FROM (fin - debut)) / 3600.0)
             FILTER (WHERE type_creneau='EFFECTIF' AND fin IS NOT NULL AND NOT est_pause)::numeric, 2), 0)
  INTO v_duree_previsionnelle, v_duree_effective
  FROM mission_creneaux
  WHERE mission_id = p_mission_id
    AND (
      NOT v_periode_active
      OR (debut::date <= p_periode_fin AND COALESCE(fin::date, debut::date) >= p_periode_debut)
    );

  v_ecart_heures := ROUND(ABS(v_duree_previsionnelle - v_duree_effective), 2);
  IF v_duree_previsionnelle > 0 THEN
    v_ecart_pourcent := ROUND(v_ecart_heures / v_duree_previsionnelle * 100, 2);
  ELSE
    v_ecart_pourcent := 0;
  END IF;

  IF v_duree_previsionnelle > 0 AND v_duree_effective > v_duree_previsionnelle * 1.10 THEN
    RAISE EXCEPTION 'Facturation bloquée : effectif %h dépasse prévisionnel %h de plus de 10 pct (écart % pct). Validation étab/admin requise.',
      v_duree_effective, v_duree_previsionnelle, v_ecart_pourcent
      USING ERRCODE = 'check_violation';
  END IF;

  IF v_duree_effective = 0 AND v_duree_previsionnelle = 0 THEN
    RAISE EXCEPTION 'Facturation bloquée : aucun créneau (effectif ni prévisionnel) sur la période. Mission probablement absente — passer en statut ABSENCE ou décaler la période.'
      USING ERRCODE = 'check_violation';
  END IF;

  v_source := CASE
    WHEN v_duree_effective > 0 AND v_duree_effective >= v_duree_previsionnelle THEN 'EFFECTIF'
    WHEN v_duree_effective = 0 AND v_duree_previsionnelle > 0 THEN 'PREVISIONNEL_PLANCHER'
    ELSE 'PREVISIONNEL'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'mode_periode', v_periode_active,
    'periode_debut', p_periode_debut,
    'periode_fin', p_periode_fin,
    'source_facturation', v_source,
    'duree_previsionnelle', v_duree_previsionnelle,
    'duree_effective', v_duree_effective,
    'duree_facturee', GREATEST(v_duree_previsionnelle, v_duree_effective),
    'ecart_heures', v_ecart_heures,
    'ecart_pourcent', v_ecart_pourcent,
    'nb_creneaux_effectif_fermes', v_nb_effectif_ferme,
    'nb_creneaux_previsionnels', v_nb_previsionnel
  );
END;
$$;


ALTER FUNCTION "public"."fn_verifier_pre_facturation"("p_mission_id" "uuid", "p_periode_debut" "date", "p_periode_fin" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fn_verifier_pre_facturation"("p_mission_id" "uuid", "p_periode_debut" "date", "p_periode_fin" "date") IS 'Garde-fou pré-facturation. Si p_periode_* NULL → vérifie mission entière (FINALE_UNIQUE). Sinon → vérifie sur période [p_periode_debut, p_periode_fin]. Block si créneau effectif ouvert / écart > 10 pct / aucun créneau. Retourne source EFFECTIF / PREVISIONNEL_PLANCHER (cas absence) / PREVISIONNEL.';



CREATE OR REPLACE FUNCTION "public"."fn_verifier_rate_limit"("p_cle" "text", "p_action" "text", "p_max_tentatives" integer DEFAULT 10, "p_fenetre_secondes" integer DEFAULT 60) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_fenetre_debut timestamptz;
  v_id uuid;
  v_total integer;
  v_premiere timestamptz;
BEGIN
  IF p_cle IS NULL OR length(p_cle) < 1 OR length(p_cle) > 256
     OR p_action IS NULL OR p_action !~ '^[a-zA-Z0-9_:-]{1,100}$'
     OR p_max_tentatives < 1 OR p_max_tentatives > 100000
     OR p_fenetre_secondes < 1 OR p_fenetre_secondes > 31536000 THEN
    RETURN false;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_action || ':' || p_cle, 0));
  v_fenetre_debut := now() - make_interval(secs => p_fenetre_secondes);

  DELETE FROM public.rate_limits
  WHERE cle = p_cle AND action = p_action
    AND premiere_tentative < v_fenetre_debut;

  SELECT
    (array_agg(id ORDER BY premiere_tentative, id))[1],
    COALESCE(sum(tentatives), 0)::integer,
    min(premiere_tentative)
  INTO v_id, v_total, v_premiere
  FROM public.rate_limits
  WHERE cle = p_cle AND action = p_action
    AND premiere_tentative >= v_fenetre_debut;

  IF v_id IS NULL THEN
    INSERT INTO public.rate_limits(cle, action, tentatives, premiere_tentative, derniere_tentative)
    VALUES (p_cle, p_action, 1, now(), now());
    RETURN true;
  END IF;

  -- Consolide aussi d'eventuels doublons crees avant ce correctif.
  DELETE FROM public.rate_limits
  WHERE cle = p_cle AND action = p_action AND id <> v_id;

  IF v_total >= p_max_tentatives THEN
    UPDATE public.rate_limits
    SET tentatives = v_total, premiere_tentative = v_premiere,
        derniere_tentative = now()
    WHERE id = v_id;
    RETURN false;
  END IF;

  UPDATE public.rate_limits
  SET tentatives = v_total + 1, premiere_tentative = v_premiere,
      derniere_tentative = now()
  WHERE id = v_id;
  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."fn_verifier_rate_limit"("p_cle" "text", "p_action" "text", "p_max_tentatives" integer, "p_fenetre_secondes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verifier_skip_serie_onboarding"("p_envoi_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_envoi RECORD;
  v_etab RECORD;
  v_soignant RECORD;
  v_count integer;
  v_j1_skipped boolean;
BEGIN
  SELECT * INTO v_envoi FROM serie_email_envois WHERE id = p_envoi_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('skip', true, 'raison', 'ENVOI_INTROUVABLE');
  END IF;

  -- ════════ SOIGNANT ════════
  IF v_envoi.serie = 'SOIGNANT_ONBOARDING' THEN
    SELECT prenom, nom, profession,
           rpps_verifie, mandat_facturation_signe,
           tous_documents_valides, type_exercice
    INTO v_soignant FROM soignants WHERE id = v_envoi.utilisateur_id;

    IF v_envoi.etape = 'J0' THEN RETURN jsonb_build_object('skip', false); END IF;

    IF v_envoi.etape = 'J1' THEN
      -- Skip si profil "complet" (RPPS vérifié + documents valides + mandat
      -- signé pour libéraux)
      IF v_soignant.tous_documents_valides = true
         AND COALESCE(v_soignant.rpps_verifie, true) = true
         AND (v_soignant.type_exercice = 'SALARIE'
              OR v_soignant.mandat_facturation_signe = true) THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'PROFIL_DEJA_COMPLET');
      END IF;
      RETURN jsonb_build_object('skip', false);
    END IF;

    IF v_envoi.etape = 'J3' THEN
      -- Skip si déjà candidaté
      SELECT count(*) INTO v_count FROM candidatures WHERE soignant_id = v_envoi.utilisateur_id;
      IF v_count > 0 THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'CANDIDATURE_DEJA_EFFECTUEE');
      END IF;
      -- Skip si J1 a été SKIPPED avec raison PROFIL_DEJA_COMPLET → c'est OK
      -- mais surtout skip si J1 SKIPPED pour profil incomplet (= on a pas
      -- réussi à le faire compléter, on insiste pas davantage)
      SELECT EXISTS(
        SELECT 1 FROM serie_email_envois
        WHERE utilisateur_id = v_envoi.utilisateur_id
          AND serie = 'SOIGNANT_ONBOARDING' AND etape = 'J1'
          AND statut = 'SKIPPED'
          AND skip_raison = 'NOTIFICATION_DESACTIVEE'
      ) INTO v_j1_skipped;
      IF v_j1_skipped THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'NOTIFICATIONS_DESACTIVEES_J1');
      END IF;
      RETURN jsonb_build_object('skip', false);
    END IF;

    IF v_envoi.etape = 'J7' THEN
      -- Skip si mission déjà assignée/en cours/terminée
      SELECT count(*) INTO v_count FROM missions
      WHERE soignant_assigne_id = v_envoi.utilisateur_id
        AND statut IN ('ASSIGNEE','EN_COURS','TERMINEE');
      IF v_count > 0 THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'MISSION_DEJA_ASSIGNEE');
      END IF;
      RETURN jsonb_build_object('skip', false);
    END IF;
  END IF;

  -- ════════ ÉTABLISSEMENT ════════
  IF v_envoi.serie = 'ETAB_ONBOARDING' THEN
    SELECT nom, type, contrat_service_signe, rib_s3_key
    INTO v_etab FROM etablissements WHERE id = v_envoi.utilisateur_id;

    IF v_envoi.etape = 'J0' THEN RETURN jsonb_build_object('skip', false); END IF;

    IF v_envoi.etape = 'J1' THEN
      -- Skip si onboarding complet (contrat signé ET RIB uploadé non-legacy)
      IF v_etab.contrat_service_signe = true
         AND v_etab.rib_s3_key IS NOT NULL
         AND v_etab.rib_s3_key <> 'legacy/auto-backfill' THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'ONBOARDING_DEJA_COMPLET');
      END IF;
      RETURN jsonb_build_object('skip', false);
    END IF;

    IF v_envoi.etape = 'J3' THEN
      SELECT count(*) INTO v_count FROM missions WHERE etablissement_id = v_envoi.utilisateur_id;
      IF v_count > 0 THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'MISSION_DEJA_PUBLIEE');
      END IF;
      RETURN jsonb_build_object('skip', false);
    END IF;

    IF v_envoi.etape = 'J7' THEN
      -- Skip si l'étab a reçu au moins 1 candidature
      SELECT count(*) INTO v_count FROM candidatures c
      JOIN missions m ON m.id = c.mission_id
      WHERE m.etablissement_id = v_envoi.utilisateur_id;
      IF v_count > 0 THEN
        RETURN jsonb_build_object('skip', true, 'raison', 'CANDIDATURE_DEJA_RECUE');
      END IF;
      RETURN jsonb_build_object('skip', false);
    END IF;
  END IF;

  RETURN jsonb_build_object('skip', false);
END;
$$;


ALTER FUNCTION "public"."fn_verifier_skip_serie_onboarding"("p_envoi_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verrouiller_reference_justificatif"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_path text;
BEGIN
  IF auth.role() = 'service_role' OR public.est_admin() THEN
    RETURN NEW;
  END IF;

  v_path := CASE TG_TABLE_NAME
    WHEN 'missions'
      THEN pg_catalog.to_jsonb(NEW)->>'justificatif_honoraires_cle'
    ELSE pg_catalog.to_jsonb(NEW)->>'justificatif_storage_path'
  END;

  IF v_path IS NOT NULL
     AND NOT public.fn_peut_deposer_justificatif(v_path) THEN
    RAISE EXCEPTION 'Référence de justificatif non autorisée'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_verrouiller_reference_justificatif"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_verrouiller_transition_liberale"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_preuve_ancienne_valide boolean;
  v_preuve_nouvelle_valide boolean;
BEGIN
  -- session_user conserve le rôle appelant ; current_user vaudrait toujours
  -- le propriétaire de cette fonction SECURITY DEFINER.
  IF session_user IN ('postgres', 'supabase_admin')
     OR COALESCE(current_setting('request.jwt.claim.role', true), '') = 'service_role'
     OR auth.role() = 'service_role'
     OR public.est_admin() THEN
    RETURN NEW;
  END IF;

  IF COALESCE(current_setting('jolene.liberal_transition', true), '') = 'true' THEN
    RETURN NEW;
  END IF;

  IF NEW.siret_liberal IS NOT DISTINCT FROM OLD.siret_liberal
     AND NEW.statut_liberal IS NOT DISTINCT FROM OLD.statut_liberal
     AND NOT (
       NEW.type_contrat IS DISTINCT FROM OLD.type_contrat
       AND (NEW.type_contrat::text = 'LIBERAL' OR OLD.type_contrat::text = 'LIBERAL')
     )
     AND NOT (
       NEW.type_exercice IS DISTINCT FROM OLD.type_exercice
       AND NEW.type_exercice IN ('LIBERAL', 'MIXTE')
     ) THEN
    RETURN NEW;
  END IF;

  IF auth.uid() IS NULL OR OLD.id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Transition libérale non autorisée' USING ERRCODE = '42501';
  END IF;

  IF NEW.siret_liberal IS DISTINCT FROM OLD.siret_liberal
     OR NEW.statut_liberal IS DISTINCT FROM OLD.statut_liberal
     OR (
       NEW.type_contrat IS DISTINCT FROM OLD.type_contrat
       AND (NEW.type_contrat::text = 'LIBERAL' OR OLD.type_contrat::text = 'LIBERAL')
     ) THEN
    RAISE EXCEPTION 'Utilisez le parcours vérifié pour modifier le statut ou le SIRET libéral'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.type_exercice IS DISTINCT FROM OLD.type_exercice
     AND NEW.type_exercice IN ('LIBERAL', 'MIXTE') THEN
    v_preuve_ancienne_valide :=
      OLD.statut_liberal = 'ACTIF'
      AND OLD.siret_liberal ~ '^[0-9]{14}$'
      AND OLD.siret_liberal_verifie IS TRUE
      AND OLD.siret_liberal_verifie_le IS NOT NULL
      AND OLD.siret_liberal_coherence_identite IS TRUE;
    v_preuve_nouvelle_valide :=
      NEW.statut_liberal = 'ACTIF'
      AND NEW.siret_liberal ~ '^[0-9]{14}$'
      AND NEW.siret_liberal_verifie IS TRUE
      AND NEW.siret_liberal_verifie_le IS NOT NULL
      AND NEW.siret_liberal_coherence_identite IS TRUE;

    IF NOT v_preuve_ancienne_valide OR NOT v_preuve_nouvelle_valide THEN
      RAISE EXCEPTION 'Activation libérale réservée au parcours SIRET et identité vérifiés'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."fn_verrouiller_transition_liberale"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_versionner_verifications_etablissement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- On ignore toujours une valeur proposée par le client. Le compteur avance
  -- aussi pour un UPDATE sans delta : c'est volontairement conservateur.
  NEW.verification_source_version := OLD.verification_source_version + 1;
  RETURN NEW;
END;
$$;


