CREATE OR REPLACE FUNCTION "public"."peut_exercer"("p_profession" "text", "p_type_exercice" "text", "p_type_etablissement" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_type_exercice IN ('SALARIE', 'CDD', 'CDD', 'VACATION') THEN
    RETURN TRUE;
  END IF;

  IF p_type_exercice IN ('LIBERAL', 'MIXTE') THEN
    RETURN public.peut_exercer_liberal(p_profession, p_type_etablissement);
  END IF;

  RETURN TRUE;
END;
$$;


