CREATE OR REPLACE FUNCTION "public"."tg_candidature_acceptee_creer_conversation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE
  v_etab_id uuid;
BEGIN
  SELECT m.etablissement_id INTO v_etab_id
  FROM public.missions m
  WHERE m.id = NEW.mission_id;
  IF v_etab_id IS NULL THEN RETURN NEW; END IF;

  BEGIN
    PERFORM public.fn_creer_conversation_si_absente(
      NEW.mission_id,
      NEW.soignant_id,
      v_etab_id
    );
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      INSERT INTO public.journaux_audit (
        acteur_id,
        type_acteur,
        action,
        type_ressource,
        id_ressource,
        details
      ) VALUES (
        '00000000-0000-0000-0000-000000000000'::uuid,
        'SYSTEME',
        'SYSTEM',
        'candidatures',
        NEW.id,
        pg_catalog.jsonb_build_object(
          'evenement', 'MESSAGERIE_TRIGGER_ECHEC',
          'sql_state', SQLSTATE,
          'sql_errm', SQLERRM,
          'mission_id', NEW.mission_id,
          'soignant_id', NEW.soignant_id
        )
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END;

  RETURN NEW;
END;
$$;


