  IF NEW.pointage_arrivee_le IS NOT NULL
     AND (TG_OP = 'INSERT' OR OLD.pointage_arrivee_le IS NULL) THEN
    PERFORM public.fn_exiger_conformite_demarrage_mission(
      NEW.mission_id,
      NEW.soignant_id
    );
  END IF;
  RETURN NEW;
END;
$$;


