CREATE OR REPLACE FUNCTION "public"."trg_fn_maj_tresorerie_bloquee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.fn_recalculer_tresorerie_bloquee(NEW.litige_id);
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.litige_id IS DISTINCT FROM OLD.litige_id THEN
      PERFORM public.fn_recalculer_tresorerie_bloquee(OLD.litige_id);
    END IF;
    PERFORM public.fn_recalculer_tresorerie_bloquee(NEW.litige_id);
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trg_fn_maj_tresorerie_bloquee"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."trg_fn_maj_tresorerie_bloquee"() IS 'CP-LITIGES-7a FIX 1 — trigger function : appelle fn_recalculer_tresorerie_bloquee pour OLD.litige_id (si FK change) et NEW.litige_id.';



CREATE OR REPLACE FUNCTION "public"."trg_verrouiller_attestation_temps_travail"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  -- Une correction administrative de l'attribution doit serialiser les
  -- controles des deux soignants. L'ordre UUID stable evite un interblocage
  -- lorsque deux attestations sont permutees concurremment.
  IF TG_OP = 'UPDATE'
     AND OLD.soignant_id IS DISTINCT FROM NEW.soignant_id THEN
    IF OLD.soignant_id IS NULL THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('jolene:attribution:' || NEW.soignant_id::text, 0)
      );
    ELSIF NEW.soignant_id IS NULL THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('jolene:attribution:' || OLD.soignant_id::text, 0)
      );
    ELSIF OLD.soignant_id::text < NEW.soignant_id::text THEN
      PERFORM pg_advisory_xact_lock(
        hashtextextended('jolene:attribution:' || OLD.soignant_id::text, 0)
      );
      PERFORM pg_advisory_xact_lock(
        hashtextextended('jolene:attribution:' || NEW.soignant_id::text, 0)
      );
    ELSE
      PERFORM pg_advisory_xact_lock(
        hashtextextended('jolene:attribution:' || NEW.soignant_id::text, 0)
      );
      PERFORM pg_advisory_xact_lock(
        hashtextextended('jolene:attribution:' || OLD.soignant_id::text, 0)
      );
    END IF;
  ELSIF NEW.soignant_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('jolene:attribution:' || NEW.soignant_id::text, 0)
    );
  END IF;
  NEW.modifie_le := clock_timestamp();
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_verrouiller_attestation_temps_travail"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_verrouiller_controles_temps_travail"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.soignant_assigne_id IS NOT NULL
     AND NEW.statut IN ('ASSIGNEE', 'EN_COURS', 'TERMINEE') THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('jolene:attribution:' || NEW.soignant_assigne_id::text, 0)
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_verrouiller_controles_temps_travail"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_verrouiller_etat_initial_mission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_role text := COALESCE(auth.role(), '');
  v_operation_interne text := COALESCE(
    current_setting('app.internal_operation', true), ''
  );
  v_raison_seed text := COALESCE(
    current_setting('jolene.admin_seed_override_reason', true), ''
  );
BEGIN
  -- Migrations/maintenance SQL sans identité applicative.
  IF session_user IN ('postgres', 'supabase_admin')
     AND auth.uid() IS NULL
     AND v_role NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  -- Seeds E2E explicites : jamais accessible à un JWT utilisateur.
  IF v_role = 'service_role'
     AND (v_operation_interne = 'true' OR NULLIF(btrim(v_raison_seed), '') IS NOT NULL) THEN
    RETURN NEW;
  END IF;

  IF NEW.statut IS DISTINCT FROM 'OUVERTE'
     OR NEW.soignant_assigne_id IS NOT NULL THEN
    RAISE EXCEPTION 'Une mission doit être créée OUVERTE et sans soignant affecté.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_verrouiller_etat_initial_mission"() OWNER TO "postgres";


