    "siret_liberal_preuve_identite_valide_jusqua" "date",
    "siret_liberal_preuve_identite_empreinte_sha256" "text",
    CONSTRAINT "chk_rayon_raisonnable" CHECK ((("rayon_deplacement_km" >= 1) AND ("rayon_deplacement_km" <= 200))),
    CONSTRAINT "chk_telephone_format" CHECK ((("telephone" IS NULL) OR (("telephone")::"text" ~ '^\+?[0-9\s\-\.]{8,20}$'::"text"))),
    CONSTRAINT "soignants_coherence_identite_check" CHECK (("coherence_identite" = ANY (ARRAY['NON_VERIFIE'::"text", 'COHERENT'::"text", 'INCOHERENT'::"text", 'EN_ATTENTE_REVUE'::"text"]))),
    CONSTRAINT "soignants_iban_provenance_coherente_check" CHECK ((("iban_titulaire_coherent" IS FALSE) OR (("iban_source_document_id" IS NOT NULL) AND ("iban_identite_document_id" IS NOT NULL) AND (NULLIF("iban_source_s3_cle", ''::"text") IS NOT NULL) AND ("iban_empreinte_sha256" ~ '^[0-9a-f]{64}$'::"text") AND ("iban_verifie_le" IS NOT NULL)))),
    CONSTRAINT "soignants_numero_securite_sociale_format" CHECK ((("numero_securite_sociale" IS NULL) OR ("numero_securite_sociale" ~ '^[0-9]{13,15}$'::"text"))),
    CONSTRAINT "soignants_preference_contrat_mixte_check" CHECK (("preference_contrat_mixte" = ANY (ARRAY['SALARIE'::"text", 'LIBERAL'::"text"]))),
    CONSTRAINT "soignants_regime_fiscal_check" CHECK (("regime_fiscal" = ANY (ARRAY['MICRO_BNC'::"text", 'DECLARATION_CONTROLEE'::"text"]))),
    CONSTRAINT "soignants_score_fiabilite_check" CHECK ((("score_fiabilite" >= (0)::numeric) AND ("score_fiabilite" <= (100)::numeric))),
    CONSTRAINT "soignants_sexe_check" CHECK ((("sexe" IS NULL) OR ("sexe" = ANY (ARRAY['M'::"text", 'F'::"text"])))),
    CONSTRAINT "soignants_siret_liberal_preuve_manuelle_complete_check" CHECK ((("siret_liberal_source_verification" IS DISTINCT FROM 'REVUE_MANUELLE_IDENTITE'::"text") OR (("siret_liberal_preuve_siret" IS NOT NULL) AND (("siret_liberal_preuve_siret")::"text" ~ '^[0-9]{14}$'::"text") AND ("siret_liberal_preuve_identite_document_id" IS NOT NULL) AND ("siret_liberal_preuve_identite_document_modifie_le" IS NOT NULL) AND (NOT ("siret_liberal_preuve_identite_s3_bucket" IS DISTINCT FROM 'jolene-documents'::"text")) AND (NULLIF("siret_liberal_preuve_identite_s3_cle", ''::"text") IS NOT NULL) AND ("siret_liberal_preuve_identite_storage_object_id" IS NOT NULL) AND ("siret_liberal_preuve_identite_storage_updated_at" IS NOT NULL) AND ("siret_liberal_preuve_identite_valide_jusqua" IS NOT NULL) AND ("siret_liberal_preuve_identite_empreinte_sha256" IS NOT NULL) AND ("siret_liberal_preuve_identite_empreinte_sha256" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "soignants_siret_liberal_source_verification_check" CHECK ((("siret_liberal_source_verification" IS NULL) OR ("siret_liberal_source_verification" = ANY (ARRAY['REGISTRE_OFFICIEL'::"text", 'REVUE_MANUELLE_IDENTITE'::"text"])))),
    CONSTRAINT "soignants_specialite_source_check" CHECK ((("specialite_source" IS NULL) OR ("specialite_source" = ANY (ARRAY['RPPS'::"text", 'MANUEL'::"text"])))),
    CONSTRAINT "soignants_statut_liberal_check" CHECK (("statut_liberal" = ANY (ARRAY['NON_LIBERAL'::"text", 'EN_COURS'::"text", 'ACTIF'::"text"]))),
    CONSTRAINT "soignants_type_exercice_check" CHECK (("type_exercice" = ANY (ARRAY['SALARIE'::"text", 'LIBERAL'::"text", 'MIXTE'::"text"]))),
    CONSTRAINT "soignants_validation_3200h_statut_check" CHECK (("validation_3200h_statut" = ANY (ARRAY['NON_DEMANDE'::"text", 'EN_ATTENTE'::"text", 'VALIDEE'::"text", 'REFUSEE'::"text"])))
);

ALTER TABLE ONLY "public"."soignants" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."soignants" OWNER TO "postgres";


COMMENT ON COLUMN "public"."soignants"."types_contrat_acceptes" IS 'JSON array de types de contrat acceptés par le soignant, ex: ["CDDU","LIBERAL"]. NULL = utilise type_contrat seul.';



COMMENT ON COLUMN "public"."soignants"."numero_securite_sociale" IS 'NIR (Numéro INSEE de Sécurité Sociale). Mention obligatoire bulletin de paie art. R3243-1 CTW. 13 chiffres ou 15 (avec clé).';



COMMENT ON COLUMN "public"."soignants"."defacto_opt_in" IS 'Si true, à chaque facture EMISE le soignant est automatiquement cédé à Defacto pour paiement J+2 (frais affichés à l''inscription). Modifiable à tout moment dans le profil.';



COMMENT ON COLUMN "public"."soignants"."sms_alertes_actives" IS 'Opt-in granulaire pour les SMS d''alerte (mission urgente, rappel J-1). Différent de sms_actif (consentement initial à recevoir des SMS). Les 2 flags sont vérifiés en cumulatif côté edge function send-sms.';



COMMENT ON COLUMN "public"."soignants"."sexe" IS 'M ou F. Requis pour DPAE (URSSAF). Renseigné par le soignant dans son profil.';



COMMENT ON COLUMN "public"."soignants"."lieu_naissance_commune" IS 'Commune de naissance (nom). Requis DPAE pour la France.';



COMMENT ON COLUMN "public"."soignants"."lieu_naissance_departement" IS 'Numéro département de naissance (01..95, 2A, 2B, 971..976). Requis DPAE.';



COMMENT ON COLUMN "public"."soignants"."pays_naissance" IS 'Pays de naissance. Default France. Si autre, le département est NULL.';



COMMENT ON COLUMN "public"."soignants"."nationalite" IS 'Nationalité du soignant. Default Française.';



COMMENT ON COLUMN "public"."soignants"."iban_virement" IS 'IBAN complet (format FR76XXXX...) saisi par le soignant pour recevoir les primes de parrainage par virement SWAN SCT. Jamais pré-rempli, jamais partagé avec l''établissement.';



COMMENT ON COLUMN "public"."soignants"."iban_titulaire" IS 'Nom du titulaire du compte bancaire (doit correspondre à l''identité du soignant).';



COMMENT ON COLUMN "public"."soignants"."est_compte_test" IS 'Compte e2e Playwright ou compte d''audit interne — exclu des surfaces publiques et de la découverte.';



COMMENT ON COLUMN "public"."soignants"."siret_liberal_verifie" IS 'Vrai uniquement après contrôle du registre officiel et concordance avec l identité du soignant.';



COMMENT ON COLUMN "public"."soignants"."iban_source_document_id" IS 'RIB actif et vérifié ayant prouvé exactement l IBAN de virement courant.';



COMMENT ON COLUMN "public"."soignants"."iban_titulaire_coherent" IS 'Concordance déterministe entre titulaire du compte, RIB et identité actuelle du soignant.';



COMMENT ON COLUMN "public"."soignants"."iban_empreinte_sha256" IS 'Empreinte SHA-256 de l IBAN normalisé salée par l UUID de la version RIB ; jamais l IBAN dans l audit ou le résultat IA.';



COMMENT ON COLUMN "public"."soignants"."siret_liberal_source_verification" IS 'Source du verdict SIRET courant : registre officiel ou revue manuelle fondee sur une piece d identite.';



COMMENT ON COLUMN "public"."soignants"."siret_liberal_preuve_identite_document_id" IS 'Document exact ayant fonde une approbation manuelle du titulaire du SIRET liberal.';



