CREATE TABLE IF NOT EXISTS "public"."factures" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "etablissement_id" "uuid" NOT NULL,
    "numero_facture" "text" NOT NULL,
    "periode_debut" "date",
    "periode_fin" "date",
    "montant_ht" numeric(10,2) NOT NULL,
    "taux_tva" numeric(5,2) DEFAULT 20.00,
    "montant_tva" numeric(10,2) NOT NULL,
    "montant_ttc" numeric(10,2) NOT NULL,
    "nombre_missions" integer DEFAULT 0,
    "stripe_invoice_id" "text",
    "stripe_payment_intent_id" "text",
    "stripe_hosted_url" "text",
    "statut" "text" DEFAULT 'BROUILLON'::"text",
    "date_emission" timestamp with time zone,
    "date_echeance" "date",
    "date_paiement" timestamp with time zone,
    "cree_le" timestamp with time zone DEFAULT "now"(),
    "modifie_le" timestamp with time zone DEFAULT "now"(),
    "chorus_pro_id" "text",
    "chorus_pro_statut" "text" DEFAULT 'NON_APPLICABLE'::"text",
    "chorus_pro_deposee_le" timestamp with time zone,
    "est_secteur_public" boolean DEFAULT false,
    "mode_paiement" "text" DEFAULT 'STRIPE'::"text",
    "virement_confirme_par" "uuid",
    "virement_confirme_le" timestamp with time zone,
    "virement_reference" "text",
    "chorus_pro_numero_flux" "text",
    "chorus_pro_date_depot" timestamp with time zone,
    "chorus_pro_date_acceptation" timestamp with time zone,
    "mission_id" "uuid",
    "type_document" "text" DEFAULT 'FACTURE'::"text" NOT NULL,
    "facture_precedente_id" "uuid",
    "montant_signe" numeric(12,2) GENERATED ALWAYS AS (
CASE
    WHEN ("type_document" = 'AVOIR'::"text") THEN (- "montant_ht")
    ELSE "montant_ht"
END) STORED,
    "relance_1_le" timestamp with time zone,
    "relance_2_le" timestamp with time zone,
    "bloque_le" timestamp with time zone,
    "facture_honoraire_id" "uuid",
    CONSTRAINT "factures_chorus_pro_statut_check" CHECK (("chorus_pro_statut" = ANY (ARRAY['NON_APPLICABLE'::"text", 'A_DEPOSER'::"text", 'DEPOSEE'::"text", 'RECUE'::"text", 'MANDATEE'::"text", 'PAYEE'::"text", 'REJETEE'::"text"]))),
    CONSTRAINT "factures_mode_paiement_check" CHECK (("mode_paiement" = ANY (ARRAY['STRIPE'::"text", 'VIREMENT'::"text", 'CHORUS_PRO'::"text"]))),
    CONSTRAINT "factures_statut_check" CHECK (("statut" = ANY (ARRAY['BROUILLON'::"text", 'EMISE'::"text", 'VIREMENT_DECLARE'::"text", 'PAYEE'::"text", 'EN_RETARD'::"text", 'ANNULEE'::"text"]))),
    CONSTRAINT "factures_type_document_check" CHECK (("type_document" = ANY (ARRAY['FACTURE'::"text", 'AVOIR'::"text", 'FACTURE_COMPLEMENTAIRE'::"text"])))
);

ALTER TABLE ONLY "public"."factures" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."factures" OWNER TO "postgres";


COMMENT ON COLUMN "public"."factures"."relance_1_le" IS 'CP-C-2 : J+7 post date_emission relance email RAPPEL_PAIEMENT_J7';



COMMENT ON COLUMN "public"."factures"."relance_2_le" IS 'CP-C-2 : J+21 post date_emission relance email PAIEMENT_RETARD_J21';



COMMENT ON COLUMN "public"."factures"."bloque_le" IS 'CP-C-3 : J+45 blocage auto publication etab';



COMMENT ON COLUMN "public"."factures"."facture_honoraire_id" IS 'Facture de commission Jolene correspondant exactement à cette facture d''honoraires (hebdomadaire ou finale).';



CREATE TABLE IF NOT EXISTS "public"."factures_honoraires" (
    "id" "uuid" DEFAULT "extensions"."uuid_generate_v4"() NOT NULL,
    "numero_facture" "text" NOT NULL,
    "soignant_id" "uuid" NOT NULL,
    "etablissement_id" "uuid" NOT NULL,
    "mission_id" "uuid",
    "montant_ht" numeric(10,2) NOT NULL,
    "montant_tva" numeric(10,2) DEFAULT 0 NOT NULL,
    "montant_ttc" numeric(10,2) NOT NULL,
    "taux_tva" numeric(4,2) DEFAULT 0,
    "exoneration_tva" boolean DEFAULT true,
    "date_emission" "date" DEFAULT CURRENT_DATE NOT NULL,
    "date_echeance" "date",
    "date_paiement" "date",
    "statut" "text" DEFAULT 'BROUILLON'::"text" NOT NULL,
    "mandat_version" "text",
    "pdf_s3_key" "text",
    "cree_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "modifie_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "factor_assigned" boolean DEFAULT false NOT NULL,
    "factor_id" "uuid",
    "subrogation_mention" "text",
    "facturx_xml_url" "text",
    "chorus_submission_id" "uuid",
    "chorus_submission_status" "text",
    "chorus_last_sync_at" timestamp with time zone,
    "is_public_sector" boolean DEFAULT false NOT NULL,
    "siret_client" "text",
    "service_code_chorus" "text",
    "engagement_juridique" "text",
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "template_version" "text" DEFAULT 'v1'::"text" NOT NULL,
    "admin_notes" "text",
    "type_document" "public"."type_document_facture" DEFAULT 'FACTURE'::"public"."type_document_facture" NOT NULL,
    "statut_litige" "public"."statut_litige_facture" DEFAULT 'NORMAL'::"public"."statut_litige_facture" NOT NULL,
    "litige_id" "uuid",
    "facture_precedente_id" "uuid",
    "mode_remboursement" "public"."mode_remboursement_avoir" DEFAULT 'N_A'::"public"."mode_remboursement_avoir" NOT NULL,
    "date_remboursement" timestamp with time zone,
    "reference_remboursement" "text",
    "montant_signe" numeric(12,2) GENERATED ALWAYS AS (
CASE
    WHEN ("type_document" = 'AVOIR'::"public"."type_document_facture") THEN (- "montant_ht")
    ELSE "montant_ht"
END) STORED,
    "pdf_a_regenerer" boolean DEFAULT false NOT NULL,
    "stripe_payment_intent_id" "text",
    "chorus_avoir_reference_invoice" "text",
    "periode_debut" "date" NOT NULL,
    "periode_fin" "date" NOT NULL,
    "numero_semaine_iso" smallint,
    "annee_iso" smallint,
    "est_facture_finale_mission" boolean DEFAULT true NOT NULL,
    CONSTRAINT "factures_honoraires_statut_check" CHECK (("statut" = ANY (ARRAY['BROUILLON'::"text", 'EN_GENERATION'::"text", 'EMISE'::"text", 'PAYEE'::"text", 'ANNULEE'::"text", 'FACTORISEE'::"text", 'EN_RETARD'::"text", 'REMPLACEE'::"text", 'ERREUR_GENERATION'::"text", 'REMBOURSE'::"text"])))
);


ALTER TABLE "public"."factures_honoraires" OWNER TO "postgres";


COMMENT ON COLUMN "public"."factures_honoraires"."statut" IS 'CP-LITIGES-7a FIX 6 — statut comptable de la note d''honoraires. BROUILLON (pré-émission), EMISE (envoyée à l''étab), PAYEE, EN_RETARD (échéance dépassée), FACTORISEE (cession affacturage), ANNULEE (invalide, ex. test ou erreur ; exclue du CA), REMPLACEE (remplacée techniquement par une nouvelle facture suite à litige résolu via fn_admin_resoudre_litige ANNULER_REEMETTRE ; exclue du CA pour éviter le double comptage avec la nouvelle).';



COMMENT ON COLUMN "public"."factures_honoraires"."type_document" IS 'FACTURE ou AVOIR.';



COMMENT ON COLUMN "public"."factures_honoraires"."statut_litige" IS 'NORMAL | EN_ATTENTE_LITIGE | LITIGE_RESOLU_AJUSTE | LITIGE_RESOLU_CONFIRME.';



COMMENT ON COLUMN "public"."factures_honoraires"."litige_id" IS 'FK litige ayant déclenché le gel.';



COMMENT ON COLUMN "public"."factures_honoraires"."facture_precedente_id" IS 'Pour AVOIR : FK facture annulée/ajustée.';



COMMENT ON COLUMN "public"."factures_honoraires"."mode_remboursement" IS 'Pour AVOIR : AUTO_STRIPE, VIREMENT_MANUEL, ou N_A.';



COMMENT ON COLUMN "public"."factures_honoraires"."date_remboursement" IS 'Timestamp du remboursement effectif.';



COMMENT ON COLUMN "public"."factures_honoraires"."reference_remboursement" IS 'Référence virement manuel ou stripe_refund_id.';



COMMENT ON COLUMN "public"."factures_honoraires"."montant_signe" IS 'Montant signé (négatif si AVOIR).';



COMMENT ON COLUMN "public"."factures_honoraires"."pdf_a_regenerer" IS 'TRUE si le PDF/XML doit être (re)généré par l''edge function generate-invoice. Remis à FALSE après succès.';



COMMENT ON COLUMN "public"."factures_honoraires"."stripe_payment_intent_id" IS 'PaymentIntent Stripe Connect lié au paiement de la facture. Renseigné par le webhook Stripe (Partie 2). Utilisé pour détecter l''éligibilité au refund auto.';



COMMENT ON COLUMN "public"."factures_honoraires"."chorus_avoir_reference_invoice" IS 'Pour un AVOIR : numero_facture de la facture d''origine (requis par Chorus Pro en métadonnée). Alimenté par generate-invoice au moment de la regénération.';



COMMENT ON COLUMN "public"."factures_honoraires"."periode_debut" IS 'Début de la période facturée (ISO date). FINALE_UNIQUE = mission.debut_le::date. Hebdo = lundi de la semaine ISO.';



COMMENT ON COLUMN "public"."factures_honoraires"."periode_fin" IS 'Fin de la période facturée (ISO date inclusive). Finale = mission.fin_le::date. Hebdo = dimanche.';



COMMENT ON COLUMN "public"."factures_honoraires"."numero_semaine_iso" IS 'Numéro de semaine ISO 8601 (1-53). NULL si facture finale unique.';



COMMENT ON COLUMN "public"."factures_honoraires"."annee_iso" IS 'Année ISO 8601 (différente de l''année calendaire en bord d''année).';



COMMENT ON COLUMN "public"."factures_honoraires"."est_facture_finale_mission" IS 'TRUE si facture finale (FINALE_UNIQUE ou facture finale partielle d''une mission HEBDO_ET_FINALE). FALSE si hebdo intermédiaire.';



