    "stripe_amount_reversed_cents" integer DEFAULT 0 NOT NULL,
    "stripe_reversal_statut" "text" DEFAULT 'AUCUN'::"text" NOT NULL,
    "facture_honoraire_id" "uuid",
    CONSTRAINT "stripe_transfers_amount_reversed_check" CHECK (("stripe_amount_reversed_cents" >= 0)),
    CONSTRAINT "stripe_transfers_dispute_statut_check" CHECK ((("dispute_statut" IS NULL) OR ("dispute_statut" = ANY (ARRAY['OUVERT'::"text", 'CLOS_won'::"text", 'CLOS_lost'::"text", 'CLOS_warning_closed'::"text", 'CLOS_warning_needs_response'::"text", 'CLOS_charge_refunded'::"text"])))),
    CONSTRAINT "stripe_transfers_reversal_statut_check" CHECK (("stripe_reversal_statut" = ANY (ARRAY['AUCUN'::"text", 'PARTIEL'::"text", 'TOTAL'::"text"]))),
    CONSTRAINT "stripe_transfers_statut_check" CHECK (("statut" = ANY (ARRAY['EN_ATTENTE'::"text", 'CHARGE_REUSSI'::"text", 'TRANSFERE'::"text", 'PAYE'::"text", 'ECHOUE'::"text", 'REMBOURSE'::"text", 'ANNULEE'::"text"])))
);


ALTER TABLE "public"."stripe_transfers" OWNER TO "postgres";


COMMENT ON COLUMN "public"."stripe_transfers"."dispute_id" IS 'ID Stripe Dispute lorsque étab conteste le paiement (chargeback). Lié à stripe_charge_id via webhook charge.dispute.created.';



COMMENT ON COLUMN "public"."stripe_transfers"."dispute_statut" IS 'Statut Stripe Dispute : OUVERT (ouverture), CLOS_won/lost/warning_closed/etc. (clôture).';



COMMENT ON COLUMN "public"."stripe_transfers"."reversed_le" IS 'Horodatage webhook transfer.reversed. Le transfer Connect a été annulé côté Stripe (statut passe REMBOURSE).';



COMMENT ON COLUMN "public"."stripe_transfers"."stripe_checkout_session_id" IS 'Checkout Session de la tentative Connect courante. Sert à reprendre une tentative active et à versionner déterministement la suivante après expiration.';



COMMENT ON COLUMN "public"."stripe_transfers"."stripe_amount_reversed_cents" IS 'Montant cumulé exact des TransferReversal Stripe, en centimes.';



COMMENT ON COLUMN "public"."stripe_transfers"."stripe_reversal_statut" IS 'AUCUN, PARTIEL ou TOTAL. REMBOURSE n’est posé que pour TOTAL.';



