CREATE TABLE IF NOT EXISTS "public"."swan_webhook_events" (
    "event_id" "text" NOT NULL,
    "event_type" "text" NOT NULL,
    "resource_id" "text" NOT NULL,
    "project_id" "text" NOT NULL,
    "statut" "text" DEFAULT 'RECU'::"text" NOT NULL,
    "tentatives" integer DEFAULT 0 NOT NULL,
    "recu_le" timestamp with time zone DEFAULT "now"() NOT NULL,
    "traitement_commence_le" timestamp with time zone,
    "traite_le" timestamp with time zone,
    "derniere_erreur" "text",
    "transaction_snapshot" "jsonb",
    CONSTRAINT "swan_webhook_events_event_id_check" CHECK (((("length"("event_id") >= 1) AND ("length"("event_id") <= 200)) AND ("event_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'::"text"))),
    CONSTRAINT "swan_webhook_events_project_id_check" CHECK (((("length"("project_id") >= 1) AND ("length"("project_id") <= 200)) AND ("project_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'::"text"))),
    CONSTRAINT "swan_webhook_events_resource_id_check" CHECK (((("length"("resource_id") >= 1) AND ("length"("resource_id") <= 200)) AND ("resource_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,199}$'::"text"))),
    CONSTRAINT "swan_webhook_events_snapshot_object_check" CHECK ((("transaction_snapshot" IS NULL) OR ("jsonb_typeof"("transaction_snapshot") = 'object'::"text"))),
    CONSTRAINT "swan_webhook_events_statut_check" CHECK (("statut" = ANY (ARRAY['RECU'::"text", 'PROCESSING'::"text", 'TRAITE'::"text", 'IGNORE'::"text", 'ERREUR'::"text"]))),
    CONSTRAINT "swan_webhook_events_tentatives_check" CHECK ((("tentatives" >= 0) AND ("tentatives" <= 1000))),
    CONSTRAINT "swan_webhook_events_type_check" CHECK ((("length"("event_type") >= 1) AND ("length"("event_type") <= 100)))
);

